  forall (a1 a2 b1 b2 c1 c2 : nat) (g1 g2 : R),
    g1 <> 0 -> g2 <> 0 ->
    let N0 := Nat.min (Nat.min a1 a2) (Nat.min (Nat.min b1 b2) (Nat.min c1 c2)) in
    let M_loc := M_loc_3d a1 a2 b1 b2 c1 c2 in
