    rewrite (Cmul_assoc (Cof_real (/ g1)) (psi a1 t *c psi b1 t *c psi c1 t) _).
    rewrite <- (Cmul_assoc (psi a1 t *c psi b1 t *c psi c1 t) (Cof_real (/ g2)) _).
