(* |⟨ψ_3,ψ_15⟩_N| ≤ 5/16（N ≥ 3） *)
Lemma pair_3_15 (N : nat) : (3 <= N)%nat ->
  Cnorm (Csum (fun k => psi 3 k *c Cconj (psi 15 k)) N) <= 5 / 16.
Proof.
