      * lia.
      * lia.
      * lia.
      * rewrite <- (mult_INR 15 63). apply INR_sqrt_le. lia.
      * apply lt_0_INR. lia.
    + replace (INR 15 * INR 63 / (2 * INR (63 - 15) * INR 30)) with (21 / 64) by (compute; field).
      apply Rle_refl.
Qed.

(* |⟨ψ_15,ψ_255⟩_N| ≤ 255/1952（N ≥ 15） *)
Lemma pair_15_255 (N : nat) : (15 <= N)%nat ->
