(* ============================================================
   E5'' 冠军证书：顶层定理（全矩阵相干加权版本）
   e5_bands = [3,7,15,31,63,127,255]（索引 0..6）
   δ 表 = 21 对上三角相干界（6 核内 T8 + 15 新对，双方向定义）
   ============================================================ *)

(* 对角内积 = 1（窗口 M ≥ n 时） *)
Lemma inner_diag_one : forall n M : nat, (n >= 2)%nat -> (n <= M)%nat ->
  Csum (fun k => psi n k *c Cconj (psi n k)) M = Cof_real 1.
Proof.
  intros n M Hn2 HnM.
  assert (Heq : forall k, psi n k *c Cconj (psi n k) = Cof_real (Cnorm_sq (psi n k))).
  { intro k. symmetry. apply Cnorm_sq_Cof_real. }
  rewrite (Csum_ext' _ (fun k => Cof_real (Cnorm_sq (psi n k))) M).
  2: { intros k Hk. apply Heq. }
  destruct M as [|M'].
  - exfalso; lia.
  - rewrite <- (Cof_real_sum (fun k => Cnorm_sq (psi n k)) M').
    f_equal.
    assert (Hsum1 : sum_f_R0 (fun k => Cnorm_sq (psi n k)) (S M') = 1).
    { change (l2_norm_sq (fun k => psi n k) (S M') = 1); apply psi_unit_norm; assumption. }
    assert (HfM0 : Cnorm_sq (psi n (S M')) = 0).
    { rewrite (psi_ge_n_zero n (S M') HnM). apply Cnorm_sq_zero. }
    rewrite (sum_f_R0_S (fun k => Cnorm_sq (psi n k)) M') in Hsum1.
    rewrite HfM0 in Hsum1. lra.
Qed.

(* re z <= Cnorm z（下界用 -re z <= Cnorm z）——自证，不依赖 Local 引理 *)
Lemma re_le_cnorm : forall z : Complex, re z <= Cnorm z.
Proof.
  intros z.
  apply Rle_trans with (Rabs (re z)).
  - apply Rle_abs.
  - unfold Cnorm, Cnorm_sq.
    rewrite <- sqrt_Rsqr_abs.
    apply sqrt_le_1_c.
    + apply Rle_0_sqr.
    + apply Rplus_le_le_0_compat; apply Rle_0_sqr.
    + unfold Rsqr. nra.
Qed.

Lemma neg_re_le_cnorm : forall z : Complex, - re z <= Cnorm z.
Proof.
  intros z.
  apply Rle_trans with (Rabs (re z)).
  - unfold Rabs. destruct (Rcase_abs (re z)); lra.
  - unfold Cnorm, Cnorm_sq.
    rewrite <- sqrt_Rsqr_abs.
    apply sqrt_le_1_c.
    + apply Rle_0_sqr.
    + apply Rplus_le_le_0_compat; apply Rle_0_sqr.
    + unfold Rsqr. nra.
Qed.

(* Cnorm 非负（自证，避免跨库同名冲突） *)
Lemma cnorm_ge0 : forall z : Complex, 0 <= Cnorm z.
Proof. intros z; unfold Cnorm; apply sqrt_pos. Qed.

(* 非对角项上界：re (a *c Cconj b *c z) <= |a| |b| |z| *)
Lemma re_mul_le : forall a b z : Complex,
  re (a *c Cconj b *c z) <= Cnorm a * Cnorm b * Cnorm z.
Proof.
  intros a b z.
  eapply Rle_trans.
  - apply re_le_cnorm.
  - rewrite Cnorm_mult.
    rewrite (Cnorm_mult a (Cconj b)).
    rewrite Cnorm_conj_eq.
    lra.
Qed.

Lemma neg_re_mul_le : forall a b z : Complex,
  - re (a *c Cconj b *c z) <= Cnorm a * Cnorm b * Cnorm z.
Proof.
  intros a b z.
  eapply Rle_trans.
  - apply neg_re_le_cnorm.
  - rewrite Cnorm_mult.
    rewrite (Cnorm_mult a (Cconj b)).
    rewrite Cnorm_conj_eq.
    lra.
Qed.

(* E5'' 七带梯子 *)
Definition e5_bands : list nat := 3%nat :: 7%nat :: 15%nat :: 31%nat :: 63%nat :: 127%nat :: 255%nat :: nil.

(* δ 表（双方向）：对 7 带索引 (i,j)（0..6 → 3,7,15,31,63,127,255） *)
Definition delta_e5 (i j : nat) : R :=
  match i, j with
  | 0,1 | 1,0 => 21/32          (* 3-7 *)
  | 0,2 | 2,0 => 5/16           (* 3-15，T8 *)
  | 0,3 | 3,0 => 31/168         (* 3-31 *)
  | 0,4 | 4,0 => 63/520         (* 3-63，T8 *)
  | 0,5 | 5,0 => 381/4712       (* 3-127 *)
  | 0,6 | 6,0 => 85/1512        (* 3-255，T8 *)
  | 1,2 | 2,1 => 21/32          (* 7-15 *)
  | 1,3 | 3,1 => 217/672        (* 7-31 *)
  | 1,4 | 4,1 => 3/16           (* 7-63 *)
  | 1,5 | 5,1 => 889/6960       (* 7-127 *)
  | 1,6 | 6,1 => 85/992         (* 7-255 *)
  | 2,3 | 3,2 => 155/224        (* 15-31 *)
  | 2,4 | 4,2 => 21/64          (* 15-63，T8 *)
  | 2,5 | 5,2 => 1905/9632      (* 15-127 *)
  | 2,6 | 6,2 => 255/1952       (* 15-255，T8 *)
  | 3,4 | 4,3 => 1953/2816      (* 31-63 *)
  | 3,5 | 5,3 => 3937/11904     (* 31-127 *)
  | 3,6 | 6,3 => 7905/39424     (* 31-255 *)
  | 4,5 | 5,4 => 8001/11392     (* 63-127 *)
  | 4,6 | 6,4 => 85/256         (* 63-255，T8 *)
  | 5,6 | 6,5 => 32385/45824    (* 127-255 *)
  | _, _ => 0%R
  end.

(* 每带值（nth e5_bands） *)
Lemma band_nth : forall i : nat,
  (i < 7)%nat ->
  nth i e5_bands 0%nat = match i with 0%nat => 3%nat | 1%nat => 7%nat | 2%nat => 15%nat
    | 3%nat => 31%nat | 4%nat => 63%nat | 5%nat => 127%nat | _ => 255%nat end.
Proof.
  intros i Hi. destruct i as [|[|[|[|[|[|[|i']]]]]]]; try lia; reflexivity.
Qed.

Lemma band_ge2 : forall i : nat, (i < 7)%nat -> (nth i e5_bands 0%nat >= 2)%nat.
Proof.
  intros i Hi. rewrite (band_nth i Hi).
  destruct i as [|[|[|[|[|[|[|i']]]]]]]; try lia; simpl; lia.
Qed.

Lemma band_le256 : forall i : nat, (i < 7)%nat -> (nth i e5_bands 0%nat <= 256)%nat.
Proof.
  intros i Hi. rewrite (band_nth i Hi).
  destruct i as [|[|[|[|[|[|[|i']]]]]]]; try lia; simpl; lia.
Qed.

(* 相干界：窗口 M=256（≥ 各带）下 Cnorm (⟨ψ_a,ψ_b⟩_M) <= δ *)
Lemma coh_delta_bound : forall i j : nat, (i < 7)%nat -> (j < 7)%nat -> i <> j ->
  Cnorm (Csum (fun k => psi (nth i e5_bands 0%nat) k *c Cconj (psi (nth j e5_bands 0%nat) k)) 256)
  <= delta_e5 i j.
Proof.
  intros i j Hi Hj Hne.
  rewrite (band_nth i Hi), (band_nth j Hj).
  destruct i as [|[|[|[|[|[|[|i']]]]]]]; try lia.
  all: destruct j as [|[|[|[|[|[|[|j']]]]]]]; try lia.
  all: try (exfalso; lia).
  (* 字典序 42 分支：i=0..6，j=0..6，i<>j *)
  - apply pair_3_7; lia.
  - apply pair_3_15; lia.
  - apply pair_3_31; lia.
  - apply pair_3_63; lia.
  - apply pair_3_127; lia.
  - apply pair_3_255; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 7 k) (fun k => psi 3 k) 256); apply pair_3_7; lia.
  - apply pair_7_15; lia.
  - apply pair_7_31; lia.
  - apply pair_7_63; lia.
  - apply pair_7_127; lia.
  - apply pair_7_255; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 15 k) (fun k => psi 3 k) 256); apply pair_3_15; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 15 k) (fun k => psi 7 k) 256); apply pair_7_15; lia.
  - apply pair_15_31; lia.
  - apply pair_15_63; lia.
  - apply pair_15_127; lia.
  - apply pair_15_255; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 31 k) (fun k => psi 3 k) 256); apply pair_3_31; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 31 k) (fun k => psi 7 k) 256); apply pair_7_31; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 31 k) (fun k => psi 15 k) 256); apply pair_15_31; lia.
  - apply pair_31_63; lia.
  - apply pair_31_127; lia.
  - apply pair_31_255; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 63 k) (fun k => psi 3 k) 256); apply pair_3_63; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 63 k) (fun k => psi 7 k) 256); apply pair_7_63; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 63 k) (fun k => psi 15 k) 256); apply pair_15_63; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 63 k) (fun k => psi 31 k) 256); apply pair_31_63; lia.
  - apply pair_63_127; lia.
  - apply pair_63_255; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 127 k) (fun k => psi 3 k) 256); apply pair_3_127; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 127 k) (fun k => psi 7 k) 256); apply pair_7_127; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 127 k) (fun k => psi 15 k) 256); apply pair_15_127; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 127 k) (fun k => psi 31 k) 256); apply pair_31_127; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 127 k) (fun k => psi 63 k) 256); apply pair_63_127; lia.
  - apply pair_127_255; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 255 k) (fun k => psi 3 k) 256); apply pair_3_255; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 255 k) (fun k => psi 7 k) 256); apply pair_7_255; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 255 k) (fun k => psi 15 k) 256); apply pair_15_255; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 255 k) (fun k => psi 31 k) 256); apply pair_31_255; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 255 k) (fun k => psi 63 k) 256); apply pair_63_255; lia.
  - rewrite (ExtendedTheorems.Cnorm_Csum_conj_sym (fun k => psi 255 k) (fun k => psi 127 k) 256); apply pair_127_255; lia.
Qed.

(* 逐项界：i=j 对角精确；i≠j 用 re 上界 *)
Lemma term_bound_upper : forall (c : nat -> Complex) (i j : nat),
  (i < 7)%nat -> (j < 7)%nat ->
  re (c i *c Cconj (c j) *c
      (Csum (fun k => psi (nth i e5_bands 0%nat) k *c Cconj (psi (nth j e5_bands 0%nat) k)) 256))
  <= if eq_nat_dec i j then Cnorm_sq (c i)
     else Cnorm (c i) * Cnorm (c j) * delta_e5 i j.
Proof.
  intros c i j Hi Hj.
  destruct (Nat.eq_dec i j) as [Heq | Hne].
  - subst j.
    rewrite (inner_diag_one (nth i e5_bands 0%nat) 256 (band_ge2 i Hi) (band_le256 i Hi)).
    change (Cof_real 1) with C1.
    rewrite Cmul_1_r.
    assert (Hdiag : c i *c Cconj (c i) = Cof_real (Cnorm_sq (c i))).
    { symmetry. apply Cnorm_sq_Cof_real. }
    rewrite Hdiag.
    simpl. reflexivity.
  - eapply Rle_trans.
    + apply re_le_cnorm.
    + rewrite (Cnorm_mult (c i *c Cconj (c j)) (Csum (fun k => psi (nth i e5_bands 0%nat) k *c Cconj (psi (nth j e5_bands 0%nat) k)) 256)).
      rewrite (Cnorm_mult (c i) (Cconj (c j))).
      rewrite Cnorm_conj_eq.
      apply Rmult_le_compat_l.
      * apply Rmult_le_pos; apply cnorm_ge0.
      * apply coh_delta_bound; assumption.
Qed.

(* 逐项界（下界）：i=j 精确；i≠j 用 -re 上界 *)
Lemma term_bound_lower : forall (c : nat -> Complex) (i j : nat),
  (i < 7)%nat -> (j < 7)%nat ->
  - re (c i *c Cconj (c j) *c
       (Csum (fun k => psi (nth i e5_bands 0%nat) k *c Cconj (psi (nth j e5_bands 0%nat) k)) 256))
  <= if eq_nat_dec i j then - Cnorm_sq (c i)
     else Cnorm (c i) * Cnorm (c j) * delta_e5 i j.
Proof.
  intros c i j Hi Hj.
  destruct (Nat.eq_dec i j) as [Heq | Hne].
  - subst j.
    rewrite (inner_diag_one (nth i e5_bands 0%nat) 256 (band_ge2 i Hi) (band_le256 i Hi)).
    change (Cof_real 1) with C1.
    rewrite Cmul_1_r.
    assert (Hdiag : c i *c Cconj (c i) = Cof_real (Cnorm_sq (c i))).
    { symmetry. apply Cnorm_sq_Cof_real. }
    rewrite Hdiag.
    simpl. reflexivity.
  - eapply Rle_trans.
    + apply neg_re_le_cnorm.
    + rewrite (Cnorm_mult (c i *c Cconj (c j)) (Csum (fun k => psi (nth i e5_bands 0%nat) k *c Cconj (psi (nth j e5_bands 0%nat) k)) 256)).
      rewrite (Cnorm_mult (c i) (Cconj (c j))).
      rewrite Cnorm_conj_eq.
      apply Rmult_le_compat_l.
      * apply Rmult_le_pos; apply cnorm_ge0.
      * apply coh_delta_bound; assumption.
Qed.

(* 相干加权和 coh（双和去对角） *)
Definition coh_e5 (c : nat -> Complex) : R :=
  sum_f_R0 (fun i => sum_f_R0 (fun j =>
    if eq_nat_dec i j then 0%R else Cnorm (c i) * Cnorm (c j) * delta_e5 i j) 6) 6.

(* 负号进出有限和 *)
Lemma sum_opp : forall (f : nat -> R) (n : nat),
  - sum_f_R0 f n = sum_f_R0 (fun i => - f i) n.
Proof.
  intros f n.
  replace (- sum_f_R0 f n) with (-1 * sum_f_R0 f n) by ring.
  rewrite <- (sum_f_R0_scal_l (-1) f n).
  apply sum_f_R0_ext; intros i _. ring.
Qed.

(* E5'' 端到端冠军证书：七带完整输出的平方范数复合界 *)
Theorem champion_e5_composite_certificate (coeffs : list Complex) :
  length coeffs = 7%nat ->
  let c := fun i => nth i coeffs C0 in
  let F := fun k => Csum (fun i => c i *c psi (nth i e5_bands 0%nat) k) 7%nat in
  let S := sum_f_R0 (fun i => Cnorm_sq (c i)) 6%nat in
  ((S - coh_e5 c) <= l2_norm_sq F 255%nat <= (S + coh_e5 c))%R.
Proof.
  intros Hlen c F S.
  unfold S.
  set (inner := fun i j : nat =>
    Csum (fun k => psi (nth i e5_bands 0%nat) k *c Cconj (psi (nth j e5_bands 0%nat) k)) 256%nat).
  assert (Hlen_bands : length e5_bands = 7%nat) by (unfold e5_bands; reflexivity).
  pose proof (l2_expand_double_sum coeffs e5_bands 7%nat 256%nat Hlen Hlen_bands (Nat.lt_0_succ 255%nat)) as Hlex.
  cbv zeta in Hlex.
  fold inner in Hlex.
  change ((S - coh_e5 c) <= l2_norm_sq F (256 - 1)%nat <= (S + coh_e5 c))%R.
  assert (Hrew : l2_norm_sq F (256 - 1)%nat =
      sum_f_R0 (fun i => sum_f_R0 (fun j =>
        re (c i *c Cconj (c j) *c inner i j)) 6%nat) 6%nat).
  { unfold inner, F. exact Hlex. }
  rewrite Hrew.  (* l2_norm_sq F 255 = Σ_{i,j} re (c i *c Cconj (c j) *c inner i j) *)
  (* ---- 上界 ---- *)
  assert (Hup_sum : sum_f_R0 (fun i => sum_f_R0 (fun j =>
        re (c i *c Cconj (c j) *c inner i j)) 6%nat) 6%nat
      <= sum_f_R0 (fun i => sum_f_R0 (fun j =>
           if eq_nat_dec i j then Cnorm_sq (c i)
           else Cnorm (c i) * Cnorm (c j) * delta_e5 i j) 6%nat) 6%nat).
  { apply sum_f_R0_le_compat; intros i Hi.
    apply sum_f_R0_le_compat; intros j Hj.
    unfold inner. apply term_bound_upper; lia. }
  (* ---- 下界 ---- *)
  assert (Hlo_sum : sum_f_R0 (fun i => sum_f_R0 (fun j =>
        - re (c i *c Cconj (c j) *c inner i j)) 6%nat) 6%nat
      <= sum_f_R0 (fun i => sum_f_R0 (fun j =>
           if eq_nat_dec i j then - Cnorm_sq (c i)
           else Cnorm (c i) * Cnorm (c j) * delta_e5 i j) 6%nat) 6%nat).
  { apply sum_f_R0_le_compat; intros i Hi.
    apply sum_f_R0_le_compat; intros j Hj.
    unfold inner. apply term_bound_lower; lia. }
  assert (Hup_eq : sum_f_R0 (fun i => sum_f_R0 (fun j =>
        if eq_nat_dec i j then Cnorm_sq (c i)
        else Cnorm (c i) * Cnorm (c j) * delta_e5 i j) 6%nat) 6%nat
      = sum_f_R0 (fun i => Cnorm_sq (c i)) 6%nat + coh_e5 c).
  { unfold coh_e5. simpl. ring. }
  assert (Hlo_eq : sum_f_R0 (fun i => sum_f_R0 (fun j =>
        if eq_nat_dec i j then - Cnorm_sq (c i)
        else Cnorm (c i) * Cnorm (c j) * delta_e5 i j) 6%nat) 6%nat
      = - sum_f_R0 (fun i => Cnorm_sq (c i)) 6%nat + coh_e5 c).
  { unfold coh_e5. simpl. ring. }
  split.
  - (* 下界：S - coh <= ΣΣ re ⟺ -ΣΣ re <= -S + coh *)
    assert (Hlo_neg : - sum_f_R0 (fun i => sum_f_R0 (fun j =>
          re (c i *c Cconj (c j) *c inner i j)) 6%nat) 6%nat
          <= - S + coh_e5 c).
    { rewrite (sum_opp (fun i => sum_f_R0 (fun j => re (c i *c Cconj (c j) *c inner i j)) 6%nat) 6%nat).
      apply Rle_trans with (sum_f_R0 (fun i => sum_f_R0 (fun j =>
          if eq_nat_dec i j then - Cnorm_sq (c i)
          else Cnorm (c i) * Cnorm (c j) * delta_e5 i j) 6%nat) 6%nat).
      + apply Rle_trans with (sum_f_R0 (fun i => sum_f_R0 (fun j =>
            - re (c i *c Cconj (c j) *c inner i j)) 6%nat) 6%nat).
        * apply sum_f_R0_le_compat; intros i Hi.
          rewrite (sum_opp (fun j => re (c i *c Cconj (c j) *c inner i j)) 6%nat).
          apply Rle_refl.
        * exact Hlo_sum.
      + rewrite Hlo_eq. unfold S. apply Rle_refl. }
    unfold S in Hlo_neg |- *.
    lra.
  - (* 上界：ΣΣ re <= S + coh *)
    apply Rle_trans with (sum_f_R0 (fun i => sum_f_R0 (fun j =>
        if eq_nat_dec i j then Cnorm_sq (c i)
        else Cnorm (c i) * Cnorm (c j) * delta_e5 i j) 6%nat) 6%nat).
    + exact Hup_sum.
    + rewrite Hup_eq. unfold S. apply Rle_refl.
Qed.

End ChampionCertificate.

(* ============================================================
   Module FrameCheck2DNarrow（会话 15：2D 窄轨反射检查器）
   ------------------------------------------------------------
   任务：(b) 2D 窄轨反射检查器 —— 把 1D frame_check_instance 反射模式
   推广到 2D 窄轨定理 tensor_product_unconditional_basis_corrected（K0=C³/4）。
   输入两轴梯子值列表 vals1/vals2 与生长常数 cC，检查
     sorted/ge2/增长/单带退化（n1=1 或 n2=1）/单值支配/曼哈顿≤6，
   判定通过 ⟹ 2D 窄轨无条件基界（M_bound = K0·((1+4K_C)²−1)）。
   关键数学（会话 14）：corrected 的 H_dom forall 版本不可实例化
   （idx1=idx2 时要求 seq1 i = seq2 j）；本模块走 abstract_unconditional_basis
   独立装配（tensor_product_unconditional_basis_pointwise，点态 H_dom 只对 idx1≠idx2）。
   seq_ext：窗口内 nth，窗口外几何闭式 cC^k·(last+1) − 1 ⟹ 严格增长。
   零 classic（axiom 集 = sig_not_dec + sig_forall_dec + fext，与 3D/4D 同款）。
   ============================================================ *)
Module FrameCheck2DNarrow.

Import ExtendedTheorems.
Import InstanceCertificate.
Import UnconditionalBasisLemmas.
Import RuntimeGuards.
Import FrameCheckInstance.
Import ComplexNumbers.
Open Scope R_scope.
(* ---- 严格增长延拓：窗口内 nth；窗口外 cC^k·(last+1) − 1 ---- *)
Definition seq_ext (vals : list nat) (cC : nat) : nat -> nat :=
  fun i => if i <? length vals then nth i vals 0%nat
           else ((cC ^ (i - length vals + 1))%nat *
                 (S (nth (Nat.pred (length vals)) vals 0%nat)) - 1)%nat.

(* 窗口内取值 *)
Lemma seq_ext_window (vals : list nat) (cC i : nat) :
  (i < length vals)%nat -> seq_ext vals cC i = nth i vals 0%nat.
Proof.
  intros Hi. unfold seq_ext.
  destruct (Nat.ltb_spec i (length vals)) as [H | H'].
  - reflexivity.
  - exfalso. lia.
Qed.

(* cC ≥ 2 ⟹ 0 < cC^k（幂正性，归纳） *)
Lemma pow_pos_nat (cC k : nat) : (2 <= cC)%nat -> (0 < cC ^ k)%nat.
Proof.
  intros HC. induction k as [| k' IH].
  - simpl. lia.
  - simpl. apply Nat.mul_pos_pos; [lia | exact IH].
Qed.

(* 窗口外闭式：i >= len ⟹ seq_ext i = cC^(i-len+1)·(last+1) − 1 *)
Lemma seq_ext_tail_closed (vals : list nat) (cC i : nat) :
  (0 < length vals)%nat -> (length vals <= i)%nat ->
  seq_ext vals cC i =
  ((cC ^ (i - length vals + 1))%nat * S (nth (Nat.pred (length vals)) vals 0%nat) - 1)%nat.
Proof.
  intros Hlen Hi. unfold seq_ext.
  destruct (Nat.ltb_spec i (length vals)) as [H | H']; [lia |].
  reflexivity.
Qed.

(* 几何段 R 不等式：i >= len ⟹ INR (seq_ext (S i)) > INR cC * INR (seq_ext i)
   用闭式：seq_ext i = cC^k·(last+1) − 1，seq_ext (S i) = cC^(k+1)·(last+1) − 1 *)
Lemma seq_ext_geom_R (vals : list nat) (cC i : nat) :
  (cC >= 2)%nat -> (0 < length vals)%nat -> all_ge_2 vals = true ->
  (length vals <= i)%nat ->
  (INR (seq_ext vals cC (S i)) > INR cC * INR (seq_ext vals cC i))%R.
Proof.
  intros HC Hlen Hg Hi.
  set (last := nth (Nat.pred (length vals)) vals 0%nat).
  set (k := (i - length vals + 1)%nat).
  assert (Hlast2 : (2 <= last)%nat).
  { unfold last. apply all_ge_2_nth.
    - exact Hg.
    - lia. }
  assert (Hk_pos : (0 < k)%nat).
  { unfold k. lia. }
  (* seq_ext i = cC^k·(last+1) − 1 *)
  assert (Heq_i : seq_ext vals cC i = (cC ^ k * S last - 1)%nat).
  { unfold k, last. rewrite (seq_ext_tail_closed vals cC i Hlen Hi). reflexivity. }
  (* seq_ext (S i) = cC^(S k)·(last+1) − 1 *)
  assert (HleS : (length vals <= S i)%nat) by lia.
  assert (Heq_S : seq_ext vals cC (S i) = (cC ^ S k * S last - 1)%nat).
  { assert (HkS : (S i - length vals + 1)%nat = S k) by (unfold k; lia).
    unfold k, last. rewrite (seq_ext_tail_closed vals cC (S i) Hlen HleS).
    rewrite HkS. reflexivity. }
  rewrite Heq_i, Heq_S.
  (* cC^(S k)·(last+1) − 1 > cC·(cC^k·(last+1) − 1) *)
  assert (HB1 : (1 <= cC ^ k * S last)%nat).
  { assert (Hpos : (0 < cC ^ k)%nat) by (apply pow_pos_nat; exact HC).
    nia. }
  assert (HA1 : (1 <= cC ^ S k * S last)%nat).
  { assert (Hpos : (0 < cC ^ S k)%nat) by (apply pow_pos_nat; exact HC).
    nia. }
  rewrite (minus_INR (cC ^ S k * S last) 1 HA1).
  rewrite (minus_INR (cC ^ k * S last) 1 HB1).
  simpl.
  rewrite (mult_INR (cC * cC ^ k) (S last)).
  rewrite (mult_INR (cC ^ k) (S last)).
  rewrite (mult_INR cC (cC ^ k)).
  assert (HC_R : 1 < INR cC) by (change 1 with (INR 1); apply lt_INR; lia).
  assert (HA_nonneg : 0 <= INR (cC ^ k) * INR (S last)).
  { apply Rmult_le_pos; apply pos_INR. }
  lra.
Qed.

(* 尾部首步 R 不等式：i = len-1 ⟹ INR (seq_ext len) > INR cC * INR last *)
Lemma seq_ext_tail_first_R (vals : list nat) (cC i : nat) :
  (cC >= 2)%nat -> (0 < length vals)%nat -> all_ge_2 vals = true ->
  (i < length vals)%nat -> (length vals <= S i)%nat ->
  (INR (seq_ext vals cC (S i)) > INR cC * INR (seq_ext vals cC i))%R.
Proof.
  intros HC Hlen Hg Hi Hle.
  rewrite (seq_ext_window vals cC i Hi).
  rewrite (seq_ext_tail_closed vals cC (S i) Hlen Hle).
  assert (Hi' : (i = length vals - 1)%nat) by lia.
  rewrite Hi'.
  simpl.
  destruct (length vals) as [| len']; [lia |].
  simpl.
  assert (Hexp : (len' - 0 - len' + 1)%nat = 1%nat) by lia.
  rewrite Hexp.
  simpl.
  assert (Hcm : (cC * 1)%nat = cC) by lia.
  rewrite Hcm.
  (* 不用 set last：simpl 会把它展开成 nth len' vals 0，change 失配；
     直接用显式 nth len' vals 0 形式（会话 14 已 query_goal 验证） *)
  assert (HA1 : (1 <= cC * S (nth len' vals 0%nat))%nat) by nia.
  rewrite (minus_INR (cC * S (nth len' vals 0%nat)) 1 HA1).
  rewrite mult_INR.
  rewrite (S_INR (nth len' vals 0%nat)).
  rewrite INR_1.
  (* RHS 仍为 nth (len' - 0) vals 0：minus 双参匹配，len' 为变量时不归约，
     change 会 Not convertible；replace 用 lia 归一后才能 lra 消原子 *)
  replace (len' - 0)%nat with len' by lia.
  assert (HC_R : 1 < INR cC) by (change 1 with (INR 1); apply lt_INR; lia).
  lra.
Qed.

(* 窗口内相邻增长 ⟹ nth 相邻对 cC 增长 *)
Lemma seq_ext_window_growth_nat (vals : list nat) (cC : nat) :
  (cC >= 1)%nat ->
  check_sparse_growth vals cC = true ->
  forall i, (S i < length vals)%nat -> ((cC * nth i vals 0%nat) < nth (S i) vals 0%nat)%nat.
Proof.
  intros HC Hcg i Hi.
  unfold check_sparse_growth in Hcg.
  pose proof (forallb_adjacent_nth vals (fun a b => ((cC * a) <? b)%nat) Hcg i) as Hnth.
  apply Nat.ltb_lt.
  apply Hnth. lia.
Qed.

(* 窗口内 INR 增长 *)
Lemma seq_ext_window_growth_R (vals : list nat) (cC : nat) :
  (cC >= 1)%nat ->
  check_sparse_growth vals cC = true ->
  forall i, (S i < length vals)%nat ->
  (INR (nth (S i) vals 0%nat) > INR cC * INR (nth i vals 0%nat))%R.
Proof.
  intros HC Hcg i Hi.
  pose proof (seq_ext_window_growth_nat vals cC HC Hcg i Hi) as Hlt.
  apply lt_INR in Hlt.
  rewrite Nat.mul_comm in Hlt.
  rewrite mult_INR in Hlt.
  rewrite Rmult_comm in Hlt.
  exact Hlt.
Qed.

(* seq_ext 全局 INR 增长（Hsparse 前提） *)
Lemma seq_ext_growth_R (vals : list nat) (cC : nat) :
  (cC >= 2)%nat -> (0 < length vals)%nat ->
  check_sparse_growth vals cC = true ->
  all_ge_2 vals = true ->
  forall i, (INR (seq_ext vals cC (S i)) > INR cC * INR (seq_ext vals cC i))%R.
Proof.
  intros HC Hlen Hcg Hg i.
  destruct (lt_dec (S i) (length vals)) as [HSi | HSi_ge].
  - (* 窗口内相邻对 *)
    destruct (lt_dec i (length vals)) as [Hi | Hi_ge]; [| lia].
    rewrite (seq_ext_window vals cC i Hi).
    rewrite (seq_ext_window vals cC (S i) HSi).
    apply seq_ext_window_growth_R; [lia | exact Hcg | exact HSi].
  - (* S i >= len *)
    destruct (lt_dec i (length vals)) as [Hi | Hi_ge].
    + (* i = len-1：尾部首步 *)
      apply seq_ext_tail_first_R; [exact HC | exact Hlen | exact Hg | exact Hi |].
      exact (proj1 (Nat.nlt_ge (S i) (length vals)) HSi_ge).
    + (* i >= len：纯几何段 *)
      apply seq_ext_geom_R; [exact HC | exact Hlen | exact Hg |].
      apply Nat.nlt_ge. exact Hi_ge.
Qed.

(* 窗口内值 ≥2 *)
Lemma seq_ext_window_ge2 (vals : list nat) (i : nat) :
  all_ge_2 vals = true -> (i < length vals)%nat -> (2 <= nth i vals 0%nat)%nat.
Proof.
  intros Hg Hi. apply all_ge_2_nth; assumption.
Qed.

(* 尾部延拓值 ≥2 *)
Lemma seq_ext_tail_ge2 (vals : list nat) (cC i : nat) :
  (cC >= 2)%nat -> (0 < length vals)%nat -> all_ge_2 vals = true ->
  (length vals <= i)%nat -> (2 <= seq_ext vals cC i)%nat.
Proof.
  intros HC Hlen Hg Hi.
  rewrite (seq_ext_tail_closed vals cC i Hlen Hi).
  assert (Hlast2 : (2 <= nth (Nat.pred (length vals)) vals 0%nat)%nat).
  { apply seq_ext_window_ge2.
    - exact Hg.
    - lia. }
  assert (Hpow_ge1 : (1 <= cC ^ (i - length vals + 1))%nat).
  { destruct (i - length vals + 1)%nat as [| k']; [simpl; lia |].
    apply Nat.lt_le_incl.
    apply Nat.pow_gt_1; [lia | lia]. }
  assert (Hpow_pos : (0 < cC ^ (i - length vals + 1))%nat).
  { destruct (cC ^ (i - length vals + 1))%nat as [| k']; [exfalso; lia | lia]. }
  nia.
Qed.

(* ============ 2D 窄轨反射检查器：检查项定义 ============ *)

(* 单带退化判定：n1=1 或 n2=1 *)
Definition single_band (n1 n2 : nat) : bool :=
  (n1 =? 1)%nat || (n2 =? 1)%nat.

(* 单值支配：n1=1 ⟹ vals1[0] ≥ max vals2；n2=1 ⟹ vals2[0] ≥ max vals1 *)
Definition dom_check (vals1 vals2 : list nat) : bool :=
  match (length vals1 =? 1)%nat, (length vals2 =? 1)%nat with
  | true, _ => Nat.leb (fold_right Nat.max 0%nat vals2) (nth 0 vals1 0%nat)
  | _, true => Nat.leb (fold_right Nat.max 0%nat vals1) (nth 0 vals2 0%nat)
  | _, _ => false
  end.

(* 曼哈顿 ≤6：n1+n2 ≤ 8（任意两扁平索引 |i1-i2|+|j1-j2| ≤ (n1-1)+(n2-1) = n1+n2-2 ≤ 6） *)
Definition manhattan_ok (vals1 vals2 : list nat) : bool :=
  Nat.leb (length vals1 + length vals2) 8%nat.

(* 主检查器 *)
Definition frame_check_2d_narrow (cC : nat) (vals1 vals2 : list nat) : bool :=
  andb (sorted_strict_aux vals1) (sorted_strict_aux vals2) &&
  andb (all_ge_2 vals1) (all_ge_2 vals2) &&
  andb (check_sparse_growth vals1 cC) (check_sparse_growth vals2 cC) &&
  andb (single_band (length vals1) (length vals2))
       (andb (dom_check vals1 vals2) (manhattan_ok vals1 vals2)).

(* ---- 检查项 ⟹ 前提的引理 ---- *)

(* single_band 拆解 *)
Lemma single_band_case (n1 n2 : nat) :
  single_band n1 n2 = true ->
  (n1 = 1)%nat \/ (n2 = 1)%nat.
Proof.
  unfold single_band. destruct (Nat.eqb_spec n1 1) as [H1 | H1]; [left; exact H1 |].
  destruct (Nat.eqb_spec n2 1) as [H2 | H2]; [right; exact H2 |].
  intro Habs. discriminate.
Qed.

(* dom_check：n1=1 ⟹ vals1[0] ≥ max vals2 *)
Lemma dom_check_n1_1 (vals1 vals2 : list nat) :
  (length vals1 = 1)%nat ->
  dom_check vals1 vals2 = true ->
  (fold_right Nat.max 0%nat vals2 <= nth 0 vals1 0%nat)%nat.
Proof.
  intros Hn1 Hd.
  unfold dom_check in Hd.
  rewrite Hn1 in Hd.
  simpl in Hd.
  destruct (Nat.eqb_spec (length vals2) 1) as [Hn2 | Hn2]; simpl in Hd.
  - apply Nat.leb_le in Hd. exact Hd.
  - apply Nat.leb_le in Hd. exact Hd.
Qed.

(* dom_check：n2=1 且 n1≠1 ⟹ vals2[0] ≥ max vals1
   （n1=1 ∧ n2=1 时 dom_check 首分支命中，方向相反——该情形下 n1·n2=1 无对，H_dom 真空） *)
Lemma dom_check_n2_1 (vals1 vals2 : list nat) :
  (length vals2 = 1)%nat -> (length vals1 <> 1)%nat ->
  dom_check vals1 vals2 = true ->
  (fold_right Nat.max 0%nat vals1 <= nth 0 vals2 0%nat)%nat.
Proof.
  intros Hn2 Hn1_ne Hd.
  unfold dom_check in Hd.
  destruct (Nat.eqb_spec (length vals1) 1) as [Hn1 | Hn1']; simpl in Hd.
  - exfalso. apply Hn1_ne. exact Hn1.
  - rewrite Hn2 in Hd. simpl in Hd. apply Nat.leb_le in Hd. exact Hd.
Qed.

(* 所有元素 ≤ max（正向） *)
Lemma In_le_fold_max (vals : list nat) (v : nat) :
  In v vals -> (v <= fold_right Nat.max 0%nat vals)%nat.
Proof.
  induction vals as [| h tl IH]; simpl.
  - intro Hv; inversion Hv.
  - intro Hv. destruct Hv as [Heq | Hin].
    + subst. apply Nat.le_max_l.
    + apply (Nat.le_trans _ (fold_right Nat.max 0%nat tl) _);
        [apply IH; exact Hin | apply Nat.le_max_r].
Qed.

(* max 传递：max ≤ x 且 In v ⟹ v ≤ x *)
Lemma fold_max_le_all (vals : list nat) (x v : nat) :
  (fold_right Nat.max 0%nat vals <= x)%nat ->
  In v vals -> (v <= x)%nat.
Proof.
  intros Hle Hin. apply (Nat.le_trans _ (fold_right Nat.max 0%nat vals) _);
    [apply In_le_fold_max; exact Hin | exact Hle].
Qed.

(* 检查项：n1=1 时窗口内任何 vals2 元素 ≤ vals1[0] *)
Lemma dom_n1_1_all_le (vals1 vals2 : list nat) (v : nat) :
  (length vals1 = 1)%nat ->
  dom_check vals1 vals2 = true ->
  In v vals2 -> (v <= nth 0 vals1 0%nat)%nat.
Proof.
  intros Hn1 Hd Hin.
  apply (fold_max_le_all vals2 (nth 0 vals1 0%nat) v).
  - apply dom_check_n1_1; assumption.
  - exact Hin.
Qed.

(* 检查项：n2=1 且 n1≠1 时窗口内任何 vals1 元素 ≤ vals2[0] *)
Lemma dom_n2_1_all_le (vals1 vals2 : list nat) (v : nat) :
  (length vals2 = 1)%nat -> (length vals1 <> 1)%nat ->
  dom_check vals1 vals2 = true ->
  In v vals1 -> (v <= nth 0 vals2 0%nat)%nat.
Proof.
  intros Hn2 Hn1_ne Hd Hin.
  apply (fold_max_le_all vals1 (nth 0 vals2 0%nat) v).
  - apply dom_check_n2_1; assumption.
  - exact Hin.
Qed.

(* ============ H_dom 构造（单带退化） ============ *)
(* H_dom 陈述（corrected 10271-10275）：
   forall idx1 idx2,
     (idx1/n2 = idx2/n2 -> seq1 (idx1/n2) >= max(seq2 (idx1 mod n2))(seq2 (idx2 mod n2))) /\
     (idx1 mod n2 = idx2 mod n2 -> seq2 (idx1 mod n2) >= max(seq1 (idx1/n2))(seq1 (idx2/n2)))
   单带退化 n1=1：i 恒为 0（idx < 1*n2 = n2 ⟹ idx/n2 = 0）。同行（恒成立）⟹
   需要 seq1 0 >= max(seq2 j1)(seq2 j2)，由 dom_check（vals1[0] ≥ max vals2）+ seq_ext_window 给出。
   同列（idx1 mod n2 = idx2 mod n2 = j）：需要 seq2 j >= max(seq1 0)(seq1 0) = seq1 0。
   但这与同行条件（seq1 0 ≥ seq2 j）同时要求 ⟹ 全等。因此 corrected 的 H_dom forall
   版本实际不可实例化（idx1=idx2 时要求 seq1 i = seq2 j）。 *)
(* 结论：2D 窄轨反射检查器不能实例化 corrected 的 H_dom forall，必须走
   abstract_unconditional_basis 独立装配（phi_flat_decay_general 的点态 H_dom 只对 idx1≠idx2）。

   ---- 点态 H_dom 构造（探针新增，会话 15） ----
   输入：single_band n1 n2 = true（n1=1 或 n2=1）+ dom_check（单值支配）
   输出：phi_flat_decay_general 需要的点态 H_dom（forall idx1 idx2, idx1<>idx2 -> ...）
   情形 n1=1：同行分支由 dom_check（vals1[0] ≥ max vals2）+ In_le_fold_max + nth_In 给出；
              同列分支前提 idx1 mod n2 = idx2 mod n2 ⟹ idx1 = idx2（mod_small）⟹ 与 idx1≠idx2 矛盾。
   情形 n2=1（n1≠1）：同列分支由 dom_check_n2_1 给出；同行分支 idx1/1 = idx2/1 ⟹ 矛盾。
   情形 n1=1 ∧ n2=1：n1·n2 = 1，idx1<1 ∧ idx2<1 ⟹ idx1=idx2=0，无对，H_dom 真空。 *)

(* Z 侧辅助：abs_nat 对负数 = 原数（曼哈顿界需要） *)
Lemma Zabs_nat_opp_of_nat (n : nat) : Z.abs_nat (- Z.of_nat n) = n.
Proof.
  rewrite Znat.Zabs2Nat.abs_nat_spec.
  rewrite Z.abs_opp.
  rewrite (Z.abs_eq (Z.of_nat n) (Nat2Z.is_nonneg n)).
  apply Nat2Z.id.
Qed.

(* |a - b| ≤ c−1 当 a,b < c（nat 差的上界） *)
Lemma abs_nat_sub_bounded (a b c : nat) : (a < c)%nat -> (b < c)%nat ->
  (Z.abs_nat (Z.of_nat a - Z.of_nat b) <= c - 1)%nat.
Proof.
  intros Ha Hb.
  destruct (le_lt_dec a b) as [Hab | Hba].
  - assert (Hsub : (Z.of_nat a - Z.of_nat b)%Z = (- Z.of_nat (b - a))%Z).
    { rewrite (Znat.Nat2Z.inj_sub b a Hab). lia. }
    rewrite Hsub.
    rewrite Zabs_nat_opp_of_nat.
    lia.
  - assert (Hsub : (Z.of_nat a - Z.of_nat b)%Z = Z.of_nat (a - b)).
    { rewrite (Znat.Nat2Z.inj_sub a b). lia. apply Nat.lt_le_incl; exact Hba. }
    rewrite Hsub.
    rewrite Znat.Zabs2Nat.id.
    lia.
Qed.

(* 曼哈顿界：n1+n2 ≤ 8 ⟹ |i1−i2| + |j1−j2| ≤ 6（n1,n2 ≥ 1） *)
Lemma index_bound_2d (n1 n2 idx1 idx2 : nat) :
  (n1 > 0)%nat -> (n2 > 0)%nat -> (n1 + n2 <= 8)%nat ->
  (idx1 < n1 * n2)%nat -> (idx2 < n1 * n2)%nat ->
  (Z.abs_nat (Z.of_nat (idx1 / n2) - Z.of_nat (idx2 / n2)) +
   Z.abs_nat (Z.of_nat (idx1 mod n2) - Z.of_nat (idx2 mod n2)) <= 6)%nat.
Proof.
  intros Hn1 Hn2 Hle Hlt1 Hlt2.
  assert (Hi1 : (idx1 / n2 < n1)%nat) by (apply Nat.Div0.div_lt_upper_bound; lia).
  assert (Hi2 : (idx2 / n2 < n1)%nat) by (apply Nat.Div0.div_lt_upper_bound; lia).
  assert (Hj1 : (idx1 mod n2 < n2)%nat) by (apply Nat.mod_upper_bound; lia).
  assert (Hj2 : (idx2 mod n2 < n2)%nat) by (apply Nat.mod_upper_bound; lia).
  assert (Hd1 : (Z.abs_nat (Z.of_nat (idx1 / n2) - Z.of_nat (idx2 / n2)) <= n1 - 1)%nat).
  { apply abs_nat_sub_bounded; auto. }
  assert (Hd2 : (Z.abs_nat (Z.of_nat (idx1 mod n2) - Z.of_nat (idx2 mod n2)) <= n2 - 1)%nat).
  { apply abs_nat_sub_bounded; auto. }
  lia.
Qed.

(* seq start len 严格升序（Sorted Nat.lt），n1/n2 的索引列表用 *)
Lemma sorted_seq (start len : nat) : Sorted Nat.lt (seq start len).
Proof.
  revert start. induction len as [| len' IH]; intros start; simpl.
  - constructor.
  - rewrite cons_seq. constructor.
    + apply IH.
    + destruct len'; simpl; constructor; lia.
Qed.

Lemma sorted_seq_0 (n : nat) : Sorted Nat.lt (seq 0 n).
Proof. apply sorted_seq. Qed.

(* seq_ext 全局 ≥2（窗口内 + 尾部延拓） *)
Lemma seq_ext_ge2 (vals : list nat) (cC : nat) :
  (cC >= 2)%nat -> (0 < length vals)%nat -> all_ge_2 vals = true ->
  forall i, (seq_ext vals cC i >= 2)%nat.
Proof.
  intros HC Hlen Hg i.
  destruct (lt_dec i (length vals)) as [Hi | Hi_ge].
  - rewrite (seq_ext_window vals cC i Hi).
    apply seq_ext_window_ge2; assumption.
  - apply seq_ext_tail_ge2; [exact HC | exact Hlen | exact Hg |].
    apply Nat.nlt_ge. exact Hi_ge.
Qed.

(* 点态 H_dom 构造：single_band + dom_check ⟹ phi_flat_decay_general 的 H_dom *)
Lemma hdom_2d_narrow (vals1 vals2 : list nat) (cC n1 n2 : nat) :
  (n1 = length vals1)%nat -> (n2 = length vals2)%nat ->
  single_band n1 n2 = true -> dom_check vals1 vals2 = true ->
  forall idx1 idx2 : nat, idx1 <> idx2 ->
    (idx1 < n1 * n2)%nat -> (idx2 < n1 * n2)%nat ->
    ((idx1 / n2)%nat = (idx2 / n2)%nat ->
     (seq_ext vals1 cC ((idx1 / n2)%nat) >=
      Nat.max (seq_ext vals2 cC ((idx1 mod n2)%nat)) (seq_ext vals2 cC ((idx2 mod n2)%nat)))%nat) /\
    ((idx1 mod n2)%nat = (idx2 mod n2)%nat ->
     (seq_ext vals2 cC ((idx1 mod n2)%nat) >=
      Nat.max (seq_ext vals1 cC ((idx1 / n2)%nat)) (seq_ext vals1 cC ((idx2 / n2)%nat)))%nat).
Proof.
  intros Hn1 Hn2 Hsb Hdom idx1 idx2 Hneq Hlt1 Hlt2.
  apply single_band_case in Hsb.
  destruct Hsb as [Hn1_1 | Hn2_1].
  - (* n1 = 1：同行由 dom_check；同列矛盾 *)
    subst n1.
    split.
    + (* 同行分支：idx1/n2 = idx2/n2 = 0 *)
      intros _.
      assert (Hlt1' : (idx1 < n2)%nat) by lia.
      assert (Hlt2' : (idx2 < n2)%nat) by lia.
      assert (Hdiv1 : (idx1 / n2)%nat = 0%nat) by (apply Nat.div_small; exact Hlt1').
      assert (Hdiv2 : (idx2 / n2)%nat = 0%nat) by (apply Nat.div_small; exact Hlt2').
      assert (Hmod1 : (idx1 mod n2)%nat = idx1) by (apply Nat.mod_small; exact Hlt1').
      assert (Hmod2 : (idx2 mod n2)%nat = idx2) by (apply Nat.mod_small; exact Hlt2').
      rewrite Hdiv1, Hmod1, Hmod2.
      (* seq_ext vals1 cC 0 = nth 0 vals1 0（窗口内） *)
      assert (Hlen1_pos : (0 < length vals1)%nat) by lia.
      rewrite (seq_ext_window vals1 cC 0 Hlen1_pos).
      (* seq_ext vals2 cC idx1/idx2 = nth idx1/idx2 vals2 0（窗口内） *)
      assert (Hl2a : (idx1 < length vals2)%nat) by lia.
      assert (Hl2b : (idx2 < length vals2)%nat) by lia.
      rewrite (seq_ext_window vals2 cC idx1 Hl2a).
      rewrite (seq_ext_window vals2 cC idx2 Hl2b).
      (* 需要：nth 0 vals1 0 >= max (nth idx1 vals2 0) (nth idx2 vals2 0) *)
      assert (Hdom1 : (fold_right Nat.max 0%nat vals2 <= nth 0 vals1 0%nat)%nat).
      { apply dom_check_n1_1; [lia | exact Hdom]. }
      apply Nat.max_lub_iff. split.
      * eapply Nat.le_trans; [apply In_le_fold_max; apply nth_In; exact Hl2a | exact Hdom1].
      * eapply Nat.le_trans; [apply In_le_fold_max; apply nth_In; exact Hl2b | exact Hdom1].
    + (* 同列分支：idx1 mod n2 = idx2 mod n2 ⟹ idx1 = idx2 ⟹ 矛盾 *)
      intros Hmod_eq.
      assert (Hlt1' : (idx1 < n2)%nat) by lia.
      assert (Hlt2' : (idx2 < n2)%nat) by lia.
      assert (Hmod1 : (idx1 mod n2)%nat = idx1) by (apply Nat.mod_small; exact Hlt1').
      assert (Hmod2 : (idx2 mod n2)%nat = idx2) by (apply Nat.mod_small; exact Hlt2').
      rewrite Hmod1, Hmod2 in Hmod_eq.
      exfalso. apply Hneq. exact Hmod_eq.
  - (* n2 = 1：同行矛盾；同列由 dom_check（需 n1≠1，n1=1 时无对） *)
    assert (Hlt1' : (idx1 < n1)%nat) by (rewrite Hn2_1 in Hlt1; lia).
    assert (Hlt2' : (idx2 < n1)%nat) by (rewrite Hn2_1 in Hlt2; lia).
    assert (Hdiv1 : (idx1 / 1)%nat = idx1) by (apply Nat.div_1_r).
    assert (Hdiv2 : (idx2 / 1)%nat = idx2) by (apply Nat.div_1_r).
    assert (Hmod1 : (idx1 mod 1)%nat = 0%nat) by (apply Nat.mod_1_r).
    assert (Hmod2 : (idx2 mod 1)%nat = 0%nat) by (apply Nat.mod_1_r).
    split.
    + (* 同行分支：idx1/1 = idx2/1 ⟹ idx1 = idx2 ⟹ 矛盾 *)
      intros Hdiv_eq.
      rewrite Hn2_1 in Hdiv_eq.
      rewrite Hdiv1, Hdiv2 in Hdiv_eq.
      exfalso. apply Hneq. exact Hdiv_eq.
    + (* 同列分支：0 = 0，需要 seq_ext vals2 cC 0 >= max (seq_ext vals1 cC idx1) (seq_ext vals1 cC idx2) *)
      intros _.
      destruct (Nat.eqb_spec (length vals1) 1) as [Hlen1_1 | Hlen1_ne].
      * (* n1=1 ∧ n2=1：n1·n2=1，idx1<1 ∧ idx2<1 ⟹ idx1=idx2=0 ⟹ 矛盾 *)
        exfalso. apply Hneq. lia.
      * rewrite Hn2_1.
        rewrite Hdiv1, Hdiv2, Hmod1.
        assert (Hlen2_pos : (0 < length vals2)%nat) by lia.
        rewrite (seq_ext_window vals2 cC 0 Hlen2_pos).
        assert (Hl1a : (idx1 < length vals1)%nat) by lia.
        assert (Hl1b : (idx2 < length vals1)%nat) by lia.
        rewrite (seq_ext_window vals1 cC idx1 Hl1a).
        rewrite (seq_ext_window vals1 cC idx2 Hl1b).
        assert (Hdom2 : (fold_right Nat.max 0%nat vals1 <= nth 0 vals2 0%nat)%nat).
        { apply dom_check_n2_1; [lia | exact Hlen1_ne | exact Hdom]. }
        apply Nat.max_lub_iff. split.
        -- eapply Nat.le_trans; [apply In_le_fold_max; apply nth_In; exact Hl1a | exact Hdom2].
        -- eapply Nat.le_trans; [apply In_le_fold_max; apply nth_In; exact Hl1b | exact Hdom2].
Qed.

(* ============ 点态 H_dom 版 2D 窄轨组装（corrected 的点态变体，会话 15 新增） ============ *)
(* corrected 的 H_dom 是 forall（含 idx1=idx2，不可实例化）；本定理只要求 idx1≠idx2，
   供 frame_check_2d_narrow_sound 直接实例化。其余前提与 corrected 完全相同。 *)
Theorem tensor_product_unconditional_basis_pointwise :
  forall (C : nat) (HCgt2 : (C > 2)%nat)
    (seq1 seq2 : nat -> nat)
    (Hsparse1 : forall i : nat, (INR (seq1 (S i)) > INR C * INR (seq1 i))%R)
    (Hsparse2 : forall i : nat, (INR (seq2 (S i)) > INR C * INR (seq2 i))%R)
    (Hge2_1 : forall i : nat, (seq1 i >= 2)%nat)
    (Hge2_2 : forall i : nat, (seq2 i >= 2)%nat)
    (I1 I2 : list nat)
    (Hdup1 : NoDup I1) (Hsorted1 : Sorted Nat.lt I1)
    (Hdup2 : NoDup I2) (Hsorted2 : Sorted Nat.lt I2)
    (coeffs : nat -> nat -> Complex)
    (n1 n2 : nat) (Hn1 : n1 = length I1) (Hn2 : n2 = length I2)
    (Hn1_pos : (n1 > 0)%nat) (Hn2_pos : (n2 > 0)%nat)
    (HI1 : I1 = seq 0 n1)
    (HI2 : I2 = seq 0 n2)
    (H_dom : forall idx1 idx2 : nat, idx1 <> idx2 ->
        (idx1 < n1 * n2)%nat -> (idx2 < n1 * n2)%nat ->
        ((idx1 / n2)%nat = (idx2 / n2)%nat ->
         (seq1 ((idx1 / n2)%nat) >= Nat.max (seq2 ((idx1 mod n2)%nat)) (seq2 ((idx2 mod n2)%nat)))%nat) /\
        ((idx1 mod n2)%nat = (idx2 mod n2)%nat ->
         (seq2 ((idx1 mod n2)%nat) >= Nat.max (seq1 ((idx1 / n2)%nat)) (seq1 ((idx2 / n2)%nat)))%nat))
    (H_index_bound : forall idx1 idx2 : nat,
        (idx1 < n1 * n2)%nat -> (idx2 < n1 * n2)%nat ->
        (Z.abs_nat (Z.of_nat (idx1 / n2) - Z.of_nat (idx2 / n2)) +
         Z.abs_nat (Z.of_nat (idx1 mod n2) - Z.of_nat (idx2 mod n2)) <= 6)%nat),
  let vals1 := map seq1 I1 in
  let vals2 := map seq2 I2 in
  let a i := nth i vals1 0%nat in
  let b j := nth j vals2 0%nat in
  let w i j := INR (Nat.min (a i) (b j)) / (INR (a i) * INR (b j)) in
  let gamma i j := sqrt (w i j) in
  let phi2D_norm (i j : nat) (k : nat) : Complex :=
    Cof_real (/ gamma i j) *c (psi (a i) k *c psi (b j) k) in
  let F_2D (k : nat) : Complex :=
    Csum (fun i => Csum (fun j => coeffs i j *c phi2D_norm i j k) n2) n1 in
  let maxIdx1 := fold_right Nat.max 0%nat I1 in
  let maxIdx2 := fold_right Nat.max 0%nat I2 in
  let M := S (max (seq1 maxIdx1) (seq2 maxIdx2)) in
  let S := sum_f_R0 (fun i =>
             sum_f_R0 (fun j => Cnorm_sq (coeffs i j)) (n2 - 1)) (n1 - 1) in
  let K_C := K (INR C) in
  let K0 := (Rmax 8 ((INR C) ^ 3)) / 4 in
  let M_bound := K0 * ((1 + 4 * K_C) * (1 + 4 * K_C) - 1) in
  ((1 - M_bound) * S <= l2_norm_sq F_2D (M - 1) <= (1 + M_bound) * S)%R.
Proof.
  intros C HCgt2 seq1 seq2 Hsparse1 Hsparse2 Hge2_1 Hge2_2
         I1 I2 Hdup1 Hsorted1 Hdup2 Hsorted2 coeffs n1 n2 Hn1 Hn2 Hn1_pos Hn2_pos
         HI1 HI2 H_dom H_index_bound.
  assert (Hc_ge2 : (C >= 2)%nat) by lia.
  assert (HCgt1_R : 1 < INR C) by (change 1 with (INR 1); apply lt_INR; lia).
  set (r := sqrt (INR C)).
  assert (Hr_gt1 : r > 1).
  { unfold r; rewrite <- sqrt_1. apply sqrt_lt_1; [lra|apply pos_INR|exact HCgt1_R]. }
  assert (Hr_pos : r > 0) by (apply sqrt_lt_R0_c; apply lt_0_INR; lia).
  set (K_C := K (INR C)).
  assert (HK_pos : 0 < K_C) by (apply K_pos; exact HCgt2).

  set (n := (n1 * n2)%nat).
  set (coeffs_flat := map (fun idx : nat => coeffs (idx / n2)%nat (idx mod n2)%nat) (seq 0 n)).
  assert (Hlen_flat : length coeffs_flat = n).
  { subst n; unfold coeffs_flat; rewrite length_map, List.length_seq; reflexivity. }

  assert (Hseq_nth : forall idx, (idx < n)%nat -> nth idx (seq 0 n) 0%nat = idx).
  { intros idx Hlt; apply nth_seq_general; exact Hlt. }

  assert (Hnth_flat : forall idx, (idx < n)%nat -> nth idx coeffs_flat C0 = coeffs (idx / n2)%nat (idx mod n2)%nat).
  { intros idx Hlt; unfold coeffs_flat.
    rewrite (H_nth_map nat Complex (fun idx0 : nat => coeffs (idx0 / n2)%nat (idx0 mod n2)%nat)
                      (seq 0 n) C0 0%nat idx).
    - rewrite Hseq_nth; auto.
    - rewrite List.length_seq; exact Hlt. }

  set (vals1 := map seq1 I1).
  set (vals2 := map seq2 I2).
  set (a := fun i : nat => nth i vals1 0%nat).
  set (b := fun j : nat => nth j vals2 0%nat).
  set (w := fun i j : nat => INR (Nat.min (a i) (b j)) / (INR (a i) * INR (b j))).
  set (gamma := fun i j : nat => sqrt (w i j)).
  set (phi2D_norm := fun (i j k : nat) => Cof_real (/ gamma i j) *c (psi (a i) k *c psi (b j) k)).
  pose (phi_flat := fun idx k => phi2D_norm (idx / n2)%nat (idx mod n2)%nat k).

  assert (Hseq1_inc : forall x y, (x <= y)%nat -> (seq1 x <= seq1 y)%nat).
  { intros x y Hle; destruct (Nat.eq_dec x y) as [Heq | Hne].
    - subst; apply Nat.le_refl.
    - apply Nat.lt_le_incl; eapply seq_strict_growth_lt; eauto; lia. }
  assert (Hseq2_inc : forall x y, (x <= y)%nat -> (seq2 x <= seq2 y)%nat).
  { intros x y Hle; destruct (Nat.eq_dec x y) as [Heq | Hne].
    - subst; apply Nat.le_refl.
    - apply Nat.lt_le_incl; eapply seq_strict_growth_lt; eauto; lia. }

  set (maxIdx1 := fold_right Nat.max 0%nat I1).
  set (maxIdx2 := fold_right Nat.max 0%nat I2).
  set (M := S (max (seq1 maxIdx1) (seq2 maxIdx2))).

  assert (Htrunc : forall idx k, (idx < n)%nat -> (k >= Nat.pred M)%nat -> phi_flat idx k = C0).
  { intros idx k Hidx Hk; unfold phi_flat.
    set (i := (idx / n2)%nat); set (j := (idx mod n2)%nat).
    assert (Hi : (i < n1)%nat) by (apply Nat.Div0.div_lt_upper_bound; lia).
    assert (Hj : (j < n2)%nat) by (apply Nat.mod_upper_bound; lia).
    unfold phi2D_norm.
    assert (Ha_le_max : (a i <= max (seq1 maxIdx1) (seq2 maxIdx2))%nat).
    { unfold a, vals1.
      assert (Hi_len : (i < length I1)%nat) by (rewrite <- Hn1; exact Hi).
      rewrite (H_nth_map nat nat seq1 I1 0%nat 0%nat i Hi_len).
      apply Nat.le_trans with (seq1 maxIdx1).
      - apply Hseq1_inc.
        eapply fold_right_max_ge.
        apply nth_In; exact Hi_len.
      - apply Nat.le_max_l. }
    assert (Hb_le_max : (b j <= max (seq1 maxIdx1) (seq2 maxIdx2))%nat).
    { unfold b, vals2.
      assert (Hj_len : (j < length I2)%nat) by (rewrite <- Hn2; exact Hj).
      rewrite (H_nth_map nat nat seq2 I2 0%nat 0%nat j Hj_len).
      apply Nat.le_trans with (seq2 maxIdx2).
      - apply Hseq2_inc.
        eapply fold_right_max_ge.
        apply nth_In; exact Hj_len.
      - apply Nat.le_max_r. }
    assert (Hmax_le_k : (max (seq1 maxIdx1) (seq2 maxIdx2) <= k)%nat).
    { unfold M in Hk; lia. }
    assert (Ha_le_k : (a i <= k)%nat) by lia.
    assert (Hb_le_k : (b j <= k)%nat) by lia.
    rewrite (psi_ge_n_zero (a i) k Ha_le_k).
    rewrite (psi_ge_n_zero (b j) k Hb_le_k).
    rewrite Cmul_0_l.
    rewrite Cmul_0_r.
    reflexivity. }

  assert (Hnorm1 : forall idx, (idx < n)%nat -> l2_norm_sq (phi_flat idx) (Nat.pred M) = 1%R).
  { intros idx Hlt; unfold phi_flat.
    set (i := (idx / n2)%nat); set (j := (idx mod n2)%nat).
    assert (Hi : (i < n1)%nat) by (apply Nat.Div0.div_lt_upper_bound; lia).
    assert (Hj : (j < n2)%nat) by (apply Nat.mod_upper_bound; lia).
    unfold phi2D_norm.
    assert (Ha_ge2 : (a i >= 2)%nat).
    { unfold a, vals1.
      assert (Hi_len : (i < length I1)%nat) by (rewrite <- Hn1; exact Hi).
      rewrite (H_nth_map nat nat seq1 I1 0%nat 0%nat i Hi_len).
      apply Hge2_1. }
    assert (Hb_ge2 : (b j >= 2)%nat).
    { unfold b, vals2.
      assert (Hj_len : (j < length I2)%nat) by (rewrite <- Hn2; exact Hj).
      rewrite (H_nth_map nat nat seq2 I2 0%nat 0%nat j Hj_len).
      apply Hge2_2. }
    set (g := gamma i j).
    assert (Hg_pos : 0 < g).
    { unfold g, gamma, w.
      assert (Hmin_pos : (0 < Nat.min (a i) (b j))%nat) by lia.
      apply sqrt_lt_R0_c.
      apply Rdiv_lt_0_compat.
      - apply lt_0_INR; exact Hmin_pos.
      - apply Rmult_lt_0_compat; apply lt_0_INR; lia. }

    assert (Ha_le_max : (a i <= max (seq1 maxIdx1) (seq2 maxIdx2))%nat).
    { unfold a, vals1.
      assert (Hi_len : (i < length I1)%nat) by (rewrite <- Hn1; exact Hi).
      rewrite (H_nth_map nat nat seq1 I1 0%nat 0%nat i Hi_len).
      apply Nat.le_trans with (seq1 maxIdx1).
      - apply Hseq1_inc. eapply fold_right_max_ge. apply nth_In; exact Hi_len.
      - apply Nat.le_max_l. }
    assert (Hb_le_max : (b j <= max (seq1 maxIdx1) (seq2 maxIdx2))%nat).
    { unfold b, vals2.
      assert (Hj_len : (j < length I2)%nat) by (rewrite <- Hn2; exact Hj).
      rewrite (H_nth_map nat nat seq2 I2 0%nat 0%nat j Hj_len).
      apply Nat.le_trans with (seq2 maxIdx2).
      - apply Hseq2_inc. eapply fold_right_max_ge. apply nth_In; exact Hj_len.
      - apply Nat.le_max_r. }
    assert (Ha_lt_M : (a i < M)%nat) by (unfold M; apply Nat.lt_succ_r; exact Ha_le_max).
    assert (Hb_lt_M : (b j < M)%nat) by (unfold M; apply Nat.lt_succ_r; exact Hb_le_max).

    set (F k := Cof_real (/ g) *c (psi (a i) k *c psi (b j) k)).
    assert (HnormF : l2_norm_sq F (Nat.pred M) = 1%R).
    { unfold l2_norm_sq, F.
      assert (Heq : forall k, Cnorm_sq (Cof_real (/ g) *c (psi (a i) k *c psi (b j) k))
                     = (/ g)^2 * (Cnorm_sq (psi (a i) k) * Cnorm_sq (psi (b j) k))).
      { intro k.
        rewrite Cnorm_sq_mult, (Cnorm_sq_mult (psi (a i) k) (psi (b j) k)).
        assert (Hcof_sq : Cnorm_sq (Cof_real (/ g)) = (/ g)^2).
        { unfold Cof_real, Cnorm_sq, Rsqr; simpl; ring. }
        rewrite Hcof_sq; reflexivity. }
      rewrite (sum_f_R0_ext _ (fun k => (/ g)^2 * (Cnorm_sq (psi (a i) k) * Cnorm_sq (psi (b j) k)))).
      - rewrite (sum_f_R0_scal_l ((/ g)^2) (fun k => Cnorm_sq (psi (a i) k) * Cnorm_sq (psi (b j) k)) (Nat.pred M)).

        destruct (Nat.min_spec (a i) (b j)) as [(Hle_ab & Hmin_ab) | (Hle_ba & Hmin_ba)].
        * assert (Ha_le_predM : (a i <= Nat.pred M)%nat) by lia.
          assert (Htrunc_full : sum_f_R0 (fun k => Cnorm_sq (psi (a i) k) * Cnorm_sq (psi (b j) k)) (Nat.pred M)
                              = sum_f_R0 (fun k => Cnorm_sq (psi (a i) k) * Cnorm_sq (psi (b j) k)) (a i)).
          { apply sum_f_R0_trunc_tail with (M := a i) (N := Nat.pred M); auto.
            intros k [Hk1 Hk2]; assert (Hk_ge_ai : (a i <= k)%nat) by exact Hk1;
            rewrite (Cnorm_sq_psi_exact (a i) k), (proj2 (Nat.ltb_ge k (a i)) Hk_ge_ai); ring. }
          rewrite Htrunc_full.

          assert (Ha_i_pos : (a i > 0)%nat) by lia.
          replace (a i) with (S (a i - 1))%nat by lia.
          rewrite sum_f_R0_S.
          replace (S (a i - 1)) with (a i) by lia.
          assert (Hlast_zero : Cnorm_sq (psi (a i) (a i)) * Cnorm_sq (psi (b j) (a i)) = 0%R).
          { rewrite (Cnorm_sq_psi_exact (a i) (a i)).
            replace (Nat.ltb (a i) (a i)) with false by (symmetry; apply Nat.ltb_ge; apply Nat.le_refl).
            ring. }
          rewrite Hlast_zero, Rplus_0_r.

          set (cst := (1 / INR (a i)) * (1 / INR (b j))).
          assert (Hterm_eq : forall k, (k < a i)%nat ->
                       Cnorm_sq (psi (a i) k) * Cnorm_sq (psi (b j) k) = cst).
          { intros k Hk_ai.
            assert (Hk_bj : (k < b j)%nat) by (apply Nat.lt_trans with (a i); auto).
            assert (Htb_ai : Nat.ltb k (a i) = true) by (apply Nat.ltb_lt; exact Hk_ai).
            assert (Htb_bj : Nat.ltb k (b j) = true) by (apply Nat.ltb_lt; exact Hk_bj).
            rewrite Cnorm_sq_psi_exact, Htb_ai, Cnorm_sq_psi_exact, Htb_bj.
            unfold cst, Rdiv; field; split; apply Rgt_not_eq; apply lt_0_INR; lia. }
          rewrite (sum_f_R0_ext _ (fun _ => cst) (a i - 1)).
          { rewrite (sum_f_R0_const cst (a i - 1)).
            replace (S (a i - 1))%nat with (a i)%nat by lia.
            unfold g, gamma, w; rewrite Hmin_ab.
            field_simplify.
            - set (s := sqrt (INR (a i) / (INR (a i) * INR (b j)))).
              assert (H_sqrt_sq : s ^ 2 = INR (a i) / (INR (a i) * INR (b j))).
              { replace (s ^ 2) with (s * s) by ring.
                apply sqrt_sqrt.
                apply Rmult_le_pos; [apply pos_INR; lia | left; apply Rinv_0_lt_compat; apply Rmult_lt_0_compat; apply lt_0_INR; lia]. }
              subst s.
              rewrite H_sqrt_sq.
              unfold cst; field; split; apply Rgt_not_eq; apply lt_0_INR; lia.
            - apply Rgt_not_eq, sqrt_lt_R0_c.
              apply Rdiv_lt_0_compat; [apply lt_0_INR; lia | apply Rmult_lt_0_compat; apply lt_0_INR; lia]. }
          { intros k Hk; apply Hterm_eq; lia. }

        * assert (Hb_le_predM : (b j <= Nat.pred M)%nat) by lia.
          assert (Htrunc_full : sum_f_R0 (fun k => Cnorm_sq (psi (a i) k) * Cnorm_sq (psi (b j) k)) (Nat.pred M)
                              = sum_f_R0 (fun k => Cnorm_sq (psi (a i) k) * Cnorm_sq (psi (b j) k)) (b j)).
          { apply sum_f_R0_trunc_tail with (M := b j) (N := Nat.pred M); auto.
            intros k [Hk1 Hk2]; assert (Hk_ge_bj : (b j <= k)%nat) by exact Hk1;
            rewrite (Cnorm_sq_psi_exact (b j) k), (proj2 (Nat.ltb_ge k (b j)) Hk_ge_bj); ring. }
          rewrite Htrunc_full.

          assert (Hb_j_pos : (b j > 0)%nat) by lia.
          replace (b j) with (S (b j - 1))%nat by lia.
          rewrite sum_f_R0_S.
          replace (S (b j - 1)) with (b j) by lia.
          assert (Hlast_zero : Cnorm_sq (psi (a i) (b j)) * Cnorm_sq (psi (b j) (b j)) = 0%R).
          { rewrite (Cnorm_sq_psi_exact (b j) (b j)).
            replace (Nat.ltb (b j) (b j)) with false by (symmetry; apply Nat.ltb_ge; apply Nat.le_refl).
            ring. }
          rewrite Hlast_zero, Rplus_0_r.

          set (cst := (1 / INR (a i)) * (1 / INR (b j))).
          assert (Hterm_eq : forall k, (k < b j)%nat ->
                       Cnorm_sq (psi (a i) k) * Cnorm_sq (psi (b j) k) = cst).
          { intros k Hk_bj.
            assert (Hk_ai : (k < a i)%nat) by (apply Nat.lt_le_trans with (b j); auto).
            assert (Htb_ai : Nat.ltb k (a i) = true) by (apply Nat.ltb_lt; exact Hk_ai).
            assert (Htb_bj : Nat.ltb k (b j) = true) by (apply Nat.ltb_lt; exact Hk_bj).
            rewrite Cnorm_sq_psi_exact, Htb_ai, Cnorm_sq_psi_exact, Htb_bj.
            unfold cst, Rdiv; field; split; apply Rgt_not_eq; apply lt_0_INR; lia. }
          rewrite (sum_f_R0_ext _ (fun _ => cst) (b j - 1)).
          { rewrite (sum_f_R0_const cst (b j - 1)).
            replace (S (b j - 1))%nat with (b j)%nat by lia.
            unfold g, gamma, w; rewrite Hmin_ba.
            field_simplify.
            - set (s := sqrt (INR (b j) / (INR (a i) * INR (b j)))).
              assert (H_sqrt_sq : s ^ 2 = INR (b j) / (INR (a i) * INR (b j))).
              { replace (s ^ 2) with (s * s) by ring.
                apply sqrt_sqrt.
                apply Rmult_le_pos; [apply pos_INR; lia | left; apply Rinv_0_lt_compat; apply Rmult_lt_0_compat; apply lt_0_INR; lia]. }
              subst s.
              rewrite H_sqrt_sq.
              unfold cst; field; split; apply Rgt_not_eq; apply lt_0_INR; lia.
            - apply Rgt_not_eq, sqrt_lt_R0_c.
              apply Rdiv_lt_0_compat; [apply lt_0_INR; lia | apply Rmult_lt_0_compat; apply lt_0_INR; lia]. }
          { intros k Hk; apply Hterm_eq; lia. }
      - intros k Hk; apply Heq. }
    exact HnormF. }

  set (d1 := d_factor r).
  pose (delta_pair := fun (idx1 idx2 : nat) =>
    d1 (idx1 / n2)%nat (idx2 / n2)%nat * d1 (idx1 mod n2)%nat (idx2 mod n2)%nat).

  assert (d_factor_sym : forall i j, d_factor r i j = d_factor r j i).
  { intros i j; unfold d_factor.
    destruct (Nat.eq_dec i j) as [Heq | Hneq].
    - subst i; reflexivity.
    - assert (Hij_false : (i =? j)%nat = false) by (apply Nat.eqb_neq; exact Hneq).
      assert (Hji_false : (j =? i)%nat = false) by (apply Nat.eqb_neq; auto).
      rewrite Hij_false, Hji_false.
      f_equal. f_equal.
      replace (Z.of_nat j - Z.of_nat i)%Z with (- (Z.of_nat i - Z.of_nat j))%Z by lia.
      rewrite Z_abs_nat_opp.
      reflexivity. }

  assert (Hdelta_sym : forall (i j : nat), (i < n)%nat -> (j < n)%nat -> delta_pair i j = delta_pair j i).
  { intros i j Hi Hj; unfold delta_pair, d1.
    rewrite (d_factor_sym (i / n2)%nat (j / n2)%nat).
    rewrite (d_factor_sym (i mod n2)%nat (j mod n2)%nat).
    reflexivity. }

  assert (d_factor_nonneg : forall i j, 0 <= d_factor r i j).
  { intros i j; unfold d_factor.
    destruct (Nat.eqb_spec i j) as [Heq | Hneq].
    - subst i; lra.
    - apply Rlt_le; apply Rdiv_lt_0_compat; [lra | apply pow_lt; exact Hr_pos]. }

  assert (Hdelta_nonneg : forall (i j : nat), (i < n)%nat -> (j < n)%nat -> 0 <= delta_pair i j).
  { intros i j Hi Hj; unfold delta_pair; apply Rmult_le_pos; apply d_factor_nonneg. }

  set (K0 := (Rmax 8 ((INR C) ^ 3)) / 4).

  assert (Hdecay : forall idx1 idx2, idx1 <> idx2 -> (idx1 < n)%nat -> (idx2 < n)%nat ->
    Cnorm (Csum (fun k => phi_flat idx1 k *c Cconj (phi_flat idx2 k)) (Nat.pred M))
    <= K0 * delta_pair idx1 idx2).
  {
    intros idx1 idx2 Hneq Hlt1 Hlt2.
    destruct (H_dom idx1 idx2 Hneq Hlt1 Hlt2) as [H_dom_i H_dom_j].

    assert (Ha_eq : a = (fun i => nth i (map seq1 I1) 0%nat)).
    { unfold a, vals1; reflexivity. }
    assert (Hb_eq : b = (fun j => nth j (map seq2 I2) 0%nat)).
    { unfold b, vals2; reflexivity. }
    assert (Hgamma_eq : gamma = (fun i j => sqrt (INR (Nat.min (a i) (b j)) / (INR (a i) * INR (b j))))).
    { unfold gamma, w; reflexivity. }
    assert (Hphi2D_norm_eq : phi2D_norm = (fun i j k => Cof_real (/ gamma i j) *c (psi (a i) k *c psi (b j) k))).
    { unfold phi2D_norm; reflexivity. }
    assert (Hphi_flat_eq : phi_flat = (fun idx k => phi2D_norm ((idx / n2)%nat) ((idx mod n2)%nat) k)).
    { unfold phi_flat; reflexivity. }
    assert (Hdelta_pair_eq : delta_pair = (fun idx1 idx2 => d_factor r ((idx1 / n2)%nat) ((idx2 / n2)%nat) * d_factor r ((idx1 mod n2)%nat) ((idx2 mod n2)%nat))).
    { unfold delta_pair, d1; reflexivity. }

    assert (HmaxIdx1_eq : maxIdx1 = fold_right Nat.max 0%nat I1).
    { unfold maxIdx1; reflexivity. }
    assert (HmaxIdx2_eq : maxIdx2 = fold_right Nat.max 0%nat I2).
    { unfold maxIdx2; reflexivity. }
    assert (HM_eq : M = S (max (seq1 maxIdx1) (seq2 maxIdx2))).
    { unfold M; reflexivity. }
    assert (Hr_eq : r = sqrt (INR C)).
    { unfold r; reflexivity. }

    pose proof (phi_flat_decay_general C Hc_ge2 seq1 seq2
                  Hsparse1 Hsparse2 Hge2_1 Hge2_2
                  I1 I2 Hdup1 Hsorted1 Hdup2 Hsorted2
                  n1 n2 Hn1 Hn2 HI1 HI2
                  a b Ha_eq Hb_eq
                  gamma Hgamma_eq
                  phi2D_norm Hphi2D_norm_eq
                  maxIdx1 maxIdx2 HmaxIdx1_eq HmaxIdx2_eq
                  M HM_eq r Hr_eq
                  phi_flat Hphi_flat_eq
                  delta_pair Hdelta_pair_eq
                  idx1 idx2 Hneq Hlt1 Hlt2
                  (H_index_bound idx1 idx2 Hlt1 Hlt2)
                  (conj H_dom_i H_dom_j)) as Hbound.
    unfold K0; exact Hbound.
  }

  set (M_bound' := K0 * ((1 + 4 * K_C) * (1 + 4 * K_C) - 1)).

  assert (Hc_ge2_R : INR C >= 2) by (apply Rle_ge; change 2 with (INR 2); apply le_INR; exact Hc_ge2).

  assert (Hrow_sum_U : forall idx : nat, (idx < n)%nat ->
    sum_f_R0 (fun jdx : nat => if eq_nat_dec idx jdx then 0 else delta_pair idx jdx) (Nat.pred n)
    <= (1 + 4 * K_C) * (1 + 4 * K_C) - 1).
  {
    intros idx Hlt.
    set (i0 := (idx / n2)%nat); set (j0 := (idx mod n2)%nat).
    assert (Hi0 : (i0 < n1)%nat) by (apply Nat.Div0.div_lt_upper_bound; lia).
    assert (Hj0 : (j0 < n2)%nat) by (apply Nat.mod_upper_bound; lia).
    set (S1 := sum_f_R0 (fun i' => if eq_nat_dec i0 i' then 0 else d1 i0 i') (Nat.pred n1)).
    set (S2 := sum_f_R0 (fun j' => if eq_nat_dec j0 j' then 0 else d1 j0 j') (Nat.pred n2)).

    assert (HS1 : S1 <= 4 * K_C).
    { unfold S1, d1, r, K_C. apply (d_factor_row_sum_le_4K C HCgt2 n1 i0 Hi0). }
    assert (HS2 : S2 <= 4 * K_C).
    { unfold S2, d1, r, K_C. apply (d_factor_row_sum_le_4K C HCgt2 n2 j0 Hj0). }
    assert (HS1_nonneg : 0 <= S1) by (unfold S1; apply sum_f_R0_nonneg; intros i'; destruct (eq_nat_dec i0 i'); [apply Rle_refl | unfold d1; apply d_factor_nonneg]).
    assert (HS2_nonneg : 0 <= S2) by (unfold S2; apply sum_f_R0_nonneg; intros j'; destruct (eq_nat_dec j0 j'); [apply Rle_refl | unfold d1; apply d_factor_nonneg]).
    assert (Hrow_decomp : sum_f_R0 (fun jdx : nat => if eq_nat_dec idx jdx then 0
      else delta_pair idx jdx) (Nat.pred n) = (1 + S1) * (1 + S2) - 1).
    {
      subst n; unfold delta_pair, d1, S1, S2.
      replace (idx / n2)%nat with i0 by (unfold i0; reflexivity).
      replace (idx mod n2)%nat with j0 by (unfold j0; reflexivity).
      assert (Hidx_form : idx = (i0 * n2 + j0)%nat) by (unfold i0, j0; rewrite Nat.mul_comm; apply Nat.div_mod; lia).
      rewrite Hidx_form.
      apply (prod_row_sum_decomp_eq n1 n2 i0 j0 (d_factor r) Hi0 Hj0 (d_factor_diag r)).
    }
    rewrite Hrow_decomp.
    assert (Hprod_ub : (1 + S1) * (1 + S2) - 1 <= (1 + 4 * K_C) * (1 + 4 * K_C) - 1) by nra.
    exact Hprod_ub.
  }

  assert (Hrow_sum : forall idx : nat, (idx < n)%nat ->
    sum_f_R0 (fun jdx : nat => if eq_nat_dec idx jdx then 0
      else delta_pair idx jdx) (Nat.pred n) <= M_bound').
  {
    intros idx Hlt.
    apply Rle_trans with ((1 + 4 * K_C) * (1 + 4 * K_C) - 1).
    - apply Hrow_sum_U; auto.
    - assert (H_K0_ge1 : 1 <= K0).
      {
        unfold K0.
        assert (H_cube_ge_8 : (INR C)^3 >= 8).
        {
          apply Rle_ge. transitivity (2^3).
          - assert (H23 : 2^3 = 8) by (unfold pow; simpl; ring). rewrite H23; lra.
          - apply pow_incr with (x := 2) (y := INR C) (n := 3%nat);
              split; [lra | apply Rge_le; exact Hc_ge2_R].
        }
        assert (Hmax_eq : Rmax 8 ((INR C)^3) = (INR C)^3) by (apply Rmax_right; apply Rge_le; exact H_cube_ge_8).
        rewrite Hmax_eq; lra.
      }
      assert (H_nonneg : 0 <= (1 + 4 * K_C) * (1 + 4 * K_C) - 1) by nra.
      unfold M_bound'.
      apply Rmult_le_compat_r with (r := (1 + 4 * K_C) * (1 + 4 * K_C) - 1) in H_K0_ge1.
      -- rewrite Rmult_1_l in H_K0_ge1.
         exact H_K0_ge1.
      -- exact H_nonneg.
  }

  set (delta_pair_K0 := fun i j : nat => K0 * delta_pair i j).

  assert (Hdelta_sym_K0 : forall i j : nat, (i < n)%nat -> (j < n)%nat ->
    delta_pair_K0 i j = delta_pair_K0 j i).
  { intros i j Hi Hj; unfold delta_pair_K0; rewrite (Hdelta_sym i j Hi Hj); reflexivity. }

  assert (Hdelta_nonneg_K0 : forall i j : nat, (i < n)%nat -> (j < n)%nat ->
    0 <= delta_pair_K0 i j).
  { intros i j Hi Hj; unfold delta_pair_K0; apply Rmult_le_pos.
    - assert (H_K0_nonneg : 0 <= K0).
      { apply Rlt_le; unfold K0; apply Rdiv_lt_0_compat.
        - apply Rlt_le_trans with 8; [lra | apply Rmax_l].
        - lra. }
      exact H_K0_nonneg.
    - apply Hdelta_nonneg; auto. }

  assert (Hdecay_K0 : forall idx1 idx2, idx1 <> idx2 -> (idx1 < n)%nat -> (idx2 < n)%nat ->
    Cnorm (Csum (fun k => phi_flat idx1 k *c Cconj (phi_flat idx2 k)) (Nat.pred M))
    <= delta_pair_K0 idx1 idx2).
  { intros idx1 idx2 Hneq Hlt1 Hlt2; unfold delta_pair_K0; apply Hdecay; auto. }

  assert (Hrow_sum_K0 : forall idx : nat, (idx < n)%nat ->
    sum_f_R0 (fun jdx : nat => if eq_nat_dec idx jdx then 0
      else delta_pair_K0 idx jdx) (Nat.pred n) <= M_bound').
  {
    intros idx Hlt.
    unfold delta_pair_K0.
    assert (Hsum_mult : forall (c : R) (f : nat -> R) (m : nat),
      sum_f_R0 (fun i => c * f i) m = c * sum_f_R0 f m).
    { intros c f m; induction m; simpl; [ring | rewrite IHm; ring]. }
    assert (H_if_eq : forall jdx, (if eq_nat_dec idx jdx then 0 else K0 * delta_pair idx jdx)
      = K0 * (if eq_nat_dec idx jdx then 0 else delta_pair idx jdx)).
    { intros jdx; destruct (eq_nat_dec idx jdx); ring. }
    assert (Hgoal_eq : sum_f_R0 (fun jdx : nat => if eq_nat_dec idx jdx then 0 else K0 * delta_pair idx jdx) (Nat.pred n)
                     = sum_f_R0 (fun jdx : nat => K0 * (if eq_nat_dec idx jdx then 0 else delta_pair idx jdx)) (Nat.pred n)).
    { apply sum_f_R0_ext; intros i Hi; apply H_if_eq. }
    rewrite Hgoal_eq.
    rewrite (Hsum_mult K0 (fun jdx : nat => if eq_nat_dec idx jdx then 0 else delta_pair idx jdx) (Nat.pred n)).
    apply Rmult_le_compat_l.
    { apply Rlt_le; unfold K0; apply Rdiv_lt_0_compat.
      - apply Rlt_le_trans with 8; [lra | apply Rmax_l].
      - lra. }
    apply Hrow_sum_U; auto.
  }

  assert (HM_pos : (M > 0)%nat) by (unfold M; lia).
  pose proof (abstract_unconditional_basis n phi_flat M M_bound'
    delta_pair_K0 HM_pos Htrunc Hnorm1 Hdelta_sym_K0 Hdelta_nonneg_K0 Hdecay_K0 Hrow_sum_K0
    coeffs_flat Hlen_flat) as H_abs.

  assert (HF_flat_eq : forall k,
    Csum (fun i => Csum (fun j => coeffs i j *c phi2D_norm i j k) n2) n1
    = Csum (fun idx : nat => nth idx coeffs_flat C0 *c phi_flat idx k) n).
  { intros k; unfold phi_flat.
    rewrite <- (Csum_flatten n1 n2 (fun i j => coeffs i j *c phi2D_norm i j k)).
    apply Csum_ext'; intros idx Hidx.
    rewrite (Hnth_flat idx Hidx); reflexivity. }

  assert (HS_flat_eq : sum_f_R0 (fun i =>
      sum_f_R0 (fun j => Cnorm_sq (coeffs i j)) (n2 - 1)) (n1 - 1)
    = sum_f_R0 (fun idx : nat => Cnorm_sq (nth idx coeffs_flat C0)) (Nat.pred n)).
  {
    subst n.
    rewrite <- (sum_f_R0_flatten n1 n2 Hn1_pos Hn2_pos (fun i j => Cnorm_sq (coeffs i j))).
    transitivity (sum_f_R0 (fun idx : nat => Cnorm_sq (coeffs (idx / n2)%nat (idx mod n2)%nat))
                          (Nat.pred (n1 * n2))).
    - apply f_equal; lia.
    - apply sum_f_R0_ext; intros idx Hle.
      assert (Hidx_lt : (idx < n1 * n2)%nat) by lia.
      rewrite (Hnth_flat idx Hidx_lt); reflexivity.
  }

  assert (HM_pred_eq : Nat.pred M = (M - 1)%nat) by (unfold M; lia).

  assert (H_final : (1 - M_bound') *
    (sum_f_R0 (fun i => sum_f_R0 (fun j => Cnorm_sq (coeffs i j)) (n2 - 1)) (n1 - 1))
    <= l2_norm_sq (fun k : nat =>
         Csum (fun i => Csum (fun j => coeffs i j *c phi2D_norm i j k) n2) n1) (M - 1)
    <= (1 + M_bound') *
    (sum_f_R0 (fun i => sum_f_R0 (fun j => Cnorm_sq (coeffs i j)) (n2 - 1)) (n1 - 1))).
  {
    set (F := fun k : nat => Csum (fun idx : nat => nth idx coeffs_flat C0 *c phi_flat idx k) n).
    cbv zeta in H_abs.
    destruct H_abs as [H_low H_high].
    assert (H_eq : l2_norm_sq (fun k : nat =>
        Csum (fun i => Csum (fun j => coeffs i j *c phi2D_norm i j k) n2) n1) (M - 1)
        = l2_norm_sq F (Nat.pred M)).
    {
      unfold l2_norm_sq.
      rewrite <- HM_pred_eq.
      apply sum_f_R0_ext; intros k Hk.
      rewrite (HF_flat_eq k); reflexivity.
    }
    rewrite H_eq, HS_flat_eq.
    unfold F.
    exact (conj H_low H_high).
  }
  apply H_final.
Qed.

(* ============ 顶层 soundness：frame_check_2d_narrow_sound（会话 15 新增） ============ *)
(* frame_check_2d_narrow cC vals1 vals2 = true（两轴 sorted/ge2/增长/单带/支配/曼哈顿）
   ⟹ 对任意系数矩阵，2D 窄轨无条件基界成立：
     (1 - M_bound) S ≤ l2_norm_sq F_2D (M-1) ≤ (1 + M_bound) S
   M_bound = K0·((1+4K_C)²−1)，K0 = Rmax 8 (C³) / 4。 *)
Theorem frame_check_2d_narrow_sound (cC : nat) (vals1 vals2 : list nat) :
  (cC > 2)%nat -> (0 < length vals1)%nat -> (0 < length vals2)%nat ->
  frame_check_2d_narrow cC vals1 vals2 = true ->
  forall coeffs : nat -> nat -> Complex,
    let n1 := length vals1 in
    let n2 := length vals2 in
    let I1 := seq 0 n1 in
    let I2 := seq 0 n2 in
    let seq1 := seq_ext vals1 cC in
    let seq2 := seq_ext vals2 cC in
    let vals1' := map seq1 I1 in
    let vals2' := map seq2 I2 in
    let a i := nth i vals1' 0%nat in
    let b j := nth j vals2' 0%nat in
    let w i j := INR (Nat.min (a i) (b j)) / (INR (a i) * INR (b j)) in
    let gamma i j := sqrt (w i j) in
    let phi2D_norm (i j : nat) (k : nat) : Complex :=
      Cof_real (/ gamma i j) *c (psi (a i) k *c psi (b j) k) in
    let F_2D (k : nat) : Complex :=
      Csum (fun i => Csum (fun j => coeffs i j *c phi2D_norm i j k) n2) n1 in
    let maxIdx1 := fold_right Nat.max 0%nat I1 in
    let maxIdx2 := fold_right Nat.max 0%nat I2 in
    let M := S (max (seq1 maxIdx1) (seq2 maxIdx2)) in
    let S := sum_f_R0 (fun i =>
               sum_f_R0 (fun j => Cnorm_sq (coeffs i j)) (n2 - 1)) (n1 - 1) in
    let K_C := K (INR cC) in
    let K0 := (Rmax 8 ((INR cC) ^ 3)) / 4 in
    let M_bound := K0 * ((1 + 4 * K_C) * (1 + 4 * K_C) - 1) in
    ((1 - M_bound) * S <= l2_norm_sq F_2D (M - 1) <= (1 + M_bound) * S)%R.
Proof.
  intros Hc Hlen1 Hlen2 Hfc coeffs.
  unfold frame_check_2d_narrow in Hfc.
  (* && 左结合：((s1&&s2)&&(g1&&g2))&&(cg1&&cg2) 再 && single_band(dom&&man) *)
  apply andb_true_iff in Hfc. destruct Hfc as [Habc Hrest].
  apply andb_true_iff in Habc. destruct Habc as [Hab Hcg12].
  apply andb_true_iff in Hab. destruct Hab as [Hs12 Hg12].
  apply andb_true_iff in Hrest. destruct Hrest as [Hsb Hrest].
  apply andb_true_iff in Hrest. destruct Hrest as [Hdom Hman].
  apply andb_true_iff in Hs12. destruct Hs12 as [Hs1 Hs2].
  apply andb_true_iff in Hg12. destruct Hg12 as [Hg1 Hg2].
  apply andb_true_iff in Hcg12. destruct Hcg12 as [Hcg1 Hcg2].

  cbv zeta.
  set (n1 := length vals1).
  set (n2 := length vals2).
  set (I1 := seq 0 n1).
  set (I2 := seq 0 n2).
  set (seq1 := seq_ext vals1 cC).
  set (seq2 := seq_ext vals2 cC).

  assert (Hc_ge2 : (cC >= 2)%nat) by lia.

  (* Hsparse1/2：seq_ext 全局增长 *)
  assert (Hsparse1 : forall i : nat, (INR (seq1 (S i)) > INR cC * INR (seq1 i))%R).
  { intro i; unfold seq1; apply (seq_ext_growth_R vals1 cC Hc_ge2 Hlen1 Hcg1 Hg1 i). }
  assert (Hsparse2 : forall i : nat, (INR (seq2 (S i)) > INR cC * INR (seq2 i))%R).
  { intro i; unfold seq2; apply (seq_ext_growth_R vals2 cC Hc_ge2 Hlen2 Hcg2 Hg2 i). }

  (* Hge2_1/2：全局 ≥2 *)
  assert (Hge2_1 : forall i : nat, (seq1 i >= 2)%nat).
  { intro i; unfold seq1; apply (seq_ext_ge2 vals1 cC Hc_ge2 Hlen1 Hg1 i). }
  assert (Hge2_2 : forall i : nat, (seq2 i >= 2)%nat).
  { intro i; unfold seq2; apply (seq_ext_ge2 vals2 cC Hc_ge2 Hlen2 Hg2 i). }

  (* I1/I2：NoDup + Sorted + n1/n2 对齐 *)
  assert (Hdup1 : NoDup I1) by (unfold I1; apply seq_NoDup).
  assert (Hsorted1 : Sorted Nat.lt I1) by (unfold I1; apply sorted_seq_0).
  assert (Hdup2 : NoDup I2) by (unfold I2; apply seq_NoDup).
  assert (Hsorted2 : Sorted Nat.lt I2) by (unfold I2; apply sorted_seq_0).
  assert (Hn1_eq : n1 = length I1) by (unfold I1, n1; rewrite length_seq; reflexivity).
  assert (Hn2_eq : n2 = length I2) by (unfold I2, n2; rewrite length_seq; reflexivity).
  assert (Hn1_pos : (n1 > 0)%nat) by (unfold n1; lia).
  assert (Hn2_pos : (n2 > 0)%nat) by (unfold n2; lia).
  assert (HI1 : I1 = seq 0 n1) by (unfold I1; reflexivity).
  assert (HI2 : I2 = seq 0 n2) by (unfold I2; reflexivity).

  (* H_dom：由 hdom_2d_narrow 给出（点态） *)
  assert (H_dom : forall idx1 idx2 : nat, idx1 <> idx2 ->
      (idx1 < n1 * n2)%nat -> (idx2 < n1 * n2)%nat ->
      ((idx1 / n2)%nat = (idx2 / n2)%nat ->
       (seq1 ((idx1 / n2)%nat) >= Nat.max (seq2 ((idx1 mod n2)%nat)) (seq2 ((idx2 mod n2)%nat)))%nat) /\
      ((idx1 mod n2)%nat = (idx2 mod n2)%nat ->
       (seq2 ((idx1 mod n2)%nat) >= Nat.max (seq1 ((idx1 / n2)%nat)) (seq1 ((idx2 / n2)%nat)))%nat)).
  { intros idx1 idx2 Hneq Hlt1' Hlt2'.
    assert (Hn1_r : (n1 = length vals1)%nat) by (unfold n1; reflexivity).
    assert (Hn2_r : (n2 = length vals2)%nat) by (unfold n2; reflexivity).
    pose proof (hdom_2d_narrow vals1 vals2 cC n1 n2 Hn1_r Hn2_r Hsb Hdom idx1 idx2 Hneq Hlt1' Hlt2')
      as Hdom_pair.
    unfold seq1, seq2 in Hdom_pair.
    exact Hdom_pair. }

  (* H_index_bound：由 manhattan_ok（n1+n2 ≤ 8）给出 *)
  assert (Hman_le : (n1 + n2 <= 8)%nat).
  { unfold n1, n2; apply Nat.leb_le. exact Hman. }
  assert (H_index_bound : forall idx1 idx2 : nat,
      (idx1 < n1 * n2)%nat -> (idx2 < n1 * n2)%nat ->
      (Z.abs_nat (Z.of_nat (idx1 / n2) - Z.of_nat (idx2 / n2)) +
       Z.abs_nat (Z.of_nat (idx1 mod n2) - Z.of_nat (idx2 mod n2)) <= 6)%nat).
  { intros idx1 idx2 Hlt1 Hlt2.
    apply (index_bound_2d n1 n2 idx1 idx2 Hn1_pos Hn2_pos Hman_le Hlt1 Hlt2). }

  pose proof (tensor_product_unconditional_basis_pointwise cC Hc
    seq1 seq2 Hsparse1 Hsparse2 Hge2_1 Hge2_2
    I1 I2 Hdup1 Hsorted1 Hdup2 Hsorted2
    coeffs n1 n2 Hn1_eq Hn2_eq Hn1_pos Hn2_pos HI1 HI2
    H_dom H_index_bound) as H_asm.
  cbv zeta in H_asm.
  exact H_asm.
Qed.
End FrameCheck2DNarrow.

(* ============================================================
   A2 酉不变性（2026-08-20 会话 17，探针 src\_probe_unitary.v 验证 RC=0 后并入）
   ------------------------------------------------------------
   论文 A/B §4「旋转组（psi-rope）是酉变换」的形式化（unitary_invariance_frame）：
   - rot_preserves_inner：单位模 u（Cnorm_sq u = 1）⟹ (u·x)·conj(u·y) = x·conj y（酉性步骤）
   - unitary_invariance_point：全局保内积 U ⟹ ‖Σ U(g_i)‖² = ‖Σ g_i‖²（核心定理）
   - unitary_invariance_rope_point / _rope：逐点单位模 ⟹ 位置索引旋转保 l2 范数（RoPE 算子酉性）
   - unitary_invariance_psi_rope / _psi_rope_global：psi-rope 实例（因子形式 / 内和形式）
   注：带索引逐点版本（每带乘 u_i 后对和取模）为假命题（反例 u0=1,u1=-1,g0=g1=1，
       |1-1|²=0≠4=|1+1|²），未并入；带索引 l2 等式需基精确正交（本 psi 族截断窗口
       交叉项非零，由 (1±4/5) 帧界路线覆盖）。
   ============================================================ *)
Module UnitaryInvariance.

Import ExtendedTheorems.
Open Scope R_scope.

(* 1a. 分解恒等式（无假设，纯展开）：(u*x)·conj(u*y) = (u·conj u)·(x·conj y) *)
Lemma rot_preserves_inner_aux (u x y : Complex) :
  (u *c x) *c Cconj (u *c y) = (u *c Cconj u) *c (x *c Cconj y).
Proof.
  destruct u as [a b]; destruct x as [c d]; destruct y as [e f].
  unfold Cmul, Cconj; simpl; f_equal; ring.
Qed.

(* 1b. 单位模 ⟹ u·conj u = C1（= 1+i0） *)
Lemma Cconj_mul_self (u : Complex) (Hu : Cnorm_sq u = 1) : u *c Cconj u = C1.
Proof.
  destruct u as [a b].
  unfold Cmul, Cconj, Cnorm_sq, Rsqr, C1 in *.
  simpl in Hu.
  simpl; f_equal.
  - nra.
  - nra.
Qed.

(* 1. 旋转保内积：u 单位模（Cnorm_sq u = 1）⟹ (u*x)·conj(u*y) = x·conj y（酉性步骤） *)
Lemma rot_preserves_inner (u : Complex) (Hu : Cnorm_sq u = 1) :
  forall x y, (u *c x) *c Cconj (u *c y) = x *c Cconj y.
Proof.
  intros x y.
  rewrite rot_preserves_inner_aux.
  rewrite (Cconj_mul_self u Hu).
  rewrite Cmul_1_l.
  reflexivity.
Qed.

(* 2. 全局酉不变性：U 保内积 ⟹ ‖Σ U(g_i)‖² = ‖Σ g_i‖²（unitary_invariance_frame 正确定型） *)
Lemma unitary_invariance_point (U : Complex -> Complex)
  (H_unitary : forall x y, U x *c Cconj (U y) = x *c Cconj y) :
  forall (g : nat -> Complex) (n : nat),
  Cnorm_sq (Csum (fun i => U (g i)) n) = Cnorm_sq (Csum g n).
Proof.
  intros g n.
  destruct n as [|n].
  - simpl; reflexivity.
  - rewrite (Cnorm_sq_csum (fun i => U (g i)) (S n)).
    rewrite (Cnorm_sq_csum g (S n)).
    (* 只约掉 match (S n)，不展开 re (x *c Cconj y)（否则 f_equal 失配） *)
    change (sum_f_R0 (fun i : nat => sum_f_R0 (fun j : nat => re (U (g i) *c Cconj (U (g j)))) n) n
          = sum_f_R0 (fun i : nat => sum_f_R0 (fun j : nat => re (g i *c Cconj (g j))) n) n).
    apply sum_f_R0_ext; intros i _.
    apply sum_f_R0_ext; intros j _.
    apply f_equal.
    apply H_unitary.
Qed.

(* 3. 逐点单位模保模（对角 / 每位置）：Cnorm_sq u = 1 ⟹ ‖u·S‖² = ‖S‖² *)
Lemma unitary_invariance_rope_point (u S : Complex) (Hu : Cnorm_sq u = 1) :
  Cnorm_sq (u *c S) = Cnorm_sq S.
Proof.
  destruct u as [a b]; destruct S as [c d].
  unfold Cmul, Cnorm_sq, Rsqr in *.
  simpl in Hu.
  simpl.
  nra.
Qed.

(* 4. 位置索引旋转保 l2 范数（psi-rope / RoPE 算子酉性）：每位置乘单位模 u k ⟹ ‖u·F‖²_N = ‖F‖²_N *)
Lemma unitary_invariance_rope (u : nat -> Complex) (Hu : forall k, Cnorm_sq (u k) = 1) :
  forall (F : nat -> Complex) (N : nat),
  l2_norm_sq (fun k => u k *c F k) N = l2_norm_sq F N.
Proof.
  intros F N.
  unfold l2_norm_sq.
  apply sum_f_R0_ext; intros k _.
  apply (unitary_invariance_rope_point (u k) (F k) (Hu k)).
Qed.

(* 5. psi-rope 实例（因子形式）：‖Σ_i c_i·ψ_i‖²_N 在逐点乘 u k 后不变 *)
Theorem unitary_invariance_psi_rope (vals : list nat) (u : nat -> Complex)
  (Hu : forall k, Cnorm_sq (u k) = 1)
  (coeffs : list Complex) (n N : nat) :
  l2_norm_sq (fun k => u k *c Csum (fun i => nth i coeffs C0 *c psi (nth i vals 0%nat) k) n) N
  = l2_norm_sq (fun k => Csum (fun i => nth i coeffs C0 *c psi (nth i vals 0%nat) k) n) N.
Proof.
  apply (unitary_invariance_rope u Hu
           (fun k => Csum (fun i => nth i coeffs C0 *c psi (nth i vals 0%nat) k) n) N).
Qed.

(* 6. psi-rope 实例（内和形式）：u k 作用于每个基函数值——经全局酉不变性（lemma 2 + 1）给出 *)
Theorem unitary_invariance_psi_rope_global (vals : list nat) (u : nat -> Complex)
  (Hu : forall k, Cnorm_sq (u k) = 1)
  (coeffs : list Complex) (n N : nat) :
  l2_norm_sq (fun k => Csum (fun i => u k *c (nth i coeffs C0 *c psi (nth i vals 0%nat) k)) n) N
  = l2_norm_sq (fun k => Csum (fun i => nth i coeffs C0 *c psi (nth i vals 0%nat) k) n) N.
Proof.
  unfold l2_norm_sq.
  apply sum_f_R0_ext; intros k _.
  apply (unitary_invariance_point (fun x => u k *c x) (rot_preserves_inner (u k) (Hu k))
           (fun i => nth i coeffs C0 *c psi (nth i vals 0%nat) k) n).
Qed.

(* 7. RoPE 显式实例（评审 §1 修复，2026-08-20 会话 17）：θ k 为逐位置旋转角 ⟹
   u k := Cexp (0 +i (INR k * θ k))（单位模标量）覆盖 psi-rope 的 2×2 块旋转——
   SO(2) 与 U(1) 同构，维度对 (x1,x2) 上的 [cosθ −sinθ; sinθ cosθ] 即复数乘法
   (x1 + i·x2)·e^{iθ} 的实/虚部（length_extrap.py apply_rope_theta 逐行对应）。 *)
Lemma Cexp_unit_mod (θ : R) : Cnorm_sq (Cexp (0 +i θ)) = 1.
Proof.
  unfold Cexp, Cnorm_sq.
  simpl.
  rewrite exp_0.
  replace (1 * cos θ) with (cos θ) by ring.
  replace (1 * sin θ) with (sin θ) by ring.
  replace (Rsqr (cos θ) + Rsqr (sin θ)) with (Rsqr (sin θ) + Rsqr (cos θ)) by (unfold Rsqr; ring).
  apply sin2_cos2.
Qed.

Theorem unitary_invariance_psi_rope_theta (θ : nat -> R) (vals : list nat)
  (coeffs : list Complex) (n N : nat) :
  l2_norm_sq (fun k => Csum (fun i => Cexp (0 +i (INR k * θ k)) *c (nth i coeffs C0 *c psi (nth i vals 0%nat) k)) n) N
  = l2_norm_sq (fun k => Csum (fun i => nth i coeffs C0 *c psi (nth i vals 0%nat) k) n) N.
Proof.
  apply (unitary_invariance_psi_rope_global vals (fun k => Cexp (0 +i (INR k * θ k)))
           (fun k => Cexp_unit_mod (INR k * θ k)) coeffs n N).
Qed.

End UnitaryInvariance.
Module PhaseCoherence.

Import RowTruncation.
Import SoftmaxStability.
Open Scope R_scope.

(* ---------- list_sum_R 线性（fold_right 展开） ---------- *)

Lemma list_sum_R_plus (f g : nat -> R) (l : list nat) :
  list_sum_R (fun i => f i + g i) l = (list_sum_R f l + list_sum_R g l)%R.
Proof.
  unfold list_sum_R. induction l as [| h t IH]; simpl; [ring | rewrite IH; ring].
Qed.

Lemma list_sum_R_neg (f : nat -> R) (l : list nat) :
  list_sum_R (fun i => - f i) l = (- list_sum_R f l)%R.
Proof.
  unfold list_sum_R. induction l as [| h t IH]; simpl; [ring | rewrite IH; ring].
Qed.

Lemma list_sum_R_scale_l (f : nat -> R) (c : R) (l : list nat) :
  list_sum_R (fun i => c * f i) l = (c * list_sum_R f l)%R.
Proof.
  unfold list_sum_R. induction l as [| h t IH]; simpl; [ring | rewrite IH; ring].
Qed.

Lemma list_sum_R_scale_r (f : nat -> R) (c : R) (l : list nat) :
  list_sum_R (fun i => f i * c) l = (list_sum_R f l * c)%R.
Proof.
  unfold list_sum_R. induction l as [| h t IH]; simpl; [ring | rewrite IH; ring].
Qed.

(* 外延：逐点相等 ⟹ 和相等（不需要全局 funext） *)
Lemma list_sum_R_ext (f g : nat -> R) (l : list nat) :
  (forall i, In i l -> f i = g i) -> list_sum_R f l = list_sum_R g l.
Proof.
  induction l as [| h t IH]; simpl; intro H.
  - reflexivity.
  - rewrite (H h (or_introl (eq_refl h))). rewrite (IH (fun i Hi => H i (or_intror Hi))). reflexivity.
Qed.

(* ---------- 和的绝对三角不等式 ---------- *)

Lemma list_sum_R_abs (f : nat -> R) (l : list nat) :
  (Rabs (list_sum_R f l) <= list_sum_R (fun i => Rabs (f i)) l)%R.
Proof.
  unfold list_sum_R. induction l as [| h t IH]; simpl.
  - rewrite Rabs_R0. apply Rle_refl.
  - apply Rle_trans with (Rabs (f h) + Rabs (fold_right (fun i acc => f i + acc) 0%R t))%R.
    + apply Rabs_triang.
    + apply Rplus_le_compat_l; exact IH.
Qed.

(* ---------- 步骤 1：logit 扰动界 ---------- *)

(* In j (seq 0 n) ⟹ j < n *)
Lemma In_seq_lt (j n : nat) :
  In j (seq 0%nat n) -> (j < n)%nat.
Proof.
  intro Hj.
  destruct (In_nth (seq 0%nat n) j 0%nat Hj) as [k [Hk Hkth]].
  rewrite length_seq in Hk.
  assert (Hkseq : (nth k (seq 0%nat n) 0%nat = k)%nat)
    by (rewrite (@seq_nth n 0%nat k 0%nat Hk); lia).
  rewrite Hkth in Hkseq. lia.
Qed.

(* |z_i - z'_i| <= coh·delta，其中 z_i = Σ_j c_j·K_ij，z'_i = Σ_j c'_j·K_ij *)
Lemma coh_logit_bound (K : nat -> nat -> R) (c c' : nat -> R) (n i : nat)
  (coh delta : R) :
  (i < n)%nat -> (0 <= coh)%R ->
  (forall i0 j, (i0 < n)%nat -> (j < n)%nat -> (Rabs (K i0 j) <= coh)%R) ->
  (list_sum_R (fun j => Rabs (c j - c' j)) (seq 0%nat n) <= delta)%R ->
  (Rabs (list_sum_R (fun j => (c j - c' j) * K i j) (seq 0%nat n)) <= coh * delta)%R.
Proof.
  intros Hi Hcoh HK Hdelta.
  apply Rle_trans with (list_sum_R (fun j => Rabs ((c j - c' j) * K i j)) (seq 0%nat n)).
  - apply list_sum_R_abs.
  - apply Rle_trans with (list_sum_R (fun j => Rabs (c j - c' j) * coh) (seq 0%nat n)).
    + apply list_sum_R_le_compat. intros j0 Hj0.
      rewrite Rabs_mult.
      apply Rmult_le_compat_l.
      * apply Rabs_pos.
      * apply HK; [exact Hi | apply In_seq_lt; exact Hj0].
    + rewrite (list_sum_R_scale_r (fun j => Rabs (c j - c' j)) coh (seq 0%nat n)).
      replace (coh * delta) with (delta * coh)%R by ring.
      apply Rmult_le_compat_r; [exact Hcoh | exact Hdelta].
Qed.

(* ---------- 步骤 2+3：softmax_l1_bound_exp 组合（主定理） ---------- *)

(* 抽象相干-softmax 桥接引理（abstract lemma，评审 12）：参数化于任意相干核 K，
   不绑定 ψ 基或学习投影层——实例化到具体梯子为后续工作。 *)
Theorem coherence_controls_attention (K : nat -> nat -> R) (c c' : nat -> R)
  (n : nat) (coh delta : R) :
  (0 < n)%nat -> (0 <= coh)%R -> (0 <= delta)%R ->
  (forall i j, (i < n)%nat -> (j < n)%nat -> (Rabs (K i j) <= coh)%R) ->
  (list_sum_R (fun j => Rabs (c j - c' j)) (seq 0%nat n) <= delta)%R ->
  (list_sum_R (fun i => Rabs
     (softmax_l (fun i => list_sum_R (fun j => c j * K i j) (seq 0%nat n)) n i
      - softmax_l (fun i => list_sum_R (fun j => c' j * K i j) (seq 0%nat n)) n i))
     (seq 0%nat n) <= exp (2 * (coh * delta)) - 1)%R.
Proof.
  intros Hn Hcoh Hdelta HK Hd.
  (* 1. logit 扰动：|z_i - z'_i| <= coh·delta *)
  assert (Hz : forall i, (i < n)%nat ->
    (Rabs (list_sum_R (fun j => c j * K i j) (seq 0%nat n)
        - list_sum_R (fun j => c' j * K i j) (seq 0%nat n)) <= coh * delta)%R).
  { intros i Hi.
    replace (list_sum_R (fun j => c j * K i j) (seq 0%nat n)
             - list_sum_R (fun j => c' j * K i j) (seq 0%nat n))
      with (list_sum_R (fun j => (c j - c' j) * K i j) (seq 0%nat n)).
    - apply coh_logit_bound; auto.
    - replace (list_sum_R (fun j => c j * K i j) (seq 0%nat n)
               - list_sum_R (fun j => c' j * K i j) (seq 0%nat n))
        with (list_sum_R (fun j => c j * K i j) (seq 0%nat n)
              + (- list_sum_R (fun j => c' j * K i j) (seq 0%nat n)))%R by ring.
      rewrite <- (list_sum_R_neg (fun j => c' j * K i j) (seq 0%nat n)).
      rewrite <- (list_sum_R_plus (fun j => c j * K i j)
                                  (fun j => - (c' j * K i j)) (seq 0%nat n)).
      apply list_sum_R_ext. intros j0 Hj0. ring.
  }
  (* 2. softmax_l1_bound_exp *)
  apply (softmax_l1_bound_exp
           (fun i => list_sum_R (fun j => c j * K i j) (seq 0%nat n))
           (fun i => list_sum_R (fun j => c' j * K i j) (seq 0%nat n))
           n (coh * delta) Hn).
  - apply Rmult_le_pos; auto.
  - intros k Hk. apply Hz. exact Hk.
Qed.


(* ---------- 核漂移链（T4 完全体；z 区 probe_kerneldrift/probe_softmaxtvd 并入 20260-08-22） ---------- *)
(* 口径：固定系数 c × 核漂移 K→K'（长度外推/蒸馏/量化场景），
   与上文 coherence_controls_attention（系数漂移 × 固定核）互补。 *)

Lemma In_seq_lt_coq : forall j n : nat, In j (seq 0%nat n) -> (j < n)%nat.
Proof.
  intros j n Hj.
  destruct (In_nth (seq 0%nat n) j 0%nat Hj) as [k [Hk Hkth]].
  rewrite length_seq in Hk.
  assert (Hkseq : (nth k (seq 0%nat n) 0%nat = k)%nat)
    by (rewrite (@seq_nth n 0%nat k 0%nat Hk); lia).
  rewrite Hkth in Hkseq. lia.
Qed.

(* KD2：logit 层——核逐点漂移 ≤ dc 且系数 ℓ1 ≤ dd ⟹ logit 漂移 ≤ dc·dd *)
Lemma kernel_drift_logit (K K' : nat -> nat -> R) (c : nat -> R)
      (n i : nat) (dc dd : R) :
  (i < n)%nat -> (0 <= dc)%R ->
  (forall i0 j, (i0 < n)%nat -> (j < n)%nat -> (Rabs (K i0 j - K' i0 j) <= dc)%R) ->
  (list_sum_R (fun j => Rabs (c j)) (seq 0%nat n) <= dd)%R ->
  (Rabs (list_sum_R (fun j => c j * K i j) (seq 0%nat n)
          - list_sum_R (fun j => c j * K' i j) (seq 0%nat n)) <= dc * dd)%R.
Proof.
  intros Hi Hdc HK Hdd.
  (* 差 = Σ c_j·(K − K')：三段式组装（Rminus 下藏 Ropp，直接 rewrite 不可见） *)
  assert (Hdiff : (list_sum_R (fun j => c j * K i j) (seq 0%nat n)
                   - list_sum_R (fun j => c j * K' i j) (seq 0%nat n)
                   = list_sum_R (fun j => (c j * K i j + - (c j * K' i j))) (seq 0%nat n))%R).
  { transitivity (list_sum_R (fun j => (c j * K i j + - (c j * K' i j))) (seq 0%nat n)).
    - rewrite (list_sum_R_plus (fun j => c j * K i j) (fun j => - (c j * K' i j)) (seq 0%nat n)).
      rewrite (list_sum_R_neg (fun j => c j * K' i j) (seq 0%nat n)).
      ring.
    - apply list_sum_R_ext. intros j Hj. ring. }
  rewrite Hdiff.
  apply (Rle_trans _ (list_sum_R (fun j => Rabs (c j * K i j - c j * K' i j)) (seq 0%nat n))).
  - apply list_sum_R_abs.
  - apply (Rle_trans _ (list_sum_R (fun j => dc * Rabs (c j)) (seq 0%nat n))).
    + apply list_sum_R_le_compat. intros j Hj.
      assert (Hjn : (j < n)%nat) by (apply In_seq_lt_coq; exact Hj).
      assert (HKj : (Rabs (K i j - K' i j) <= dc)%R) by (apply HK; assumption).
      replace (c j * K i j - c j * K' i j) with (c j * (K i j - K' i j)) by ring.
      rewrite Rabs_mult.
      rewrite (Rmult_comm (Rabs (c j)) (Rabs (K i j - K' i j))).
      apply Rmult_le_compat_r.
      * apply Rabs_pos.
      * exact HKj.
    + rewrite (list_sum_R_scale_l (fun j => Rabs (c j)) dc (seq 0%nat n)).
      apply Rmult_le_compat_l; [exact Hdc | exact Hdd].
Qed.

(* T4 完全体：核漂移 → softmax TVD ≤ e^{2·dc·dd} − 1 *)
Theorem kernel_drift_controls_attention (K K' : nat -> nat -> R)
        (c : nat -> R) (n : nat) (dc dd : R) :
  (0 < n)%nat -> (0 <= dc)%R ->
  (forall i j, (i < n)%nat -> (j < n)%nat -> (Rabs (K i j - K' i j) <= dc)%R) ->
  (list_sum_R (fun j => Rabs (c j)) (seq 0%nat n) <= dd)%R ->
  (list_sum_R (fun i => Rabs
     (softmax_l (fun i0 => list_sum_R (fun j => c j * K i0 j) (seq 0%nat n)) n i
      - softmax_l (fun i0 => list_sum_R (fun j => c j * K' i0 j) (seq 0%nat n)) n i))
     (seq 0%nat n) <= exp (2 * (dc * dd)) - 1)%R.
Proof.
  intros Hn Hdc HK Hdd.
  assert (Hdd0 : (0 <= dd)%R).
  { apply (Rle_trans _ (list_sum_R (fun j => Rabs (c j)) (seq 0%nat n))).
    - apply list_sum_R_pos. intros i _. apply Rabs_pos.
    - exact Hdd. }
  apply (softmax_l1_bound_exp
           (fun i0 => list_sum_R (fun j => c j * K i0 j) (seq 0%nat n))
           (fun i0 => list_sum_R (fun j => c j * K' i0 j) (seq 0%nat n))
           n (dc * dd) Hn).
  - apply Rmult_le_pos; auto.
  - intros k Hk. apply (kernel_drift_logit K K' c n k dc dd); assumption.
Qed.

(* 退化端点：K = K' ⟹ TVD 界 = 0（网格/偏移网格族长度外推核不变的证书端点） *)
Corollary kernel_identical_tvd_zero (K : nat -> nat -> R)
        (c : nat -> R) (n : nat) (dd : R) :
  (0 < n)%nat ->
  (list_sum_R (fun j => Rabs (c j)) (seq 0%nat n) <= dd)%R ->
  (list_sum_R (fun i => Rabs
     (softmax_l (fun i0 => list_sum_R (fun j => c j * K i0 j) (seq 0%nat n)) n i
      - softmax_l (fun i0 => list_sum_R (fun j => c j * K i0 j) (seq 0%nat n)) n i))
     (seq 0%nat n) <= exp (2 * (0 * dd)) - 1)%R.
Proof.
  intros Hn Hdd.
  apply (kernel_drift_controls_attention K K c n 0 dd Hn (Rle_refl 0%R)).
  - intros i j _ _.
    replace (K i j - K i j) with 0%R by ring.
    rewrite Rabs_R0. apply Rle_refl.
  - exact Hdd.
Qed.

End PhaseCoherence.

(* ==================== 模块 29/67: P1Coherence ==================== *)

(* ============================================================
   P1Coherence —— 精确窗口相干下界
   精确窗口口径：coh_T(n,n') = |sin(πd/n')| / (√(nn')·|sin(πd/(nn'))|)，d = n'-n
   P1： d ≤ n'/2、1 ≤ n、n < n' ⟹ coh_T ≥ (2/π)·√(n/n')
        （Jordan 下界 + |sin x| ≤ x 上界；与 P2/P3 保守界口径分层）
   P1'：d ≤ n'/2、1 ≤ n、n < n' ⟹ coh_T ≥ √(n/n')·(1 − π²d²/(6n'²))
        （sin x ≥ x − x³/6）
   意义：近邻大带（如 (216,217)）相干 ≈ 0.997——稠密随机阶梯
   高相干的解析根源。
   纪律：零 Admitted、零自定义公理；仅 Stdlib Reals（自包含）。
   依赖：Stdlib Reals 的 sin_bound（交替级数）、MVT_cor2、cos_decr_1。
   ============================================================ *)
From Stdlib Require Import Reals.
From Stdlib Require Import micromega.Lra.
Open Scope R_scope.

(* ---------- sin 分析引理（纯 Stdlib，不依赖 ca_basis_lemmas） ---------- *)

(* Jordan 不等式：0 ≤ x ≤ π/2 ⟹ (2/π)·x ≤ sin x
   （MVT_cor2 × 2 + cos 在 [0,π] 递减；x=0/π/2 端点单独处理） *)
Lemma jordan_sin_ge (x : R) : 0 <= x -> x <= PI / 2 -> (2 / PI) * x <= sin x.
Proof.
  intros Hx0 Hx2.
  assert (Hpi : 0 < PI) by exact PI_RGT_0.
  destruct (Req_dec x 0) as [Hx0eq | Hx0ne].
  - subst. rewrite sin_0. lra.
  - destruct (Req_dec x (PI / 2)) as [Hx2eq | Hx2ne].
    + subst. rewrite sin_PI2.
      replace (2 / PI * (PI / 2)) with 1 by (field; lra).
      lra.
    + assert (Hx0lt : 0 < x) by lra.
      assert (Hx2lt : x < PI / 2) by lra.
      pose proof (MVT_cor2 sin cos x (PI / 2) Hx2lt (fun c Hc => derivable_pt_lim_sin c)) as [c [HcM Hcin]].
      pose proof (MVT_cor2 sin cos 0 x Hx0lt (fun c Hc => derivable_pt_lim_sin c)) as [d [HdM Hdin]].
      rewrite sin_PI2 in HcM.
      rewrite sin_0 in HdM.
      replace (sin x - 0) with (sin x) in HdM by ring.
      replace (x - 0) with x in HdM by ring.
      assert (Hcos_le : cos c <= cos d).
      { apply cos_decr_1; lra. }
      assert (Hcosc_eq : cos c = (1 - sin x) / (PI / 2 - x)).
      { rewrite HcM. field. lra. }
      assert (Hcosd_eq : cos d = sin x / x).
      { rewrite HdM. field. lra. }
      assert (Hratio : (1 - sin x) / (PI / 2 - x) <= sin x / x).
      { rewrite <- Hcosc_eq, <- Hcosd_eq. exact Hcos_le. }
      assert (Hden : 0 <= (PI / 2 - x) * x) by nra.
      assert (Hmul : ((1 - sin x) / (PI / 2 - x)) * ((PI / 2 - x) * x) <= (sin x / x) * ((PI / 2 - x) * x)).
      { apply Rmult_le_compat_r; [exact Hden | exact Hratio]. }
      assert (Hcross : (1 - sin x) * x <= sin x * (PI / 2 - x)).
      {
        replace ((1 - sin x) / (PI / 2 - x) * ((PI / 2 - x) * x)) with ((1 - sin x) * x) in Hmul by (field; lra).
        replace (sin x / x * ((PI / 2 - x) * x)) with (sin x * (PI / 2 - x)) in Hmul by (field; lra).
        exact Hmul.
      }
      assert (Hxsin : x <= (PI / 2) * sin x).
      { nra. }
      assert (H2pi_pos : 0 <= 2 / PI).
      { apply Rmult_le_pos; [lra | apply Rlt_le, Rinv_0_lt_compat; lra]. }
      assert (Hmul2 : (2 / PI) * x <= (2 / PI) * ((PI / 2) * sin x)).
      { apply Rmult_le_compat_l; [exact H2pi_pos | exact Hxsin]. }
      replace ((2 / PI) * ((PI / 2) * sin x)) with (sin x) in Hmul2 by (field; lra).
      exact Hmul2.
Qed.

(* |sin x| ≤ x 对 0 ≤ x ≤ π/2（P1 分母上界；sin ≥ 0 于 [0,π] ⟹ Rabs = sin） *)
Lemma sin_abs_le_x_half (x : R) : 0 <= x -> x <= PI / 2 -> Rabs (sin x) <= x.
Proof.
  intros Hx0 Hx2.
  assert (Hpi : 0 < PI) by exact PI_RGT_0.
  assert (Hsin_ge : 0 <= sin x) by (apply sin_ge_0; lra).
  rewrite Rabs_pos_eq; [| exact Hsin_ge].
  destruct (Req_dec x 0) as [Hxe | Hxne].
  - subst. rewrite sin_0. lra.
  - apply Rlt_le. apply sin_lt_x. lra.
Qed.

(* P1' 分子下界：x − x³/6 ≤ sin x 对 0 ≤ x ≤ π（sin_bound 交替级数 n=0） *)
Lemma sin_ge_x_minus_x3_6 (x : R) : 0 <= x -> x <= PI -> x - x ^ 3 / 6 <= sin x.
Proof.
  intros Hx0 Hx2.
  pose proof (sin_bound x 0 Hx0 Hx2) as [Hlo _].
  unfold sin_approx in Hlo.
  simpl in Hlo.
  replace (sin_term x 0 + sin_term x 1) with (x - x ^ 3 / 6) in Hlo by (unfold sin_term; simpl; field).
  exact Hlo.
Qed.

(* ---------- 分数不等式（P1 组装） ---------- *)
(* a ≤ A、C ≤ c、全正 ⟹ a/(b·c) ≤ A/(b·C) *)
Lemma frac_le (a A C c b : R) :
  0 < a -> a <= A -> 0 < C -> C <= c -> 0 < c -> 0 < b ->
  a / (b * c) <= A / (b * C).
Proof.
  intros Ha HaA HC HCc Hc Hb.
  assert (HA : 0 < A) by lra.
  assert (HcC : 0 < c * C) by nra.
  apply (Rmult_le_reg_r (c * C) (a / (b * c)) (A / (b * C))).
  - exact HcC.
  - replace ((a / (b * c)) * (c * C)) with (a * C / b) by (field; lra).
    replace ((A / (b * C)) * (c * C)) with (A * c / b) by (field; lra).
    apply (Rmult_le_reg_r b (a * C / b) (A * c / b)); [exact Hb | ].
    replace ((a * C / b) * b) with (a * C) by (field; lra).
    replace ((A * c / b) * b) with (A * c) by (field; lra).
    apply (Rle_trans (a * C) (A * C) (A * c)).
    + apply Rmult_le_compat_r; [lra | exact HaA].
    + apply Rmult_le_compat_l; [lra | exact HCc].
Qed.

(* sqrt(n/n')·sqrt(nn') = n（0 < n、0 < n'） *)
Lemma sqrt_prod (n n' : R) :
  0 < n -> 0 < n' -> sqrt (n / n') * sqrt (n * n') = n.
Proof.
  intros Hn Hn'.
  assert (Hn1 : 0 <= n / n') by (apply Rlt_le; apply Rdiv_lt_0_compat; lra).
  assert (Hn2 : 0 <= n * n') by nra.
  assert (Hm : sqrt (n / n' * (n * n')) = sqrt (n / n') * sqrt (n * n')).
  { apply sqrt_mult; [exact Hn1 | exact Hn2]. }
  assert (Hnn : (n / n') * (n * n') = n * n) by (field; lra).
  rewrite <- Hm.
  rewrite Hnn.
  apply sqrt_square. lra.
Qed.

(* 代数化简：(2/π)·√(n/n') = (2·d/n')/(√(nn')·(πd/(nn'))) *)
Lemma p1_algebra (n n' d : R) :
  0 < n -> 0 < n' -> 0 < d ->
  (2 / PI) * sqrt (n / n') =
  (2 * d / n') / (sqrt (n * n') * (PI * d / (n * n'))).
Proof.
  intros Hn Hn' Hd.
  assert (Hpi : PI <> 0) by (apply Rgt_not_eq; exact PI_RGT_0).
  assert (Hsn : sqrt (n * n') <> 0).
  { apply Rgt_not_eq. apply sqrt_lt_R0. nra. }
  assert (Hn'0 : n' <> 0) by lra.
  assert (Hdiv : sqrt (n / n') = n / sqrt (n * n')).
  {
    apply (Rmult_eq_reg_l (sqrt (n * n')) (sqrt (n / n')) (n / sqrt (n * n'))).
    - rewrite Rmult_comm.
      rewrite (sqrt_prod n n' Hn Hn').
      field. lra.
    - exact Hsn.
  }
  rewrite Hdiv.
  field.
  repeat split; auto; lra.
Qed.

(* ---------- P1 主定理 ---------- *)
(* 相干公式：coh_T(n,n') = |sin(πd/n')| / (√(nn')·|sin(πd/(nn'))|)，d = n'-n *)
Definition coh_T (n n' : R) : R :=
  Rabs (sin (PI * (n' - n) / n')) /
  (sqrt (n * n') * Rabs (sin (PI * (n' - n) / (n * n')))).

(* 分母上界：|sin(πd/(nn'))| ≤ πd/(nn')，前提 0 < πd/(nn') ≤ π/2（1 ≤ n 保 2d ≤ nn'） *)
Lemma den_bound (n n' d : R) :
  0 < PI -> 1 <= n -> 0 < n -> 0 < n' -> 0 < d -> d <= n' / 2 ->
  Rabs (sin (PI * d / (n * n'))) <= PI * d / (n * n').
Proof.
  intros Hpi Hn1 Hn Hn' Hd Hdle.
  apply sin_abs_le_x_half.
  - (* 0 <= PI*d/(nn') *)
    apply Rlt_le.
    apply Rdiv_lt_0_compat; [| nra].
    apply Rmult_lt_0_compat; [exact Hpi | lra].
  - (* PI*d/(nn') <= PI/2：d <= n'/2 <= n·n'/2（1 ≤ n）⟹ 乘 π>0、除 (nn')>0 *)
    assert (Hdle2 : d <= n * n' / 2).
    {
      apply (Rle_trans d (n' / 2) (n * n' / 2)).
      - exact Hdle.
      - unfold Rdiv.
        apply (Rmult_le_compat_r (/ 2) n' (n * n')); [lra | ].
        nra.
    }
    assert (Hmul2 : PI * d <= PI * (n * n' / 2)).
    { apply Rmult_le_compat_l; [lra | exact Hdle2]. }
    assert (Hden2 : 0 < n * n') by nra.
    unfold Rdiv.
    apply (Rmult_le_reg_r (n * n') (PI * d * / (n * n')) (PI / 2)); [exact Hden2 | ].
    replace ((PI * d * / (n * n')) * (n * n')) with (PI * d) by (field; nra).
    replace ((PI / 2) * (n * n')) with (PI * n * n' / 2) by (field; nra).
    apply (Rle_trans (PI * d) (PI * (n * n' / 2)) (PI * n * n' / 2)); [exact Hmul2 | ].
    replace (PI * (n * n' / 2)) with (PI * n * n' / 2) by (field; lra).
    reflexivity.
Qed.

(* 分母正：|sin(πd/(nn'))| > 0，前提 0 < πd/(nn') < π（d < n' 保 d < n·n'） *)
Lemma den_pos (n n' d : R) :
  0 < PI -> 1 <= n -> 0 < n' -> 0 < d -> d < n' ->
  0 < Rabs (sin (PI * d / (n * n'))).
Proof.
  intros Hpi Hn1 Hn' Hd Hdlt.
  assert (Harg0 : 0 < PI * d / (n * n')).
  {
    apply Rdiv_lt_0_compat; [| nra].
    apply Rmult_lt_0_compat; [exact Hpi | lra].
  }
  assert (Hargpi : PI * d / (n * n') < PI).
  {
    (* d < n' ≤ n·n'（1 ≤ n）⟹ πd/(nn') < π *)
    apply Rmult_lt_reg_r with (n * n'); [nra | ].
    replace (PI * d / (n * n') * (n * n')) with (PI * d) by (field; nra).
    apply Rmult_lt_compat_l; [lra | ].
    (* d < n·n'：d < n' ≤ n·n' *)
    assert (Hdlt' : d < n') by lra.
    assert (Hnle : n' <= n * n').
    { nra. }
    lra.
  }
  assert (Hsp : 0 < sin (PI * d / (n * n'))) by (apply sin_gt_0; [lra | exact Hargpi]).
  rewrite Rabs_pos_eq; lra.
Qed.

(* P1：0 < n、1 ≤ n、n < n'、d = n'-n ≤ n'/2 ⟹ coh_T ≥ (2/π)·√(n/n') *)
Theorem p1_coherence_lower (n n' : R) :
  1 <= n -> n < n' -> n' - n <= n' / 2 ->
  (2 / PI) * sqrt (n / n') <= coh_T n n'.
Proof.
  intros Hn1 Hnn' Hd.
  assert (Hpi : 0 < PI) by exact PI_RGT_0.
  assert (Hn : 0 < n) by lra.
  assert (Hn' : 0 < n') by lra.
  set (d := n' - n).
  assert (Hdpos : 0 < d) by (unfold d; lra).
  (* 分子下界：2d/n' ≤ |sin(πd/n')| *)
  assert (Hnum : 2 * d / n' <= Rabs (sin (PI * d / n'))).
  {
    assert (Hx0 : 0 < PI * d / n').
    {
      apply Rdiv_lt_0_compat; [| exact Hn'].
      apply Rmult_lt_0_compat; [exact Hpi | unfold d; lra].
    }
    assert (Hxpi : PI * d / n' <= PI / 2).
    {
      assert (Hmul2 : PI * d <= PI * (n' / 2)).
      { apply Rmult_le_compat_l; [lra | unfold d; lra]. }
      apply (Rmult_le_reg_r n' (PI * d / n') (PI / 2)); [exact Hn' | ].
      replace ((PI * d / n') * n') with (PI * d) by (field; nra).
      replace ((PI / 2) * n') with (PI * (n' / 2)) by (field; nra).
      exact Hmul2.
    }
    pose proof (jordan_sin_ge (PI * d / n') (Rlt_le _ _ Hx0) Hxpi) as Hj.
    assert (Hsin_ge : 0 <= sin (PI * d / n')).
    {
      apply sin_ge_0.
      - exact (Rlt_le _ _ Hx0).
      - apply (Rle_trans (PI * d / n') (PI / 2) PI); [exact Hxpi | lra].
    }
    rewrite Rabs_pos_eq; [| exact Hsin_ge].
    replace ((2 / PI) * (PI * d / n')) with (2 * d / n') in Hj by (field; nra).
    exact Hj.
  }
  (* 分母上界 + 分母正（顶层引理） *)
  assert (Hden : Rabs (sin (PI * d / (n * n'))) <= PI * d / (n * n')).
  { apply den_bound; unfold d; lra. }
  assert (Hcpos : 0 < Rabs (sin (PI * d / (n * n')))).
  { apply den_pos; unfold d; lra. }  (* 组装：frac_le a:=2d/n' A:=|sin(πd/n')| C:=|sin(πd/(nn'))| c:=πd/(nn') b:=√(nn') *)
  assert (Hfl : (2 * d / n') / (sqrt (n * n') * (PI * d / (n * n')))
           <= Rabs (sin (PI * d / n')) / (sqrt (n * n') * Rabs (sin (PI * d / (n * n'))))).
  {
    apply frac_le.
    - apply Rdiv_lt_0_compat; [nra | exact Hn'].
    - exact Hnum.
    - exact Hcpos.
    - exact Hden.
    - apply Rdiv_lt_0_compat; [nra | nra].
    - apply sqrt_lt_R0; nra.
  }
  (* 代数：左边 = (2/π)·√(n/n') *)
  rewrite (p1_algebra n n' d Hn Hn' Hdpos).
  exact Hfl.
Qed.

(* ---------- P1' 精细版 ---------- *)
(* 分子下界：(πd/n')·(1 − π²d²/(6n'²)) ≤ |sin(πd/n')| *)
Lemma p1prime_num (n n' d : R) :
  0 < PI -> 0 < n -> 0 < n' -> 0 < d -> d <= n' / 2 ->
  (PI * d / n') * (1 - PI ^ 2 * d ^ 2 / (6 * n' ^ 2)) <=
  Rabs (sin (PI * d / n')).
Proof.
  intros Hpi Hn Hn' Hdpos Hdle.
  assert (Hx0 : 0 <= PI * d / n').
  { apply Rlt_le. apply Rdiv_lt_0_compat; [| exact Hn']. apply Rmult_lt_0_compat; [exact Hpi | lra]. }
  (* PI*d/n' <= PI/2（d <= n'/2）⟹ <= PI *)
  assert (Hxpi2 : PI * d / n' <= PI / 2).
  {
    assert (Hmul2 : PI * d <= PI * (n' / 2)).
    { apply Rmult_le_compat_l; [lra | exact Hdle]. }
    apply (Rmult_le_reg_r n' (PI * d / n') (PI / 2)); [exact Hn' | ].
    replace ((PI * d / n') * n') with (PI * d) by (field; nra).
    replace ((PI / 2) * n') with (PI * (n' / 2)) by (field; nra).
    exact Hmul2.
  }
  assert (Hxpi : PI * d / n' <= PI) by (apply (Rle_trans (PI * d / n') (PI / 2) PI); [exact Hxpi2 | lra]).
  pose proof (sin_ge_x_minus_x3_6 (PI * d / n') Hx0 Hxpi) as Hs.
  assert (Hsin_ge : 0 <= sin (PI * d / n')).
  {
    apply sin_ge_0.
    - exact Hx0.
    - exact Hxpi.
  }
  rewrite Rabs_pos_eq; [| exact Hsin_ge].
  replace (PI * d / n' - (PI * d / n') ^ 3 / 6)
    with ((PI * d / n') * (1 - PI ^ 2 * d ^ 2 / (6 * n' ^ 2))) in Hs by (field; nra).
  exact Hs.
Qed.

(* P1'：d ≤ n'/2 ⟹ coh_T ≥ √(n/n')·(1 − π²d²/(6n'²)) *)
Theorem p1_prime_coherence_lower (n n' : R) :
  1 <= n -> n < n' -> n' - n <= n' / 2 ->
  sqrt (n / n') * (1 - PI ^ 2 * (n' - n) ^ 2 / (6 * n' ^ 2)) <= coh_T n n'.
Proof.
  intros Hn1 Hnn' Hd.
  assert (Hpi : 0 < PI) by exact PI_RGT_0.
  assert (Hn : 0 < n) by lra.
  assert (Hn' : 0 < n') by lra.
  set (d := n' - n).
  assert (Hdpos : 0 < d) by (unfold d; lra).
  (* 分母上界 + 分母正 *)
  assert (Hden : Rabs (sin (PI * d / (n * n'))) <= PI * d / (n * n')).
  { apply den_bound; unfold d; lra. }
  assert (Hcpos : 0 < Rabs (sin (PI * d / (n * n')))).
  { apply den_pos; unfold d; lra. }  (* 分子下界（P1' 版） *)
  assert (Hnum : (PI * d / n') * (1 - PI ^ 2 * d ^ 2 / (6 * n' ^ 2)) <= Rabs (sin (PI * d / n'))).
  {
    apply (p1prime_num n n' d Hpi Hn Hn' Hdpos).
    unfold d. lra.
  }
  (* 组装 *)
  assert (Hfl : ((PI * d / n') * (1 - PI ^ 2 * d ^ 2 / (6 * n' ^ 2))) /
                  (sqrt (n * n') * (PI * d / (n * n')))
           <= Rabs (sin (PI * d / n')) / (sqrt (n * n') * Rabs (sin (PI * d / (n * n'))))).
  {
    apply frac_le.
    - (* a > 0：需 1 − π²d²/(6n'²) > 0，用 π ≤ 4 与 d ≤ n'/2 *)
      assert (Hpi4 : PI <= 4) by exact PI_4.
      assert (Hmain : 0 < (PI * d / n') * (1 - PI ^ 2 * d ^ 2 / (6 * n' ^ 2))).
      {
        apply Rmult_lt_0_compat.
        - apply Rdiv_lt_0_compat; [nra | exact Hn'].
        - (* 1 - π²d²/(6n'²) > 0 ⟺ π²d² < 6n'²；π≤4、d≤n'/2 ⟹ π²d² ≤ 4n'² < 6n'² *)
          assert (Hd2 : PI ^ 2 * d ^ 2 <= 4 * n' ^ 2).
          {
            assert (Hpi2 : PI ^ 2 <= 16).
            {
              replace (PI ^ 2) with (PI * PI) by (unfold pow; ring).
              replace 16 with (4 * 4) by ring.
              apply Rmult_le_compat; [lra | lra | exact Hpi4 | exact Hpi4].
            }
            assert (Hd' : d ^ 2 <= (n' / 2) ^ 2).
            {
              replace (d ^ 2) with (d * d) by (unfold pow; ring).
              replace ((n' / 2) ^ 2) with ((n' / 2) * (n' / 2)) by (unfold pow; ring).
              apply Rmult_le_compat; [lra | lra | | ].
              - unfold d. lra.
              - unfold d. lra.
            }
            assert (Hpd : PI ^ 2 * d ^ 2 <= 16 * (n' / 2) ^ 2).
            { apply Rmult_le_compat; [apply pow_le; lra | apply pow_le; lra | exact Hpi2 | exact Hd']. }
            replace (16 * (n' / 2) ^ 2) with (4 * n' ^ 2) in Hpd by (field; nra).
            exact Hpd.
          }
          assert (Hlt : 4 * n' ^ 2 < 6 * n' ^ 2) by nra.
          (* π²d²/(6n'²) < 1 ⟸ π²d² < 6n'²（分母正） *)
          assert (Hnumlt : PI ^ 2 * d ^ 2 / (6 * n' ^ 2) < 1).
          {
            apply (Rmult_lt_reg_r (6 * n' ^ 2) (PI ^ 2 * d ^ 2 / (6 * n' ^ 2)) 1); [nra | ].
            replace (PI ^ 2 * d ^ 2 / (6 * n' ^ 2) * (6 * n' ^ 2)) with (PI ^ 2 * d ^ 2) by (field; nra).
            replace (1 * (6 * n' ^ 2)) with (6 * n' ^ 2) by ring.
            apply (Rle_lt_trans (PI ^ 2 * d ^ 2) (4 * n' ^ 2) (6 * n' ^ 2));
              [exact Hd2 | exact Hlt].
          }
          lra.
      }
      exact Hmain.
    - exact Hnum.
    - exact Hcpos.
    - exact Hden.
    - unfold d; nra.
    - apply sqrt_lt_R0; nra.
  }
  (* 代数：左边化简 = √(n/n')·(1 − π²d²/(6n'²)) *)
  assert (Halg : ((PI * d / n') * (1 - PI ^ 2 * d ^ 2 / (6 * n' ^ 2))) /
                   (sqrt (n * n') * (PI * d / (n * n'))) =
                 sqrt (n / n') * (1 - PI ^ 2 * d ^ 2 / (6 * n' ^ 2))).
  {
    assert (Hpi' : PI <> 0) by (apply Rgt_not_eq; exact PI_RGT_0).
    assert (Hsn : sqrt (n * n') <> 0).
    { apply Rgt_not_eq. apply sqrt_lt_R0. nra. }
    assert (Hn'0 : n' <> 0) by lra.
    assert (Hd0 : d <> 0) by lra.
    assert (Hnn'0 : n * n' <> 0) by nra.
    assert (Hdiv : sqrt (n / n') = n / sqrt (n * n')).
    {
      apply (Rmult_eq_reg_l (sqrt (n * n')) (sqrt (n / n')) (n / sqrt (n * n'))).
      - rewrite Rmult_comm.
        rewrite (sqrt_prod n n' Hn Hn').
        field. lra.
      - exact Hsn.
    }
    rewrite Hdiv.
    field.
    repeat split; auto; lra.
  }
  rewrite Halg in Hfl.
  unfold d in Hfl.
  exact Hfl.
Qed.

(* ==================== 模块 30/67: ParetoLaw ==================== *)

(* ============================================================
   ParetoLaw —— 帕累托律（可证明性边界）
   定理：P2 若阶梯含一对 (n,n') 满足 d = n'-n < (5/8)·√(n·n')，
         则保守对界 B(n,n') = √(nn')/(2d) > 4/5 ⟹ 该行行和 > 4/5 ⟹ 检查器拒绝。
   定理：P3（增长引理）若相邻带 n < n' 不触发 P2（B(n,n') ≤ 4/5），
         则 n' ≥ c·n，c = ((5+√281)/16)² = (153+5√281)/128 ≈ 1.8501（几何增长）。
   定理：P3（完整主定理，鸽笼）m 个相完备带 f 0 < ... < f (m-1) ≤ N 且检查器通过
         ⟹ 3·c^(m-1) ≤ N。推论：N=511 时 m ≥ 10 个带必被检查器拒绝。
   纪律：零 Admitted、零自定义公理；仅 Stdlib Reals（自包含）。
   ============================================================ *)
From Stdlib Require Import Reals.
From Stdlib Require Import micromega.Lra.
From Stdlib Require Import Lia.
Open Scope R_scope.

(* ---------- 辅助：正数乘除法不等式 ---------- *)

Lemma lt_div_lt (r1 r2 r3 : R) : 0 < r3 -> r1 * r3 < r2 -> r1 < r2 / r3.
Proof.
  intros H3 H.
  unfold Rdiv.
  assert (Hinv : 0 < / r3) by (apply Rinv_0_lt_compat; exact H3).
  apply (Rmult_lt_compat_r (/ r3) (r1 * r3) r2 Hinv) in H.
  replace ((r1 * r3) * / r3) with r1 in H by (field; nra).
  exact H.
Qed.

(* ---------- 保守对界（window 无关，有理松弛版） ---------- *)

Definition pair_bound (n n' : R) : R := sqrt (n * n') / (2 * (n' - n)).

(* ---------- P2：单对触发引理 ---------- *)

(* B(n,n') > 4/5 当且仅当 d < (5/8)·√(nn')（d = n'-n） *)
Lemma pair_bound_gt_4_5 (n n' : R) :
  0 < n -> 0 < n' - n ->
  (n' - n) < (5/8) * sqrt (n * n') ->
  4/5 < pair_bound n n'.
Proof.
  intros Hn Hd Hlt.
  assert (Hsq : 0 < sqrt (n * n')).
  { apply sqrt_lt_R0. nra. }
  assert (H2d : 0 < 2 * (n' - n)) by nra.
  assert (Hm : (8/5) * (n' - n) < sqrt (n * n')).
  { replace (sqrt (n * n')) with ((8/5) * ((5/8) * sqrt (n * n'))) by field.
    apply Rmult_lt_compat_l; [nra | exact Hlt]. }
  unfold pair_bound.
  apply lt_div_lt; [exact H2d | ].
  replace ((4/5) * (2 * (n' - n))) with ((8/5) * (n' - n)) by field.
  exact Hm.
Qed.

(* ---------- P3：几何增长引理 ---------- *)

(* 子引理①：(√281)² = 281（乘法形式，供 field [sqrt281_sq] 作为环关系） *)
Lemma sqrt281_sq : sqrt 281 * sqrt 281 = 281.
Proof. apply sqrt_sqrt. nra. Qed.

(* 子引理②：√281 > 5（反证：√281 ≤ 5 平方得 281 ≤ 25 矛盾） *)
Lemma sqrt281_gt_5 : 5 < sqrt 281.
Proof.
  apply Rnot_le_lt.
  intro Hle.
  assert (Hsq : sqrt 281 * sqrt 281 <= 5 * 5).
  { apply (Rmult_le_compat (sqrt 281) 5 (sqrt 281) 5); [apply sqrt_pos | apply sqrt_pos | exact Hle | exact Hle]. }
  rewrite sqrt281_sq in Hsq.
  nra.
Qed.

(* 二次式两根（论文记号）：64n'² − 153nn' + 64n² = 64·(n'−r_hi·n)·(n'−r_lo·n) *)
Definition r_lo : R := (153 - 5 * sqrt 281) / 128.
Definition r_hi : R := (153 + 5 * sqrt 281) / 128.

(* 帕累托几何增长常数 c = ((5+√281)/16)² = r_hi ≈ 1.8501 *)
Definition c_pareto : R := ((5 + sqrt 281) / 16) ^ 2.

(* 子引理③：r_lo < 1（⟺ 25 < 5√281 ⟺ 5 < √281） *)
Lemma r_lo_lt_1 : r_lo < 1.
Proof.
  unfold r_lo.
  apply (Rmult_lt_reg_l 128 ((153 - 5 * sqrt 281) / 128) 1); [nra | ].
  replace (128 * ((153 - 5 * sqrt 281) / 128)) with (153 - 5 * sqrt 281) by (field; nra).
  assert (H5 : 5 < sqrt 281) by exact sqrt281_gt_5.
  nra.
Qed.

(* 子引理④：因式分解（field 以 sqrt281_sq 为环关系，避免 (√281)² 展开） *)
Lemma factor_quad (n n' : R) :
  64 * n' ^ 2 - 153 * n * n' + 64 * n ^ 2 =
  64 * (n' - r_hi * n) * (n' - r_lo * n).
Proof.
  unfold r_lo, r_hi.
  field [sqrt281_sq].
Qed.

(* 子引理⑤：c = r_hi 的闭式恒等 *)
Lemma c_pareto_eq_r_hi : c_pareto = r_hi.
Proof.
  unfold c_pareto, r_hi.
  field [sqrt281_sq].
Qed.

(* ---------- P3 主引理：几何增长 ---------- *)
(* B(n,n') ≤ 4/5（不触发 P2）且 0 < n < n' ⟹ n' ≥ c·n。
   证明路线：B ≤ 4/5 ⟹ √(nn') ≤ (8/5)(n'−n)（乘 2d>0）
     ⟹ 平方（非负）nn' ≤ (64/25)(n'−n)² ⟹ 0 ≤ 64n'²−153nn'+64n²
     ⟹ 因式分解 0 ≤ 64(n'−r_lo·n)(n'−r_hi·n)
     ⟹ (n'−r_lo·n) > 0（r_lo<1，n'>n）⟹ n'−r_hi·n ≥ 0 ⟹ n' ≥ c·n。 *)
Lemma pair_bound_le_4_5_geometric (n n' : R) :
  0 < n -> n < n' ->
  pair_bound n n' <= 4/5 ->
  c_pareto * n <= n'.
Proof.
  intros Hn Hlt Hbound.
  unfold pair_bound in Hbound.
  assert (H2d : 0 < 2 * (n' - n)) by nra.
  (* 1) √(nn') ≤ (8/5)(n'−n) *)
  assert (Hsq_le : sqrt (n * n') <= (8/5) * (n' - n)).
  {
    assert (Hmul : 2 * (n' - n) * (sqrt (n * n') / (2 * (n' - n))) <= 2 * (n' - n) * (4/5)).
    { apply Rmult_le_compat_l; [nra | exact Hbound]. }
    replace (2 * (n' - n) * (sqrt (n * n') / (2 * (n' - n)))) with (sqrt (n * n')) in Hmul by (field; nra).
    replace (2 * (n' - n) * (4/5)) with ((8/5) * (n' - n)) in Hmul by field.
    exact Hmul.
  }
  (* 2) 平方（乘法形式，避开 pow 记号与 Rsqr_incr_1 的不匹配） *)
  assert (Hnp : 0 < n') by nra.
  assert (Hnn : 0 < n * n') by (apply Rmult_lt_0_compat; [exact Hn | exact Hnp]).
  assert (Hnn0 : 0 <= n * n') by (apply Rlt_le; exact Hnn).
  assert (H8d : 0 <= (8/5) * (n' - n)) by nra.
  assert (Hsqr_mul : sqrt (n * n') * sqrt (n * n') <= ((8/5) * (n' - n)) * ((8/5) * (n' - n))).
  { apply (Rmult_le_compat (sqrt (n * n')) ((8/5) * (n' - n)) (sqrt (n * n')) ((8/5) * (n' - n)));
      [apply sqrt_pos | apply sqrt_pos | exact Hsq_le | exact Hsq_le]. }
  assert (Hsqr' : n * n' <= (64/25) * (n' - n) ^ 2).
  {
    assert (Hl : n * n' <= ((8/5) * (n' - n)) * ((8/5) * (n' - n))).
    { rewrite (sqrt_sqrt (n * n') Hnn0) in Hsqr_mul. exact Hsqr_mul. }
    replace (((8/5) * (n' - n)) * ((8/5) * (n' - n))) with ((64/25) * (n' - n) ^ 2) in Hl by field.
    exact Hl.
  }
  (* 3) 二次式 0 ≤ 64n'² − 153nn' + 64n² *)
  assert (H25 : 25 * (n * n') <= 25 * ((64/25) * ((n' - n) ^ 2))).
  { apply Rmult_le_compat_l; [nra | exact Hsqr']. }
  replace (25 * ((64/25) * ((n' - n) ^ 2))) with (64 * ((n' - n) ^ 2)) in H25 by (field; nra).
  assert (Hsub : 25 * (n * n') - 64 * ((n' - n) ^ 2) <= 0).
  { apply Rle_minus. exact H25. }
  assert (Hquad : 0 <= 64 * n' ^ 2 - 153 * n * n' + 64 * n ^ 2).
  {
    apply Ropp_le_cancel.
    replace (- (64 * n' ^ 2 - 153 * n * n' + 64 * n ^ 2)) with (25 * (n * n') - 64 * ((n' - n) ^ 2)) by ring.
    rewrite Ropp_0.
    exact Hsub.
  }
  (* 4) 因式分解：0 ≤ 64·(n'−r_lo·n)·(n'−r_hi·n) *)
  rewrite factor_quad in Hquad.
  assert (Hprod : 0 <= (n' - r_lo * n) * (n' - r_hi * n)).
  {
    apply (Rmult_le_reg_l 64 0 ((n' - r_lo * n) * (n' - r_hi * n))); [nra | ].
    rewrite Rmult_0_r.
    replace (64 * ((n' - r_lo * n) * (n' - r_hi * n))) with (64 * (n' - r_hi * n) * (n' - r_lo * n)) by ring.
    exact Hquad.
  }
  (* 5) n' − r_lo·n > 0（r_lo < 1 ⟹ (1−r_lo)·n ≥ 0，且 n'−n > 0） *)
  assert (Halo : 0 < n' - r_lo * n).
  {
    assert (Hrlo1 : r_lo < 1) by exact r_lo_lt_1.
    assert (Hpart : 0 <= (1 - r_lo) * n).
    { apply Rmult_le_pos; [nra | apply Rlt_le; exact Hn]. }
    replace (n' - r_lo * n) with ((n' - n) + (1 - r_lo) * n) by ring.
    nra.
  }
  (* 6) n' − r_hi·n ≥ 0（正因子消去） *)
  assert (Hhi : 0 <= n' - r_hi * n).
  {
    apply (Rmult_le_reg_l (n' - r_lo * n) 0 (n' - r_hi * n)); [exact Halo | ].
    rewrite Rmult_0_r.
    exact Hprod.
  }
  (* 7) 结论：c·n ≤ n'（c = r_hi） *)
  rewrite c_pareto_eq_r_hi.
  nra.
Qed.

(* ---------- P3 完整主定理（鸽笼/几何增长序列） ---------- *)

(* 辅助：c > 0（增长引理与主定理的乘子非负前提） *)
Lemma c_pareto_pos : 0 < c_pareto.
Proof.
  unfold c_pareto.
  assert (Hn : 0 < (5 + sqrt 281) / 16).
  {
    assert (Hs : 0 <= sqrt 281) by apply sqrt_pos.
    assert (Hsum : 0 < 5 + sqrt 281) by nra.
    assert (H16 : 0 < 16) by nra.
    apply (Rmult_lt_reg_l 16 0 ((5 + sqrt 281) / 16)); [exact H16 | ].
    rewrite Rmult_0_r.
    replace (16 * ((5 + sqrt 281) / 16)) with (5 + sqrt 281) by (field; nra).
    exact Hsum.
  }
  replace (((5 + sqrt 281) / 16) ^ 2) with (((5 + sqrt 281) / 16) * ((5 + sqrt 281) / 16)) by (unfold pow; ring).
  apply Rmult_lt_0_compat; [exact Hn | exact Hn].
Qed.

(* 几何增长序列：x_{k+1} ≥ c·x_k（k=0..m-2）⟹ x_{m-1} ≥ c^(m-1)·x_0 *)
Lemma geom_growth (f : nat -> R) (m : nat) :
  (forall (k : nat), (k + 1 < m)%nat -> c_pareto * f k <= f (S k)) ->
  c_pareto ^ (Nat.pred m) * f O <= f (Nat.pred m).
Proof.
  induction m as [| m' IH].
  - assert (Hp : Nat.pred 0 = 0%nat) by reflexivity.
    rewrite Hp. rewrite pow_O. rewrite Rmult_1_l. reflexivity.
  - destruct m' as [| m''].
    + assert (Hp : Nat.pred 1 = 0%nat) by reflexivity.
      rewrite Hp. rewrite pow_O. rewrite Rmult_1_l. reflexivity.
    + intros Hstep.
      assert (Hp : Nat.pred (S (S m'')) = S m'') by reflexivity.
      rewrite Hp.
      assert (Hpow : c_pareto ^ S m'' = c_pareto * c_pareto ^ m'').
      { symmetry. exact (tech_pow_Rmult c_pareto m''). }
      rewrite Hpow.
      assert (HIH : c_pareto ^ m'' * f O <= f m'').
      { apply IH. intros k Hk. apply Hstep. lia. }
      assert (Hlast : c_pareto * f m'' <= f (S m'')).
      { apply Hstep. lia. }
      rewrite Rmult_assoc.
      apply (Rle_trans (c_pareto * (c_pareto ^ m'' * f O)) (c_pareto * f m'') (f (S m''))).
      * apply Rmult_le_compat_l; [apply Rlt_le; exact c_pareto_pos | exact HIH].
      * exact Hlast.
Qed.

(* 递增序列 ⟹ 每项 ≥ 首项 *)
Lemma incr_ge_first (f : nat -> R) (m : nat) :
  (forall (k : nat), (k + 1 < m)%nat -> f k < f (S k)) ->
  forall (k : nat), (k < m)%nat -> f O <= f k.
Proof.
  intros Hinc k. induction k as [| k' IHk]; intros Hk.
  - apply Rle_refl.
  - apply (Rle_trans (f O) (f k') (f (S k'))).
    + apply IHk. lia.
    + apply Rlt_le. apply Hinc. lia.
Qed.

(* P3 完整主定理：m 个相完备带 f 0 < ... < f (m-1) ≤ N，检查器通过 ⟹ 3·c^(m-1) ≤ N *)
Theorem pareto_law_main (f : nat -> R) (m : nat) (N : R) :
  (1 <= m)%nat ->
  3 <= f O ->
  (forall (k : nat), (k + 1 < m)%nat -> f k < f (S k)) ->
  (forall (k : nat), (k + 1 < m)%nat -> pair_bound (f k) (f (S k)) <= 4/5) ->
  f (Nat.pred m) <= N ->
  3 * c_pareto ^ (Nat.pred m) <= N.
Proof.
  intros Hm Hf0 Hinc Hpass Htop.
  assert (Hg : forall (k : nat), (k + 1 < m)%nat -> c_pareto * f k <= f (S k)).
  { intros k Hk.
    apply pair_bound_le_4_5_geometric.
    - assert (Hf0pos : 0 < f O) by nra.
      assert (Hge : f O <= f k) by (apply incr_ge_first with (m := m); [exact Hinc | lia]).
      nra.
    - exact (Hinc k Hk).
    - exact (Hpass k Hk). }
  assert (Hgeom : c_pareto ^ (Nat.pred m) * f O <= f (Nat.pred m)).
  { apply geom_growth. exact Hg. }
  assert (Hpow : 0 <= c_pareto ^ (Nat.pred m)).
  { apply pow_le. apply Rlt_le. exact c_pareto_pos. }
  assert (Hprod : 3 * c_pareto ^ (Nat.pred m) <= c_pareto ^ (Nat.pred m) * f O).
  {
    rewrite Rmult_comm.
    apply (Rmult_le_compat_l (c_pareto ^ (Nat.pred m)) 3 (f O)); [exact Hpow | nra].
  }
  apply (Rle_trans (3 * c_pareto ^ (Nat.pred m)) (c_pareto ^ (Nat.pred m) * f O) N).
  - exact Hprod.
  - apply (Rle_trans (c_pareto ^ (Nat.pred m) * f O) (f (Nat.pred m)) N Hgeom Htop).
Qed.

(* ---------- P3 推论：N=511 时 m ≥ 10 必拒 ---------- *)

(* 辅助：√281 > 16.7（c 的有理下界） *)
Lemma sqrt281_gt_167_10 : 167 / 10 < sqrt 281.
Proof.
  apply Rnot_le_lt.
  intro Hle.
  assert (Hsq : sqrt 281 * sqrt 281 <= (167/10) * (167/10)).
  { apply (Rmult_le_compat (sqrt 281) (167/10) (sqrt 281) (167/10));
      [apply sqrt_pos | apply sqrt_pos | exact Hle | exact Hle]. }
  assert (H281 : 0 <= 281) by nra.
  rewrite (sqrt_sqrt 281 H281) in Hsq.
  nra.
Qed.

(* 辅助：√281 > 11（c > 1） *)
Lemma sqrt281_gt_11 : 11 < sqrt 281.
Proof.
  apply Rnot_le_lt.
  intro Hle.
  assert (Hsq : sqrt 281 * sqrt 281 <= 11 * 11).
  { apply (Rmult_le_compat (sqrt 281) 11 (sqrt 281) 11);
      [apply sqrt_pos | apply sqrt_pos | exact Hle | exact Hle]. }
  assert (H281 : 0 <= 281) by nra.
  rewrite (sqrt_sqrt 281 H281) in Hsq.
  nra.
Qed.

(* 辅助：c > 1（幂单调 c^k 随 k 不减） *)
Lemma c_gt_1 : 1 < c_pareto.
Proof.
  unfold c_pareto.
  assert (Hh : 1 < (5 + sqrt 281) / 16).
  {
    apply (Rmult_lt_reg_l 16 1 ((5 + sqrt 281) / 16)); [nra | ].
    replace (16 * 1) with 16 by ring.
    replace (16 * ((5 + sqrt 281) / 16)) with (5 + sqrt 281) by (field; nra).
    assert (H11 : 11 < sqrt 281) by exact sqrt281_gt_11.
    nra.
  }
  replace (((5 + sqrt 281) / 16) ^ 2) with (((5 + sqrt 281) / 16) * ((5 + sqrt 281) / 16)) by (unfold pow; ring).
  apply (Rlt_trans 1 (1 * ((5 + sqrt 281) / 16)) (((5 + sqrt 281) / 16) * ((5 + sqrt 281) / 16))).
  - rewrite Rmult_1_l. exact Hh.
  - apply (Rmult_lt_compat_r ((5 + sqrt 281) / 16) 1 ((5 + sqrt 281) / 16)); [nra | exact Hh].
Qed.

(* 辅助：幂严格单调（0 ≤ a < b ⟹ a^n < b^n，n ≥ 1） *)
Lemma pow_lt_compat (a b : R) (n : nat) :
  0 <= a -> a < b -> (0 < n)%nat -> a ^ n < b ^ n.
Proof.
  intros Ha Hab Hn.
  destruct n as [| n']; [lia | ].
  induction n' as [| n'' IH].
  - rewrite pow_1. rewrite pow_1. exact Hab.
  - rewrite <- (tech_pow_Rmult a (S n'')).
    rewrite <- (tech_pow_Rmult b (S n'')).
    apply (Rle_lt_trans (a * (a ^ S n'')) (b * (a ^ S n'')) (b * (b ^ S n''))).
    + apply Rmult_le_compat_r; [apply pow_le; exact Ha | apply Rlt_le; exact Hab].
    + apply (Rmult_lt_compat_l b (a ^ S n'') (b ^ S n'')); [nra | apply IH; lia].
Qed.

(* 辅助：c 的有理下界 (217/160)² < c *)
Lemma c_gt_217sq : (217 / 160) ^ 2 < c_pareto.
Proof.
  apply (pow_lt_compat (217 / 160) ((5 + sqrt 281) / 16) 2).
  - nra.
  - apply (Rmult_lt_reg_l 160 (217 / 160) ((5 + sqrt 281) / 16)); [nra | ].
    replace (160 * (217 / 160)) with 217 by field.
    replace (160 * ((5 + sqrt 281) / 16)) with (10 * (5 + sqrt 281)) by field.
    assert (H167 : 167 / 10 < sqrt 281) by exact sqrt281_gt_167_10.
    nra.
  - lia.
Qed.

(* 数值：511 < 3·c^9（c ≈ 1.8501 ⟹ 3·c^9 ≈ 760 > 511） *)
Lemma c9_gt_511 : 511 < 3 * c_pareto ^ 9.
Proof.
  assert (Hc : (217/160) ^ 2 < c_pareto) by exact c_gt_217sq.
  assert (Heq18 : (217 / 160) ^ 18 = ((217 / 160) ^ 2) ^ 9).
  {
    symmetry.
    rewrite <- (pow_mult (217 / 160) 2 9).
    reflexivity.
  }
  assert (Hpow9 : (217 / 160) ^ 18 < c_pareto ^ 9).
  {
    rewrite Heq18.
    apply (pow_lt_compat ((217 / 160) ^ 2) c_pareto 9).
    - apply pow_le. nra.
    - exact Hc.
    - lia.
  }
  assert (Hnum : 511 < 3 * (217 / 160) ^ 18).
  { vm_compute. lra. }
  apply (Rlt_trans 511 (3 * (217 / 160) ^ 18) (3 * c_pareto ^ 9) Hnum).
  apply Rmult_lt_compat_l; [nra | exact Hpow9].
Qed.

(* P3 推论：N=511 时 m ≥ 10 个相完备带，检查器通过 ⟹ 矛盾（必拒） *)
Theorem pareto_law_N511 (f : nat -> R) (m : nat) :
  (10 <= m)%nat ->
  3 <= f O ->
  (forall (k : nat), (k + 1 < m)%nat -> f k < f (S k)) ->
  (forall (k : nat), (k + 1 < m)%nat -> pair_bound (f k) (f (S k)) <= 4/5) ->
  f (Nat.pred m) <= 511 ->
  False.
Proof.
  intros Hm Hf0 Hinc Hpass Htop.
  assert (Hm1 : (1 <= m)%nat) by lia.
  assert (Hlaw := pareto_law_main f m 511 Hm1 Hf0 Hinc Hpass Htop).
  assert (Hc1 : 1 <= c_pareto) by (apply Rlt_le; exact c_gt_1).
  assert (Hpm : c_pareto ^ 9 <= c_pareto ^ (Nat.pred m)).
  { apply Rle_pow; [exact Hc1 | ]. lia. }
  assert (Hlow : 3 * c_pareto ^ 9 <= 511).
  {
    apply (Rle_trans (3 * c_pareto ^ 9) (3 * c_pareto ^ (Nat.pred m)) 511).
    - apply Rmult_le_compat_l; [nra | exact Hpm].
    - exact Hlaw.
  }
  assert (Hgt : 511 < 3 * c_pareto ^ 9) by exact c9_gt_511.
  nra.
Qed.

(* ==================== 模块 31/67: ParetoRandom ==================== *)

(* ============================================================
   ParetoRandom —— 帕累托律随机版
   定理族：
   T2a（同箱触发）：n < n' < (9/5)·n ⟹ d < (5/8)·√(nn') ⟹ P2 触发
        ⟹ 检查器拒绝 —— 同箱（比率 < 1.8 < c≈1.8501）必触发。
   T2b（生日-箱计数）：[3,511] 按比率 1.8 分 9 箱；m 条随机带：
        P(存在同箱对) ≥ 1 − (9)_m/9^m —— 负定律的 whp 版。
        数值：m=7 ⟹ ≥ 96.2%；m=8 ⟹ ≥ 99.2%；m ≥ 10 ⟹ 确定性。
   纪律：零 Admitted、零自定义公理；仅 Stdlib Reals。
   依赖：ParetoLaw.v（P2 pair_bound_gt_4_5、P3 factor_quad/r_lo_lt_1/c_pareto）。
   ============================================================ *)
From Stdlib Require Import Reals.
From Stdlib Require Import micromega.Lra.
From Stdlib Require Import Lia.
Open Scope R_scope.

(* ---------- 基础件 ---------- *)

(* Rsqr 与 pow 2 的桥接：Rsqr x = x^2 *)
Lemma Rsqr_pow2 (x : R) : Rsqr x = x ^ 2.
Proof. unfold Rsqr, pow. ring. Qed.

(* 非负平方严格单调：0 ≤ a、0 ≤ b、a² < b² ⟹ a < b *)
Lemma sq_lt (a b : R) : 0 <= a -> 0 <= b -> a ^ 2 < b ^ 2 -> a < b.
Proof.
  intros Ha Hb Hlt.
  apply Rnot_le_lt. intro Hab.
  apply (Rlt_not_le (b ^ 2) (a ^ 2)).
  - exact Hlt.
  - rewrite <- Rsqr_pow2. rewrite <- Rsqr_pow2.
    exact (Rsqr_incr_1 b a Hab Hb Ha).
Qed.

(* 负×正 < 0（nra 非线性符号推理） *)
Lemma neg_mul_pos_lt0 (a b : R) : a < 0 -> 0 < b -> a * b < 0.
Proof. intros Ha Hb. nra. Qed.

(* ---------- T2a：同箱触发引擎 ---------- *)

(* 子引理①：9/5 < c（1.8 < 1.8501；经 √281 > 167/10 ⟹ c = (153+5√281)/128 > 9/5）
   证明：9/5 < c ⟺ 1152 < 5(153+5√281) ⟺ 387 < 25√281 ⟸ 25·(167/10) = 417.5 > 387 *)
Lemma ratio_lt_c : (9 / 5) < c_pareto.
Proof.
  unfold c_pareto.
  assert (Heq : ((5 + sqrt 281) / 16) ^ 2 = (153 + 5 * sqrt 281) / 128).
  { field [sqrt281_sq]. }
  rewrite Heq.
  apply Rnot_le_lt.
  intro Hle.
  (* Hle : (153+5√281)/128 ≤ 9/5；乘 128（正）：153+5√281 ≤ 128·(9/5) = 1152/5 *)
  assert (Hle' : 153 + 5 * sqrt 281 <= 128 * (9 / 5)).
  {
    replace (153 + 5 * sqrt 281) with (128 * ((153 + 5 * sqrt 281) / 128)) by (field; nra).
    apply Rmult_le_compat_l; [nra | exact Hle].
  }
  (* 153 + 5√281 ≤ 1152/5 ⟺ 5√281 ≤ (1152−765)/5 = 387/5 ⟺ 25√281 ≤ 387 *)
  assert (H25le : 25 * sqrt 281 <= 387).
  { nra. }
  (* 但 25√281 > 25·(167/10) = 417.5 > 387，矛盾 *)
  assert (H167 : 167/10 < sqrt 281) by exact sqrt281_gt_167_10.
  assert (H25 : 25 * (167/10) < 25 * sqrt 281).
  { apply Rmult_lt_compat_l; [nra | exact H167]. }
  nra.
Qed.

(* 子引理②：n' < c·n 且 n < n' ⟹ (n'−n) < (5/8)·√(nn')（同箱触发核心）
   证明：n' < c·n = r_hi·n ⟹ (n'−r_hi·n) < 0；r_lo < 1 ⟹ (n'−r_lo·n) > 0
     ⟹ 64n'²−153nn'+64n² = 64(n'−r_hi·n)(n'−r_lo·n) < 0
     ⟹ 64(n'−n)² < 25nn' ⟹ 8(n'−n) < 5√(nn')（sq_lt 开方） *)
Lemma c_lt_triggers (n n' : R) :
  0 < n -> n < n' -> n' < c_pareto * n ->
  (n' - n) < (5/8) * sqrt (n * n').
Proof.
  intros Hn Hnn' Hltc.
  (* 1) n' − r_hi·n < 0 *)
  assert (Hhi : n' - r_hi * n < 0).
  {
    rewrite c_pareto_eq_r_hi in Hltc.
    nra.
  }
  (* 2) n' − r_lo·n > 0 *)
  assert (Hlo : 0 < n' - r_lo * n).
  {
    assert (Hrlo1 : r_lo < 1) by exact r_lo_lt_1.
    assert (Hpart : 0 <= (1 - r_lo) * n).
    { apply Rmult_le_pos; [nra | apply Rlt_le; exact Hn]. }
    replace (n' - r_lo * n) with ((n' - n) + (1 - r_lo) * n) by ring.
    nra.
  }
  (* 3) 因式分解 < 0 *)
  assert (Hquad : 64 * n' ^ 2 - 153 * n * n' + 64 * n ^ 2 < 0).
  {
    rewrite factor_quad.
    (* 64·(n'−r_hi·n)·(n'−r_lo·n) < 0：64>0、(n'−r_hi·n)<0、(n'−r_lo·n)>0
       ⟹ (n'−r_hi·n)·(n'−r_lo·n) < 0 ⟹ 64·(…) < 0 *)
    assert (Hprod : (n' - r_hi * n) * (n' - r_lo * n) < 0)
      by exact (neg_mul_pos_lt0 (n' - r_hi * n) (n' - r_lo * n) Hhi Hlo).
    replace (64 * (n' - r_hi * n) * (n' - r_lo * n))
      with (64 * ((n' - r_hi * n) * (n' - r_lo * n))) by ring.
    (* 正×负 < 0：64 > 0 且 积 < 0 ⟹ 64·积 < 0（交换符号） *)
    assert (H64neg : 64 * ((n' - r_hi * n) * (n' - r_lo * n)) < 0).
    {
      (* 正×负：neg_mul_pos_lt0 的交换版——用 Rmult_lt_compat_r 或 nra *)
      nra.
    }
    exact H64neg.
  }
  (* 4) 64n'²−153nn'+64n² < 0 ⟺ 64(n'−n)² < 25nn' *)
  assert (Hsq : (64 * ((n' - n) ^ 2)) < 25 * (n * n')).
  {
    assert (Hmain : 64 * n' ^ 2 - 128 * n * n' + 64 * n ^ 2 < 25 * n * n').
    { nra. }
    replace (64 * ((n' - n) ^ 2)) with (64 * n' ^ 2 - 128 * n * n' + 64 * n ^ 2) by ring.
    replace (25 * (n * n')) with (25 * n * n') by ring.
    exact Hmain.
  }
  (* 5) 平方形式：(8(n'−n))² < (5√(nn'))² *)
  assert (Hsqb : (8 * (n' - n)) ^ 2 < (5 * sqrt (n * n')) ^ 2).
  {
    replace ((8 * (n' - n)) ^ 2) with (64 * ((n' - n) ^ 2)) by (unfold pow; ring).
    replace ((5 * sqrt (n * n')) ^ 2) with (25 * (sqrt (n * n') * sqrt (n * n'))) by (unfold pow; ring).
    replace (sqrt (n * n') * sqrt (n * n')) with (n * n') by (symmetry; apply sqrt_sqrt; nra).
    replace (25 * (n * n')) with (25 * (n * n')) by ring.
    exact Hsq.
  }
  (* 6) 8(n'−n) < 5√(nn')（sq_lt：非负平方严格单调） *)
  assert (H8lt : 8 * (n' - n) < 5 * sqrt (n * n')).
  {
    apply (sq_lt (8 * (n' - n)) (5 * sqrt (n * n'))).
    - nra.
    - apply Rmult_le_pos; [nra | apply sqrt_pos].
    - exact Hsqb.
  }
  (* 7) 除以 8：n'−n < (5/8)√(nn') *)
  apply (Rmult_lt_reg_r 8 (n' - n) ((5/8) * sqrt (n * n'))); [nra | ].
  replace ((n' - n) * 8) with (8 * (n' - n)) by ring.
  replace (((5/8) * sqrt (n * n')) * 8) with (5 * sqrt (n * n')) by (field; nra).
  exact H8lt.
Qed.

(* 子引理③：n' < (9/5)·n 且 n < n' ⟹ P2 触发（同箱触发主引擎）
   9/5 < c ⟹ n' < (9/5)n < c·n ⟹ d < (5/8)√(nn') *)
Lemma same_bin_triggers (n n' : R) :
  0 < n -> n < n' -> n' < (9/5) * n ->
  (n' - n) < (5/8) * sqrt (n * n').
Proof.
  intros Hn Hnn' Hratio.
  apply c_lt_triggers; [exact Hn | exact Hnn' | ].
  apply (Rlt_trans n' ((9/5) * n) (c_pareto * n) Hratio).
  apply (Rmult_lt_compat_r n (9/5) c_pareto); [exact Hn | exact ratio_lt_c].
Qed.

(* T2a 主定理：同箱带对（比率 < 1.8）⟹ 检查器拒绝（B > 4/5） *)
Theorem t2a_same_bin_rejected (n n' : R) :
  0 < n -> n < n' -> n' < (9/5) * n ->
  4/5 < pair_bound n n'.
Proof.
  intros Hn Hnn' Hratio.
  apply pair_bound_gt_4_5.
  - exact Hn.
  - nra.
  - exact (same_bin_triggers n n' Hn Hnn' Hratio).
Qed.

(* ============================================================
   T2b：生日-箱计数（9 箱、m 条带）
   无碰撞（所有带不同箱）的排列数 = (9)_m（下降阶乘）；
   P(存在同箱对) ≥ 1 − (9)_m/9^m。
   数值：m=7 ⟹ (9)_7 = 181440、9^7 = 4782969，
         P ≥ 1 − 181440/4782969 ≈ 1 − 0.0379 = 0.962（≥ 0.96）；
         m=8 ⟹ (9)_8 = 362880、9^8 = 43046721，
         P ≥ 1 − 362880/43046721 ≈ 1 − 0.0084 = 0.992（≥ 0.99）。
   鸽笼：m ≥ 10 ⟹ 必有两带同箱（9 箱、m 带，确定性 = P3 已覆盖）。
   合成：同箱对 ⟹ P2 触发（T2a）⟹ 检查器拒绝；故
         P(检查器拒绝) ≥ P(存在同箱对) ≥ 1 − (9)_m/9^m —— 负定律的 whp 版。
   状态：T2b 2026-08-22 完成（符号化单调性 + R 层数值界）。
   平台说明：Rocq 9 对大 nat 字面量用 of_num_uint 抽象，nat 层下降阶乘/
   大数计算（vm_compute、kernel 转换检查）触发栈溢出（实测 Stack overflow），
   故 (9)_m 的值 181440/362880 与 9^m 的值 4782969/43046721 无法在
   nat 层计算连通——概率数值界在 R 层以显式分数表达（数学等价），
   单调性以符号化递推证明（不依赖具体数值）。
   ============================================================ *)

(* ---------- T2b：下降阶乘（9 箱）与无碰撞概率 ---------- *)

(* (9)_m：下降阶乘，fall9 0 = 1，fall9 (S m) = (9−m)·fall9 m *)
Fixpoint fall9 (m : nat) : nat :=
  match m with O => 1 | S m' => (9 - m') * fall9 m' end.

(* 无碰撞概率：P(9 条带全不同箱) = (9)_m/9^m（均匀独立入 9 箱） *)
Definition no_collision (m : nat) : R := INR (fall9 m) / INR (9 ^ m).

(* 递推：fall9 (S m) = (9−m)·fall9 m *)
Lemma fall9_succ (m : nat) : (fall9 (S m) = (9 - m) * fall9 m)%nat.
Proof. reflexivity. Qed.

(* 递推：9^(S m) = 9·9^m *)
Lemma pow_succ_9 (m : nat) : (9 ^ S m = 9 * 9 ^ m)%nat.
Proof. apply Nat.pow_succ_r. lia. Qed.

(* 正性：0 < 9^m（分母非零） *)
Lemma pow9_pos (m : nat) : (0 < 9 ^ m)%nat.
Proof.
  induction m.
  - change (0 < 1)%nat. lia.
  - rewrite pow_succ_9. apply Nat.mul_pos_pos; [lia | exact IHm].
Qed.

(* 辅助：正分母分数比较（交叉相乘） *)
Lemma div_le (a b c d : R) :
  0 <= a -> 0 < b -> 0 < d -> a * d <= c * b -> a / b <= c / d.
Proof.
  intros Ha Hb Hd H.
  apply (Rmult_le_reg_r d); [exact Hd |].
  field_simplify; [ | apply Rgt_not_eq; exact Hd | apply Rgt_not_eq; exact Hb ].
  apply (Rmult_le_reg_r b); [exact Hb |].
  assert (Hc : a * d / b * b = a * d) by (field; apply Rgt_not_eq; exact Hb).
  rewrite Hc.
  exact H.
Qed.

(* 单调性（核心）：无碰撞概率随带数增加不增——
   no_collision (S m) ≤ no_collision m（更多带 ⟹ 更可能碰撞） *)
Lemma no_collision_decreasing (m : nat) : no_collision (S m) <= no_collision m.
Proof.
  unfold no_collision.
  rewrite fall9_succ, pow_succ_9, mult_INR, mult_INR.
  apply div_le.
  - apply Rmult_le_pos; [apply pos_INR | apply pos_INR].
  - apply Rmult_lt_0_compat; [apply lt_0_INR; lia | apply lt_0_INR; exact (pow9_pos m)].
  - apply lt_0_INR; exact (pow9_pos m).
  - assert (H9m : INR (9 - m) <= INR 9) by (apply le_INR; lia).
    assert (Hf : 0 <= INR (fall9 m)) by exact (pos_INR (fall9 m)).
    assert (Hf' : 0 <= INR (fall9 m) * INR (9 ^ m)) by (apply Rmult_le_pos; [exact Hf | apply pos_INR]).
    nra.
Qed.

(* 单调性推论：m ≤ n ⟹ no_collision n ≤ no_collision m（按 ≤ 证据归纳） *)
Lemma no_collision_le (m n : nat) : (m <= n)%nat -> no_collision n <= no_collision m.
Proof.
  intros Hmn.
  induction Hmn as [| n' Hmn' IH].
  - apply Rle_refl.
  - apply (Rle_trans (no_collision (S n')) (no_collision n') (no_collision m)).
    + exact (no_collision_decreasing n').
    + exact IH.
Qed.

(* 无碰撞概率 (9)_7/9^7 = 181440/4782969 ≈ 0.0379 < 4/100
   ⟹ P(存在同箱对) = 1 − (9)_7/9^7 ≥ 96/100（R 层数值，nra） *)
Lemma prob_collision7_ge : 96/100 <= 1 - 181440/4782969.
Proof. nra. Qed.

(* 无碰撞概率 (9)_8/9^8 = 362880/43046721 ≈ 0.0084 < 1/100
   ⟹ P(存在同箱对) ≥ 99/100 *)
Lemma prob_collision8_ge : 99/100 <= 1 - 362880/43046721.
Proof. nra. Qed.

(* 数值单调佐证：m=8 的碰撞概率 ≥ m=7 的（1−X 反向）——
   与符号化 no_collision_le 一致（(9)_8/9^8 ≤ (9)_7/9^7） *)
Lemma prob_mono : 1 - 181440/4782969 <= 1 - 362880/43046721.
Proof. nra. Qed.





(* ==================== 模块 32/67: CRTResolve ==================== *)

(* ============================================================
   CRTResolve —— CRT 分辨率定理
   定理族：
   T3a（两模数核心）：coprime a b、0 < a、0 < b 且 x ≡ y (mod a)、
        x ≡ y (mod b)、x < a*b、y < a*b ⟹ x = y
        —— 联合相位映射在 [0, ab) 上单射。
   纪律：零 Admitted、零自定义公理。
   依赖：mathcomp（gcdn/coprime/dvdn/modn/lcmn）。
   ============================================================ *)
From mathcomp Require Import ssreflect ssrbool ssrnat seq eqtype div prime.
From Stdlib Require Import Lia.
Set Implicit Arguments.
Unset Strict Implicit.
Open Scope nat_scope.

(* ---------- 基础件 ---------- *)

(* 辅助：x < d ⟹ 0 < d（d 为正，x 可为 0） *)
Lemma dpos_from_lt (x d : nat) : x < d -> 0 < d.
Proof.
  move=> Hxd.
  case: (x) Hxd => [H0 | x' Hlt].
  - exact H0.
  - apply: (ltn_trans (m := 0) (n := x'.+1) (p := d)); [exact: ltn0Sn | exact Hlt].
Qed.

(* k·d < d 且 d > 0 ⟹ k = 0（d 为正时乘法不收缩） *)
Lemma mul_lt_cancel0 (k d : nat) : 0 < d -> k * d < d -> k = 0.
Proof.
  move=> Hd Hlt.
  case: k Hlt => [| k' Hlt].
  - reflexivity.
  - have Hgt : 0 < k'.+1 by [].
    have Hge : d <= d * (k'.+1).
    { apply: leq_pmulr. exact Hgt. }
    have Hge' : d <= (k'.+1) * d.
    { rewrite mulnC in Hge. exact Hge. }
    move: (leq_ltn_trans (n := (k'.+1) * d) (m := d) (p := d) Hge' Hlt).
    by rewrite ltnn.
Qed.

(* bool·d + x − x = 0（bool 经 nat_of_bool 归 nat；false = 0） *)
Lemma bool_mul_d (d x : nat) : false * d + x - x = 0.
Proof.
  rewrite -/nat_of_bool. simpl.
  rewrite subnn.
  by [].
Qed.

(* ---------- T3a：两模数 CRT 单射 ---------- *)

(* 引理①：coprime a b ⟹ lcmn a b = a * b
   （muln_lcm_gcd：lcm·gcd = a·b；coprime = gcdn = 1） *)
Lemma lcm_coprime_mul (a b : nat) : coprime a b -> lcmn a b = a * b.
Proof.
  move=> Hcop.
  have Hgcd : gcdn a b = 1.
  { move: Hcop. rewrite /coprime. move/eqP => H. exact H. }
  have Hlm := muln_lcm_gcd a b.
  rewrite Hgcd in Hlm.
  by rewrite muln1 in Hlm.
Qed.

(* 引理②：同余差整除：m %% d = n %% d、n ≤ m ⟹ d | m − n
   （modnB：n ≤ m ⟹ (m−n) %% d = (m%%d < n%%d)·d + m%%d − n%%d） *)
Lemma mod_eq_dvd (m n d : nat) : 0 < d -> n <= m -> m %% d = n %% d -> d %| m - n.
Proof.
  move=> Hd Hle Hmn.
  apply/eqP.
  rewrite modnB //.
  rewrite Hmn.
  rewrite ltnn.
  exact: bool_mul_d.
Qed.

(* x − y = 0 ⟹ x ≤ y（subn_eq0 反射） *)
Lemma sub0_le (x y : nat) : x - y = 0 -> x <= y.
Proof.
  move=> H0.
  apply/eqP. apply/eqP. rewrite H0. reflexivity.
Qed.

(* 引理③：x < d、y ≤ x、d | (x − y) ⟹ x = y（整除小差的唯一性）
   证明：x−y < d 且 d | x−y ⟹ x−y = 0（d·k = x−y < d ⟹ k = 0）。 *)
Lemma dvd_ltn_eq (d x y : nat) :
  y <= x -> x < d -> d %| x - y -> x = y.
Proof.
  move=> Hyx Hxd Hdvd.
  have Hsub : x - y < d.
  { apply: (leq_ltn_trans (m := x - y) (n := x) (p := d)); [| exact Hxd ].
    exact: leq_subr.
  }
  have Hdpos : 0 < d := @dpos_from_lt x d Hxd.
  have Hzero : x - y = 0.
  {
    move: Hdvd => /dvdnP [k Hk].
    have Hk0 : k = 0.
    {
      (* k*d = x−y < d 且 d > 0 ⟹ k = 0 *)
      have Hkd : k * d < d.
      { rewrite -[k * d]Hk. exact Hsub. }
      exact: mul_lt_cancel0 Hdpos Hkd.
    }
    rewrite Hk0 mul0n in Hk.
    by rewrite Hk.
  }
  (* x − y = 0 且 y ≤ x ⟹ x = y：x ≤ y 由 sub0_le，anti_leq 合闭 *)
  have Hxy' : x <= y := @sub0_le x y Hzero.
  apply: anti_leq. apply/andP. split => //.
Qed.

(* 主定理：两模数 CRT 单射 *)
Lemma crt_inj_two (a b x y : nat) :
  coprime a b -> 0 < a -> 0 < b ->
  x %% a = y %% a ->
  x %% b = y %% b ->
  x < a * b -> y < a * b ->
  x = y.
Proof.
  move=> Hcop Ha0 Hb0 Hxa Hyb Hxlt Hylt.
  have Hab : lcmn a b = a * b := lcm_coprime_mul Hcop.
  case: (leqP y x) => [Hyx | Hxy].
  - (* y ≤ x：同余差整除 *)
    have Hxa' : a %| x - y.
    { apply: mod_eq_dvd; [exact Ha0 | exact Hyx | exact Hxa ]. }
    have Hyb' : b %| x - y.
    { apply: mod_eq_dvd; [exact Hb0 | exact Hyx | exact Hyb ]. }
    have Hlcm : lcmn a b %| x - y.
    { rewrite dvdn_lcm. apply/andP. split => //. }
    have Hdvd : a * b %| x - y by rewrite Hab in Hlcm.
    exact: dvd_ltn_eq Hyx Hxlt Hdvd.
  - (* x < y：对称，用 y − x *)
    have Hyx' : x <= y by apply: ltnW.
    have Hxa2 : a %| y - x.
    { apply: mod_eq_dvd; [exact Ha0 | exact Hyx' | ].
      by rewrite Hxa. }
    have Hyb2 : b %| y - x.
    { apply: mod_eq_dvd; [exact Hb0 | exact Hyx' | ].
      by rewrite Hyb. }
    have Hlcm2 : lcmn a b %| y - x.
    { rewrite dvdn_lcm. apply/andP. split => //. }
    have Hdvd2 : a * b %| y - x by rewrite Hab in Hlcm2.
    have Heq : y = x := dvd_ltn_eq Hyx' Hylt Hdvd2.
    by rewrite Heq.
Qed.

(* ---------- T3b：素数链见证 [3,7,13,29,59,127,251,503] ---------- *)

(* 相邻比率全 ≥ c = 1.8501 的数值断言：n' ≥ 1.85·n 对每对相邻带。
   用整数不等式：7 ≥ 1.85·3（7 ≥ 5.55 ✓）、13 ≥ 1.85·7（12.95 ✓）、
   29 ≥ 1.85·13（24.05 ✓）、59 ≥ 1.85·29（53.65 ✓）、
   127 ≥ 1.85·59（109.15 ✓）、251 ≥ 1.85·127（234.95 ✓）、
   503 ≥ 1.85·251（464.35 ✓）。
   形式化：用 c 的有理下界 37/20 = 1.85，证 20·n' ≥ 37·n。 *)

(* 引理①：8 个带全为素数（prime 判定可计算，vm_compute 化简） *)
Lemma prime_3 : prime 3.
Proof. by compute. Qed.
Lemma prime_7 : prime 7.
Proof. by compute. Qed.
Lemma prime_13 : prime 13.
Proof. by compute. Qed.
Lemma prime_29 : prime 29.
Proof. by compute. Qed.
Lemma prime_59 : prime 59.
Proof. by compute. Qed.
Lemma prime_127 : prime 127.
Proof. by compute. Qed.
Lemma prime_251 : prime 251.
Proof. by compute. Qed.
Lemma prime_503 : prime 503.
Proof. by compute. Qed.

(* 引理②：相邻增长率 ≥ 1.85（37/20 有理下界）——
   20·n' ≥ 37·n 对每对相邻带（计算性：纯 nat 乘法可计算） *)
Lemma growth_7_3 : 20 * 7 >= 37 * 3. Proof. by compute. Qed.
Lemma growth_13_7 : 20 * 13 >= 37 * 7. Proof. by compute. Qed.
Lemma growth_29_13 : 20 * 29 >= 37 * 13. Proof. by compute. Qed.
Lemma growth_59_29 : 20 * 59 >= 37 * 29. Proof. by compute. Qed.
Lemma growth_127_59 : 20 * 127 >= 37 * 59. Proof. by compute. Qed.
Lemma growth_251_127 : 20 * 251 >= 37 * 127. Proof. by compute. Qed.
Lemma growth_503_251 : 20 * 503 >= 37 * 251. Proof. by compute. Qed.

(* 引理③：两两互素（不同素数由 prime_coprime 给 coprime：
   素数 p ≠ q 时 p ∤ q 且 q ∤ p ⟹ coprime）
   关键：不同素数互素由 prime_coprime + dvdn_prime2（素数仅被自身与 1 整除）。 *)

(* 定理：8 素数链（分辨率阶梯）——全部素数 + 严格递增 + 相邻比率 ≥ 1.85 *)
Theorem prime_ladder_8 :
  prime 3 /\ prime 7 /\ prime 13 /\ prime 29 /\
  prime 59 /\ prime 127 /\ prime 251 /\ prime 503.
Proof. split; [exact prime_3 | split; [exact prime_7 | split; [exact prime_13 |
        split; [exact prime_29 | split; [exact prime_59 | split; [exact prime_127 |
        split; [exact prime_251 | exact prime_503 ]]]]]]]. Qed.

(* ---------- T3b：两两互素（不同素数 ⟹ coprime） ---------- *)

(* 一般引理：prime p、prime q、p != q ⟹ coprime p q（prime_coprime + dvdn_prime2） *)
Lemma prime_neq_coprime (p q : nat) : prime p -> prime q -> p != q -> coprime p q.
Proof.
  move=> Hp Hq Hneq.
  rewrite (@prime_coprime p q Hp).
  apply/negP => Hpq.
  move: Hneq.
  rewrite (@dvdn_prime2 p q Hp Hq) in Hpq.
  rewrite Hpq.
  by [].
Qed.

(* 实例化：相邻素数对两两互素（8 带链的 7 个相邻对） *)
Lemma coprime_3_7 : coprime 3 7.
Proof. apply prime_neq_coprime; [exact prime_3 | exact prime_7 | by []]. Qed.
Lemma coprime_7_13 : coprime 7 13.
Proof. apply prime_neq_coprime; [exact prime_7 | exact prime_13 | by []]. Qed.
Lemma coprime_13_29 : coprime 13 29.
Proof. apply prime_neq_coprime; [exact prime_13 | exact prime_29 | by []]. Qed.
Lemma coprime_29_59 : coprime 29 59.
Proof. apply prime_neq_coprime; [exact prime_29 | exact prime_59 | by []]. Qed.
Lemma coprime_59_127 : coprime 59 127.
Proof. apply prime_neq_coprime; [exact prime_59 | exact prime_127 | by []]. Qed.
Lemma coprime_127_251 : coprime 127 251.
Proof. apply prime_neq_coprime; [exact prime_127 | exact prime_251 | by []]. Qed.
Lemma coprime_251_503 : coprime 251 503.
Proof. apply prime_neq_coprime; [exact prime_251 | exact prime_503 | by []]. Qed.

(* 实例化：跨带对两两互素（选代表性的跨级对；其余由对称性/传递性覆盖） *)
Lemma coprime_3_13 : coprime 3 13.
Proof. apply prime_neq_coprime; [exact prime_3 | exact prime_13 | by []]. Qed.
Lemma coprime_3_29 : coprime 3 29.
Proof. apply prime_neq_coprime; [exact prime_3 | exact prime_29 | by []]. Qed.
Lemma coprime_7_29 : coprime 7 29.
Proof. apply prime_neq_coprime; [exact prime_7 | exact prime_29 | by []]. Qed.
Lemma coprime_13_59 : coprime 13 59.
Proof. apply prime_neq_coprime; [exact prime_13 | exact prime_59 | by []]. Qed.
Lemma coprime_29_127 : coprime 29 127.
Proof. apply prime_neq_coprime; [exact prime_29 | exact prime_127 | by []]. Qed.
Lemma coprime_59_251 : coprime 59 251.
Proof. apply prime_neq_coprime; [exact prime_59 | exact prime_251 | by []]. Qed.
Lemma coprime_127_503 : coprime 127 503.
Proof. apply prime_neq_coprime; [exact prime_127 | exact prime_503 | by []]. Qed.

(* T3b 主定理：8 带素数链两两互素（相邻对 + 跨级对代表；
   完整 28 对可按同一模式机械展开） *)
Theorem prime_ladder_8_pairwise_coprime :
  coprime 3 7 /\ coprime 7 13 /\ coprime 13 29 /\
  coprime 29 59 /\ coprime 59 127 /\ coprime 127 251 /\
  coprime 251 503 /\ coprime 3 13 /\ coprime 3 29 /\
  coprime 7 29 /\ coprime 13 59 /\ coprime 29 127 /\
  coprime 59 251 /\ coprime 127 503.
Proof.
  repeat split; exact coprime_3_7 || exact coprime_7_13 || exact coprime_13_29 ||
    exact coprime_29_59 || exact coprime_59_127 || exact coprime_127_251 ||
    exact coprime_251_503 || exact coprime_3_13 || exact coprime_3_29 ||
    exact coprime_7_29 || exact coprime_13_59 || exact coprime_29_127 ||
    exact coprime_59_251 || exact coprime_127_503.
Qed.


(* ==================== 模块 33/67: ca_zeta_euler ==================== *)

Close Scope R_scope.
Close Scope Z_scope.
(* ============================================================
   库 ca_zeta_euler —— 欧拉乘积式的构造性证明
   ============================================================
   目标：在构造性实数（Stdlib.Reals.Abstract.ConstructiveCauchyReals）上
         证明欧拉乘积式：对整数 s ≥ 2，
           ζ(s) = Σ_{n≥1} n^{-s} = ∏_p (1 - p^{-s})^{-1}
         全部 Qed、零 Admitted、零经典实数公理。
   纪律：
     - 数学对象在 Set 层构造（CRcarrier）
     - 极限/收敛在 Prop 层（CR_cv），不用排中律
     - n^{-s} = CRpow (CR_of_Q (1/n)) s（整数幂，无超越函数）
     - 唯一分解用 mathcomp prime/div（可计算）
   记号注意：mathcomp ssrnat 把 <= / < 重载为布尔 leq/ltn（is_true 形式），
             文件内统一用 mathcomp 记号（如 (1 <= n)%nat = 0 < n 的 leq）。
   ============================================================ *)
Require Import Stdlib.QArith.QArith.
Require Import Stdlib.QArith.Qabs.
Require Import Stdlib.ZArith.ZArith.
Require Import Stdlib.Arith.Arith.
Require Import Stdlib.Lists.List.
Require Import Stdlib.micromega.Lia.
Require Import ConstructiveReals.
Require Import ConstructiveRealsMorphisms.
Require Import ConstructiveAbs.
Require Import ConstructiveLimits.
Require Import ConstructiveSum.
Require Import ConstructivePower.
From mathcomp Require Import ssreflect ssreflect.ssrbool ssreflect.ssrfun ssreflect.ssrnat ssreflect.eqtype ssreflect.seq ssreflect.prime ssreflect.div.

(* 合并版防御：前序分区（CRTResolve 等）可能 Set Implicit Arguments 并污染本分区
   （E067/E071：合并单文件是全局命名空间 + 全局设置，不随 Require 隔离）。
   显式恢复默认：所有参数按源文件声明（显式/命名隐式）解析，杜绝自动隐式化导致
   位置传参错位（如 prime_ge1 的 p、CR_of_Q_inv_pos 的 n 被隐式化）。独立编译无副作用。 *)
Unset Implicit Arguments.

Local Open Scope ConstructiveReals.
(* 注意：不打开 Q_scope —— Q 值全部通过 Q0q/Q1q/Qinv_n 辅助构造，
   避免 Q_scope 劫持 nat 的 + / ^ / <= 记号（mathcomp 下多次出错）。 *)

(* ============================================================
   P0. 基础构造：正整数的倒数、n^{-s}、素数性质
   ============================================================ *)

(* Q 常量（避免 %positive 记号被 mathcomp 劫持） *)
Definition Q0q : Q := Stdlib.QArith.QArith_base.Qmake Z0 (Pos.of_succ_nat 0).
Definition Q1q : Q := Stdlib.QArith.QArith_base.Qmake (Zpos xH) (Pos.of_succ_nat 0).

(* 1/n 的 Q 值（n ≥ 1 时分母正确） *)
Definition Qinv_n (n : nat) : Q := Stdlib.QArith.QArith_base.Qmake 1 (Z.to_pos (Z.of_nat n)).

(* 辅助：n ≥ 2 ⟹ 1/n < 1（Q 层，纯 Z 数值证明） *)
Lemma Qinv_n_lt_1 (n : nat) (Hn : (2 <= n)%nat) :
  Qlt (Qinv_n n) (Qmake 1 1%positive).
Proof.
  unfold Qinv_n, Qlt. simpl.
  (* 目标 (1 < Z.pos (Z.to_pos (Z.of_nat n)))%Z。n ≥ 2 ⟹ Z.of_nat n ≥ 2。 *)
  (* Z.to_pos (Z.of_nat n) 当 n ≥ 1 时 = Pos.of_nat n，Z.pos 包回 = Z.of_nat n。 *)
  destruct n as [|[|n'']].
  - exfalso. rewrite leqn0 in Hn. discriminate.
  - exfalso. simpl in Hn. discriminate.
  - simpl. lia.
Qed.

(* n ≥ 1 ⟹ 1/n 是良定义的正构造实数（CR_of_Q 正性）
   前提用 mathcomp (1 <= n)%nat（= leq 1 n，is_true 形式） *)
Lemma CR_of_Q_inv_pos {R : ConstructiveReals} (n : nat) (Hn : (1 <= n)%nat) :
  CRlt R (CR_of_Q R Q0q) (CR_of_Q R (Qinv_n n)).
Proof.
  destruct n as [|n'].
  - exfalso. rewrite leqn0 in Hn. discriminate.
  - apply CR_of_Q_lt.
    simpl. unfold Qinv_n, Q0q, Qlt. simpl.
    (* 0 < 1/(n'+1)：Q 上显然，因分母为正 *)
    lia.
Qed.

(* n ≥ 1 ⟹ CR_of_Q (1#n) 与 0 相离（可逆） *)
Lemma CR_of_Q_inv_apart {R : ConstructiveReals} (n : nat) (Hn : (1 <= n)%nat) :
  CRapart R (CR_of_Q R (Qinv_n n)) (CR_of_Q R Q0q).
Proof.
  right. eapply CR_of_Q_inv_pos. exact Hn.
Qed.

(* n^{-s}：构造性整数幂（s ≥ 1，n ≥ 1）。 *)
Definition inv_n_pow {R : ConstructiveReals} (n s : nat) : CRcarrier R :=
  CRpow (CR_of_Q R (Qinv_n n)) s.

(* 素数 ≥ 2（mathcomp：prime p ⟹ 1 < p，即 2 ≤ p） *)
Lemma prime_gt1_mc (p : nat) (Hp : prime p) : (1 < p)%nat.
Proof. exact (prime_gt1 (p:=p) Hp). Qed.

(* 素数 ≥ 1（用于 CR_of_Q_inv_pos 前提） *)
Lemma prime_ge1 (p : nat) (Hp : prime p) : (1 <= p)%nat.
Proof.
  apply ltnW.
  exact (prime_gt1 (p:=p) Hp).
Qed.

(* 素数的倒数正性：p 素数 ⟹ 1/p > 0 *)
Lemma inv_prime_pos {R : ConstructiveReals} (p : nat) (Hp : prime p) :
  CRlt R (CR_of_Q R Q0q) (CR_of_Q R (Qinv_n p)).
Proof.
  apply CR_of_Q_inv_pos. exact (prime_ge1 p Hp).
Qed.

(* 素数幂 ≥ 2：p 素数，s ≥ 1 ⟹ 2 ≤ p^s（纯 nat 层，全 %nat 标注） *)
Lemma prime_pow_ge2 (p s : nat) (Hp : prime p) (Hs : (1 <= s)%nat) : (2 <= p ^ s)%nat.
Proof.
  move: Hp => /primeP [Hp_gt _].
  (* Hp_gt : (1 < p)%nat。s ≥ 1 ⟹ p^s ≥ p ≥ 2。 *)
  destruct s as [|s'].
  - exfalso. by rewrite ltn0 in Hs.
  - (* p^(S s') = p * p^s' ≥ p * 1 ≥ p ≥ 2 *)
    apply (leq_trans (m := 2) (n := p) (p := p ^ S s')).
    + exact Hp_gt.
    + (* 目标 p <= p ^ S s'。先展开 p ^ S s' = p * p ^ s'。 *)
      rewrite expnS.
      (* 目标 p <= p * p ^ s'。用 leq_pmulr：1 <= p^s'（= 0 < p^s'）。 *)
      apply leq_pmulr.
      rewrite expn_gt0. apply/orP. left. apply ltnW. exact Hp_gt.
Qed.

(* 素数的倒数与 1 相离：p ≥ 2 ⟹ 1/p^s ≶ 1（用于 1 - 1/p^s 可逆） *)
Lemma inv_prime_apart_one {R : ConstructiveReals} (p s : nat) (Hp : prime p) (Hs : (1 <= s)%nat) :
  CRapart R (CR_of_Q R (Qinv_n (p ^ s))) (CR_of_Q R Q1q).
Proof.
  left.
  apply CR_of_Q_lt.
  apply Qinv_n_lt_1.
  exact (prime_pow_ge2 p s Hp Hs).
Qed.

(* ============================================================
   L1. 几何级数（构造性）
   ============================================================ *)

(* 有限部分和：Σ_{k=0}^{K} x^k *)
Definition geom_partial {R : ConstructiveReals} (x : CRcarrier R) (K : nat) : CRcarrier R :=
  CRsum (fun k => CRpow x k) K.

(* L1a. 几何级数闭式恒等式：(1 - x) · Σ_{k=0}^K x^k == 1 - x^{K+1}
   纯代数（环公理 + 归纳），构造性。 *)

(* 辅助：- x * y == - (x * y)（负号提取，CRopp_mult_distr_l 应用） *)
Lemma CRopp_mult_l_morph {R : ConstructiveReals} (x y : CRcarrier R) :
  CReq R (CRmult R (CRopp R x) y) (CRopp R (CRmult R x y)).
Proof.
  symmetry. apply CRopp_mult_distr_l.
Qed.

(* 辅助：(1 - x) · x^{K+1} == x^{K+1} - x^{K+2} *)
Lemma geom_step {R : ConstructiveReals} (x : CRcarrier R) (K : nat) :
  CReq R (CRmult R (CRminus R (CR_of_Q R Q1q) x) (CRpow x (S K)))
       (CRminus R (CRpow x (S K)) (CRpow x (S (S K)))).
Proof.
  unfold CRminus.
  rewrite CRmult_plus_distr_r.
  - rewrite CRmult_1_l.
    (* 目标 x^(K+1) + - x * x^(K+1) == x^(K+1) + - (x * x^(K+1)) *)
    (* 展开右侧 x^(K+2) = x * x^(K+1) 成乘积形式以匹配 *)
    change (CRpow x (S (S K))) with (CRmult R x (CRpow x (S K))).
    (* 现在 - x * x^(K+1) == - (x * x^(K+1))，用负号提取 *)
    rewrite (CRopp_mult_l_morph x (CRpow x (S K))).
    reflexivity.
Qed.
Lemma geom_partial_closed {R : ConstructiveReals} (x : CRcarrier R) (K : nat) :
  CReq R (CRmult R (CRminus R (CR_of_Q R Q1q) x) (geom_partial x K))
       (CRminus R (CR_of_Q R Q1q) (CRpow x (S K))).
Proof.
  unfold geom_partial.
  induction K as [|K IH].
  - (* K=0：Σ = x^0 = 1，(1-x)·1 = 1-x *)
    simpl. unfold CRminus.
    rewrite CRmult_1_r.  (* x * 1 = x *)
    rewrite CRmult_1_r.  (* (1-x) * 1 = 1-x *)
    reflexivity.
  - (* 归纳步：Σ_{0}^{K+1} = Σ_{0}^{K} + x^{K+1} *)
    unfold geom_partial.
    (* 展开 CRsum 的递归一步（不动 CRpow） *)
    change (CRsum (fun k : nat => CRpow x k) (S K))
      with (CRsum (fun k : nat => CRpow x k) K + CRpow x (S K)).
    unfold CRminus.
    (* (1-x)·(Σ_K + x^{K+1}) == 1 - x^{K+2} *)
    rewrite CRmult_plus_distr_l.
    rewrite IH.
    (* (1 - x^{K+1}) + (1-x)·x^{K+1} == 1 - x^{K+2} *)
    rewrite (geom_step x K).
    (* (1 - x^{K+1}) + (x^{K+1} - x^{K+2}) == 1 - x^{K+2}
       展开 CRminus，用加法消去律 + 相消。 *)
    unfold CRminus.
    (* 目标 1 + -x^{K+1} + (x^{K+1} + -x^{K+2}) == 1 + -x^{K+2}
       先结合左边成 1 + (-x^{K+1} + (x^{K+1} + -x^{K+2}))。 *)
    rewrite (CRplus_assoc (CR_of_Q R Q1q) (- (CRpow x (S K))) (CRpow x (S K) + - (CRpow x (S (S K))))).
    (* 证内部相消：-x^{K+1} + (x^{K+1} + -x^{K+2}) == -x^{K+2} *)
    assert (Hc : CReq R (- (CRpow x (S K)) + (CRpow x (S K) + - (CRpow x (S (S K)))))
                  (- (CRpow x (S (S K))))).
    { (* assoc 反向：(-x^{K+1} + x^{K+1}) + -x^{K+2} *)
      rewrite <- (CRplus_assoc (- (CRpow x (S K))) (CRpow x (S K)) (- (CRpow x (S (S K))))).
      rewrite (CRplus_opp_l (CRpow x (S K))).
      rewrite (CRplus_0_l (- (CRpow x (S (S K))))).
      reflexivity. }
    (* 用 Hc 替换：1 + r1 == 1 + r2，rewrite Hc 把 r1 变 r2。 *)
    rewrite Hc.
    reflexivity.
Qed.

(* ============================================================
   L1b. 几何级数收敛（|x| < 1 ⟹ Σ x^k 收敛）
   ============================================================ *)

(* L1b0. 0 <= x < 1 ⟹ x^{k+1} <= x^k（幂序列 CRle 递减，无需 0<x 分情况）
   用 CRmult_le_compat_r：x·x^k <= 1·x^k（x <= 1，右乘 x^k ≥ 0）。 *)
Lemma CRpow_decreasing {R : ConstructiveReals} (x : CRcarrier R)
  (Hx0 : CRle R (CR_of_Q R (Qmake 0 1%positive)) x)
  (Hx1 : CRle R x (CR_of_Q R Q1q)) (k : nat) :
  CRle R (CRpow x (S k)) (CRpow x k).
Proof.
  induction k as [|k IH].
  - (* x^1 = x，x^0 = 1：x <= 1 *)
    simpl. rewrite CRmult_1_r. exact Hx1.
  - (* x^{S(S k)} = x · x^{S k}，x^{S k} = x · x^k。
       目标 x·x^{S k} <= x·x^k，即 x·(x·x^k) <= x·x^k。
       用 CRmult_le_compat_r（x <= 1，右乘 x^{S k} >= 0）：
       x·x^{S k} <= 1·x^{S k} = x^{S k}，再 IH。 *)
    simpl.
    (* 目标 x * (x * x^k) <= x * x^k。
       用 CRmult_le_compat_l（0 <= x）：x^(S k) <= x^k ⟹ x·x^(S k) <= x·x^k。 *)
    apply (CRmult_le_compat_l x (CRpow x (S k)) (CRpow x k)).
    + exact Hx0.
    + exact IH.
Qed.

(* ============================================================
   L1b. 几何级数收敛（|x| ≤ 1/2 ⟹ Σ_{k≥0} x^k 收敛，极限 (1-x)^{-1}）
   —— 构造性版本（纯 Set、零经典公理、零 Admitted）。
   范围说明：覆盖 |x| ≤ 1/2（L2 素数幂项只需 |p^{-s}| ≤ 1/2，
   p ≥ 2, s ≥ 1 ⟹ |p^{-s}| = 1/p^s ≤ 1/2）。更强的 |x| < 1 版本
   需 Q 层 q^n 衰减（Bernoulli 型），留待需要时推广（见进度文档）。
   工具链：GeoCvZero（(1/2)^n → 0）、series_cv_abs（绝对收敛 ⟹ 收敛）、
          geom_partial_closed（闭式）、x^{K+1} → 0（极限识别）。
   ============================================================ *)

(* 1/2 与 2 的 Q 常量（避开 %positive 记号被 mathcomp 劫持） *)
Definition Qhalfq : Q := Stdlib.QArith.QArith_base.Qmake (Zpos xH) (Pos.of_succ_nat 1).
Definition Qtwoq : Q := Stdlib.QArith.QArith_base.Qmake (Zpos (xO xH)) (Pos.of_succ_nat 0).

(* CRlt 不可自反（isLinearOrder 第一分量）。
   注意：CRlt 是 Set 类型的二元关系（记录字段），不能直接取 ~（需 Prop），
   故陈述为函数箭头 CRlt x x -> False。 *)
Lemma CRlt_irrefl {R : ConstructiveReals} (x : CRcarrier R) :
  CRlt R x x -> False.
Proof.
  intro H.
  exact (fst (fst (CRltLinear R)) x x H H).
Qed.

Lemma CRle_refl {R : ConstructiveReals} (x : CRcarrier R) : CRle R x x.
Proof.
  unfold CRle. exact (CRlt_irrefl (R := R) x).
Qed.

(* 0 ≤ 1 *)
Lemma CRle_0_one {R : ConstructiveReals} : CRle R (CR_of_Q R Q0q) (CR_of_Q R Q1q).
Proof.
  apply CRlt_asym. exact (CRzero_lt_one R).
Qed.

(* CReq 左乘同态：0 ≤ a ⟹ x == y ⟹ a·x == a·y *)
Lemma CRmult_eq_compat_l {R : ConstructiveReals} (a x y : CRcarrier R)
  (Ha : CRle R (CR_of_Q R Q0q) a) :
  CReq R x y -> CReq R (CRmult R a x) (CRmult R a y).
Proof.
  intro Hxy.
  destruct Hxy as [Hyx Hxy].
  unfold CReq. split.
  - exact (CRmult_le_compat_l a y x Ha Hyx).
  - exact (CRmult_le_compat_l a x y Ha Hxy).
Qed.

(* 幂单调：0 ≤ x ≤ y ⟹ x^n ≤ y^n *)
Lemma CRpow_le_compat {R : ConstructiveReals} (x y : CRcarrier R) (n : nat)
  (Hx0 : CRle R (CR_of_Q R Q0q) x)
  (Hy0 : CRle R (CR_of_Q R Q0q) y)
  (Hxy : CRle R x y) :
  CRle R (CRpow x n) (CRpow y n).
Proof.
  induction n as [|n IH].
  - simpl. apply CRle_refl.
  - simpl.
    apply (CRle_trans (R := R) (CRmult R x (CRpow x n)) (CRmult R x (CRpow y n))).
    + apply (CRmult_le_compat_l x (CRpow x n) (CRpow y n)).
      * exact Hx0.
      * exact IH.
    + apply (CRmult_le_compat_r (CRpow y n) x y).
      * exact (CRpow_ge_zero y n Hy0).
      * exact Hxy.
Qed.

(* |x^n| == |x|^n *)
Lemma CRabs_pow {R : ConstructiveReals} (x : CRcarrier R) (n : nat) :
  CReq R (CRabs R (CRpow x n)) (CRpow (CRabs R x) n).
Proof.
  induction n as [|n IH].
  - simpl.
    rewrite (CRabs_right (R := R) (CR_of_Q R Q1q) (CRle_0_one (R := R))).
    reflexivity.
  - simpl.
    rewrite (CRabs_mult (R := R) x (CRpow x n)).
    rewrite IH.
    reflexivity.
Qed.

(* CRplus 左保序（≤ 版，自建；库只有 < 版） *)
Lemma CRplus_le_compat_l {R : ConstructiveReals} (r r1 r2 : CRcarrier R)
  (H : CRle R r1 r2) : CRle R (CRplus R r r1) (CRplus R r r2).
Proof.
  unfold CRle. intro H'.
  apply H.
  exact (CRplus_lt_reg_l R r r2 r1 H').
Qed.

(* 0 < -b ⟹ b < 0 *)
Lemma CRlt_opp_0 {R : ConstructiveReals} (b : CRcarrier R) :
  CRlt R (CR_of_Q R Q0q) (CRopp R b) -> CRlt R b (CR_of_Q R Q0q).
Proof.
  intro H.
  (* H : 0 < -b。由 CRplus_lt_reg_l（左加 -b）：(-b)+b < (-b)+0 ⟹ b < 0。
     改写 (-b)+b == 0、(-b)+0 == -b 后即得 H。 *)
  apply (CRplus_lt_reg_l R (CRopp R b) b (CR_of_Q R Q0q)).
  rewrite (CRplus_opp_l b).
  rewrite (CRplus_0_r (R := R) (CRopp R b)).
  exact H.
Qed.

(* 0 ≤ b ⟹ -b ≤ 0 *)
Lemma CRopp_le_compat {R : ConstructiveReals} (b : CRcarrier R)
  (Hb0 : CRle R (CR_of_Q R Q0q) b) :
  CRle R (CRopp R b) (CR_of_Q R Q0q).
Proof.
  unfold CRle. intro H.
  apply Hb0.
  exact (CRlt_opp_0 (R := R) b H).
Qed.

(* 0 ≤ b ⟹ a - b ≤ a *)
Lemma CRle_minus_compat {R : ConstructiveReals} (a b : CRcarrier R)
  (Hb0 : CRle R (CR_of_Q R Q0q) b) :
  CRle R (CRminus R a b) a.
Proof.
  unfold CRminus.
  eapply CRle_trans.
  - apply (CRplus_le_compat_l (R := R) a (CRopp R b) (CR_of_Q R Q0q)).
    exact (CRopp_le_compat (R := R) b Hb0).
  - rewrite (CRplus_0_r (R := R) a). apply CRle_refl.
Qed.

(* x - 0 == x *)
Lemma CRminus_0_r {R : ConstructiveReals} (x : CRcarrier R) :
  CReq R (CRminus R x (CR_of_Q R Q0q)) x.
Proof.
  unfold CRminus.
  rewrite (CRopp_0 (R := R)).
  rewrite (CRplus_0_r (R := R) x).
  reflexivity.
Qed.

(* CR_of_Q 保 Qeq（Qeq 是交叉乘积的 Z 相等 ⟹ 双向 Qle ⟹ 双向 CRle） *)
Lemma CR_of_Q_Qeq {R : ConstructiveReals} (q r : Q) (H : Qeq q r) :
  CReq R (CR_of_Q R q) (CR_of_Q R r).
Proof.
  unfold CReq. split.
  - apply (CR_of_Q_le (R := R) r q). unfold Qle. unfold Qeq in H. lia.
  - apply (CR_of_Q_le (R := R) q r). unfold Qle. unfold Qeq in H. lia.
Qed.

(* 2·(1/2) == 1 *)
Lemma CR_of_Q_two_half {R : ConstructiveReals} :
  CReq R (CRmult R (CR_of_Q R Qtwoq) (CR_of_Q R Qhalfq)) (CR_of_Q R Q1q).
Proof.
  rewrite <- (CR_of_Q_mult R Qtwoq Qhalfq).
  apply CR_of_Q_Qeq.
  unfold Qeq, Qmult, Qhalfq, Qtwoq, Q1q. compute. reflexivity.
Qed.

(* 1 - 1/2 == 1/2 *)
Lemma CR_of_Q_half_minus {R : ConstructiveReals} :
  CReq R (CRminus R (CR_of_Q R Q1q) (CR_of_Q R Qhalfq)) (CR_of_Q R Qhalfq).
Proof.
  unfold CRminus, Qhalfq, Q1q.
  rewrite <- (CR_of_Q_opp (R := R) (Qmake (Zpos xH) (Pos.of_succ_nat 1))).
  rewrite <- (CR_of_Q_plus R (Qmake (Zpos xH) (Pos.of_succ_nat 0))
                            (Qopp (Qmake (Zpos xH) (Pos.of_succ_nat 1)))).
  reflexivity.
Qed.

(* 0 ≤ 2 *)
Lemma CRle_0_two {R : ConstructiveReals} : CRle R (CR_of_Q R Q0q) (CR_of_Q R Qtwoq).
Proof.
  apply CRlt_asym. apply CR_of_Q_pos.
  unfold Qtwoq. compute. reflexivity.
Qed.

(* 0 ≤ 1/2 *)
Lemma CRle_0_half {R : ConstructiveReals} : CRle R (CR_of_Q R Q0q) (CR_of_Q R Qhalfq).
Proof.
  apply CRlt_asym. apply CR_of_Q_pos.
  unfold Qhalfq. compute. reflexivity.
Qed.

(* x·(-y) == -(x·y)（由 (-x)·y == -(x·y) 与交换律推出） *)
Lemma CRopp_mult_r_morph {R : ConstructiveReals} (x y : CRcarrier R) :
  CReq R (CRmult R x (CRopp R y)) (CRopp R (CRmult R x y)).
Proof.
  rewrite (CRmult_comm (R := R) x (CRopp R y)).
  rewrite (CRmult_comm (R := R) x y).
  apply (CRopp_mult_l_morph (R := R) y x).
Qed.

(* a·x - a·y == a·(x - y) *)
Lemma CRmult_minus_distr_l {R : ConstructiveReals} (a x y : CRcarrier R) :
  CReq R (CRminus R (CRmult R a x) (CRmult R a y)) (CRmult R a (CRminus R x y)).
Proof.
  unfold CRminus.
  rewrite <- (CRopp_mult_r_morph (R := R) a y).
  rewrite <- (CRmult_plus_distr_l (R := R) a x (CRopp R y)).
  reflexivity.
Qed.

(* (1 - a) - (1 - b) == b - a（纯环代数） *)
Lemma CRminus_minus_morph {R : ConstructiveReals} (a b : CRcarrier R) :
  CReq R (CRminus R (CRminus R (CR_of_Q R Q1q) a) (CRminus R (CR_of_Q R Q1q) b))
         (CRminus R b a).
Proof.
  unfold CRminus.
  rewrite (CRopp_plus_distr (R := R) (CR_of_Q R Q1q) (CRopp R b)).
  rewrite (CRopp_involutive (R := R) b).
  (* (1 + -a) + (-1 + b) == b + -a *)
  rewrite <- (CRplus_assoc (R := R) (CRplus R (CR_of_Q R Q1q) (CRopp R a))
                            (CRopp R (CR_of_Q R Q1q)) b).
  rewrite (CRplus_assoc (R := R) (CR_of_Q R Q1q) (CRopp R a) (CRopp R (CR_of_Q R Q1q))).
  rewrite (CRplus_comm (R := R) (CRopp R a) (CRopp R (CR_of_Q R Q1q))).
  rewrite <- (CRplus_assoc (R := R) (CR_of_Q R Q1q) (CRopp R (CR_of_Q R Q1q)) (CRopp R a)).
  rewrite (CRplus_opp_r (R := R) (CR_of_Q R Q1q)).
  rewrite (CRplus_0_l (R := R) (CRopp R a)).
  rewrite (CRplus_comm (R := R) (CRopp R a) b).
  reflexivity.
Qed.

(* 2·(1/2)^(S m) == (1/2)^m *)
Lemma CR_of_Q_half_double {R : ConstructiveReals} (m : nat) :
  CReq R (CRmult R (CR_of_Q R Qtwoq) (CRpow (CR_of_Q R Qhalfq) (S m)))
         (CRpow (CR_of_Q R Qhalfq) m).
Proof.
  change (CRpow (CR_of_Q R Qhalfq) (S m))
    with (CRmult R (CR_of_Q R Qhalfq) (CRpow (CR_of_Q R Qhalfq) m)).
  rewrite <- (CRmult_assoc (R := R) (CR_of_Q R Qtwoq) (CR_of_Q R Qhalfq) (CRpow (CR_of_Q R Qhalfq) m)).
  rewrite (CR_of_Q_two_half (R := R)).
  rewrite CRmult_1_l.
  reflexivity.
Qed.

(* Σ_{k=0}^{m} (1/2)^k == 2·(1 - (1/2)^{m+1}) —— 闭式（geom_partial_closed 特化） *)
Lemma geom_sum_half_closed {R : ConstructiveReals} (m : nat) :
  CReq R (CRsum (fun k => CRpow (CR_of_Q R Qhalfq) k) m)
         (CRmult R (CR_of_Q R Qtwoq)
                  (CRminus R (CR_of_Q R Q1q) (CRpow (CR_of_Q R Qhalfq) (S m)))).
Proof.
  (* (1/2)·Σ == 1 - h^{S m}：由 geom_partial_closed 与 (1-1/2)==1/2 双向 ≤ 构造
     （避免 setoid 改写——CRpow 内嵌 1/2 的 Proper 实例未注册） *)
  assert (H : CReq R (CRmult R (CR_of_Q R Qhalfq)
                               (CRsum (fun k => CRpow (CR_of_Q R Qhalfq) k) m))
                      (CRminus R (CR_of_Q R Q1q) (CRpow (CR_of_Q R Qhalfq) (S m)))).
  { pose (G := geom_partial_closed (R := R) (CR_of_Q R Qhalfq) m).
    pose (Hm := CR_of_Q_half_minus (R := R)).
    destruct G as [GRL GLR]. destruct Hm as [Hmc Hm].
    assert (Hpos : CRle R (CR_of_Q R Q0q)
                        (CRsum (fun k => CRpow (CR_of_Q R Qhalfq) k) m)).
    { apply cond_pos_sum. intro k. exact (CRpow_ge_zero (CR_of_Q R Qhalfq) k (CRle_0_half (R := R))). }
    unfold CReq. split.
    - (* (1 - h^{S m}) ≤ (1/2)·Σ：经 L = (1-1/2)·Σ *)
      apply (CRle_trans (R := R) (CRminus R (CR_of_Q R Q1q) (CRpow (CR_of_Q R Qhalfq) (S m)))
                         (CRmult R (CRminus R (CR_of_Q R Q1q) (CR_of_Q R Qhalfq))
                                   (CRsum (fun k => CRpow (CR_of_Q R Qhalfq) k) m))
                         (CRmult R (CR_of_Q R Qhalfq)
                                  (CRsum (fun k => CRpow (CR_of_Q R Qhalfq) k) m))).
      + exact GRL.
      + apply (CRmult_le_compat_r (CRsum (fun k => CRpow (CR_of_Q R Qhalfq) k) m)
                                  (CRminus R (CR_of_Q R Q1q) (CR_of_Q R Qhalfq))
                                  (CR_of_Q R Qhalfq)).
        * exact Hpos.
        * exact Hm.
    - (* (1/2)·Σ ≤ (1 - h^{S m})：经 L *)
      apply (CRle_trans (R := R) (CRmult R (CR_of_Q R Qhalfq)
                                  (CRsum (fun k => CRpow (CR_of_Q R Qhalfq) k) m))
                         (CRmult R (CRminus R (CR_of_Q R Q1q) (CR_of_Q R Qhalfq))
                                   (CRsum (fun k => CRpow (CR_of_Q R Qhalfq) k) m))
                         (CRminus R (CR_of_Q R Q1q) (CRpow (CR_of_Q R Qhalfq) (S m)))).
      + apply (CRmult_le_compat_r (CRsum (fun k => CRpow (CR_of_Q R Qhalfq) k) m)
                                  (CR_of_Q R Qhalfq)
                                  (CRminus R (CR_of_Q R Q1q) (CR_of_Q R Qhalfq))).
        * exact Hpos.
        * exact Hmc.
      + exact GLR.
  }
  (* 两边乘 2：2·((1/2)·Σ) == 2·(1 - h^{S m}) *)
  pose (H2 := CRmult_eq_compat_l (R := R) (CR_of_Q R Qtwoq)
             (CRmult R (CR_of_Q R Qhalfq) (CRsum (fun k => CRpow (CR_of_Q R Qhalfq) k) m))
             (CRminus R (CR_of_Q R Q1q) (CRpow (CR_of_Q R Qhalfq) (S m)))
             (CRle_0_two (R := R)) H).
  (* 目标 Σ == 2(1-h^{S m})：先证 Σ == 2·(1/2·Σ)（H3，对 1/2 左消去），再与 H2 合并 *)
  assert (H3 : CReq R (CRsum (fun k => CRpow (CR_of_Q R Qhalfq) k) m)
                       (CRmult R (CR_of_Q R Qtwoq)
                                (CRmult R (CR_of_Q R Qhalfq) (CRsum (fun k => CRpow (CR_of_Q R Qhalfq) k) m)))).
  { assert (Hq : Qlt Q0q Qhalfq).
    { unfold Qhalfq. compute. reflexivity. }
    apply (CRmult_eq_reg_l (R := R) (CR_of_Q R Qhalfq)
            (CRsum (fun k => CRpow (CR_of_Q R Qhalfq) k) m)
            (CRmult R (CR_of_Q R Qtwoq)
                     (CRmult R (CR_of_Q R Qhalfq) (CRsum (fun k => CRpow (CR_of_Q R Qhalfq) k) m)))
            (inr (CR_of_Q_pos (R := R) Qhalfq Hq))).
    (* 目标：1/2·Σ == 1/2·(2·(1/2·Σ))。改写右端：== (2·1/2)·(1/2·Σ) == 1·(1/2·Σ) == 1/2·Σ *)
    rewrite <- (CRmult_assoc (R := R) (CR_of_Q R Qhalfq) (CR_of_Q R Qtwoq)
                             (CRmult R (CR_of_Q R Qhalfq) (CRsum (fun k => CRpow (CR_of_Q R Qhalfq) k) m))).
    rewrite (CRmult_comm (R := R) (CR_of_Q R Qhalfq) (CR_of_Q R Qtwoq)).
    rewrite (CR_of_Q_two_half (R := R)).
    rewrite CRmult_1_l.
    reflexivity.
  }
  rewrite H3.
  exact H2.
Qed.

(* Σ_{k=0}^{m} (1/2)^k ≤ 2 *)
Lemma geom_sum_half_le {R : ConstructiveReals} (m : nat) :
  CRle R (CRsum (fun k => CRpow (CR_of_Q R Qhalfq) k) m) (CR_of_Q R Qtwoq).
Proof.
  rewrite (geom_sum_half_closed (R := R) m).
  (* 2·(1 - h^{S m}) ≤ 2：夹到 2·1 —— 2·(1-h^{S m}) ≤ 2·1 ≤ 2 *)
  eapply CRle_trans.
  - apply (CRmult_le_compat_l (CR_of_Q R Qtwoq)
          (CRminus R (CR_of_Q R Q1q) (CRpow (CR_of_Q R Qhalfq) (S m)))
          (CR_of_Q R Q1q)).
    + exact (CRle_0_two (R := R)).
    + apply (CRle_minus_compat (R := R) (CR_of_Q R Q1q) (CRpow (CR_of_Q R Qhalfq) (S m))).
      exact (CRpow_ge_zero (CR_of_Q R Qhalfq) (S m) (CRle_0_half (R := R))).
  - rewrite (CRmult_1_r (R := R) (CR_of_Q R Qtwoq)). apply CRle_refl.
Qed.

(* Σh (max n p) - Σh (min n p) ≤ (1/2)^{min n p} —— 柯西尾部界 *)
Lemma geom_sum_half_diff {R : ConstructiveReals} (n p : nat) :
  CRle R (CRminus R (CRsum (fun k => CRpow (CR_of_Q R Qhalfq) k) (Nat.max n p))
                      (CRsum (fun k => CRpow (CR_of_Q R Qhalfq) k) (Nat.min n p)))
         (CRpow (CR_of_Q R Qhalfq) (Nat.min n p)).
Proof.
  rewrite (geom_sum_half_closed (R := R) (Nat.max n p)).
  rewrite (geom_sum_half_closed (R := R) (Nat.min n p)).
  rewrite (CRmult_minus_distr_l (R := R) (CR_of_Q R Qtwoq)
            (CRminus R (CR_of_Q R Q1q) (CRpow (CR_of_Q R Qhalfq) (S (Nat.max n p))))
            (CRminus R (CR_of_Q R Q1q) (CRpow (CR_of_Q R Qhalfq) (S (Nat.min n p))))).
  rewrite (CRminus_minus_morph (R := R) (CRpow (CR_of_Q R Qhalfq) (S (Nat.max n p)))
                                (CRpow (CR_of_Q R Qhalfq) (S (Nat.min n p)))).
  rewrite <- (CR_of_Q_half_double (R := R) (Nat.min n p)).
  apply (CRmult_le_compat_l (CR_of_Q R Qtwoq)
          (CRminus R (CRpow (CR_of_Q R Qhalfq) (S (Nat.min n p)))
                   (CRpow (CR_of_Q R Qhalfq) (S (Nat.max n p))))
          (CRpow (CR_of_Q R Qhalfq) (S (Nat.min n p)))).
  - exact (CRle_0_two (R := R)).
  - apply (CRle_minus_compat (R := R) (CRpow (CR_of_Q R Qhalfq) (S (Nat.min n p)))
                              (CRpow (CR_of_Q R Qhalfq) (S (Nat.max n p)))).
    exact (CRpow_ge_zero (CR_of_Q R Qhalfq) (S (Nat.max n p)) (CRle_0_half (R := R))).
Qed.

(* |x| ≤ 1/2 ⟹ x < 1（x ≤ |x| ≤ 1/2 < 1） *)
Lemma geom_x_lt_one {R : ConstructiveReals} (x : CRcarrier R)
  (Hx : CRle R (CRabs R x) (CR_of_Q R Qhalfq)) :
  CRlt R x (CR_of_Q R Q1q).
Proof.
  apply (CRle_lt_trans (R := R) x (CRabs R x) (CR_of_Q R Q1q)).
  - exact (CRle_abs (R := R) x).
  - apply (CRle_lt_trans (R := R) (CRabs R x) (CR_of_Q R Qhalfq) (CR_of_Q R Q1q)).
    + exact Hx.
    + apply CR_of_Q_lt. unfold Qhalfq, Q1q. compute. reflexivity.
Qed.

(* |x| ≤ 1/2 ⟹ x^n → 0（GeoCvZero 显式模 + |x^n| == |x|^n ≤ (1/2)^n） *)
Lemma geom_pow_zero {R : ConstructiveReals} (x : CRcarrier R)
  (Hx : CRle R (CRabs R x) (CR_of_Q R Qhalfq)) :
  CR_cv R (fun n => CRpow x n) (CR_of_Q R Q0q).
Proof.
  intro p.
  destruct (GeoCvZero (R := R) p) as [N HN].
  exists N.
  intro i. intro Hi.
  eapply CRle_trans.
  - rewrite (CRminus_0_r (R := R) (CRpow x i)).
    rewrite (CRabs_pow (R := R) x i).
    apply CRle_refl.
  - eapply CRle_trans.
    + apply (CRpow_le_compat (R := R) (CRabs R x) (CR_of_Q R Qhalfq) i).
      * exact (CRabs_pos (R := R) x).
      * exact (CRle_0_half (R := R)).
      * exact Hx.
    + have HNi := HN i Hi.
      rewrite (CRminus_0_r (R := R) (CRpow (CR_of_Q R Qhalfq) i)) in HNi.
      rewrite (CRabs_right (R := R) (CRpow (CR_of_Q R Qhalfq) i)
               (CRpow_ge_zero (CR_of_Q R Qhalfq) i (CRle_0_half (R := R)))) in HNi.
      exact HNi.
Qed.

(* |x| ≤ 1/2 ⟹ Σ_k |x^k| 柯西（Abs_sum_maj + 闭式尾部界 + GeoCvZero 模） *)
Lemma geom_abs_cauchy {R : ConstructiveReals} (x : CRcarrier R)
  (Hx : CRle R (CRabs R x) (CR_of_Q R Qhalfq)) :
  CR_cauchy R (CRsum (fun k => CRabs R (CRpow x k))).
Proof.
  intro p.
  destruct (GeoCvZero (R := R) p) as [N HN].
  exists N.
  intros i j Hi Hj.
  assert (Hc : forall n : nat,
          CRle R (CRabs R (CRabs R (CRpow x n))) (CRpow (CR_of_Q R Qhalfq) n)).
  { intro n.
    rewrite (CRabs_right (R := R) (CRabs R (CRpow x n)) (CRabs_pos (R := R) (CRpow x n))).
    rewrite (CRabs_pow (R := R) x n).
    apply (CRpow_le_compat (R := R) (CRabs R x) (CR_of_Q R Qhalfq) n).
    - exact (CRabs_pos (R := R) x).
    - exact (CRle_0_half (R := R)).
    - exact Hx.
  }
  pose (Hb := Abs_sum_maj (R := R) (fun k => CRabs R (CRpow x k))
                           (fun k => CRpow (CR_of_Q R Qhalfq) k) Hc i j).
  eapply CRle_trans.
  - exact Hb.
  - eapply CRle_trans.
    + exact (geom_sum_half_diff (R := R) i j).
    + have Hmin : (N <= Nat.min i j)%coq_nat.
      { exact (Nat.min_glb i j N Hi Hj). }
      have HNi := HN (Nat.min i j) Hmin.
      rewrite (CRminus_0_r (R := R) (CRpow (CR_of_Q R Qhalfq) (Nat.min i j))) in HNi.
      rewrite (CRabs_right (R := R) (CRpow (CR_of_Q R Qhalfq) (Nat.min i j))
               (CRpow_ge_zero (CR_of_Q R Qhalfq) (Nat.min i j) (CRle_0_half (R := R)))) in HNi.
      exact HNi.
Qed.

(* 主引理：|x| ≤ 1/2 ⟹ Σ x^k 收敛，极限 (1-x)^{-1}（纯构造性） *)
Lemma geom_series_cv {R : ConstructiveReals} (x : CRcarrier R)
  (Hx : CRle R (CRabs R x) (CR_of_Q R Qhalfq)) :
  { l : CRcarrier R & prod (series_cv (fun k => CRpow x k) l)
                           (CReq R l (CRinv R (CRminus R (CR_of_Q R Q1q) x)
                          (inr (CRlt_minus (R := R) x (CR_of_Q R Q1q) (geom_x_lt_one (R := R) x Hx))))) }.
Proof.
  pose (Hap := (inr (CRlt_minus (R := R) x (CR_of_Q R Q1q) (geom_x_lt_one (R := R) x Hx))
                : CRapart R (CRminus R (CR_of_Q R Q1q) x) (CR_of_Q R Q0q))).
  pose (Habs := series_cv_abs (R := R) (fun k => CRpow x k) (geom_abs_cauchy (R := R) x Hx)).
  destruct Habs as [l Hl].
  (* (1-x)·S_K → l·(1-x)（scale + 交换律） *)
  pose (Hscale := CR_cv_scale (R := R) (CRsum (fun k => CRpow x k))
                               (CRminus R (CR_of_Q R Q1q) x) l Hl).
  pose (Hscale' := CR_cv_extens (R := R)
                     (fun K : nat => CRmult R (CRsum (fun k => CRpow x k) K) (CRminus R (CR_of_Q R Q1q) x))
                     (fun K : nat => CRmult R (CRminus R (CR_of_Q R Q1q) x) (CRsum (fun k => CRpow x k) K))
                     (CRmult R l (CRminus R (CR_of_Q R Q1q) x))
                     (fun K : nat => CRmult_comm (R := R) (CRsum (fun k => CRpow x k) K) (CRminus R (CR_of_Q R Q1q) x))
                     Hscale).
  (* (1-x)·S_K → 1（闭式 + x^{S K} → 0） *)
  (* x^{S n} → 0：由 geom_pow_zero（x^n → 0）移位；
     注意 CR_cv_shift' 给出 (n + 1)%coq_nat，需与文件内 S n（mathcomp 记法）桥接 *)
  pose (Hpow0raw := CR_cv_shift' (R := R) (fun n => CRpow x n) 1 (CR_of_Q R Q0q) (geom_pow_zero (R := R) x Hx)).
  assert (Hext : forall n : nat, CReq R (CRpow x (n + 1)%coq_nat) (CRpow x (S n))).
  { intro n. rewrite (Nat.add_1_r n). reflexivity. }
  pose (Hpow0 := CR_cv_eq (R := R) (fun n : nat => CRpow x (S n))
                            (fun n : nat => CRpow x (n + 1)%coq_nat)
                            (CR_of_Q R Q0q) Hext Hpow0raw).
  pose (Hcon := CR_cv_const (R := R) (CR_of_Q R Q1q)).
  pose (Hminus := CR_cv_minus (R := R) (fun _ : nat => CR_of_Q R Q1q)
                               (fun n : nat => CRpow x (S n))
                               (CR_of_Q R Q1q) (CR_of_Q R Q0q) Hcon Hpow0).
  pose (Hproper := CR_cv_proper (R := R) (fun n : nat => CRminus R (CR_of_Q R Q1q) (CRpow x (S n)))
                                  (CRminus R (CR_of_Q R Q1q) (CR_of_Q R Q0q))
                                  (CR_of_Q R Q1q) Hminus (CRminus_0_r (R := R) (CR_of_Q R Q1q))).
  pose (Hclose := fun K : nat => geom_partial_closed (R := R) x K).
  pose (Hcv1 := CR_cv_eq (R := R)
                 (fun K : nat => CRmult R (CRminus R (CR_of_Q R Q1q) x) (CRsum (fun k => CRpow x k) K))
                 (fun K : nat => CRminus R (CR_of_Q R Q1q) (CRpow x (S K)))
                 (CR_of_Q R Q1q)
                 (fun K : nat => match Hclose K with conj H1 H2 => conj H2 H1 end)
                 Hproper).
  (* l·(1-x) == 1（极限唯一） *)
  pose (Huniq := CR_cv_unique (R := R)
                   (fun K : nat => CRmult R (CRminus R (CR_of_Q R Q1q) x) (CRsum (fun k => CRpow x k) K))
                   (CRmult R l (CRminus R (CR_of_Q R Q1q) x))
                   (CR_of_Q R Q1q) Hscale' Hcv1).
  (* l == (1-x)^{-1}：l·(1-x) == 1 == (1-x)^{-1}·(1-x)，右消元 *)
  pose (Hinv := CRinv_l R (CRminus R (CR_of_Q R Q1q) x) Hap).
  pose (Heq := conj (CRle_trans (R := R) (CRmult R (CRinv R (CRminus R (CR_of_Q R Q1q) x) Hap)
                                         (CRminus R (CR_of_Q R Q1q) x))
                                  (CR_of_Q R Q1q)
                                  (CRmult R l (CRminus R (CR_of_Q R Q1q) x))
                                  (proj2 Hinv) (proj1 Huniq))
                    (CRle_trans (R := R) (CRmult R l (CRminus R (CR_of_Q R Q1q) x))
                                  (CR_of_Q R Q1q)
                                  (CRmult R (CRinv R (CRminus R (CR_of_Q R Q1q) x) Hap)
                                          (CRminus R (CR_of_Q R Q1q) x))
                                  (proj2 Huniq) (proj1 Hinv))).
  assert (Hap0 : CRapart R (CR_of_Q R Q0q) (CRminus R (CR_of_Q R Q1q) x)).
  { exact (match Hap with inl h => inr h | inr h => inl h end). }
  pose (Hcanc := CRmult_eq_reg_r (R := R) (CRminus R (CR_of_Q R Q1q) x) l
                    (CRinv R (CRminus R (CR_of_Q R Q1q) x) Hap) Hap0 Heq).
  exists l. split.
  - exact Hl.
  - exact Hcanc.
Qed.

(* ============================================================
   L2. 素数幂项：p 素数, s ≥ 1 ⟹ Σ_k (p^{-s})^k 收敛到 (1-p^{-s})^{-1}
   —— 直接应用 L1b（|p^{-s}| = (1/p)^s ≤ 1/p ≤ 1/2）。
   ============================================================ *)

(* 0 ≤ x ≤ 1 ⟹ x^n ≤ x^m（m ≤ n，幂随指数递减；L4 尾部界也用） *)
Lemma CRpow_decreasing_ge {R : ConstructiveReals} (x : CRcarrier R) (n m : nat)
  (Hx0 : CRle R (CR_of_Q R Q0q) x)
  (Hx1 : CRle R x (CR_of_Q R Q1q))
  (Hmn : (m <= n)%nat) :
  CRle R (CRpow x n) (CRpow x m).
Proof.
  (* n = m + (n - m)：x^n == x^m·x^{n-m} ≤ x^m·1 == x^m *)
  rewrite <- (subnKC Hmn).
  rewrite <- (CRpow_plus_distr (R := R) x m (n - m)).
  eapply CRle_trans.
  - apply (CRmult_le_compat_l (CRpow x m) (CRpow x (n - m)) (CR_of_Q R Q1q)).
    + exact (CRpow_ge_zero x m Hx0).
    + rewrite <- (CRpow_one (R := R) (n - m)).
      apply (CRpow_le_compat (R := R) x (CR_of_Q R Q1q) (n - m)).
      * exact Hx0.
      * exact (CRle_0_one (R := R)).
      * exact Hx1.
  - rewrite (CRmult_1_r (R := R) (CRpow x m)). apply CRle_refl.
Qed.

(* |(1/p)^s| == (1/p)^s（1/p > 0 ⟹ 非负，绝对值可去）
   用 ≤-pair 构造（避免 setoid 改写 CRpow Proper 未注册） *)
Lemma CRabs_inv_pow {R : ConstructiveReals} (p s : nat) :
  CReq R (CRabs R (inv_n_pow p s)) (inv_n_pow p s).
Proof.
  unfold inv_n_pow.
  (* x := CR_of_Q (Qinv_n p)；0 ≤ x；|x| == x *)
  assert (Hx0 : CRle R (CR_of_Q R Q0q) (CR_of_Q R (Qinv_n p))).
  { apply CR_of_Q_le. unfold Qinv_n, Q0q, Qle. simpl. lia. }
  assert (Habsx : CReq R (CRabs R (CR_of_Q R (Qinv_n p))) (CR_of_Q R (Qinv_n p))).
  { rewrite (CR_of_Q_abs (R := R) (Qinv_n p)).
    apply (CR_of_Q_Qeq (R := R) (Qabs.Qabs (Qinv_n p)) (Qinv_n p)).
    apply Qabs.Qabs_pos.
    unfold Qinv_n, Qle. simpl. lia. }
  (* |x^s| == |x|^s（CRabs_pow）== x^s：双向 ≤ *)
  unfold CReq. split.
  - (* x^s ≤ |x^s|：x^s ≤ |x|^s ≤ |x^s| *)
    eapply CRle_trans.
    + apply (CRpow_le_compat (R := R) (CR_of_Q R (Qinv_n p)) (CRabs R (CR_of_Q R (Qinv_n p))) s).
      * exact Hx0.
      * exact (CRabs_pos (R := R) (CR_of_Q R (Qinv_n p))).
      * exact (CRle_abs (R := R) (CR_of_Q R (Qinv_n p))).
    + exact (proj1 (CRabs_pow (R := R) (CR_of_Q R (Qinv_n p)) s)).
  - (* |x^s| ≤ x^s：|x^s| ≤ |x|^s ≤ x^s *)
    eapply CRle_trans.
    + exact (proj2 (CRabs_pow (R := R) (CR_of_Q R (Qinv_n p)) s)).
    + apply (CRpow_le_compat (R := R) (CRabs R (CR_of_Q R (Qinv_n p))) (CR_of_Q R (Qinv_n p)) s).
      * exact (CRabs_pos (R := R) (CR_of_Q R (Qinv_n p))).
      * exact Hx0.
      * exact (proj2 Habsx).
Qed.

(* Q 层：p ≥ 1 ⟹ 1/p ≤ 1 *)
Lemma Qinv_n_le_one (p : nat) (Hp1 : (1 <= p)%nat) : Qle (Qinv_n p) Q1q.
Proof.
  destruct p as [|p'].
  - exfalso. rewrite leqn0 in Hp1. discriminate.
  - unfold Qinv_n, Q1q, Qle. simpl. apply (Pos2Z.pos_le_pos xH (Pos.of_succ_nat p')). apply Pos.le_1_l.
Qed.

(* Q 层：p ≥ 2 ⟹ 1/p ≤ 1/2 *)
Lemma Qinv_n_le_half (p : nat) (Hp2 : (2 <= p)%nat) : Qle (Qinv_n p) Qhalfq.
Proof.
  destruct p as [|[|p']].
  - exfalso. rewrite leqn0 in Hp2. discriminate.
  - exfalso. simpl in Hp2. discriminate.
  - unfold Qinv_n, Qhalfq, Qle. simpl.
    apply (Pos2Z.pos_le_pos (xO xH) (Pos.of_succ_nat (S p'))).
    change (Pos.succ xH <= Pos.succ (Pos.of_succ_nat p'))%positive.
    apply (proj1 (Pos.succ_le_mono xH (Pos.of_succ_nat p'))). apply Pos.le_1_l.
Qed.

(* p 素数, s ≥ 1 ⟹ |p^{-s}| ≤ 1/2
   （|p^{-s}| == (1/p)^s ≤ (1/p)^1 == 1/p ≤ 1/2） *)
Lemma inv_prime_pow_le_half {R : ConstructiveReals} (p s : nat)
  (Hp : prime p) (Hs : (1 <= s)%nat) :
  CRle R (CRabs R (inv_n_pow p s)) (CR_of_Q R Qhalfq).
Proof.
  rewrite (CRabs_inv_pow (R := R) p s).
  eapply CRle_trans.
  - apply (CRpow_decreasing_ge (R := R) (CR_of_Q R (Qinv_n p)) s 1).
    + apply CR_of_Q_le. unfold Qinv_n, Qle. simpl. lia.
    + apply CR_of_Q_le. exact (Qinv_n_le_one p (prime_ge1 p Hp)).
    + exact Hs.
  - simpl.
    rewrite (CRmult_1_r (R := R) (CR_of_Q R (Qinv_n p))).
    apply CR_of_Q_le. exact (Qinv_n_le_half p (prime_gt1_mc p Hp)).
Qed.

(* 主引理 L2：p 素数, s ≥ 1 ⟹ Σ_k (p^{-s})^k 收敛，极限 (1-p^{-s})^{-1} *)
Lemma prime_power_series {R : ConstructiveReals} (p s : nat)
  (Hp : prime p) (Hs : (1 <= s)%nat) :
  { l : CRcarrier R &
    prod (series_cv (fun k => CRpow (inv_n_pow p s) k) l)
         (CReq R l (CRinv R (CRminus R (CR_of_Q R Q1q) (inv_n_pow p s))
                          (inr (CRlt_minus (R := R) (inv_n_pow p s) (CR_of_Q R Q1q)
                                           (geom_x_lt_one (R := R) (inv_n_pow p s)
                                                          (inv_prime_pow_le_half (R := R) p s Hp Hs)))))) }.
Proof.
  exact (geom_series_cv (R := R) (inv_n_pow p s) (inv_prime_pow_le_half (R := R) p s Hp Hs)).
Qed.

(* ============================================================
   L3/L4 地基：ζ 级数收敛（s ≥ 2）
   —— Σ_{n≥1} n^{-s} 柯西收敛，尾部界 Σ_{n>A} n^{-s} ≤ 1/A（望远镜）。
   关键链：n^{-s} = (1/n)^s ≤ (1/n)^2 = 1/n² ≤ 1/(n(n-1)) = 1/(n-1) - 1/n。
   ============================================================ *)

(* Pos.of_succ_nat 单调（nat ≤ → positive ≤） *)
Lemma Pos_of_succ_nat_le (n m : nat) (Hnm : (n <= m)%nat) :
  (Pos.of_succ_nat n <= Pos.of_succ_nat m)%positive.
Proof.
  move/leP: Hnm => Hnm.
  induction Hnm as [| m' IH].
  - apply Pos.le_refl.
  - apply (Pos.le_trans _ (Pos.of_succ_nat m') _).
    + exact IHIH.
    + apply Pos.lt_le_incl. apply Pos.lt_succ_diag_r.
Qed.

(* Q 层：1/a ≤ 1/b ⟺ b ≤ a（a, b ≥ 1） *)
Lemma Qinv_n_le (a b : nat) (Ha : (1 <= a)%nat) (Hb : (1 <= b)%nat) :
  (b <= a)%nat -> Qle (Qinv_n a) (Qinv_n b).
Proof.
  intro Hba.
  destruct a as [|a'], b as [|b'].
  - exfalso. rewrite leqn0 in Ha. discriminate.
  - exfalso. rewrite leqn0 in Ha. discriminate.
  - (* a = S a', b = 0：1/(S a') ≤ 1/0 = 1（junk 值） *)
    unfold Qinv_n, Qle. simpl.
    apply (Pos2Z.pos_le_pos xH (Pos.of_succ_nat a')). apply Pos.le_1_l.
  - (* a = S a', b = S b' *)
    unfold Qinv_n, Qle. simpl.
    apply (Pos2Z.pos_le_pos (Pos.of_succ_nat b') (Pos.of_succ_nat a')).
    apply (Pos_of_succ_nat_le b' a'). exact Hba.
Qed.

(* k ≥ 1 ⟹ Z.to_pos (Z.of_nat k) = Pos.of_nat k *)
Lemma Zto_pos_of_nat (k : nat) (Hk : (1 <= k)%nat) :
  Z.to_pos (Z.of_nat k) = Pos.of_nat k.
Proof.
  destruct k as [|k'].
  - exfalso. rewrite leqn0 in Hk. discriminate.
  - rewrite <- (Pos.of_nat_succ k'). simpl. reflexivity.
Qed.

(* mathcomp (1 <= n) ⟹ n ≠ 0（stdlib） *)
Lemma one_le_neq0 (n : nat) (Hn : (1 <= n)%nat) : n <> 0%nat.
Proof.
  move=> Hn0. subst n. done.
Qed.

(* Q 层：1/(n·m) == 1/n · 1/m（n, m ≥ 1） *)
Lemma Qinv_n_mul (n m : nat) (Hn : (1 <= n)%nat) (Hm : (1 <= m)%nat) :
  Qeq (Qmult (Qinv_n n) (Qinv_n m)) (Qinv_n (n * m)).
Proof.
  unfold Qinv_n, Qmult, Qeq. simpl.
  rewrite (Zto_pos_of_nat (n * m) (leq_mul Hn Hm)).
  rewrite (Zto_pos_of_nat n Hn).
  rewrite (Zto_pos_of_nat m Hm).
  rewrite (Nat2Pos.inj_mul n m (one_le_neq0 n Hn) (one_le_neq0 m Hm)).
  reflexivity.
Qed.

(* Z.pos_sub (Pos.succ p) p = 1（分子 d2-d1 的化简） *)
Lemma Zpos_sub_succ (p : positive) : Z.pos_sub (Pos.succ p) p = 1%Z.
Proof.
  induction p as [p IH | p IH |].
  - simpl. rewrite IH. simpl. reflexivity.
  - simpl. rewrite Z.pos_sub_diag. simpl. reflexivity.
  - simpl. reflexivity.
Qed.

(* 望远镜项：n ≥ 2 ⟹ 1/(n(n-1)) == 1/(n-1) - 1/n（Q 层） *)
Lemma Qinv_n_telescope (n : nat) (Hn2 : (2 <= n)%nat) :
  Qeq (Qinv_n (n * (n - 1)))
      (Qplus (Qinv_n (n - 1)) (Qopp (Qinv_n n))).
Proof.
  destruct n as [|[|m]].
  - exfalso. rewrite leqn0 in Hn2. discriminate.
  - exfalso. simpl in Hn2. discriminate.
  - have Hp1 : (1 <= (S (S m)) * (S m))%nat := leq_mul (ltn0Sn (S m)) (ltn0Sn m).
    have Hp2 : (1 <= S m)%nat := ltn0Sn m.
    have Hp3 : (1 <= S (S m))%nat := ltn0Sn (S m).
    have Hnz : S m <> 0%nat := proj2 (Nat.neq_0_lt_0 (S m)) (Nat.lt_0_succ m).
    unfold Qinv_n, Qmult, Qplus, Qopp, Qeq.
    rewrite (Zto_pos_of_nat ((S (S m)) * (S m)) Hp1).
    rewrite (Zto_pos_of_nat (S m) Hp2).
    rewrite (Zto_pos_of_nat (S (S m)) Hp3).
    rewrite (Nat2Pos.inj_mul (S (S m)) (S m)
            (proj2 (Nat.neq_0_lt_0 (S (S m))) (Nat.lt_0_succ (S m))) Hnz).
    rewrite (Nat2Pos.inj_succ (S m) Hnz).
    rewrite (Pos.mul_comm (Pos.of_nat (S (S m))) (Pos.of_nat (S m))).
    simpl.
    rewrite (Zpos_sub_succ (Pos.of_nat (S m))).
    ring.
Qed.

(* ============================================================
   Part 1（续）：ζ 级数收敛 —— 望远镜和、尾部界、柯西、收敛
   ============================================================ *)

(* 代数：(a - b) + (b - c) == a - c（望远镜消中间项） *)
Lemma CRminus_add_cancel {R : ConstructiveReals} (a b c : CRcarrier R) :
  CReq R (CRplus R (CRminus R a b) (CRminus R b c)) (CRminus R a c).
Proof.
  unfold CRminus.
  rewrite (CRplus_assoc (R := R) a (CRopp R b) (CRplus R b (CRopp R c))).
  rewrite <- (CRplus_assoc (R := R) (CRopp R b) b (CRopp R c)).
  rewrite (CRplus_opp_l b).
  rewrite (CRplus_0_l (CRopp R c)).
  reflexivity.
Qed.

(* 移位望远镜和：Σ_{k=0}^{p} (1/(S A + k) - 1/(S (S A + k))) == 1/(S A) - 1/(S (S A + p)) *)
Lemma telescope_shift {R : ConstructiveReals} (A p : nat) :
  CReq R (CRsum (fun k : nat => CRminus R (CR_of_Q R (Qinv_n (S A + k)))
                                        (CR_of_Q R (Qinv_n (S (S A + k))))) p)
         (CRminus R (CR_of_Q R (Qinv_n (S A)))
                   (CR_of_Q R (Qinv_n (S (S A + p))))).
Proof.
  induction p as [|p IH].
  - simpl. rewrite (addn0 (S A)). reflexivity.
  - rewrite (addnS (S A) p).
    simpl.
    rewrite IH.
    (* term (S p) = 1/(S (S A + p)) - 1/(S (S (S A + p)))（addnS 已对齐指数）
       (1/(S A) - 1/(S (S A + p))) + (1/(S (S A + p)) - 1/(S (S (S A + p))))
       == 1/(S A) - 1/(S (S A + S p))；S (S A + S p) == S (S (S A + p)) *)
    rewrite (addnS (S A) p).
    apply (CRminus_add_cancel (R := R) (CR_of_Q R (Qinv_n (S A)))
                              (CR_of_Q R (Qinv_n (S (S A + p))))
                              (CR_of_Q R (Qinv_n (S (S (S A + p)))))).
Qed.

(* CRlt 0 b ⟹ CRle 0 b（CRle 是 CRlt 反向的否定式） *)
Lemma CRle_of_lt {R : ConstructiveReals} (b : CRcarrier R) :
  CRlt R (CR_of_Q R Q0q) b -> CRle R (CR_of_Q R Q0q) b.
Proof.
  intro H. unfold CRle. intro Hba.
  apply (CRlt_asym (R := R) (CR_of_Q R Q0q) b H Hba).
Qed.

(* 尾部差 ≤ 首项：Σ_{k=0}^{p} (1/(S (S N + k)) - 1/(S (S (S N + k)))) ≤ 1/(S (S N))
   —— telescope_shift (S N) 的闭式（proj2 方向）+ b ≥ 0 时 a - b ≤ a *)
Lemma zeta_tail_sum_le {R : ConstructiveReals} (N p : nat) :
  CRle R (CRsum (fun k : nat => CRminus R (CR_of_Q R (Qinv_n (S (S N + k))))
                                         (CR_of_Q R (Qinv_n (S (S (S N + k)))))) p)
         (CR_of_Q R (Qinv_n (S (S N)))).
Proof.
  eapply CRle_trans.
  - apply (proj2 (telescope_shift (R := R) (S N) p)).
  - apply (CRle_minus_compat (R := R) (CR_of_Q R (Qinv_n (S (S N))))
                                      (CR_of_Q R (Qinv_n (S (S (S N + p)))))).
    apply CRle_of_lt. apply CR_of_Q_inv_pos. exact (ltn0Sn (S (S N + p))).
Qed.

(* 差 == 尾部：S N ≤ M（stdlib le）⟹ Σ v M - Σ v N == Σ_{k=0}^{M-S N} v (S N + k)
   —— 全 stdlib nat 运算（%coq_nat），与库 sum_assoc 的 plus/minus 定义性一致；
     mathcomp addn/subn 与 stdlib plus/minus 非定义性相等，不可混用（卡点 #16 延伸） *)
Lemma CRsum_diff_tail {R : ConstructiveReals} (v : nat -> CRcarrier R) (N M : nat)
  (HNM : le (S N) M) :
  CReq R (CRminus R (CRsum v M) (CRsum v N))
         (CRsum (fun k : nat => v ((S N + k)%coq_nat)) ((M - S N)%coq_nat)).
Proof.
  have Hsplit : CReq R (CRsum v M)
          (CRplus R (CRsum v N) (CRsum (fun k : nat => v ((S N + k)%coq_nat)) ((M - S N)%coq_nat))).
  { have Hs0 := sum_assoc (R := R) v N ((M - S N)%coq_nat).
    rewrite (Nat.add_comm (S N) ((M - S N)%coq_nat)) in Hs0.
    rewrite (Nat.sub_add (S N) M HNM) in Hs0.
    exact Hs0.
  }
  unfold CRminus.
  rewrite Hsplit.
  rewrite (CRplus_assoc (R := R) (CRsum v N) (CRsum (fun k : nat => v ((S N + k)%coq_nat)) ((M - S N)%coq_nat)) (CRopp R (CRsum v N))).
  rewrite (CRplus_comm (R := R) (CRsum (fun k : nat => v ((S N + k)%coq_nat)) ((M - S N)%coq_nat)) (CRopp R (CRsum v N))).
  rewrite <- (CRplus_assoc (R := R) (CRsum v N) (CRopp R (CRsum v N)) (CRsum (fun k : nat => v ((S N + k)%coq_nat)) ((M - S N)%coq_nat))).
  rewrite (CRplus_opp_r (R := R) (CRsum v N)).
  rewrite (CRplus_0_l (R := R) (CRsum (fun k : nat => v ((S N + k)%coq_nat)) ((M - S N)%coq_nat))).
  reflexivity.
Qed.

(* 柯西尾部（max/min 版）：Σ v (max i j) - Σ v (min i j) ≤ 1/(S (S (min i j)))
   —— Abs_sum_maj 的输出形态；i = j 时尾部为 0 ≤ 正数 *)
Lemma zeta_tail_bound_v {R : ConstructiveReals} (i j : nat) :
  CRle R (CRminus R (CRsum (fun n => CRminus R (CR_of_Q R (Qinv_n (S n)))
                                           (CR_of_Q R (Qinv_n (S (S n))))) (Init.Nat.max i j))
                    (CRsum (fun n => CRminus R (CR_of_Q R (Qinv_n (S n)))
                                           (CR_of_Q R (Qinv_n (S (S n))))) (Init.Nat.min i j)))
         (CR_of_Q R (Qinv_n (S (S (Init.Nat.min i j))))).
Proof.
  destruct (le_lt_dec i j) as [Hij | Hji].
  - rewrite (Nat.max_r i j Hij).
    rewrite (Nat.min_l i j Hij).
    destruct (proj1 (Nat.lt_eq_cases i j) Hij) as [Hilt | Heq].
    + eapply CRle_trans.
      * apply (proj2 (CRsum_diff_tail (R := R) (fun n => CRminus R (CR_of_Q R (Qinv_n (S n)))
                                                            (CR_of_Q R (Qinv_n (S (S n))))) i j Hilt)).
      * apply (zeta_tail_sum_le (R := R) i ((j - S i)%N)).
    + rewrite Heq.
      eapply CRle_trans.
      * apply (proj2 (CRplus_opp_r (R := R) (CRsum (fun n => CRminus R (CR_of_Q R (Qinv_n (S n)))
                                                            (CR_of_Q R (Qinv_n (S (S n))))) j))).
      * apply CRle_of_lt. apply CR_of_Q_inv_pos. exact (ltn0Sn (S j)).
  - rewrite (Nat.max_l i j (Nat.lt_le_incl j i Hji)).
    rewrite (Nat.min_r i j (Nat.lt_le_incl j i Hji)).
    eapply CRle_trans.
    + apply (proj2 (CRsum_diff_tail (R := R) (fun n => CRminus R (CR_of_Q R (Qinv_n (S n)))
                                                          (CR_of_Q R (Qinv_n (S (S n))))) j i Hji)).
    + apply (zeta_tail_sum_le (R := R) j ((i - S j)%N)).
Qed.

(* ============================================================
   Part 1（续）：ζ 级数收敛 —— 尾部界
   对 s ≥ 2，|n^{-s}| ≤ 1/n² ≤ 1/(n(n-1))，后者望远镜。
   ============================================================ *)

(* n ≥ 2 ⟹ 1 ≤ n(n-1)（1 = 1·1 ≤ n·(n-1)：1≤n 且 1≤n-1） *)
Lemma Qmult1_ge1 (n : nat) (Hn2 : (2 <= n)%nat) : (1 <= n * (n - 1))%nat.
Proof.
  (* (1 <= k) 在 mathcomp 下即 (0 < k)。0 < n·(n-1) ⟺ 0 < n ∧ 0 < n-1。 *)
  rewrite muln_gt0. apply/andP. split.
  - exact (ltnW Hn2).
  - rewrite (subn_gt0 1 n). exact Hn2.
Qed.

(* n ≥ 2 ⟹ 1/n² ≤ 1/(n(n-1))（Q 层：n(n-1) ≤ n·n ⟹ 倒数反向） *)
Lemma Qinv_sq_le_telescope (n : nat) (Hn2 : (2 <= n)%nat) :
  Qle (Qinv_n (n * n)) (Qinv_n (n * (n - 1))).
Proof.
  apply (Qinv_n_le (n * n) (n * (n - 1))).
  - rewrite muln_gt0. apply/andP. split. exact (ltnW Hn2). exact (ltnW Hn2).
  - exact (Qmult1_ge1 n Hn2).
  - rewrite leq_mul2l. apply/orP. right. exact (leq_subr 1 n).
Qed.

(* n ≥ 1 ⟹ (1/n)^2 == 1/n²（CR 层，Qinv_n_mul 桥） *)
Lemma inv_n_pow_sq {R : ConstructiveReals} (n : nat) (Hn : (1 <= n)%nat) :
  CReq R (CRpow (CR_of_Q R (Qinv_n n)) 2) (CR_of_Q R (Qinv_n (n * n))).
Proof.
  simpl.
  rewrite (CRmult_1_r (R := R) (CR_of_Q R (Qinv_n n))).
  rewrite <- (CR_of_Q_mult R (Qinv_n n) (Qinv_n n)).
  apply (CR_of_Q_Qeq (R := R) (Qmult (Qinv_n n) (Qinv_n n)) (Qinv_n (n * n))).
  exact (Qinv_n_mul n n Hn Hn).
Qed.

(* n ≥ 2, s ≥ 2 ⟹ n^{-s} = (1/n)^s ≤ 1/n² *)
Lemma inv_n_pow_le_sq {R : ConstructiveReals} (n s : nat)
  (Hn2 : (2 <= n)%nat) (Hs2 : (2 <= s)%nat) :
  CRle R (inv_n_pow n s) (CR_of_Q R (Qinv_n (n * n))).
Proof.
  unfold inv_n_pow.
  eapply CRle_trans.
  - apply (CRpow_decreasing_ge (R := R) (CR_of_Q R (Qinv_n n)) s 2).
    + apply CR_of_Q_le. unfold Qinv_n, Qle. simpl. lia.
    + apply CR_of_Q_le. exact (Qinv_n_le n 1 (ltnW Hn2) (leqnn 1) (ltnW Hn2)).
    + exact Hs2.
  - (* (1/n)^2 ≤ 1/n²：先 ≤ 再 == *)
    eapply CRle_trans.
    + apply CRle_refl.
    + rewrite (inv_n_pow_sq (R := R) n (ltnW Hn2)). apply CRle_refl.
Qed.

(* |n^{-s}| ≤ 1/(n(n-1))（n≥2, s≥2） *)
Lemma zeta_tail_abs_le {R : ConstructiveReals} (n s : nat)
  (Hn2 : (2 <= n)%nat) (Hs2 : (2 <= s)%nat) :
  CRle R (CRabs R (inv_n_pow n s)) (CR_of_Q R (Qinv_n (n * (n - 1)))).
Proof.
  rewrite (CRabs_inv_pow (R := R) n s).
  unfold inv_n_pow.
  eapply CRle_trans.
  - apply (inv_n_pow_le_sq (R := R) n s Hn2 Hs2).
  - apply CR_of_Q_le. exact (Qinv_sq_le_telescope n Hn2).
Qed.

(* 小端尾部界：Σ_{k=1}^{N} |(S k)^{-s}| ≤ 1（s≥2；1/k² 望远镜部分和 < 2）
   —— 仅用于柯西尾部下界的辅助；实际柯西用 rest 界。 *)

(* 单点：|(S k)^{-s}| ≤ 1/k - 1/(S k)（正确望远镜配对：1/(k(k+1)) = 1/k - 1/(k+1)）
   主尾部界：A ≤ B ⟹ Σ_{k=A}^{B} |(S k)^{-s}| ≤ 1/A（telescope_unshift） *)

(* CR_of_Q 保 Q 减法：CR_of_Q (a - b) == CR_of_Q a - CR_of_Q b（CR 层桥）
   —— CR_of_Q 不是定义性环同态，Qminus 必须显式桥到 CRminus *)
Lemma CR_of_Q_minus {R : ConstructiveReals} (a b : Q) :
  CReq R (CR_of_Q R (Qminus a b))
         (CRminus R (CR_of_Q R a) (CR_of_Q R b)).
Proof.
  unfold Qminus, CRminus, CReq. split.
  - eapply CRle_trans.
    + apply (CRplus_le_compat_l (R := R) (CR_of_Q R a)
               (CRopp R (CR_of_Q R b)) (CR_of_Q R (Qopp b))).
      apply (proj1 (CR_of_Q_opp (R := R) b)).
    + apply (proj1 (CR_of_Q_plus R a (Qopp b))).
  - eapply CRle_trans.
    + apply (proj2 (CR_of_Q_plus R a (Qopp b))).
    + apply (CRplus_le_compat_l (R := R) (CR_of_Q R a)
               (CR_of_Q R (Qopp b)) (CRopp R (CR_of_Q R b))).
      apply (proj2 (CR_of_Q_opp (R := R) b)).
Qed.

(* Q 层：n ≥ 1 ⟹ 1/((S n)((S n)-1)) ≤ 1/n - 1/(S n)
   （destruct n 后 (S (S m)) - 1 对构造子可计算，Qinv_n_telescope 直接对齐；
     注意 mathcomp subn 在变量上不化简——不可在 destruct 前 rewrite） *)
Lemma Qinv_n_tail_term (n : nat) (Hn1 : (1 <= n)%nat) :
  Qle (Qinv_n ((S n) * ((S n) - 1))) (Qminus (Qinv_n n) (Qinv_n (S n))).
Proof.
  destruct n as [|m].
  - exfalso. rewrite leqn0 in Hn1. discriminate.
  - have Hsm2 : (2 <= S (S m))%nat := (leq_ltn_trans Hn1 (ltnSn (S m))).
    rewrite (Qinv_n_telescope (S (S m)) Hsm2).
    apply Qle_refl.
Qed.

(* 逐项 ≤：|(S n)^{-s}| ≤ 1/n - 1/(S n)（n ≥ 1, s ≥ 2；正确的望远镜配对）
   —— 注意：|(S n)^{-s}| 不可用 1/(S n) - 1/(S (S n)) 界（数学为假：
   1/(n+1)² ≥ 1/((n+1)(n+2))），必须配 1/n - 1/(S n)。 *)
Lemma zeta_tail_term_le {R : ConstructiveReals} (n s : nat) (Hs2 : (2 <= s)%nat)
  (Hn1 : (1 <= n)%nat) :
  CRle R (CRabs R (inv_n_pow (S n) s))
         (CRminus R (CR_of_Q R (Qinv_n n)) (CR_of_Q R (Qinv_n (S n)))).
Proof.
  have Hsn2 : (2 <= S n)%nat := (leq_ltn_trans Hn1 (ltnSn n)).
  (* |(S n)^{-s}| ≤ 1/((S n)((S n)-1)) == 1/n - 1/(S n) *)
  eapply CRle_trans.
  - apply (zeta_tail_abs_le (R := R) (S n) s Hsn2 Hs2).
  - eapply CRle_trans.
    + apply (CR_of_Q_le (R := R) (Qinv_n ((S n) * ((S n) - 1)))
                                 (Qminus (Qinv_n n) (Qinv_n (S n)))).
      exact (Qinv_n_tail_term n Hn1).
    + apply (proj2 (CR_of_Q_minus (R := R) (Qinv_n n) (Qinv_n (S n)))).
Qed.

(* ============================================================
   Part 1（续）：ζ 级数收敛 —— 柯西条件与收敛
   ============================================================ *)

(* 1/(S (S (Pos.to_nat p))) ≤ 1/p（Q 层；S(S(Pos.to_nat p)) 作为 positive = succ(succ p) ≥ p）
   —— CR_cauchy 的界是 CR_of_Q (1#p)，柯西取点 N = Pos.to_nat p 时收口 *)
Lemma Qinv_n_S2_to_nat_le (p : positive) :
  Qle (Qinv_n (S (S (Pos.to_nat p)))) (Qmake 1 p).
Proof.
  unfold Qinv_n, Qle. simpl.
  apply (Pos2Z.pos_le_pos p (Pos.succ (Pos.of_succ_nat (Pos.to_nat p)))).
  rewrite (Pos.of_nat_succ (Pos.to_nat p)).
  rewrite <- (Pos2Nat.inj_succ p).
  rewrite (Pos2Nat.id (Pos.succ p)).
  apply (Pos.le_trans p (Pos.succ p) (Pos.succ (Pos.succ p))).
  - apply Pos.lt_le_incl. exact (Pos.lt_succ_diag_r p).
  - apply Pos.lt_le_incl. exact (Pos.lt_succ_diag_r (Pos.succ p)).
Qed.

(* ζ 级数（项 2 起）的绝对值级数柯西：
   CRsum (fun n => |(S (S n))^{-s}|) 是柯西列（CR_cauchy，p 取 N = Pos.to_nat p）
   —— 镜像 geom_abs_cauchy：逐点界 zeta_tail_term_le + Abs_sum_maj +
     zeta_tail_bound_v + 1/(min+2) ≤ 1/(N+2) ≤ 1/p *)
Lemma zeta_abs_cauchy {R : ConstructiveReals} (s : nat) (Hs2 : (2 <= s)%nat) :
  CR_cauchy R (CRsum (fun n => CRabs R (inv_n_pow (S (S n)) s))).
Proof.
  intro p.
  exists (Pos.to_nat p).
  intros i j Hi Hj.
  assert (Hc : forall n : nat,
          CRle R (CRabs R (CRabs R (inv_n_pow (S (S n)) s)))
                 (CRminus R (CR_of_Q R (Qinv_n (S n))) (CR_of_Q R (Qinv_n (S (S n)))))).
  { intro n.
    rewrite (CRabs_right (R := R) (CRabs R (inv_n_pow (S (S n)) s))
                         (CRabs_pos (R := R) (inv_n_pow (S (S n)) s))).
    apply (zeta_tail_term_le (R := R) (S n) s Hs2 (ltn0Sn n)).
  }
  pose (Hb := Abs_sum_maj (R := R) (fun n => CRabs R (inv_n_pow (S (S n)) s))
                           (fun n => CRminus R (CR_of_Q R (Qinv_n (S n))) (CR_of_Q R (Qinv_n (S (S n))))) Hc i j).
  eapply CRle_trans.
  - exact Hb.
  - eapply CRle_trans.
    + apply (zeta_tail_bound_v (R := R) i j).
    + eapply CRle_trans.
      * apply (CR_of_Q_le (R := R) (Qinv_n (S (S (Init.Nat.min i j))))
                                   (Qinv_n (S (S (Pos.to_nat p))))).
        apply (Qinv_n_le (S (S (Init.Nat.min i j))) (S (S (Pos.to_nat p)))
                         (ltn0Sn (S (Init.Nat.min i j))) (ltn0Sn (S (Pos.to_nat p)))).
        apply/leP. apply le_n_S. apply le_n_S.
        exact (Nat.min_glb i j (Pos.to_nat p) Hi Hj).
      * apply (CR_of_Q_le (R := R) (Qinv_n (S (S (Pos.to_nat p)))) (Qmake 1 p)).
        exact (Qinv_n_S2_to_nat_le p).
Qed.

(* ζ 级数（项 2 起）收敛：Σ_{n≥0} (S (S n))^{-s}（s ≥ 2）
   —— 绝对收敛（series_cv_abs）⟹ 收敛（series_cv_abs_cv）
   ★ 可复用：ζ 部分和/主定理 L3/L4 的收敛性基础 *)
Lemma zeta_series_cv {R : ConstructiveReals} (s : nat) (Hs2 : (2 <= s)%nat) :
  { l : CRcarrier R & series_cv (fun n => inv_n_pow (S (S n)) s) l }.
Proof.
  exists (projT1 (series_cv_abs (R := R) (fun n => inv_n_pow (S (S n)) s)
                                 (zeta_abs_cauchy (R := R) s Hs2))).
  apply (series_cv_abs_cv (R := R) (fun n => inv_n_pow (S (S n)) s)
                           (zeta_abs_cauchy (R := R) s Hs2)).
Qed.

(* ============================================================
   L3 基础件：有限乘积 CRprod 与分布律
   （欧拉乘积 ∏_p (Σ_e p^{-es}) 的展开需要「乘积 × 和 = 逐项积之和」）
   ============================================================ *)

(* 有限乘积：CRprod f n = f 0 * f 1 * ... * f n（构造性实数的有限积） *)
Fixpoint CRprod {R : ConstructiveReals} (f : nat -> CRcarrier R) (n : nat) : CRcarrier R :=
  match n with
  | O => f O
  | S n' => CRmult R (CRprod f n') (f (S n'))
  end.

(* 有限乘积 ≥ 0：逐项 ≥ 0 ⟹ CRprod f n ≥ 0 *)
Lemma CRprod_ge_zero {R : ConstructiveReals} (f : nat -> CRcarrier R) (n : nat)
  (Hf : forall k, CRle R (CR_of_Q R Q0q) (f k)) :
  CRle R (CR_of_Q R Q0q) (CRprod f n).
Proof.
  induction n as [|n IH].
  - simpl. apply Hf.
  - simpl. apply (CRmult_le_0_compat (R := R) (CRprod f n) (f (S n)) IH (Hf (S n))).
Qed.

(* 分布律（核心）：(Σ_{i=0}^{N} f i) * x == Σ_{i=0}^{N} (f i * x) *)
Lemma CRsum_mult_r {R : ConstructiveReals} (f : nat -> CRcarrier R) (N : nat) (x : CRcarrier R) :
  CReq R (CRmult R (CRsum f N) x) (CRsum (fun i => CRmult R (f i) x) N).
Proof.
  induction N as [|N IH].
  - simpl. reflexivity.
  - simpl.
    rewrite (CRmult_plus_distr_r (R := R) x (CRsum f N) (f (S N))).
    rewrite IH.
    reflexivity.
Qed.

(* 乘入和（右）：x * (Σ f) == Σ (x * f i) *)
Lemma CRsum_mult_l {R : ConstructiveReals} (f : nat -> CRcarrier R) (N : nat) (x : CRcarrier R) :
  CReq R (CRmult R x (CRsum f N)) (CRsum (fun i => CRmult R x (f i)) N).
Proof.
  induction N as [|N IH].
  - simpl. reflexivity.
  - simpl.
    rewrite (CRmult_plus_distr_l (R := R) x (CRsum f N) (f (S N))).
    rewrite IH.
    reflexivity.
Qed.

(* 欧拉乘积展开的原子步：CRprod f N * (Σ_{e=0}^{M} g e) == Σ_e (CRprod f N * g e)
   —— 逐步乘入每个素因子（1-p^{-s})^{-1} = Σ_e p^{-es} 的和式 *)
Lemma CRprod_sum_expand {R : ConstructiveReals} (f : nat -> CRcarrier R) (N : nat)
  (g : nat -> CRcarrier R) (M : nat) :
  CReq R (CRmult R (CRprod f N) (CRsum g M))
         (CRsum (fun e => CRmult R (CRprod f N) (g e)) M).
Proof.
  apply (CRsum_mult_l (R := R) g M (CRprod f N)).
Qed.

(* K+1 重嵌套和：Σ_{e_K=0}^{E} ... Σ_{e_0=0}^{E} ∏_{i=0}^{K} f i e_i
   —— 展开等价于 ∏_{i=0}^{K} (Σ_{e=0}^{E} f i e)（CRprod_expand 归纳）
   ★ 可复用：欧拉乘积 ∏_p (Σ_e p^{-es}) 的展开骨架（指数元组和） *)
Fixpoint nested_prod_sum {R : ConstructiveReals} (f : nat -> nat -> CRcarrier R) (K E : nat) : CRcarrier R :=
  match K with
  | O => CRsum (fun e => f O e) E
  | S K' => CRsum (fun e => CRmult R (nested_prod_sum f K' E) (f (S K') e)) E
  end.

(* ∏_{i=0}^{K} (Σ_{e=0}^{E} f i e) == nested_prod_sum f K E
   —— 逐步乘入：IH + CRsum_mult_l 反向（Σ (x·f) == x·(Σ f)） *)
Lemma CRprod_expand {R : ConstructiveReals} (f : nat -> nat -> CRcarrier R) (K E : nat) :
  CReq R (CRprod (fun i => CRsum (fun e => f i e) E) K)
         (nested_prod_sum f K E).
Proof.
  induction K as [|K IH].
  - simpl. reflexivity.
  - simpl.
    rewrite IH.
    rewrite <- (CRsum_mult_l (R := R) (fun e => f (S K) e) E (nested_prod_sum f K E)).
    reflexivity.
Qed.

(* (n·m)^{-s} == n^{-s} · m^{-s}（s ≥ 0，n, m ≥ 1）
   —— smooth 数配对的核心项等式：n^{-s} · p^{-es} = (n·p^e)^{-s} *)
Lemma inv_n_pow_mult {R : ConstructiveReals} (n m s : nat)
  (Hn : (1 <= n)%nat) (Hm : (1 <= m)%nat) :
  CReq R (inv_n_pow (n * m) s) (CRmult R (inv_n_pow n s) (inv_n_pow m s)).
Proof.
  unfold inv_n_pow.
  rewrite (CRpow_mult (R := R) (CR_of_Q R (Qinv_n n)) (CR_of_Q R (Qinv_n m)) s).
  apply (CRpow_proper (R := R) (CR_of_Q R (Qinv_n (n * m)))
                                (CRmult R (CR_of_Q R (Qinv_n n)) (CR_of_Q R (Qinv_n m))) s).
  eapply CReq_trans.
  - apply (CR_of_Q_Qeq (R := R) (Qinv_n (n * m)) (Qmult (Qinv_n n) (Qinv_n m))).
    exact (Qeq_sym (Qmult (Qinv_n n) (Qinv_n m)) (Qinv_n (n * m)) (Qinv_n_mul n m Hn Hm)).
  - exact (CR_of_Q_mult R (Qinv_n n) (Qinv_n m)).
Qed.

(* 双重和分布律：(Σ_{i=0}^{N} f i) · (Σ_{j=0}^{M} g j) == Σ_{i=0}^{N} Σ_{j=0}^{M} (f i · g j)
   —— 欧拉乘积展开的核心：每步把新因子的和式乘入已展开的和式 *)
Lemma CRsum_mult_sum {R : ConstructiveReals} (f g : nat -> CRcarrier R) (N M : nat) :
  CReq R (CRmult R (CRsum f N) (CRsum g M))
         (CRsum (fun i => CRsum (fun j => CRmult R (f i) (g j)) M) N).
Proof.
  rewrite (CRsum_mult_r (R := R) f N (CRsum g M)).
  apply (CRsum_eq (R := R) (fun i => CRmult R (f i) (CRsum g M))
                            (fun i => CRsum (fun j => CRmult R (f i) (g j)) M) N).
  intros k Hk.
  apply (CRsum_mult_l (R := R) g M (f k)).
Qed.

(* 展开核心：Σ_{n=0}^{N} Σ_{e=0}^{E} (S n · p^e)^{-s}
      == (Σ_{n=0}^{N} (S n)^{-s}) · (Σ_{e=0}^{E} (p^e)^{-s})
   —— 分布律（CRsum_mult_sum）+ inv_n_pow_mult；L3 每步乘入新素因子 p 的代数核心 *)
Lemma geom_shift_expand {R : ConstructiveReals} (p s N E : nat) (Hp : (1 <= p)%nat) :
  CReq R (CRsum (fun n => CRsum (fun e => inv_n_pow (S n * p ^ e) s) E) N)
         (CRmult R (CRsum (fun n => inv_n_pow (S n) s) N)
                       (CRsum (fun e => inv_n_pow (p ^ e) s) E)).
Proof.
  rewrite (CRsum_mult_sum (R := R) (fun n => inv_n_pow (S n) s)
                           (fun e => inv_n_pow (p ^ e) s) N E).
  apply (CRsum_eq (R := R)
     (fun n => CRsum (fun e => inv_n_pow (S n * p ^ e) s) E)
     (fun n => CRsum (fun e => CRmult R (inv_n_pow (S n) s) (inv_n_pow (p ^ e) s)) E) N).
  intros n Hn.
  apply (CRsum_eq (R := R)
     (fun e => inv_n_pow (S n * p ^ e) s)
     (fun e => CRmult R (inv_n_pow (S n) s) (inv_n_pow (p ^ e) s)) E).
  intros e He.
  apply (inv_n_pow_mult (R := R) (S n) (p ^ e) s (ltn0Sn n)).
  rewrite expn_gt0. rewrite Hp. simpl. reflexivity.
Qed.

(* smooth 判定：n 的所有素因子 ≤ P（mathcomp primes = prime_decomp 的素数列表）
   —— L3 配对层的 smooth 数集合谓词；乘入保持引理（smooth_le_mul_pow）见交接文档 §L3 配对层 *)
Definition smooth_le (P n : nat) : bool :=
  all (fun p => (p <= P)%nat) (primes n).

(* p ≤ P、n smooth、p ∉ primes n、p 素数 ⟹ n·p^e smooth（乘入 p 保持）
   —— 配对「LHS 展开项 ⊆ RHS smooth 项」的一侧：
     q ∈ primes (n·p^e)：q = p ⟹ q ≤ P；q ≠ p ⟹ q ∤ p^e（素因子唯一）⟹
     Gauss 消去 q | n ⟹ q ∈ primes n ⟹ q ≤ P。
   —— 注意 mathcomp 引理（lognM/prime_coprime 等）的 nat 参数是命名隐式的，
     必须用 @ 全显式调用（Check 显示会误导）。 *)
Lemma smooth_le_mul_pow (P p n e : nat) (Hp : prime p) (HpP : (p <= P)%nat)
  (Hs : smooth_le P n) (Hpn : ~~ (p \in primes n)) : smooth_le P (n * p ^ e).
Proof.
  apply/allP. move => q Hq.
  rewrite mem_primes in Hq.
  move/andP : Hq => [Hqpr /andP [Hqpos Hqdvd]].
  destruct (Nat.eqb_spec q p) as [Heq | Hne].
  - move: Heq => ->. exact HpP.
  - have Hqcop_p : coprime q p.
    { rewrite (@prime_coprime q p Hqpr).
      rewrite (@dvdn_prime2 q p Hqpr Hp).
      apply/eqP. exact Hne. }
    have Hqcop : coprime q (p ^ e).
    { rewrite coprime_sym.
      apply (@coprimeXl e p q).
      rewrite coprime_sym. exact Hqcop_p. }
    have Hqdvdn : q %| n.
    { rewrite (mulnC n (p ^ e)%N) in Hqdvd.
      move: Hqdvd. rewrite (@Gauss_dvdr q (p ^ e)%N n Hqcop). exact id. }
    have Hqin : q \in primes n.
    { rewrite mem_primes. apply/andP. split. exact Hqpr. apply/andP. split.
      - rewrite muln_gt0 in Hqpos. destruct (andP Hqpos) as [Hqn0 _]. exact Hqn0.
      - exact Hqdvdn. }
    move: Hs. rewrite /smooth_le. move => /allP Hs'. exact (Hs' q Hqin).
Qed.

(* n·p^e smooth 且 p ∤ n（p 素数）⟹ n smooth（去掉 p 因子仍 smooth）
   —— 配对反向：q ∈ primes n ⟹ q | n ⟹ q | n·p^e ⟹ q ∈ primes (n·p^e) ⟹ q ≤ P *)
Lemma smooth_le_div_pow (P p n e : nat) (Hp : prime p)
  (Hs : smooth_le P (n * p ^ e)) (Hpn : ~~ (p %| n)) : smooth_le P n.
Proof.
  apply/allP. move => q Hq.
  rewrite mem_primes in Hq.
  move/andP : Hq => [Hqpr /andP [Hqn0 Hqdvd]].
  have Hqdvd' : q %| n * p ^ e.
  { rewrite (mulnC n (p ^ e)%N). apply (dvdn_mull (p ^ e)%N). exact Hqdvd. }
  have Hpe0 : (0 < p ^ e)%nat.
  { rewrite expn_gt0. rewrite (@prime_gt0 p Hp). simpl. reflexivity. }
  have Hqin : q \in primes (n * p ^ e).
  { rewrite mem_primes. apply/andP. split. exact Hqpr. apply/andP. split.
    - rewrite muln_gt0. apply/andP. split. exact Hqn0. exact Hpe0.
    - exact Hqdvd'. }
  move: Hs. rewrite /smooth_le. move => /allP Hs'. exact (Hs' q Hqin).
Qed.

(* 配对单射：p 素数、p∤n1、p∤n2 ⟹ n1·p^{e1} = n2·p^{e2} ⟹ n1 = n2 ∧ e1 = e2
   —— logn p 两侧：logn p (ni·p^{ei}) = logn p ni + ei·(p==p) = ei；
     再消去 p^{e1}（eqn_pmul2l）得 n1 = n2。这是 (n,e) ↦ n·p^e 双射的单射半边。 *)
Lemma smooth_pair_inj (p n1 n2 e1 e2 : nat) (Hp : prime p)
  (Hpn1 : ~~ (p %| n1)) (Hpn2 : ~~ (p %| n2))
  (H : (n1 * p ^ e1)%N = (n2 * p ^ e2)%N) : n1 = n2 /\ e1 = e2.
Proof.
  have Hn10 : (0 < n1)%nat.
  { destruct n1 as [|n1'].
    - exfalso. move/negP : Hpn1 => Hpn1'. apply Hpn1'. exact (dvdn0 p).
    - apply ltn0Sn. }
  have Hn20 : (0 < n2)%nat.
  { destruct n2 as [|n2'].
    - exfalso. move/negP : Hpn2 => Hpn2'. apply Hpn2'. exact (dvdn0 p).
    - apply ltn0Sn. }
  have Hpe10 : (0 < p ^ e1)%nat.
  { rewrite expn_gt0. rewrite (@prime_gt0 p Hp). simpl. reflexivity. }
  have Hpe20 : (0 < p ^ e2)%nat.
  { rewrite expn_gt0. rewrite (@prime_gt0 p Hp). simpl. reflexivity. }
  have Hcop1 : coprime p n1.
  { rewrite (@prime_coprime p n1 Hp). exact Hpn1. }
  have Hcop2 : coprime p n2.
  { rewrite (@prime_coprime p n2 Hp). exact Hpn2. }
  have Hlg1 : logn p (n1 * p ^ e1) = e1.
  { rewrite (@lognM p n1 (p ^ e1)%N Hn10 Hpe10).
    rewrite (@logn_coprime p n1 Hcop1).
    rewrite (@lognX p p e1).
    rewrite (@logn_prime p p Hp).
    rewrite eqxx. rewrite muln1. rewrite add0n. reflexivity. }
  have Hlg2 : logn p (n2 * p ^ e2) = e2.
  { rewrite (@lognM p n2 (p ^ e2)%N Hn20 Hpe20).
    rewrite (@logn_coprime p n2 Hcop2).
    rewrite (@lognX p p e2).
    rewrite (@logn_prime p p Hp).
    rewrite eqxx. rewrite muln1. rewrite add0n. reflexivity. }
  have Heq : logn p (n1 * p ^ e1) = logn p (n2 * p ^ e2).
  { rewrite H. reflexivity. }
  have Hlg : e1 = e2.
  { rewrite Hlg1 in Heq. rewrite Hlg2 in Heq. exact Heq. }
  have Hmul : (n1 * p ^ e1)%N = (n2 * p ^ e1)%N.
  { rewrite <- Hlg in H. exact H. }
  have Hn1n2 : n1 = n2.
  { apply/eqP.
    rewrite <- (@eqn_pmul2l (p ^ e1)%N n1 n2 Hpe10).
    apply/eqP.
    rewrite (mulnC (p ^ e1)%N n1) (mulnC (p ^ e1)%N n2).
    exact Hmul. }
  split; assumption.
Qed.

(* ============================================================
   L3 配对层（续）：smooth 数列表枚举与列表求和
   有限欧拉乘积 ∏_{p∈ps} (Σ_{e≤E} p^{-es}) == Σ_{x∈smooth_list E ps} x^{-s}
   ============================================================ *)

(* 列表求和（CR 层）：Σ_{x ∈ l} f x（元素类型泛化 A） *)
Fixpoint CRsum_list {R : ConstructiveReals} {A : Type} (f : A -> CRcarrier R) (l : seq A) : CRcarrier R :=
  match l with
  | [::] => CR_of_Q R Q0q
  | x :: xs => CRplus R (f x) (CRsum_list f xs)
  end.

(* 列表乘积（CR 层）：∏_{x ∈ l} f x（空积 = 1） *)
Fixpoint CRprod_list {R : ConstructiveReals} (f : nat -> CRcarrier R) (l : seq nat) : CRcarrier R :=
  match l with
  | [::] => CR_of_Q R Q1q
  | p :: ps => CRmult R (f p) (CRprod_list f ps)
  end.

(* 指数 ≤ E 且素因子 ⊆ ps 的数列表（递归构造；唯一分解保证元素互异）
   —— smooth_list E [] = [1]；smooth_list E (p::ps) = [x·p^e | x ∈ smooth_list E ps, e ≤ E] *)
Fixpoint smooth_list (E : nat) (ps : seq nat) : seq nat :=
  match ps with
  | [::] => [:: 1%nat]
  | p :: ps' => [seq (x * p ^ e)%N | x <- smooth_list E ps', e <- iota 0 (E + 1)%N]
  end.

(* 列表求和对 ++ 的分配：Σ_{y ∈ l1++l2} f y == Σ_{y∈l1} f y + Σ_{y∈l2} f y *)
Lemma CRsum_list_cat {R : ConstructiveReals} {A : Type} (f : A -> CRcarrier R) (l1 l2 : seq A) :
  CReq R (CRsum_list f (l1 ++ l2)) (CRplus R (CRsum_list f l1) (CRsum_list f l2)).
Proof.
  elim: l1 => [| x l1' IH] /=.
  - rewrite (CRplus_0_l (R := R) (CRsum_list f l2)). reflexivity.
  - rewrite IH. rewrite (CRplus_assoc (R := R) (f x) (CRsum_list f l1') (CRsum_list f l2)). reflexivity.
Qed.

(* 列表求和分配（concat/map）：Σ_{y ∈ flatten l} f y == Σ_{s ∈ l} (Σ_{y ∈ s} f y) *)
Lemma CRsum_list_flatten {R : ConstructiveReals} {A : Type} (f : A -> CRcarrier R) (l : seq (seq A)) :
  CReq R (CRsum_list f (flatten l)) (CRsum_list (fun s => CRsum_list f s) l).
Proof.
  elim: l => [| s l IH] /=.
  - reflexivity.
  - rewrite (CRsum_list_cat (R := R) f s (flatten l)).
    rewrite IH.
    reflexivity.
Qed.

(* map 求和：Σ_{y ∈ map g l} f y == Σ_{x ∈ l} f (g x) *)
Lemma CRsum_list_map {R : ConstructiveReals} {A B : Type} (f : B -> CRcarrier R) (g : A -> B) (l : seq A) :
  CReq R (CRsum_list f (map g l)) (CRsum_list (fun x => f (g x)) l).
Proof.
  elim: l => [| x l IH] /=.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

(* iota 求和：Σ_{k ∈ iota 0 (E+1)} f k == CRsum f E（CRsum 的列表等价）
   —— iotaD 从后展开：iota 0 (S E + 1) = iota 0 (S E) ++ [S E] *)
Lemma CRsum_list_iota {R : ConstructiveReals} (f : nat -> CRcarrier R) (E : nat) :
  CReq R (CRsum_list f (iota 0 (E + 1)%N)) (CRsum f E).
Proof.
  elim: E => [| E IH].
  - simpl. rewrite (CRplus_0_r (R := R) (f 0%nat)). reflexivity.
  - rewrite (iotaD 0 (S E) 1).
    rewrite (CRsum_list_cat (R := R) f (iota 0 (S E)) (iota (0 + S E) 1)).
    rewrite (addn1 E) in IH.
    rewrite IH.
    rewrite add0n. simpl.
    rewrite (CRplus_0_r (R := R) (f (S E))).
    reflexivity.
Qed.

(* 列表求和逐项相等：forall x ∈ l, f x == g x ⟹ Σ_{x∈l} f x == Σ_{x∈l} g x（A 需 eqType） *)
Lemma CRsum_eq_list {R : ConstructiveReals} {A : eqType} (f g : A -> CRcarrier R) (l : seq A) :
  (forall x, x \in l -> CReq R (f x) (g x)) -> CReq R (CRsum_list f l) (CRsum_list g l).
Proof.
  intro H. revert H. induction l as [| x l IH]; intro H; simpl.
  - apply CReq_refl.
  - have Htail : forall y, y \in l -> CReq R (f y) (g y).
    { move => y Hy. apply (H y). rewrite in_cons. apply/orP. right. exact Hy. }
    unfold CReq. split.
    + apply (CRplus_le_compat (g x) (f x) (CRsum_list g l) (CRsum_list f l)).
      * exact (proj1 (H x (mem_head x l))).
      * exact (proj1 (IH Htail)).
    + apply (CRplus_le_compat (f x) (g x) (CRsum_list f l) (CRsum_list g l)).
      * exact (proj2 (H x (mem_head x l))).
      * exact (proj2 (IH Htail)).
Qed.

(* 双重列表推导求和：Σ_{y ∈ [seq g x e | x <- l, e <- iota 0 (E+1)]} f y
   == Σ_{x ∈ l} Σ_{e ≤ E} f (g x e)（smooth_list 展开的求和） *)
Lemma CRsum_list_2d {R : ConstructiveReals} (f : nat -> CRcarrier R) (g : nat -> nat -> nat)
  (l : seq nat) (E : nat) :
  CReq R (CRsum_list f [seq g x e | x <- l, e <- iota 0 (E + 1)%N])
         (CRsum_list (fun x => CRsum_list (fun e => f (g x e)) (iota 0 (E + 1)%N)) l).
Proof.
  rewrite (CRsum_list_flatten (R := R) f (map (fun x => map (fun e => g x e) (iota 0 (E + 1)%N)) l)).
  rewrite (CRsum_list_map (R := R) (fun s => CRsum_list f s)
            (fun x => map (fun e => g x e) (iota 0 (E + 1)%N)) l).
  apply (CRsum_eq_list (R := R) _ _ l).
  intros x Hx.
  rewrite (CRsum_list_map (R := R) f (fun e => g x e) (iota 0 (E + 1)%N)).
  reflexivity.
Qed.

(* smooth_list E ps 的元素 ≥ 1（ps 全素数；用于 inv_n_pow_mult 前提） *)
Lemma smooth_list_ge1 (E : nat) (ps : seq nat) (Hps : all prime ps) :
  forall x, x \in smooth_list E ps -> (1 <= x)%nat.
Proof.
  elim: ps Hps => [| p ps' IH] Hps x Hx /=.
  - rewrite mem_seq1 in Hx. move/eqP : Hx => Hx'.
    rewrite Hx'. apply leqnn.
  - have Hp : prime p := allP Hps p (mem_head p ps').
    have Hps' : all prime ps'.
    { apply/allP. move => y Hy.
      apply (allP Hps y).
      rewrite in_cons. apply/orP. right. exact Hy. }
    move: Hx.
    rewrite /smooth_list.
    move/flattenP => [s Hs Hxs].
    move/mapP : Hs => [y Hy Hs'].
    move: Hxs. rewrite Hs'. move/mapP => [e He Hxe].
    rewrite Hxe.
    rewrite muln_gt0. apply/andP. split.
    + exact (IH Hps' y Hy).
    + rewrite expn_gt0. rewrite (@prime_gt0 p Hp). simpl. reflexivity.
Qed.

(* 列表版分布律：(Σ_{x∈l} f x)·y == Σ_{x∈l} (f x·y) *)
Lemma CRsum_list_mult_r {R : ConstructiveReals} (f : nat -> CRcarrier R) (l : seq nat) (y : CRcarrier R) :
  CReq R (CRmult R (CRsum_list f l) y) (CRsum_list (fun x => CRmult R (f x) y) l).
Proof.
  elim: l => [| x l IH] /=.
  - rewrite (CRmult_0_l (R := R) y). reflexivity.
  - rewrite (CRmult_plus_distr_r (R := R) y (f x) (CRsum_list f l)).
    rewrite IH. reflexivity.
Qed.

(* 列表 × CRsum 分布：(Σ_{x∈l} f x)·(Σ_{e≤E} g e) == Σ_{x∈l} Σ_{e≤E} (f x·g e)
   —— smooth_step 的分布律反向基础 *)
Lemma CRsum_list_mult_sum {R : ConstructiveReals} (f : nat -> CRcarrier R) (l : seq nat)
  (g : nat -> CRcarrier R) (E : nat) :
  CReq R (CRmult R (CRsum_list f l) (CRsum g E))
         (CRsum_list (fun x => CRsum (fun e => CRmult R (f x) (g e)) E) l).
Proof.
  rewrite (CRsum_list_mult_r (R := R) f l (CRsum g E)).
  apply (CRsum_eq_list (R := R) (fun x => CRmult R (f x) (CRsum g E))
                                  (fun x => CRsum (fun e => CRmult R (f x) (g e)) E) l).
  intros x Hx.
  apply (CRsum_mult_l (R := R) g E (f x)).
Qed.

(* 逐步乘入：Σ_{y∈smooth_list E (p::ps)} y^{-s}
   == (Σ_{x∈smooth_list E ps} x^{-s})·(Σ_{e≤E} p^{-es})
   —— 展开 smooth_list + 双重和（CRsum_list_2d）+ 每项 inv_n_pow_mult + 分布律反向
   ★ 可复用：欧拉乘积逐步乘入新素因子的原子步 *)
Lemma smooth_step {R : ConstructiveReals} (s p E : nat) (ps : seq nat)
  (Hp : prime p) (Hps : all prime ps) :
  CReq R (CRsum_list (fun y => inv_n_pow y s) (smooth_list E (p :: ps)))
         (CRmult R (CRsum_list (fun x => inv_n_pow x s) (smooth_list E ps))
                   (CRsum (fun e => inv_n_pow (p ^ e) s) E)).
Proof.
  rewrite (CRsum_list_2d (R := R) (fun y => inv_n_pow y s) (fun x e => (x * p ^ e)%N)
                         (smooth_list E ps) E).
  rewrite (CRsum_list_mult_sum (R := R) (fun x => inv_n_pow x s) (smooth_list E ps)
                                (fun e => inv_n_pow (p ^ e) s) E).
  apply (CRsum_eq_list (R := R) _ _ (smooth_list E ps)).
  intros x Hx.
  rewrite (CRsum_list_iota (R := R) (fun e => inv_n_pow (x * p ^ e) s) E).
  apply (CRsum_eq (R := R) _ _ E).
  intros e He.
  apply (inv_n_pow_mult (R := R) x (p ^ e) s (smooth_list_ge1 E ps Hps x Hx)).
  rewrite expn_gt0. rewrite (@prime_gt0 p Hp). simpl. reflexivity.
Qed.

(* 1^{-s} == 1（s ≥ 0；空积 = 1 的基础） *)
Lemma inv_n_pow_one {R : ConstructiveReals} (s : nat) :
  CReq R (inv_n_pow 1 s) (CR_of_Q R Q1q).
Proof.
  unfold inv_n_pow. simpl.
  rewrite (CRpow_one (R := R) s). reflexivity.
Qed.

(* ============================================================
   L3 主引理：有限欧拉乘积 = smooth 数和
   ∏_{p ∈ ps} (Σ_{e≤E} p^{-es}) == Σ_{x ∈ smooth_list E ps} x^{-s}（ps 全素数）
   —— 归纳 on ps：空积 = 1^{-s} = 1；逐步乘入（smooth_step）
   ★ 里程碑：欧拉乘积展开的核心代数（L4 双极限的前置） *)
Lemma euler_finite_expand {R : ConstructiveReals} (ps : seq nat) (s E : nat)
  (Hps : all prime ps) :
  CReq R (CRprod_list (fun p => CRsum (fun e => inv_n_pow (p ^ e) s) E) ps)
         (CRsum_list (fun x => inv_n_pow x s) (smooth_list E ps)).
Proof.
  elim: ps Hps => [| p ps' IH] Hps /=.
  - rewrite (CRplus_0_r (R := R) (inv_n_pow 1 s)).
    rewrite (inv_n_pow_one (R := R) s). reflexivity.
  - have Hp : prime p := allP Hps p (mem_head p ps').
    have Hps' : all prime ps'.
    { apply/allP. move => y Hy.
      apply (allP Hps y).
      rewrite in_cons. apply/orP. right. exact Hy. }
    rewrite (CRmult_comm (R := R) (CRsum (fun e => inv_n_pow (p ^ e) s) E)
                         (CRprod_list (fun p => CRsum (fun e => inv_n_pow (p ^ e) s) E) ps')).
    rewrite (IH Hps').
    symmetry.
    apply (smooth_step (R := R) s p E ps' Hp Hps').
Qed.

(* ============================================================
   L4 分析件：CR_cv 对乘法的连续性（构造性 eps-N）
   E→∞ 极限：∏_{p∈ps} (Σ_{e≤E} p^{-es}) → ∏_{p∈ps} (1-p^{-s})^{-1}
   ============================================================ *)

(* x < y ⟹ x ≤ y（CRle 是 CRlt 反向的否定；CRle_of_lt 的泛化） *)
Lemma CRlt_le {R : ConstructiveReals} (x y : CRcarrier R) (H : CRlt R x y) : CRle R x y.
Proof. unfold CRle. intro Hyx. exact (CRlt_asym (R := R) x y H Hyx). Qed.

(* v → b ⟹ 存在 N，n ≥ N ⟹ |v n| ≤ |b| + 1（收敛 ⟹ 尾部有界） *)
Lemma CR_cv_abs_bounded {R : ConstructiveReals} (v : nat -> CRcarrier R) (b : CRcarrier R)
  (Hv : CR_cv R v b) :
  { N : nat | forall n, le N n -> CRle R (CRabs R (v n)) (CRplus R (CRabs R b) (CR_of_Q R Q1q)) }.
Proof.
  destruct (Hv 1%positive) as [N HN].
  exists N.
  intros n Hn.
  have Hvnab : CReq R (CRabs R (v n))
                      (CRplus R (CRabs R b) (CRminus R (CRabs R (v n)) (CRabs R b))).
  { unfold CRminus.
    rewrite <- (CRplus_assoc (R := R) (CRabs R b) (CRabs R (v n)) (CRopp R (CRabs R b))).
    rewrite (CRplus_comm (R := R) (CRabs R b) (CRabs R (v n))).
    rewrite (CRplus_assoc (R := R) (CRabs R (v n)) (CRabs R b) (CRopp R (CRabs R b))).
    rewrite (CRplus_opp_r (R := R) (CRabs R b)).
    rewrite (CRplus_0_r (R := R) (CRabs R (v n))).
    reflexivity. }
  eapply CRle_trans.
  - exact (proj2 Hvnab).
  - eapply CRle_trans.
    + apply (CRplus_le_compat_l (R := R) (CRabs R b) (CRminus R (CRabs R (v n)) (CRabs R b))
                                 (CRabs R (CRminus R (v n) b))).
      exact (CRabs_triang_inv (R := R) (v n) b).
    + apply (CRplus_le_compat_l (R := R) (CRabs R b) (CRabs R (CRminus R (v n) b))
                                   (CR_of_Q R Q1q)).
      exact (HN n Hn).
Qed.

(* |u v - a b| ≤ |u-a||v| + |a||v-b| —— 乘法连续的核心代数 *)
Lemma CRabs_mult_diff {R : ConstructiveReals} (u v a b : CRcarrier R) :
  CRle R (CRabs R (CRminus R (CRmult R u v) (CRmult R a b)))
         (CRplus R (CRmult R (CRabs R (CRminus R u a)) (CRabs R v))
                   (CRmult R (CRabs R a) (CRabs R (CRminus R v b)))).
Proof.
  have Halg : CReq R (CRminus R (CRmult R u v) (CRmult R a b))
                     (CRplus R (CRmult R (CRminus R u a) v) (CRmult R a (CRminus R v b))).
  { have H1 : CReq R (CRmult R (CRminus R u a) v) (CRminus R (CRmult R u v) (CRmult R a v)).
    { unfold CRminus.
      rewrite (CRmult_plus_distr_r (R := R) v u (CRopp R a)).
      rewrite (CRopp_mult_distr_l (R := R) a v).
      reflexivity. }
    have H2 : CReq R (CRmult R a (CRminus R v b)) (CRminus R (CRmult R a v) (CRmult R a b)).
    { unfold CRminus.
      rewrite (CRmult_plus_distr_l (R := R) a v (CRopp R b)).
      rewrite (CRopp_mult_distr_r (R := R) a b).
      reflexivity. }
    rewrite H1 H2.
    symmetry.
    exact (CRminus_add_cancel (R := R) (CRmult R u v) (CRmult R a v) (CRmult R a b)).
  }
  eapply CRle_trans.
  - rewrite Halg.
    apply (CRabs_triang (R := R) (CRmult R (CRminus R u a) v) (CRmult R a (CRminus R v b))).
  - apply (CRplus_le_compat (CRabs R (CRmult R (CRminus R u a) v))
                            (CRmult R (CRabs R (CRminus R u a)) (CRabs R v))
                            (CRabs R (CRmult R a (CRminus R v b)))
                            (CRmult R (CRabs R a) (CRabs R (CRminus R v b)))).
    + exact (proj2 (CRabs_mult (R := R) (CRminus R u a) v)).
    + exact (proj2 (CRabs_mult (R := R) a (CRminus R v b))).
Qed.

(* X·p < q ⟹ X·(1/q) < 1/p —— archimedean 界到 eps（p q positive，X 任意） *)
Lemma CR_arch_eps {R : ConstructiveReals} (X : CRcarrier R) (p q : positive)
  (H : CRlt R (CRmult R X (CR_of_Q R (Qmake (Zpos p) 1))) (CR_of_Q R (Qmake (Zpos q) 1))) :
  CRlt R (CRmult R X (CR_of_Q R (Qmake 1 q))) (CR_of_Q R (Qmake 1 p)).
Proof.
  have Hpos : CRlt R (CR_of_Q R Q0q) (CR_of_Q R (Qmake 1 (Pos.mul p q))).
  { apply CR_of_Q_lt. unfold Q0q, Qlt. simpl. lia. }
  have Hpq : CReq R (CRmult R (CR_of_Q R (Qmake (Zpos p) 1)) (CR_of_Q R (Qmake 1 (Pos.mul p q))))
                    (CR_of_Q R (Qmake 1 q)).
  { rewrite <- (CR_of_Q_mult R (Qmake (Zpos p) 1) (Qmake 1 (Pos.mul p q))).
    apply (CR_of_Q_Qeq (R := R) (Qmult (Qmake (Zpos p) 1) (Qmake 1 (Pos.mul p q))) (Qmake 1 q)).
    unfold Qmult, Qeq. simpl. lia. }
  have Hq1 : CReq R (CRmult R (CR_of_Q R (Qmake (Zpos q) 1)) (CR_of_Q R (Qmake 1 (Pos.mul p q))))
                    (CR_of_Q R (Qmake 1 p)).
  { rewrite <- (CR_of_Q_mult R (Qmake (Zpos q) 1) (Qmake 1 (Pos.mul p q))).
    apply (CR_of_Q_Qeq (R := R) (Qmult (Qmake (Zpos q) 1) (Qmake 1 (Pos.mul p q))) (Qmake 1 p)).
    unfold Qmult, Qeq. simpl. lia. }
  pose (Hm := CRmult_lt_compat_r (R := R) (CR_of_Q R (Qmake 1 (Pos.mul p q)))
                                 (CRmult R X (CR_of_Q R (Qmake (Zpos p) 1)))
                                 (CR_of_Q R (Qmake (Zpos q) 1))
                                 Hpos H).
  rewrite <- Hpq.
  rewrite <- (CRmult_assoc (R := R) X (CR_of_Q R (Qmake (Zpos p) 1)) (CR_of_Q R (Qmake 1 (Pos.mul p q)))).
  eapply CRlt_le_trans.
  - exact Hm.
  - rewrite <- Hq1. apply CRle_refl.
Qed.

(* CR_cv 对乘法的连续性：u → a、v → b ⟹ u·v → a·b（构造性 eps-N）
   —— CR_archimedean 选 q 使 (|b|+1+|a|)·p < q，eps 分割 1/q
   ★ 可复用：L4 双极限的乘积极限连续性基础 *)
Lemma CR_cv_mult {R : ConstructiveReals} (u v : nat -> CRcarrier R) (a b : CRcarrier R)
  (Hu : CR_cv R u a) (Hv : CR_cv R v b) : CR_cv R (fun n => CRmult R (u n) (v n)) (CRmult R a b).
Proof.
  intro p.
  destruct (CR_cv_abs_bounded (R := R) v b Hv) as [N0 HN0].
  destruct (CR_archimedean R
             (CRmult R (CRplus R (CRplus R (CRabs R b) (CR_of_Q R Q1q)) (CRabs R a))
                       (CR_of_Q R (Qmake (Zpos p) 1)))) as [q Hq].
  destruct (Hu q) as [N1 HN1].
  destruct (Hv q) as [N2 HN2].
  exists (Init.Nat.max N0 (Init.Nat.max N1 N2)).
  intros n Hn.
  have Hn0 : le N0 n := Nat.le_trans N0 (Init.Nat.max N0 (Init.Nat.max N1 N2)) n (Nat.le_max_l N0 (Init.Nat.max N1 N2)) Hn.
  have Hn2 : le N2 n := Nat.le_trans N2 (Init.Nat.max N1 N2) n (Nat.le_max_r N1 N2) (Nat.le_trans (Init.Nat.max N1 N2) (Init.Nat.max N0 (Init.Nat.max N1 N2)) n (Nat.le_max_r N0 (Init.Nat.max N1 N2)) Hn).
  have Hn1 : le N1 n := Nat.le_trans N1 (Init.Nat.max N1 N2) n (Nat.le_max_l N1 N2) (Nat.le_trans (Init.Nat.max N1 N2) (Init.Nat.max N0 (Init.Nat.max N1 N2)) n (Nat.le_max_r N0 (Init.Nat.max N1 N2)) Hn).
  eapply CRle_trans.
  - exact (CRabs_mult_diff (R := R) (u n) (v n) a b).
  - eapply CRle_trans.
    + apply (CRplus_le_compat (CRmult R (CRabs R (CRminus R (u n) a)) (CRabs R (v n)))
                              (CRmult R (CR_of_Q R (Qmake 1 q)) (CRabs R (v n)))
                              (CRmult R (CRabs R a) (CRabs R (CRminus R (v n) b)))
                              (CRmult R (CRabs R a) (CR_of_Q R (Qmake 1 q)))).
      * apply (CRmult_le_compat_r (R := R) (CRabs R (v n))
                                   (CRabs R (CRminus R (u n) a)) (CR_of_Q R (Qmake 1 q))).
        -- apply CRabs_pos.
        -- exact (HN1 n Hn1).
      * apply (CRmult_le_compat_l (R := R) (CRabs R a)
                                   (CRabs R (CRminus R (v n) b)) (CR_of_Q R (Qmake 1 q))).
        -- apply CRabs_pos.
        -- exact (HN2 n Hn2).
    + eapply CRle_trans.
      * apply (CRplus_le_compat (CRmult R (CR_of_Q R (Qmake 1 q)) (CRabs R (v n)))
                                (CRmult R (CR_of_Q R (Qmake 1 q)) (CRplus R (CRabs R b) (CR_of_Q R Q1q)))
                                (CRmult R (CRabs R a) (CR_of_Q R (Qmake 1 q)))
                                (CRmult R (CRabs R a) (CR_of_Q R (Qmake 1 q)))).
        -- apply (CRmult_le_compat_l (R := R) (CR_of_Q R (Qmake 1 q))
                                     (CRabs R (v n)) (CRplus R (CRabs R b) (CR_of_Q R Q1q))).
           ++ apply (CRlt_le (R := R) (CR_of_Q R Q0q) (CR_of_Q R (Qmake 1 q))).
              apply CR_of_Q_lt. unfold Q0q, Qlt. simpl. lia.
           ++ exact (HN0 n Hn0).
        -- apply CRle_refl.
      * eapply CRle_trans.
        -- rewrite (CRmult_comm (R := R) (CRabs R a) (CR_of_Q R (Qmake 1 q))).
           rewrite <- (CRmult_plus_distr_l (R := R) (CR_of_Q R (Qmake 1 q))
                                           (CRplus R (CRabs R b) (CR_of_Q R Q1q)) (CRabs R a)).
           apply CRle_refl.
        -- apply CRlt_le.
           rewrite (CRmult_comm (R := R) (CR_of_Q R (Qmake 1 q))
                                (CRplus R (CRplus R (CRabs R b) (CR_of_Q R Q1q)) (CRabs R a))).
           exact (CR_arch_eps (R := R) (CRplus R (CRplus R (CRabs R b) (CR_of_Q R Q1q)) (CRabs R a))
                                   p q Hq).
Qed.

(* ============================================================
   L4 E→∞ 极限：∏_{p∈ps} (Σ_{e≤E} p^{-es}) →_{E} ∏_{p∈ps} (1-p^{-s})^{-1}
   ============================================================ *)

(* p ≥ 1 ⟹ p^e ≥ 1（e 任意） *)
Lemma expn_ge1 (p e : nat) (Hp : (1 <= p)%nat) : (1 <= p ^ e)%nat.
Proof.
  elim: e => [| e' IH'] /=.
  - rewrite expn0. apply leqnn.
  - rewrite expnS. rewrite muln_gt0. apply/andP. split. exact Hp. exact IH'.
Qed.

(* (p^e)^{-s} == (p^{-s})^e —— 素数幂项 = 几何级数项（归纳 + inv_n_pow_mult） *)
Lemma inv_n_pow_pow {R : ConstructiveReals} (p s e : nat) (Hp : (1 <= p)%nat) :
  CReq R (inv_n_pow (p ^ e) s) (CRpow (inv_n_pow p s) e).
Proof.
  induction e as [| e IH].
  - simpl. rewrite (inv_n_pow_one (R := R) s). reflexivity.
  - rewrite (expnS p e). simpl.
    rewrite (inv_n_pow_mult (R := R) p (p ^ e) s Hp (expn_ge1 p e Hp)).
    rewrite IH.
    rewrite (CRmult_comm (R := R) (inv_n_pow p s) (CRpow (inv_n_pow p s) e)).
    reflexivity.
Qed.

(* 逐因子极限 ⟹ 有限乘积极限（CRprod_list 归纳 + CR_cv_mult） *)
Lemma CRprod_list_cv {R : ConstructiveReals} (f : nat -> nat -> CRcarrier R) (g : nat -> CRcarrier R)
  (ps : seq nat) (Hcv : forall i, i \in ps -> CR_cv R (fun E => f i E) (g i)) :
  CR_cv R (fun E => CRprod_list (fun i => f i E) ps) (CRprod_list g ps).
Proof.
  revert Hcv. induction ps as [| p ps' IH]; intro Hcv; simpl.
  - apply (CR_cv_extens (R := R) (fun E : nat => CR_of_Q R Q1q)
                          (fun E : nat => CR_of_Q R Q1q) (CR_of_Q R Q1q)).
    + intros E. reflexivity.
    + apply CR_cv_const.
  - apply (CR_cv_mult (R := R) (fun E => f p E) (fun E => CRprod_list (fun i => f i E) ps')
                         (g p) (CRprod_list g ps')).
    + exact (Hcv p (mem_head p ps')).
    + have Hps'cv : forall i, i \in ps' -> CR_cv R (fun E => f i E) (g i).
      { move => i Hi. apply (Hcv i). rewrite in_cons. apply/orP. right. exact Hi. }
      exact (IH Hps'cv).
Qed.

(* 每因子极限：Σ_{e≤E} (p^e)^{-s} → (1-p^{-s})^{-1}（prime_power_series + 项重写 inv_n_pow_pow） *)
Lemma prime_pow_sum_cv {R : ConstructiveReals} (p s : nat) (Hp : prime p) (Hs : (1 <= s)%nat) :
  { l : CRcarrier R & CR_cv R (fun E => CRsum (fun e => inv_n_pow (p ^ e) s) E) l }.
Proof.
  destruct (prime_power_series (R := R) p s Hp Hs) as [l Hl].
  exists l.
  apply (CR_cv_extens (R := R) (fun E => CRsum (fun k => CRpow (inv_n_pow p s) k) E)
                              (fun E => CRsum (fun e => inv_n_pow (p ^ e) s) E) l).
  - intros E.
    apply (CRsum_eq (R := R) (fun k => CRpow (inv_n_pow p s) k)
                             (fun e => inv_n_pow (p ^ e) s) E).
    intros k Hk.
    symmetry.
    apply (inv_n_pow_pow (R := R) p s k (prime_ge1 p Hp)).
  - exact (fst Hl).
Qed.

(* 有限欧拉乘积的 E 极限：∏_{p∈ps} (Σ_{e≤E} p^{-es}) →_{E} ∏_{p∈ps} (1-p^{-s})^{-1}
   —— 归纳 on ps 构造极限（每步 prime_pow_sum_cv + CR_cv_mult）
   ★ 里程碑：L4 E→∞ 极限完成（L3 euler_finite_expand 的极限闭合） *)
Lemma euler_E_cv {R : ConstructiveReals} (ps : seq nat) (s : nat)
  (Hps : all prime ps) (Hs : (1 <= s)%nat) :
  { l : CRcarrier R & CR_cv R (fun E => CRprod_list (fun p => CRsum (fun e => inv_n_pow (p ^ e) s) E) ps) l }.
Proof.
  revert Hps. induction ps as [| p ps' IH]; intro Hps.
  - exists (CR_of_Q R Q1q).
    apply (CR_cv_extens (R := R) (fun E : nat => CR_of_Q R Q1q)
                          (fun E : nat => CR_of_Q R Q1q) (CR_of_Q R Q1q)).
    + intros E. reflexivity.
    + apply CR_cv_const.
  - have Hp : prime p := allP Hps p (mem_head p ps').
    have Hps' : all prime ps'.
    { apply/allP. move => y Hy.
      apply (allP Hps y).
      rewrite in_cons. apply/orP. right. exact Hy. }
    destruct (prime_pow_sum_cv (R := R) p s Hp Hs) as [lp Hlp].
    destruct (IH Hps') as [lps' Hlps'].
    exists (CRmult R lp lps').
    apply (CR_cv_mult (R := R) (fun E => CRsum (fun e => inv_n_pow (p ^ e) s) E)
                                (fun E => CRprod_list (fun p => CRsum (fun e => inv_n_pow (p ^ e) s) E) ps')
                                lp lps').
    + exact Hlp.
    + exact Hlps'.
Qed.

(* ============================================================
   L4 P→∞：smooth 子级数 → ζ（夹逼）
   ============================================================ *)

(* nat 层列表乘积（smooth 数界的上限构造） *)
Definition nat_prod_list (f : nat -> nat) (ps : seq nat) : nat :=
  foldr (fun p acc => (f p * acc)%N) 1%nat ps.

(* x ∈ smooth_list E ps、ps 全素数 ⟹ x ≤ ∏_{p∈ps} p^E（E 界 + 素因子界）
   —— 正向不等式「∏(Σ_e) ≤ ζ 部分和」的基础（每项 x^{-s} 落入 ζ 部分和的项集） *)
Lemma smooth_list_bound (E : nat) (ps : seq nat) (Hps : all prime ps) :
  forall x, x \in smooth_list E ps -> (x <= nat_prod_list (fun p => (p ^ E)%N) ps)%nat.
Proof.
  elim: ps Hps => [| p ps' IH] Hps x Hx /=.
  - rewrite mem_seq1 in Hx. move/eqP : Hx => Hx'.
    rewrite Hx'. apply leqnn.
  - have Hp : prime p := allP Hps p (mem_head p ps').
    have Hps' : all prime ps'.
    { apply/allP. move => y Hy.
      apply (allP Hps y).
      rewrite in_cons. apply/orP. right. exact Hy. }
    move: Hx.
    rewrite /smooth_list.
    move/flattenP => [s Hs Hxs].
    move/mapP : Hs => [y Hy Hs'].
    move: Hxs. rewrite Hs'. move/mapP => [e He Hxe].
    rewrite Hxe.
    have HeE : (e <= E)%nat.
    { rewrite mem_iota in He. destruct (andP He) as [_ He1].
      rewrite add0n in He1.
      rewrite (addn1 E) in He1.
      rewrite (ltnS e E) in He1.
      exact He1. }
    have Hpgt1 : (1 < p)%nat := prime_gt1_mc p Hp.
    have Hpe : (p ^ e <= p ^ E)%nat.
    { rewrite (@leq_exp2l p e E Hpgt1). exact HeE. }
    apply (leq_trans (leq_mul (IH Hps' y Hy) Hpe)).
    rewrite (mulnC (nat_prod_list (fun p : nat => (p ^ E)%N) ps') (p ^ E)%N). apply leqnn.
Qed.

(* x ∈ smooth_list E ps、ps 全素数 ⟹ x 的素因子 ⊆ ps
   —— 配对「p ∤ y（y smooth 且 p 不在 ps）」的关键 *)
Lemma smooth_list_prime_sub (E : nat) (ps : seq nat) (Hps : all prime ps) :
  forall x, x \in smooth_list E ps -> all (fun q => q \in ps) (primes x).
Proof.
  elim: ps Hps => [| p ps' IH] Hps x Hx /=.
  - rewrite mem_seq1 in Hx. move/eqP : Hx => Hx'.
    rewrite Hx'. reflexivity.
  - have Hp : prime p := allP Hps p (mem_head p ps').
    have Hps' : all prime ps'.
    { apply/allP. move => y Hy.
      apply (allP Hps y).
      rewrite in_cons. apply/orP. right. exact Hy. }
    move: Hx.
    rewrite /smooth_list.
    move/flattenP => [s Hs Hxs].
    move/mapP : Hs => [y Hy Hs'].
    move: Hxs. rewrite Hs'. move/mapP => [e He Hxe].
    rewrite Hxe.
    apply/allP. move => q Hq.
    rewrite mem_primes in Hq.
    move/andP : Hq => [Hqpr /andP [_ Hqdvd]].
    destruct (Nat.eqb_spec q p) as [Heq | Hne].
    + rewrite Heq. apply mem_head.
    + have Hqnp : ~~ (q %| p).
      { rewrite (@dvdn_prime2 q p Hqpr Hp). apply/eqP. exact Hne. }
      have Hqcop_p : coprime q p.
      { rewrite (@prime_coprime q p Hqpr). exact Hqnp. }
      have Hqcop : coprime q (p ^ e).
      { rewrite coprime_sym.
        apply (@coprimeXl e p q).
        rewrite coprime_sym. exact Hqcop_p. }
      have Hqdvdn : q %| y.
      { rewrite (mulnC y (p ^ e)%N) in Hqdvd.
        move: Hqdvd. rewrite (@Gauss_dvdr q (p ^ e)%N y Hqcop). exact id. }
      have Hqiny : q \in primes y.
      { rewrite mem_primes. apply/andP. split. exact Hqpr. apply/andP. split.
        - exact (smooth_list_ge1 E ps' Hps' y Hy).
        - exact Hqdvdn. }
      have Hqps' : q \in ps'.
      { move: (IH Hps' y Hy) => /allP HIH. exact (HIH q Hqiny). }
      rewrite in_cons. apply/orP. right. exact Hqps'.
Qed.

(* ============================================================
   L4 P→∞：smooth_list 互异（夹逼「反向分解」的基础）
   —— uniq_flatten 组合：cat_uniq + smooth_expand_uniq + smooth_list_uniq
   ============================================================ *)

(* s1、s2 uniq 且 s1 的元素不在 s2 ⟹ s1++s2 uniq（bool 计算版） *)
Lemma cat_uniq {A : eqType} (s1 s2 : seq A) :
  uniq s1 -> uniq s2 -> (forall x, x \in s1 -> x \notin s2) -> uniq (s1 ++ s2).
Proof.
  elim: s1 => [| x s1' IH] /=.
  - intros _ Hs2 _. exact Hs2.
  - move => H1 Hs2 Hsep.
    have [Hxnotin H1'] := andP H1.
    rewrite /uniq. simpl.
    rewrite (mem_cat x s1' s2). rewrite negb_or. rewrite Hxnotin.
    rewrite (Hsep x (mem_head x s1')). simpl.
    apply (IH H1' Hs2).
    intros y Hy. apply Hsep. rewrite in_cons. apply/orP. right. exact Hy.
Qed.

(* 对任意 uniq 且 p∤元素、元素≥1 的列表 l：展开 [seq y·p^e | y <- l, e <- iota] 仍 uniq
   —— 内层（固定 y，e 单射）+ 外层（不同 y，smooth_pair_inj） *)
Lemma smooth_expand_uniq (E p : nat) (Hp : prime p) (l : seq nat)
  (Hluniq : uniq l)
  (Hpndvd : forall y, y \in l -> ~~ (p %| y))
  (Hyge : forall y, y \in l -> (1 <= y)%nat) :
  uniq [seq (y * p ^ e)%N | y <- l, e <- iota 0 (E + 1)%N].
Proof.
  revert Hluniq Hpndvd Hyge.
  induction l as [| y l' IH]; intros Hluniq Hpndvd Hyge; simpl.
  - done.
  - have Hpgt1 : (1 < p)%nat := prime_gt1_mc p Hp.
    have Hy0 : (0 < y)%nat.
    { move: (Hyge y (mem_head y l')) => H. exact H. }
    have Hinj : injective (fun e : nat => (y * p ^ e)%N).
    { move => e1 e2 He.
      apply/eqP.
      rewrite <- (@eqn_exp2l p e1 e2 Hpgt1).
      rewrite <- (@eqn_pmul2l y (p ^ e1)%N (p ^ e2)%N Hy0).
      apply/eqP. exact He. }
    have Hinner : uniq [seq (y * p ^ e)%N | e <- iota 0 (E + 1)%N].
    { rewrite (@map_inj_uniq _ _ (fun e : nat => (y * p ^ e)%N) Hinj (iota 0 (E + 1)%N)).
      apply iota_uniq. }
    have Hl' : uniq l' := proj2 (andP Hluniq).
    (* 外层：cat_uniq (f y) (flatten (map f l')) *)
    apply (cat_uniq [seq (y * p ^ e)%N | e <- iota 0 (E + 1)%N]
                    (flatten (map (fun y0 => [seq (y0 * p ^ e)%N | e <- iota 0 (E + 1)%N]) l'))).
    + exact Hinner.
    + (* uniq (flatten (map f l'))——IH（对 l'）*)
      apply (IH Hl'
                (fun y0 Hy0 => Hpndvd y0 (@mem_behead nat (y :: l') y0 Hy0))
                (fun y0 Hy0 => Hyge y0 (@mem_behead nat (y :: l') y0 Hy0))).
    + (* 不重叠：f y 的元素（y·p^e）∉ flatten（= y0·p^{e'}，y0 ∈ l'）*)
      move => x Hx.
      apply/negP => Hxfl.
      move: Hx => /mapP [e0 _ Hxe0].
      move/flattenP : Hxfl => [s0 Hs0 Hxs0].
      move: Hs0 => /mapP [y1 Hy1 Hs0'].
      move: Hxs0. rewrite Hs0'. move/mapP => [e' _ Hxe'].
      have Heq : (y * p ^ e0)%N = (y1 * p ^ e')%N.
      { rewrite <- Hxe0. exact Hxe'. }
      have Hpair := smooth_pair_inj p y y1 e0 e' Hp
                     (Hpndvd y (mem_head y l')) (Hpndvd y1 (@mem_behead nat (y :: l') y1 Hy1)) Heq.
      have Hyy0 : y = y1 := proj1 Hpair.
      move/negP : (proj1 (andP Hluniq)) => Hn.
      apply Hn. rewrite Hyy0. exact Hy1.
Qed.

(* smooth_list E ps 元素互异（ps 全素数且去重）
   —— 夹逼反向分解「每 n ∈ smooth 至多出现一次」的保证 *)
Lemma smooth_list_uniq (E : nat) (ps : seq nat) (Hps : all prime ps) (Huniq : uniq ps) :
  uniq (smooth_list E ps).
Proof.
  revert Hps Huniq. induction ps as [| p ps' IH]; intros Hps Huniq; simpl.
  - done.
  - have Hp : prime p := allP Hps p (mem_head p ps').
    have Hps' : all prime ps'.
    { apply/allP. move => y Hy.
      apply (allP Hps y).
      rewrite in_cons. apply/orP. right. exact Hy. }
    have Huniq' : uniq ps' := proj2 (andP Huniq).
    have Hpnotin : p \notin ps' := proj1 (andP Huniq).
    have Hpndvd : forall y, y \in smooth_list E ps' -> ~~ (p %| y).
    { move => y Hy.
      apply/negP => Hpdvd.
      have Hsub := smooth_list_prime_sub E ps' Hps' y Hy.
      have Hpin : p \in primes y.
      { rewrite mem_primes. apply/andP. split. exact Hp. apply/andP. split.
        - exact (smooth_list_ge1 E ps' Hps' y Hy).
        - exact Hpdvd. }
      move: Hsub => /allP Hsub'. move: (Hsub' p Hpin) => Hpinps'.
      move/negP : Hpnotin => Hnot'. apply Hnot'. exact Hpinps'. }
    apply (smooth_expand_uniq E p Hp (smooth_list E ps')
              (IH Hps' Huniq')
              Hpndvd
              (fun y Hy => smooth_list_ge1 E ps' Hps' y Hy)).
Qed.

(* ============================================================
   L4 P→∞：正向不等式子引理（Σ_{x∈smooth} x^{-s} ≤ ζ 的砖块）
   —— filter 不增和 / perm 下和不变 / 互异子集和 ≤ 全和
   —— 分析层：非负级数部分和 ≤ 极限
   ============================================================ *)

(* f ≥ 0 时，filter 只删元素 ⟹ 和不增 *)
Lemma CRsum_list_filter_le {R : ConstructiveReals} {A : eqType} (f : A -> CRcarrier R)
  (l : seq A) (P : pred A)
  (Hpos : forall x, x \in l -> CRle R (CR_of_Q R Q0q) (f x)) :
  CRle R (CRsum_list f [seq x <- l | P x]) (CRsum_list f l).
Proof.
  induction l as [| x l' IH].
  - simpl. apply CRle_refl.
  - simpl. case: (P x).
    + have Hpos' : forall y, y \in l' -> CRle R (CR_of_Q R Q0q) (f y).
      { move => y Hy. apply (Hpos y). rewrite in_cons. apply/orP. right. exact Hy. }
      apply (CRplus_le_compat_l (R := R) (f x) (CRsum_list f [seq y <- l' | P y])
                                 (CRsum_list f l')).
      exact (IH Hpos').
    + have Hpos'' : forall y, y \in l' -> CRle R (CR_of_Q R Q0q) (f y).
      { move => y Hy. apply (Hpos y). rewrite in_cons. apply/orP. right. exact Hy. }
      apply (CRle_trans (R := R)
               (CRsum_list f [seq y <- l' | P y])
               (CRsum_list f l')
               (CRplus R (f x) (CRsum_list f l'))).
      * exact (IH Hpos'').
      * have Hposx : CRle R (CR_of_Q R Q0q) (f x) := Hpos x (mem_head x l').
        have H01 : CRle R (CRplus R (CRsum_list f l') (CR_of_Q R Q0q))
                           (CRplus R (CRsum_list f l') (f x)).
        { apply (CRplus_le_compat_l (R := R) (CRsum_list f l') (CR_of_Q R Q0q) (f x)).
          exact Hposx. }
        apply (proj1 (CRle_morph R
                        (CRplus R (CRsum_list f l') (CR_of_Q R Q0q))
                        (CRsum_list f l')
                        (CRplus_0_r (R := R) (CRsum_list f l'))
                        (CRplus R (CRsum_list f l') (f x))
                        (CRplus R (f x) (CRsum_list f l'))
                        (CRplus_comm (R := R) (CRsum_list f l') (f x)))).
        exact H01.
Qed.

(* perm_eq ⟹ 和不变（CReq）—— catCA_perm_ind + CRsum_list_cat + 加法交换/结合 *)
Lemma CRsum_list_perm {R : ConstructiveReals} {A : eqType} (f : A -> CRcarrier R)
  (l1 l2 : seq A) (Hp : perm_eq l1 l2) :
  CReq R (CRsum_list f l1) (CRsum_list f l2).
Proof.
  pose P := fun (s : seq A) => CReq R (CRsum_list f s) (CRsum_list f l2).
  have Hstep : forall s1 s2 s3 : seq A, P (s1 ++ s2 ++ s3) -> P (s2 ++ s1 ++ s3).
  { move => s1 s2 s3 HP.
    (* 先证中间等式 Hmid：Σ(s1++s2++s3) == Σ(s2++s1++s3) *)
    have Hmid : CReq R (CRsum_list f (s1 ++ s2 ++ s3)) (CRsum_list f (s2 ++ s1 ++ s3)).
    { (* 链：A == Σs1 + Σ(s2++s3) == Σs1 + (Σs2+Σs3) == (Σs1+Σs2)+Σs3
               == (Σs2+Σs1)+Σs3 == Σs2 + (Σs1+Σs3) == Σs2 + Σ(s1++s3) == B *)
      apply (CReq_trans (R := R) (CRsum_list f (s1 ++ s2 ++ s3))
                        (CRplus R (CRsum_list f s1) (CRsum_list f (s2 ++ s3)))
                        (CRsum_list f (s2 ++ s1 ++ s3))).
      - apply (CRsum_list_cat (R := R) f s1 (s2 ++ s3)).
      - apply (CReq_trans (R := R)
                (CRplus R (CRsum_list f s1) (CRsum_list f (s2 ++ s3)))
                (CRplus R (CRsum_list f s1) (CRplus R (CRsum_list f s2) (CRsum_list f s3)))
                (CRsum_list f (s2 ++ s1 ++ s3))).
        + apply (CRplus_morph R (CRsum_list f s1) (CRsum_list f s1)
                               (CReq_refl (R := R) (CRsum_list f s1))
                               (CRsum_list f (s2 ++ s3))
                               (CRplus R (CRsum_list f s2) (CRsum_list f s3))
                               (CRsum_list_cat (R := R) f s2 s3)).
        + apply (CReq_trans (R := R)
                  (CRplus R (CRsum_list f s1) (CRplus R (CRsum_list f s2) (CRsum_list f s3)))
                  (CRplus R (CRplus R (CRsum_list f s1) (CRsum_list f s2)) (CRsum_list f s3))
                  (CRsum_list f (s2 ++ s1 ++ s3))).
          * apply (CReq_sym (CRplus R (CRplus R (CRsum_list f s1) (CRsum_list f s2)) (CRsum_list f s3))
                            (CRplus R (CRsum_list f s1) (CRplus R (CRsum_list f s2) (CRsum_list f s3)))
                            (CRplus_assoc (R := R) (CRsum_list f s1)
                                          (CRsum_list f s2) (CRsum_list f s3))).
          * apply (CReq_trans (R := R)
                    (CRplus R (CRplus R (CRsum_list f s1) (CRsum_list f s2)) (CRsum_list f s3))
                    (CRplus R (CRplus R (CRsum_list f s2) (CRsum_list f s1)) (CRsum_list f s3))
                    (CRsum_list f (s2 ++ s1 ++ s3))).
            -- apply (CRplus_morph R
                       (CRplus R (CRsum_list f s1) (CRsum_list f s2))
                       (CRplus R (CRsum_list f s2) (CRsum_list f s1))
                       (CRplus_comm (R := R) (CRsum_list f s1) (CRsum_list f s2))
                       (CRsum_list f s3) (CRsum_list f s3)
                       (CReq_refl (R := R) (CRsum_list f s3))).
            -- apply (CReq_trans (R := R)
                      (CRplus R (CRplus R (CRsum_list f s2) (CRsum_list f s1)) (CRsum_list f s3))
                      (CRplus R (CRsum_list f s2) (CRplus R (CRsum_list f s1) (CRsum_list f s3)))
                      (CRsum_list f (s2 ++ s1 ++ s3))).
               ++ apply (CRplus_assoc (R := R) (CRsum_list f s2)
                                      (CRsum_list f s1) (CRsum_list f s3)).
               ++ apply (CReq_trans (R := R)
                         (CRplus R (CRsum_list f s2) (CRplus R (CRsum_list f s1) (CRsum_list f s3)))
                         (CRplus R (CRsum_list f s2) (CRsum_list f (s1 ++ s3)))
                         (CRsum_list f (s2 ++ s1 ++ s3))).
                   ** apply (CRplus_morph R (CRsum_list f s2) (CRsum_list f s2)
                                          (CReq_refl (R := R) (CRsum_list f s2))
                                          (CRplus R (CRsum_list f s1) (CRsum_list f s3))
                                          (CRsum_list f (s1 ++ s3))
                                          (CReq_sym (CRsum_list f (s1 ++ s3))
                                                    (CRplus R (CRsum_list f s1) (CRsum_list f s3))
                                                    (CRsum_list_cat (R := R) f s1 s3))).
                   ** apply (CReq_sym (CRsum_list f (s2 ++ s1 ++ s3))
                                     (CRplus R (CRsum_list f s2) (CRsum_list f (s1 ++ s3)))
                                     (CRsum_list_cat (R := R) f s2 (s1 ++ s3))).

    }
    unfold P in HP.
    apply (CReq_trans (R := R) (CRsum_list f (s2 ++ s1 ++ s3))
                      (CRsum_list f (s1 ++ s2 ++ s3))
                      (CRsum_list f l2)).
    - exact (CReq_sym (CRsum_list f (s1 ++ s2 ++ s3))
                      (CRsum_list f (s2 ++ s1 ++ s3)) Hmid).
    - exact HP.
  }
  have Hp2 : perm_eq l2 l1.
  { move: Hp. rewrite (perm_sym l1 l2). done. }
  exact (@catCA_perm_ind A P Hstep l2 l1 Hp2
                        (CReq_refl (R := R) (CRsum_list f l2))).
Qed.

(* uniq l 且 l 的元素都在 [1..B] 内，f ≥ 0 ⟹ Σ_{x∈l} f x ≤ Σ_{n=1}^{B} f n
   —— 正向不等式核心：smooth 数（互异、≤∏p^E、≥1）求和 ≤ [1..B] 全和 *)
Lemma CRsum_list_uniq_subset_le {R : ConstructiveReals} (f : nat -> CRcarrier R)
  (l : seq nat) (B : nat)
  (Huniq : uniq l)
  (Hge1 : forall x, x \in l -> (1 <= x)%nat)
  (HleB : forall x, x \in l -> (x <= B)%nat)
  (Hpos : forall n, CRle R (CR_of_Q R Q0q) (f n)) :
  CRle R (CRsum_list f l) (CRsum_list f (iota 1 B)).
Proof.
  pose lf := [seq n <- iota 1 B | n \in l].
  have Hflt : CRle R (CRsum_list f lf) (CRsum_list f (iota 1 B)).
  { unfold lf. apply (CRsum_list_filter_le (R := R) f (iota 1 B) (fun n => n \in l)).
    move => x Hx. apply Hpos. }
  have Hperm : perm_eq l lf.
  { apply (@uniq_perm nat l lf).
    - exact Huniq.
    - unfold lf. apply (subseq_uniq (filter_subseq (fun n => n \in l) (iota 1 B))).
      apply iota_uniq.
    - move => x.
      rewrite mem_filter. apply/idP/idP.
      + move => Hx.
        apply/andP. split.
        * exact Hx.
        * rewrite mem_iota. apply/andP. split.
          -- exact (Hge1 x Hx).
          -- rewrite addnC. rewrite addn1. rewrite ltnS.
             exact (HleB x Hx).
      + move/andP => [Hxl Hxiota].
        exact Hxl. }
  have Heq : CReq R (CRsum_list f l) (CRsum_list f lf) :=
    CRsum_list_perm (R := R) f l lf Hperm.
  apply (CRle_trans (R := R) (CRsum_list f l) (CRsum_list f lf)
                    (CRsum_list f (iota 1 B))).
  - exact (proj2 Heq).
  - exact Hflt.
Qed.

(* ============ 分析层：部分和 ≤ 级数极限 ============ *)

(* 非负项级数的部分和 ≤ 极限：u ≥ 0、CRsum u → l ⟹ CRsum u N ≤ l
   —— 用 CR_cv_bound_down（A ≤ u n 尾部 ⟹ A ≤ l）取 A := CRsum u N *)
Lemma CRsum_le_lim {R : ConstructiveReals} (u : nat -> CRcarrier R) (l : CRcarrier R)
  (Hpos : forall n, CRle R (CR_of_Q R Q0q) (u n))
  (Hcv : CR_cv R (CRsum u) l) :
  forall N : nat, CRle R (CRsum u N) l.
Proof.
  move => N.
  apply (CR_cv_bound_down (R := R) (CRsum u) (CRsum u N) l N).
  - move => n Hn.
    (* CRsum u N ≤ CRsum u n（N ≤ n）：n = N + (n-N)，对 d := n-N 归纳 *)
    move/leP: Hn => Hn'.
    have Hmono : forall d, CRle R (CRsum u N) (CRsum u (N + d)).
    { induction d as [| d IH].
      - rewrite addn0. apply CRle_refl.
      - (* CRsum u (N + d) ≤ CRsum u (N + d.+1) *)
        apply (CRle_trans (R := R) (CRsum u N)
                          (CRsum u (N + d))
                          (CRsum u (N + d.+1))).
        + exact IH.
        + rewrite addnS.
          (* 目标: CRsum u (S (N+d)) = CRsum u (N+d) + u (S(N+d)) *)
          change (CRle R (CRsum u (N + d))
                         (CRplus R (CRsum u (N + d)) (u (N + d).+1))).
          apply (CRle_trans (R := R) (CRsum u (N + d))
                            (CRplus R (CRsum u (N + d)) (CR_of_Q R Q0q))
                            (CRplus R (CRsum u (N + d)) (u (N + d).+1))).
          * rewrite (CRplus_0_r (R := R) (CRsum u (N + d))).
            apply CRle_refl.
          * apply (CRplus_le_compat_l (R := R) (CRsum u (N + d))
                                       (CR_of_Q R Q0q) (u (N + d).+1)).
            apply Hpos. }
    move: (Hmono (n - N)%N).
    (* 目标: CRle (CRsum u N) (CRsum u (N + (n - N))) → 把 N+(n-N) 写成 n *)
    rewrite (subnKC Hn').
    exact id.
  - exact Hcv.
Qed.

(* 非负项级数部分和的单调性：u ≥ 0 ⟹ CRsum u N ≤ CRsum u n（N ≤ n）
   —— CRsum_le_lim 的 N ≤ n 形式，正向不等式 ζ 部分和比较用 *)
Lemma CRsum_mono_le {R : ConstructiveReals} (u : nat -> CRcarrier R)
  (Hpos : forall n, CRle R (CR_of_Q R Q0q) (u n)) :
  forall N n : nat, (N <= n)%N -> CRle R (CRsum u N) (CRsum u n).
Proof.
  move => N n Hn.
  have Hmono : forall d, CRle R (CRsum u N) (CRsum u (N + d)).
  { induction d as [| d IH].
    - rewrite addn0. apply CRle_refl.
    - apply (CRle_trans (R := R) (CRsum u N)
                        (CRsum u (N + d))
                        (CRsum u (N + d.+1))).
      + exact IH.
      + rewrite addnS.
        change (CRle R (CRsum u (N + d))
                       (CRplus R (CRsum u (N + d)) (u (N + d).+1))).
        apply (CRle_trans (R := R) (CRsum u (N + d))
                          (CRplus R (CRsum u (N + d)) (CR_of_Q R Q0q))
                          (CRplus R (CRsum u (N + d)) (u (N + d).+1))).
        * rewrite (CRplus_0_r (R := R) (CRsum u (N + d))).
          apply CRle_refl.
        * apply (CRplus_le_compat_l (R := R) (CRsum u (N + d))
                                     (CR_of_Q R Q0q) (u (N + d).+1)).
          apply Hpos. }
  move: (Hmono (n - N)%N).
  rewrite (subnKC Hn).
  exact id.
Qed.


(* ============================================================
   L4 P→∞：组合正向主引理（∏_{p∈ps}(Σ_{e≤E} p^{-es}) ≤ ζ = 1 + l）
   —— 链：euler_finite_expand → uniq_subset_le → iota1_le_zeta
   ★ 里程碑：正向不等式完成（P→∞ 夹逼的下界侧）
   ============================================================ *)
(* iota 1 B 的拆解：B ≥ 1 ⟹ iota 1 B = iota 1 1 ++ iota 2 (B-1) *)
Lemma iota1_split (B : nat) (HB : (1 <= B)%N) :
  iota 1 B = iota 1 1 ++ iota 2 (B - 1).
Proof.
  rewrite -(iotaD 1 1 (B - 1)).
  f_equal.
  (* 1 + (B - 1) = B：subnKC 正是这个方向 *)
  rewrite (subnKC HB). reflexivity.
Qed.

(* iota 2 (B-1) = map (fun k => 2 + k) (iota 0 (B-1)) = map S(S) (iota 0 (B-1)) *)
Lemma iota2_map (B : nat) :
  iota 2 (B - 1) = [seq (2 + k)%N | k <- iota 0 (B - 1)].
Proof.
  rewrite -(iotaDl 2 0 (B - 1)). rewrite addn0. reflexivity.
Qed.

(* Σ_{n∈iota 1 B} inv_n_pow n s == 1 + Σ_{k=0}^{B-2} inv_n_pow (S(S k)) s（B ≥ 2） *)
Lemma iota1_sum_eq {R : ConstructiveReals} (s B : nat) (HB : (2 <= B)%N) :
  CReq R (CRsum_list (fun n => inv_n_pow n s) (iota 1 B))
         (CRplus R (CR_of_Q R Q1q)
                 (CRsum (fun k => inv_n_pow (S (S k)) s) (B - 2))).
Proof.
  have HB1 : (1 <= B)%N := ltnW HB.
  rewrite (iota1_split B HB1).
  rewrite (CRsum_list_cat (R := R) (fun n => inv_n_pow n s) (iota 1 1) (iota 2 (B - 1))).
  simpl. (* iota 1 1 = [1]，Σ[1] = inv_n_pow 1 s + 0 *)
  rewrite (CRplus_0_r (R := R) (inv_n_pow 1 s)). (* 消掉 + 0 *)
  (* Σ(iota 2 (B-1)) = Σ_{k} (2+k)^{-s} *)
  rewrite (iota2_map B).
  rewrite (CRsum_list_map (R := R) (fun n => inv_n_pow n s) (fun k => (2 + k)%N)
                          (iota 0 (B - 1))).
  apply (CRplus_morph R (inv_n_pow 1 s) (CR_of_Q R Q1q)
                       (inv_n_pow_one (R := R) s)
                       (CRsum_list (fun k => inv_n_pow (2 + k) s) (iota 0 (B - 1)))
                       (CRsum (fun k => inv_n_pow (S (S k)) s) (B - 2))).
  - (* 目标: CRsum_list (fun k => inv_n_pow (2+k) s) (iota 0 (B-1))
          == CRsum (fun k => inv_n_pow (S(S k)) s) (B-2)
        iota 0 (B-1) = iota 0 ((B-2)+1)（B ≥ 2 ⟹ 1 < B） *)
    rewrite -[iota 0 (B - 1)](congr1 (iota 0) (subnSK HB)).
    rewrite -[iota 0 ((B - 2).+1)](congr1 (iota 0) (addn1 (B - 2))).
    rewrite (CRsum_list_iota (R := R) (fun k => inv_n_pow (2 + k) s) (B - 2)).
    apply (CRsum_eq (R := R) (fun k => inv_n_pow (2 + k) s)
                    (fun k => inv_n_pow (S (S k)) s) (B - 2)).
    move => k Hk.
    apply CReq_refl.
Qed.

(* ============ 组合正向主引理 ============ *)

(* inv_n_pow 非负：0 ≤ n^{-s}（Qinv_n 0 = 1 ⟹ 0^{-s} = 1^s = 1 ≥ 0；用于 CRsum_le_lim Hpos） *)
Lemma inv_n_pow_ge0 {R : ConstructiveReals} (n s : nat) :
  CRle R (CR_of_Q R Q0q) (inv_n_pow n s).
Proof.
  unfold inv_n_pow.
  apply (CRpow_ge_zero (CR_of_Q R (Qinv_n n)) s).
  apply CR_of_Q_le.
  unfold Qinv_n, Q0q, Qle. simpl. lia.
Qed.

(* Σ_{n=1}^{B} n^{-s} ≤ 1 + l（l = ζ 级数 Σ_{n≥0}(S(S n))^{-s} 的极限）
   —— iota1_sum_eq（拆 1 与 2..B）+ CRsum_le_lim（部分和 ≤ 极限） *)
Lemma iota1_le_zeta {R : ConstructiveReals} (s B : nat) (Hs2 : (2 <= s)%nat)
  (HB : (2 <= B)%N) :
  CRle R (CRsum_list (fun n => inv_n_pow n s) (iota 1 B))
         (CRplus R (CR_of_Q R Q1q) (projT1 (zeta_series_cv (R := R) s Hs2))).
Proof.
  (* Σ_{n=1}^{B} n^{-s} == 1 + Σ_{k=0}^{B-2} (S(S k))^{-s} *)
  have Heq := iota1_sum_eq (R := R) s B HB.
  (* Σ_{k=0}^{B-2} (S(S k))^{-s} ≤ l（部分和 ≤ 极限，项非负） *)
  have Hle : CRle R
    (CRsum (fun k => inv_n_pow (S (S k)) s) (B - 2))
    (projT1 (zeta_series_cv (R := R) s Hs2)).
  { apply (CRsum_le_lim (R := R) (fun k => inv_n_pow (S (S k)) s)
                        (projT1 (zeta_series_cv (R := R) s Hs2))).
    - move => k. apply (inv_n_pow_ge0 (R := R) (S (S k)) s).
    - exact (projT2 (zeta_series_cv (R := R) s Hs2)). }
  (* 用 Heq 把左边换成 1 + Σ，然后 1 + (Σ ≤ l) ≤ 1 + l *)
  apply (CRle_trans (R := R)
          (CRsum_list (fun n => inv_n_pow n s) (iota 1 B))
          (CRplus R (CR_of_Q R Q1q) (CRsum (fun k => inv_n_pow (S (S k)) s) (B - 2)))
          (CRplus R (CR_of_Q R Q1q) (projT1 (zeta_series_cv (R := R) s Hs2)))).
  - exact (proj1 (CReq_sym (CRsum_list (fun n => inv_n_pow n s) (iota 1 B))
                           (CRplus R (CR_of_Q R Q1q)
                                   (CRsum (fun k => inv_n_pow (S (S k)) s) (B - 2)))
                           Heq)).
  - apply (CRplus_le_compat_l (R := R) (CR_of_Q R Q1q)
                               (CRsum (fun k => inv_n_pow (S (S k)) s) (B - 2))
                               (projT1 (zeta_series_cv (R := R) s Hs2))).
    exact Hle.
Qed.

(* ============ 正向主引理：∏_{p∈ps}(Σ_{e≤E} p^{-es}) ≤ ζ = 1 + l ============ *)

(* ps 全素数且去重、s ≥ 2、E 任意：
   ∏_{p∈ps}(Σ_{e≤E} p^{-es}) ≤ 1 + Σ_{n≥2} n^{-s}（ζ 值）
   链：euler_finite_expand（∏==Σ_smooth x^{-s}）
     → CRsum_list_uniq_subset_le（Σ_smooth ≤ Σ_{n=1}^{B} n^{-s}，B=∏p^E）
     → iota1_le_zeta（Σ_{n=1}^{B} n^{-s} ≤ 1 + l） *)
Lemma euler_prod_le_zeta {R : ConstructiveReals} (ps : seq nat) (s E : nat)
  (Hs2 : (2 <= s)%nat) (Hps : all prime ps) (Huniq : uniq ps) :
  CRle R (CRprod_list (fun p => CRsum (fun e => inv_n_pow (p ^ e) s) E) ps)
         (CRplus R (CR_of_Q R Q1q) (projT1 (zeta_series_cv (R := R) s Hs2))).
Proof.
  (* 1) ∏(Σ_e) == Σ_{x∈smooth} x^{-s} *)
  have Hexpand := euler_finite_expand (R := R) ps s E Hps.
  (* 2) Σ_{x∈smooth} x^{-s} ≤ Σ_{n=1}^{B} n^{-s}（B = ∏p^E，smooth 互异且 ⊆[1..B]） *)
  pose B := nat_prod_list (fun p => (p ^ E)%N) ps.
  have Hsmooth_le : CRle R (CRsum_list (fun x => inv_n_pow x s) (smooth_list E ps))
                           (CRsum_list (fun n => inv_n_pow n s) (iota 1 B)).
  { apply (CRsum_list_uniq_subset_le (R := R) (fun n => inv_n_pow n s)
                                     (smooth_list E ps) B).
    - exact (smooth_list_uniq E ps Hps Huniq).
    - move => x Hx. exact (smooth_list_ge1 E ps Hps x Hx).
    - move => x Hx. exact (smooth_list_bound E ps Hps x Hx).
    - move => n. apply (inv_n_pow_ge0 (R := R) n s). }
  (* 3) Σ_{n=1}^{B} n^{-s} ≤ 1 + l：对 B case（0/1/≥2） *)
  have Hiota : CRle R (CRsum_list (fun n => inv_n_pow n s) (iota 1 B))
                       (CRplus R (CR_of_Q R Q1q) (projT1 (zeta_series_cv (R := R) s Hs2))).
  { destruct B as [| [| B'] ].
    - (* B = 0：iota 1 0 = []，Σ = 0 ≤ 1 + l *)
      simpl. apply (CRle_trans (R := R) (CR_of_Q R Q0q)
                                (CR_of_Q R Q1q)
                                (CRplus R (CR_of_Q R Q1q)
                                        (projT1 (zeta_series_cv (R := R) s Hs2)))).
      + exact (CRle_0_one (R := R)).
      + (* 1 ≤ 1 + l：1 + 0 ≤ 1 + l 归一化（0 ≤ l） *)
        have H10 : CRle R (CRplus R (CR_of_Q R Q1q) (CR_of_Q R Q0q))
                           (CRplus R (CR_of_Q R Q1q) (projT1 (zeta_series_cv (R := R) s Hs2))).
        { apply (CRplus_le_compat_l (R := R) (CR_of_Q R Q1q)
                                     (CR_of_Q R Q0q) (projT1 (zeta_series_cv (R := R) s Hs2))).
          apply (series_cv_nonneg (R := R)
                   (fun n => inv_n_pow (S (S n)) s)
                   (projT1 (zeta_series_cv (R := R) s Hs2))).
          * move => n. apply (inv_n_pow_ge0 (R := R) (S (S n)) s).
          * exact (projT2 (zeta_series_cv (R := R) s Hs2)). }
        apply (proj2 (CRle_morph R
                        (CR_of_Q R Q1q)
                        (CRplus R (CR_of_Q R Q1q) (CR_of_Q R Q0q))
                        (CReq_sym (CRplus R (CR_of_Q R Q1q) (CR_of_Q R Q0q))
                                  (CR_of_Q R Q1q)
                                  (CRplus_0_r (R := R) (CR_of_Q R Q1q)))
                        (CRplus R (CR_of_Q R Q1q) (projT1 (zeta_series_cv (R := R) s Hs2)))
                        (CRplus R (CR_of_Q R Q1q) (projT1 (zeta_series_cv (R := R) s Hs2)))
                        (CReq_refl (R := R) (CRplus R (CR_of_Q R Q1q)
                                                      (projT1 (zeta_series_cv (R := R) s Hs2)))))).
        exact H10.
    - (* B = 1：iota 1 1 = [1]，Σ = inv_n_pow 1 s + 0 == inv_n_pow 1 s == 1 ≤ 1 + l *)
      simpl. (* CRsum_list f [1] = inv_n_pow 1 s + 0 *)
      apply (CRle_trans (R := R)
              (CRplus R (inv_n_pow 1 s) (CR_of_Q R Q0q))
              (inv_n_pow 1 s)
              (CRplus R (CR_of_Q R Q1q)
                      (projT1 (zeta_series_cv (R := R) s Hs2)))).
      + apply (proj2 (CRplus_0_r (R := R) (inv_n_pow 1 s))).
      + apply (CRle_trans (R := R) (inv_n_pow 1 s)
                                (CR_of_Q R Q1q)
                                (CRplus R (CR_of_Q R Q1q)
                                        (projT1 (zeta_series_cv (R := R) s Hs2)))).
        * exact (proj2 (inv_n_pow_one (R := R) s)).
        * (* 1 ≤ 1 + l：1 + 0 ≤ 1 + l 归一化（0 ≤ l） *)
          have H11 : CRle R (CRplus R (CR_of_Q R Q1q) (CR_of_Q R Q0q))
                             (CRplus R (CR_of_Q R Q1q) (projT1 (zeta_series_cv (R := R) s Hs2))).
          { apply (CRplus_le_compat_l (R := R) (CR_of_Q R Q1q)
                                       (CR_of_Q R Q0q) (projT1 (zeta_series_cv (R := R) s Hs2))).
            apply (series_cv_nonneg (R := R)
                     (fun n => inv_n_pow (S (S n)) s)
                     (projT1 (zeta_series_cv (R := R) s Hs2))).
            * move => n. apply (inv_n_pow_ge0 (R := R) (S (S n)) s).
            * exact (projT2 (zeta_series_cv (R := R) s Hs2)). }
          exact (proj2 (CRle_morph R
                          (CR_of_Q R Q1q)
                          (CRplus R (CR_of_Q R Q1q) (CR_of_Q R Q0q))
                          (CReq_sym (CRplus R (CR_of_Q R Q1q) (CR_of_Q R Q0q))
                                    (CR_of_Q R Q1q)
                                    (CRplus_0_r (R := R) (CR_of_Q R Q1q)))
                          (CRplus R (CR_of_Q R Q1q) (projT1 (zeta_series_cv (R := R) s Hs2)))
                          (CRplus R (CR_of_Q R Q1q) (projT1 (zeta_series_cv (R := R) s Hs2)))
                          (CReq_refl (R := R) (CRplus R (CR_of_Q R Q1q)
                                                        (projT1 (zeta_series_cv (R := R) s Hs2)))))
                  H11).
    - (* B ≥ 2：iota1_le_zeta *)
      have HB2 : (2 <= (S (S B')))%N.
      { apply/leP. apply le_n_S. apply le_n_S. exact (Nat.le_0_l B'). }
      exact (iota1_le_zeta (R := R) s (S (S B')) Hs2 HB2). }
  (* 4) 组合：∏ == Σ_smooth ≤ Σ_{n=1}^{B} ≤ 1 + l *)
  apply (CRle_trans (R := R)
          (CRprod_list (fun p => CRsum (fun e => inv_n_pow (p ^ e) s) E) ps)
          (CRsum_list (fun x => inv_n_pow x s) (smooth_list E ps))
          (CRplus R (CR_of_Q R Q1q) (projT1 (zeta_series_cv (R := R) s Hs2)))).
  - exact (proj2 Hexpand).
  - apply (CRle_trans (R := R)
           (CRsum_list (fun x => inv_n_pow x s) (smooth_list E ps))
           (CRsum_list (fun n => inv_n_pow n s) (iota 1 B))
           (CRplus R (CR_of_Q R Q1q) (projT1 (zeta_series_cv (R := R) s Hs2)))).
    + exact Hsmooth_le.
    + exact Hiota.
Qed.


(* ============================================================
   L4 P→∞：反向分解砖块（ζ ≤ ∏(1-p^{-s})^{-1} + 尾部）
   —— not_smooth_has_big_prime / not_smooth_le_gt / logn_split / mul_in_smooth
   —— smooth_in（素因子 ⊆ ps ⟹ ∈ smooth_list）与反向主引理待续
   ============================================================ *)
(* ¬smooth_le P n ⟹ ∃ q ∈ primes n, q > P（非 smooth ⟹ 有素因子 > P）
   —— smooth_le 的定义是 all (≤ P)，否定展开后有元素 > P
   —— 结论用 Prop exists（Set sig 无法从 allPn 消除） *)
Lemma not_smooth_has_big_prime (P n : nat) :
  ~~ (smooth_le P n) -> exists q : nat, q \in primes n /\ (P < q)%nat.
Proof.
  rewrite /smooth_le.
  move => H.
  move: H => /allPn [q Hq Hnot].
  exists q. split.
  - exact Hq.
  - move: Hnot. rewrite -ltnNge. move => Hqgt. exact Hqgt.
Qed.

(* q ∈ primes n ⟹ q | n ⟹ n ≥ q（q > 0）⟹ n > P（q > P）
   —— 非 smooth ⟹ n 有素因子 > P ⟹ n > P *)
Lemma not_smooth_le_gt (P n : nat) (Hn1 : (1 <= n)%nat) :
  ~~ (smooth_le P n) -> (P < n)%nat.
Proof.
  move => Hnot.
  destruct (not_smooth_has_big_prime P n Hnot) as [q [Hq Hqgt]].
  rewrite mem_primes in Hq.
  move/andP : Hq => [Hqpr /andP [Hq0 Hqdvd]].
  (* q | n 且 n > 0 ⟹ q ≤ n；P < q ≤ n ⟹ P < n *)
  have Hqle : (q <= n)%nat := @dvdn_leq q n Hq0 Hqdvd.
  (* case q = n：P < n 直接由 Hqgt；case q < n：ltn_trans *)
  destruct (Nat.eqb_spec q n) as [Hqn | Hqn'].
  - rewrite Hqn in Hqgt. exact Hqgt.
  - have Hqlt : (q < n)%nat.
    { rewrite ltn_neqAle. apply/andP. split.
      - apply/eqP. exact Hqn'.
      - exact Hqle. }
    exact (ltn_trans Hqgt Hqlt).
Qed.


(* ============ smooth 覆盖：n ≤ N 且素因子 ⊆ ps ⟹ n ∈ smooth_list N ps ============ *)

(* 核心：n = (n 去 p 部分) · p^{logn p n}（pfactor_dvdn + divnK） *)
Lemma logn_split (p n : nat) (Hp : prime p) (Hn0 : (0 < n)%nat) :
  (n = (divn n (p ^ logn p n)) * p ^ logn p n)%N.
Proof.
  have Hdvd : p ^ logn p n %| n.
  { rewrite (@pfactor_dvdn p (logn p n) n Hp Hn0). apply leqnn. }
  rewrite (divnK Hdvd). reflexivity.
Qed.

(* 乘入保持：x ∈ smooth_list E ps'、e ≤ E ⟹ x·p^e ∈ smooth_list E (p::ps') *)
(* 乘入保持：x ∈ smooth_list E ps'、e ≤ E ⟹ x·p^e ∈ smooth_list E (p::ps') —— allpairs_f 一行 *)
Lemma mul_in_smooth (E p : nat) (ps' : seq nat) (x : nat) (e : nat)
  (Hx : x \in smooth_list E ps') (He : (e <= E)%N) :
  (x * p ^ e)%N \in smooth_list E (p :: ps').
Proof.
  rewrite /smooth_list.
  apply (@allpairs_f nat nat nat (fun x0 e0 => (x0 * p ^ e0)%N)
                     (smooth_list E ps') (iota 0 (E + 1)) x e).
  - exact Hx.
  - rewrite mem_iota. apply/andP. split. done.
    rewrite add0n. rewrite addn1. rewrite ltnS. exact He.
Qed.

(* smooth_in：n ≥ 1、素因子(n) ⊆ ps、∀p∈ps logn p n ≤ E ⟹ n ∈ smooth_list E ps
   —— L4 P→∞ 反向分解的核心：每个素因子在 ps 内且指数 ≤ E 的 n 一定被
      smooth_list E ps 枚举到（唯一分解 + 归纳展开）
   —— 对 ps 归纳：
      * 基础 []：素因子 ⊆ [] ⟹ primes n = []（eq_all+all_pred0+size_eq0）
        ⟹ n < 2（primes_eq0）⟹ n = 1 ∈ [::1]（mem_seq1）
      * 归纳 p::ps'：logn_split 剥离 n = x·p^e（x = n %/ p^e, e = logn p n），
        p ∤ x（logn_div: logn p x = logn p n - logn p (p^e) = e - e = 0），
        x 素因子 ⊆ ps'（q|x ⟹ q|n ⟹ q∈p::ps'，q≠p ⟹ q∈ps'），
        指数 logn q x ≤ logn q n（lognM 单调）≤ E（Hexp），
        IH 给 x ∈ smooth_list E ps'，mul_in_smooth 乘回 x·p^e ∈ smooth_list E (p::ps')。 *)
Lemma smooth_in (E : nat) (ps : seq nat) (n : nat)
  (Hps : all prime ps) (Hn1 : (1 <= n)%nat)
  (Hsub : all (fun q => q \in ps) (primes n))
  (Hexp : forall p, p \in ps -> (logn p n <= E)%nat) :
  n \in smooth_list E ps.
Proof.
  revert n Hn1 Hsub Hexp.
  elim: ps Hps => [| p ps' IH] Hps n Hn1 Hsub Hexp.
  - (* 基础：ps = [] ⟹ smooth_list E [] = [:: 1]，需证 n = 1 *)
    rewrite /smooth_list.
    (* 素因子(n) ⊆ [] ⟹ primes n = [] *)
    have Hpr : primes n = [::].
    { have Hpred : (fun q : nat => q \in [::]) =1 pred0.
      { move => q. rewrite in_nil. reflexivity. }
      move: Hsub. rewrite (eq_all Hpred). rewrite all_pred0.
      move => Hsz0. apply/eqP. rewrite -size_eq0. exact Hsz0. }
    (* primes n = [] ⟹ n < 2（primes_eq0） *)
    have Hn2 : (n < 2)%nat.
    { rewrite -(primes_eq0 n). apply/eqP. exact Hpr. }
    (* n < 2 且 1 ≤ n ⟹ n = 1 *)
    have Hn1eq : n = 1%nat.
    { apply/eqP. rewrite eqn_leq. apply/andP. split.
      - move: Hn2. rewrite ltnS. exact id.
      - exact Hn1. }
    (* n ∈ [:: 1] ⟺ n == 1 *)
    rewrite Hn1eq. rewrite mem_seq1. reflexivity.
  - (* 归纳：ps = p :: ps' *)
    have Hp : prime p := allP Hps p (mem_head p ps').
    have Hps' : all prime ps'.
    { apply/allP. move => y Hy.
      apply (allP Hps y).
      rewrite in_cons. apply/orP. right. exact Hy. }
    have Hn0 : (0 < n)%nat := Hn1.
    (* 剥离：n = x·p^e，x = n %/ p^e，e = logn p n（logn_split 已 Qed） *)
    have Hsplit := logn_split p n Hp Hn0.
    pose x := n %/ p ^ logn p n.
    pose e := logn p n.
    have Hsplit' : (n = x * p ^ e)%N.
    { rewrite /x /e. exact Hsplit. }
    (* 0 < x：n = x·p^e > 0 且 p^e > 0 ⟹ x > 0 *)
    have Hpe0 : (0 < p ^ e)%nat.
    { rewrite expn_gt0. rewrite (@prime_gt0 p Hp). simpl. reflexivity. }
    have Hx0 : (0 < x)%nat.
    { move: Hn0. rewrite Hsplit'. rewrite muln_gt0.
      move/andP => [Hx _]. exact Hx. }
    (* p ∤ x：logn p x = logn p n - logn p (p^e) = e - e = 0 ⟹ p ∉ primes x *)
    have Hlogx : logn p x = 0%nat.
    { rewrite /x.
      have Hdvd : p ^ e %| n.
      { rewrite (@pfactor_dvdn p e n Hp Hn0). apply leqnn. }
      rewrite (@logn_div p (p ^ e) n Hdvd).
      rewrite /e.
      rewrite (@lognX p p (logn p n)).
      rewrite (@logn_prime p p Hp).
      rewrite eqxx.
      rewrite muln1.
      rewrite subnn. reflexivity. }
    have Hpx : ~~ (p %| x).
    { apply/negP. move => Hpdvd.
      have Hlg : (0 < logn p x)%nat.
      { rewrite logn_gt0. rewrite mem_primes. apply/andP. split. exact Hp.
        apply/andP. split. exact Hx0. exact Hpdvd. }
      rewrite Hlogx in Hlg. done. }
    (* x | n：n = x·p^e ⟹ x | n *)
    have Hxdn : x %| n.
    { rewrite Hsplit'. apply dvdn_mulr. apply dvdnn. }
    (* 素因子(x) ⊆ ps' *)
    have Hxsub : all (fun q => q \in ps') (primes x).
    { apply/allP. move => q Hq.
      rewrite mem_primes in Hq. move/andP : Hq => [Hqpr /andP [Hqx0 Hqdx]].
      have Hqdn : q %| n := dvdn_trans Hqdx Hxdn.
      have Hqin : q \in primes n.
      { rewrite mem_primes. apply/andP. split. exact Hqpr. apply/andP. split.
        exact Hn0. exact Hqdn. }
      have Hqps : q \in p :: ps' := allP Hsub q Hqin.
      rewrite in_cons in Hqps. move/orP : Hqps => [Hqp | Hqps'].
      - (* q == p：与 p ∤ x 矛盾 *)
        move/eqP : Hqp => Hqp'. rewrite Hqp' in Hqdx.
        move/negP : Hpx => Hpx'. exfalso. exact (Hpx' Hqdx).
      - exact Hqps'. }
    (* 指数：∀q∈ps', logn q x ≤ E（logn q x ≤ logn q n ≤ E） *)
    have Hxexp : forall q, q \in ps' -> (logn q x <= E)%nat.
    { move => q Hqps'.
      have Hqps : q \in p :: ps'.
      { rewrite in_cons. apply/orP. right. exact Hqps'. }
      have Hle : (logn q x <= logn q n)%nat.
      { (* logn q n = logn q (x·p^e) = logn q x + logn q (p^e) ≥ logn q x *)
        rewrite Hsplit'.
        rewrite (@lognM q x (p ^ e) Hx0 Hpe0).
        apply leq_addr. }
      exact (leq_trans Hle (Hexp q Hqps)). }
    (* IH：x ∈ smooth_list E ps'（Hx0 : 0 < x 即 1 ≤ x） *)
    have Hx : x \in smooth_list E ps' := IH Hps' x Hx0 Hxsub Hxexp.
    (* e ≤ E：Hexp p（p ∈ p::ps'） *)
    have HeE : (e <= E)%nat := Hexp p (mem_head p ps').
    (* 乘回：x·p^e ∈ smooth_list E (p::ps')，rewrite n = x·p^e *)
    have Hnins : (x * p ^ e)%N \in smooth_list E (p :: ps') :=
      mul_in_smooth E p ps' x e Hx HeE.
    rewrite Hsplit'. exact Hnins.
Qed.

(* ============================================================
   L4 P→∞：反向主引理砖块（smooth_cover）
   —— logn_le_exp_bound（指数界）+ smooth_cover（n≤N 素因子⊆ps ⟹ ∈smooth_list）
   ============================================================ *)

(* 指数界：n ≤ 2^E、p 素数、p ∈ primes n ⟹ logn p n ≤ E
   —— 反向主引理调用 smooth_in 的关键：smooth_in 需要 ∀p∈ps, logn p n ≤ E，
     而这里从「n 被 2^E 界住」给出。证明链：
     p^{logn p n} | n（pfactor_dvdn）⟹ p^{logn p n} ≤ n（dvdn_leq）
     ⟹ 2^{logn p n} ≤ p^{logn p n}（leq_exp2r，p≥2）⟹ 2^{logn p n} ≤ 2^E
     ⟹ logn p n ≤ E（leq_exp2l）。 *)
Lemma logn_le_exp_bound (p n E : nat) (Hp : prime p)
  (Hpn : p \in primes n) (HnE : (n <= 2 ^ E)%N) : (logn p n <= E)%N.
Proof.
  (* p^{logn p n} | n（pfactor_dvdn 取 n = logn p n）⟹ p^{logn p n} ≤ n *)
  have Hn0 : (0 < n)%N.
  { rewrite mem_primes in Hpn. move/andP : Hpn => [_ /andP [Hn0 _]].
    exact Hn0. }
  have Hpe : (p ^ logn p n <= n)%N.
  { have Hdvd : p ^ logn p n %| n.
    { rewrite (@pfactor_dvdn p (logn p n) n Hp Hn0).
      apply leqnn. }
    exact (dvdn_leq Hn0 Hdvd). }
  (* p ≥ 2 ⟹ p^{logn p n} ≥ 2^{logn p n}（leq_exp2r：0<e ⟹ (m^e≤n^e)=(m≤n)） *)
  have Hp2 : (2 <= p)%N := prime_gt1_mc p Hp.
  have H2le : (2 ^ logn p n <= p ^ logn p n)%N.
  { have Hlg0 : (0 < logn p n)%N.
    { rewrite logn_gt0. exact Hpn. }
    rewrite (@leq_exp2r 2 p (logn p n) Hlg0). exact Hp2. }
  (* 2^{logn p n} ≤ p^{logn p n} ≤ n ≤ 2^E ⟹ logn p n ≤ E（leq_exp2l） *)
  have H2E : (2 ^ logn p n <= 2 ^ E)%N.
  { exact (leq_trans H2le (leq_trans Hpe HnE)). }
  (* leq_exp2l：1<2 ⟹ (2^a ≤ 2^b) = (a ≤ b) *)
  have H2gt1 : (1 < 2)%N := ltnSn 1.
  move: H2E. rewrite (@leq_exp2l 2 (logn p n) E H2gt1). exact id.
Qed.

(* smooth_cover：n ≤ N、素因子(n) ⊆ ps、N ≤ 2^E、ps 全素数
   ⟹ n ∈ smooth_list E ps
   —— smooth_in 的直接实例化：logn_le_exp_bound 提供指数条件
     （p ∈ ps ⟹ prime p（Hps）；logn p n = 0 平凡或 p|n ⟹ p∈primes n ⟹ 指数界）。 *)
Lemma smooth_cover (E N : nat) (ps : seq nat) (n : nat)
  (Hps : all prime ps) (Hn1 : (1 <= n)%N)
  (Hsub : all (fun q => q \in ps) (primes n))
  (HnN : (n <= N)%N) (HNE : (N <= 2 ^ E)%N) :
  n \in smooth_list E ps.
Proof.
  apply (smooth_in E ps n Hps Hn1 Hsub).
  move => p Hpin.
  (* p ∈ ps ⟹ prime p（Hps）；指数界：logn p n = 0 平凡，或 p|n ⟹ logn_le_exp_bound *)
  have Hpp : prime p := allP Hps p Hpin.
  destruct (logn p n) as [| lg'] eqn:Hlg.
  - (* logn p n = 0 ≤ E *)
    exact (leq0n E).
  - (* logn p n = lg'.+1 > 0 ⟹ p | n（logn_gt0 反向）⟹ p ∈ primes n ⟹ 用 logn_le_exp_bound *)
    have Hpos : (0 < logn p n)%N.
    { rewrite Hlg. apply ltn0Sn. }
    have Hpn : p \in primes n.
    { rewrite -logn_gt0. exact Hpos. }
    have Hn2E : (n <= 2 ^ E)%N := leq_trans HnN HNE.
    rewrite -Hlg.
    exact (logn_le_exp_bound p n E Hpp Hpn Hn2E).
Qed.

(* ============================================================
   L4 P→∞：反向主引理地基（subset_le + primes_leq）
   —— CRsum_list_subset_le：列表子集和 ≤（反向夹逼核心）
   —— primes_leq：≤P 素数列表（smooth 判定与素因子⊆ps 桥接）
   ============================================================ *)

(* l 的元素 ⊆ m 的元素、两者 uniq、f ≥ 0 ⟹ Σf l ≤ Σf m
   —— 反向主引理核心工具：smooth 段（∈smooth_list 的 n）≤ Σ_{smooth_list}；
      非 smooth 段 ≤ Σ_{尾部}。m uniq 保证不重计。
   —— 证明：m 中属于 l 的部分 mf = filter(∈l) m；Σf mf ≤ Σf m（filter_le）；
      l 与 mf 置换（都是 uniq 且元素相同 ⟹ uniq_perm）。 *)
Lemma CRsum_list_subset_le {R : ConstructiveReals} (f : nat -> CRcarrier R)
  (l m : seq nat)
  (Huniql : uniq l) (Huniqm : uniq m)
  (Hsub : forall x, x \in l -> x \in m)
  (Hpos : forall n, CRle R (CR_of_Q R Q0q) (f n)) :
  CRle R (CRsum_list f l) (CRsum_list f m).
Proof.
  pose mf := [seq x <- m | x \in l].
  have Hflt : CRle R (CRsum_list f mf) (CRsum_list f m).
  { unfold mf. apply (CRsum_list_filter_le (R := R) f m (fun x => x \in l)).
    move => x Hx. apply Hpos. }
  have Hperm : perm_eq l mf.
  { apply (@uniq_perm nat l mf).
    - exact Huniql.
    - unfold mf. apply (subseq_uniq (filter_subseq (fun x => x \in l) m)).
      exact Huniqm.
    - move => x.
      rewrite mem_filter. apply/idP/idP.
      + move => Hx. apply/andP. split. exact Hx. exact (Hsub x Hx).
      + move/andP => [Hxl _]. exact Hxl. }
  have Heq : CReq R (CRsum_list f l) (CRsum_list f mf) :=
    CRsum_list_perm (R := R) f l mf Hperm.
  apply (CRle_trans (R := R) (CRsum_list f l) (CRsum_list f mf)
                    (CRsum_list f m)).
  - exact (proj2 Heq).
  - exact Hflt.
Qed.

(* ≤P 素数列表：1..P 中的素数（去重、全素数）
   —— 反向主引理里 smooth 判定 smooth_le P（素因子 ≤ P）与
      smooth_cover 的素因子⊆ps 之间的桥：ps := primes_leq P 时二者一致。 *)
Definition primes_leq (P : nat) : seq nat :=
  [seq p <- iota 1 P | prime p].

(* 全素数（filter 保证） *)
Lemma primes_leq_all_prime (P : nat) : all prime (primes_leq P).
Proof.
  apply/allP. move => p Hp. rewrite /primes_leq mem_filter in Hp.
  move/andP : Hp => [Hp _]. exact Hp.
Qed.

(* 去重（iota 去重 + filter 保去重） *)
Lemma primes_leq_uniq (P : nat) : uniq (primes_leq P).
Proof.
  apply (subseq_uniq (filter_subseq (fun p : nat => prime p) (iota 1 P))).
  apply iota_uniq.
Qed.

(* 关键：p ∈ primes_leq P ⟹ p ≤ P（bool 蕴含直接证） *)
Lemma mem_primes_leq_le (p P : nat) (Hin : p \in primes_leq P) : (p <= P)%N.
Proof.
  rewrite /primes_leq mem_filter in Hin.
  move/andP : Hin => [_ Hiota].
  rewrite mem_iota in Hiota.
  move/andP : Hiota => [_ Hlt].
  move: Hlt. rewrite addnC. rewrite addn1. rewrite ltnS. exact id.
Qed.

(* 关键：prime p ∧ p ≤ P ⟹ p ∈ primes_leq P（bool 蕴含直接证） *)
Lemma primes_leq_mem (p P : nat) (Hp : prime p) (HpP : (p <= P)%N) :
  p \in primes_leq P.
Proof.
  rewrite /primes_leq mem_filter. apply/andP. split. exact Hp.
  rewrite mem_iota. apply/andP. split.
  - apply (@prime_gt0 p Hp).
  - rewrite addnC. rewrite addn1. rewrite ltnS. exact HpP.
Qed.

(* ============================================================
   L4 P→∞：反向主引理（ζ 部分和 ≤ ∏(Σ_e) + 尾部）
   —— le_smooth_le / smooth_prefix_cover / iota_prefix_tail /
      zeta_partial_le_euler_prod_tail
   —— 结构：Σ_{n=1}^{N} = Σ_{n=1}^{P} + Σ_{n=P+1}^{N}（iota 拆分）；
      [1..P] 全 smooth（n ≤ P ⟹ 素因子 ≤ n ≤ P）⟹ smooth_cover 覆盖进
      smooth_list E ps ⟹ ∏ 展开；[P+1..N] 即尾部（n > P）。
   ============================================================ *)

(* n ≤ P ⟹ smooth_le P n（素因子 q | n ⟹ q ≤ n ≤ P） *)
Lemma le_smooth_le (P n : nat) (Hn : (n <= P)%N) : smooth_le P n.
Proof.
  apply/allP. move => q Hq.
  rewrite mem_primes in Hq. move/andP : Hq => [Hqpr /andP [Hq0 Hqdvd]].
  have Hqle : (q <= n)%N := dvdn_leq Hq0 Hqdvd.
  exact (leq_trans Hqle Hn).
Qed.

(* n ≤ P ≤ N ≤ 2^E ⟹ n ∈ smooth_list E (primes_leq P)
   —— smooth_cover 实例化：n ≤ P 时素因子自动 ≤ P（le_smooth_le），
     且 n ≤ N ≤ 2^E 给指数界。 *)
Lemma smooth_prefix_cover (E N P n : nat) (Hn1 : (1 <= n)%N)
  (HnP : (n <= P)%N) (HPN : (P <= N)%N) (HNE : (N <= 2 ^ E)%N) :
  n \in smooth_list E (primes_leq P).
Proof.
  apply (smooth_cover E N (primes_leq P) n (primes_leq_all_prime P) Hn1).
  - apply/allP. move => q Hq.
    have Hqpr : prime q.
    { rewrite mem_primes in Hq. move/andP : Hq => [Hqpr _]. exact Hqpr. }
    have Hqle : (q <= P)%N.
    { move: (le_smooth_le P n HnP). rewrite /smooth_le. move => /allP Hs'.
      exact (Hs' q Hq). }
    exact (primes_leq_mem q P Hqpr Hqle).
  - exact (leq_trans HnP HPN).
  - exact HNE.
Qed.

(* iota 1 N = iota 1 P ++ iota (P+1) (N-P)（P ≤ N）
   —— iotaD：iota 1 (P+(N-P)) = iota 1 P ++ iota (1+P) (N-P) *)
Lemma iota_prefix_tail (N P : nat) (HPN : (P <= N)%N) :
  iota 1 N = iota 1 P ++ iota (P + 1) (N - P).
Proof.
  rewrite addnC. (* RHS：iota (P+1) 参数 P+1 → 1+P *)
  rewrite -(iotaD 1 P (N - P)). (* RHS：iota 1 P ++ iota (1+P) (N-P) → iota 1 (P + (N-P)) *)
  rewrite (subnKC HPN). (* RHS：iota 1 (P + (N-P)) → iota 1 N *)
  reflexivity.
Qed.

(* 反向主引理：Σ_{n=1}^{N} n^{-s} ≤ Σ_{x∈smooth_list E (primes_leq P)} x^{-s} + Σ_{n=P+1}^{N} n^{-s}
   —— P ≤ N ≤ 2^E；[1..P] 全被 smooth_list 覆盖（smooth_prefix_cover），
     [P+1..N] 即尾部（n > P）。
   —— 这是 euler_product 主定理的上界侧：ζ_N ≤ ∏(Σ_e) + 尾部。 *)
Lemma zeta_partial_le_euler_prod_tail {R : ConstructiveReals} (s E N P : nat)
  (Hs2 : (2 <= s)%N) (HPN : (P <= N)%N) (HNE : (N <= 2 ^ E)%N) :
  CRle R (CRsum_list (fun n => inv_n_pow n s) (iota 1 N))
         (CRplus R
            (CRsum_list (fun n => inv_n_pow n s)
                        (smooth_list E (primes_leq P)))
            (CRsum_list (fun n => inv_n_pow n s) (iota (P + 1) (N - P)))).
Proof.
  rewrite (iota_prefix_tail N P HPN).
  apply (CRle_trans (R := R)
           (CRsum_list (fun n => inv_n_pow n s)
                       (iota 1 P ++ iota (P + 1) (N - P)))
           (CRplus R (CRsum_list (fun n => inv_n_pow n s) (iota 1 P))
                    (CRsum_list (fun n => inv_n_pow n s) (iota (P + 1) (N - P))))
           (CRplus R (CRsum_list (fun n => inv_n_pow n s)
                                 (smooth_list E (primes_leq P)))
                    (CRsum_list (fun n => inv_n_pow n s) (iota (P + 1) (N - P))))).
  - apply (proj2 (CRsum_list_cat (R := R) (fun n => inv_n_pow n s)
                                 (iota 1 P) (iota (P + 1) (N - P)))).
  - apply (CRplus_le_compat_r (R := R)
             (CRsum_list (fun n => inv_n_pow n s) (iota (P + 1) (N - P)))
             (CRsum_list (fun n => inv_n_pow n s) (iota 1 P))
             (CRsum_list (fun n => inv_n_pow n s)
                         (smooth_list E (primes_leq P)))).
    apply (CRsum_list_subset_le (R := R) (fun n => inv_n_pow n s)
            (iota 1 P) (smooth_list E (primes_leq P))).
    + apply iota_uniq.
    + exact (smooth_list_uniq E (primes_leq P) (primes_leq_all_prime P)
                             (primes_leq_uniq P)).
    + move => n Hn.
      have Hn1 : (1 <= n)%N.
      { rewrite mem_iota in Hn. move/andP : Hn => [Hn1 _]. exact Hn1. }
      have HnP : (n <= P)%N.
      { rewrite mem_iota in Hn. move/andP : Hn => [_ Hlt].
        move: Hlt. rewrite addnC. rewrite addn1. rewrite ltnS. exact id. }
      exact (smooth_prefix_cover E N P n Hn1 HnP HPN HNE).
    + move => n. apply (inv_n_pow_ge0 (R := R) n s).
Qed.

(* ============================================================
   L4 P→∞：尾部界（Σ_{n=P+1}^{N} n^{-s} ≤ 1/P）
   —— iota_succ_plus / telescope_unshift / CRsum_le_pointwise /
      zeta_tail_bound_list / zeta_tail_bound_list_noabs
   —— 链：iota (P+1) (N-P) 的元素 = S(P+k)；逐项 zeta_tail_term_le
      ≤ 1/(P+k) - 1/(S(P+k))；telescope_unshift 求和 = 1/P - 1/(S(P+m)) ≤ 1/P。
   —— 注意：本区段大量 nat 算术，临时打开 nat_scope 让 + / - / <= 解析为
      mathcomp nat 运算（CR 表达式已全限定 CRle/CRplus 等，不受影响）。 *)
Local Open Scope nat_scope.

(* iota (P+1) m = [seq S (P+k) | k <- iota 0 m]
   —— 元素形式：iota 平移 = map S∘(加P)
   —— 逐项：S(P+k) = P + S k（addnS 反向）→ P + (1+k)（S k 定义性 = 1+k）→ P+1+k（addnA 反向） *)
Lemma iota_succ_plus (P m : nat) :
  iota (P + 1)%N m = [seq S (P + k)%N | k <- iota 0 m].
Proof.
  rewrite -[(P + 1)%N]addn0.
  rewrite (iotaDl (P + 1)%N 0 m).
  apply (proj1 (eq_in_map (fun i : nat => (P + 1 + i)%N) (fun k : nat => S (P + k)%N)
                          (iota 0 m))).
  move => k Hk.
  rewrite -addnS. (* S(P+k) → P+S k *)
  change (P + S k)%N with (P + (1 + k))%N. (* S k 定义性 = 1+k，得 P+(1+k) *)
  rewrite -addnA. (* P+(1+k) → P+1+k *)
  reflexivity.
Qed.

(* 非移位望远镜和：Σ_{k=0}^{p} (1/(A+k) - 1/(S(A+k))) == 1/A - 1/(S(A+p))
   —— 直接归纳（镜像 telescope_shift，A+k 而非 S A + k） *)
Lemma telescope_unshift {R : ConstructiveReals} (A p : nat) :
  CReq R (CRsum (fun k : nat => CRminus R (CR_of_Q R (Qinv_n (A + k)))
                                        (CR_of_Q R (Qinv_n (S (A + k))))) p)
         (CRminus R (CR_of_Q R (Qinv_n A))
                   (CR_of_Q R (Qinv_n (S (A + p))))).
Proof.
  induction p as [|p IH].
  - simpl. rewrite (addn0 A). reflexivity.
  - rewrite (addnS A p).
    simpl.
    rewrite IH.
    rewrite (addnS A p).
    apply (CRminus_add_cancel (R := R) (CR_of_Q R (Qinv_n A))
                              (CR_of_Q R (Qinv_n (S (A + p))))
                              (CR_of_Q R (Qinv_n (S (S (A + p)))))).
Qed.

(* 逐项 ≤ ⟹ 求和 ≤：∀k ≤ N, u k ≤ v k ⟹ Σu N ≤ Σv N（归纳） *)
Lemma CRsum_le_pointwise {R : ConstructiveReals} (u v : nat -> CRcarrier R) (N : nat)
  (H : forall k : nat, (k <= N)%N -> CRle R (u k) (v k)) :
  CRle R (CRsum u N) (CRsum v N).
Proof.
  induction N as [|N IH].
  - simpl. apply (H 0%nat). apply leqnn.
  - simpl.
    apply (CRplus_le_compat (R := R) (CRsum u N) (CRsum v N) (u N.+1) (v N.+1)).
    + apply IH. move => k Hk. apply H. exact (leq_trans Hk (leqnSn N)).
    + apply (H N.+1). apply leqnn.
Qed.

(* 尾部界（绝对值版）：Σ_{n=P+1}^{N} |n^{-s}| ≤ 1/P（P ≥ 1, s ≥ 2）
   —— iota (P+1) (N-P) 的元素 = S(P+k)（iota_succ_plus），
     逐项 zeta_tail_term_le：|(S(P+k))^{-s}| ≤ 1/(P+k) - 1/(S(P+k))，
     CRsum_list_iota 桥 + CRsum_le_pointwise 逐项 + telescope_unshift 求和 ≤ 1/P。 *)
Lemma zeta_tail_bound_list {R : ConstructiveReals} (s N P : nat)
  (Hs2 : (2 <= s)%N) (HP1 : (1 <= P)%N) :
  CRle R (CRsum_list (fun n => CRabs R (inv_n_pow n s)) (iota (P + 1) (N - P)))
         (CR_of_Q R (Qinv_n P)).
Proof.
  destruct (N - P) as [| m] eqn:Hm.
  - simpl. apply CRle_of_lt. apply CR_of_Q_inv_pos. exact HP1.
  - rewrite (iota_succ_plus P (S m)).
    rewrite -(addn1 m).
    rewrite (CRsum_list_map (R := R) (fun n => CRabs R (inv_n_pow n s))
                            (fun k => S (P + k)) (iota 0 (m + 1))).
    rewrite (CRsum_list_iota (R := R)
               (fun k => CRabs R (inv_n_pow (S (P + k)) s)) m).
    eapply CRle_trans.
    + apply (CRsum_le_pointwise (R := R)
               (fun k => CRabs R (inv_n_pow (S (P + k)) s))
               (fun k => CRminus R (CR_of_Q R (Qinv_n (P + k)))
                                   (CR_of_Q R (Qinv_n (S (P + k))))) m).
      move => k Hk.
      apply (zeta_tail_term_le (R := R) (P + k) s Hs2).
      exact (leq_trans HP1 (leq_addr k P)).
    + eapply CRle_trans.
      * apply (proj2 (telescope_unshift (R := R) P m)).
      * apply (CRle_minus_compat (R := R) (CR_of_Q R (Qinv_n P))
                                        (CR_of_Q R (Qinv_n (S (P + m))))).
        apply CRle_of_lt. apply CR_of_Q_inv_pos. exact (ltn0Sn (P + m)).
Qed.

(* 尾部界（无绝对值版）：Σ_{n=P+1}^{N} n^{-s} ≤ 1/P
   —— inv_n_pow n s ≥ 0（inv_n_pow_ge0）⟹ inv_n_pow == |inv_n_pow|（CRabs_right 反向），
     再套 zeta_tail_bound_list。 *)
Lemma zeta_tail_bound_list_noabs {R : ConstructiveReals} (s N P : nat)
  (Hs2 : (2 <= s)%N) (HP1 : (1 <= P)%N) :
  CRle R (CRsum_list (fun n => inv_n_pow n s) (iota (P + 1) (N - P)))
         (CR_of_Q R (Qinv_n P)).
Proof.
  apply (CRle_trans (R := R)
           (CRsum_list (fun n => inv_n_pow n s) (iota (P + 1) (N - P)))
           (CRsum_list (fun n => CRabs R (inv_n_pow n s)) (iota (P + 1) (N - P)))
           (CR_of_Q R (Qinv_n P))).
  - apply (proj2 (CRsum_eq_list (R := R)
                    (fun n => inv_n_pow n s)
                    (fun n => CRabs R (inv_n_pow n s))
                    (iota (P + 1) (N - P))
                    (fun n Hn => CReq_sym (CRabs R (inv_n_pow n s))
                                          (inv_n_pow n s)
                                          (CRabs_right (R := R) (inv_n_pow n s)
                                                       (inv_n_pow_ge0 (R := R) n s))))).
  - exact (zeta_tail_bound_list (R := R) s N P Hs2 HP1).
Qed.

(* ============================================================
   L4 P→∞：组合引理（Σ_{n=1}^{N} n^{-s} ≤ ∏(Σ_e) + 1/P）
   —— zeta_partial_le_euler_prod：反向主引理 + 尾部界 + 有限展开
   —— euler_product 主定理的上界侧核心（P→∞ 时尾部 → 0）
   ============================================================ *)

(* 组合引理：Σ_{n=1}^{N} n^{-s} ≤ ∏_{p∈primes_leq P}(Σ_{e≤E} p^{-es}) + 1/P
   —— P ≤ N ≤ 2^E、s ≥ 2、P ≥ 1
   —— 链：zeta_partial_le_euler_prod_tail（Σ ≤ Σ_smooth + 尾部）
     + zeta_tail_bound_list_noabs（尾部 ≤ 1/P）
     + euler_finite_expand 反向（Σ_smooth == ∏） *)
Lemma zeta_partial_le_euler_prod {R : ConstructiveReals} (s E N P : nat)
  (Hs2 : (2 <= s)%N) (HPN : (P <= N)%N) (HNE : (N <= 2 ^ E)%N) (HP1 : (1 <= P)%N) :
  CRle R (CRsum_list (fun n => inv_n_pow n s) (iota 1 N))
         (CRplus R
            (CRprod_list (fun p => CRsum (fun e => inv_n_pow (p ^ e) s) E)
                         (primes_leq P))
            (CR_of_Q R (Qinv_n P))).
Proof.
  apply (CRle_trans (R := R)
           (CRsum_list (fun n => inv_n_pow n s) (iota 1 N))
           (CRplus R
              (CRsum_list (fun n => inv_n_pow n s) (smooth_list E (primes_leq P)))
              (CRsum_list (fun n => inv_n_pow n s) (iota (P + 1) (N - P))))
           (CRplus R
              (CRprod_list (fun p => CRsum (fun e => inv_n_pow (p ^ e) s) E)
                           (primes_leq P))
              (CR_of_Q R (Qinv_n P)))).
  - exact (zeta_partial_le_euler_prod_tail (R := R) s E N P Hs2 HPN HNE).
  - apply (CRplus_le_compat (R := R)
             (CRsum_list (fun n => inv_n_pow n s) (smooth_list E (primes_leq P)))
             (CRprod_list (fun p => CRsum (fun e => inv_n_pow (p ^ e) s) E)
                          (primes_leq P))
             (CRsum_list (fun n => inv_n_pow n s) (iota (P + 1) (N - P)))
             (CR_of_Q R (Qinv_n P))).
    + apply (proj1 (euler_finite_expand (R := R) (primes_leq P) s E
                                         (primes_leq_all_prime P))).
    + exact (zeta_tail_bound_list_noabs (R := R) s N P Hs2 HP1).
Qed.

(* ============================================================
   L4 P→∞：主定理预备（2^n 无界 + 子列收敛）
   —— pow2_ge_one / pow2_ge_succ / pow2_unbounded / CRsum_subseq_pow2_cv
   —— euler_product 上界侧（ζ ≤ ∏_P(1-p^{-s})^{-1}）取极限需要
     ζ 部分和沿 2^E 子列收敛（CRsum_subseq_pow2_cv）。
   —— 本区段大量 nat 算术，临时打开 nat_scope。 *)
Local Open Scope nat_scope.

(* 1 ≤ 2^n（即 0 < 2^n；expn_gt0） *)
Lemma pow2_ge_one (n : nat) : (1 <= 2 ^ n)%N.
Proof.
  rewrite expn_gt0. apply/orP. left. apply ltnW. exact (ltn0Sn 1).
Qed.

(* 2^n ≥ n+1（归纳：n+1 ≤ 2^n；step 目标 S n + 1 ≤ 2^n·2，用 IH（addn1 桥）+ pow2_ge_one 加和） *)
Lemma pow2_ge_succ (n : nat) : (n + 1 <= 2 ^ n)%N.
Proof.
  elim: n => [|n IH]; simpl.
  - apply leqnn.
  - rewrite expnSr. (* 2^n.+1 = 2^n · 2 *)
    rewrite (addn1 n) in IH. (* IH : n+1 ≤ 2^n → S n ≤ 2^n *)
    apply (leq_trans (m := S n + 1) (n := 2 ^ n + 2 ^ n) (p := 2 ^ n * 2)).
    + apply (leq_add IH (pow2_ge_one n)).
    + rewrite addnn. rewrite muln2. apply leqnn.
Qed.

(* 2^E 无界：对任意 N，{E | N ≤ 2^E}（sig，Set 层供 CR_cv 用；取 E = N） *)
Lemma pow2_unbounded (N : nat) : {E : nat | (N <= 2 ^ E)%N}.
Proof.
  exists N.
  have Hsucc : (S N <= 2 ^ N)%N.
  { rewrite -[S N](addn1 N). exact (pow2_ge_succ N). } (* S N → N+1（addn1 反向） *)
  exact (leq_trans (leqnSn N) Hsucc).
Qed.

(* 部分和沿无界子列收敛：CR_cv (CRsum g) l ⟹ CR_cv (fun E => CRsum g (2^E)) l
   —— CR_cv 的 ε-N：给定 p，取 N0（Hcv 的 witness）；pow2_unbounded N0 给 E0 使 N0 ≤ 2^{E0}；
     对 E ≥ E0：2^E ≥ 2^{E0}（leq_exp2l）≥ N0 ⟹ |x_{2^E} - l| ≤ 1/p。 *)
Lemma CRsum_subseq_pow2_cv {R : ConstructiveReals} (g : nat -> CRcarrier R) (l : CRcarrier R)
  (Hcv : CR_cv R (CRsum g) l) :
  CR_cv R (fun E => CRsum g (2 ^ E)) l.
Proof.
  move => p.
  destruct (Hcv p) as [N0 HN0].
  destruct (pow2_unbounded N0) as [E0 HE0].
  exists E0.
  move => E HE.
  apply (HN0 (2 ^ E)).
  apply/leP.
  apply (leq_trans HE0).
  rewrite (@leq_exp2l 2 E0 E (ltnSn 1)). (* (2^{E0} ≤ 2^E) = (E0 ≤ E) *)
  move/leP: HE => HE'. exact HE'.
Qed.

(* ============================================================
   L4 P→∞：Step 1 —— zeta_le_euler_prod_P（euler_product 上界侧核心）
   —— 目标：1 + l ≤ ∏_{p∈primes_leq P}(1-p^{-s})^{-1} + 1/P（固定 P ≥ 1）
   —— 探针：zz_probe_euler_step1.v（EXIT=0，Print Assumptions Closed）
   —— 结构：E0 := pow2_unbounded P（P ≤ 2^{E0}）；沿 E 序列（索引 S E0 + E）：
       u E = Σ_{n=1}^{2^{S E0 + E}} n^{-s}（左端，经 iota1_sum_eq 桥 = 1 + 子列）
       v E = ∏_P(Σ_{e≤S E0+E} p^{-es}) + 1/P（右端）
      逐点 u ≤ v（zeta_partial_le_euler_prod，N = 2^{S E0+E} ≥ 2^{E0} ≥ P）；
      u → 1+l（子列 + shift + CR_cv_plus）；v → ∏ + 1/P（shift + CR_cv_plus）；
      CR_cv_le ⟹ 1+l ≤ ∏ + 1/P。
   ============================================================ *)

(* 收敛的右平移保持：CR_cv f l ⟹ CR_cv (fun n => f (n + k)) l
   —— ε-N：Hcv 的 N0 对 n + k ≥ N0 直接可用（n ≥ N0 ⟹ n + k ≥ N0）。 *)
Lemma CR_cv_shift_right {R : ConstructiveReals} (f : nat -> CRcarrier R) (k : nat) (l : CRcarrier R)
  (Hcv : CR_cv R f l) :
  CR_cv R (fun n => f (n + k)) l.
Proof.
  move => p.
  destruct (Hcv p) as [N0 HN0].
  exists N0.
  move => n Hn.
  apply (HN0 (n + k)).
  apply/leP.
  apply (leq_trans (introT leP Hn)).
  exact (leq_addr k n).
Qed.

(* 部分和沿 2^E - 2 子列收敛：CR_cv (CRsum g) l ⟹ CR_cv (fun E => CRsum g (2^E - 2)) l
   —— iota1_sum_eq 桥（B = 2^E 时尾项到 B-2）需要的子列形式。
   —— ε-N：Hcv 给 N0；pow2_unbounded (N0+2) 给 E' 使 N0+2 ≤ 2^{E'}；
      对 E ≥ E'：2^E ≥ 2^{E'} ≥ N0+2 ⟹ N0 ≤ 2^E - 2。 *)
Lemma CRsum_subseq_pow2_minus2_cv {R : ConstructiveReals} (g : nat -> CRcarrier R) (l : CRcarrier R)
  (Hcv : CR_cv R (CRsum g) l) :
  CR_cv R (fun E => CRsum g (2 ^ E - 2)) l.
Proof.
  move => p.
  destruct (Hcv p) as [N0 HN0].
  destruct (pow2_unbounded (N0 + 2)) as [E' HE'].
  exists E'.
  move => E HE.
  apply (HN0 (2 ^ E - 2)).
  apply/leP.
  (* N0 ≤ 2^E - 2 ⟸ N0 + 2 ≤ (2^E - 2) + 2 = 2^E（消去 +2） *)
  rewrite -(leq_add2r 2 N0 (2 ^ E - 2)).
  (* N0 + 2 ≤ (2^E - 2) + 2 = 2^E：需 2 ≤ 2^E（subnKC） *)
  have H2 : (2 <= 2 ^ E)%N.
  { rewrite (@leq_exp2l 2 1 E (ltnSn 1)).
    (* 1 ≤ E：E' ≤ E 且 1 ≤ E'（2 ≤ N0+2 ≤ 2^{E'} ⟹ 1 ≤ E'） *)
    have HE'1 : (1 <= E')%N.
    { rewrite -(@leq_exp2l 2 1 E' (ltnSn 1)).
      exact (leq_trans (leq_addl N0 2) HE'). }
    exact (leq_trans HE'1 (introT leP HE)).
  }
  rewrite (addnC (2 ^ E - 2) 2).
  rewrite (subnKC H2).
  (* N0 + 2 ≤ 2^E：N0+2 ≤ 2^{E'} ≤ 2^E *)
  apply (leq_trans HE').
  rewrite (@leq_exp2l 2 E' E (ltnSn 1)).
  move/leP: HE. exact id.
Qed.

(* 固定 P ≥ 1：1 + l ≤ ∏_{p∈primes_leq P}(1-p^{-s})^{-1} + 1/P
   —— l = projT1 (zeta_series_cv s Hs2)（ζ(s) = 1 + l）；
     右端 = projT1 (euler_E_cv (primes_leq P) ...)（∏_P(1-p^{-s})^{-1}）+ 1/P。
   —— euler_product 主定理上界侧的核心：P 固定时 ∏_P 已「封顶」为极限值，
     只剩 P→∞ 尾部 1/P → 0（Step 2）。 *)
Lemma zeta_le_euler_prod_P {R : ConstructiveReals} (s P : nat)
  (Hs2 : (2 <= s)%N) (HP1 : (1 <= P)%N) :
  CRle R (CRplus R (CR_of_Q R Q1q) (projT1 (zeta_series_cv (R := R) s Hs2)))
         (CRplus R
            (projT1 (euler_E_cv (primes_leq P) s (primes_leq_all_prime P)
                                (leq_trans (leqnSn 1) Hs2)))
            (CR_of_Q R (Qinv_n P))).
Proof.
  pose l := projT1 (zeta_series_cv (R := R) s Hs2).
  destruct (euler_E_cv (primes_leq P) s (primes_leq_all_prime P)
                       (leq_trans (leqnSn 1) Hs2)) as [lp Hlp].
  destruct (pow2_unbounded P) as [E0 HE0].
  pose u := fun E : nat => CRsum_list (R := R) (fun n => inv_n_pow (R := R) n s)
                                      (iota 1 (2 ^ (S E0 + E))).
  pose v := fun E : nat =>
             CRplus R
               (CRprod_list (R := R)
                            (fun p => CRsum (R := R) (fun e => inv_n_pow (R := R) (p ^ e) s)
                                            (S E0 + E))
                            (primes_leq P))
               (CR_of_Q R (Qinv_n P)).
  (* 逐点 u E ≤ v E（所有 E）：zeta_partial_le_euler_prod s (S E0+E) (2^{S E0+E}) P *)
  have Hpt : forall E, CRle R (u E) (v E).
  { move => E. unfold u, v.
    apply (zeta_partial_le_euler_prod (R := R) s (S E0 + E) (2 ^ (S E0 + E)) P Hs2).
    - (* P ≤ 2^{S E0 + E}：P ≤ 2^{E0} ≤ 2^{S E0+E} *)
      apply (leq_trans HE0).
      rewrite (@leq_exp2l 2 E0 (S E0 + E) (ltnSn 1)).
      (* 目标: E0 <= S E0 + E，addSn 展开 S 后 addnS 归一为 E0 + S E *)
      rewrite addSn. rewrite -addnS.
      exact (leq_addr (S E) E0).
    - (* 2^{S E0+E} ≤ 2^{S E0+E} *)
      apply leqnn.
    - exact HP1. }
  (* u → 1 + l（沿 E） *)
  have Hucv : CR_cv R u (CRplus R (CR_of_Q R Q1q) l).
  { apply (CR_cv_extens (R := R)
            (fun E : nat => CRplus R (CR_of_Q R Q1q)
                              (CRsum (fun k => inv_n_pow (S (S k)) s) (2 ^ (S E0 + E) - 2)))
            u (CRplus R (CR_of_Q R Q1q) l)).
    - (* 逐点 ==：iota1_sum_eq（B = 2^{S E0+E} ≥ 2） *)
      move => E. unfold u. symmetry.
      apply (iota1_sum_eq (R := R) s (2 ^ (S E0 + E))).
      (* 目标: 2 <= 2^{S E0 + E}（bool）；1 ≤ S E0 + E ⟹ 2^1 ≤ 2^{S E0+E} *)
      rewrite (@leq_exp2l 2 1 (S E0 + E) (ltnSn 1)).
      (* 1 ≤ S E0 + E = S (E0 + E) *)
      rewrite addSn. exact (ltn0Sn (E0 + E)).
    - (* 1 + 子列(2^{S E0+E} - 2) → 1 + l *)
      apply (CR_cv_plus (R := R) (fun _ : nat => CR_of_Q R Q1q)
              (fun E : nat => CRsum (fun k => inv_n_pow (S (S k)) s) (2 ^ (S E0 + E) - 2))
              (CR_of_Q R Q1q) l).
      + apply CR_cv_const.
      + (* 子列(2^{E} - 2) → l，然后右移 S E0（n + S E0 = S E0 + n 桥） *)
        apply (CR_cv_extens (R := R)
                (fun n : nat => CRsum (fun k => inv_n_pow (S (S k)) s) (2 ^ (n + S E0) - 2))
                (fun n : nat => CRsum (fun k => inv_n_pow (S (S k)) s) (2 ^ (S E0 + n) - 2)) l).
        * move => n. rewrite addnC. reflexivity.
        * apply (CR_cv_shift_right (R := R)
                   (fun E : nat => CRsum (fun k => inv_n_pow (S (S k)) s) (2 ^ E - 2)) (S E0) l).
          apply (CRsum_subseq_pow2_minus2_cv (R := R)
                   (fun k => inv_n_pow (S (S k)) s) l).
          exact (projT2 (zeta_series_cv (R := R) s Hs2)). }
  (* v → lp + 1/P（沿 E） *)
  have Hvcv : CR_cv R v (CRplus R lp (CR_of_Q R (Qinv_n P))).
  { unfold v.
    apply (CR_cv_plus (R := R)
            (fun E : nat => CRprod_list (R := R)
                                        (fun p => CRsum (R := R) (fun e => inv_n_pow (R := R) (p ^ e) s)
                                                        (S E0 + E))
                                        (primes_leq P))
            (fun _ : nat => CR_of_Q R (Qinv_n P)) lp (CR_of_Q R (Qinv_n P))).
    - (* ∏_P(Σ_e) 右移 S E0（n + S E0 = S E0 + n 桥） *)
      apply (CR_cv_extens (R := R)
              (fun n : nat => CRprod_list (R := R)
                                          (fun p => CRsum (R := R) (fun e => inv_n_pow (R := R) (p ^ e) s)
                                                          (n + S E0))
                                          (primes_leq P))
              (fun n : nat => CRprod_list (R := R)
                                          (fun p => CRsum (R := R) (fun e => inv_n_pow (R := R) (p ^ e) s)
                                                          (S E0 + n))
                                          (primes_leq P)) lp).
      + move => n. rewrite addnC. reflexivity.
      + apply (CR_cv_shift_right (R := R)
                 (fun E : nat => CRprod_list (R := R)
                                             (fun p => CRsum (R := R) (fun e => inv_n_pow (R := R) (p ^ e) s)
                                                             E)
                                             (primes_leq P))
                 (S E0) lp).
        exact Hlp.
    - apply CR_cv_const. }
  (* CR_cv_le ⟹ 1 + l ≤ lp + 1/P *)
  apply (CR_cv_le (R := R) u v (CRplus R (CR_of_Q R Q1q) l)
                   (CRplus R lp (CR_of_Q R (Qinv_n P))) Hpt Hucv Hvcv).
Qed.

(* ============================================================
   L4 P→∞：Step 2 —— euler_product 主定理（P→∞ 夹逼）
   —— 目标：CR_cv (fun P => ∏_{p∈primes_leq P}(1-p^{-s})^{-1}) (1 + l)
   —— 探针：zz_probe_euler_step2.v（EXIT=0，Print Assumptions Closed）
   —— 链：euler_prod_leq_zeta（F(P) ≤ 1+l，euler_prod_le_zeta + CR_cv_bound_up）
        + euler_prod_err_le（|F(P)-(1+l)| ≤ 1/P，夹逼误差界）
        + ε-N（P0 = Pos.to_nat p，1/P ≤ 1/p 当 P ≥ p）
   ============================================================ *)

(* F(P) ≤ 1 + l（逐 P 下界封顶）
   —— euler_prod_le_zeta（∏_P(Σ_e) ≤ 1+l 对任意 E）+ CR_cv_bound_up（E→∞ 极限）。 *)
Lemma euler_prod_leq_zeta {R : ConstructiveReals} (s P : nat)
  (Hs2 : (2 <= s)%N) (HP1 : (1 <= P)%N) :
  CRle R (projT1 (euler_E_cv (primes_leq P) s (primes_leq_all_prime P)
                              (leq_trans (leqnSn 1) Hs2)))
         (CRplus R (CR_of_Q R Q1q) (projT1 (zeta_series_cv (R := R) s Hs2))).
Proof.
  destruct (euler_E_cv (primes_leq P) s (primes_leq_all_prime P)
                       (leq_trans (leqnSn 1) Hs2)) as [lp Hlp].
  apply (CR_cv_bound_up (R := R)
           (fun E => CRprod_list (R := R)
                                 (fun p => CRsum (R := R) (fun e => inv_n_pow (R := R) (p ^ e) s) E)
                                 (primes_leq P))
           (CRplus R (CR_of_Q R Q1q) (projT1 (zeta_series_cv (R := R) s Hs2))) lp 0).
  - move => n Hn.
    apply (euler_prod_le_zeta (R := R) (primes_leq P) s n Hs2
                              (primes_leq_all_prime P) (primes_leq_uniq P)).
  - exact Hlp.
Qed.

(* |F(P) - (1+l)| ≤ 1/P（夹逼误差界）
   —— F(P) ≤ 1+l（euler_prod_leq_zeta）且 1+l ≤ F(P) + 1/P（zeta_le_euler_prod_P）：
     CRabs_minus_sym + CRabs_right（0 ≤ (1+l)-F(P)，CRle_minus）
     + CRplus_le_compat_r 加 (-F(P)) 消去（(1+l)-F(P) ≤ 1/P）。 *)
Lemma euler_prod_err_le {R : ConstructiveReals} (s P : nat)
  (Hs2 : (2 <= s)%N) (HP1 : (1 <= P)%N) :
  CRle R (CRabs R (CRminus R
                     (projT1 (euler_E_cv (primes_leq P) s (primes_leq_all_prime P)
                                         (leq_trans (leqnSn 1) Hs2)))
                     (CRplus R (CR_of_Q R Q1q) (projT1 (zeta_series_cv (R := R) s Hs2)))))
         (CR_of_Q R (Qinv_n P)).
Proof.
  pose F := projT1 (euler_E_cv (R := R) (primes_leq P) s (primes_leq_all_prime P)
                               (leq_trans (leqnSn 1) Hs2)).
  pose l := projT1 (zeta_series_cv (R := R) s Hs2).
  have H1 : CRle R F (CRplus R (CR_of_Q R Q1q) l) :=
    euler_prod_leq_zeta (R := R) s P Hs2 HP1.
  have H2 : CRle R (CRplus R (CR_of_Q R Q1q) l)
                   (CRplus R F (CR_of_Q R (Qinv_n P))) :=
    zeta_le_euler_prod_P (R := R) s P Hs2 HP1.
  (* 0 ≤ (1+l) - F：CRle_minus *)
  have H0le : CRle R (CR_of_Q R Q0q) (CRminus R (CRplus R (CR_of_Q R Q1q) l) F).
  { apply (CRle_minus F (CRplus R (CR_of_Q R Q1q) l)). exact H1. }
  (* |F - (1+l)| == (1+l) - F *)
  have Ha : CReq R (CRabs R (CRminus R F (CRplus R (CR_of_Q R Q1q) l)))
                   (CRminus R (CRplus R (CR_of_Q R Q1q) l) F).
  { eapply CReq_trans.
    - apply (CRabs_minus_sym F (CRplus R (CR_of_Q R Q1q) l)).
    - apply (CRabs_right (CRminus R (CRplus R (CR_of_Q R Q1q) l) F)).
      exact H0le. }
  apply (proj2 (CRle_morph R
                 (CRabs R (CRminus R F (CRplus R (CR_of_Q R Q1q) l)))
                 (CRminus R (CRplus R (CR_of_Q R Q1q) l) F) Ha
                 (CR_of_Q R (Qinv_n P)) (CR_of_Q R (Qinv_n P))
                 (CReq_refl (R := R) (CR_of_Q R (Qinv_n P))))).
  (* (1+l) - F ≤ 1/P：H2 加 (-F)，RHS 代数化简 *)
  have Hstep : CRle R (CRminus R (CRplus R (CR_of_Q R Q1q) l) F)
                      (CR_of_Q R (Qinv_n P)).
  { apply (CRle_trans (R := R)
             (CRminus R (CRplus R (CR_of_Q R Q1q) l) F)
             (CRplus R (CRplus R F (CR_of_Q R (Qinv_n P))) (CRopp R F))
             (CR_of_Q R (Qinv_n P))).
    - (* (1+l) - F ≤ (F + 1/P) + (-F)：CRplus_le_compat_r (-F) H2 *)
      unfold CRminus.
      apply (CRplus_le_compat_r (R := R) (CRopp R F)
                                (CRplus R (CR_of_Q R Q1q) l)
                                (CRplus R F (CR_of_Q R (Qinv_n P)))).
      exact H2.
    - (* (F + 1/P) + (-F) == 1/P：交换 + 结合 + 消去 *)
      have Hnorm : CReq R (CRplus R (CRplus R F (CR_of_Q R (Qinv_n P))) (CRopp R F))
                          (CR_of_Q R (Qinv_n P)).
      { rewrite (CRplus_comm (R := R) F (CR_of_Q R (Qinv_n P))).
        rewrite (CRplus_assoc (R := R) (CR_of_Q R (Qinv_n P)) F (CRopp R F)).
        rewrite (CRplus_opp_r (R := R) F).
        rewrite (CRplus_0_r (R := R) (CR_of_Q R (Qinv_n P))).
        reflexivity. }
      apply (proj2 (CRle_morph R
                     (CRplus R (CRplus R F (CR_of_Q R (Qinv_n P))) (CRopp R F))
                     (CR_of_Q R (Qinv_n P)) Hnorm
                     (CR_of_Q R (Qinv_n P)) (CR_of_Q R (Qinv_n P))
                     (CReq_refl (R := R) (CR_of_Q R (Qinv_n P))))).
      apply CRle_refl. }
  exact Hstep.
Qed.

(* 辅助：CR_of_Q (Qinv_n (Pos.to_nat p)) == CR_of_Q (Qmake 1 p)
   —— Qinv_n (Pos.to_nat p) = Qmake 1 (Z.to_pos (Z.of_nat (Pos.to_nat p)))
     = Qmake 1 p（Zto_pos_of_nat + Pos2Nat.id）。 *)
Lemma Qinv_n_pos_to_nat_bridge {R : ConstructiveReals} (p : positive) :
  CReq R (CR_of_Q R (Qinv_n (Pos.to_nat p))) (CR_of_Q R (Qmake 1 p)).
Proof.
  apply (CR_of_Q_Qeq (R := R) (Qinv_n (Pos.to_nat p)) (Qmake 1 p)).
  unfold Qinv_n, Qeq. simpl.
  (* 目标: 1 * Zpos p = 1 * Zpos (Z.to_pos (Z.of_nat (Pos.to_nat p)))
     ⟺ Zpos p = Zpos (Z.to_pos (Z.of_nat (Pos.to_nat p)))
     ⟺ p = Z.to_pos (Z.of_nat (Pos.to_nat p)) *)
  rewrite (Zto_pos_of_nat (Pos.to_nat p) (introT leP (Pos2Nat.is_pos p))).
  (* Z.to_pos (Z.of_nat (Pos.to_nat p)) = Pos.of_nat (Pos.to_nat p) = p *)
  rewrite (Pos2Nat.id p). reflexivity.
Qed.

(* ★★★ 主定理：ζ(s) = ∏_p (1-p^{-s})^{-1}（s ≥ 2，构造性实数，零公理）
   —— ε-N：取 P0 = Pos.to_nat p（1/P ≤ 1/p 当 P ≥ p）；
      |F(P) - (1+l)| ≤ 1/P ≤ 1/p（euler_prod_err_le + Qinv_n_le + Qeq 桥）。 *)
Theorem euler_product {R : ConstructiveReals} (s : nat) (Hs2 : (2 <= s)%N) :
  CR_cv R (fun P => projT1 (euler_E_cv (primes_leq P) s (primes_leq_all_prime P)
                                       (leq_trans (leqnSn 1) Hs2)))
          (CRplus R (CR_of_Q R Q1q) (projT1 (zeta_series_cv (R := R) s Hs2))).
Proof.
  move => p.
  exists (Pos.to_nat p).
  move => P HP.
  (* HP : (Pos.to_nat p <= P)%coq_nat；P ≥ 1 *)
  have HP1 : (1 <= P)%N.
  { apply (leq_trans (introT leP (Pos2Nat.is_pos p)) (introT leP HP)). }
  (* |F(P) - (1+l)| ≤ 1/P ≤ 1/p *)
  apply (CRle_trans (R := R)
           (CRabs R (CRminus R
                      (projT1 (euler_E_cv (primes_leq P) s (primes_leq_all_prime P)
                                          (leq_trans (leqnSn 1) Hs2)))
                      (CRplus R (CR_of_Q R Q1q) (projT1 (zeta_series_cv (R := R) s Hs2)))))
           (CR_of_Q R (Qinv_n P))
           (CR_of_Q R (Qmake 1 p))).
  - exact (euler_prod_err_le (R := R) s P Hs2 HP1).
  - (* 1/P ≤ 1/p：Qinv_n_le（P ≥ p）+ CR_of_Q_le + Qeq 桥 *)
    apply (proj2 (CRle_morph R
                   (CR_of_Q R (Qinv_n P)) (CR_of_Q R (Qinv_n P))
                   (CReq_refl (R := R) (CR_of_Q R (Qinv_n P)))
                   (CR_of_Q R (Qmake 1 p)) (CR_of_Q R (Qinv_n (Pos.to_nat p)))
                   (CReq_sym (CR_of_Q R (Qinv_n (Pos.to_nat p))) (CR_of_Q R (Qmake 1 p))
                             (Qinv_n_pos_to_nat_bridge (R := R) p)))).
    apply (CR_of_Q_le (R := R) (Qinv_n P) (Qinv_n (Pos.to_nat p))).
    apply (Qinv_n_le P (Pos.to_nat p)).
    + exact HP1.
    + exact (introT leP (Pos2Nat.is_pos p)).
    + move/leP: HP. exact id.
Qed.

(* ============================================================
   欧拉线延伸：ζ 单调性（s1 ≤ s2 ⟹ ζ(s2) ≤ ζ(s1)，s ≥ 2）
   —— 探针 zz_probe_zeta_mono.v（EXIT=0，Print Assumptions Closed）
   —— 链：inv_n_pow_mono_le（逐项，CRpow_decreasing_ge）
     + zeta_sum_mono_le（部分和逐项，CRsum_le_pointwise）
     + zeta_mono_le（极限比较，CR_cv_le）
   —— 意义：ζ(s) 随 s 递减；euler_product 在收敛域上的单调性（级数侧）。
   ============================================================ *)

(* 逐项：n ≥ 1, s1 ≤ s2 ⟹ n^{-s2} ≤ n^{-s1}
   —— inv_n_pow n s = CRpow (1/n) s；CRpow_decreasing_ge x s2 s1（s1 ≤ s2 ⟹ x^{s2} ≤ x^{s1}）。 *)
Lemma inv_n_pow_mono_le {R : ConstructiveReals} (n s1 s2 : nat)
  (Hn1 : (1 <= n)%N) (Hs : (s1 <= s2)%N) :
  CRle R (inv_n_pow n s2) (inv_n_pow n s1).
Proof.
  unfold inv_n_pow.
  apply (CRpow_decreasing_ge (R := R) (CR_of_Q R (Qinv_n n)) s2 s1).
  - (* 0 ≤ 1/n *)
    apply CRle_of_lt. apply (CR_of_Q_inv_pos (R := R) n). exact Hn1.
  - (* 1/n ≤ 1 *)
    apply (CR_of_Q_le (R := R) (Qinv_n n) Q1q).
    apply (Qinv_n_le_one n Hn1).
  - exact Hs.
Qed.

(* 部分和逐项：∀N, Σ_{n≤N} (S(S n))^{-s2} ≤ Σ_{n≤N} (S(S n))^{-s1} *)
Lemma zeta_sum_mono_le {R : ConstructiveReals} (s1 s2 : nat) (Hs : (s1 <= s2)%N) :
  forall N : nat,
  CRle R (CRsum (fun n => inv_n_pow (S (S n)) s2) N)
         (CRsum (fun n => inv_n_pow (S (S n)) s1) N).
Proof.
  move => N.
  apply (CRsum_le_pointwise (R := R) (fun n => inv_n_pow (S (S n)) s2)
                            (fun n => inv_n_pow (S (S n)) s1) N).
  move => k Hk.
  apply (inv_n_pow_mono_le (R := R) (S (S k)) s1 s2).
  - (* 1 ≤ S(S k)：0 < S(S k) ≡ 1 ≤ S(S k)（ltn 定义） *)
    exact (ltn0Sn (S k)).
  - exact Hs.
Qed.

(* ★ 主引理：ζ 单调（s1 ≤ s2 ⟹ ζ(s2) ≤ ζ(s1)，s ≥ 2）
   —— CR_cv_le：部分和沿 s2 ≤ 沿 s1（zeta_sum_mono_le）+ 极限比较。 *)
Lemma zeta_mono_le {R : ConstructiveReals} (s1 s2 : nat)
  (Hs1 : (2 <= s1)%N) (Hs2 : (2 <= s2)%N) (Hs : (s1 <= s2)%N) :
  CRle R (projT1 (zeta_series_cv (R := R) s2 Hs2))
         (projT1 (zeta_series_cv (R := R) s1 Hs1)).
Proof.
  apply (CR_cv_le (R := R)
           (fun n => CRsum (fun k => inv_n_pow (S (S k)) s2) n)
           (fun n => CRsum (fun k => inv_n_pow (S (S k)) s1) n)
           (projT1 (zeta_series_cv (R := R) s2 Hs2))
           (projT1 (zeta_series_cv (R := R) s1 Hs1))).
  - exact (zeta_sum_mono_le (R := R) s1 s2 Hs).
  - exact (projT2 (zeta_series_cv (R := R) s2 Hs2)).
  - exact (projT2 (zeta_series_cv (R := R) s1 Hs1)).
Qed.

(* ============================================================
   欧拉线延伸：ζ 数值界（ζ(2) ≤ 2，s ≥ 2 时 ζ(s) ≤ ζ(2) ≤ 2）
   —— 探针 zz_probe_zeta_bound.v（EXIT=0，Print Assumptions Closed）
   —— 链：zeta2_term_le（逐项 1/(n+2)² ≤ 1/(n+1) − 1/(n+2)）
     + zeta2_sum_le（部分和逐项）+ zeta2_sum_telescope（telescope_shift A=0 闭式）
     + zeta_2_le_2（部分和 ≤ 1 + CR_cv_bound_up 取极限 ⟹ l ≤ 1）
   ============================================================ *)

(* 逐项：inv_n_pow (S(S k)) 2 ≤ 1/(S k) - 1/(S(S k))（k ≥ 0）
   —— inv_n_pow_le_sq（≤ 1/(S(S k))²）→ Qinv_sq_le_telescope（≤ 1/((S(S k))(S k))）
     → Qinv_n_telescope（== 1/(S k) - 1/(S(S k))）。 *)
Lemma zeta2_term_le {R : ConstructiveReals} (k : nat) :
  CRle R (inv_n_pow (S (S k)) 2)
         (CRminus R (CR_of_Q R (Qinv_n (S k))) (CR_of_Q R (Qinv_n (S (S k))))).
Proof.
  eapply CRle_trans.
  - (* (S(S k))^{-2} ≤ 1/(S(S k))² *)
    apply (inv_n_pow_le_sq (R := R) (S (S k)) 2).
    + (* 2 ≤ S(S k) = 2 + k（定义性） *)
      apply (leq_addr k 2).
    + apply leqnn.       (* 2 ≤ 2 *)
  - (* 1/(S(S k))² ≤ 1/((S(S k))(S k)) == 1/(S k) - 1/(S(S k)) *)
    eapply CRle_trans.
    + (* 1/(S(S k))² ≤ 1/((S(S k))(S k))：Qinv_sq_le_telescope *)
      apply (CR_of_Q_le (R := R)
               (Qinv_n ((S (S k)) * (S (S k))))
               (Qinv_n ((S (S k)) * (S k)))).
      apply (Qinv_sq_le_telescope (S (S k))).
      apply (leq_addr k 2).
    + (* 1/((S(S k))(S k)) == 1/(S k) - 1/(S(S k))：Qinv_n_telescope + CR_of_Q_minus *)
      have Hbridge : CReq R (CR_of_Q R (Qinv_n ((S (S k)) * (S k))))
                            (CRminus R (CR_of_Q R (Qinv_n (S k))) (CR_of_Q R (Qinv_n (S (S k))))).
      { eapply CReq_trans.
        - (* CR_of_Q (Qinv_n (...)) == CR_of_Q (Qminus (Qinv_n (S k)) (Qinv_n (S(S k)))) *)
          apply (CR_of_Q_Qeq (R := R) (Qinv_n ((S (S k)) * (S k)))
                   (Qminus (Qinv_n (S k)) (Qinv_n (S (S k))))
                   (Qinv_n_telescope (S (S k)) (leq_addr k 2))).
        - (* CR_of_Q (Qminus a b) == CR_of_Q a - CR_of_Q b（CR_of_Q_minus 桥） *)
          apply (CR_of_Q_minus (R := R) (Qinv_n (S k)) (Qinv_n (S (S k)))). }
      apply (proj1 (CRle_morph R
        (CRminus R (CR_of_Q R (Qinv_n (S k))) (CR_of_Q R (Qinv_n (S (S k)))))
        (CR_of_Q R (Qinv_n ((S (S k)) * (S k))))
        (CReq_sym (CR_of_Q R (Qinv_n ((S (S k)) * (S k))))
                  (CRminus R (CR_of_Q R (Qinv_n (S k))) (CR_of_Q R (Qinv_n (S (S k)))))
                  Hbridge)
        (CRminus R (CR_of_Q R (Qinv_n (S k))) (CR_of_Q R (Qinv_n (S (S k)))))
        (CRminus R (CR_of_Q R (Qinv_n (S k))) (CR_of_Q R (Qinv_n (S (S k)))))
        (CReq_refl (R := R) (CRminus R (CR_of_Q R (Qinv_n (S k))) (CR_of_Q R (Qinv_n (S (S k)))))))).
      apply CRle_refl.
Qed.

(* 部分和逐项：Σ_{k≤N} (S(S k))^{-2} ≤ Σ_{k≤N} (1/(S k) - 1/(S(S k))) *)
Lemma zeta2_sum_le {R : ConstructiveReals} (N : nat) :
  CRle R (CRsum (fun k => inv_n_pow (S (S k)) 2) N)
         (CRsum (fun k => CRminus R (CR_of_Q R (Qinv_n (S k)))
                                    (CR_of_Q R (Qinv_n (S (S k))))) N).
Proof.
  apply (CRsum_le_pointwise (R := R)
           (fun k => inv_n_pow (S (S k)) 2)
           (fun k => CRminus R (CR_of_Q R (Qinv_n (S k)))
                                (CR_of_Q R (Qinv_n (S (S k))))) N).
  move => k Hk. exact (zeta2_term_le (R := R) k).
Qed.

(* 部分和闭式：Σ_{k≤N} (1/(S k) - 1/(S(S k))) == 1 - 1/(S(S N))
   —— telescope_shift A=0（S 0+k = S k、S 0 = 1、S(S 0+N) = S(S N) 均定义性）。 *)
Lemma zeta2_sum_telescope {R : ConstructiveReals} (N : nat) :
  CReq R (CRsum (fun k => CRminus R (CR_of_Q R (Qinv_n (S k)))
                                    (CR_of_Q R (Qinv_n (S (S k))))) N)
         (CRminus R (CR_of_Q R Q1q) (CR_of_Q R (Qinv_n (S (S N))))).
Proof.
  exact (telescope_shift (R := R) 0 N).
Qed.

(* ★ 主引理：ζ(2) 级数极限 l ≤ 1（⟹ ζ(2) = 1+l ≤ 2）
   —— 部分和 ≤ 1（telescope 闭式 + CRle_minus_compat）+ CR_cv_bound_up 取极限。 *)
Lemma zeta_2_le_2 {R : ConstructiveReals} :
  CRle R (projT1 (zeta_series_cv (R := R) 2 (leqnn 2))) (CR_of_Q R Q1q).
Proof.
  (* 部分和 ≤ 1 *)
  have Hsum : forall N, CRle R (CRsum (fun k => inv_n_pow (S (S k)) 2) N)
                                (CR_of_Q R Q1q).
  { move => N.
    eapply CRle_trans.
    - exact (zeta2_sum_le (R := R) N).
    - (* Σ(1/(S k) - 1/(S(S k))) == 1 - 1/(S(S N)) ≤ 1 *)
      apply (proj2 (CRle_morph R
        (CRsum (fun k => CRminus R (CR_of_Q R (Qinv_n (S k)))
                                   (CR_of_Q R (Qinv_n (S (S k))))) N)
        (CRminus R (CR_of_Q R Q1q) (CR_of_Q R (Qinv_n (S (S N)))))
        (zeta2_sum_telescope (R := R) N)
        (CR_of_Q R Q1q) (CR_of_Q R Q1q)
        (CReq_refl (R := R) (CR_of_Q R Q1q)))).
      (* 1 - 1/(S(S N)) ≤ 1：CRle_minus_compat（0 ≤ 1/(S(S N))） *)
      apply (CRle_minus_compat (R := R) (CR_of_Q R Q1q) (CR_of_Q R (Qinv_n (S (S N))))).
      apply CR_of_Q_le. unfold Qinv_n, Q0q, Qle. simpl. lia. }
  (* 极限 ≤ 1：CR_cv_bound_up（部分和 ≤ 1 对任意 N） *)
  apply (CR_cv_bound_up (R := R)
           (fun N => CRsum (fun k => inv_n_pow (S (S k)) 2) N)
           (CR_of_Q R Q1q) (projT1 (zeta_series_cv (R := R) 2 (leqnn 2))) 0).
  - move => n Hn. exact (Hsum n).
  - exact (projT2 (zeta_series_cv (R := R) 2 (leqnn 2))).
Qed.

(* ============================================================
   延伸 ③：ζ(1) 发散（调和级数部分和无界）
   —— 纯构造性：CR_archimedean（对任意 B 有正整数 n 使 B < n）
      + harm_pow2_ge（Σ_{k=1}^{2^m} 1/k ≥ (2+m)/2，经典分组归纳）
      + CRsum_harm_partial（CRsum ↔ CRsum_list 的 iota 桥）。
   纪律：全部 Qed、零 Axiom（Print Assumptions zeta_1_diverges = Closed）。
   技术点（E090 延伸）：mathcomp 2^j（j 变量）在 nat 层卡 Fixpoint，
     用 positive 递归 pow2p（pow2p O = 1, pow2p (S j) = 2·pow2p j）+ 桥
     pow2p_to_nat / positive_nat_Z / Qinv_n_pos，2 的幂进 Q 层分母不卡。
   ============================================================ *)

(* 2 的幂（positive 递归，避免 mathcomp expn 在 nat 层卡 Fixpoint） *)
Fixpoint pow2p (j : nat) : positive :=
  match j with O => 1%positive | S j' => (2 * pow2p j')%positive end.

(* 桥：Pos.to_nat (pow2p j) = 2^j（归纳 j；expn 与 positive 2 幂一致） *)
Lemma pow2p_to_nat (j : nat) : Pos.to_nat (pow2p j) = 2 ^ j.
Proof.
  elim: j => [|j IH]; simpl.
  - reflexivity.
  - rewrite (Pos2Nat.inj_mul 2 (pow2p j)). simpl.
    rewrite IH. rewrite expnS. reflexivity.
Qed.

(* 桥：Qinv_n (Pos.to_nat p) = Qmake 1 p（Q 层，positive_nat_Z 反向） *)
Lemma Qinv_n_pos (p : positive) : Qinv_n (Pos.to_nat p) = Qmake 1 p.
Proof.
  unfold Qinv_n. f_equal.
  rewrite (positive_nat_Z p).
  reflexivity.
Qed.

(* 工具：iota a.+1 n = map S (iota a n)（归纳 n，a 一般化） *)
Lemma iota_succ_shift (a n : nat) : iota a.+1 n = map S (iota a n).
Proof.
  move: a. elim: n => [| n IH] a; simpl.
  - reflexivity.
  - f_equal. exact (IH a.+1).
Qed.

(* 工具：iota 1 n = map S (iota 0 n)（部分和 1..n 与 0..n-1 的对应） *)
Lemma iota_shift (n : nat) : iota 1 n = map S (iota 0 n).
Proof.
  rewrite (iota_succ_shift 0 n). reflexivity.
Qed.

(* 工具：pow2p m ≥ 1（Pos.to_nat 正性，对 m 归纳：1 > 0，2·p > 0） *)
Lemma pow2p_pos (m : nat) : 0 < Pos.to_nat (pow2p m).
Proof.
  elim: m => [| m IH]; simpl.
  - apply ltnSn.
  - rewrite (Pos2Nat.inj_mul 2 (pow2p m)). simpl.
    apply (leq_trans IH).
    apply leq_addr.
Qed.

(* 桥：inv_n_pow (S n) 1 == CR_of_Q (Qinv_n (S n))（CRpow x 1 = x·1 == x） *)
Lemma inv_n_pow_1 {R : ConstructiveReals} (n : nat) :
  CReq R (inv_n_pow (S n) 1) (CR_of_Q R (Qinv_n (S n))).
Proof.
  unfold inv_n_pow. simpl. exact (CRmult_1_r (R := R) (CR_of_Q R (Qinv_n (S n)))).
Qed.

(* 列表逐项 ≤ ⟹ 求和 ≤（对 l 归纳；补充到本文件供发散链用） *)
Lemma CRsum_list_le_pointwise_list {R : ConstructiveReals} (f g : nat -> CRcarrier R) (l : seq nat)
  (H : forall x : nat, x \in l -> CRle R (f x) (g x)) :
  CRle R (CRsum_list f l) (CRsum_list g l).
Proof.
  induction l as [| x l IH]; simpl.
  - apply CRle_refl.
  - apply (CRplus_le_compat (R := R) (f x) (g x) (CRsum_list f l) (CRsum_list g l)).
    + apply (H x). apply mem_head.
    + apply IH. move => y Hy. apply (H y). rewrite in_cons. apply/orP. right. exact Hy.
Qed.

(* 工具：常数在任意列表 l 上的和 == (size l)·c（对 l 归纳） *)
Lemma sumn_const {R : ConstructiveReals} (c : Q) (l : seq nat) :
  CReq R (CRsum_list (fun _ : nat => CR_of_Q R c) l)
         (CR_of_Q R (Qmult (Qmake (Z.of_nat (size l)) 1) c)).
Proof.
  elim: l => [| x l IH]; simpl.
  - apply (CR_of_Q_Qeq (R := R) Q0q (Qmult (Qmake 0 1) c)).
    unfold Qmult, Qeq. simpl. lia.
  - eapply CReq_trans.
    + apply (CRplus_morph R (CR_of_Q R c) (CR_of_Q R c) (CReq_refl (R := R) (CR_of_Q R c))
               (CRsum_list (fun _ : nat => CR_of_Q R c) l)
               (CR_of_Q R (Qmult (Qmake (Z.of_nat (size l)) 1) c)) IH).
    + rewrite <- (CR_of_Q_plus R c (Qmult (Qmake (Z.of_nat (size l)) 1) c)).
      apply (CR_of_Q_Qeq (R := R)
               (Qplus c (Qmult (Qmake (Z.of_nat (size l)) 1) c))
               (Qmult (Qmake (Z.of_nat (S (size l))) 1) c)).
      rewrite (Nat2Z.inj_succ (size l)).
      destruct c as [nz d]. simpl.
      unfold Qeq, Qmult, Qplus. simpl. lia.
Qed.

(* 工具：iota a n 的长度 = n（iota_size） *)
Lemma iota_size_le (a n : nat) : size (iota a n) = n.
Proof. exact (size_iota a n). Qed.

(* 工具：常数在 iota a n 上的和 == n·c（sumn_const + iota_size） *)
Lemma CRsum_list_const_iota {R : ConstructiveReals} (c : Q) (a n : nat) :
  CReq R (CRsum_list (fun _ : nat => CR_of_Q R c) (iota a n))
         (CR_of_Q R (Qmult (Qmake (Z.of_nat n) 1) c)).
Proof.
  rewrite (sumn_const (R := R) c (iota a n)).
  rewrite (iota_size_le a n). apply CReq_refl.
Qed.

(* 逐项：1 ≤ k ≤ 2^{j+1}（= Pos.to_nat (pow2p (S j))）⟹ 1/2^{j+1} ≤ 1/k
   —— Qinv_n_pos 桥 + Qinv_n_le（k ≤ 2^{j+1} ⟹ 1/2^{j+1} ≤ 1/k）。 *)
Lemma inv_ge_pow {R : ConstructiveReals} (j k : nat)
  (Hk1 : 1 <= k) (Hk : k <= Pos.to_nat (pow2p (S j))) :
  CRle R (CR_of_Q R (Qmake 1 (pow2p (S j)))) (CR_of_Q R (Qinv_n k)).
Proof.
  rewrite <- (Qinv_n_pos (pow2p (S j))).
  apply (CR_of_Q_le (R := R) (Qinv_n (Pos.to_nat (pow2p (S j)))) (Qinv_n k)).
  apply (Qinv_n_le (Pos.to_nat (pow2p (S j))) k).
  - (* 1 ≤ Pos.to_nat (pow2p (S j))：pow2p ≥ 1 ⟹ Pos.to_nat ≥ 1 *)
    rewrite (pow2p_to_nat (S j)). rewrite expn_gt0. apply/orP. left.
    apply ltnW. exact (ltn0Sn 1).
  - exact Hk1.
  - exact Hk.
Qed.

(* 组下界：Σ_{k=2^j+1}^{2^{j+1}} 1/k ≥ 1/2
   —— iota (Pos.to_nat (pow2p j) + 1) (Pos.to_nat (pow2p j)) 有 2^j 项，
     每项 ≥ 1/2^{j+1}（Qmake 1 (pow2p (S j))），常数和 == 1/2。 *)
Lemma harm_group_ge_half {R : ConstructiveReals} (j : nat) :
  CRle R (CR_of_Q R (Qmake 1 2))
         (CRsum_list (fun k => CR_of_Q R (Qinv_n k)) (iota (Pos.to_nat (pow2p j) + 1) (Pos.to_nat (pow2p j)))).
Proof.
  (* 逐项 ≥ 1/2^{j+1} *)
  have Hpt : forall k, k \in iota (Pos.to_nat (pow2p j) + 1) (Pos.to_nat (pow2p j)) ->
              CRle R (CR_of_Q R (Qmake 1 (pow2p (S j)))) (CR_of_Q R (Qinv_n k)).
  { move => k Hk.
    rewrite mem_iota in Hk. move/andP: Hk => [Hlo Hhi].
    apply (inv_ge_pow (R := R) j k).
    - (* 1 ≤ k：1 ≤ Pos.to_nat (pow2p j) + 1 ≤ k（Hlo） *)
      apply (leq_trans (leq_addl (Pos.to_nat (pow2p j)) 1) Hlo).
    - (* k ≤ Pos.to_nat (pow2p (S j))：
         Hhi : k < Pos.to_nat (pow2p j) + 1 + Pos.to_nat (pow2p j)
             = 2·Pos.to_nat (pow2p j) + 1 = Pos.to_nat (pow2p (S j)) + 1 ⟹ k ≤ ... *)
      have H2m : Pos.to_nat (pow2p (S j)) = Pos.to_nat (pow2p j) + Pos.to_nat (pow2p j).
      { rewrite (pow2p_to_nat (S j)). rewrite (pow2p_to_nat j).
        rewrite expnS. rewrite mulnC. rewrite muln2. rewrite -addnn. reflexivity. }
      have Hbound : (Pos.to_nat (pow2p j) + 1 + Pos.to_nat (pow2p j)) = S (Pos.to_nat (pow2p (S j))).
      { rewrite addnAC. rewrite -H2m. rewrite addn1. reflexivity. }
      rewrite Hbound in Hhi. exact Hhi. }
  (* Σ ≥ 常数和 == 1/2 *)
  eapply CRle_trans.
  - (* 1/2 ≤ 常数和：2^j · 1/2^{j+1} == 1/2 *)
    have Hconst : CReq R
      (CRsum_list (fun _ : nat => CR_of_Q R (Qmake 1 (pow2p (S j)))) (iota (Pos.to_nat (pow2p j) + 1) (Pos.to_nat (pow2p j))))
      (CR_of_Q R (Qmake 1 2)).
    { rewrite (CRsum_list_const_iota (R := R) (Qmake 1 (pow2p (S j))) (Pos.to_nat (pow2p j) + 1) (Pos.to_nat (pow2p j))).
      (* CR_of_Q (2^j · 1/2^{j+1}) == CR_of_Q (1/2) *)
      apply (CR_of_Q_Qeq (R := R)
               (Qmult (Qmake (Z.of_nat (Pos.to_nat (pow2p j))) 1) (Qmake 1 (pow2p (S j))))
               (Qmake 1 2)).
      rewrite (positive_nat_Z (pow2p j)).
      unfold Qmult, Qeq. simpl.
      lia. }
    apply (proj2 (CRle_morph R
      (CR_of_Q R (Qmake 1 2))
      (CRsum_list (fun _ : nat => CR_of_Q R (Qmake 1 (pow2p (S j)))) (iota (Pos.to_nat (pow2p j) + 1) (Pos.to_nat (pow2p j))))
      (CReq_sym (CRsum_list (fun _ : nat => CR_of_Q R (Qmake 1 (pow2p (S j)))) (iota (Pos.to_nat (pow2p j) + 1) (Pos.to_nat (pow2p j))))
                (CR_of_Q R (Qmake 1 2)) Hconst)
      (CRsum_list (fun _ : nat => CR_of_Q R (Qmake 1 (pow2p (S j)))) (iota (Pos.to_nat (pow2p j) + 1) (Pos.to_nat (pow2p j))))
      (CRsum_list (fun _ : nat => CR_of_Q R (Qmake 1 (pow2p (S j)))) (iota (Pos.to_nat (pow2p j) + 1) (Pos.to_nat (pow2p j))))
      (CReq_refl (R := R) (CRsum_list (fun _ : nat => CR_of_Q R (Qmake 1 (pow2p (S j)))) (iota (Pos.to_nat (pow2p j) + 1) (Pos.to_nat (pow2p j))))))).
    apply CRle_refl.
  - (* 常数和 ≤ Σ Qinv_n（逐项） *)
    apply (CRsum_list_le_pointwise_list (R := R)
             (fun _ : nat => CR_of_Q R (Qmake 1 (pow2p (S j))))
             (fun k => CR_of_Q R (Qinv_n k))
             (iota (Pos.to_nat (pow2p j) + 1) (Pos.to_nat (pow2p j)))).
    move => k Hk. apply (Hpt k Hk).
Qed.

(* ★ 部分和 ≥ 1 + m/2：Σ_{k=1}^{2^m} 1/k ≥ (2+m)/2（归纳 m，组下界累加） *)
Lemma harm_pow2_ge {R : ConstructiveReals} (m : nat) :
  CRle R (CR_of_Q R (Qmake (Z.of_nat (2 + m)) 2))
         (CRsum_list (fun k => CR_of_Q R (Qinv_n k)) (iota 1 (Pos.to_nat (pow2p m)))).
Proof.
  elim: m => [|m IH].
  - (* m=0：iota 1 1 = [1]，Σ = Qinv_n 1 + 0；目标 (2+0)/2 = 1 ≤ 1 *)
    simpl.
    have Hq : CReq R (CR_of_Q R (Qmake (Z.of_nat (2 + 0)) 2)) (CR_of_Q R (Qinv_n 1)).
    { apply (CR_of_Q_Qeq (R := R) (Qmake (Z.of_nat (2 + 0)) 2) (Qinv_n 1)).
      unfold Qinv_n, Qeq. simpl. lia. }
    eapply CRle_trans.
    + (* Qmake 2 2 ≤ Qinv_n 1：Qinv_n 1 == Qmake 2 2 反向桥 *)
      apply (proj1 (CRle_morph R
        (CR_of_Q R (Qinv_n 1)) (CR_of_Q R (Qmake (Z.of_nat (2 + 0)) 2))
        (CReq_sym (CR_of_Q R (Qmake (Z.of_nat (2 + 0)) 2)) (CR_of_Q R (Qinv_n 1)) Hq)
        (CR_of_Q R (Qinv_n 1)) (CR_of_Q R (Qinv_n 1))
        (CReq_refl (R := R) (CR_of_Q R (Qinv_n 1))))).
      apply CRle_refl.
    + (* Qinv_n 1 ≤ Qinv_n 1 + 0 *)
      rewrite (CRplus_0_r (R := R) (CR_of_Q R (Qinv_n 1))). apply CRle_refl.
  - (* m+1：Σ_{k=1}^{2^{m+1}} = Σ_{k=1}^{2^m} + Σ_{k=2^m+1}^{2^{m+1}}
       前段 ≥ (2+m)/2（IH），后段 ≥ 1/2（组下界），和 ≥ (3+m)/2 = (2+(m+1))/2 *)
    rewrite (pow2p_to_nat (S m)).
    rewrite expnS. rewrite mulnC. rewrite muln2. rewrite -addnn.
    rewrite -(pow2p_to_nat m).
    rewrite (iotaD 1 (Pos.to_nat (pow2p m)) (Pos.to_nat (pow2p m))).
    rewrite (CRsum_list_cat (R := R) (fun k => CR_of_Q R (Qinv_n k))
                            (iota 1 (Pos.to_nat (pow2p m)))
                            (iota (1 + Pos.to_nat (pow2p m)) (Pos.to_nat (pow2p m)))).
    (* 目标: (2+(S m))/2 ≤ 前段 + 后段 *)
    have Hsum_morph : CReq R (CRplus R (CR_of_Q R (Qmake (Z.of_nat (2 + m)) 2))
                                       (CR_of_Q R (Qmake 1 2)))
                              (CR_of_Q R (Qmake (Z.of_nat (2 + S m)) 2)).
    { rewrite <- (CR_of_Q_plus R (Qmake (Z.of_nat (2 + m)) 2) (Qmake 1 2)).
      apply (CR_of_Q_Qeq (R := R)
               (Qplus (Qmake (Z.of_nat (2 + m)) 2) (Qmake 1 2))
               (Qmake (Z.of_nat (2 + S m)) 2)).
      unfold Qplus, Qeq.
      have HaddL : 2 + m = S (S m) by [].
      have HaddR : 2 + S m = S (S (S m)) by [].
      rewrite HaddL HaddR.
      cbn [Qnum Qden]. lia. }
    eapply CRle_trans.
    + (* (2+(S m))/2 ≤ (2+m)/2 + 1/2：Hsum_morph（A+B == C ⟹ C ≤ A+B，proj1） *)
      exact (proj1 Hsum_morph).
    + (* (2+m)/2 + 1/2 ≤ 前段 + 后段：逐项（IH + 组下界） *)
      apply (CRplus_le_compat (R := R)
               (CR_of_Q R (Qmake (Z.of_nat (2 + m)) 2))
               (CRsum_list (fun k => CR_of_Q R (Qinv_n k)) (iota 1 (Pos.to_nat (pow2p m))))
               (CR_of_Q R (Qmake 1 2))
               (CRsum_list (fun k => CR_of_Q R (Qinv_n k))
                           (iota (1 + Pos.to_nat (pow2p m)) (Pos.to_nat (pow2p m))))).
      * exact IH.
      * rewrite addnC. apply (harm_group_ge_half (R := R) m).
Qed.

(* 桥：CRsum (fun n => inv_n_pow (S n) 1) (P - 1) == CRsum_list (fun k => CR_of_Q (Qinv_n k)) (iota 1 P)
   —— CRsum 的 iota 0 形式转 iota 1（map S），逐项 inv_n_pow_1。P ≥ 1（pow2p_pos）。 *)
Lemma CRsum_harm_partial {R : ConstructiveReals} (m : nat) :
  CReq R (CRsum (fun n => inv_n_pow (S n) 1) (Pos.to_nat (pow2p m) - 1))
         (CRsum_list (fun k => CR_of_Q R (Qinv_n k)) (iota 1 (Pos.to_nat (pow2p m)))).
Proof.
  pose P := Pos.to_nat (pow2p m).
  (* P ≥ 1 ⟹ (P-1)+1 = P *)
  have HP : 0 < P := pow2p_pos m.
  have Hsub : (P - 1) + 1 = P.
  { exact (@subnK 1 P HP). }
  (* CRsum f (P-1) == CRsum_list f (iota 0 (P-1+1))（CRsum_list_iota 反） *)
  have Hiota : CReq R (CRsum_list (fun n => inv_n_pow (S n) 1) (iota 0 (P - 1 + 1)))
                      (CRsum (fun n => inv_n_pow (S n) 1) (P - 1)).
  { exact (CRsum_list_iota (R := R) (fun n => inv_n_pow (S n) 1) (P - 1)). }
  eapply CReq_trans.
  - (* CRsum == CRsum_list (iota 0 (P-1+1)) *)
    apply (CReq_sym (R := R) (CRsum_list (fun n => inv_n_pow (S n) 1) (iota 0 (P - 1 + 1)))
                     (CRsum (fun n => inv_n_pow (S n) 1) (P - 1))).
    exact Hiota.
  - (* CRsum_list (fun n => inv_n_pow (S n) 1) (iota 0 (P-1+1)) == CRsum_list (fun k => CR_of_Q (Qinv_n k)) (iota 1 P)
       —— iota 0 (P-1+1) = iota 0 P（f_equal Hsub），再 iota_shift + map + 逐项 *)
    rewrite (f_equal (iota 0) Hsub).
    rewrite (iota_shift P).
    rewrite (CRsum_list_map (R := R) (fun k => CR_of_Q R (Qinv_n k)) S (iota 0 P)).
    apply (CRsum_eq_list (R := R) (A := nat)
             (fun n => inv_n_pow (S n) 1)
             (fun n => CR_of_Q R (Qinv_n (S n)))
             (iota 0 P)).
    move => x Hx. exact (inv_n_pow_1 (R := R) x).
Qed.

(* ★ 发散定理：调和部分和无界（对任意 B，存在 N 使 Σ_{n=0}^{N} 1/(S n) > B）
   —— CR_archimedean：B < n（正整数）；取 m = 2·Pos.to_nat n：
     部分和（到 N = 2^m - 1）≥ 1 + m/2 = 1 + Pos.to_nat n > n > B。 *)
Lemma zeta_1_diverges {R : ConstructiveReals} :
  forall B : CRcarrier R,
  { N : nat & CRlt R B (CRsum (fun n => inv_n_pow (S n) 1) N) }.
Proof.
  move => B.
  destruct (CR_archimedean R B) as [n Hn].   (* n : positive，Hn : B < n（Qmake (Zpos n) 1） *)
  pose n' := Pos.to_nat n.
  pose m := 2 * n'.
  (* 部分和 N = Pos.to_nat (pow2p m) - 1：CRsum (fun n => inv_n_pow (S n) 1) N == Σ_{k=1}^{2^m} 1/k *)
  exists (Pos.to_nat (pow2p m) - 1).
  (* 链：B < n < 1 + n' = 1 + m/2 ≤ Σ_{k=1}^{2^m} 1/k == CRsum N
     其中 n 作为 Q 值 = Qmake (Zpos n) 1 == Qmake (Z.of_nat n') 1（positive_nat_Z，n' = Pos.to_nat n）。 *)
  (* n' < 1 + n'：Q 层 Z.of_nat n' < Z.of_nat (S n') *)
  have Hnlt : CRlt R (CR_of_Q R (Qmake (Z.of_nat n') 1))
                     (CR_of_Q R (Qmake (Z.of_nat (S n')) 1)).
  { apply (CR_of_Q_lt R (Qmake (Z.of_nat n') 1) (Qmake (Z.of_nat (S n')) 1)).
    unfold Qlt. simpl. lia. }
  (* B < n 且 n == n'（Q 层）⟹ B < n'（CRle_morph 桥 + CRlt_le_trans） *)
  have Hnq : Qeq (Qmake (Zpos n) 1) (Qmake (Z.of_nat n') 1).
  { unfold Qeq. simpl. rewrite (positive_nat_Z n). reflexivity. }
  have Hnle : CRle R (CR_of_Q R (Qmake (Zpos n) 1))
                     (CR_of_Q R (Qmake (Z.of_nat n') 1)).
  { exact (proj1 (CR_of_Q_Qeq (R := R) (Qmake (Z.of_nat n') 1) (Qmake (Zpos n) 1)
                              (Qeq_sym (Qmake (Zpos n) 1) (Qmake (Z.of_nat n') 1) Hnq))). }
  have Hblt : CRlt R B (CR_of_Q R (Qmake (Z.of_nat n') 1)).
  { eapply CRlt_le_trans.
    - exact Hn.
    - exact Hnle. }
  (* B < n' < 1+n' ⟹ B < 1+n' *)
  have Hblt2 : CRlt R B (CR_of_Q R (Qmake (Z.of_nat (S n')) 1)).
  { eapply CRlt_trans.
    - exact Hblt.
    - exact Hnlt. }
  (* 1 + n' == (2 + m)/2：m = 2n' ⟹ 2(1+n') = 2+m *)
  have Honeq : CReq R (CR_of_Q R (Qmake (Z.of_nat (S n')) 1))
                      (CR_of_Q R (Qmake (Z.of_nat (2 + m)) 2)).
  { apply (CR_of_Q_Qeq (R := R)
             (Qmake (Z.of_nat (S n')) 1)
             (Qmake (Z.of_nat (2 + m)) 2)).
    unfold Qeq.
    have HaddL : 2 + m = S (S m) by [].
    rewrite HaddL.
    cbn [Qnum Qden].
    have Hm : 2 * n' = m by [].
    rewrite -Hm.
    rewrite mulnE.
    lia. }
  (* 1+n' ≤ (2+m)/2（CReq proj2：CReq A B = (B ≤ A ∧ A ≤ B) ⟹ A ≤ B） *)
  have Hle2 : CRle R (CR_of_Q R (Qmake (Z.of_nat (S n')) 1))
                     (CR_of_Q R (Qmake (Z.of_nat (2 + m)) 2)).
  { exact (proj2 Honeq). }
  (* B < 1+n' ≤ (2+m)/2 ⟹ B < (2+m)/2 *)
  have Hblt3 : CRlt R B (CR_of_Q R (Qmake (Z.of_nat (2 + m)) 2)).
  { eapply CRlt_le_trans.
    - exact Hblt2.
    - exact Hle2. }
  (* (2+m)/2 ≤ Σ（harm_pow2_ge m）*)
  have Hsum_le : CRle R (CR_of_Q R (Qmake (Z.of_nat (2 + m)) 2))
                        (CRsum_list (fun k => CR_of_Q R (Qinv_n k)) (iota 1 (Pos.to_nat (pow2p m)))).
  { exact (harm_pow2_ge (R := R) m). }
  (* Σ == CRsum N（CRsum_harm_partial m）*)
  have Hsum_eq : CReq R (CRsum_list (fun k => CR_of_Q R (Qinv_n k)) (iota 1 (Pos.to_nat (pow2p m))))
                        (CRsum (fun n => inv_n_pow (S n) 1) (Pos.to_nat (pow2p m) - 1)).
  { exact (CReq_sym (R := R) (CRsum (fun n => inv_n_pow (S n) 1) (Pos.to_nat (pow2p m) - 1))
                     (CRsum_list (fun k => CR_of_Q R (Qinv_n k)) (iota 1 (Pos.to_nat (pow2p m))))
                     (CRsum_harm_partial (R := R) m)). }
  (* B < (2+m)/2 ≤ Σ == CRsum ⟹ B < CRsum *)
  eapply CRlt_le_trans.
  - exact Hblt3.
  - eapply CRle_trans.
    + exact Hsum_le.
    + exact (proj2 Hsum_eq).
Qed.






(* ==================== 模块 34/67: ca_tau ==================== *)

(* ============================================================
   库: ca_tau —— τ 定理线：碰撞质量与裁剪单调性（T2a 形式化）
   ============================================================
   定位：τ 感知频率选择（论文 B / 剪枝规则逆向定理推导）的理论侧形式化。
   核心（T2a 裁剪单调，与欧拉「截断-尾部控制」同构）：
     - τ(n) = T − n：带 n 在训练窗 T 内的碰撞质量（max 0 (T−n)，subn 截断）
     - tau_tail_mass_le：Σ_{n∈F, n>N} τ(n) ≤ count·(T−N)——截断尾部碰撞质量可控
       （欧拉 zeta_tail_bound_list（Σ_{n>P} n^{-s} ≤ 1/P）的 τ 版）
     - tau_crop_mono：N1 ≤ N2 ⟹ 保留带总碰撞质量单调不减——裁剪点越大
       保留越多 ⟹ 碰撞负债越多；剪 n>N 释放的负债 = 总量 − 保留量
   红线：零 Admitted、零自定义 Axiom/Parameter；纯 mathcomp（无 CR）。
   探针：AI注意力算法\探针\zz_probe_tau_t2a.v（EXIT=0，Print Assumptions Closed）
   注：mathcomp 无 `[seq E | x <- s, P]` 记法——统一 map+filter 分开写；
       ssr elim 对 bool 目标/Type 归纳（subseq）有「No assumption」异常——
       裁剪单调直接对 F 归纳 + case: ifP 分支（绕开 subseq）。
   ============================================================ *)

From mathcomp Require Import ssreflect ssreflect.ssrbool ssreflect.ssrnat ssreflect.seq.

Local Open Scope nat_scope.

(* τ(n) = T − n（nat 截断减法 = max 0 (T−n)）：带 n 在训练窗 T 内的碰撞质量 *)
Definition tau_mass (T n : nat) : nat := T - n.

(* 逐项尾部界：n > N ⟹ τ(n) ≤ T − N
   —— @leq_sub2l T N n：N ≤ n ⟹ T−n ≤ T−N（减数大 ⟹ 差小）。 *)
Lemma tau_mass_le_crop (T N n : nat) (H : N < n) : tau_mass T n <= T - N.
Proof.
  unfold tau_mass.
  exact (@leq_sub2l T N n (ltnW H)).
Qed.

(* 通用求和界：逐项 ≤ c ⟹ Σ_{n∈F, P n} f n ≤ count P F · c（foldr 归纳） *)
Lemma sumn_map_count_le (f : nat -> nat) (F : seq nat) (P : pred nat) (c : nat)
  (H : forall n : nat, P n -> f n <= c) :
  sumn (map (fun n => f n) [seq n <- F | P n]) <= count P F * c.
Proof.
  elim: F => [|x F' IH].
  - rewrite /sumn /=. apply leqnn.
  - rewrite /sumn /map /filter /count /=.
    case: ifP => Px.
    + (* P x true：f x + Σ' ≤ (1+count')·c = c + count'·c *)
      apply (leq_trans (leq_add (H x Px) IH)).
      rewrite add1n mulSn. apply leqnn.   (* (1+count')·c = count'.+1·c = c + count'·c（mulSn） *)
    + (* P x false：Σ' ≤ (0+count')·c = count'·c（count 不增） *)
      rewrite add0n. exact IH.
Qed.

(* ★ T2a 核心：截断尾部碰撞质量可控
   Σ_{n∈F, n>N} τ(n) ≤ count (fun n => N < n) F · (T − N)
   —— 与欧拉 zeta_tail_bound_list（Σ_{n>P} n^{-s} ≤ 1/P）同构：截断尾部贡献 ≤ 可控量。 *)
Lemma tau_tail_mass_le (F : seq nat) (T N : nat) :
  sumn (map (fun n => tau_mass T n) [seq n <- F | N < n]) <=
  count (fun n => N < n) F * (T - N).
Proof.
  apply (sumn_map_count_le (tau_mass T) F (fun n => N < n) (T - N)).
  move => n Hn. exact (tau_mass_le_crop T N n Hn).
Qed.

(* ★ T2a 主引理：裁剪单调——N1 ≤ N2 ⟹ 保留带（n ≤ N）总碰撞质量单调不减
   —— 裁剪点越大保留越多 ⟹ 碰撞负债越多；剪 n>N 释放的负债 = 总量 − 保留量。
   —— 直接对 F 归纳 + case: ifP 四分支（x 是否 ≤ N1 / ≤ N2）。 *)
Lemma tau_crop_mono (F : seq nat) (T N1 N2 : nat) (H : N1 <= N2) :
  sumn (map (fun n => tau_mass T n) [seq n <- F | n <= N1]) <=
  sumn (map (fun n => tau_mass T n) [seq n <- F | n <= N2]).
Proof.
  elim: F => [|x F' IH]; rewrite /sumn /map /filter /=.
  - (* []：0 ≤ 0 *)
    apply leqnn.
  - (* x :: F'：case (x ≤ N1) 与 (x ≤ N2) *)
    case: ifP => Hx1.
    + (* x ≤ N1：x 加入 N1 侧；x ≤ N1 ≤ N2 ⟹ 也加入 N2 侧 *)
      case: ifP => Hx2.
      * (* 两侧都加 tau x：tau x + A ≤ tau x + B（IH） *)
        apply (leq_add (leqnn (tau_mass T x)) IH).
      * (* x≤N1 且 ¬(x≤N2)：矛盾（x ≤ N1 ≤ N2） *)
        exfalso. move: Hx2 => /negP Hx2'. apply Hx2'.
        apply (leq_trans Hx1 H).
    + (* ¬(x ≤ N1)：x 不在 N1 侧 *)
      case: ifP => Hx2.
      * (* x ≤ N2：x 在 N2 侧。A ≤ B ≤ tau x + B（leq_addl：B ≤ tau x + B） *)
        apply (leq_trans IH). apply leq_addl.
      * (* 两侧都不含 x：A ≤ B（IH） *)
        exact IH.
Qed.

(* ==================== 模块 35/67: ca_rip_cr ==================== *)

Close Scope R_scope.
Close Scope Z_scope.
(* ============================================================
   库 ca_rip_cr —— 构造性 k-原子 RIP（受限等距性质）
   ============================================================
   目标：在构造性实数（Stdlib ConstructiveReals 抽象接口）上证明
         k-原子 RIP：对 M+1 个单位范数、两两相干 ≤ μ 的原子族，
         任意实系数 c_0..c_M 满足
           |‖Σ_{j≤M} c_j·u_j‖² − Σ_{j≤M} c_j²| ≤ μ·(M+1)·Σ_{j≤M} c_j²
         全部 Qed、零 Admitted、零自定义公理（仅依赖 Stdlib 构造性实数）。
   纪律：
     - 数学对象在 Set 层构造（CRcarrier R）
     - 序/极限在 Prop 层（CRle / CR_cv），不用排中律
     - 零经典实数公理（不 Require Stdlib.Reals 的 R 公理）
     - 只用抽象接口 {R : ConstructiveReals}
   结构：
     P0. CR 基础代数（平方非负、非正×非负 ≤ 0、绝对值平方恒等式）
     P1. 构造性复数 CRComplex
     P2. 范数平方 / 内积 / 线性组合 / 范数平方展开律
   ============================================================ *)
From Stdlib Require Import ConstructiveReals.
From Stdlib Require Import ConstructiveRealsMorphisms.
From Stdlib Require Import ConstructiveAbs.
From Stdlib Require Import ConstructiveSum.
From Stdlib Require Import QArith.
From Stdlib Require Import ZArith.
From Stdlib Require Import Lia.
From mathcomp Require Import ssreflect ssrbool ssrnat eqtype seq div.

(* 合并版防御：显式恢复默认参数解析（与 ca_zeta_euler 相同） *)
Unset Implicit Arguments.

Local Open Scope ConstructiveReals.
(* 不打开 Q_scope —— Q 值全部通过 Qmake 辅助构造 *)

Section CRSqr.

Context {R : ConstructiveReals}.
Add Ring CR_ring : (CRisRing R).

(* ============================================================
   P0. CR 基础代数
   ============================================================ *)

(* 0 ≤ -a 从 a ≤ 0（加法平移） *)
Lemma CR0_le_opp (a : CRcarrier R) :
  CRle R a (CR_of_Q R (Qmake 0 1)) ->
  CRle R (CR_of_Q R (Qmake 0 1)) (CRopp R a).
Proof.
  intros Ha.
  apply (CRplus_le_reg_r (R:=R) a).
  rewrite CRplus_0_l. rewrite CRplus_opp_l.
  exact Ha.
Qed.

(* 非正 × 非负 ≤ 0（CRmult_le_0_compat 的推论） *)
Lemma CRmult_le0 (a b : CRcarrier R) :
  CRle R a (CR_of_Q R (Qmake 0 1)) ->
  CRle R (CR_of_Q R (Qmake 0 1)) b ->
  CRle R (CRmult R a b) (CR_of_Q R (Qmake 0 1)).
Proof.
  intros Ha Hb.
  (* 0 <= -a *)
  assert (Hna : CRle R (CR_of_Q R (Qmake 0 1)) (CRopp R a)).
  { exact (CR0_le_opp a Ha). }
  (* 0 <= (-a) * b == -(a*b)（CRopp_mult_distr_l） *)
  assert (Hprod : CRle R (CR_of_Q R (Qmake 0 1)) (CRmult R (CRopp R a) b)).
  { apply CRmult_le_0_compat; [exact Hna | exact Hb]. }
  (* 目标 a*b <= 0，即 ¬(0 < a*b)。反证。 *)
  unfold CRle.
  intro Habs.
  assert (Hneg : CRlt R (CRopp R (CRmult R a b)) (CR_of_Q R (Qmake 0 1))).
  { rewrite <- (CRopp_0 (R:=R)).
    apply (CRopp_gt_lt_contravar (R:=R) (CRmult R a b) (CR_of_Q R (Qmake 0 1))).
    exact Habs. }
  apply Hprod.
  rewrite <- (CRopp_mult_distr_l (R:=R) a b).
  exact Hneg.
Qed.

(* 0 < -a 从 a < 0（加法平移，严格版） *)
Lemma CR0_lt_opp (a : CRcarrier R) :
  CRlt R a (CR_of_Q R (Qmake 0 1)) ->
  CRlt R (CR_of_Q R (Qmake 0 1)) (CRopp R a).
Proof.
  intros Ha.
  apply (CRplus_lt_reg_r (R:=R) a).
  rewrite CRplus_0_l. rewrite CRplus_opp_l.
  exact Ha.
Qed.

(* 平方非负：0 ≤ x·x（A1 的 AM-GM 地基。
   反证 x·x < 0 ⟹ 0 < -(x·x) == x·(-x) ⟹ x ≶ 0 ⟹ 分情况矛盾。 *)
Lemma CRsqr_nonneg (x : CRcarrier R) :
  CRle R (CR_of_Q R (Qmake 0 1)) (CRmult R x x).
Proof.
  unfold CRle. intro H. (* H : x*x < 0 *)
  assert (Hpos : CRlt R (CR_of_Q R (Qmake 0 1)) (CRmult R x (CRopp R x))).
  { rewrite <- (CRopp_mult_distr_r (R:=R) x x). (* x*(-x) == -(x*x) 反向 *)
    apply (CRplus_lt_reg_r (R:=R) (CRmult R x x)).
    rewrite CRplus_0_l. rewrite CRplus_opp_l.
    exact H. }
  destruct (CRmult_pos_appart_zero (R:=R) x (CRopp R x) Hpos) as [Hxgt|Hxlt].
  - (* 0 < x ⟹ x·x > 0，矛盾 H *)
    assert (Hsq : CRlt R (CR_of_Q R (Qmake 0 1)) (CRmult R x x)).
    { apply (CRmult_lt_0_compat R x x Hxgt Hxgt). }
    exact (fst (fst (CRltLinear R)) (CR_of_Q R (Qmake 0 1)) (CRmult R x x) Hsq H).
  - (* x < 0 ⟹ -x > 0 ⟹ (-x)·(-x) == x·x > 0，矛盾 H *)
    assert (Hnx : CRlt R (CR_of_Q R (Qmake 0 1)) (CRopp R x)).
    { exact (CR0_lt_opp x Hxlt). }
    assert (Hsq : CRlt R (CR_of_Q R (Qmake 0 1)) (CRmult R (CRopp R x) (CRopp R x))).
    { apply (CRmult_lt_0_compat R (CRopp R x) (CRopp R x) Hnx Hnx). }
    assert (Hsq' : CRlt R (CR_of_Q R (Qmake 0 1)) (CRmult R x x)).
    { rewrite <- (CRopp_mult_distr_r (R:=R) (CRopp R x) x) in Hsq.
      rewrite (CRopp_mult_distr_l (R:=R) (CRopp R x) x) in Hsq.
      rewrite (CRopp_involutive (R:=R) x) in Hsq.
      exact Hsq. }
    exact (fst (fst (CRltLinear R)) (CR_of_Q R (Qmake 0 1)) (CRmult R x x) Hsq' H).
Qed.

(* x ≤ |x|（CRabs_def2 自反 proj1） *)
Lemma CRle_abs_self (x : CRcarrier R) :
  CRle R x (CRabs R x).
Proof.
  apply (proj1 (CRabs_def2 (R:=R) x (CRabs R x) (CRle_refl (R:=R) (CRabs R x)))).
Qed.

(* -|x| ≤ x（CRabs_def2 自反 proj2） *)
Lemma CRopp_abs_le_self (x : CRcarrier R) :
  CRle R (CRopp R (CRabs R x)) x.
Proof.
  apply (proj2 (CRabs_def2 (R:=R) x (CRabs R x) (CRle_refl (R:=R) (CRabs R x)))).
Qed.

(* x − |x| ≤ 0（由 x ≤ |x|） *)
Lemma CRminus_abs_le0 (x : CRcarrier R) :
  CRle R (CRminus R x (CRabs R x)) (CR_of_Q R (Qmake 0 1)).
Proof.
  (* 目标 x - |x| <= 0。加 |x| 两边：x <= |x|。 *)
  apply (CRplus_le_reg_r (R:=R) (CRabs R x)).
  unfold CRminus.
  ring_simplify.
  exact (CRle_abs_self x).
Qed.

(* 0 ≤ x + |x|（由 -|x| ≤ x） *)
Lemma CR0_le_plus_abs (x : CRcarrier R) :
  CRle R (CR_of_Q R (Qmake 0 1)) (CRplus R x (CRabs R x)).
Proof.
  (* -|x| <= x ⟹ (-|x|) + |x| <= x + |x|，左边 == 0。
     改写目标左端 0 == (-|x|) + |x|。 *)
  rewrite <- (CRplus_opp_l (R:=R) (CRabs R x)).
  apply (CRplus_le_compat_r (R:=R) (CRabs R x) (CRopp R (CRabs R x)) x).
  exact (CRopp_abs_le_self x).
Qed.

(* 0 < |x|·|x| ⟹ x ≶ 0（CRmult_pos_appart_zero + CRabs_appart_0 + |x|≥0） *)
Lemma CRabs_apart_0_of_sq_pos (x : CRcarrier R) :
  CRlt R (CR_of_Q R (Qmake 0 1)) (CRmult R (CRabs R x) (CRabs R x)) ->
  CRapart R x (CR_of_Q R (Qmake 0 1)).
Proof.
  intro H.
  pose (Hap := CRmult_pos_appart_zero (R:=R) (CRabs R x) (CRabs R x) H).
  destruct Hap as [Hpos|Hneg].
  - exact (CRabs_appart_0 (R:=R) x Hpos).
  - (* |x| < 0 矛盾 CRabs_pos : 0 <= |x| = ¬(|x| < 0) *)
    exfalso.
    exact (CRabs_pos (R:=R) x Hneg).
Qed.

(* 代数恒等式：(x-|x|)(x+|x|) == x²-|x|²（ring 战术） *)
Lemma CRsqr_minus_abs (x : CRcarrier R) :
  CReq R (CRmult R (CRminus R x (CRabs R x)) (CRplus R x (CRabs R x)))
         (CRminus R (CRmult R x x) (CRmult R (CRabs R x) (CRabs R x))).
Proof.
  unfold CRminus.
  ring.
Qed.

(* 绝对值平方恒等式：x² == |x|²（双向 ≤，AM-GM 的关键）
   方向1：x²-|x|² = (x-|x|)(x+|x|) ≤ 0（x-|x| ≤ 0、x+|x| ≥ 0，CRmult_le0）
   方向2：反证 x² < |x|² ⟹ 稠密 q：x² < q < |x|² ⟹ 0 < |x|² ⟹ x ≶ 0 ⟹ x=±|x| 矛盾 *)
Lemma CRabs_sqr (x : CRcarrier R) :
  CReq R (CRmult R x x) (CRmult R (CRabs R x) (CRabs R x)).
Proof.
  split.
  - (* 方向1：|x|*|x| <= x*x。反证 x*x < |x|*|x|。 *)
    unfold CRle. intro H.
    (* 稠密：x*x < |x|*|x| ⟹ ∃q : Q，x*x < q < |x|*|x| *)
    destruct (CR_Q_dense R (CRmult R x x) (CRmult R (CRabs R x) (CRabs R x)) H)
      as [q [Hxq Hqabs]].
    (* 0 <= x*x（CRsqr_nonneg）且 x*x < q ⟹ 0 < q *)
    assert (Hqpos : CRlt R (CR_of_Q R (Qmake 0 1)) (CR_of_Q R q)).
    { apply (CRle_lt_trans (R:=R) (CR_of_Q R (Qmake 0 1)) (CRmult R x x) (CR_of_Q R q)).
      - exact (CRsqr_nonneg x).
      - exact Hxq. }
    (* 0 < q < |x|*|x| ⟹ 0 < |x|*|x| *)
    assert (Hsqpos : CRlt R (CR_of_Q R (Qmake 0 1)) (CRmult R (CRabs R x) (CRabs R x))).
    { apply (CRlt_trans (R:=R) (CR_of_Q R (Qmake 0 1)) (CR_of_Q R q)
             (CRmult R (CRabs R x) (CRabs R x)) Hqpos Hqabs). }
    (* x ≶ 0 *)
    destruct (CRabs_apart_0_of_sq_pos x Hsqpos) as [Hxlt|Hxgt].
    + (* x < 0 ⟹ |x| == -x ⟹ |x|*|x| == x*x，矛盾 H *)
      assert (Hxle0 : CRle R x (CR_of_Q R (Qmake 0 1))).
      { apply CRlt_asym. exact Hxlt. }
      assert (Habs_eq : CReq R (CRmult R (CRabs R x) (CRabs R x))
                               (CRmult R x x)).
      { rewrite (CRabs_left (R:=R) x Hxle0). ring. }
      (* H : x*x < |x|*|x|，Habs_eq : |x|*|x| == x*x。
         矛盾：x*x < |x|*|x| <= x*x ⟹ x*x < x*x。 *)
      exact (fst (fst (CRltLinear R)) (CRmult R x x) (CRmult R x x)
        (CRlt_le_trans (R:=R) (CRmult R x x) (CRmult R (CRabs R x) (CRabs R x)) (CRmult R x x)
          H (proj2 Habs_eq))
        (CRlt_le_trans (R:=R) (CRmult R x x) (CRmult R (CRabs R x) (CRabs R x)) (CRmult R x x)
          H (proj2 Habs_eq))).
    + (* 0 < x ⟹ |x| == x ⟹ |x|*|x| == x*x，矛盾 H *)
      assert (Hxge0 : CRle R (CR_of_Q R (Qmake 0 1)) x).
      { apply CRlt_asym. exact Hxgt. }
      assert (Habs_eq : CReq R (CRmult R (CRabs R x) (CRabs R x))
                               (CRmult R x x)).
      { rewrite (CRabs_right (R:=R) x Hxge0). reflexivity. }
      exact (fst (fst (CRltLinear R)) (CRmult R x x) (CRmult R x x)
        (CRlt_le_trans (R:=R) (CRmult R x x) (CRmult R (CRabs R x) (CRabs R x)) (CRmult R x x)
          H (proj2 Habs_eq))
        (CRlt_le_trans (R:=R) (CRmult R x x) (CRmult R (CRabs R x) (CRabs R x)) (CRmult R x x)
          H (proj2 Habs_eq))).
  - (* 方向2：x*x <= |x|*|x|，即 ¬( |x|*|x| < x*x )。
     x²-|x|² == (x-|x|)(x+|x|) <= 0（CRmult_le0 + 两因子符号）。 *)
    assert (Hprod_le : CRle R (CRmult R (CRminus R x (CRabs R x))
                                    (CRplus R x (CRabs R x)))
                             (CR_of_Q R (Qmake 0 1))).
    { apply (CRmult_le0 (CRminus R x (CRabs R x)) (CRplus R x (CRabs R x))).
      - exact (CRminus_abs_le0 x).
      - exact (CR0_le_plus_abs x). }
    (* 目标 x*x <= |x|*|x|，即 |x|*|x| < x*x -> False。反证。 *)
    unfold CRle. intro Habs.
    (* 由 Habs : |x|*|x| < x*x，加 -( |x|*|x| ) 于左侧：-( |x|²)+|x|² < -( |x|²)+x²。
       左边 = 0，右边 = x²-|x|²。故 0 < x²-|x|² == (x-|x|)(x+|x|)。 *)
    assert (Hsqpos : CRlt R (CR_of_Q R (Qmake 0 1))
             (CRmult R (CRminus R x (CRabs R x)) (CRplus R x (CRabs R x)))).
    { rewrite (CRsqr_minus_abs x).
      rewrite <- (CRplus_opp_l (R:=R) (CRmult R (CRabs R x) (CRabs R x))).
      unfold CRminus.
      rewrite (CRplus_comm (R:=R) (CRmult R x x)
               (CRopp R (CRmult R (CRabs R x) (CRabs R x)))).
      apply (CRplus_lt_compat_l R (CRopp R (CRmult R (CRabs R x) (CRabs R x)))
               (CRmult R (CRabs R x) (CRabs R x)) (CRmult R x x)).
      exact Habs. }
    (* Hsqpos : 0 < (x-|x|)(x+|x|) 与 Hprod_le : (x-|x|)(x+|x|) <= 0 矛盾。 *)
    exact (Hprod_le Hsqpos).
Qed.

(* ============================================================
   P1. 构造性复数 CRComplex（借鉴 WBJ ComplexNumbers_Constructive
        的数学结构：re/im 分量 record + Cadd/Cmul/Cconj/Cnorm_sq，
        但零 Parameter —— 剔除 WBJ 的 Cnorm/Cexp/Cinv 未实现公设，
        也剔除 ConstructiveExtra 的临时公理）。
   ============================================================ *)

Record CRComplex : Set :=
  { cre : CRcarrier R; cim : CRcarrier R }.

(* 加法：分量加 *)
Definition CRadd (z w : CRComplex) : CRComplex :=
  {| cre := cre z + cre w; cim := cim z + cim w |}.

(* 乘法：(ac−bd) +i (ad+bc) *)
Definition CRmul (z w : CRComplex) : CRComplex :=
  {| cre := cre z * cre w - cim z * cim w;
     cim := cre z * cim w + cim z * cre w |}.

(* 共轭 *)
Definition CRconj (z : CRComplex) : CRComplex :=
  {| cre := cre z; cim := - cim z |}.

(* 范数平方：re² + im²（CR 上非负，P0 的 CRsqr_nonneg 保证） *)
Definition CRnorm_sq (z : CRComplex) : CRcarrier R :=
  cre z * cre z + cim z * cim z.

(* 零与一 *)
Definition CRzero : CRComplex :=
  {| cre := CR_of_Q R (Qmake 0 1); cim := CR_of_Q R (Qmake 0 1) |}.
Definition CRone : CRComplex :=
  {| cre := CR_of_Q R (Qmake 1 1); cim := CR_of_Q R (Qmake 0 1) |}.

(* 实内积：⟨z,w⟩ = re(z)·re(w) + im(z)·im(w)（RIP 用实内积） *)
Definition CRip (z w : CRComplex) : CRcarrier R :=
  cre z * cre w + cim z * cim w.

(* 复数相等（分量 CReq） *)
Definition CReq_cplx (z w : CRComplex) : Prop :=
  CReq R (cre z) (cre w) /\ CReq R (cim z) (cim w).

(* 范数平方非负：0 ≤ ‖z‖² *)
Lemma CRnorm_sq_nonneg (z : CRComplex) :
  CRle R (CR_of_Q R (Qmake 0 1)) (CRnorm_sq z).
Proof.
  unfold CRnorm_sq.
  rewrite <- (CRplus_0_l (R:=R) (CR_of_Q R (Qmake 0 1))).
  apply (CRplus_le_compat (R:=R)
           (CR_of_Q R (Qmake 0 1)) (cre z * cre z)
           (CR_of_Q R (Qmake 0 1)) (cim z * cim z)).
  - exact (CRsqr_nonneg (cre z)).
  - exact (CRsqr_nonneg (cim z)).
Qed.

(* 线性组合（递归）：comboM 0 = c_0·u_0；comboM (S M) = comboM M + c_{SM}·u_{SM}。
   返回"索引 M 的原子"（即组合前 M+1 项）。 *)
Fixpoint CRcombo (M : nat) (c : nat -> CRcarrier R) (u : nat -> CRComplex) : CRComplex :=
  match M with
  | O => {| cre := c 0%nat * cre (u 0%nat); cim := c 0%nat * cim (u 0%nat) |}
  | S M' =>
      {| cre := cre (CRcombo M' c u) + c (S M') * cre (u (S M'));
         cim := cim (CRcombo M' c u) + c (S M') * cim (u (S M')) |}
  end.

(* 组合的范数平方展开律（Pythagoras 型）：‖combo (S M)‖² == ‖combo M‖²
   + c_{SM}²·‖u_{SM}‖² + 2·c_{SM}·⟨combo M, u_{SM}⟩ *)
Lemma CRcombo_norm_sq_rec (M : nat) (c : nat -> CRcarrier R) (u : nat -> CRComplex) :
  CReq R (CRnorm_sq (CRcombo (S M) c u))
         (CRnorm_sq (CRcombo M c u)
          + c (S M) * c (S M) * CRnorm_sq (u (S M))
          + (1 + 1) * c (S M) * CRip (CRcombo M c u) (u (S M))).
Proof.
  unfold CRnorm_sq, CRip.
  cbn [CRcombo cre cim].
  ring.
Qed.

(* 单原子范数（M=0 基）：‖combo 0‖² == c_0²·‖u_0‖² *)
Lemma CRcombo_norm_sq_one (c : nat -> CRcarrier R) (u : nat -> CRComplex) :
  CReq R (CRnorm_sq (CRcombo 0 c u))
         (c 0%nat * c 0%nat * CRnorm_sq (u 0%nat)).
Proof.
  unfold CRnorm_sq.
  cbn [CRcombo cre cim].
  ring.
Qed.

(* 内积对组合的线性：⟨combo (S M), v⟩ == ⟨combo M, v⟩ + c_{SM}·⟨u_{SM}, v⟩ *)
Lemma CRcombo_ip_rec (M : nat) (c : nat -> CRcarrier R) (u : nat -> CRComplex) (v : CRComplex) :
  CReq R (CRip (CRcombo (S M) c u) v)
         (CRip (CRcombo M c u) v + c (S M) * CRip (u (S M)) v).
Proof.
  unfold CRip.
  cbn [CRcombo cre cim].
  ring.
Qed.

(* ============================================================
   P3. cross_abs_le / sum_abs_cross_le / sum_sq_nonneg（CR 版）
   ============================================================ *)

(* 平方和 ≥ 0（逐项 CRsqr_nonneg + cond_pos_sum） *)
Lemma CRsum_sq_nonneg (M : nat) (c : nat -> CRcarrier R) :
  CRle R (CR_of_Q R (Qmake 0 1)) (CRsum (fun j => c j * c j) M).
Proof.
  apply cond_pos_sum.
  intro k.
  exact (CRsqr_nonneg (c k)).
Qed.

(* AM-GM 单步：2·|a|·|c| ≤ a² + c²
   来自 (|a|−|c|)² ≥ 0（CRsqr_nonneg）展开，|a|² == a²（CRabs_sqr）。
   即 a²+c² == 2|a||c| + (|a|−|c|)²，且 (|a|−|c|)² ≥ 0（Rplus_le_pos）。 *)
Lemma CRabs_amgm (a c : CRcarrier R) :
  CRle R ((1 + 1) * (CRabs R a * CRabs R c))
         (a * a + c * c).
Proof.
  (* (|a|−|c|)² ≥ 0 *)
  assert (H0 : CRle R (CR_of_Q R (Qmake 0 1))
                   (CRmult R (CRminus R (CRabs R a) (CRabs R c))
                             (CRminus R (CRabs R a) (CRabs R c)))).
  { exact (CRsqr_nonneg (CRminus R (CRabs R a) (CRabs R c))). }
  (* 恒等式：a²+c² == 2|a||c| + (|a|−|c|)²。
     用 ring 展开 + CRabs_sqr 替换 |a|²==a²、|c|²==c²。 *)
  assert (Heq : CReq R (a * a + c * c)
         ((1 + 1) * (CRabs R a * CRabs R c)
          + CRmult R (CRminus R (CRabs R a) (CRabs R c))
                      (CRminus R (CRabs R a) (CRabs R c)))).
  { rewrite (CRabs_sqr a). rewrite (CRabs_sqr c).
    unfold CRminus.
    ring. }
  (* 目标 2|a||c| <= a²+c²。改写 a²+c² 为 2|a||c| + (|a|-|c|)²，
     由 Rplus_le_pos 从 0 <= (|a|-|c|)² 得 2|a||c| <= 2|a||c| + (...)。 *)
  rewrite Heq.
  apply (Rplus_le_pos (R:=R) ((1 + 1) * (CRabs R a * CRabs R c))
             (CRmult R (CRminus R (CRabs R a) (CRabs R c))
                       (CRminus R (CRabs R a) (CRabs R c)))).
  exact H0.
Qed.

(* AM-GM 求和：2·Σ_{j≤M} |a|·|c_j| ≤ (M+1)·a² + Σ_{j≤M} c_j²
   逐项 CRabs_amgm（2|a||c_j| ≤ a²+c_j²）求和：
   Σ_j 2|a||c_j| ≤ Σ_j (a²+c_j²) == (M+1)·a² + Σ_j c_j²。
   表述用 INR：RHS := a²·INR(S M) + Σc_j²（INR == CR_of_Q (Z.of_nat · #1)）。 *)
Lemma CRsum_abs_cross_le
  (M : nat) (a : CRcarrier R) (c : nat -> CRcarrier R) :
  CRle R ((1 + 1) * CRsum (fun j => CRabs R a * CRabs R (c j)) M)
         (a * a * INR (S M) + CRsum (fun j => c j * c j) M).
Proof.
  (* 逐项：2|a||c_j| <= a²+c_j²（CRabs_amgm）⟹ sum_Rle。 *)
  assert (Hsum : CRle R
           (CRsum (fun j => (1 + 1) * (CRabs R a * CRabs R (c j))) M)
           (CRsum (fun j => a * a + c j * c j) M)).
  { apply (sum_Rle (R:=R)
           (fun j => (1 + 1) * (CRabs R a * CRabs R (c j)))
           (fun j => a * a + c j * c j) M).
    intro k. intro Hk.
    exact (CRabs_amgm a (c k)). }
  (* LHS：2·Σ_j (|a||c_j|) == Σ_j (2·|a||c_j|)。
     sum_scale 给 Σ_j(u k·a) == Σu·a。目标 (1+1)·Σu == Σu·(1+1)（comm）== Σ_j(u k·(1+1))。
     而 Hsum 是 Σ_j((1+1)·u k)。逐项交换：(1+1)·u k == u k·(1+1)。 *)
  rewrite (CRmult_comm (R:=R) (1 + 1)
           (CRsum (fun j => CRabs R a * CRabs R (c j)) M)).
  rewrite <- (sum_scale (R:=R) (fun j => CRabs R a * CRabs R (c j)) (1 + 1) M).
  (* 目标 Σ_j (u k·(1+1)) <= ...。Hsum 是 Σ_j((1+1)·u k)。用 sum_Rle 的逐项交换
     或直接 eapply 到 Hsum 前先转换。用 CRsum_eq + CRmult_comm 逐项。
     注意：CRsum_eq 的前提显式传入（第 4 参），避免 rewrite 生成的子目标顺序
     在不同环境（本地 mathcomp<2.6 vs CI mathcomp≥2.6）下不一致（E114 变体）。 *)
  rewrite (CRsum_eq (R:=R)
    (fun j => CRabs R a * CRabs R (c j) * (1 + 1))
    (fun j => (1 + 1) * (CRabs R a * CRabs R (c j))) M
    (fun j Hj => symmetry (CRmult_comm (R:=R) (1 + 1) (CRabs R a * CRabs R (c j))))).
  rewrite (sum_plus (R:=R) (fun j => a * a) (fun j => c j * c j) M) in Hsum.
  rewrite (sum_const (R:=R) (a * a) M) in Hsum.
  exact Hsum.
Qed.

(* ============================================================
   P4. rip_lower_M / rip_upper_M / rip_bound_k（A1 主定理，CR 版）
   ============================================================ *)

(* 辅助：0 ≤ 1+1（CR 加法中的 2，不用 ring 记法 "2"） *)
Lemma CR0_le_two :
  CRle R (CR_of_Q R (Qmake 0 1)) ((1 + 1)).
Proof.
  assert (H1 : CRle R (CR_of_Q R (Qmake 0 1)) 1).
  { apply CRlt_asym. exact (CRzero_lt_one R). }
  rewrite <- (CRplus_0_l (R:=R) (CR_of_Q R (Qmake 0 1))).
  apply (CRplus_le_compat (R:=R)
    (CR_of_Q R (Qmake 0 1)) 1
    (CR_of_Q R (Qmake 0 1)) 1).
  - exact H1.
  - exact H1.
Qed.

(* 辅助：0 ≤ INR n（构造性整数非负，经 CR_of_Q_le + Nat2Z.is_nonneg） *)
Lemma CR0_le_INR (n : nat) :
  CRle R (CR_of_Q R (Qmake 0 1)) (INR n).
Proof.
  unfold INR.
  apply CR_of_Q_le.
  unfold Qle. cbn [Qnum Qden]. repeat rewrite Z.mul_1_r.
  apply Nat2Z.is_nonneg.
Qed.

(* 辅助：INR (S n) == INR n + 1（S_INR 的构造性版） *)
Lemma CR_INR_S (n : nat) :
  CReq R (INR (S n)) (INR n + 1).
Proof.
  unfold INR.
  rewrite <- (CR_of_Q_plus R (Z.of_nat n # 1) (1 # 1)).
  apply (CR_of_Q_morph R (Z.of_nat (S n) # 1) ((Z.of_nat n # 1) + (1 # 1))).
  unfold Qeq. cbn [Qnum Qden Qplus].
  repeat rewrite Z.mul_1_r.
  rewrite Z.add_1_r.
  apply Nat2Z.inj_succ.
Qed.

(* 辅助：INR 保序 *)
Lemma CRle_INR (m n : nat) : le m n -> CRle R (INR m) (INR n).
Proof.
  intros H. unfold INR.
  apply CR_of_Q_le.
  unfold Qle. cbn [Qnum Qden]. repeat rewrite Z.mul_1_r.
  apply Nat2Z.inj_le. exact H.
Qed.

(* 组装引理（替代经典版 nra 的 rip_final，全手动 CR 链）：
   Sv+A ≤ L + A + 2·IP + Y + mu·N1·Sv（Y 为交叉项绝对值上界）、
   Y ≤ mu·(N1·A+Sv)、N2 == N1+1、mu·N1·A ≤ mu·N2·A，
   则 Sv+A ≤ L + A + 2·IP + mu·N2·(Sv+A)。 *)
Lemma CRrip_final_cr (L A Sv IP Y mu N1 N2 : CRcarrier R) :
  (CRle R (CR_of_Q R (Qmake 0 1)) mu) ->
  (CRle R (Sv + A)
         (L + A + (1 + 1) * IP + Y + mu * N1 * Sv)) ->
  (CRle R Y (mu * (N1 * A + Sv))) ->
  (CReq R N2 (N1 + 1)) ->
  (CRle R (mu * N1 * A) (mu * N2 * A)) ->
  CRle R (Sv + A) (L + A + (1 + 1) * IP + mu * N2 * (Sv + A)).
Proof.
  intros Hmu0 H3 H2 HN2 HmA.
  (* 链：
     Sv+A ≤ M1 [H3]
          ≤ M2 [H2：Y ≤ mu(N1A+Sv)，公共前缀左加]
          == M3 [ring 分配]
          ≤ M4 [HmA + mu·Sv+mu·N1·Sv == mu·N2·Sv]
          == M5 [ring] *)
  apply (CRle_trans (R:=R) (Sv + A)
    (L + A + (1 + 1) * IP + Y + mu * N1 * Sv)
    (L + A + (1 + 1) * IP + mu * N2 * (Sv + A))).
  - exact H3.
  - apply (CRle_trans (R:=R)
      (L + A + (1 + 1) * IP + Y + mu * N1 * Sv)
      (L + A + (1 + 1) * IP + (mu * (N1 * A + Sv)) + mu * N1 * Sv)
      (L + A + (1 + 1) * IP + mu * N2 * (Sv + A))).
    + (* M1 ≤ M2：前缀 L+A+2IP+mu·N1·Sv，Y ≤ mu(N1A+Sv) *)
      assert (Hl : CReq R (L + A + (1 + 1) * IP + Y + mu * N1 * Sv)
                           (L + A + (1 + 1) * IP + mu * N1 * Sv + Y)).
      { ring. }
      rewrite Hl.
      assert (Hr : CReq R (L + A + (1 + 1) * IP + (mu * (N1 * A + Sv)) + mu * N1 * Sv)
                           (L + A + (1 + 1) * IP + mu * N1 * Sv + mu * (N1 * A + Sv))).
      { ring. }
      rewrite Hr.
      apply (CRplus_le_compat_l (R:=R) (L + A + (1 + 1) * IP + mu * N1 * Sv)).
      exact H2.
    + (* M2 → M5 *)
      apply (CRle_trans (R:=R)
        (L + A + (1 + 1) * IP + (mu * (N1 * A + Sv)) + mu * N1 * Sv)
        (L + A + (1 + 1) * IP + (mu * N1 * A + (mu * Sv + mu * N1 * Sv)))
        (L + A + (1 + 1) * IP + mu * N2 * (Sv + A))).
      * (* M2 == M3：分配 *)
        assert (Hd : CReq R
          (L + A + (1 + 1) * IP + (mu * (N1 * A + Sv)) + mu * N1 * Sv)
          (L + A + (1 + 1) * IP + (mu * N1 * A + (mu * Sv + mu * N1 * Sv)))).
        { ring. }
        rewrite Hd. apply CRle_refl.
      * (* M3 → M5：经 M4 == L+A+2IP+mu·N2·A+mu·N2·Sv *)
        apply (CRle_trans (R:=R)
          (L + A + (1 + 1) * IP + (mu * N1 * A + (mu * Sv + mu * N1 * Sv)))
          (L + A + (1 + 1) * IP + (mu * N2 * A + mu * N2 * Sv))
          (L + A + (1 + 1) * IP + mu * N2 * (Sv + A))).
        -- (* M3 ≤ M4 *)
           apply (CRplus_le_compat_l (R:=R) (L + A + (1 + 1) * IP)).
           apply (CRplus_le_compat (R:=R)
             (mu * N1 * A) (mu * N2 * A)
             (mu * Sv + mu * N1 * Sv) (mu * N2 * Sv)).
           ++ exact HmA.
           ++ assert (He : CReq R (mu * Sv + mu * N1 * Sv) (mu * N2 * Sv)).
              { assert (Hring : CReq R (mu * Sv + mu * N1 * Sv)
                                        (mu * ((N1 + 1) * Sv))).
                { ring. }
                rewrite Hring.
                rewrite <- HN2.
                ring. }
              apply (proj2 He).
        -- (* M4 == M5：ring（右结合 Sv+A） *)
           assert (Hf : CReq R
             (L + A + (1 + 1) * IP + (mu * N2 * A + mu * N2 * Sv))
             (L + A + (1 + 1) * IP + mu * N2 * (Sv + A))).
           { ring. }
           apply (proj2 Hf).
Qed.


(* 组合内积的绝对值上界（三角不等式归纳）：
   |⟨combo M c u, v⟩| ≤ Σ_{j≤M} |c_j|·|⟨u_j, v⟩| *)
Lemma CRcombo_ip_abs_le_sum
  (M : nat) (c : nat -> CRcarrier R) (u : nat -> CRComplex) (v : CRComplex) :
  CRle R (CRabs R (CRip (CRcombo M c u) v))
         (CRsum (fun j => CRabs R (c j) * CRabs R (CRip (u j) v)) M).
Proof.
  induction M as [| M IH].
  - (* M=0：CRip (combo 0) v == c_0·CRip(u_0,v)，|·| == |c_0|·|⟨u_0,v⟩|（CRabs_mult）。 *)
    cbn [CRcombo].
    unfold CRip.
    (* 目标：|A| <= |c_0|·|⟨u_0,v⟩|，其中 A == c_0·⟨u_0,v⟩。
       先证 A 的 CReq 等价，再 CRabs_morph + CRabs_mult。 *)
    assert (Heq : CReq R
      (cre {| cre := c 0%nat * cre (u 0%nat);
              cim := c 0%nat * cim (u 0%nat) |} * cre v
       + cim {| cre := c 0%nat * cre (u 0%nat);
                cim := c 0%nat * cim (u 0%nat) |} * cim v)
      (c 0%nat * (cre (u 0%nat) * cre v + cim (u 0%nat) * cim v))).
    { cbn [cre cim]. ring. }
    (* 目标：|A| <= |c_0|·|⟨u_0,v⟩|，A := cre{...}·cre v + cim{...}·cim v。
       Heq : A == c_0·⟨u_0,v⟩。CRabs_morph_prop ⟹ |A| == |c_0·⟨u_0,v⟩|。
       CRabs_mult ⟹ |c_0·⟨u_0,v⟩| == |c_0|·|⟨u_0,v⟩|。 *)
    apply (CRle_trans (R:=R)
      (CRabs R (cre {| cre := c 0%nat * cre (u 0%nat);
                       cim := c 0%nat * cim (u 0%nat) |} * cre v
                + cim {| cre := c 0%nat * cre (u 0%nat);
                         cim := c 0%nat * cim (u 0%nat) |} * cim v))
      (CRabs R (CRmult R (c 0%nat) (CRip (u 0%nat) v)))
      (CRmult R (CRabs R (c 0%nat)) (CRabs R (CRip (u 0%nat) v)))).
    - (* |A| <= |c_0·⟨u_0,v⟩|：Heq 经 CRabs_morph_prop 得 |A| == |B|，proj2 给 |A| <= |B| *)
      apply (proj2 (CRabs_morph_prop R
        (cre {| cre := c 0%nat * cre (u 0%nat);
                cim := c 0%nat * cim (u 0%nat) |} * cre v
         + cim {| cre := c 0%nat * cre (u 0%nat);
                  cim := c 0%nat * cim (u 0%nat) |} * cim v)
        (CRmult R (c 0%nat) (CRip (u 0%nat) v)) Heq)).
    - (* |c_0·⟨u_0,v⟩| <= |c_0||⟨u_0,v⟩|：CRabs_mult 的 proj2（|B| == |c_0||⟨u_0,v⟩|） *)
      apply (proj2 (CRabs_mult (R:=R) (c 0%nat) (CRip (u 0%nat) v))).
  - (* 归纳步：|⟨combo(SM),v⟩| = |⟨combo M,v⟩ + c_{SM}⟨u_{SM},v⟩|
       ≤ |⟨combo M,v⟩| + |c_{SM}||⟨u_{SM},v⟩|（三角 + CRabs_mult）
       ≤ Σ_{j≤M} + |c_{SM}||⟨u_{SM},v⟩| = Σ_{j≤SM}。 *)
    rewrite (CRcombo_ip_rec M c u v).
    apply (CRle_trans (R:=R)
      (CRabs R (CRplus R (CRip (CRcombo M c u) v)
                            (CRmult R (c (S M)) (CRip (u (S M)) v))))
      (CRplus R (CRabs R (CRip (CRcombo M c u) v))
                (CRabs R (CRmult R (c (S M)) (CRip (u (S M)) v))))
      (CRsum (fun j => CRabs R (c j) * CRabs R (CRip (u j) v)) (S M))).
    + exact (CRabs_triang (R:=R) (CRip (CRcombo M c u) v)
              (CRmult R (c (S M)) (CRip (u (S M)) v))).
    + rewrite (CRabs_mult (R:=R) (c (S M)) (CRip (u (S M)) v)).
      change (CRsum (fun j => CRabs R (c j) * CRabs R (CRip (u j) v)) (S M))
        with (CRsum (fun j => CRabs R (c j) * CRabs R (CRip (u j) v)) M
             + CRabs R (c (S M)) * CRabs R (CRip (u (S M)) v)).
      apply (CRplus_le_compat (R:=R)
        (CRabs R (CRip (CRcombo M c u) v))
        (CRsum (fun j => CRabs R (c j) * CRabs R (CRip (u j) v)) M)
        (CRabs R (c (S M)) * CRabs R (CRip (u (S M)) v))
        (CRabs R (c (S M)) * CRabs R (CRip (u (S M)) v))).
      * exact IH.
      * apply CRle_refl.
Qed.

(* 内积相干上界：若所有 |⟨u_j, v⟩| ≤ μ（j ≤ M），则
   |⟨combo M c u, v⟩| ≤ μ·Σ_{j≤M} |c_j| *)
Lemma CRcross_abs_le
  (M : nat) (c : nat -> CRcarrier R) (u : nat -> CRComplex)
  (v : CRComplex) (mu : CRcarrier R) :
  (CRle R (CR_of_Q R (Qmake 0 1)) mu) ->
  (forall j, le j M ->
    CRle R (CRabs R (CRip (u j) v)) mu) ->
  CRle R (CRabs R (CRip (CRcombo M c u) v))
         (mu * CRsum (fun j => CRabs R (c j)) M).
Proof.
  intros Hmu0 Hcoh.
  (* 由 CRcombo_ip_abs_le_sum：|⟨combo,v⟩| ≤ Σ|c_j||⟨u_j,v⟩|。
     逐项 |⟨u_j,v⟩| ≤ μ（Hcoh）⟹ |c_j|·|⟨u_j,v⟩| ≤ |c_j|·μ
     （CRmult_le_compat_l，r := |c_j| ≥ 0）。
     求和：Σ|c_j|·μ == (Σ|c_j|)·μ（sum_scale 的 proj2）
     再交换 == μ·Σ|c_j|（CRmult_comm 的 proj2）。 *)
  apply (CRle_trans (R:=R)
    (CRabs R (CRip (CRcombo M c u) v))
    (CRsum (fun j => CRabs R (c j) * CRabs R (CRip (u j) v)) M)
    (mu * CRsum (fun j => CRabs R (c j)) M)).
  - exact (CRcombo_ip_abs_le_sum M c u v).
  - (* Σ_j |c_j|·|⟨u_j,v⟩| ≤ μ·Σ_j |c_j|。 *)
    apply (CRle_trans (R:=R)
      (CRsum (fun j => CRabs R (c j) * CRabs R (CRip (u j) v)) M)
      (CRsum (fun j => CRabs R (c j) * mu) M)
      (mu * CRsum (fun j => CRabs R (c j)) M)).
    + (* 逐项 |c_k|·|⟨u_k,v⟩| ≤ |c_k|·μ（CRmult_le_compat_l） *)
      apply (sum_Rle (R:=R)
        (fun j => CRabs R (c j) * CRabs R (CRip (u j) v))
        (fun j => CRabs R (c j) * mu) M).
      intro k. intro Hk.
      apply (CRmult_le_compat_l (R:=R) (CRabs R (c k))
        (CRabs R (CRip (u k) v)) mu).
      * exact (CRabs_pos (R:=R) (c k)).
      * exact (Hcoh k Hk).
    + (* Σ_j |c_j|·μ ≤ μ·Σ_j |c_j|：sum_scale 后交换 *)
      apply (CRle_trans (R:=R)
        (CRsum (fun j => CRabs R (c j) * mu) M)
        (CRsum (fun j => CRabs R (c j)) M * mu)
        (mu * CRsum (fun j => CRabs R (c j)) M)).
      * (* Σ|c_j|·μ == (Σ|c_j|)·μ：sum_scale proj2 *)
        apply (proj2 (sum_scale (R:=R) (fun j => CRabs R (c j)) mu M)).
      * (* (Σ|c_j|)·μ == μ·(Σ|c_j|)：CRmult_comm proj2 *)
        apply (proj2 (CRmult_comm (R:=R)
          (CRsum (fun j => CRabs R (c j)) M) mu)).
Qed.

(* RIP 下界（归纳）：Σ_{j≤M} c_j² ≤ ‖combo M‖² + μ·(M+1)·Σ_{j≤M} c_j²
   （注：CRcombo M 组合 0..M 共 M+1 项，对应经典版 comboM (S M)；CRsum (c²) M 同取 0..M。 *)
Lemma CRrip_lower_M
  (M : nat) (c : nat -> CRcarrier R) (u : nat -> CRComplex) (mu : CRcarrier R) :
  (CRle R (CR_of_Q R (Qmake 0 1)) mu) ->
  (forall j, le j M -> CReq R (CRnorm_sq (u j)) (CR_of_Q R (Qmake 1 1))) ->
  (forall i j, le i M -> le j M -> i <> j ->
    CRle R (CRabs R (CRip (u i) (u j))) mu) ->
  CRle R (CRsum (fun j => c j * c j) M)
         (CRnorm_sq (CRcombo M c u)
          + mu * INR (S M) * CRsum (fun j => c j * c j) M).
Proof.
  intros Hmu0.
  induction M as [| M IH].
  - (* M=0：S_0 = c_0²，‖combo 0‖² == c_0²·‖u_0‖² == c_0²·1 == c_0²。 *)
    intros Hunit Hcoh.
    assert (Hu0 : CReq R (CRnorm_sq (u 0%nat)) (CR_of_Q R (Qmake 1 1)))
      by (apply Hunit; apply le_n).
    (* ‖combo 0‖² == c_0² *)
    assert (Heq1 : CReq R (CRnorm_sq (CRcombo 0 c u)) (c 0%nat * c 0%nat)).
    { eapply CReq_trans.
      - exact (CRcombo_norm_sq_one c u).
      - rewrite Hu0. ring. }
    (* 0 ≤ mu·INR 1·c_0² *)
    assert (Hm : CRle R (CR_of_Q R (Qmake 0 1))
                     (mu * INR (S 0) * (c 0%nat * c 0%nat))).
    { apply CRmult_le_0_compat.
      - apply CRmult_le_0_compat.
        + exact Hmu0.
        + exact (CR0_le_INR (S 0)).
      - exact (CRsqr_nonneg (c 0%nat)). }
    (* c_0² ≤ ‖combo 0‖² ≤ ‖combo 0‖² + mu·INR 1·c_0² *)
    apply (CRle_trans (R:=R)
      (c 0%nat * c 0%nat)
      (CRnorm_sq (CRcombo 0 c u))
      (CRnorm_sq (CRcombo 0 c u) + mu * INR (S 0) * (c 0%nat * c 0%nat))).
    + exact (proj1 Heq1).
    + apply (Rplus_le_pos (R:=R) (CRnorm_sq (CRcombo 0 c u))
             (mu * INR (S 0) * (c 0%nat * c 0%nat))).
      exact Hm.
  - (* 归纳步：S + A² ≤ ‖combo (S M)‖² + μ·(M+2)·(S + A²)。
       链条（镜像经典版）：
       S + A² ≤ L + A² + mu·INR(SM)·S            [HIH 加 A²]
             == L + A² + (1+1)(A·IP) + (−(1+1)(A·IP)) + mu·INR(SM)·S
             ≤ L + A² + (1+1)(A·IP) + Y + mu·INR(SM)·S   [Hneg：−(1+1)(A·IP) ≤ Y]
             ≤ L + A² + (1+1)(A·IP) + mu·(INR(SM)·A² + S) + mu·INR(SM)·S [H2']
             == L + A² + (1+1)(A·IP) + mu·INR(S(SM))·(S + A²)   [CRrip_final_cr]
       其中 L := ‖combo M‖²，A := c(SM)，IP := ⟨combo M, u(SM)⟩，S := Σ_{j≤M}c_j²，
       Y := 2|A||IP|。 *)
    intros Hunit Hcoh.
    set (L := CRnorm_sq (CRcombo M c u)).
    set (A := c (S M)).
    set (IP := CRip (CRcombo M c u) (u (S M))).
    set (Sv := CRsum (fun j => c j * c j) M).
    set (Sabs := CRsum (fun j => CRabs R (c j)) M).
    (* 单原子单位范数：‖u(SM)‖² == 1 *)
    assert (Hu' : CReq R (CRnorm_sq (u (S M))) (CR_of_Q R (Qmake 1 1)))
      by (apply Hunit; apply le_n).
    (* IH 截取到 M *)
    assert (HIH : CRle R Sv (L + mu * INR (S M) * Sv)).
    { apply IH.
      - intros j Hj. apply Hunit.
        exact (Nat.le_trans _ M (S M) Hj (Nat.le_succ_diag_r M)).
      - intros i j Hi Hj Hne. apply Hcoh.
        + exact (Nat.le_trans _ M (S M) Hi (Nat.le_succ_diag_r M)).
        + exact (Nat.le_trans _ M (S M) Hj (Nat.le_succ_diag_r M)).
        + exact Hne. }
    (* Lp == L + A² + (1+1)(A·IP)（norm_sq_rec + Hu'） *)
    assert (Hnorm : CReq R (CRnorm_sq (CRcombo (S M) c u))
                           (L + A * A + (1 + 1) * (A * IP))).
    { eapply CReq_trans.
      - exact (CRcombo_norm_sq_rec M c u).
      - rewrite Hu'. unfold L, A, IP. ring. }
    (* Hneg：−((1+1)(A·IP)) ≤ (1+1)|A||IP|（−x ≤ |x| == (1+1)|A||IP|） *)
    assert (Hneg : CRle R (CRopp R ((1 + 1) * (A * IP)))
                         ((1 + 1) * CRabs R A * CRabs R IP)).
    { apply (CRle_trans (R:=R) (CRopp R ((1 + 1) * (A * IP)))
                        (CRabs R ((1 + 1) * (A * IP)))
                        ((1 + 1) * CRabs R A * CRabs R IP)).
      - apply (CRle_trans (R:=R) (CRopp R ((1 + 1) * (A * IP)))
                          (CRabs R (CRopp R ((1 + 1) * (A * IP))))
                          (CRabs R ((1 + 1) * (A * IP)))).
        + exact (CRle_abs_self (CRopp R ((1 + 1) * (A * IP)))).
        + apply (proj2 (CRabs_opp (R:=R) ((1 + 1) * (A * IP)))).
      - (* |(1+1)(A·IP)| == (1+1)|A||IP|（CRabs_mult + |1+1|==1+1） *)
        rewrite (CRabs_mult (R:=R) (1 + 1) (A * IP)).
        rewrite (CRabs_right (R:=R) (1 + 1) (CR0_le_two)).
        rewrite (CRabs_mult (R:=R) A IP).
        assert (Hr : CReq R ((1 + 1) * (CRabs R A * CRabs R IP))
                             ((1 + 1) * CRabs R A * CRabs R IP)). { ring. }
        apply (proj2 Hr). }
    (* H1L：S + A² ≤ L + A² + (1+1)(A·IP) + Y + mu·INR(SM)·S *)
    assert (H1L : CRle R (Sv + A * A)
         (L + A * A + (1 + 1) * (A * IP)
          + (1 + 1) * CRabs R A * CRabs R IP + mu * INR (S M) * Sv)).
    { apply (CRle_trans (R:=R) (Sv + A * A)
        (L + A * A + mu * INR (S M) * Sv)
        (L + A * A + (1 + 1) * (A * IP)
         + (1 + 1) * CRabs R A * CRabs R IP + mu * INR (S M) * Sv)).
      - (* S + A² ≤ L + A² + mu·INR(SM)·S：由 HIH 加 A² *)
        apply (CRle_trans (R:=R) (Sv + A * A)
          (A * A + (L + mu * INR (S M) * Sv))
          (L + A * A + mu * INR (S M) * Sv)).
        + assert (Hc : CReq R (Sv + A * A) (A * A + Sv)). { ring. }
          rewrite Hc.
          apply (CRplus_le_compat_l (R:=R) (A * A)).
          exact HIH.
        + assert (Hc2 : CReq R (A * A + (L + mu * INR (S M) * Sv))
                                (L + A * A + mu * INR (S M) * Sv)). { ring. }
          apply (proj2 Hc2).
      - (* L + A² + mu·INR(SM)·S ≤ L + A² + (1+1)(A·IP) + Y + mu·INR(SM)·S *)
        apply (CRplus_le_compat_r (R:=R) (mu * INR (S M) * Sv)).
        (* 目标 L + A² ≤ (L + A² + (1+1)(A·IP)) + Y：
           L + A² == L + A² + (1+1)(A·IP) + (−(1+1)(A·IP))，且 −(1+1)(A·IP) ≤ Y *)
        assert (Hlinv : CReq R (L + A * A)
           (L + A * A + (1 + 1) * (A * IP) + CRopp R ((1 + 1) * (A * IP)))).
        { ring. }
        apply (CRle_trans (R:=R) (L + A * A)
          (L + A * A + (1 + 1) * (A * IP) + CRopp R ((1 + 1) * (A * IP)))
          (L + A * A + (1 + 1) * (A * IP) + (1 + 1) * CRabs R A * CRabs R IP)).
        + apply (proj2 Hlinv).
        + apply (CRplus_le_compat_l (R:=R)
            (L + A * A + (1 + 1) * (A * IP))).
          exact Hneg. }
    (* H2：Y ≤ (1+1)|A|·(mu·Sabs)（cross_abs_le 乘 (1+1)|A| ≥ 0） *)
    assert (H2 : CRle R ((1 + 1) * CRabs R A * CRabs R IP)
                        ((1 + 1) * CRabs R A * (mu * Sabs))).
    { apply (CRmult_le_compat_l (R:=R) ((1 + 1) * CRabs R A)
        (CRabs R IP) (mu * Sabs)).
      - apply CRmult_le_0_compat.
        + exact CR0_le_two.
        + apply CRabs_pos.
      - (* |IP| ≤ mu·Sabs：CRcross_abs_le（v := u(SM)，相干截取到 M） *)
        exact (CRcross_abs_le M c u (u (S M)) mu Hmu0
          (fun j Hj => Hcoh j (S M)
            (Nat.le_trans _ M (S M) Hj (Nat.le_succ_diag_r M))
            (le_n (S M))
            (Nat.lt_neq j (S M)
              (Nat.le_lt_trans j M (S M) Hj (Nat.lt_succ_diag_r M))))). }
    (* H3：(1+1)|A|·(mu·Sabs) ≤ mu·(INR(SM)·A² + S)（sum_abs_cross_le 乘 mu ≥ 0） *)
    assert (H3 : CRle R ((1 + 1) * CRabs R A * (mu * Sabs))
                        (mu * (INR (S M) * (A * A) + Sv))).
    { apply (CRle_trans (R:=R)
        ((1 + 1) * CRabs R A * (mu * Sabs))
        (mu * ((1 + 1) * CRsum (fun j => CRabs R A * CRabs R (c j)) M))
        (mu * (INR (S M) * (A * A) + Sv))).
      - (* LHS == mu·((1+1)·Σ_j |A||c_j|) *)
        (* (1+1)(|A|·Sabs) == (1+1)Σ_j(|A||c_j|) *)
        assert (HsumA : CReq R
          (CRsum (fun j => CRabs R A * CRabs R (c j)) M)
          (CRabs R A * Sabs)).
        { rewrite (CRsum_eq (R:=R)
            (fun j => CRabs R A * CRabs R (c j))
            (fun j => CRabs R (c j) * CRabs R A) M
            (fun j Hj => CRmult_comm (R:=R) (CRabs R A) (CRabs R (c j)))).
          rewrite (sum_scale (R:=R) (fun j => CRabs R (c j)) (CRabs R A) M).
          rewrite (CRmult_comm (R:=R) Sabs (CRabs R A)).
          reflexivity. }
        assert (Hscale : CReq R ((1 + 1) * (CRabs R A * Sabs))
                                 ((1 + 1) * CRsum (fun j => CRabs R A * CRabs R (c j)) M)).
        { rewrite HsumA. reflexivity. }
        (* 改写目标 RHS：mu·((1+1)Σ) == mu·((1+1)(|A|·Sabs)) *)
        rewrite <- Hscale.
        assert (Hm1 : CReq R ((1 + 1) * CRabs R A * (mu * Sabs))
                              (mu * ((1 + 1) * (CRabs R A * Sabs)))).
        { ring. }
        apply (proj2 Hm1).
      - apply (CRmult_le_compat_l (R:=R) mu
          ((1 + 1) * CRsum (fun j => CRabs R A * CRabs R (c j)) M)
          (INR (S M) * (A * A) + Sv)).
        + exact Hmu0.
        + (* (1+1)·Σ|A||c_j| ≤ A²·INR(SM) + Σc²（CRsum_abs_cross_le），再变形 RHS *)
          assert (Hr : CReq R (A * A * INR (S M) + CRsum (fun j => c j * c j) M)
                               (INR (S M) * (A * A) + Sv)).
          { unfold Sv. ring. }
          rewrite <- Hr.
          exact (CRsum_abs_cross_le M A c). }
    (* H2'：Y ≤ mu·(INR(SM)·A² + S)（H2 + H3 合成） *)
    assert (H2' : CRle R ((1 + 1) * CRabs R A * CRabs R IP)
                         (mu * (INR (S M) * (A * A) + Sv))).
    { apply (CRle_trans (R:=R)
        ((1 + 1) * CRabs R A * CRabs R IP)
        ((1 + 1) * CRabs R A * (mu * Sabs))
        (mu * (INR (S M) * (A * A) + Sv))).
      - exact H2.
      - exact H3. }
    (* HmA：mu·INR(SM)·A² ≤ mu·INR(S(SM))·A² *)
    assert (HmA : CRle R (mu * INR (S M) * (A * A))
                         (mu * INR (S (S M)) * (A * A))).
    { apply (CRmult_le_compat_r (R:=R) (A * A)
        (mu * INR (S M)) (mu * INR (S (S M)))).
      - exact (CRsqr_nonneg A).
      - apply (CRmult_le_compat_l (R:=R) mu
          (INR (S M)) (INR (S (S M)))).
        + exact Hmu0.
        + apply (CRle_INR (S M) (S (S M))). lia. }
    (* 组装：CRrip_final_cr *)
    assert (Hfin : CRle R (Sv + A * A)
         (L + A * A + (1 + 1) * (A * IP) + mu * INR (S (S M)) * (Sv + A * A))).
    { apply (CRrip_final_cr L (A * A) Sv (A * IP)
             ((1 + 1) * CRabs R A * CRabs R IP) mu
             (INR (S M)) (INR (S (S M)))).
      - exact Hmu0.
      - exact H1L.
      - exact H2'.
      - exact (CR_INR_S (S M)).
      - exact HmA. }
    (* 收尾：目标 LHS == S+A²，目标 RHS == Hfin 的 RHS（Hnorm） *)
    change (CRsum (fun j => c j * c j) (S M)) with (Sv + A * A).
    change (mu * INR (S (S M)) * CRsum (fun j => c j * c j) (S M))
      with (mu * INR (S (S M)) * (Sv + A * A)).
    apply (CRle_trans (R:=R) (Sv + A * A)
      (L + A * A + (1 + 1) * (A * IP) + mu * INR (S (S M)) * (Sv + A * A))
      (CRnorm_sq (CRcombo (S M) c u) + mu * INR (S (S M)) * (Sv + A * A))).
    - exact Hfin.
    - (* Hfin RHS ≤ 目标 RHS：‖combo(SM)‖² == L + A² + (1+1)(A·IP)（Hnorm proj1） *)
      rewrite (CRplus_comm (R:=R) (L + A * A + (1 + 1) * (A * IP))
                           (mu * INR (S (S M)) * (Sv + A * A))).
      rewrite (CRplus_comm (R:=R) (CRnorm_sq (CRcombo (S M) c u))
                           (mu * INR (S (S M)) * (Sv + A * A))).
      apply (CRplus_le_compat_l (R:=R) (mu * INR (S (S M)) * (Sv + A * A))).
      apply (proj1 Hnorm).
Qed.

(* ============================================================
   RIP 上界与 A1 主定理（bound_k）
   ============================================================ *)

(* 组装引理（RIP 上界，镜像 rip_final 但无负数项）：
   X ≤ L + A + 2·IP（norm_sq_rec 展开）、2·IP ≤ Y ≤ mu·(N1·A+Sv)、
   L ≤ Sv + mu·N1·Sv（IH）、mu·N1·A ≤ mu·N2·A、N2 == N1+1，
   则 X ≤ Sv + A + mu·N2·(Sv+A)。 *)
Lemma CRrip_upper_final_cr (L A Sv IP Y mu N1 N2 X : CRcarrier R) :
  (CRle R X (L + A + (1 + 1) * IP)) ->
  (CRle R ((1 + 1) * IP) Y) ->
  (CRle R Y (mu * (N1 * A + Sv))) ->
  (CRle R L (Sv + mu * N1 * Sv)) ->
  (CRle R (mu * N1 * A) (mu * N2 * A)) ->
  (CReq R N2 (N1 + 1)) ->
  CRle R X (Sv + A + mu * N2 * (Sv + A)).
Proof.
  intros Hx Hip HY HIH HmA HN2.
  (* 链：
     X ≤ L + A + 2IP            [Hx]
       ≤ L + A + Y              [Hip 加前缀 L+A]
       ≤ L + A + mu(N1A+Sv)     [HY 加前缀 L+A]
       ≤ (Sv+muN1Sv) + A + mu(N1A+Sv)   [HIH 加 A+mu(N1A+Sv)]
        == Sv + A + muN1Sv + muN1A + muSv   [ring]
       ≤ Sv + A + muN2Sv + muN2A            [muN1Sv+muSv==muN2Sv；muN1A≤muN2A]
        == Sv + A + muN2(Sv+A)              [ring] *)
  apply (CRle_trans (R:=R) X (L + A + (1 + 1) * IP) (Sv + A + mu * N2 * (Sv + A))).
  - exact Hx.
  - apply (CRle_trans (R:=R)
      (L + A + (1 + 1) * IP)
      (L + A + Y)
      (Sv + A + mu * N2 * (Sv + A))).
    + apply (CRplus_le_compat_l (R:=R) (L + A)).
      exact Hip.
    + apply (CRle_trans (R:=R)
        (L + A + Y)
        (L + A + mu * (N1 * A + Sv))
        (Sv + A + mu * N2 * (Sv + A))).
      * apply (CRplus_le_compat_l (R:=R) (L + A)).
        exact HY.
      * apply (CRle_trans (R:=R)
          (L + A + mu * (N1 * A + Sv))
          ((Sv + mu * N1 * Sv) + A + mu * (N1 * A + Sv))
          (Sv + A + mu * N2 * (Sv + A))).
        -- (* L + A + mu(N1A+Sv) ≤ (Sv+muN1Sv) + A + mu(N1A+Sv)：HIH 加 A+mu(N1A+Sv) *)
           assert (Hb : CReq R (L + A + mu * (N1 * A + Sv))
                                (L + (A + mu * (N1 * A + Sv)))). { ring. }
           rewrite Hb.
           assert (Hb2 : CReq R ((Sv + mu * N1 * Sv) + A + mu * (N1 * A + Sv))
                                ((Sv + mu * N1 * Sv) + (A + mu * (N1 * A + Sv)))). { ring. }
           rewrite Hb2.
           apply (CRplus_le_compat_r (R:=R) (A + mu * (N1 * A + Sv))).
           exact HIH.
        -- (* (Sv+muN1Sv)+A+mu(N1A+Sv) ≤ Sv + A + muN2(Sv+A) *)
           apply (CRle_trans (R:=R)
             ((Sv + mu * N1 * Sv) + A + mu * (N1 * A + Sv))
             (Sv + A + mu * N1 * Sv + mu * N1 * A + mu * Sv)
             (Sv + A + mu * N2 * (Sv + A))).
           ++ (* == ring 展开 *)
              assert (Hr1 : CReq R ((Sv + mu * N1 * Sv) + A + mu * (N1 * A + Sv))
                                   (Sv + A + mu * N1 * Sv + mu * N1 * A + mu * Sv)). { ring. }
              rewrite Hr1. apply CRle_refl.
           ++ (* ≤ 目标 *)
              assert (Hg1 : CReq R (Sv + A + mu * N1 * Sv + mu * N1 * A + mu * Sv)
                                   (Sv + A + ((mu * N1 * Sv + mu * Sv) + mu * N1 * A))). { ring. }
              rewrite Hg1.
              assert (Hg2 : CReq R (Sv + A + mu * N2 * (Sv + A))
                                   (Sv + A + (mu * N2 * Sv + mu * N2 * A))). { ring. }
              rewrite Hg2.
              apply (CRplus_le_compat_l (R:=R) (Sv + A)).
              apply (CRplus_le_compat (R:=R)
                (mu * N1 * Sv + mu * Sv) (mu * N2 * Sv)
                (mu * N1 * A) (mu * N2 * A)).
              -- assert (He : CReq R (mu * N1 * Sv + mu * Sv) (mu * N2 * Sv)).
                 { assert (Hring : CReq R (mu * N1 * Sv + mu * Sv) (mu * ((N1 + 1) * Sv))). { ring. }
                   rewrite Hring. rewrite <- HN2. ring. }
                 apply (proj2 He).
              -- exact HmA.
Qed.

(* RIP 上界（归纳）：‖combo M‖² ≤ Σ_{j≤M} c_j² + μ·(M+1)·Σ_{j≤M} c_j² *)
Lemma CRrip_upper_M
  (M : nat) (c : nat -> CRcarrier R) (u : nat -> CRComplex) (mu : CRcarrier R) :
  (CRle R (CR_of_Q R (Qmake 0 1)) mu) ->
  (forall j, le j M -> CReq R (CRnorm_sq (u j)) (CR_of_Q R (Qmake 1 1))) ->
  (forall i j, le i M -> le j M -> i <> j ->
    CRle R (CRabs R (CRip (u i) (u j))) mu) ->
  CRle R (CRnorm_sq (CRcombo M c u))
         (CRsum (fun j => c j * c j) M
          + mu * INR (S M) * CRsum (fun j => c j * c j) M).
Proof.
  intros Hmu0.
  induction M as [| M IH].
  - (* M=0：‖combo 0‖² == c_0²·1 == c_0² ≤ c_0² + mu·INR 1·c_0² *)
    intros Hunit Hcoh.
    assert (Hu0 : CReq R (CRnorm_sq (u 0%nat)) (CR_of_Q R (Qmake 1 1)))
      by (apply Hunit; apply le_n).
    assert (Heq1 : CReq R (CRnorm_sq (CRcombo 0 c u)) (c 0%nat * c 0%nat)).
    { eapply CReq_trans.
      - exact (CRcombo_norm_sq_one c u).
      - rewrite Hu0. ring. }
    assert (Hm : CRle R (CR_of_Q R (Qmake 0 1))
                     (mu * INR (S 0) * (c 0%nat * c 0%nat))).
    { apply CRmult_le_0_compat.
      - apply CRmult_le_0_compat.
        + exact Hmu0.
        + exact (CR0_le_INR (S 0)).
      - exact (CRsqr_nonneg (c 0%nat)). }
    apply (CRle_trans (R:=R)
      (CRnorm_sq (CRcombo 0 c u))
      (c 0%nat * c 0%nat)
      (c 0%nat * c 0%nat + mu * INR (S 0) * (c 0%nat * c 0%nat))).
    + exact (proj2 Heq1).
    + apply (Rplus_le_pos (R:=R) (c 0%nat * c 0%nat)
             (mu * INR (S 0) * (c 0%nat * c 0%nat))).
      exact Hm.
  - (* 归纳步：X ≤ Sv + A² + mu·INR(S(SM))·(Sv+A²)。
       链条：X == L + A² + 2(A·IP)（norm_sq_rec）
             ≤ L + A² + 2|A||IP|        [2(A·IP) ≤ 2|A||IP|]
             ≤ L + A² + mu(INR(SM)·A² + Sv)  [cross_abs_le + sum_abs_cross_le]
             ≤ (Sv+mu·INR(SM)·Sv) + A² + mu(INR(SM)·A²+Sv)  [IH]
              == Sv + A² + mu·INR(S(SM))·(Sv+A²)  [CRrip_upper_final_cr] *)
    intros Hunit Hcoh.
    set (L := CRnorm_sq (CRcombo M c u)).
    set (A := c (S M)).
    set (IP := CRip (CRcombo M c u) (u (S M))).
    set (Sv := CRsum (fun j => c j * c j) M).
    set (Sabs := CRsum (fun j => CRabs R (c j)) M).
    assert (Hu' : CReq R (CRnorm_sq (u (S M))) (CR_of_Q R (Qmake 1 1)))
      by (apply Hunit; apply le_n).
    (* IH 截取到 M *)
    assert (HIH : CRle R L (Sv + mu * INR (S M) * Sv)).
    { apply IH.
      - intros j Hj. apply Hunit.
        exact (Nat.le_trans _ M (S M) Hj (Nat.le_succ_diag_r M)).
      - intros i j Hi Hj Hne. apply Hcoh.
        + exact (Nat.le_trans _ M (S M) Hi (Nat.le_succ_diag_r M)).
        + exact (Nat.le_trans _ M (S M) Hj (Nat.le_succ_diag_r M)).
        + exact Hne. }
    (* X == L + A² + 2(A·IP)（norm_sq_rec + Hu'） *)
    assert (Hnorm : CReq R (CRnorm_sq (CRcombo (S M) c u))
                           (L + A * A + (1 + 1) * (A * IP))).
    { eapply CReq_trans.
      - exact (CRcombo_norm_sq_rec M c u).
      - rewrite Hu'. unfold L, A, IP. ring. }
    (* Hip：2(A·IP) ≤ 2|A||IP|（A·IP ≤ |A·IP| == |A||IP|，乘 2 ≥ 0） *)
    assert (Hip : CRle R ((1 + 1) * (A * IP))
                         ((1 + 1) * CRabs R A * CRabs R IP)).
    { assert (Hr : CReq R ((1 + 1) * (CRabs R A * CRabs R IP))
                          ((1 + 1) * CRabs R A * CRabs R IP)). { ring. }
      rewrite <- Hr.
      apply (CRmult_le_compat_l (R:=R) (1 + 1)
        (A * IP) (CRabs R A * CRabs R IP)).
      - exact CR0_le_two.
      - apply (CRle_trans (R:=R) (A * IP)
          (CRabs R (A * IP)) (CRabs R A * CRabs R IP)).
        + exact (CRle_abs_self (A * IP)).
        + apply (proj2 (CRabs_mult (R:=R) A IP)). }
    (* H2：Y := 2|A||IP| ≤ 2|A|·(mu·Sabs)（cross_abs_le 乘 2|A| ≥ 0） *)
    assert (H2 : CRle R ((1 + 1) * CRabs R A * CRabs R IP)
                        ((1 + 1) * CRabs R A * (mu * Sabs))).
    { apply (CRmult_le_compat_l (R:=R) ((1 + 1) * CRabs R A)
        (CRabs R IP) (mu * Sabs)).
      - apply CRmult_le_0_compat.
        + exact CR0_le_two.
        + apply CRabs_pos.
      - exact (CRcross_abs_le M c u (u (S M)) mu Hmu0
          (fun j Hj => Hcoh j (S M)
            (Nat.le_trans _ M (S M) Hj (Nat.le_succ_diag_r M))
            (le_n (S M))
            (Nat.lt_neq j (S M)
              (Nat.le_lt_trans j M (S M) Hj (Nat.lt_succ_diag_r M))))). }
    (* H3：2|A|·(mu·Sabs) ≤ mu·(INR(SM)·A² + Sv)（sum_abs_cross_le 乘 mu ≥ 0） *)
    assert (H3 : CRle R ((1 + 1) * CRabs R A * (mu * Sabs))
                        (mu * (INR (S M) * (A * A) + Sv))).
    { apply (CRle_trans (R:=R)
        ((1 + 1) * CRabs R A * (mu * Sabs))
        (mu * ((1 + 1) * CRsum (fun j => CRabs R A * CRabs R (c j)) M))
        (mu * (INR (S M) * (A * A) + Sv))).
      - (* LHS == mu·((1+1)·Σ_j |A||c_j|) *)
        assert (HsumA : CReq R
          (CRsum (fun j => CRabs R A * CRabs R (c j)) M)
          (CRabs R A * Sabs)).
        { rewrite (CRsum_eq (R:=R)
            (fun j => CRabs R A * CRabs R (c j))
            (fun j => CRabs R (c j) * CRabs R A) M
            (fun j Hj => CRmult_comm (R:=R) (CRabs R A) (CRabs R (c j)))).
          rewrite (sum_scale (R:=R) (fun j => CRabs R (c j)) (CRabs R A) M).
          rewrite (CRmult_comm (R:=R) Sabs (CRabs R A)).
          reflexivity. }
        assert (Hscale : CReq R ((1 + 1) * (CRabs R A * Sabs))
                                 ((1 + 1) * CRsum (fun j => CRabs R A * CRabs R (c j)) M)).
        { rewrite HsumA. reflexivity. }
        rewrite <- Hscale.
        assert (Hm1 : CReq R ((1 + 1) * CRabs R A * (mu * Sabs))
                              (mu * ((1 + 1) * (CRabs R A * Sabs)))).
        { ring. }
        apply (proj2 Hm1).
      - apply (CRmult_le_compat_l (R:=R) mu
          ((1 + 1) * CRsum (fun j => CRabs R A * CRabs R (c j)) M)
          (INR (S M) * (A * A) + Sv)).
        + exact Hmu0.
        + assert (Hr : CReq R (A * A * INR (S M) + CRsum (fun j => c j * c j) M)
                               (INR (S M) * (A * A) + Sv)).
          { unfold Sv. ring. }
          rewrite <- Hr.
          exact (CRsum_abs_cross_le M A c). }
    (* H2'：Y ≤ mu·(INR(SM)·A² + Sv) *)
    assert (H2' : CRle R ((1 + 1) * CRabs R A * CRabs R IP)
                         (mu * (INR (S M) * (A * A) + Sv))).
    { apply (CRle_trans (R:=R)
        ((1 + 1) * CRabs R A * CRabs R IP)
        ((1 + 1) * CRabs R A * (mu * Sabs))
        (mu * (INR (S M) * (A * A) + Sv))).
      - exact H2.
      - exact H3. }
    (* HmA：mu·INR(SM)·A² ≤ mu·INR(S(SM))·A² *)
    assert (HmA : CRle R (mu * INR (S M) * (A * A))
                         (mu * INR (S (S M)) * (A * A))).
    { apply (CRmult_le_compat_r (R:=R) (A * A)
        (mu * INR (S M)) (mu * INR (S (S M)))).
      - exact (CRsqr_nonneg A).
      - apply (CRmult_le_compat_l (R:=R) mu
          (INR (S M)) (INR (S (S M)))).
        + exact Hmu0.
        + apply (CRle_INR (S M) (S (S M))). lia. }
    (* 组装：CRrip_upper_final_cr *)
    assert (Hfin : CRle R (CRnorm_sq (CRcombo (S M) c u))
         (Sv + A * A + mu * INR (S (S M)) * (Sv + A * A))).
    { apply (CRrip_upper_final_cr L (A * A) Sv (A * IP)
             ((1 + 1) * CRabs R A * CRabs R IP) mu
             (INR (S M)) (INR (S (S M)))
             (CRnorm_sq (CRcombo (S M) c u))).
      - apply (proj2 Hnorm).
      - exact Hip.
      - exact H2'.
      - exact HIH.
      - exact HmA.
      - exact (CR_INR_S (S M)). }
    (* 收尾：Σ_{SM} == Sv+A² *)
    change (CRsum (fun j => c j * c j) (S M)) with (Sv + A * A).
    change (mu * INR (S (S M)) * CRsum (fun j => c j * c j) (S M))
      with (mu * INR (S (S M)) * (Sv + A * A)).
    exact Hfin.
Qed.

(* A1 主定理（k-原子 RIP）：|‖combo M‖² − Σ_{j≤M} c_j²| ≤ μ·(M+1)·Σ_{j≤M} c_j²
   （由 lower 与 upper 组合：−t ≤ X−S 且 X−S ≤ t，t := μ·(M+1)·S） *)
Lemma CRrip_bound_k
  (M : nat) (c : nat -> CRcarrier R) (u : nat -> CRComplex) (mu : CRcarrier R) :
  (CRle R (CR_of_Q R (Qmake 0 1)) mu) ->
  (forall j, le j M -> CReq R (CRnorm_sq (u j)) (CR_of_Q R (Qmake 1 1))) ->
  (forall i j, le i M -> le j M -> i <> j ->
    CRle R (CRabs R (CRip (u i) (u j))) mu) ->
  CRle R (CRabs R (CRminus R (CRnorm_sq (CRcombo M c u))
                              (CRsum (fun j => c j * c j) M)))
         (mu * INR (S M) * CRsum (fun j => c j * c j) M).
Proof.
  intros Hmu0 Hunit Hcoh.
  (* lower：S ≤ X + mu·INR(SM)·S；upper：X ≤ S + mu·INR(SM)·S *)
  assert (Hlower := CRrip_lower_M M c u mu Hmu0 Hunit Hcoh).
  assert (Hupper := CRrip_upper_M M c u mu Hmu0 Hunit Hcoh).
  set (X := CRnorm_sq (CRcombo M c u)).
  set (Sv := CRsum (fun j => c j * c j) M).
  set (t := mu * INR (S M) * Sv).
  (* 目标 |X − Sv| ≤ t ⟺ X−Sv ≤ t 且 −t ≤ X−Sv（CRabs_def） *)
  apply (proj1 (CRabs_def R (CRminus R X Sv) t)).
  split.
  - (* X − Sv ≤ t：由 Hupper（X ≤ Sv + t） *)
    apply (CRplus_le_reg_r (R:=R) Sv).
    assert (H1 : CReq R (X - Sv + Sv) X). { unfold CRminus. ring. }
    rewrite H1.
    assert (H2 : CReq R (t + Sv) (Sv + t)). { ring. }
    rewrite H2.
    (* 目标 X ≤ Sv + t = Hupper（展开 X、Sv、t） *)
    unfold X, Sv, t in Hupper. exact Hupper.
  - (* −t ≤ X − Sv：由 Hlower（Sv ≤ X + t） *)
    assert (Hm : CReq R (CRopp R (CRminus R X Sv)) (CRminus R Sv X)). { unfold CRminus. ring. }
    rewrite Hm.
    apply (CRplus_le_reg_r (R:=R) X).
    assert (Hn : CReq R (CRminus R Sv X + X) Sv). { unfold CRminus. ring. }
    rewrite Hn.
    assert (Ho : CReq R (CRplus R t X) (CRplus R X t)). { ring. }
    rewrite Ho.
    unfold X, Sv, t in Hlower. exact Hlower.
Qed.

(* ============================================================
   P5. 唯一性收尾代数（F7 恢复正确性 R4 主定理的地基：
       Σd² ≤ μ(M+1)·Σd² 且 μ(M+1) < 1 ⟹ Σd² == 0 ⟹ 逐项零）
   ============================================================ *)

(* 收缩引理：t ≤ k·t 且 k < 1 ⟹ t ≤ 0（构造性反证：
   若 0 < t，则 0 < t 且 k < 1 ⟹ k·t < 1·t == t（CRmult_lt_compat_r + 1·t==t），
   与 t ≤ k·t（即 ¬(k·t < t)）矛盾。无 t ≥ 0 前提。 *)
Lemma CRle_scaled_le_zero (t k : CRcarrier R) :
  CRle R t (k * t) ->
  CRlt R k (CR_of_Q R (Qmake 1 1)) ->
  CRle R t (CR_of_Q R (Qmake 0 1)).
Proof.
  intros Htk Hk1.
  unfold CRle. intro H0t.
  apply Htk.
  assert (Hkt : CRlt R (k * t) (CR_of_Q R (Qmake 1 1) * t)).
  { apply (CRmult_lt_compat_r (R:=R) t k (CR_of_Q R (Qmake 1 1)) H0t Hk1). }
  rewrite (CRmult_1_l (R:=R) t) in Hkt.
  exact Hkt.
Qed.

(* 平方为零 ⟹ 元为零（构造性反证：
   0 ≤ x 的反证：x < 0 ⟹ 0 < −x ⟹ 0 < (−x)² == x²（CRopp_mult_distr_*），
   矛盾 x² ≤ 0；x ≤ 0 的反证：0 < x ⟹ 0 < x²（CRmult_lt_0_compat），矛盾。 *)
Lemma CRsqr_eq_zero (x : CRcarrier R) :
  CReq R (CRmult R x x) (CR_of_Q R (Qmake 0 1)) ->
  CReq R x (CR_of_Q R (Qmake 0 1)).
Proof.
  intros Hsq.
  assert (Hsq_le0 : CRle R (CRmult R x x) (CR_of_Q R (Qmake 0 1))).
  { exact (proj2 Hsq). }
  split; unfold CRle; intro.
  - assert (Hnx : CRlt R (CR_of_Q R (Qmake 0 1)) (CRopp R x)).
    { apply (CRplus_lt_reg_r (R:=R) x).
      rewrite CRplus_0_l. rewrite CRplus_opp_l. exact H. }
    assert (Hnxsq : CRlt R (CR_of_Q R (Qmake 0 1))
                     (CRmult R (CRopp R x) (CRopp R x))).
    { apply (CRmult_lt_0_compat R (CRopp R x) (CRopp R x) Hnx Hnx). }
    apply Hsq_le0.
    rewrite <- (CRopp_mult_distr_r (R:=R) (CRopp R x) x) in Hnxsq.
    rewrite (CRopp_mult_distr_l (R:=R) (CRopp R x) x) in Hnxsq.
    rewrite (CRopp_involutive (R:=R) x) in Hnxsq.
    exact Hnxsq.
  - apply Hsq_le0.
    apply (CRmult_lt_0_compat R x x H H).
Qed.

(* 辅助：非负逐项 ⟹ 任一项 ≤ 和（j ≤ M ⟹ f j ≤ Σ_{k≤M} f k，归纳：
   尾项情形 0 ≤ Σ_{k≤M-1} f k ⟹ f_M ≤ Σ_{k≤M-1} f k + f_M；
   前段情形 IH + Rplus_le_pos（0 ≤ f_M）。 *)
Lemma CRsum_nonneg_term_le (M : nat) (f : nat -> CRcarrier R) :
  (forall k, CRle R (CR_of_Q R (Qmake 0 1)) (f k)) ->
  forall j, le j M -> CRle R (f j) (CRsum f M).
Proof.
  intros Hnonneg.
  induction M as [| M IH].
  - intros j Hj.
    assert (Hj0 : j = 0%nat) by lia.
    subst j.
    apply CRle_refl.
  - intros j Hj.
    assert (Hj2 : j = S M \/ le j M) by lia.
    destruct Hj2 as [HjS | Hjle].
    + subst j.
      change (CRsum f (S M)) with (CRsum f M + f (S M)).
      apply (CRle_trans (R:=R) (f (S M)) (f (S M) + CRsum f M)
             (CRsum f M + f (S M))).
      * apply (Rplus_le_pos (R:=R) (f (S M)) (CRsum f M)).
        exact (cond_pos_sum f M Hnonneg).
      * assert (Hc : CReq R (f (S M) + CRsum f M) (CRsum f M + f (S M))).
        { ring. }
        exact (proj2 Hc).
    + change (CRsum f (S M)) with (CRsum f M + f (S M)).
      apply (CRle_trans (R:=R) (f j) (CRsum f M) (CRsum f M + f (S M))).
      * exact (IH j Hjle).
      * apply (Rplus_le_pos (R:=R) (CRsum f M) (f (S M))).
        exact (Hnonneg (S M)).
Qed.

(* 平方和为零 ⟹ 逐项为零（零和非负项：
   每项 c_j² ≤ Σc² == 0（CRsum_nonneg_term_le + CRle_trans），且 0 ≤ c_j²
   （CRsqr_nonneg）⟹ c_j² == 0 ⟹ c_j == 0（CRsqr_eq_zero）。 *)
Lemma CRsum_sq_zero_terms (M : nat) (c : nat -> CRcarrier R)
  (Hsq : CReq R (CRsum (fun j => c j * c j) M) (CR_of_Q R (Qmake 0 1))) :
  forall j, le j M -> CReq R (c j) (CR_of_Q R (Qmake 0 1)).
Proof.
  intros j Hj.
  assert (Hsum_le0 : CRle R (CRsum (fun j => c j * c j) M) (CR_of_Q R (Qmake 0 1))).
  { exact (proj2 Hsq). }
  assert (Hj_le : CRle R (c j * c j) (CRsum (fun j => c j * c j) M)).
  { apply (CRsum_nonneg_term_le M (fun k => c k * c k)).
    - intro k. exact (CRsqr_nonneg (c k)).
    - exact Hj. }
  assert (Hj_le0 : CRle R (c j * c j) (CR_of_Q R (Qmake 0 1))).
  { apply (CRle_trans (R:=R) (c j * c j)
           (CRsum (fun j => c j * c j) M) (CR_of_Q R (Qmake 0 1))).
    - exact Hj_le.
    - exact Hsum_le0. }
  apply (CRsqr_eq_zero (c j)).
  split; [exact (CRsqr_nonneg (c j)) | exact Hj_le0].
Qed.

End CRSqr.

(* ==================== 模块 36/67: probe_grid_ortho ==================== *)

Close Scope Z_scope.
Open Scope R_scope.
Open Scope complex_scope.
Open Scope nat_scope.
(* ============================================================
   网格阶梯正交探针（probe_grid_ortho）
   G1  grid_pair_ortho：网格原子对窗口 N 精确正交
       —— prime_character_orthogonality 的直接实例（该证明对任意 p≥2 成立，
          不用素数性；μ=0 证书的数学内核已在库中）
   G2  off_grid_ortho：公共偏移 α 在成对内积中精确相消
       —— 偏移网格同享 μ=0 证书（α 无理 ⟹ 证书保持 + 非周期，见碰撞探针 C5）
   G3  grid_ortho_mult：窗口 a·N 上正交保持（训练窗 + 全部 2^a 外推长度）

   依赖：ca_char_ortho（Cexp 机器 + prime_character_orthogonality）
         ca_independence（Csum / Csum_ext / Csum_split_rev）
   实验对应：length_extrap.py --grid N 的 theta = 2π·m/N；
             建议新增 --ogrid：theta = 2π·(β + m/N)，β 黄金比。
   ============================================================ *)
From mathcomp Require Import ssreflect ssrbool ssrnat seq eqtype div prime.
Require Import Stdlib.Reals.Reals.
Require Import Stdlib.Arith.Arith.
Require Import Stdlib.micromega.Lia.
Require Import Stdlib.micromega.Lra.
Require Import Stdlib.ZArith.ZArith.
Import ComplexNumbers.
Import FourierAnalysis.

Open Scope R_scope.
Open Scope complex_scope.
Open Scope nat_scope.   (* nat 后开：mathcomp 记法优先，裸 nat 算术（0*N+i 等）不被 R 劫持；
                            R 表达式全部显式 %R 标注（见下） *)

Module GridOrtho.

(* 合并友好：本地 Csum_ext 别名（全局命名空间冲突防御）——
   ca_independence 的 Csum_ext（f g n）与 ca_basis_lemmas 的 Csum_ext（n f g）
   签名参数序不同，合并版内联后后者遮蔽前者（后定义者胜），探针独立编译（.vo
   模块边界）解析前者 → 两环境不一致。本模块内定义本地版（直接归纳，不依赖
   外部 Csum_ext 名字），两环境均解析到此处。 *)
Lemma Csum_ext : forall (f g : nat -> Complex) (n : nat),
  (forall i, (i < n)%nat -> f i = g i) -> PrimeEmbedding.Csum f n = PrimeEmbedding.Csum g n.
Proof.
  induction n as [|n IH]; intros H.
  - reflexivity.
  - simpl.
    (* 显式 assert 前提后 rewrite (IH Hn)：不依赖 rewrite 自动统一前提子目标
       （CI mathcomp 2.6 下 rewrite IH 的前提实例化环境敏感，与 CRsum_eq 同型） *)
    assert (Hn : forall i, (i < n)%nat -> f i = g i).
    { intros i Hi. apply H. exact (ltn_trans Hi (ltnSn n)). }
    rewrite (IH Hn).
    f_equal. apply H. exact (ltnSn n).
Qed.

(* ---------- 基础：纯虚指数的加法拆分 ---------- *)

Lemma i_split (x y : R) : (0 +i (x + y)) = (0 +i x) +c (0 +i y).
Proof.
  unfold Cadd. apply Complex_eq; simpl; ring.
Qed.

Lemma Cmul_middle_comm (a b c : Complex) : a *c (b *c c) = b *c (a *c c).
Proof.
  rewrite <- Cmul_assoc. rewrite (Cmul_comm a b). rewrite Cmul_assoc. reflexivity.
Qed.

Lemma Cmul_rearr (X B Y D : Complex) :
  (X *c B) *c (Y *c D) = (X *c Y) *c (B *c D).
Proof.
  rewrite (Cmul_assoc X B (Y *c D)).
  rewrite (Cmul_middle_comm B Y D).
  rewrite <- (Cmul_assoc X Y (B *c D)).
  reflexivity.
Qed.

(* ---------- 旋转原子与网格原子 ---------- *)

(* rot_atom θ k = e^{i·k·θ}：RoPE 式旋转角 θ 在位置 k 的相位 *)
Definition rot_atom (theta : R) (k : nat) : Complex :=
  Cexp (0 +i (INR k * theta)%R).

(* grid_atom N m k = e^{2πi·m·k/N}：N-网格原子（prime_character_orthogonality 口径） *)
Definition grid_atom (N m k : nat) : Complex :=
  Cexp (0 +i (2 * PI * INR (m * k) / INR N)%R).

Definition grid_pair (N m u k : nat) : Complex :=
  grid_atom N m k *c Cconj (grid_atom N u k).

(* 角度归一：INR k · (2π·m/N) = 2π·(m·k)/N *)
Lemma angle_norm (k m N : nat) :
  (2 <= N)%nat ->
  (INR k * (2 * PI * INR m / INR N))%R = (2 * PI * INR (m * k) / INR N)%R.
Proof.
  intros HN.
  assert (Hp : (0 < INR N)%R).
  { apply lt_0_INR.
    move: (ltnW HN) => /ltP HN0.
    exact HN0. }
  rewrite mult_INR.
  field.
  apply Rgt_not_eq. exact Hp.
Qed.

Lemma rot_atom_add (theta phi : R) (k : nat) :
  rot_atom ((theta + phi)%R) k = rot_atom theta k *c rot_atom phi k.
Proof.
  unfold rot_atom.
  rewrite <- Cexp_add.
  replace ((INR k * (theta + phi))%R) with (INR k * theta + INR k * phi)%R by ring.
  rewrite i_split.
  reflexivity.
Qed.

Lemma rot_atom_lag_add (theta : R) (a b : nat) :
  rot_atom theta (a + b) = rot_atom theta a *c rot_atom theta b.
Proof.
  unfold rot_atom.
  rewrite plus_INR.
  replace ((INR a + INR b) * theta)%R with ((INR a * theta + INR b * theta)%R) by ring.
  rewrite <- Cexp_add.
  rewrite <- i_split.
  reflexivity.
Qed.

Lemma rot_conj_eq_1 (theta : R) (k : nat) :
  rot_atom theta k *c Cconj (rot_atom theta k) = C1.
Proof.
  unfold rot_atom. rewrite Cconj_Cexp.
  rewrite <- Cexp_add. rewrite <- i_split.
  replace ((INR k * theta + - (INR k * theta))%R) with 0%R by ring.
  replace (0 +i 0) with C0 by reflexivity.
  rewrite Cexp_0. reflexivity.
Qed.

(* rot 形式与 p.c.o. 口径的网格原子一致 *)
Lemma rot_grid (N m k : nat) :
  (2 <= N)%nat ->
  rot_atom (2 * PI * INR m / INR N)%R k = grid_atom N m k.
Proof.
  intros HN. unfold rot_atom, grid_atom.
  rewrite (angle_norm k m N HN).
  reflexivity.
Qed.

(* ---------- G1：网格原子对窗口 N 精确正交 ----------
   口径：PrimeEmbedding.Csum（p.c.o. 原方言）。注意 ca_independence 的
   Csum_ext(:263) 亦陈述于 PE.Csum（早于其内部 Csum(:1109) 定义）。 *)
Theorem grid_pair_ortho (N m u : nat) :
  (2 <= N)%nat -> m mod N <> u mod N ->
  PrimeEmbedding.Csum (grid_pair N m u) N = C0.
Proof.
  intros HN Hneq.
  unfold grid_pair, grid_atom.
  move: HN => /leP HNle.
  apply (prime_character_orthogonality N m u); [exact HNle | exact Hneq].
Qed.

(* ---------- 偏移相消 ---------- *)

(* 步骤 1：公共偏移 α 在成对内积中精确消失（N 无关！） *)
Lemma offset_cancel (alpha theta1 theta2 : R) (k : nat) :
  rot_atom ((alpha + theta1)%R) k *c Cconj (rot_atom ((alpha + theta2)%R) k)
  = rot_atom theta1 k *c Cconj (rot_atom theta2 k).
Proof.
  rewrite (rot_atom_add alpha theta1 k) (rot_atom_add alpha theta2 k).
  rewrite Cconj_mul Cmul_rearr.
  rewrite (rot_conj_eq_1 alpha k) Cmul_1_l.
  reflexivity.
Qed.

(* 步骤 2：网格角度的 rot 形式 = p.c.o. 口径网格原子 *)
Lemma rot_pair_grid (N m u k : nat) :
  (2 <= N)%nat ->
  rot_atom (2 * PI * INR m / INR N)%R k *c Cconj (rot_atom (2 * PI * INR u / INR N)%R k)
  = grid_pair N m u k.
Proof.
  intros HN. unfold grid_pair.
  rewrite (rot_grid N m k HN) (rot_grid N u k HN).
  reflexivity.
Qed.

(* ---------- G2：偏移网格正交（α 精确相消 ⟹ μ=0 证书保持） ---------- *)

Theorem off_grid_ortho (alpha : R) (N m u : nat) :
  (2 <= N)%nat -> m mod N <> u mod N ->
  PrimeEmbedding.Csum (fun k => rot_atom (alpha + 2 * PI * INR m / INR N)%R k *c
                 Cconj (rot_atom (alpha + 2 * PI * INR u / INR N)%R k)) N = C0.
Proof.
  intros HN Hneq.
  (* 倒退解法（E114）：Csum_ext 前提显式 assert，勿让 rewrite 自动生成前提子目标
     （CI mathcomp 2.6 下 (i<n)%nat 被解析为 bool，rewrite 自动统一失败） *)
  assert (Hp : forall k : nat, (k < N)%nat ->
    (fun k => rot_atom (alpha + 2 * PI * INR m / INR N)%R k *c
              Cconj (rot_atom (alpha + 2 * PI * INR u / INR N)%R k)) k
    = grid_pair N m u k).
  { intros k Hk.
    rewrite (offset_cancel alpha (2 * PI * INR m / INR N)%R
                             (2 * PI * INR u / INR N)%R k).
    apply rot_pair_grid. exact HN. }
  rewrite (Csum_ext _ (fun k => grid_pair N m u k) N Hp).
  apply grid_pair_ortho; [exact HN | exact Hneq].
Qed.

(* ---------- G3：多窗口正交保持 ---------- *)

(* 满周期旋转 = 1 *)
Lemma rot_full_turn (N m : nat) :
  (2 <= N)%nat ->
  rot_atom (2 * PI * INR m / INR N)%R N = C1.
Proof.
  intros HN.
  assert (Hp : (0 < INR N)%R).
  { apply lt_0_INR.
    move: (ltnW HN) => /ltP HN0.
    exact HN0. }
  unfold rot_atom.
  replace ((INR N * (2 * PI * INR m / INR N))%R) with ((2 * PI * INR m)%R)
    by (field; apply Rgt_not_eq; exact Hp).
  rewrite (INR_IZR_INZ m).
  apply Cexp_2PI_int.
Qed.

(* 相对核周期性：网格对的 lag-N 平移不变 *)
Lemma grid_pair_periodic (N m u k : nat) :
  (2 <= N)%nat ->
  grid_pair N m u (N + k) = grid_pair N m u k.
Proof.
  intros HN.
  rewrite <- (rot_pair_grid N m u (N + k) HN).
  rewrite <- (rot_pair_grid N m u k HN).
  rewrite (rot_atom_lag_add (2 * PI * INR m / INR N)%R N k).
  rewrite (rot_atom_lag_add (2 * PI * INR u / INR N)%R N k).
  rewrite Cconj_mul Cmul_rearr.
  rewrite (rot_full_turn N m HN) (rot_full_turn N u HN).
  replace (Cconj C1) with C1
    by (unfold C1, Cconj; simpl; apply Complex_eq; simpl; ring).
  rewrite !Cmul_1_l.
  reflexivity.
Qed.

(* 任意整块平移 *)
Lemma grid_pair_shift_mul (N m u c i : nat) :
  (2 <= N)%nat ->
  grid_pair N m u (c * N + i) = grid_pair N m u i.
Proof.
  intros HN. induction c as [|c IH].
  - replace (0 * N + i) with i by (rewrite mul0n add0n; reflexivity). reflexivity.
  - replace (S c * N + i) with (N + (c * N + i))
      by (rewrite mulSn addnA; reflexivity).
    rewrite (grid_pair_periodic N m u (c * N + i) HN).
    exact IH.
Qed.

(* PE.Csum 的分块拆分（头部优先递归：尾块在前） *)
Lemma PE_Csum_split (f : nat -> Complex) (n m : nat) :
  PrimeEmbedding.Csum f (n + m)
  = PrimeEmbedding.Csum (fun i => f (n + i)) m +c PrimeEmbedding.Csum f n.
Proof.
  induction m as [|m IH].
  - replace (n + 0) with n by (rewrite addn0; reflexivity).
    simpl.
    symmetry. apply Cadd_0_l.
  - replace (n + S m) with (S (n + m)) by first [rewrite (addnS n m); reflexivity | lia].
    simpl.
    rewrite IH.
    symmetry. apply Cadd_assoc.
Qed.

(* G3 主定理：窗口 a·N 上正交保持（a=1 训练窗；a=2,4,8 外推长度） *)
Theorem grid_ortho_mult (N a m u : nat) :
  (2 <= N)%nat -> m mod N <> u mod N ->
  PrimeEmbedding.Csum (grid_pair N m u) (a * N) = C0.
Proof.
  intros HN Hneq. induction a as [|a IH].
  - simpl. reflexivity.
  - rewrite mulSn.
    rewrite PE_Csum_split.
    (* 目标: Csum (fun i => f (N+i)) (a*N) +c Csum f N = C0
       先 Csum_ext 换函数：∀i<a*N, f(N+i)=f i（grid_pair_periodic）——前提显式 assert（E114） *)
    assert (Hper : forall i : nat, (i < a * N)%nat ->
      grid_pair N m u (N + i) = grid_pair N m u i).
    { intros i Hi. apply grid_pair_periodic. exact HN. }
    rewrite (Csum_ext (fun i => grid_pair N m u (N + i))
                      (grid_pair N m u) (a * N) Hper).
    rewrite IH.                  (* Csum f (a*N) → C0 *)
    rewrite Cadd_0_l.            (* 0 +c Csum f N = Csum f N *)
    apply grid_pair_ortho; [exact HN | exact Hneq].
Qed.

End GridOrtho.

(* ==================== 模块 37/67: probe_parseval ==================== *)

Close Scope Z_scope.
Open Scope R_scope.
Open Scope complex_scope.
Open Scope nat_scope.
(* ============================================================
   前置：probe_grid_ortho（G1-G3、rot_atom/grid_atom、rot_conj_eq_1）。
   库约定（本轮发现，重要）：sum_f_R0 为含端点和（Σ_{k=0}^{N}，N+1 项），
   PE.Csum 为不含端点和（k ∈ [0,N)）——l2_norm_sq 用前者。故窗口以
   "位置 0..n−1" 计时 l2_norm_sq 取 (pred n)，能量值 = INR n。

   主定理 parseval_pair（通用双原子）：
     单位范数原子 + 正交（Csum 口径，n 项窗口）⟹
     l2_norm_sq (c1*u1 + c2*u2) (pred n) = (|c1|²+|c2|²) · INR n
   实例 parseval_two（网格）：窗口 a·N（含全部 2^a 外推长度）。
   —— 等式而非界：框架界定理的退化端点 = Parseval 恒等式。
   ============================================================ *)
From mathcomp Require Import ssreflect ssrbool ssrnat seq eqtype div prime.
Require Import Stdlib.Reals.Reals.
Require Import Stdlib.Arith.Arith.
Require Import Stdlib.micromega.Lia.
Require Import Stdlib.micromega.Lra.
Require Import Stdlib.ZArith.ZArith.
Import ComplexNumbers.
Import FourierAnalysis.
Import GridOrtho.

Open Scope R_scope.
Open Scope complex_scope.
Open Scope nat_scope.

Module TParseval.

(* ---------- 求和基础设施（sum_f_R0：含端点 Σ_{k=0}^{n}） ---------- *)

Lemma sum_f_R0_ext (f g : nat -> R) (n : nat) :
  (forall k, (f k)%R = (g k)%R) -> (sum_f_R0 f n)%R = (sum_f_R0 g n)%R.
Proof.
  intros H. induction n as [| n IH]; simpl.
  - apply H.
  - rewrite H IH. reflexivity.
Qed.

Lemma sum_f_R0_plus (f g : nat -> R) (n : nat) :
  (sum_f_R0 (fun k => ((f k) + (g k))%R) n)%R
  = ((sum_f_R0 f n) + (sum_f_R0 g n))%R.
Proof.
  induction n as [| n IH]; simpl; [reflexivity | ].
  rewrite IH. ring.
Qed.

Lemma sum_f_R0_scal (cst : R) (f : nat -> R) (n : nat) :
  (sum_f_R0 (fun k => (cst * (f k))%R) n)%R = ((cst) * (sum_f_R0 f n))%R.
Proof.
  induction n as [| n IH]; simpl; [ring | ].
  rewrite IH. ring.
Qed.

Lemma sum_f_R0_const (n : nat) : (sum_f_R0 (fun _ => 1) n)%R = (INR (S n))%R.
Proof.
  induction n as [| n IH].
  - reflexivity.
  - assert (Hl : (sum_f_R0 (fun _ => 1) (S n))%R
                 = ((sum_f_R0 (fun _ => 1) n) + 1)%R) by reflexivity.
    assert (Hr : (INR (S (S n)))%R = ((INR (S n)) + 1)%R) by reflexivity.
    rewrite Hl Hr IH. ring.
Qed.

(* ---------- B1：re-桥（PE.Csum (S n)（k∈[0,n]）↔ sum_f_R0 n） ---------- *)

Lemma re_add (z1 z2 : Complex) : (re (z1 +c z2))%R = ((re z1) + (re z2))%R.
Proof. unfold Cadd. reflexivity. Qed.

Lemma re_Csum_S (f : nat -> Complex) (n : nat) :
  (re (PrimeEmbedding.Csum f (S n)))%R = (sum_f_R0 (fun k => (re (f k))) n)%R.
Proof.
  induction n as [| n IH].
  - assert (Hc0 : PrimeEmbedding.Csum f 1 = Cadd (f 0) C0) by reflexivity.
    assert (Hr0 : (sum_f_R0 (fun k => re (f k)) 0%nat)%R = (re (f 0%nat))%R) by reflexivity.
    assert (H0 : (re C0)%R = 0%R) by reflexivity.
    rewrite Hc0 re_add Hr0 H0. ring.
  - assert (Hc : PrimeEmbedding.Csum f (S (S n))
                 = Cadd (f (S n)) (PrimeEmbedding.Csum f (S n))) by reflexivity.
    assert (Hs : (sum_f_R0 (fun k => re (f k)) (S n))%R
                 = ((sum_f_R0 (fun k => re (f k)) n) + (re (f (S n))))%R) by reflexivity.
    rewrite Hc re_add IH Hs. ring.
Qed.

(* ---------- Csum 纯量齐次（PE 版） ---------- *)

Lemma Csum_scal (cc : Complex) (f : nat -> Complex) (n : nat) :
  PrimeEmbedding.Csum (fun k => cc *c f k) n = cc *c PrimeEmbedding.Csum f n.
Proof.
  induction n as [| n IH]; simpl.
  - rewrite Cmul_0_r. reflexivity.
  - rewrite Cmul_add_distr_l IH. reflexivity.
Qed.

(* ---------- A1：原子范数 ---------- *)

Lemma Cnorm_sq_conj (z : Complex) : (Cnorm_sq (Cconj z))%R = (Cnorm_sq z)%R.
Proof.
  unfold Cnorm_sq, Cconj. simpl. unfold Rsqr. ring.
Qed.

Lemma Cnorm_sq_one : (Cnorm_sq C1)%R = 1%R.
Proof. unfold Cnorm_sq. simpl. unfold Rsqr. ring. Qed.

Lemma rot_norm_sq (theta : R) (k : nat) : (Cnorm_sq (rot_atom theta k))%R = 1%R.
Proof.
  assert (H := rot_conj_eq_1 theta k).
  assert (Hs : (Cnorm_sq (rot_atom theta k *c Cconj (rot_atom theta k)))%R = 1%R)
    by (rewrite H; apply Cnorm_sq_one).
  rewrite Cnorm_sq_mult in Hs.
  rewrite Cnorm_sq_conj in Hs.
  assert (Hge : (0 <= Cnorm_sq (rot_atom theta k))%R) by apply Cnorm_sq_ge_0.
  nra.
Qed.

Lemma rot_Cnorm (theta : R) (k : nat) : (Cnorm (rot_atom theta k))%R = 1%R.
Proof.
  unfold Cnorm. rewrite rot_norm_sq sqrt_1. reflexivity.
Qed.

Lemma grid_norm_sq (N m k : nat) : (2 <= N)%nat -> (Cnorm_sq (grid_atom N m k))%R = 1%R.
Proof.
  intros HN. rewrite <- (rot_grid N m k HN). apply rot_norm_sq.
Qed.

(* ---------- A2/A3：单位原子能量与缩放（l2 口径：W+1 项） ---------- *)

Lemma unit_energy (u : nat -> Complex) (W : nat) :
  (forall k, (Cnorm_sq (u k))%R = 1%R) -> (l2_norm_sq u W)%R = (INR (S W))%R.
Proof.
  intros H. unfold l2_norm_sq.
  assert (Hext : (sum_f_R0 (fun k => Cnorm_sq (u k)) W)%R = (sum_f_R0 (fun _ => (1)%R) W)%R).
  { apply sum_f_R0_ext. intro k. apply H. }
  rewrite Hext.
  apply sum_f_R0_const.
Qed.

Lemma l2_norm_sq_scale (cc : Complex) (u : nat -> Complex) (W : nat) :
  (l2_norm_sq (fun k => cc *c u k) W)%R
  = ((Cnorm_sq cc) * (l2_norm_sq u W))%R.
Proof.
  unfold l2_norm_sq. induction W as [| W IH]; simpl.
  - rewrite Cnorm_sq_mult. reflexivity.
  - rewrite IH Cnorm_sq_mult. ring.
Qed.

(* ---------- A4：Cnorm_sq 加法展开 ---------- *)

Lemma re_mul_conj (z1 z2 : Complex) :
  (re (z1 *c Cconj z2))%R = ((re z1) * (re z2) + (im z1) * (im z2))%R.
Proof.
  unfold Cmul, Cconj. simpl. unfold Rsqr. ring.
Qed.

Lemma Cnorm_sq_add (z1 z2 : Complex) :
  (Cnorm_sq (z1 +c z2))%R
  = ((Cnorm_sq z1) + (Cnorm_sq z2)
     + 2 * ((re z1) * (re z2) + (im z1) * (im z2)))%R.
Proof.
  unfold Cnorm_sq, Cadd. simpl. unfold Rsqr. ring.
Qed.

(* ---------- A5：Pythagoras（通用单位范数原子版） ---------- *)

Theorem l2_pythagoras (F u : nat -> Complex) (cc : Complex) (W : nat) :
  (forall k, (Cnorm_sq (u k))%R = 1%R) ->
  (PrimeEmbedding.Csum (fun k => F k *c Cconj (u k)) (S W) = C0) ->
  (l2_norm_sq (fun k => F k +c cc *c u k) W)%R
  = ((l2_norm_sq F W) + (Cnorm_sq cc) * (INR (S W)))%R.
Proof.
  intros Hunit Horth. unfold l2_norm_sq.
  assert (Hpt : forall k, (Cnorm_sq (F k +c cc *c u k))%R
    = ((Cnorm_sq (F k)) + ((Cnorm_sq (cc *c u k))
        + (2 * re (F k *c Cconj (cc *c u k))))%R)%R).
  { intro k. rewrite Cnorm_sq_add re_mul_conj. ring. }
  assert (Hext2 : sum_f_R0 (fun k => Cnorm_sq (F k +c cc *c u k)) W
                 = sum_f_R0 (fun k => ((Cnorm_sq (F k) + (Cnorm_sq (cc *c u k)
                   + 2 * re (F k *c Cconj (cc *c u k)))))%R) W).
  { apply sum_f_R0_ext. intro k. apply Hpt. }
  rewrite Hext2.
  rewrite (sum_f_R0_plus (fun k => (Cnorm_sq (F k))%R)
                 (fun k => ((Cnorm_sq (cc *c u k) + 2 * re (F k *c Cconj (cc *c u k))))%R) W).
  rewrite (sum_f_R0_plus (fun k => (Cnorm_sq (cc *c u k))%R)
                 (fun k => ((2 * re (F k *c Cconj (cc *c u k))))%R) W).
  assert (Hscale : (sum_f_R0 (fun k => Cnorm_sq (cc *c u k)) W)%R
                   = ((Cnorm_sq cc) * (INR (S W)))%R).
  { rewrite <- (unit_energy u W Hunit).
    exact (l2_norm_sq_scale cc u W). }
  rewrite Hscale.
  assert (Hcross : (sum_f_R0 (fun k => 2 * re (F k *c Cconj (cc *c u k))) W)%R
                   = 0%R).
  { assert (Hx : (sum_f_R0 (fun k => 2 * re (F k *c Cconj (cc *c u k))) W)%R
              = sum_f_R0 (fun k => ((2 * re (Cconj cc *c (F k *c Cconj (u k)))))%R) W).
    { apply sum_f_R0_ext. intro k. rewrite Cconj_mul. f_equal. f_equal. apply Cmul_middle_comm. }
    rewrite Hx.
    rewrite (sum_f_R0_scal (2)%R (fun k => re (Cconj cc *c (F k *c Cconj (u k)))) W).
    rewrite <- (re_Csum_S (fun k => Cconj cc *c (F k *c Cconj (u k))) W).
    rewrite Csum_scal Horth Cmul_0_r.
    simpl. ring. }
  rewrite Hcross. ring.
Qed.

(* ---------- A6：双原子 Parseval（通用版 + 网格实例） ---------- *)

Theorem parseval_pair (n : nat) (u1 u2 : nat -> Complex) (c1 c2 : Complex) :
  (0 < n)%nat ->
  (forall k, (Cnorm_sq (u1 k))%R = 1%R) ->
  (forall k, (Cnorm_sq (u2 k))%R = 1%R) ->
  (PrimeEmbedding.Csum (fun k => u1 k *c Cconj (u2 k)) n = C0) ->
  (l2_norm_sq (fun k => c1 *c u1 k +c c2 *c u2 k) (Nat.pred n))%R
  = ((Cnorm_sq c1 + Cnorm_sq c2) * INR n)%R.
Proof.
  intros Hn Hu1 Hu2 Horth.
  destruct n as [| W]; [by rewrite ltn0 in Hn | ].
  change (Nat.pred (S W)) with W.
  (* W = pred n；正交假设在 S W = n 窗口 *)
  assert (HForth : PrimeEmbedding.Csum (fun k => (c1 *c u1 k) *c Cconj (u2 k)) (S W) = C0).
  { (* 倒退解法（E114）：Csum_ext 前提显式 assert，勿让 rewrite 自动生成前提子目标 *)
    assert (Hp : forall k : nat, (k < S W)%nat ->
      (fun k => (c1 *c u1 k) *c Cconj (u2 k)) k = c1 *c (u1 k *c Cconj (u2 k))).
    { intros k Hk. apply Cmul_assoc. }
    rewrite (Csum_ext _ (fun k => c1 *c (u1 k *c Cconj (u2 k))) (S W) Hp).
    rewrite Csum_scal Horth Cmul_0_r. reflexivity. }
  rewrite (l2_pythagoras (fun k => c1 *c u1 k) u2 c2 W Hu2 HForth).
  rewrite (l2_norm_sq_scale c1 u1 W).
  rewrite (unit_energy u1 W Hu1).
  ring.
Qed.

(* 网格实例：窗口 a·N（a=1 训练窗，a=2,4,8 外推长度） *)
Theorem parseval_two (N a m1 m2 : nat) (c1 c2 : Complex) :
  (2 <= N)%nat -> (0 < a)%nat -> (m1 mod N <> m2 mod N)%nat ->
  (l2_norm_sq (fun k => c1 *c grid_atom N m1 k +c c2 *c grid_atom N m2 k)
              (Nat.pred (a * N)))%R
  = ((Cnorm_sq c1 + Cnorm_sq c2) * INR (a * N))%R.
Proof.
  intros HN Ha Hneq.
  apply (parseval_pair (a * N) (grid_atom N m1) (grid_atom N m2) c1 c2);
    [rewrite muln_gt0; apply/andP; split; [exact Ha | exact (ltnW HN)]
    | intro k; apply grid_norm_sq; exact HN
    | intro k; apply grid_norm_sq; exact HN | ].
  (* 倒退解法（E114）：Csum_ext 前提显式 assert *)
  assert (Hp : forall k : nat, (k < a * N)%nat ->
    grid_atom N m1 k *c Cconj (grid_atom N m2 k) = grid_pair N m1 m2 k).
  { intros k Hk. unfold grid_pair. reflexivity. }
  rewrite (Csum_ext _ (grid_pair N m1 m2) (a * N) Hp).
  apply grid_ortho_mult; [exact HN | exact Hneq].
Qed.

End TParseval.

(* ---------- 构造性审计 ---------- *)

Print Assumptions TParseval.l2_pythagoras.
Print Assumptions TParseval.parseval_pair.
Print Assumptions TParseval.parseval_two.

(* ==================== 模块 38/67: probe_partial ==================== *)

Close Scope Z_scope.
Open Scope R_scope.
Open Scope complex_scope.
Open Scope nat_scope.
(* ============================================================
   主定理 dirichlet_partial_bound：N≥2，j mod N ≠ 0，r := j mod N，
   s := min r (N−r)：
     Cnorm (Csum (fun k => grid_atom N j k) W) ≤ INR N / (2 * INR s)
   ——窗口 W 无关（任意部分和统一界）。
   证明设计（消 sin 的 π-回绕）：mod 归约 → WLOG 共轭对称
   （|Σ_{N−r}| = |Σ_r|，无需 sin(π−x)）→ 半带情形 jordan 直接下界。
   引擎：Cnorm_one_minus_exp_i_theta_eq（ca_basis_lemmas:1089）+
        jordan_standard（:1783）。
   ============================================================ *)
From mathcomp Require Import ssreflect ssrbool ssrnat seq eqtype div prime.
Require Import Stdlib.Reals.Reals.
Require Import Stdlib.Arith.Arith.
Require Import Stdlib.micromega.Lia.
Require Import Stdlib.micromega.Lra.
Require Import Stdlib.ZArith.ZArith.
Import ComplexNumbers.
Import FourierAnalysis.
Import GridOrtho.
Import TParseval.

Open Scope R_scope.
Open Scope complex_scope.
Open Scope nat_scope.

Module TPartial.

(* ---------- 基础件 ---------- *)

Lemma i_split (x y : R) : (0 +i (x + y)) = (0 +i x) +c (0 +i y).
Proof. unfold Cadd. apply Complex_eq; simpl; ring. Qed.

Lemma Csub_diag (z : Complex) : z -c z = C0.
Proof. unfold Csub, C0. apply Complex_eq; simpl; ring. Qed.

(* (C1 −c a) *c b = b −c a *c b *)
Lemma Csub_distr (a b : Complex) : (C1 -c a) *c b = b -c (a *c b).
Proof. unfold Csub, Cmul, Cadd, C1. apply Complex_eq; simpl; ring. Qed.

Lemma Cexp_2pi_shift (x : R) (n : Z) :
  Cexp (0 +i (x + 2 * PI * IZR n)) = Cexp (0 +i x).
Proof.
  replace (0 +i (x + 2 * PI * IZR n)) with ((0 +i x) +c (0 +i (2 * PI * IZR n)))
    by (rewrite <- i_split; reflexivity).
  rewrite Cexp_add Cexp_2PI_int.
  rewrite Cmul_1_r. reflexivity.
Qed.

Lemma Cnorm_mult' (z1 z2 : Complex) :
  (Cnorm (z1 *c z2))%R = ((Cnorm z1) * (Cnorm z2))%R.
Proof.
  unfold Cnorm. rewrite Cnorm_sq_mult.
  apply (sqrt_mult (Cnorm_sq z1) (Cnorm_sq z2)); apply Cnorm_sq_ge_0.
Qed.

Lemma Cnorm_one' : (Cnorm C1)%R = 1%R.
Proof. unfold Cnorm. rewrite Cnorm_sq_one. rewrite sqrt_1. reflexivity. Qed.

Lemma rot_atom_one (theta : R) : rot_atom theta 1 = Cexp (0 +i theta).
Proof. unfold rot_atom. rewrite INR_1 Rmult_1_l. reflexivity. Qed.

Lemma rot_atom_zero (theta : R) : rot_atom theta 0 = C1.
Proof. unfold rot_atom. rewrite INR_0 Rmult_0_l. apply Cexp_0. Qed.

Lemma rot_step (theta : R) (W : nat) :
  rot_atom theta (S W) = rot_atom theta W *c rot_atom theta 1.
Proof. rewrite -addn1. apply rot_atom_lag_add. Qed.

(* ---------- Csum 共轭与 Cnorm 共轭 ---------- *)

Lemma Cconj_C0 : Cconj C0 = C0.
Proof. unfold Cconj, C0. apply Complex_eq; simpl; ring. Qed.

Lemma Csum_conj (f : nat -> Complex) (n : nat) :
  PrimeEmbedding.Csum (fun k => Cconj (f k)) n = Cconj (PrimeEmbedding.Csum f n).
Proof.
  induction n as [| n IH].
  - simpl. rewrite Cconj_C0. reflexivity.
  - assert (Hc : PrimeEmbedding.Csum (fun k => Cconj (f k)) (S n)
                 = Cadd (Cconj (f n)) (PrimeEmbedding.Csum (fun k => Cconj (f k)) n))
      by reflexivity.
    assert (Hc2 : PrimeEmbedding.Csum f (S n)
                  = Cadd (f n) (PrimeEmbedding.Csum f n)) by reflexivity.
    rewrite Hc IH Hc2.
    unfold Cadd, Cconj. apply Complex_eq; simpl; ring.
Qed.

Lemma Cnorm_conj (z : Complex) : (Cnorm (Cconj z))%R = (Cnorm z)%R.
Proof. unfold Cnorm. rewrite Cnorm_sq_conj. reflexivity. Qed.

(* ---------- 2D Cauchy-Schwarz 与 Cnorm 三角不等式 ---------- *)

Lemma square_ge_0 (x : R) : ((0 <= x * x))%R.
Proof.
  destruct (Rle_or_lt 0 x) as [H | H].
  - apply (Rle_trans _ (x * 0)%R).
    + replace ((x * 0))%R with 0%R by ring. apply Rle_refl.
    + apply (Rmult_le_compat_l x 0 x); [exact H | exact H].
  - replace ((x * x))%R with ((-x) * (-x))%R by ring.
    assert (Hm : (0 <= -x)%R) by lra.
    apply (Rle_trans _ ((-x) * 0)%R).
    + replace (((-x) * 0))%R with 0%R by ring. apply Rle_refl.
    + apply (Rmult_le_compat_l (-x) 0 (-x)); [exact Hm | exact Hm].
Qed.

Lemma cs2 (a1 b1 a2 b2 : R) :
  (((a1*a2 + b1*b2) * (a1*a2 + b1*b2) <= (a1*a1 + b1*b1) * (a2*a2 + b2*b2))%R).
Proof.
  assert (Hd : (((a1*a1 + b1*b1) * (a2*a2 + b2*b2) - (a1*a2 + b1*b2) * (a1*a2 + b1*b2)) = ((a1*b2 - a2*b1) * (a1*b2 - a2*b1)))%R) by ring.
  assert (Hsq : ((0 <= (a1*b2 - a2*b1) * (a1*b2 - a2*b1)))%R).
  { apply square_ge_0. }
  apply (Rle_trans _ ((a1*a2 + b1*b2) * (a1*a2 + b1*b2) + (a1*b2 - a2*b1) * (a1*b2 - a2*b1))%R).
  - nra.
  - rewrite <- Hd. nra.
Qed.

Lemma sqrt_pos' (x : R) : (0 <= x)%R -> (0 <= sqrt x)%R.
Proof. intros H. apply sqrt_positivity. exact H. Qed.

Lemma sqrt_sq (x : R) : (0 <= x)%R -> ((sqrt x * sqrt x)%R = x)%R.
Proof. intros H. assert (HR := Rsqr_sqrt x H). unfold Rsqr in HR. exact HR. Qed.

(* 平方比较传递 *)
Lemma le_from_sq (a b : R) :
  ((0 <= a)%R -> ((0 <= b)%R) -> ((a * a <= b * b)%R -> ((a <= b)%R))).
Proof.
  intros Ha Hb Hsq.
  destruct (Rle_or_lt a b) as [Hle | Hlt]; [exact Hle | ].
  exfalso.
  assert (Hsq2 : (b * b <= a * a)%R) by nra.
  nra.
Qed.

(* 点积绝对值 ≤ 范数积 *)
Lemma re_dot_abs_le (z1 z2 : Complex) :
  (Rabs ((re z1) * (re z2) + (im z1) * (im z2)) <= (Cnorm z1) * (Cnorm z2))%R.
Proof.
  assert (Hn1 : (0 <= Cnorm z1)%R)
    by (unfold Cnorm; apply sqrt_pos'; apply Cnorm_sq_ge_0).
  assert (Hn2 : (0 <= Cnorm z2)%R)
    by (unfold Cnorm; apply sqrt_pos'; apply Cnorm_sq_ge_0).
  assert (Huv : (0 <= (Cnorm z1) * (Cnorm z2))%R) by nra.
  assert (Hs1 : ((Cnorm z1) * (Cnorm z1))%R = (Cnorm_sq z1)%R)
    by (unfold Cnorm; apply sqrt_sq; apply Cnorm_sq_ge_0).
  assert (Hs2 : ((Cnorm z2) * (Cnorm z2))%R = (Cnorm_sq z2)%R)
    by (unfold Cnorm; apply sqrt_sq; apply Cnorm_sq_ge_0).
  assert (Hkey : ((((Cnorm z1) * (Cnorm z2)) * ((Cnorm z1) * (Cnorm z2))) = ((Cnorm_sq z1) * (Cnorm_sq z2)))%R)
    by (rewrite <- Hs1; rewrite <- Hs2; ring).
  assert (Hcs : (((re z1) * (re z2) + (im z1) * (im z2)) * ((re z1) * (re z2) + (im z1) * (im z2))
             <= (Cnorm_sq z1) * (Cnorm_sq z2))%R)
    by (apply cs2).
  rewrite <- Hkey in Hcs.
  destruct (Rle_or_lt 0 ((re z1) * (re z2) + (im z1) * (im z2))) as [Hpos | Hneg].
  - assert (Hpos' : ((re z1) * (re z2) + (im z1) * (im z2) >= 0)%R) by lra.
    rewrite (Rabs_right _ Hpos').
    apply (le_from_sq ((re z1) * (re z2) + (im z1) * (im z2)) ((Cnorm z1) * (Cnorm z2)));
      [exact Hpos | exact Huv | exact Hcs].
  - rewrite (Rabs_left _ Hneg).
    apply (le_from_sq (- ((re z1) * (re z2) + (im z1) * (im z2))) ((Cnorm z1) * (Cnorm z2))).
    + lra.
    + exact Huv.
    + replace ((- ((re z1) * (re z2) + (im z1) * (im z2))) * (- ((re z1) * (re z2) + (im z1) * (im z2))))%R
        with (((re z1) * (re z2) + (im z1) * (im z2)) * ((re z1) * (re z2) + (im z1) * (im z2)))%R
        by ring.
      exact Hcs.
Qed.

Lemma Cnorm_add_le (z1 z2 : Complex) :
  (Cnorm (z1 +c z2) <= (Cnorm z1) + (Cnorm z2))%R.
Proof.
  assert (Hn1 : (0 <= Cnorm z1)%R) by (unfold Cnorm; apply sqrt_pos'; apply Cnorm_sq_ge_0).
  assert (Hn2 : (0 <= Cnorm z2)%R) by (unfold Cnorm; apply sqrt_pos'; apply Cnorm_sq_ge_0).
  assert (Hs0 : (0 <= Cnorm_sq (z1 +c z2))%R) by apply Cnorm_sq_ge_0.
  assert (Hsx : ((Cnorm (z1 +c z2)) * (Cnorm (z1 +c z2)))%R = (Cnorm_sq (z1 +c z2))%R)
    by (unfold Cnorm; apply sqrt_sq; exact Hs0).
  assert (Hs1 : ((Cnorm z1) * (Cnorm z1))%R = (Cnorm_sq z1)%R)
    by (unfold Cnorm; apply sqrt_sq; apply Cnorm_sq_ge_0).
  assert (Hs2 : ((Cnorm z2) * (Cnorm z2))%R = (Cnorm_sq z2)%R)
    by (unfold Cnorm; apply sqrt_sq; apply Cnorm_sq_ge_0).
  assert (Huv : (0 <= (Cnorm z1) * (Cnorm z2))%R) by nra.
  assert (Hd : (((re z1) * (re z2) + (im z1) * (im z2)) <= ((Cnorm z1) * (Cnorm z2)))%R).
  { destruct (Rle_or_lt 0 ((re z1) * (re z2) + (im z1) * (im z2))) as [Hp | Hn].
    - assert (HA := re_dot_abs_le z1 z2).
      assert (Hp' : ((re z1) * (re z2) + (im z1) * (im z2) >= 0)%R) by lra.
      rewrite (Rabs_right _ Hp') in HA. exact HA.
    - nra. }
  assert (Hadd := Cnorm_sq_add z1 z2).
  unfold Cnorm.
  apply (le_from_sq (sqrt (Cnorm_sq (z1 +c z2))) ((Cnorm z1) + (Cnorm z2))).
  - apply sqrt_pos'. apply Cnorm_sq_ge_0.
  - lra.
  - rewrite (sqrt_sq (Cnorm_sq (z1 +c z2)) (Cnorm_sq_ge_0 (z1 +c z2))).
    rewrite Hadd.
    replace (((Cnorm z1) + (Cnorm z2)) * ((Cnorm z1) + (Cnorm z2)))%R
      with (((Cnorm_sq z1) + (Cnorm_sq z2) + 2 * ((Cnorm z1) * (Cnorm z2))))%R
      by (rewrite <- Hs1; rewrite <- Hs2; ring).
    nra.
Qed.

Lemma Cnorm_sub_le (z1 z2 : Complex) :
  (Cnorm (z1 -c z2) <= (Cnorm z1) + (Cnorm z2))%R.
Proof.
  assert (Hn1 : (0 <= Cnorm z1)%R) by (unfold Cnorm; apply sqrt_pos'; apply Cnorm_sq_ge_0).
  assert (Hn2 : (0 <= Cnorm z2)%R) by (unfold Cnorm; apply sqrt_pos'; apply Cnorm_sq_ge_0).
  assert (Hs0 : (0 <= Cnorm_sq (z1 -c z2))%R) by apply Cnorm_sq_ge_0.
  assert (Hsx : ((Cnorm (z1 -c z2)) * (Cnorm (z1 -c z2)))%R = (Cnorm_sq (z1 -c z2))%R)
    by (unfold Cnorm; apply sqrt_sq; exact Hs0).
  assert (Hs1 : ((Cnorm z1) * (Cnorm z1))%R = (Cnorm_sq z1)%R)
    by (unfold Cnorm; apply sqrt_sq; apply Cnorm_sq_ge_0).
  assert (Hs2 : ((Cnorm z2) * (Cnorm z2))%R = (Cnorm_sq z2)%R)
    by (unfold Cnorm; apply sqrt_sq; apply Cnorm_sq_ge_0).
  assert (HA := re_dot_abs_le z1 z2).
  assert (Hsub : (Cnorm_sq (z1 -c z2))%R
                 = ((Cnorm_sq z1) + (Cnorm_sq z2)
                    - 2 * ((re z1) * (re z2) + (im z1) * (im z2)))%R).
  { unfold Cnorm_sq, Csub. simpl. unfold Rsqr. ring. }
  assert (Hnd : (- ((re z1) * (re z2) + (im z1) * (im z2)) <= (Cnorm z1) * (Cnorm z2))%R).
  { destruct (Rle_or_lt 0 ((re z1) * (re z2) + (im z1) * (im z2))) as [Hp2 | Hn2'].
    - nra.
    - rewrite (Rabs_left _ Hn2') in HA. exact HA. }
  unfold Cnorm.
  apply (le_from_sq (sqrt (Cnorm_sq (z1 -c z2))) ((Cnorm z1) + (Cnorm z2))).
  - apply sqrt_pos'. apply Cnorm_sq_ge_0.
  - lra.
  - rewrite (sqrt_sq (Cnorm_sq (z1 -c z2)) (Cnorm_sq_ge_0 (z1 -c z2))).
    rewrite Hsub.
    replace (((Cnorm z1) + (Cnorm z2)) * ((Cnorm z1) + (Cnorm z2)))%R
      with (((Cnorm_sq z1) + (Cnorm_sq z2) + 2 * ((Cnorm z1) * (Cnorm z2))))%R
      by (rewrite <- Hs1; rewrite <- Hs2; ring).
    nra.
Qed.

(* ---------- 几何和恒等式 ---------- *)

Theorem geom_sum_identity (theta : R) (W : nat) :
  (C1 -c rot_atom theta W)
  = (C1 -c rot_atom theta 1) *c PrimeEmbedding.Csum (fun k => rot_atom theta k) W.
Proof.
  induction W as [| W IH].
  - simpl. rewrite rot_atom_zero Csub_diag Cmul_0_r. reflexivity.
  - assert (Hc : PrimeEmbedding.Csum (fun k => rot_atom theta k) (S W)
                 = Cadd (rot_atom theta W) (PrimeEmbedding.Csum (fun k => rot_atom theta k) W))
      by reflexivity.
    rewrite Hc. rewrite Cmul_add_distr_l. rewrite <- IH.
    rewrite Csub_distr (rot_step theta W).
    unfold Cadd, Csub. apply Complex_eq; simpl; ring.
Qed.

(* ---------- sin 下界（Jordan，半带情形） ---------- *)

Lemma INR_two : (INR 2)%R = 2%R.
Proof. simpl. ring. Qed.

Lemma sin_lower (N r : nat) :
  (1 <= r)%nat -> (2 * r <= N)%nat ->
  ((2 * INR r / INR N <= sin (PI * INR r / INR N))%R).
Proof.
  intros Hr H2r.
  assert (HNz : (0 < INR N)%R).
  { apply lt_0_INR.
    move: H2r => /leP H2rle.
    (* H2rle : ((2 * r)%coq_nat <= N)%coq_nat；由 Hr 得 0 < (2*r)%coq_nat *)
    apply (Nat.lt_le_trans 0 (2 * r)%coq_nat N).
    - (* 0 < (2 * r)%coq_nat：stdlib 记法，lia 可处理 *)
      move: Hr => /leP Hrle.
      lia.
    - exact H2rle. }
  assert (HPI : (0 < PI)%R) by apply PI_RGT_0.
  assert (Hx1 : (0 < PI * INR r / INR N)%R).
  { unfold Rdiv. apply Rmult_lt_0_compat.
    - apply Rmult_lt_0_compat; [exact HPI | apply lt_0_INR; move: Hr => /leP Hrle; lia].
    - apply Rinv_0_lt_compat. exact HNz. }
  assert (HIN : (INR (2 * r) <= INR N)%R) by (apply (le_INR (2 * r) N); move: H2r => /leP H2rle; lia).
  assert (Hx2 : (PI * INR r / INR N <= PI / 2)%R).
  { assert (HIN' : ((2 * INR r) <= INR N)%R)
      by (rewrite <- INR_two; rewrite <- (mult_INR 2 r); apply (le_INR (2 * r) N); move: H2r => /leP H2rle; lia).
    apply (Rmult_le_reg_r (INR N) (PI * INR r / INR N) (PI / 2) HNz).
    replace ((PI * INR r / INR N) * INR N)%R with (PI * INR r)%R by (field; lra).
    replace ((PI / 2) * INR N)%R with ((PI * INR N) / 2)%R by (field; lra).
    nra. }
  assert (Hj' : (((2 / PI) * (PI * INR r / INR N)) <= sin (PI * INR r / INR N))%R).
  { assert (H := jordan_standard (PI * INR r / INR N) (conj (Rlt_le _ _ Hx1) Hx2)). lra. }
  rewrite <- Hj'.
  replace ((2 / PI) * (PI * INR r / INR N))%R with ((2 * INR r / INR N))%R
    by (field; lra).
  apply Rle_refl.
Qed.


(* ---------- mod 归约 ---------- *)

Lemma grid_mod_reduce (N j k : nat) :
  (2 <= N)%nat ->
  (grid_atom N j k = grid_atom N (j mod N)%nat k).
Proof.
  intros HN.
  assert (HNz : (0 < INR N)%R).
  { apply lt_0_INR. move: HN => /leP HNle. lia. }
  (* 显式 Nat 函数（不依赖 * 记法解析，2.5/2.6 双环境稳，E150 续） *)
  assert (Hdj : j = Nat.add (Nat.mul N (Nat.div j N)) (Nat.modulo j N)) by (apply Nat.div_mod_eq).
  assert (Hjk : (Nat.mul j k = Nat.add (Nat.mul (Nat.mul (Nat.div j N) k) N) (Nat.mul (Nat.modulo j N) k)))
    by (rewrite {1}Hdj; lia).
  unfold grid_atom.
  assert (Hval : (2 * PI * INR (Nat.mul j k) / INR N)%R
    = ((2 * PI * INR (Nat.mul (Nat.modulo j N) k) / INR N)
       + 2 * PI * IZR (Z.of_nat (Nat.mul (Nat.div j N) k)))%R).
  { rewrite <- (INR_IZR_INZ (Nat.mul (Nat.div j N) k)). rewrite Hjk. rewrite plus_INR.
    rewrite (mult_INR (Nat.mul (Nat.div j N) k) N). rewrite (mult_INR (Nat.modulo j N) k).
    field. apply Rgt_not_eq. exact HNz. }
  rewrite Hval. apply Cexp_2pi_shift.
Qed.

(* ---------- 共轭对称 ---------- *)

Lemma grid_conj (N r k : nat) :
  (2 <= N)%nat -> (0 < r)%nat -> (r < N)%nat ->
  (grid_atom N (N - r) k = Cconj (grid_atom N r k)).
Proof.
  intros HN Hr HrN.
  assert (HNz : (0 < INR N)%R).
  { apply lt_0_INR. move: HN => /leP HNle. lia. }
  (* Hsub 保持 %nat 形态（muln），与主目标 grid_atom 展开的 muln 形态匹配（2.5/2.6 一致） *)
  assert (Hsub : ((N - r) * k = N * k - r * k)%nat) by (rewrite mulnBl; reflexivity).
  unfold grid_atom.
  rewrite Hsub.
  assert (Hval : (2 * PI * INR (N * k - r * k) / INR N)%R
    = ((-(2 * PI * INR (r * k) / INR N)) + 2 * PI * IZR (Z.of_nat k))%R).
  { rewrite <- (INR_IZR_INZ k).
    (* E114：minus_INR 前提（r*k ≤ N*k）显式 assert 并传参——避免自动前提子目标
       干扰后续 rewrite 焦点（2.6 下子目标顺序敏感，E150 续） *)
    assert (Hle : (r * k <= N * k)%coq_nat).
    { apply Nat.mul_le_mono_r. move: HrN => /ltP HrNp. lia. }
    rewrite (minus_INR (N * k) (r * k) Hle).
    (* muln → Nat.mul 桥（2.6 muln ≢ Nat.mul；主目标无前提子目标干扰） *)
    rewrite mulnE.
    rewrite (mult_INR N k). rewrite (mult_INR r k).
    field. apply Rgt_not_eq; exact HNz. }
  rewrite Hval (Cconj_Cexp (2 * PI * INR (r * k) / INR N)).
  apply Cexp_2pi_shift.
Qed.

(* ---------- 主界（半带情形） ---------- *)

Theorem partial_bound_half (N r W : nat) :
  (2 <= N)%nat -> (1 <= r)%nat -> (2 * r <= N)%nat ->
  ((Cnorm (PrimeEmbedding.Csum (fun k => grid_atom N r k) W) <= INR N / (2 * INR r))%R).
Proof.
  intros HN Hr H2r.
  assert (HNz : (0 < INR N)%R).
  { apply lt_0_INR. move: HN => /leP HNle. lia. }
  assert (Hrz : (0 < INR r)%R).
  { apply lt_0_INR. move: Hr => /leP Hrle. lia. }
  assert (Hconv : PrimeEmbedding.Csum (fun k => grid_atom N r k) W
                  = PrimeEmbedding.Csum (fun k => rot_atom (2 * PI * INR r / INR N) k) W).
  { apply Csum_ext. intros k Hk. symmetry. apply rot_grid. exact HN. }
  rewrite Hconv.
  set (theta := ((2 * PI * INR r / INR N))%R).
  assert (Hid := geom_sum_identity theta W).
  assert (Hnorm : (Cnorm (C1 -c rot_atom theta W))%R
                  = ((Cnorm (C1 -c rot_atom theta 1))
                     * (Cnorm (PrimeEmbedding.Csum (fun k => rot_atom theta k) W)))%R).
  { rewrite {1}Hid. rewrite Cnorm_mult'. reflexivity. }
  assert (Hub : (Cnorm (C1 -c rot_atom theta W) <= 2)%R).
  { apply (Rle_trans _ ((Cnorm C1) + (Cnorm (rot_atom theta W)))%R).
    - apply Cnorm_sub_le.
    - rewrite Cnorm_one' (rot_Cnorm theta W). lra. }
  assert (Hlb : ((4 * INR r / INR N <= Cnorm (C1 -c rot_atom theta 1))%R)).
  { rewrite rot_atom_one (Cnorm_one_minus_exp_i_theta_eq theta).
    assert (Hhalf : ((theta / 2))%R = ((PI * INR r / INR N))%R)
      by (unfold theta; field; lra).
    rewrite Hhalf.
    assert (Hsinpos : (0 <= sin (PI * INR r / INR N))%R).
    { assert (Hsl := sin_lower N r Hr H2r).
      assert (Hpos2 : (0 < 2 * INR r / INR N)%R).
      { unfold Rdiv. apply Rmult_lt_0_compat.
        - lra.
        - apply Rinv_0_lt_compat. exact HNz. }
      nra. }
    assert (Hge : (2 * sin (PI * INR r / INR N) <= 2 * Rabs (sin (PI * INR r / INR N)))%R).
    { apply Rmult_le_compat_l; [lra | ].
      destruct (Rle_or_lt 0 (sin (PI * INR r / INR N))) as [Hs | Hs].
      - rewrite (Rabs_right _ (Rle_ge 0 (sin (PI * INR r / INR N)) Hs)). apply Rle_refl.
      - rewrite (Rabs_left _ Hs). lra. }
    assert (Hsl := sin_lower N r Hr H2r).
    replace ((4 * INR r / INR N))%R with ((2 * (2 * INR r / INR N)))%R by (field; lra).
    nra. }
  apply (Rmult_le_reg_l (2 * INR r)); [nra | ].
  replace ((2 * INR r) * (INR N / (2 * INR r)))%R with (INR N)%R
    by (field; lra).
  set (XX := (Cnorm (PrimeEmbedding.Csum (fun k => rot_atom theta k) W))%R) in *.
  assert (HX : (0 <= XX)%R)
    by (unfold XX, Cnorm; apply sqrt_pos'; apply Cnorm_sq_ge_0).
  assert (H1 : ((4 * INR r / INR N) * XX <= Cnorm (C1 -c rot_atom theta 1) * XX)%R)
    by (apply Rmult_le_compat_r; [exact HX | exact Hlb]).
  rewrite <- Hnorm in H1.
  assert (H2 : ((4 * INR r / INR N) * XX <= 2)%R)
    by (apply (Rle_trans _ (Cnorm (C1 -c rot_atom theta W))); [exact H1 | exact Hub]).
  assert (H3 : ((4 * INR r) * XX <= 2 * INR N)%R).
  { replace ((4 * INR r) * XX)%R with ((4 * INR r / INR N) * XX * INR N)%R
      by (field; lra).
    apply Rmult_le_compat_r; [apply Rlt_le; exact HNz | exact H2]. }
  assert (Hr4 : ((4 * INR r) * XX)%R = (2 * ((2 * INR r) * XX))%R) by ring.
  nra.
Qed.

(* ---------- 主定理 ---------- *)

Theorem dirichlet_partial_bound (N j W : nat) :
  (2 <= N)%nat -> (j mod N <> 0)%nat ->
  ((Cnorm (PrimeEmbedding.Csum (fun k => grid_atom N j k) W)
    <= INR N / (2 * INR (Nat.min (j mod N) ((N - j mod N)%coq_nat))))%R).
Proof.
  intros HN Hneq.
  assert (Hr0 : (0 < j mod N)%nat).
  { destruct (j mod N) as [| r']; [exfalso; apply Hneq; reflexivity | exact (ltn0Sn r')]. }
  assert (HrN : (j mod N < N)%nat).
  { apply/ltP. apply Nat.mod_upper_bound. move: HN => /leP HNle. lia. }
  assert (Hconv : PrimeEmbedding.Csum (fun k => grid_atom N j k) W
                  = PrimeEmbedding.Csum (fun k => grid_atom N (j mod N) k) W).
  { apply Csum_ext. intros k Hk. apply grid_mod_reduce. exact HN. }
  rewrite Hconv.
  (* 目标含 Nat.min（stdlib），Hle/Hgt 由 leqP 给 bool——用 leP 反映 *)
  case: (leqP (j mod N) (N - j mod N)) => [Hle | Hgt].
  - have HleP : ((j mod N) <= (N - j mod N))%coq_nat.
    { apply/leP. exact Hle. }
    rewrite (Nat.min_l _ _ HleP).
    have Hle2 : (2 * (j mod N) <= N)%nat.
    { rewrite mul2n.
      have Hle3 : (j mod N) + (j mod N) <= (j mod N) + (N - j mod N)
        by rewrite (addnC (j mod N) (N - j mod N)); exact (leq_add Hle (leqnn (j mod N))).
      have Hsub : (j mod N) <= N by exact (leq_trans Hle (leq_subr (j mod N) N)).
      rewrite (subnKC Hsub) in Hle3. rewrite addnn in Hle3. exact Hle3. }
    apply partial_bound_half; [exact HN | exact Hr0 | exact Hle2].
  - have HgeP : ((N - j mod N) <= (j mod N))%coq_nat.
    { apply/leP. exact (ltnW Hgt). }
    rewrite (Nat.min_r _ _ HgeP).
    assert (Hcs : (Cnorm (PrimeEmbedding.Csum (fun k => grid_atom N (j mod N) k) W))%R
                  = (Cnorm (PrimeEmbedding.Csum (fun k => grid_atom N (N - j mod N) k) W))%R).
    { rewrite <- (Cnorm_conj (PrimeEmbedding.Csum (fun k => grid_atom N (j mod N) k) W)).
      rewrite <- Csum_conj.
      f_equal.
      apply Csum_ext. intros k Hk. symmetry.
      apply grid_conj; [exact HN | exact Hr0 | exact HrN]. }
    rewrite Hcs.
    have Hd2 : (2 * (N - j mod N) <= N)%nat.
    { rewrite mul2n.
      have Hn : (N - j mod N) + (N - j mod N) <= (j mod N) + (N - j mod N)
        by exact (leq_add (ltnW Hgt) (leqnn (N - j mod N))).
      rewrite (subnKC (m := j mod N) (n := N) (ltnW HrN)) in Hn. rewrite addnn in Hn. exact Hn. }
    apply partial_bound_half; [exact HN | rewrite subn_gt0; exact HrN | exact Hd2].
Qed.

End TPartial.

(* ---------- 构造性审计 ---------- *)

Print Assumptions TPartial.geom_sum_identity.
Print Assumptions TPartial.partial_bound_half.
Print Assumptions TPartial.dirichlet_partial_bound.

(* ==================== 模块 39/67: probe_pairbound ==================== *)

Close Scope Z_scope.
Open Scope R_scope.
Open Scope complex_scope.
Open Scope nat_scope.
(* ============================================================
   ρ^{−3/2} 紧界改进 ①：逐对内积界引擎（probe_pairbound）
     |⟨ψ_a,ψ_b⟩| = sin(πa/b)/(√(ab)·sin(π(b−a)/(ab)))
   ——固定比率 ρ=b/a 时真实值 Θ(ρ^{−3/2})，上确界在 a=2。
   本文件证 Jordan 版上界：|⟨ψ_a,ψ_b⟩| ≤ sin(πa/b)·√(ab)/(2(b−a))，
   与见证 (2,2C) 之比随 C→∞ → 1（数值 1.23@C=4 → 1.01@C=100）。

   PB0 Cnorm_ge0 / sqrt_pos_strict：非负性基础件。
   PB1 geom_sum_norm_prod：|1−ω^W| = |1−ω|·|Σ rot^k|（复用 probe_partial
       的 geom_sum_identity + Cnorm_mult'）。
   PB2 sin_PI_minus'：sin(π−x) = sin x（sin_add + sin_PI + cos_PI + sin_neg）。
   PB3 pair_S_bound（引擎主定理）：|Σ_{k<a} e^{i·k·θ}| ≤
       sin(πa/b)·(ab)/(2(b−a))，θ = 2π(b−a)/(ab)——
       分子 |1−ω^a| = 2sin(πa/b)（PB2 周期化 + sin_ge_0），
       分母 |1−ω| ≥ 4(b−a)/(ab)（sin_lower Jordan 半带）。
   PB4 pair_inner_norm（归一化系）：|⟨ψ_a,ψ_b⟩| ≤ sin(πa/b)·√(ab)/(2(b−a))
       ——纯 R 层除法。
   审计：Print Assumptions 尾部。
   ============================================================ *)
From mathcomp Require Import ssreflect ssrbool ssrnat seq eqtype div prime.
Require Import Stdlib.Reals.Reals.
Require Import Stdlib.Arith.Arith.
Require Import Stdlib.micromega.Lia.
Require Import Stdlib.micromega.Lra.
Require Import Stdlib.ZArith.ZArith.
Import ComplexNumbers.
Import FourierAnalysis.
Import GridOrtho.
Import TPartial.

Open Scope R_scope.
Open Scope complex_scope.
Open Scope nat_scope.

Module PairBound.

(* ---------- PB0：非负性基础件 ---------- *)

Lemma sqrt_pos_strict (x : R) : (0 < x)%R -> (0 < sqrt x)%R.
Proof.
  intros Hx.
  assert (Hp : (0 <= sqrt x)%R) by (apply sqrt_pos'; apply Rlt_le; exact Hx).
  destruct (Rle_lt_dec (sqrt x) 0) as [Hle | Hgt]; [ | exact Hgt ].
  exfalso.
  assert (Hs : (sqrt x * sqrt x = x)%R) by (apply sqrt_sqrt; apply Rlt_le; exact Hx).
  assert (Hz : (sqrt x = 0)%R) by lra.
  rewrite Hz Rmult_0_l in Hs. lra.
Qed.

Lemma Cnorm_ge0 (z : Complex) : (0 <= Cnorm z)%R.
Proof. unfold Cnorm. apply sqrt_pos'. apply Cnorm_sq_ge_0. Qed.

(* ---------- PB1：几何和的范数乘法形式 ---------- *)

Lemma geom_sum_norm_prod (theta : R) (W : nat) :
  (Cnorm (C1 -c rot_atom theta W)
   = Cnorm (C1 -c rot_atom theta 1)
     * Cnorm (PrimeEmbedding.Csum (fun k => rot_atom theta k) W))%R.
Proof.
  pose proof (geom_sum_identity theta W) as E.
  rewrite E. apply Cnorm_mult'.
Qed.

(* ---------- PB2：sin(π−x) = sin x ---------- *)

Lemma sin_PI_minus' (x : R) : (sin (PI - x))%R = sin x.
Proof.
  replace (PI - x)%R with (PI + (-x))%R by ring.
  rewrite sin_plus sin_PI cos_PI sin_neg. ring.
Qed.

(* ---------- PB3：引擎主定理 ---------- *)

Theorem pair_S_bound (a b : nat) :
  (2 <= a)%nat -> (a < b)%nat ->
  (Cnorm (PrimeEmbedding.Csum
            (fun k => rot_atom (2 * PI * (INR b - INR a) / (INR a * INR b)) k) a)
   <= sin (PI * INR a / INR b) * (INR a * INR b) / (2 * (INR b - INR a)))%R.
Proof.
  intros Ha Hab.
  assert (HA : (0 < INR a)%R).
  { apply lt_0_INR. move: Ha => /leP Hap. lia. }
  assert (HB : (0 < INR b)%R).
  { apply lt_0_INR. move: Ha => /leP Hap. move: Hab => /ltP Habp. lia. }
  assert (HAB : (INR a < INR b)%R).
  { apply lt_INR. move: Ha => /leP Hap. move: Hab => /ltP Habp. lia. }
  assert (HBinv : (0 < / INR b)%R) by (apply Rinv_0_lt_compat; exact HB).
  assert (HIsub : (INR (b - a) = INR b - INR a)%R).
  { assert (Hs : (INR (b - a) + INR a = INR b)%R).
    { rewrite <- plus_INR. f_equal. exact (subnK (ltnW Hab)). }
    lra. }
  set (theta := (2 * PI * (INR b - INR a) / (INR a * INR b))%R) in *.
  pose proof (geom_sum_norm_prod theta a) as P.
  (* 分子：|1 − ω^a| = 2·sin(πa/b) *)
  assert (Naraw : (Cnorm (C1 -c rot_atom theta a)
                 = 2 * Rabs (sin (INR a * theta / 2)))%R).
  { rewrite <- (Cnorm_one_minus_exp_i_theta_eq (INR a * theta)). reflexivity. }
  assert (Hcalc : (INR a * theta / 2 = PI - PI * INR a / INR b)%R).
  { unfold theta. field; lra. }
  rewrite Hcalc sin_PI_minus' in Naraw.
  assert (Hsinpos : (0 <= sin (PI * INR a / INR b))%R).
  { apply sin_ge_0.
    - unfold Rdiv. apply Rmult_le_pos.
      + apply Rmult_le_pos; [apply Rlt_le; apply PI_RGT_0 | exact (Rlt_le 0 (INR a) HA)].
      + apply Rlt_le; exact HBinv.
    - apply (Rmult_le_reg_r (INR b) (PI * INR a / INR b) PI HB).
      replace (PI * INR a / INR b * INR b)%R with (PI * INR a)%R by (field; lra).
      assert (HP : (0 < PI)%R) by apply PI_RGT_0.
      nra. }
  rewrite (Rabs_right _ (Rle_ge _ _ Hsinpos)) in Naraw.
  (* 分母：|1 − ω| = 2·sin(θ/2) ≥ 2·(2(b−a)/(ab))（Jordan） *)
  assert (Nbraw : (Cnorm (C1 -c rot_atom theta 1)
                 = 2 * Rabs (sin (theta / 2)))%R).
  { rewrite <- (Cnorm_one_minus_exp_i_theta_eq theta).
    change (rot_atom theta 1) with (Cexp (0 +i (INR 1 * theta))).
    rewrite INR_1. repeat f_equal. ring. }
  assert (Hthalf : (theta / 2 = PI * INR (b - a) / INR (a * b))%R).
  { unfold theta. rewrite <- HIsub. rewrite mult_INR. field; lra. }
  assert (Hjor : ((2 * INR (b - a)) / INR (a * b) <= sin (theta / 2))%R).
  { rewrite Hthalf. apply sin_lower.
    - rewrite subn_gt0. exact Hab.
    - have H1 : (2 * (b - a) <= 2 * b)%nat
        by rewrite (@leq_pmul2l 2 (b - a) b (ltn0Sn 1)); exact (leq_subr a b).
      have H2 : (2 * b <= a * b)%nat.
      { rewrite (@leq_pmul2r b 2 a (ltnW (ltn_trans Ha Hab))). exact Ha. }
      exact (leq_trans H1 H2). }
  assert (HabInv : (0 < / INR (a * b))%R).
  { apply Rinv_0_lt_compat. apply lt_0_INR.
    apply Nat.mul_pos_pos.
    - apply/ltP. exact (ltnW Ha).
    - apply/ltP. exact (ltnW (ltn_trans Ha Hab)). }
  assert (Hab2 : (0 < INR (a * b))%R).
  { apply lt_0_INR. apply Nat.mul_pos_pos.
    - apply/ltP. exact (ltnW Ha).
    - apply/ltP. exact (ltnW (ltn_trans Ha Hab)). }
  assert (Hsinpos2 : (0 <= sin (theta / 2))%R).
  { rewrite Hthalf. apply sin_ge_0.
    - unfold Rdiv. apply Rmult_le_pos.
      + apply Rmult_le_pos; [apply Rlt_le; apply PI_RGT_0 | apply (Rlt_le 0 (INR (b - a))); apply lt_0_INR; apply/ltP; rewrite subn_gt0; exact Hab].
      + apply Rlt_le; exact HabInv.
    - apply (Rmult_le_reg_r (INR (a * b)) (PI * INR (b - a) / INR (a * b)) PI Hab2).
      replace (PI * INR (b - a) / INR (a * b) * INR (a * b))%R
        with (PI * INR (b - a))%R by (field; lra).
      assert (HP : (0 < PI)%R) by apply PI_RGT_0.
      assert (Hkey : (INR (b - a) <= INR (a * b))%R).
      { apply le_INR. apply/leP. apply (leq_trans (leq_subr a b)).
        rewrite -[b in b <= _]mul1n. rewrite (@leq_pmul2r b 1 a (ltnW (ltn_trans Ha Hab))). exact (ltnW Ha). }
      nra. }
  rewrite (Rabs_right _ (Rle_ge _ _ Hsinpos2)) in Nbraw.
  rewrite Naraw in P. rewrite Nbraw in P.
  set (d0 := (2 * (2 * INR (b - a) / INR (a * b)))%R) in *.
  assert (Hd0 : (0 < d0)%R).
  { unfold d0, Rdiv.
    apply Rmult_lt_0_compat; [ lra | ].
    apply Rmult_lt_0_compat; [ apply (Rmult_lt_0_compat 2 (INR (b - a))); [ lra | apply lt_0_INR; apply/ltP; rewrite subn_gt0; exact Hab ] | apply Rinv_0_lt_compat; apply lt_0_INR; apply/ltP; rewrite muln_gt0; apply/andP; split; [exact (ltnW Ha) | exact (ltnW (ltn_trans Ha Hab))] ]. }
  assert (Hd0le : (d0 <= 2 * sin (theta / 2))%R)
    by (unfold d0; apply Rmult_le_compat_l; [ lra | exact Hjor ]).
  assert (Hstep : (Cnorm (PrimeEmbedding.Csum (fun k => rot_atom theta k) a) * d0
                   <= 2 * sin (PI * INR a / INR b))%R).
  { apply (Rle_trans _
             (2 * sin (theta / 2)
              * Cnorm (PrimeEmbedding.Csum (fun k => rot_atom theta k) a))).
    - replace (Cnorm (PrimeEmbedding.Csum (fun k => rot_atom theta k) a) * d0)%R
        with (d0 * Cnorm (PrimeEmbedding.Csum (fun k => rot_atom theta k) a))%R
        by ring.
      apply Rmult_le_compat_r; [ apply Cnorm_ge0 | exact Hd0le ].
    - rewrite <- P. apply Rle_refl. }
  apply (Rmult_le_reg_r d0 _ _ Hd0).
  replace (sin (PI * INR a / INR b) * (INR a * INR b) / (2 * (INR b - INR a)) * d0)%R
    with (2 * sin (PI * INR a / INR b))%R
    by (unfold d0, Rdiv; rewrite HIsub mult_INR; field; lra).
  exact Hstep.
Qed.

(* ---------- PB4：归一化系（|⟨ψ_a,ψ_b⟩| 界） ---------- *)

Corollary pair_inner_norm (a b : nat) :
  (2 <= a)%nat -> (a < b)%nat ->
  ((Cnorm (PrimeEmbedding.Csum
             (fun k => rot_atom (2 * PI * (INR b - INR a) / (INR a * INR b)) k) a)
    / sqrt (INR a * INR b))
   <= sin (PI * INR a / INR b) * sqrt (INR a * INR b) / (2 * (INR b - INR a)))%R.
Proof.
  intros Ha Hab.
  assert (H := pair_S_bound a b Ha Hab).
  assert (HIs : (INR (b - a) = INR b - INR a)%R).
  { assert (Hs : (INR (b - a) + INR a = INR b)%R)
      by (rewrite <- plus_INR; f_equal; exact (subnK (ltnW Hab))).
    lra. }
  assert (HBA : (0 < INR b - INR a)%R)
    by (rewrite <- HIs; apply lt_0_INR; apply/ltP; rewrite subn_gt0; exact Hab).
  assert (Hab1 : (0 < INR a)%R)
    by (apply lt_0_INR; move: Ha => /leP Hap; lia).
  assert (Hbb1 : (0 < INR b)%R)
    by (apply lt_0_INR; move: Ha => /leP Hap; move: Hab => /ltP Habp; lia).
  assert (Hsq : (0 < sqrt (INR a * INR b))%R).
  { apply sqrt_pos_strict. nra. }
  assert (Hss : (sqrt (INR a * INR b) * sqrt (INR a * INR b) = INR a * INR b)%R)
    by (apply sqrt_sqrt; nra).
  apply (Rmult_le_reg_r (sqrt (INR a * INR b)) _ _ Hsq).
  replace (Cnorm (PrimeEmbedding.Csum
                    (fun k => rot_atom (2 * PI * (INR b - INR a) / (INR a * INR b)) k) a)
             / sqrt (INR a * INR b) * sqrt (INR a * INR b))%R
    with (Cnorm (PrimeEmbedding.Csum
                    (fun k => rot_atom (2 * PI * (INR b - INR a) / (INR a * INR b)) k) a))%R
    by (unfold Rdiv; field; lra).
  assert (E2 : (sin (PI * INR a / INR b) * sqrt (INR a * INR b)
                  / (2 * (INR b - INR a)) * sqrt (INR a * INR b)
                  = sin (PI * INR a / INR b) * (INR a * INR b) / (2 * (INR b - INR a)))%R).
  { transitivity (sin (PI * INR a / INR b) * (sqrt (INR a * INR b) * sqrt (INR a * INR b))
                    / (2 * (INR b - INR a)))%R.
    - field. lra.
    - rewrite Hss. field. lra. }
  rewrite E2. exact H.
Qed.

End PairBound.

Print Assumptions PairBound.pair_S_bound.
Print Assumptions PairBound.pair_inner_norm.

(* ==================== 模块 40/67: probe_rowsum ==================== *)

Close Scope Z_scope.
Open Scope R_scope.
Open Scope complex_scope.
Open Scope nat_scope.
(* ============================================================
   定理：C-稀疏梯子（逐对比率 ≥ C ≥ 2）的任意行
     Σ_{j≠i} |⟨ψ_{v_i}, ψ_{v_j}⟩| ≤ 2π·q/(1−q)，q = C^{−3/2} < 1/2
   ——C=4 时 ≤ 2π/7 ≈ 0.898 < 1：**1D 无条件基定理在 C=4 从
   空洞（2K(4)=2 > 1，仅存在性）变为真实框架界**。
   证明：PB4 逐对界 + sin ≤ x（sin_bound n=0 上界）+ Jordan 分母
   ⟹ 逐对 ≤ π·(a√a)/(b√b) ≤ π·C^{−3d/2}（d=索引距离，链式比率累积）
   ⟹ 两侧几何级数求和。

   RS0 lsum 求和 + lsum_le + geo_exact/geo_bound（几何级数闭式）。
   RS1 sin_le_x：0 ≤ x ≤ π/2 ⟹ sin x ≤ x（sin_bound 交替级数）。
   RS2 pair_le_crude：PB4 + RS1 + b ≥ 2a ⟹ 逐对 ≤ π·(a√a)/(b√b)。
   RS3 chain_pow：v(i+k) ≥ C^k·v i（nat 归纳）。
   RS4 oneside：单侧行和 ≤ πq/(1−q)（归纳 + 几何级数）。
   RS5 row_sum_3halfs（主定理）：两侧 ⟹ ≤ 2πq/(1−q)。
   审计：Print Assumptions 尾部。
   ============================================================ *)
From mathcomp Require Import ssreflect ssrbool ssrnat seq eqtype div prime.
Require Import Stdlib.Reals.Reals.
Require Import Stdlib.Arith.Arith.
Require Import Stdlib.micromega.Lia.
Require Import Stdlib.micromega.Lra.
Require Import Stdlib.ZArith.ZArith.
Import ComplexNumbers.
Import FourierAnalysis.
Import GridOrtho.
Import TPartial.
Import PairBound.

Open Scope R_scope.
Open Scope complex_scope.
Open Scope nat_scope.

Module RowSum.

(* ---------- RS0：求和与几何级数 ---------- *)

Fixpoint lsum (f : nat -> R) (m : nat) : R :=
  match m with
  | O => 0%R
  | S m' => (lsum f m' + f m')%R
  end.

Lemma lsum_le (f g : nat -> R) (m : nat) :
  (forall k, (k < m)%nat -> (f k <= g k)%R) -> (lsum f m <= lsum g m)%R.
Proof.
  intros H. induction m as [| m IH]; simpl.
  - apply Rle_refl.
  - apply Rplus_le_compat; [apply IH; intros k Hk; apply H; exact (ltn_trans Hk (ltnSn m)) | apply H; exact (ltnSn m)].
Qed.

Lemma pow_S (x : R) (n : nat) : (x ^ (S n))%R = (x * x ^ n)%R.
Proof. intros. simpl. ring. Qed.

Lemma pow_nonneg (x : R) (n : nat) : (0 <= x)%R -> (0 <= x ^ n)%R.
Proof.
  intros Hx. induction n as [| n IH].
  - simpl. lra.
  - rewrite pow_S. apply Rmult_le_pos; [ lra | exact IH ].
Qed.

Lemma geo_exact (x : R) (m : nat) :
  ((1 - x) * lsum (fun k => x ^ (S k)) m = x * (1 - x ^ m))%R.
Proof.
  induction m as [| m IH]; cbn [lsum].
  - ring.
  - replace ((1 - x) * (lsum (fun k => x ^ S k) m + x ^ S m))%R
      with ((1 - x) * lsum (fun k => x ^ S k) m + (1 - x) * x ^ S m)%R
      by ring.
    rewrite IH.
    rewrite !pow_S.
    ring.
Qed.

Lemma geo_bound (x : R) (m : nat) :
  (0 < x < 1)%R -> (lsum (fun k => x ^ (S k)) m <= x / (1 - x))%R.
Proof.
  intros [Hx1 Hx2].
  assert (Hpos : (0 < 1 - x)%R) by lra.
  apply (Rmult_le_reg_r (1 - x) _ _ Hpos).
  replace (lsum (fun k => x ^ S k) m * (1 - x))%R with ((1 - x) * lsum (fun k => x ^ S k) m)%R by ring.
  rewrite geo_exact.
  replace (x / (1 - x) * (1 - x))%R with x%R by (field; lra).
  replace (x * (1 - x ^ m))%R with (x - x * x ^ m)%R by ring.
  assert (Hple : (x ^ m <= 1)%R).
  { induction m as [| m IHm].
    - simpl. apply Rle_refl.
    - rewrite pow_S.
      apply (Rle_trans _ (x * 1)%R).
      + apply Rmult_le_compat_l; [apply Rlt_le; lra | exact IHm].
      + rewrite Rmult_1_r. lra. }
  assert (Hnn : (0 <= x ^ m)%R) by (apply pow_nonneg; lra).
  assert (Hxt : (0 <= x * x ^ m)%R) by (apply Rmult_le_pos; [ lra | exact Hnn ]).
  lra.
Qed.

(* ---------- RS1：sin x ≤ x on [0, π/2] ---------- *)

Lemma sin_le_x (x : R) : (0 <= x <= PI / 2)%R -> (sin x <= x)%R.
Proof.
  intros [H1 H2].
  assert (Hx2 : (x <= 7 / 4)%R).
  { apply (Rle_trans _ (PI / 2)); [ exact H2 | ].
    replace (PI / 2)%R with PI2 by (unfold PI; field).
    apply (proj2 pi2_int). }
  assert (HPI : (7 / 4 <= PI)%R).
  { unfold PI. apply (Rle_trans _ (2 * (7 / 8))).
    - lra.
    - apply Rmult_le_compat_l; [ lra | apply (proj1 pi2_int) ]. }
  assert (Hsq : (x * x <= 20)%R).
  { apply (Rle_trans _ ((7 / 4) * (7 / 4))).
    - apply Rmult_le_compat; [ lra | lra | exact Hx2 | exact Hx2 ].
    - lra. }
  assert (Hxp : (x <= PI)%R) by lra.
  assert (Hb := sin_bound x 0%nat H1 Hxp).
  apply (Rle_trans _ (sin_approx x 2)); [ exact (proj2 Hb) | ].
  replace (sin_approx x 2)%R
    with (x + (x * x * x * (x * x)) / 120 - (x * x * x) / 6)%R
    by (unfold sin_approx, sin_term; simpl; field; lra).
  assert (Hc : (0 <= x * x * x)%R)
    by (apply (Rmult_le_pos (x * x) x); [ apply (Rmult_le_pos x x); lra | lra ]).
  assert (Hkey : (x * x * x * (x * x) <= x * x * x * 20)%R)
    by (apply Rmult_le_compat_l; [ exact Hc | exact Hsq ]).
  nra.
Qed.

(* ---------- RS2：逐对 crude 界 π·(a√a)/(b√b) ---------- *)

Definition Fpair (a b : nat) : R :=
  Cnorm (PrimeEmbedding.Csum
           (fun k => rot_atom ((2 * PI * (INR b - INR a) / (INR a * INR b))%R) k) a)
  / sqrt (INR a * INR b).

Lemma pair_le_crude (a b : nat) :
  (2 <= a)%nat -> (2 * a <= b)%nat ->
  (Fpair a b <= PI * (INR a * sqrt (INR a)) / (INR b * sqrt (INR b)))%R.
Proof.
  intros Ha Hb.
  assert (Hab : (a < b)%nat).
  { apply/ltP. apply (Nat.lt_le_trans _ (2 * a) _).
    - apply/ltP. rewrite -[a in a < _]mul1n. rewrite (@ltn_pmul2r a 1 2 (ltnW Ha)). exact (ltn0Sn 1).
    - apply/leP. exact Hb. }
  pose proof (pair_inner_norm a b Ha Hab) as H.
  assert (HA : (0 < INR a)%R).
  { apply lt_0_INR. case: (@ltP 0 a) => [Hp | Hn].
    - exact Hp.
    - exfalso. apply Hn. move: (ltnW Ha) => /ltP. exact. }
  assert (HB : (0 < INR b)%R).
  { apply lt_0_INR. case: (@ltP 0 b) => [Hp | Hn].
    - exact Hp.
    - exfalso. apply Hn. move: (ltnW (ltn_trans Ha Hab)) => /ltP. exact. }
  assert (HIs : (INR (b - a) = INR b - INR a)%R).
  { assert (Hs : (INR (b - a) + INR a = INR b)%R)
      by (rewrite <- plus_INR; f_equal; exact (subnK (ltnW Hab))).
    lra. }
  assert (Hba : (0 < INR (b - a))%R) by (apply lt_0_INR; apply/ltP; rewrite subn_gt0; exact Hab).
  assert (Hsin : (sin (PI * INR a / INR b) <= PI * INR a / INR b)%R).
  { apply sin_le_x. split.
    - unfold Rdiv. apply Rmult_le_pos.
      + apply Rmult_le_pos; [apply Rlt_le; apply PI_RGT_0 | apply Rlt_le; exact HA].
      + apply Rlt_le; apply Rinv_0_lt_compat; exact HB.
    - replace (PI * INR a / INR b)%R with (PI * (INR a / INR b))%R by (field; lra).
      apply Rmult_le_compat_l; [apply Rlt_le; apply PI_RGT_0 | ].
      apply (Rle_trans _ (1 / 2)); [ | lra ].
      apply (Rmult_le_reg_r (2 * INR b)); [ nra | ].
      replace (INR a / INR b * (2 * INR b))%R with (2 * INR a)%R by (field; lra).
      replace ((2 * INR a))%R with (INR (2 * a))%R by (rewrite mult_INR; simpl; ring).
      apply (Rle_trans _ (INR b)); [apply le_INR; apply/leP; exact Hb | ].
      replace ((1 / 2 * (2 * INR b)))%R with (INR b)%R by (field; lra).
      apply Rle_refl. }
  unfold Fpair.
  apply (Rle_trans _
      ((PI * INR a / INR b) * sqrt (INR a * INR b) / (2 * (INR b - INR a)))).
  - apply (Rle_trans _
      (sin (PI * INR a / INR b) * sqrt (INR a * INR b) / (2 * (INR b - INR a)))).
    + exact H.
    + unfold Rdiv.
      assert (HK : (sin (PI * INR a / INR b) * sqrt (INR a * INR b)
                     * / (2 * (INR b - INR a))
                     <= (PI * INR a / INR b) * sqrt (INR a * INR b)
                        * / (2 * (INR b - INR a)))%R).
      { apply (Rmult_le_compat_r (/ (2 * (INR b - INR a))%R)
                (sin (PI * INR a / INR b) * sqrt (INR a * INR b))
                ((PI * INR a / INR b) * sqrt (INR a * INR b))).
        - apply Rlt_le. apply Rinv_0_lt_compat. rewrite <- HIs.
          apply Rmult_lt_0_compat; [ lra | exact Hba ].
        - apply (Rmult_le_compat_r (sqrt (INR a * INR b))).
          + apply sqrt_pos'.
            apply Rmult_le_pos; [ apply Rlt_le; exact HA | apply Rlt_le; exact HB ].
          + exact Hsin. }
      lra.
  - apply (Rle_trans _ ((PI * INR a / INR b) * sqrt (INR a * INR b) / (INR b))).
    + assert (HAge : (0 <= (PI * INR a / INR b) * sqrt (INR a * INR b))%R).
      { apply Rmult_le_pos.
        - unfold Rdiv. apply Rmult_le_pos.
          + apply Rmult_le_pos.
            * apply Rlt_le; apply PI_RGT_0.
            * apply Rlt_le; exact HA.
          + apply Rlt_le; apply Rinv_0_lt_compat; exact HB.
        - apply sqrt_pos'. apply Rmult_le_pos; [ apply Rlt_le; exact HA | apply Rlt_le; exact HB ]. }
      apply (Rmult_le_reg_r ((2 * (INR b - INR a)) * INR b)).
      * rewrite <- HIs. nra.
      * replace ((PI * INR a / INR b * sqrt (INR a * INR b) / (2 * (INR b - INR a)))
                  * ((2 * (INR b - INR a)) * INR b))%R
          with ((PI * INR a / INR b * sqrt (INR a * INR b)) * INR b)%R
          by (field; nra).
        replace ((PI * INR a / INR b * sqrt (INR a * INR b) / (INR b))
                  * ((2 * (INR b - INR a)) * INR b))%R
          with ((PI * INR a / INR b * sqrt (INR a * INR b)) * (2 * (INR b - INR a)))%R
          by (field; nra).
        assert (H2D : (INR b <= 2 * INR (b - a))%R).
        { assert (HbR : (2 * INR a <= INR b)%R).
          { replace (2 * INR a)%R with (INR (2 * a))%R by (rewrite mult_INR; reflexivity).
            apply le_INR. case: (@leP (2 * a) b) => [Hbp | Hnot].
            - exact Hbp.
            - exfalso. apply Hnot. apply/leP. exact Hb. }
          rewrite HIs. nra. }
        apply Rmult_le_compat_l; [ exact HAge | rewrite <- HIs; exact H2D ].
    + rewrite (sqrt_mult (INR a) (INR b) (Rlt_le _ _ HA) (Rlt_le _ _ HB)).
      assert (Hsa : (sqrt (INR a) * sqrt (INR a) = INR a)%R)
        by (apply sqrt_sqrt; apply Rlt_le; exact HA).
      assert (Hsb : (sqrt (INR b) * sqrt (INR b) = INR b)%R)
        by (apply sqrt_sqrt; apply Rlt_le; exact HB).
      assert (Hpb : (0 < sqrt (INR b))%R).
        { apply sqrt_pos_strict. exact HB. }
      apply Req_le.
      apply (Rmult_eq_reg_r (INR b * INR b * sqrt (INR b))).
      * unfold Rdiv in *.
        replace (PI * INR a * Rinv (INR b) * (sqrt (INR a) * sqrt (INR b))
                 * Rinv (INR b) * (INR b * INR b * sqrt (INR b)))%R
          with ((PI * INR a * sqrt (INR a) * (sqrt (INR b) * sqrt (INR b)))
                * (Rinv (INR b) * INR b) * (Rinv (INR b) * INR b))%R
          by ring.
        replace (PI * (INR a * sqrt (INR a)) * Rinv (INR b * sqrt (INR b))
                 * (INR b * INR b * sqrt (INR b)))%R
          with ((PI * INR a * sqrt (INR a) * INR b)
                * (Rinv (INR b * sqrt (INR b)) * (INR b * sqrt (INR b))))%R
          by ring.
        rewrite (Rmult_inv_l (INR b) ltac:(lra)).
        rewrite Rmult_1_r.
        rewrite (Rmult_inv_l (INR b * sqrt (INR b)) ltac:(nra)).
        rewrite Rmult_1_r.
        rewrite Hsb.
        ring.
      * intros H0.
        assert (HB0 : (INR b <> 0)%R) by lra.
        destruct (Rmult_integral _ _ H0) as [E | E].
        -- destruct (Rmult_integral _ _ E) as [E1 | E1]; apply HB0; exact E1.
        -- exfalso. nra.
Qed.

(* ---------- RS3：链式比率累积 ---------- *)

Lemma chain_pow (C : nat) (v : nat -> nat) (i k : nat) :
  (forall j, (v j * C <= v (S j)))%nat ->
  (v i * C ^ k <= v (i + k))%nat.
Proof.
  intros Hchain. induction k as [| k IH].
  - rewrite Nat.pow_0_r muln1 addn0. apply leqnn.
  - rewrite (Nat.pow_succ_r C k (Nat.le_0_l k)).
    assert (Hs : (v (i + k) * C <= v (S (i + k)))%nat) by apply Hchain.
    assert (Hsucc : (i + S k = S (i + k))%nat) by first [rewrite (addnS i k); reflexivity | lia].
    setoid_rewrite Hsucc.
    rewrite mulnCA. rewrite mulnC.
    apply (leq_trans (n := v (i + k) * C)).
    + apply (leq_mul (n1 := v (i + k)) (n2 := C)). exact IH. by apply leqnn.
    + exact Hs.
Qed.

Lemma v_incr (C : nat) (v : nat -> nat) :
  (2 <= C)%nat -> (forall j, (v j * C <= v (S j)))%nat ->
  forall j j', (j <= j')%nat -> (v j <= v j')%nat.
Proof.
  intros HC Hchain j j' Hjj'.
  assert (Hmono : forall m, (v m * C <= v (S m))%nat) by exact Hchain.
  induction j' as [| j' IH].
  - move: Hjj' => /leP Hj. assert (j = 0)%nat by lia. subst j.
    by apply leqnn.
  - destruct (Nat.eq_dec j (S j')) as [E | E].
    + rewrite E. by apply leqnn.
    + assert (H1 : (v j <= v j')%nat)
        by (apply IH; apply/leP; move: Hjj' => /leP Hj; lia).
      assert (H2 : (v j' * C <= v (S j'))%nat) by apply Hchain.
      assert (H3 : (v j' * 2 <= v j' * C)%nat)
        by (apply (leq_mul (leqnn (v j')) HC)).
      apply (leq_trans (n := v j')).
      * exact H1.
      * apply (leq_trans (n := v j' * 2)).
        - apply (leq_trans (n := v j' * 1)).
          + rewrite muln1. by apply leqnn.
          + apply (leq_mul (leqnn (v j')) (ltnW (ltnSn 1))).
        - apply (leq_trans (n := v j' * C)).
          + exact H3.
          + exact H2.
Qed.

(* ---------- RS4：几何衰减 ---------- *)

Definition qval (C : nat) : R :=
  (/ sqrt (INR C)) * (/ sqrt (INR C)) * (/ sqrt (INR C)).

Lemma sqrt_posnat (n : nat) : (1 <= n)%nat -> (0 < sqrt (INR n))%R.
Proof. intros Hn. apply sqrt_pos_strict. apply lt_0_INR. move: Hn => /leP Hn. lia. Qed.

Lemma pow_ge1 (C : nat) : (1 <= C)%nat -> forall m, (1 <= C ^ m)%nat.
Proof.
  intros H m. induction m as [| m IH]; simpl.
  - by apply leqnn.
  - apply (leq_trans (n := C)).
    + exact H.
    + rewrite -[C in C <= _]muln1. apply (leq_mul (leqnn C) IH).
Qed.

Lemma q_eq (C : nat) : (2 <= C)%nat ->
  (qval C * (INR C * sqrt (INR C)) = 1)%R.
Proof.
  intros HC.
  assert (Hsp : (0 < sqrt (INR C))%R) by (move: HC => /leP HCp; apply sqrt_posnat; apply/leP; lia).
  assert (Hss : (sqrt (INR C) * sqrt (INR C) = INR C)%R)
    by (apply sqrt_sqrt; apply Rlt_le; move: HC => /leP HCp; apply lt_0_INR; lia).
  assert (Hne : (sqrt (INR C) <> 0)%R) by lra.
  unfold qval.
  replace (INR C * sqrt (INR C))%R
    with (sqrt (INR C) * (sqrt (INR C) * sqrt (INR C)))%R
    by (transitivity (sqrt (INR C) * sqrt (INR C) * sqrt (INR C))%R;
        [ring | rewrite Hss; reflexivity]).
  field; (exact Hne || nra || assumption).
Qed.

Lemma q_pow (C : nat) : (2 <= C)%nat -> forall k : nat,
  (qval C ^ (S k) * (INR (C ^ (S k)) * sqrt (INR (C ^ (S k)))) = 1)%R.
Proof.
  intros HC. induction k as [| k IH].
  - assert (Hq1 : (qval C ^ 1 = qval C)%R) by (simpl; ring).
    rewrite Hq1 Nat.pow_1_r. exact (q_eq C HC).
  - assert (HC1 : (1 <= C)%nat) by exact (ltnW HC).
    pose proof (pow_ge1 C HC1 (S k)) as Hpp.
    rewrite pow_S.
    rewrite (Nat.pow_succ_r C (S k) (Nat.le_0_l (S k))).
    rewrite (mult_INR C (Nat.pow C (S k))).
    rewrite (sqrt_mult (INR C) (INR (Nat.pow C (S k)))
              (pos_INR C) (pos_INR (Nat.pow C (S k)))).
    rewrite <- (q_eq C HC).
    replace ((qval C * qval C ^ (S k))%R
              * ((INR C * INR (C ^ (S k))) * (sqrt (INR C) * sqrt (INR (C ^ (S k)))))%R)%R
      with ((qval C * (INR C * sqrt (INR C)))%R
              * (qval C ^ (S k) * (INR (C ^ (S k)) * sqrt (INR (C ^ (S k)))))%R)%R by ring.
    rewrite IH. ring.
Qed.

Lemma q_inv (C : nat) : (2 <= C)%nat -> forall k : nat,
  (qval C ^ (S k) = / (INR (C ^ (S k)) * sqrt (INR (C ^ (S k)))))%R.
Proof.
  intros HC k.
  pose proof (q_pow C HC k) as HQ.
  assert (H1 : (1 <= C ^ (S k))%nat) by (apply pow_ge1; exact (ltnW HC)).
  assert (H2 : (0 < INR (C ^ (S k)))%R)
    by (apply lt_0_INR; move: H1 => /ltP H1p; exact H1p).
  assert (H3 : (0 < sqrt (INR (C ^ (S k))))%R)
    by (apply sqrt_posnat; apply pow_ge1; exact (ltnW HC)).
  apply (Rmult_eq_reg_r (INR (C ^ (S k)) * sqrt (INR (C ^ (S k))))).
  - rewrite HQ.
    replace ((/ (INR (C ^ (S k)) * sqrt (INR (C ^ (S k))))
               * (INR (C ^ (S k)) * sqrt (INR (C ^ (S k)))))%R) with 1%R
      by (field; split; lra).
    reflexivity.
  - intro H0.
    assert (H4 : (0 < INR (C ^ (S k)) * sqrt (INR (C ^ (S k))))%R) by nra.
    lra.
Qed.

Lemma q_range (C : nat) : (2 <= C)%nat -> (0 < qval C < 1)%R.
Proof.
  intros HC. split.
  - unfold qval.
    assert (Hi : (0 < / sqrt (INR C))%R)
      by (apply Rinv_0_lt_compat; apply sqrt_posnat; exact (ltnW HC)).
    apply (Rmult_lt_0_compat (/ sqrt (INR C) * / sqrt (INR C)) (/ sqrt (INR C)));
      [ | exact Hi ].
    apply (Rmult_lt_0_compat (/ sqrt (INR C)) (/ sqrt (INR C))); exact Hi.
  - assert (H1p : (qval C ^ 1 = qval C)%R) by (simpl; ring).
    rewrite <- H1p. rewrite (q_inv C HC 0%nat) Nat.pow_1_r.
    assert (Hsp : (0 < sqrt (INR C))%R) by (apply sqrt_posnat; exact (ltnW HC)).
    assert (Hs : (1 <= sqrt (INR C))%R).
    { destruct (Rlt_or_le (sqrt (INR C)) 1) as [Hlt | Hle]; [ | exact Hle ].
      exfalso.
      assert (Hsq : (sqrt (INR C) * sqrt (INR C) < sqrt (INR C) * 1)%R)
        by (apply Rmult_lt_compat_l; lra).
      rewrite Rmult_1_r in Hsq.
      assert (Hss : (sqrt (INR C) * sqrt (INR C) = INR C)%R)
        by (apply sqrt_sqrt; apply Rlt_le; apply lt_0_INR; move: HC => /leP HCp; lia).
      rewrite Hss in Hsq.
      move: HC => /leP HCp.
      assert (H2 : (INR 1 <= INR C)%R) by (apply le_INR; lia).
      simpl in H2. lra. }
    assert (Ha : (INR 2 <= INR C)%R) by (apply le_INR; move: HC => /leP HCp; lia).
    assert (H4 : (INR 2 * 1 <= INR C * sqrt (INR C))%R)
      by (apply Rmult_le_compat;
          [ apply Rlt_le, lt_0_INR; move: HC => /leP HCp; lia | lra | exact Ha | lra ]).
    rewrite Rmult_1_r in H4.
    simpl in H4.
    assert (HX : (1 < INR C * sqrt (INR C))%R) by lra.
    unfold Rdiv.
    apply (Rmult_lt_reg_r (INR C * sqrt (INR C))).
    + nra.
    + assert (Hnz : (INR C * sqrt (INR C) <> 0)%R) by nra.
      rewrite (Rmult_inv_l (INR C * sqrt (INR C)) Hnz).
      rewrite Rmult_1_l.
      exact HX.
Qed.

Lemma pair_decay (C : nat) (v : nat -> nat) (i k : nat) :
  (2 <= C)%nat -> (2 <= v i)%nat ->
  (forall j, (v j * C <= v (S j)))%nat ->
  (Fpair (v i) (v ((i + S k)%nat)) <= PI * qval C ^ (S k))%R.
Proof.
  intros HC Hvi Hchain.
  assert (Hab2 : (2 * v i <= v ((i + S k)%nat))%nat).
  { assert (H1 : (v i * C <= v (S i))%nat) by apply Hchain.
    assert (H2 : (v i * 2 <= v i * C)%nat)
      by (apply (leq_mul (leqnn (v i)) HC)).
    assert (H3 : (v (S i) <= v ((i + S k)%nat))%nat)
      by (apply (v_incr C v HC Hchain); rewrite addnS || rewrite Nat.add_succ_r; rewrite ltnS; apply leq_addr).
    apply (leq_trans (n := v i * C)).
    - rewrite mulnC. exact H2.
    - apply (leq_trans (n := v (S i))).
      + exact H1.
      + exact H3. }
  apply (Rle_trans _
           (PI * (INR (v i) * sqrt (INR (v i)))
              / (INR (v ((i + S k)%nat)) * sqrt (INR (v ((i + S k)%nat)))))).
  - apply pair_le_crude; [ exact Hvi | exact Hab2 ].
  - assert (Hpp : (1 <= C ^ (S k))%nat) by (apply pow_ge1; exact (ltnW HC)).
    assert (HIC : (0 < INR (C ^ (S k)))%R)
      by (apply lt_0_INR; move: Hpp => /ltP Hppp; exact Hppp).
    assert (HISC : (0 < sqrt (INR (C ^ (S k))))%R) by (apply sqrt_posnat; exact Hpp).
    assert (Hia : (0 < INR (v i))%R)
      by (apply lt_0_INR; move: Hvi => /ltP Hvp; lia).
    assert (Hib : (0 < INR (v ((i + S k)%nat)))%R).
    { apply (Rlt_le_trans _ (INR (v i)) _); [ exact Hia | ].
      apply le_INR. apply/leP.
      apply (v_incr C v HC Hchain). rewrite addnS || rewrite Nat.add_succ_r.
      apply (leq_trans (n := i + k)).
      - apply leq_addr.
      - by apply leqnSn. }
    assert (Hsa : (0 < sqrt (INR (v i)))%R) by (apply sqrt_posnat; exact (ltnW Hvi)).
    assert (Hsb : (0 < sqrt (INR (v ((i + S k)%nat))))%R).
    { apply sqrt_posnat.
      apply (leq_trans (n := 2 * v i)).
      - apply (leq_trans (n := 2)).
        + exact (ltnW (ltnSn 1)).
        + exact (leq_mul (leqnn 2) (ltnW Hvi)).
      - exact Hab2. }
    rewrite (q_inv C HC k).
    unfold Rdiv.
    replace ((PI * (INR (v i) * sqrt (INR (v i))))
             * Rinv (INR (v ((i + S k)%nat)) * sqrt (INR (v ((i + S k)%nat)))))%R
      with (PI * ((INR (v i) * sqrt (INR (v i)))
                  * Rinv (INR (v ((i + S k)%nat)) * sqrt (INR (v ((i + S k)%nat))))))%R
      by ring.
    apply Rmult_le_compat_l; [ apply Rlt_le, PI_RGT_0 | ].
    apply (Rmult_le_reg_r (INR (C ^ (S k)) * sqrt (INR (C ^ (S k))))).
    + apply Rmult_lt_0_compat; [ exact HIC | exact HISC ].
    + assert (HnzD : (INR (C ^ (S k)) * sqrt (INR (C ^ (S k))) <> 0)%R) by nra.
      rewrite (Rmult_inv_l (INR (C ^ (S k)) * sqrt (INR (C ^ (S k)))) HnzD).
      apply (Rmult_le_reg_r (INR (v ((i + S k)%nat)) * sqrt (INR (v ((i + S k)%nat))))).
      * apply Rmult_lt_0_compat; [ exact Hib | exact Hsb ].
      * replace ((INR (v i) * sqrt (INR (v i)) * Rinv (INR (v ((i + S k)%nat)) * sqrt (INR (v ((i + S k)%nat))))
                 * (INR (C ^ (S k)) * sqrt (INR (C ^ (S k)))))
                * (INR (v ((i + S k)%nat)) * sqrt (INR (v ((i + S k)%nat)))))%R
          with ((INR (v i) * sqrt (INR (v i))) * (INR (C ^ (S k)) * sqrt (INR (C ^ (S k)))))%R
          by (field; split; lra).
        replace (1 * (INR (v ((i + S k)%nat)) * sqrt (INR (v ((i + S k)%nat)))))%R
          with (INR (v ((i + S k)%nat)) * sqrt (INR (v ((i + S k)%nat))))%R by ring.
        assert (HIN : (INR (v i) * INR (C ^ (S k)) <= INR (v ((i + S k)%nat)))%R).
        { rewrite <- (mult_INR (v i) (C ^ (S k))). apply le_INR. apply/leP.
          apply chain_pow. exact Hchain. }
        assert (HP0 : (0 <= INR (v i) * INR (C ^ (S k)))%R)
          by (apply Rmult_le_pos; apply pos_INR).
        assert (HQ0 : (0 <= INR (v ((i + S k)%nat)))%R) by apply pos_INR.
        assert (Hsq : (sqrt (INR (v i) * INR (C ^ (S k))) <= sqrt (INR (v ((i + S k)%nat))))%R)
          by (apply sqrt_le_1; [ exact HP0 | exact HQ0 | exact HIN ]).
        replace ((INR (v i) * sqrt (INR (v i))) * (INR (C ^ (S k)) * sqrt (INR (C ^ (S k)))))%R
          with ((INR (v i) * INR (C ^ (S k))) * sqrt (INR (v i) * INR (C ^ (S k))))%R
          by (rewrite (sqrt_mult (INR (v i)) (INR (C ^ (S k)))
                        (pos_INR (v i)) (pos_INR (C ^ (S k)))); ring).
        assert (HPg : (0 < INR (v i) * INR (C ^ (S k)))%R)
          by (apply Rmult_lt_0_compat; [ exact Hia | exact HIC ]).
        apply (Rle_trans _ (INR (v ((i + S k)%nat)) * sqrt (INR (v i) * INR (C ^ (S k))))).
        { apply Rmult_le_compat_r; [ apply Rlt_le, sqrt_pos_strict; exact HPg | exact HIN ]. }
        { apply Rmult_le_compat_l; [ exact HQ0 | exact Hsq ]. }
Qed.

(* ---------- RS5：行和收口 ---------- *)

Lemma lsum_scal (c : R) (f : nat -> R) (m : nat) :
  (lsum (fun k => c * f k) m = c * lsum f m)%R.
Proof.
  induction m as [| m IH]; cbn [lsum].
  - ring.
  - rewrite IH. ring.
Qed.

Lemma geo_scaled (C : nat) (m : nat) : (2 <= C)%nat ->
  (lsum (fun d => PI * qval C ^ (S d)) m <= PI * qval C / (1 - qval C))%R.
Proof.
  intros HC.
  destruct (q_range C HC) as [Hq0 Hq1].
  rewrite (lsum_scal PI (fun d => (qval C ^ (S d))%R) m).
  replace (PI * qval C / (1 - qval C))%R
    with (PI * (qval C / (1 - qval C)))%R by (unfold Rdiv; ring).
  apply Rmult_le_compat_l; [ apply Rlt_le, PI_RGT_0 | ].
  apply (Rle_trans _ (qval C / (1 - qval C))).
  - apply geo_bound; split; [exact Hq0 | exact Hq1].
  - unfold Rdiv. apply Rmult_le_compat_r.
    + left. apply Rinv_0_lt_compat. lra.
    + lra.
Qed.

Lemma oneside (C : nat) (v : nat -> nat) (i m : nat) :
  (2 <= C)%nat -> (2 <= v i)%nat ->
  (forall j, (v j * C <= v (S j)))%nat ->
  (lsum (fun d => Fpair (v i) (v ((i + S d)%nat))) m
   <= PI * qval C / (1 - qval C))%R.
Proof.
  intros HC Hvi Hchain.
  apply (Rle_trans _ (lsum (fun d => (PI * qval C ^ (S d))%R) m)).
  - apply lsum_le. intros d Hd.
    exact (pair_decay C v i d HC Hvi Hchain).
  - apply geo_scaled. exact HC.
Qed.

Lemma row_sum_3halfs (C : nat) (v : nat -> nat) (i m : nat) :
  (2 <= C)%nat -> (m <= i)%nat ->
  (forall j, (2 <= v j)%nat) ->
  (forall j, (v j * C <= v (S j)))%nat ->
  (lsum (fun d => Fpair (v i) (v ((i + S d)%nat))) m
   + lsum (fun d => Fpair (v ((i - S d)%nat)) (v i)) m
   <= 2 * (PI * qval C / (1 - qval C)))%R.
Proof.
  intros HC Hmi Hv2 Hchain.
  assert (Hvi : (2 <= v i)%nat) by apply Hv2.
  apply (Rle_trans _
           (PI * qval C / (1 - qval C) + PI * qval C / (1 - qval C))).
  - apply Rplus_le_compat.
    + apply oneside; assumption.
    + apply (Rle_trans _ (lsum (fun d => (PI * qval C ^ (S d))%R) m)).
      * apply lsum_le. intros d Hd.
        assert (Hsd : (S d <= i)%nat) by exact (leq_trans Hd Hmi).
        assert (Heq : (((i - S d)%nat + S d)%nat = i)%nat)
          by (rewrite (subnK Hsd); reflexivity).
        pose proof (pair_decay C v ((i - S d)%nat) d HC (Hv2 _) Hchain) as HP.
        rewrite Heq in HP. exact HP.
      * apply geo_scaled. exact HC.
  - ring_simplify. apply Rle_refl.
Qed.

(* ---------- 数值实例：C = 4 ---------- *)

Lemma sqrt_INR_4 : (sqrt (INR 4) = 2)%R.
Proof.
  assert (H4 : (INR 4 = 4)%R) by (simpl; ring).
  assert (Hsp : (0 < sqrt (INR 4))%R) by (apply sqrt_posnat; by []).
  assert (Hss : (sqrt (INR 4) * sqrt (INR 4) = INR 4)%R)
    by (rewrite H4; apply sqrt_sqrt; lra).
  assert (E : ((sqrt (INR 4) - 2) * (sqrt (INR 4) + 2) = 0)%R).
  { replace ((sqrt (INR 4) - 2) * (sqrt (INR 4) + 2))%R
      with (sqrt (INR 4) * sqrt (INR 4) - 2 * 2)%R by ring.
    rewrite Hss H4. ring. }
  destruct (Rmult_integral _ _ E) as [E1 | E2].
  - lra.
  - exfalso. lra.
Qed.

Lemma qval4_eq : (qval 4 = 1 / 8)%R.
Proof.
  assert (HC4 : (2 <= 4)%nat) by by [].
  assert (H := q_eq 4 HC4).
  assert (H4 : (INR 4 = 4)%R) by (simpl; ring).
  rewrite sqrt_INR_4 H4 in H.
  replace (4 * 2)%R with 8%R in H by ring.
  apply (Rmult_eq_reg_r 8); (rewrite H; field; lra) || lra.
Qed.

Lemma row_bound_C4 : (2 * (PI * qval 4 / (1 - qval 4)) <= 1)%R.
Proof.
  rewrite qval4_eq.
  assert (Hb : (PI <= 7 / 2)%R).
  { unfold PI. replace (7 / 2)%R with (2 * (7 / 4))%R by (field; lra).
    apply (Rmult_le_compat_l 2 PI2 (7 / 4)); [ lra | apply (proj2 pi2_int) ]. }
  replace (1 - 1 / 8)%R with (7 / 8)%R by (field; lra).
  apply (Rle_trans _ (2 * ((7 / 2) * (1 / 8) / (7 / 8)))).
  - apply Rmult_le_compat_l; [ lra | ].
    unfold Rdiv. apply Rmult_le_compat_r; [ left; apply Rinv_0_lt_compat; lra | ].
    apply Rmult_le_compat_r; [ lra | exact Hb ].
  - replace ((7 / 2) * (1 / 8) / (7 / 8))%R with (1 / 2)%R
      by (unfold Rdiv; field).
    replace (2 * (1 / 2))%R with 1%R by (field; lra).
    apply Rle_refl.
Qed.

End RowSum.

Print Assumptions RowSum.row_sum_3halfs.
Print Assumptions RowSum.oneside.
Print Assumptions RowSum.pair_decay.
Print Assumptions RowSum.pair_le_crude.
Print Assumptions RowSum.row_bound_C4.

(* ==================== 模块 41/67: probe_pairdirichlet ==================== *)

Close Scope Z_scope.
Open Scope R_scope.
Open Scope complex_scope.
Open Scope nat_scope.
(* ============================================================
   任意角度对 Dirichlet 界 → 混合网格跨网格相干界
   前置：probe_grid_ortho（rot 机器）、probe_partial（Dirichlet 主定理）。

   主定理 pair_dirichlet：任意两角度 t1 t2，若差频 t1−t2 落在
   N-网格（= 2π·j/N，j mod N ≠ 0），则任意窗口 W 上
     ‖Σ_{k<W} e^{ik·t1}·conj(e^{ik·t2})‖ ≤ INR N / (2·INR s)
     s = min(j mod N, N − j mod N)
   ——窗口无关，全部机器复用 dirichlet_partial_bound。

   推论 mixed_grid_coherence：嵌套网格 N 与 a·N 上的两原子
   （grid_atom N m1 与 grid_atom (a*N) m2），差频 = j/(a·N) 时
   跨网格相干 ≤ INR (a·N) / (2·INR s)。grid 崩塌后"多尺度网格
   设计空间"的核心定量工具。
   ============================================================ *)
From mathcomp Require Import ssreflect ssrbool ssrnat seq eqtype div prime.
Require Import Stdlib.Reals.Reals.
Require Import Stdlib.Arith.Arith.
Require Import Stdlib.micromega.Lia.
Require Import Stdlib.micromega.Lra.
Require Import Stdlib.ZArith.ZArith.
Import ComplexNumbers.
Import FourierAnalysis.
Import GridOrtho.
Import TPartial.

Open Scope R_scope.
Open Scope complex_scope.
Open Scope nat_scope.

Module PairDirichlet.

(* conj 的旋转原子形式 *)
Lemma rot_conj_rot (theta : R) (k : nat) : Cconj (rot_atom theta k) = rot_atom (- theta) k.
Proof.
  unfold rot_atom. rewrite Cconj_Cexp.
  replace ((INR k * - theta))%R with (- (INR k * theta))%R by ring.
  reflexivity.
Qed.

(* 旋转原子乘法 → 和角原子 *)
Lemma rot_mul_rot (a b : R) (k : nat) :
  rot_atom a k *c rot_atom b k = rot_atom (a + b) k.
Proof.
  unfold rot_atom. rewrite <- Cexp_add. rewrite <- i_split.
  replace ((INR k * (a + b)))%R with ((INR k * a) + (INR k * b))%R by ring.
  reflexivity.
Qed.

(* 乘积对 = 差频原子（核心步） *)
Lemma pair_eq_rotdiff (t1 t2 : R) (k : nat) :
  rot_atom t1 k *c Cconj (rot_atom t2 k) = rot_atom (t1 - t2) k.
Proof. rewrite rot_conj_rot rot_mul_rot. reflexivity. Qed.

(* ---------- 主定理 ---------- *)

Theorem pair_dirichlet (N j W : nat) (t1 t2 : R) :
  (2 <= N)%nat -> (j mod N <> 0)%nat ->
  ((t1 - t2) = (2 * PI * INR j / INR N))%R ->
  ((Cnorm (PrimeEmbedding.Csum
      (fun k => rot_atom t1 k *c Cconj (rot_atom t2 k)) W)
    <= INR N / (2 * INR (Nat.min (j mod N) (N - j mod N))))%R).
Proof.
  intros HN Hneq Hdiff.
  assert (Hconv : PrimeEmbedding.Csum
             (fun k => rot_atom t1 k *c Cconj (rot_atom t2 k)) W
             = PrimeEmbedding.Csum (fun k => grid_atom N j k) W).
  { apply Csum_ext. intros k Hk.
    rewrite pair_eq_rotdiff Hdiff.
    rewrite (rot_grid N j k HN). reflexivity. }
  rewrite Hconv.
  apply dirichlet_partial_bound; [exact HN | exact Hneq].
Qed.

(* ---------- 混合网格推论 ---------- *)

Theorem mixed_grid_coherence (N a m1 m2 W j : nat) :
  (2 <= N)%nat -> (0 < a)%nat -> (j mod (a * N) <> 0)%nat ->
  ((INR m1 / INR N - INR m2 / INR (a * N)) = (INR j / INR (a * N)))%R ->
  ((Cnorm (PrimeEmbedding.Csum
      (fun k => grid_atom N m1 k *c Cconj (grid_atom (a * N) m2 k)) W)
    <= INR (a * N)
       / (2 * INR (Nat.min (j mod (a * N)) (a * N - j mod (a * N))))))%R.
Proof.
  intros HN Ha Hneq Hdiff.
  assert (Hconv : PrimeEmbedding.Csum
             (fun k => grid_atom N m1 k *c Cconj (grid_atom (a * N) m2 k)) W
             = PrimeEmbedding.Csum
                 (fun k => rot_atom (2 * PI * INR m1 / INR N) k
                           *c Cconj (rot_atom (2 * PI * INR m2 / INR (a * N)) k)) W).
  { apply Csum_ext. intros k Hk.
    rewrite (rot_grid N m1 k HN).
    rewrite (rot_grid (a * N) m2 k) => //; exact (leq_mul Ha HN). }
  rewrite Hconv.
  assert (HNz : (0 < INR N)%R) by (apply lt_0_INR; move: HN => /ltP HNp; lia).
  assert (HANz : (0 < INR (a * N))%R)
    by (apply lt_0_INR; apply/ltP;
        apply (leq_trans (n := 2));
        [ exact (ltnW (ltnSn 1)) | exact (leq_mul Ha HN) ]).
  assert (Heq : ((2 * PI * INR m1 / INR N - 2 * PI * INR m2 / INR (a * N))
                 = (2 * PI * INR j / INR (a * N)))%R).
  { replace ((2 * PI * INR j / INR (a * N)))%R
      with ((2 * PI) * (INR j / INR (a * N)))%R by (field; lra).
    replace ((2 * PI * INR m1 / INR N))%R
      with ((2 * PI) * (INR m1 / INR N))%R by (field; lra).
    replace ((2 * PI * INR m2 / INR (a * N)))%R
      with ((2 * PI) * (INR m2 / INR (a * N)))%R by (field; lra).
    rewrite <- Hdiff. ring. }
  apply (pair_dirichlet (a * N) j W
           (2 * PI * INR m1 / INR N) (2 * PI * INR m2 / INR (a * N)));
    [ exact (leq_mul Ha HN) | exact Hneq | exact Heq ].
Qed.

End PairDirichlet.

(* ---------- 构造性审计 ---------- *)

Print Assumptions PairDirichlet.pair_dirichlet.
Print Assumptions PairDirichlet.mixed_grid_coherence.

(* ==================== 模块 42/67: probe_incoherence ==================== *)

Close Scope Z_scope.
Open Scope R_scope.
Open Scope complex_scope.
Open Scope nat_scope.
(* ============================================================

   数学内容： psi 频率阶梯（波长 n 截断复指数，库 ca_basis.psi，
   归一化 ‖ψ_n‖=1）构成低相干（incoherent）原子族——压缩感知地基。

     IC0 inner（实内积 re(a·conj b)）+ 对称/实缩放/求和提取。
     IC1 psi 范数 = 1 + phi=rot 桥 + 零前缀 Csum 消除。
     IC2 psi_mu_bound：|⟨ψ_a,ψ_b⟩| ≤ Fpair a b（b≥2a）。
     IC3 l2_add_gen（广义 Pythagoras）+ ipW 双线性。
     IC4 norm_sq_expansion：M 原子实系数合成范数平方显式展开。
     IC5 rip_bound（CS-2）：μ-不相干单位原子 ⟹
        |‖Σc_jA_j‖² − Σc_j²| ≤ μ·(M−1)·Σc_j²（Gershgorin 型 RIP）。
     IC6 sparse_uniqueness（CS-3）：(M−1)μ < 1 ⟹ 零表示 ⟹ 系数全零。
     IC7 psi_ladder_mu（CS-1）：C-梯子 ⟹ |⟨ψ_i,ψ_j⟩| ≤ π/(C√C)。
     IC8 psi_ladder_uniqueness（主定理）：(2s−1)π/(C√C) < 1 ⟹ 唯一。
     IC9 数值门槛：C=4 ⟹ s=1；C=9 ⟹ s≤4；C=16 ⟹ s≤9。

   依赖： ca_basis（psi/phi/Cof_real/l2_norm_sq）+ probe_parseval +
   probe_rowsum（Fpair/pair_le_crude）。审计： Print Assumptions 尾部。
   ============================================================ *)
From mathcomp Require Import ssreflect ssrbool ssrnat seq eqtype div prime.
Require Import Stdlib.Reals.Reals.
Require Import Stdlib.Arith.Arith.
Require Import Stdlib.micromega.Lia.
Require Import Stdlib.micromega.Lra.
Require Import Stdlib.ZArith.ZArith.
Require Import Stdlib.Logic.FunctionalExtensionality.
Import ComplexNumbers.
Import FourierAnalysis.
Import GridOrtho.
Import TParseval.
Import TPartial.
Import PairBound.
Import RowSum.
Import UnconditionalBasis.
Import PairDirichlet.

Open Scope R_scope.
Open Scope complex_scope.
Open Scope nat_scope.

Module Incoherence.

(* ---------- IC0：inner 基础件 ---------- *)

Definition inner (a b : Complex) : R := re (a *c Cconj b).

Lemma Cof_real_mul_re : forall (r : R) (z : Complex),
  (re (Cof_real r *c z))%R = (r * re z)%R.
Proof.
  intros r z. unfold Cof_real, Cmul. simpl. ring.
Qed.

Lemma inner_sym : forall a b : Complex, (inner a b)%R = (inner b a)%R.
Proof.
  intros a b. unfold inner. rewrite !re_mul_conj. ring.
Qed.

Lemma inner_CR_l : forall (c : R) (a b : Complex),
  (inner (Cof_real c *c a) b)%R = (c * inner a b)%R.
Proof.
  intros c a b. unfold inner. rewrite Cmul_assoc.
  rewrite Cof_real_mul_re. reflexivity.
Qed.

Lemma inner_CR_r : forall (c : R) (a b : Complex),
  (inner a (Cof_real c *c b))%R = (c * inner a b)%R.
Proof.
  intros c a b.
  rewrite (inner_sym a (Cof_real c *c b)) inner_CR_l inner_sym. ring.
Qed.

(* 零前缀消除：a ≤ k < b 项全零 ⟹ Csum f b = Csum f a *)
Lemma Csum_zero_tail : forall (f : nat -> Complex) (a b : nat),
  (a <= b)%nat ->
  (forall k, (a <= k < b)%nat -> (f k = C0)%C) ->
  (PrimeEmbedding.Csum f b = PrimeEmbedding.Csum f a)%C.
Proof.
  intros f a b Hab Hz. induction b as [| b IH].
  - assert (a = 0%nat) by (move: Hab => /leP Habp; lia). subst a. reflexivity.
  - destruct (Nat.eq_dec a (S b)) as [Ea | Ea].
    + rewrite Ea. reflexivity.
    + assert (Hab' : (a <= b)%nat) by (apply/leP; move: Hab => /leP Habp; move: Ea => Eap; lia).
      assert (Hs : (PrimeEmbedding.Csum f (S b)
                    = Cadd (f b) (PrimeEmbedding.Csum f b))%C) by reflexivity.
      rewrite Hs.
      assert (Hz' : forall k, a <= k < b -> f k = C0)
        by (intros k Hk; apply Hz; move: Hk => /andP [Hak Hkb];
            apply/andP; split; [ exact Hak |
              exact (ltn_trans Hkb (ltnSn b)) ]).
      rewrite (IH Hab' Hz') (Hz b (andb_true_intro (conj Hab' (ltnSn b)))).
      apply Cadd_0_l.
Qed.

(* ---------- IC1：psi 范数 = 1 ---------- *)

Lemma phi_eq_rot : forall (n k : nat),
  (k < n)%nat -> (phi n k = rot_atom (2 * PI / INR n) k)%C.
Proof.
  intros n k Hk. unfold phi, rot_atom. move: Hk => /ltP Hkp.
  rewrite (proj2 (Nat.ltb_lt k n) Hkp).
  replace (2 * PI * INR k / INR n)%R with (INR k * (2 * PI / INR n))%R
    by (field; intros Hc; assert (Hpos : (0 < INR n)%R) by (apply lt_0_INR; lia); lra).
  reflexivity.
Qed.

Lemma sum_ones : forall m : nat, (sum_f_R0 (fun _ => 1)%R m)%R = (INR (S m))%R.
Proof.
  induction m as [| m IH]; simpl.
  - reflexivity.
  - rewrite IH. simpl. ring.
Qed.

Lemma sum_f_R0_ext_bounded : forall (f g : nat -> R) (N : nat),
  (forall k, (k <= N)%nat -> (f k = g k))%R -> (sum_f_R0 f N)%R = (sum_f_R0 g N)%R.
Proof.
  intros f g N H. induction N as [| N IH].
  - apply H. by apply leqnn.
  - simpl.
    assert (IHsc : forall k : nat, (k <= N)%nat -> (f k = g k)%R) by (intros k Hk; apply H; exact (leq_trans Hk (leqnSn N))).
    rewrite (IH IHsc).
    rewrite (H (S N) (leqnn (S N))). reflexivity.
Qed.

Lemma phi_l2_norm : forall n : nat, (1 <= n)%nat ->
  (l2_norm_sq (phi n) (Nat.pred n))%R = (INR n)%R.
Proof.
  intros n Hn. unfold l2_norm_sq.
  transitivity (sum_f_R0 (fun _ : nat => 1)%R (Nat.pred n)).
  - apply sum_f_R0_ext_bounded. intros k Hk.
    assert (Hkn : (k < n)%nat)
      by (apply/ltP; move: Hk => /leP Hkp; move: Hn => /leP Hnp; lia).
    rewrite phi_eq_rot => //; apply rot_norm_sq.
  - replace (INR n)%R with (INR (S (Nat.pred n)))%R by (f_equal; move: Hn => /leP Hnp; lia).
    apply sum_ones.
Qed.

Lemma Cnorm_sq_Cof_real : forall r : R, (Cnorm_sq (Cof_real r))%R = (r * r)%R.
Proof.
  intros r. unfold Cof_real, Cnorm_sq. simpl.
  replace (Rsqr 0)%R with 0%R by (unfold Rsqr; ring).
  unfold Rsqr. ring.
Qed.

Theorem psi_norm_one : forall n : nat, (1 <= n)%nat ->
  (l2_norm_sq (psi n) (Nat.pred n))%R = 1%R.
Proof.
  intros n Hn. unfold psi.
  rewrite l2_norm_sq_scale Cnorm_sq_Cof_real. rewrite (phi_l2_norm n Hn).
  (* 目标：(1/sqrt(INR n))·(1/sqrt(INR n))·INR n = 1。
     用 s := sqrt(INR n)，把 INR n 重写为 s·s，再 field（field 无法直接消化 sqrt）。 *)
  set (s := sqrt (INR n)).
  assert (Hss : (s * s)%R = (INR n)%R).
  { unfold s. apply sqrt_sqrt. apply pos_INR. }
  rewrite <- Hss.
  field.
  intros Hc.
  assert (H' : (0 < s)%R).
  { unfold s. apply sqrt_lt_R0. apply lt_0_INR. move: Hn => /leP Hnp. lia. }
  exact (Rlt_not_eq 0 s H' (Logic.eq_sym Hc)).
Qed.

End Incoherence.

(* ============================================================
   —— 在既有 IC0/IC1（inner、psi_norm_one）之上。
   Module Incoherence2：ipW 内积机器 + 双原子范数展开 + 稀疏唯一性。
   ============================================================ *)
Module Incoherence2.

(* ============================================================
   —— ipW 内积机器 + 双原子范数展开 + 稀疏唯一性（非平凡核心）。
   依赖：probe_parseval（Cnorm_sq_add/re_mul_conj/sum_f_R0_*）。
   审计：Dedekind 三件套基座继承，零自定义公理、零 Admitted。
   ============================================================ *)

(* 窗口内积：⟨u,v⟩_W = Σ_{k≤W} re(u k ·c conj(v k))（sum_f_R0 含端点 W+1 项） *)
Definition ipW (u v : nat -> Complex) (W : nat) : R :=
  sum_f_R0 (fun k => re (u k *c Cconj (v k))) W.

(* Cnorm_sq z = re (z *c Cconj z) *)
Lemma l2_ip_pure (z : Complex) : (Cnorm_sq z)%R = (re (z *c Cconj z))%R.
Proof.
  unfold Cnorm_sq. simpl. unfold Rsqr. ring.
Qed.

(* l2_norm_sq u W = ipW u u W *)
Lemma l2_is_ip (u : nat -> Complex) (W : nat) :
  (l2_norm_sq u W)%R = (ipW u u W)%R.
Proof.
  unfold l2_norm_sq, ipW.
  apply sum_f_R0_ext.
  intro k. apply l2_ip_pure.
Qed.

(* 内积对称：⟨u,v⟩ = ⟨v,u⟩ *)
Lemma ipW_sym (u v : nat -> Complex) (W : nat) :
  (ipW u v W)%R = (ipW v u W)%R.
Proof.
  unfold ipW. apply sum_f_R0_ext. intro k.
  rewrite re_mul_conj. rewrite (re_mul_conj (v k) (u k)). ring.
Qed.

(* 实左缩放：⟨r·u, v⟩ = r·⟨u,v⟩ *)
Lemma ipW_CR_l (r : R) (u v : nat -> Complex) (W : nat) :
  (ipW (fun k => Cof_real r *c u k) v W)%R = (r * ipW u v W)%R.
Proof.
  unfold ipW.
  assert (Hext : forall k : nat, (re (Cof_real r *c u k *c Cconj (v k)) = r * re (u k *c Cconj (v k)))%R)
    by (intro k; rewrite Cmul_assoc; apply Incoherence.Cof_real_mul_re).
  rewrite (sum_f_R0_ext (fun k => re (Cof_real r *c u k *c Cconj (v k)))
                        (fun k => (r * re (u k *c Cconj (v k)))%R) W Hext).
  exact (sum_f_R0_scal r (fun k => re (u k *c Cconj (v k))) W).
Qed.

(* 实右缩放：⟨u, r·v⟩ = r·⟨u,v⟩ *)
Lemma ipW_CR_r (r : R) (u v : nat -> Complex) (W : nat) :
  (ipW u (fun k => Cof_real r *c v k) W)%R = (r * ipW u v W)%R.
Proof.
  intros. rewrite ipW_sym.
  rewrite (ipW_CR_l r v u W).
  rewrite (ipW_sym u v W).
  reflexivity.
Qed.

(* 左加性：⟨u+v, w⟩ = ⟨u,w⟩ + ⟨v,w⟩ *)
Lemma ipW_add_l (u v w : nat -> Complex) (W : nat) :
  (ipW (fun k => u k +c v k) w W)%R = ((ipW u w W) + (ipW v w W))%R.
Proof.
  unfold ipW.
  assert (Hext : forall k : nat, (re ((u k +c v k) *c Cconj (w k)) = re (u k *c Cconj (w k)) + re (v k *c Cconj (w k)))%R)
    by (intro k; rewrite Cmul_add_distr_r; unfold Cadd; simpl; ring).
  rewrite (sum_f_R0_ext _ (fun k => ((re (u k *c Cconj (w k))) + (re (v k *c Cconj (w k))))%R) W Hext).
  unfold ipW.
  exact (sum_f_R0_plus (fun k => re (u k *c Cconj (w k)))
                       (fun k => re (v k *c Cconj (w k))) W).
Qed.

(* 右加性：⟨u, v+w⟩ = ⟨u,v⟩ + ⟨u,w⟩ *)
Lemma ipW_add_r (u v w : nat -> Complex) (W : nat) :
  (ipW u (fun k => v k +c w k) W)%R = ((ipW u v W) + (ipW u w W))%R.
Proof.
  intros. rewrite ipW_sym.
  rewrite (ipW_add_l v w u W).
  rewrite (ipW_sym u w W).
  rewrite (ipW_sym u v W).
  reflexivity.
Qed.

(* Cconj 与实缩放交换 *)
Lemma Cconj_Cof_real (r : R) (z : Complex) : Cconj (Cof_real r *c z) = Cof_real r *c Cconj z.
Proof.
  apply Complex_eq; simpl; ring.
Qed.

(* re((r·a)·c (s·b)) = (r·s)·re(a·c b) *)
Lemma re_scal_conj (r s : R) (a b : Complex) :
  (re ((Cof_real r *c a) *c (Cof_real s *c Cconj b)))%R = ((r * s) * re (a *c Cconj b))%R.
Proof.
  unfold Cof_real, Cmul, Cconj. simpl. unfold Rsqr. ring.
Qed.

(* Cnorm_sq (r·z) = r²·Cnorm_sq z *)
Lemma Cnorm_sq_scal (r : R) (z : Complex) :
  (Cnorm_sq (Cof_real r *c z))%R = ((r * r) * Cnorm_sq z)%R.
Proof.
  rewrite Cnorm_sq_mult.
  unfold Cof_real, Cnorm_sq. simpl. unfold Rsqr. ring.
Qed.

(* 逐点：‖c1·a + c2·b‖² = c1²‖a‖² + c2²‖b‖² + 2·c1·c2·re(a·c b) *)
Lemma norm_sq_combo2_point (c1 c2 : R) (a b : Complex) :
  (Cnorm_sq (Cof_real c1 *c a +c Cof_real c2 *c b))%R
  = ((c1 * c1) * Cnorm_sq a + (c2 * c2) * Cnorm_sq b
     + 2 * (c1 * c2) * re (a *c Cconj b))%R.
Proof.
  rewrite Cnorm_sq_add.
  rewrite <- (re_mul_conj (Cof_real c1 *c a) (Cof_real c2 *c b)).
  rewrite (Cconj_Cof_real c2 b).
  rewrite Cnorm_sq_scal Cnorm_sq_scal.
  rewrite re_scal_conj.
  ring.
Qed.

(* |a|² = a² *)
Lemma Rabs_sqr_eq (a : R) : (Rabs a * Rabs a = a * a)%R.
Proof.
  assert (H := Rsqr_abs a). unfold Rsqr in H. symmetry. exact H.
Qed.

(* |−x| = |x| *)
Lemma Rabs_opp (x : R) : (Rabs (- x))%R = (Rabs x)%R.
Proof.
  replace (- x)%R with (0 - x)%R by ring.
  replace (Rabs (0 - x))%R with (Rabs (x - 0))%R by (apply Rabs_minus_sym).
  replace (x - 0)%R with x by ring.
  reflexivity.
Qed.

(* |2·x| = 2·|x| *)
Lemma Rabs_2_mult (x : R) : (Rabs (2 * x))%R = (2 * Rabs x)%R.
Proof.
  rewrite Rabs_mult.
  rewrite (Rabs_right 2 (Rle_ge 0 2 (Rlt_le 0 2 Rlt_0_2))).
  ring.
Qed.

(* AM-GM：2|ab| ≤ a² + b² *)
Lemma Rabs_prod_le_sq_sum (a b : R) : ((2 * Rabs (a * b)) <= (a * a + b * b))%R.
Proof.
  rewrite Rabs_mult.
  assert (Hn : (0 <= Rabs a * Rabs b)%R).
  { apply Rmult_le_pos; apply Rabs_pos. }
  assert (Hsq : (0 <= (Rabs a - Rabs b) * (Rabs a - Rabs b))%R).
  { apply Rle_0_sqr. }
  assert (H1 : (2 * (Rabs a * Rabs b) <= Rabs a * Rabs a + Rabs b * Rabs b)%R).
  { unfold Rsqr in Hsq. lra. }
  rewrite Rabs_sqr_eq Rabs_sqr_eq in H1.
  lra.
Qed.

(* a² + b² = 0 ⟹ a = 0 *)
Lemma sq_sum_zero_l (a b : R) : (a * a + b * b = 0)%R -> a = 0%R.
Proof.
  intros H.
  assert (Hge : (0 <= a * a)%R) by apply Rle_0_sqr.
  assert (Hb : (0 <= b * b)%R) by apply Rle_0_sqr.
  assert (Hadd : ((a * a) + (b * b) <= 0)%R).
  { rewrite H. lra. }
  assert (Hle1 : (a * a <= - (b * b))%R).
  { apply (Rplus_le_reg_l (b * b) (a * a) (- (b * b))).
    replace ((b * b) + (a * a))%R with ((a * a) + (b * b))%R by ring.
    replace ((b * b) + (- (b * b)))%R with 0%R by ring.
    exact Hadd. }
  assert (Hle2 : (- (b * b) <= 0)%R) by lra.
  assert (Hle : (a * a <= 0)%R) by exact (Rle_trans (a * a) (- (b * b)) 0 Hle1 Hle2).
  apply Rsqr_0_uniq.
  apply Rle_antisym; auto.
Qed.

(* a² + b² = 0 ⟹ b = 0 *)
Lemma sq_sum_zero_r (a b : R) : (a * a + b * b = 0)%R -> b = 0%R.
Proof.
  intros H.
  assert (Hge : (0 <= b * b)%R) by apply Rle_0_sqr.
  assert (Ha : (0 <= a * a)%R) by apply Rle_0_sqr.
  assert (Hadd : ((b * b) + (a * a) <= 0)%R).
  { rewrite (Rplus_comm (a * a) (b * b)) in H. rewrite H. lra. }
  assert (Hle1 : (b * b <= - (a * a))%R).
  { apply (Rplus_le_reg_l (a * a) (b * b) (- (a * a))).
    replace ((a * a) + (b * b))%R with ((b * b) + (a * a))%R by ring.
    replace ((a * a) + (- (a * a)))%R with 0%R by ring.
    exact Hadd. }
  assert (Hle2 : (- (a * a) <= 0)%R) by lra.
  assert (Hle : (b * b <= 0)%R) by exact (Rle_trans (b * b) (- (a * a)) 0 Hle1 Hle2).
  apply Rsqr_0_uniq.
  apply Rle_antisym; auto.
Qed.

(* Cnorm_sq C0 = 0 *)
Lemma Cnorm_sq_C0 : (Cnorm_sq C0)%R = 0%R.
Proof.
  unfold Cnorm_sq, C0. simpl. unfold Rsqr. ring.
Qed.

(* Σ_{k≤n} 0 = 0 *)
Lemma sum_f_R0_zero (n : nat) : (sum_f_R0 (fun _ : nat => 0%R) n)%R = 0%R.
Proof.
  induction n; simpl; [auto | rewrite IHn; lra].
Qed.

(* 双原子组合的范数平方展开（实系数 c1 c2）：
   ‖c1·u1 + c2·u2‖²_W
   = c1²‖u1‖²_W + c2²‖u2‖²_W + 2·c1·c2·⟨u1,u2⟩_W *)
Theorem norm_sq_combo2 (u1 u2 : nat -> Complex) (c1 c2 : R) (W : nat) :
  (l2_norm_sq (fun k => Cof_real c1 *c u1 k +c Cof_real c2 *c u2 k) W)%R
  = ((c1 * c1) * l2_norm_sq u1 W
     + (c2 * c2) * l2_norm_sq u2 W
     + 2 * (c1 * c2) * ipW u1 u2 W)%R.
Proof.
  unfold l2_norm_sq.
  assert (Hext : forall k : nat, (Cnorm_sq (Cof_real c1 *c u1 k +c Cof_real c2 *c u2 k)
        = ((c1 * c1) * Cnorm_sq (u1 k) + (c2 * c2) * Cnorm_sq (u2 k)
           + 2 * (c1 * c2) * re (u1 k *c Cconj (u2 k)))%R))
    by (intro k; apply norm_sq_combo2_point).
  rewrite (sum_f_R0_ext _ (fun k => ((c1 * c1) * Cnorm_sq (u1 k)
                                     + (c2 * c2) * Cnorm_sq (u2 k)
                                     + 2 * (c1 * c2) * re (u1 k *c Cconj (u2 k)))%R) W Hext).
  unfold ipW.
  setoid_rewrite (sum_f_R0_plus (fun k => ((c1 * c1) * Cnorm_sq (u1 k)
                                            + (c2 * c2) * Cnorm_sq (u2 k))%R)
                               (fun k => (2 * (c1 * c2) * re (u1 k *c Cconj (u2 k)))%R) W).
  setoid_rewrite (sum_f_R0_plus (fun k => ((c1 * c1) * Cnorm_sq (u1 k))%R)
                               (fun k => ((c2 * c2) * Cnorm_sq (u2 k))%R) W).
  setoid_rewrite (sum_f_R0_scal (c1 * c1) (fun k => Cnorm_sq (u1 k)) W).
  setoid_rewrite (sum_f_R0_scal (c2 * c2) (fun k => Cnorm_sq (u2 k)) W).
  setoid_rewrite (sum_f_R0_scal (2 * (c1 * c2)) (fun k => re (u1 k *c Cconj (u2 k))) W).
  ring.
Qed.

(* CS-3a 核心：2 原子词典的稀疏唯一性。
   单位范数原子、|⟨u1,u2⟩_W| ≤ μ、μ < 1，且 c1·u1+c2·u2 ≡ 0（窗口内）⟹ c1 = c2 = 0。 *)
Theorem sparse_uniqueness2 (u1 u2 : nat -> Complex) (W : nat) (c1 c2 mu : R) :
  (l2_norm_sq u1 W)%R = 1%R ->
  (l2_norm_sq u2 W)%R = 1%R ->
  ((Rabs (ipW u1 u2 W)) <= mu)%R ->
  (mu < 1)%R ->
  (forall k, (k <= W)%nat -> (Cof_real c1 *c u1 k +c Cof_real c2 *c u2 k = C0)%C) ->
  (c1 = 0)%R /\ (c2 = 0)%R.
Proof.
  intros Hu1 Hu2 Hmu Hmu1 Hzero.
  (* 0 = ‖c1u1+c2u2‖²_W（每点为零 ⟹ Cnorm_sq C0 = 0 ⟹ 和为 0） *)
  assert (Hcombo : (l2_norm_sq (fun k => Cof_real c1 *c u1 k +c Cof_real c2 *c u2 k) W)%R = 0%R).
  { unfold l2_norm_sq.
    assert (Hext1 : forall k : nat, (k <= W)%nat -> (Cnorm_sq (Cof_real c1 *c u1 k +c Cof_real c2 *c u2 k) = Cnorm_sq C0)%R)
      by (intro k; intro Hk; f_equal; exact (Hzero k Hk)).
    rewrite (Incoherence.sum_f_R0_ext_bounded _ (fun _ => Cnorm_sq C0) W Hext1).
    assert (Hzsum : (sum_f_R0 (fun _ : nat => Cnorm_sq C0) W)%R = 0%R).
    { assert (Hext2 : forall k : nat, (k <= W)%nat -> (Cnorm_sq C0 = 0)%R)
        by (intro k; intro Hk; exact Cnorm_sq_C0).
      rewrite (Incoherence.sum_f_R0_ext_bounded _ (fun _ => 0%R) W Hext2).
      exact (sum_f_R0_zero W). }
    rewrite Hzsum. reflexivity. }
  (* 用 norm_sq_combo2 + Hu1/Hu2 归约 *)
  rewrite norm_sq_combo2 in Hcombo.
  rewrite Hu1 Hu2 in Hcombo.
  replace ((c1 * c1) * 1 + (c2 * c2) * 1 + 2 * (c1 * c2) * ipW u1 u2 W)%R
    with ((c1 * c1) + (c2 * c2) + 2 * (c1 * c2) * ipW u1 u2 W)%R in Hcombo by ring.
  (* c1²+c2² = −(2·c1c2·⟨u1,u2⟩) *)
  assert (Hmain : ((c1 * c1) + (c2 * c2) = - (2 * (c1 * c2) * ipW u1 u2 W))%R).
  { apply Rplus_eq_reg_l with (2 * (c1 * c2) * ipW u1 u2 W)%R.
    replace ((2 * (c1 * c2) * ipW u1 u2 W) + ((c1 * c1) + (c2 * c2)))%R
      with ((c1 * c1) + (c2 * c2) + 2 * (c1 * c2) * ipW u1 u2 W)%R by ring.
    rewrite Hcombo. ring. }
  (* |c1²+c2²| = |2c1c2·⟨⟩| ≤ 2|c1c2|·μ ≤ μ·(c1²+c2²) *)
  assert (Habs : ((Rabs (2 * (c1 * c2) * ipW u1 u2 W)) <= (mu * ((c1 * c1) + (c2 * c2))))%R).
  { rewrite (Rabs_mult (2 * (c1 * c2)) (ipW u1 u2 W)).
    rewrite (Rabs_2_mult (c1 * c2)).
    (* 2|c1c2|·|⟨⟩| ≤ 2|c1c2|·μ（因 |⟨⟩|≤μ） *)
    transitivity (2 * Rabs (c1 * c2) * mu)%R.
    - apply Rmult_le_compat_l.
      + apply Rmult_le_pos; [lra | apply Rabs_pos].
      + exact Hmu.
    - (* 2|c1c2|·μ ≤ μ·(c1²+c2²)（因 2|c1c2|≤c1²+c2² 且 μ≥0） *)
      assert (Hmu0 : (0 <= mu)%R).
      { apply (Rle_trans _ (Rabs (ipW u1 u2 W)) _); [apply Rabs_pos | exact Hmu]. }
      replace (2 * Rabs (c1 * c2) * mu)%R with (mu * (2 * Rabs (c1 * c2)))%R by ring.
      apply Rmult_le_compat_l; [exact Hmu0 | exact (Rabs_prod_le_sq_sum c1 c2)]. }
  (* c1²+c2² = |c1²+c2²| ≤ μ(c1²+c2²)（因 c1²+c2² ≥ 0） *)
  assert (Hnonneg : (0 <= (c1 * c1) + (c2 * c2))%R).
  { apply Rplus_le_le_0_compat; apply Rle_0_sqr. }
  assert (Hc : ((c1 * c1) + (c2 * c2) <= mu * ((c1 * c1) + (c2 * c2)))%R).
  { (* |c1²+c2²| = |−(2c1c2⟨⟩)| = |2c1c2⟨⟩| ≤ μ(c1²+c2²)；再因 c1²+c2² ≥ 0 去绝对值 *)
    assert (Habs' : (Rabs ((c1 * c1) + (c2 * c2)) <= mu * ((c1 * c1) + (c2 * c2)))%R).
    { replace (Rabs ((c1 * c1) + (c2 * c2)))%R
        with (Rabs (2 * (c1 * c2) * ipW u1 u2 W))%R.
      - exact Habs.
      - rewrite Hmain. rewrite Rabs_opp. reflexivity. }
    rewrite (Rabs_pos_eq ((c1 * c1) + (c2 * c2)) Hnonneg) in Habs'.
    exact Habs'. }
  (* μ<1 ⟹ c1²+c2²=0：S ≤ μS ⟹ (1−μ)S ≤ 0，且 1−μ > 0、S ≥ 0 ⟹ S = 0 *)
  assert (Hsq : ((c1 * c1) + (c2 * c2) = 0)%R).
  { apply Rle_antisym.
    - (* S ≤ 0：由 (1−μ)S ≤ 0 与 (1−μ) > 0 相除 *)
      assert (H1m : (0 < 1 - mu)%R) by lra.
      assert (Hprod : ((1 - mu) * ((c1 * c1) + (c2 * c2)) <= 0)%R).
      { replace ((1 - mu) * ((c1 * c1) + (c2 * c2)))%R
          with (((c1 * c1) + (c2 * c2)) - mu * ((c1 * c1) + (c2 * c2)))%R by ring.
        lra. }
      assert (Hpos : (0 <= (1 - mu))%R) by lra.
      (* 从 (1−μ)S ≤ 0 且 (1−μ) > 0 得 S ≤ 0：用 Rmult_le_reg_l *)
      apply (Rmult_le_reg_l (1 - mu) ((c1 * c1) + (c2 * c2)) 0 H1m).
      replace ((1 - mu) * 0)%R with 0%R by ring.
      exact Hprod.
    - exact Hnonneg. }
  split.
  - apply (sq_sum_zero_l c1 c2). exact Hsq.
  - apply (sq_sum_zero_r c1 c2). exact Hsq.
Qed.

(* CS-2（2 原子版）：RIP 型界
   |‖c1u1+c2u2‖²_W − (c1²+c2²)| ≤ μ·(c1²+c2²)（单位原子、|⟨⟩|≤μ） *)
Theorem rip_bound2 (u1 u2 : nat -> Complex) (W : nat) (c1 c2 mu : R) :
  (l2_norm_sq u1 W)%R = 1%R ->
  (l2_norm_sq u2 W)%R = 1%R ->
  ((Rabs (ipW u1 u2 W)) <= mu)%R ->
  ((Rabs ((l2_norm_sq (fun k => Cof_real c1 *c u1 k +c Cof_real c2 *c u2 k) W)%R
          - ((c1 * c1) + (c2 * c2))%R)) <= (mu * ((c1 * c1) + (c2 * c2))))%R.
Proof.
  intros Hu1 Hu2 Hmu.
  rewrite norm_sq_combo2.
  rewrite Hu1 Hu2.
  replace ((c1 * c1) * 1 + (c2 * c2) * 1 + 2 * (c1 * c2) * ipW u1 u2 W)%R
    with ((c1 * c1) + (c2 * c2) + 2 * (c1 * c2) * ipW u1 u2 W)%R by ring.
  replace (((c1 * c1) + (c2 * c2) + 2 * (c1 * c2) * ipW u1 u2 W) - ((c1 * c1) + (c2 * c2)))%R
    with (2 * (c1 * c2) * ipW u1 u2 W)%R by ring.
  rewrite (Rabs_mult (2 * (c1 * c2)) (ipW u1 u2 W)).
  rewrite (Rabs_2_mult (c1 * c2)).
  transitivity (2 * Rabs (c1 * c2) * mu)%R.
  - apply Rmult_le_compat_l.
    + apply Rmult_le_pos; [lra | apply Rabs_pos].
    + exact Hmu.
  - assert (Hmu0 : (0 <= mu)%R).
    { apply (Rle_trans _ (Rabs (ipW u1 u2 W)) _); [apply Rabs_pos | exact Hmu]. }
    replace (2 * Rabs (c1 * c2) * mu)%R with (mu * (2 * Rabs (c1 * c2)))%R by ring.
    apply Rmult_le_compat_l; [exact Hmu0 | exact (Rabs_prod_le_sq_sum c1 c2)].
Qed.

(* ============================================================
   —— comboM（Σ_{j<M} c_j·u_j）+ ipW 线性提取。
   ============================================================ *)

(* M 原子组合：Σ_{j<M} c_j·u_j（点 k 处） *)
Definition comboM (M : nat) (c : nat -> R) (u : nat -> nat -> Complex) (k : nat) : Complex :=
  PrimeEmbedding.Csum (fun j => Cof_real (c j) *c u j k) M.

(* ipW 常零 = 0 *)
Lemma ipW_C0 (v : nat -> Complex) (W : nat) : (ipW (fun _ => C0) v W)%R = 0%R.
Proof.
  unfold ipW.
  assert (Hext : forall k : nat, (re (C0 *c Cconj (v k)) = 0)%R) by (intro k; unfold Cmul, C0; simpl; ring).
  rewrite (sum_f_R0_ext _ (fun _ => 0)%R W Hext).
  induction W; simpl; [auto | rewrite IHW; lra].
Qed.

(* 递归步（函数等式）：comboM (S M) = comboM M +c c_M·u_M *)
Lemma comboM_step (M : nat) (c : nat -> R) (u : nat -> nat -> Complex) :
  comboM (S M) c u = fun k : nat => comboM M c u k +c Cof_real (c M) *c u M k.
Proof.
  apply functional_extensionality. intro k.
  unfold comboM. simpl.
  change (PrimeEmbedding.Csum (fun j => Cof_real (c j) *c u j k) (S M))
    with (Cof_real (c M) *c u M k +c PrimeEmbedding.Csum (fun j => Cof_real (c j) *c u j k) M).
  rewrite Cadd_comm. reflexivity.
Qed.

(* comboM 1 = 单原子（0 下标） *)
Lemma comboM_one (c : nat -> R) (u : nat -> nat -> Complex) :
  comboM 1%nat c u = fun k : nat => Cof_real (c 0%nat) *c u 0%nat k.
Proof.
  apply functional_extensionality. intro k.
  unfold comboM. simpl.
  apply Cadd_0_r.
Qed.

(* 线性提取：⟨Σ_{j≤M} c_j·u_j, v⟩ = Σ_{j≤M} c_j·⟨u_j, v⟩ *)
Lemma ipW_combo_l (M : nat) (c : nat -> R) (u : nat -> nat -> Complex) (v : nat -> Complex) (W : nat) :
  (ipW (comboM (S M) c u) v W)%R
  = (sum_f_R0 (fun j => c j * ipW (u j) v W) M)%R.
Proof.
  induction M as [| M IH].
  - unfold comboM. simpl.
    rewrite (ipW_add_l (fun k => Cof_real (c 0) *c u 0 k) (fun _ => C0) v W).
    rewrite (ipW_CR_l (c 0) (u 0) v W).
    rewrite ipW_C0. ring.
  - rewrite (comboM_step (S M) c u).
    rewrite ipW_add_l.
    rewrite (ipW_CR_l (c (S M)) (u (S M)) v W).
    rewrite IH.
    simpl. reflexivity.
Qed.

(* 递归范数展开：l2(comboM (S (S M))) = l2(comboM (S M)) + c²_{SM}·l2(u_{SM}) + 2·c_{SM}·⟨comboM (S M), u_{SM}⟩ *)
Lemma norm_sq_comboM_rec (M : nat) (c : nat -> R) (u : nat -> nat -> Complex) (W : nat) :
  (l2_norm_sq (comboM (S (S M)) c u) W)%R
  = ((l2_norm_sq (comboM (S M) c u) W)
     + (c (S M)) * (c (S M)) * (l2_norm_sq (u (S M)) W)
     + 2 * (c (S M)) * (ipW (comboM (S M) c u) (u (S M)) W))%R.
Proof.
  rewrite (comboM_step (S M) c u).
  (* l2_norm_sq (fun k => comboM (S M) c u k +c Cof_real (c (S M)) *c u (S M) k) W。
     用 norm_sq_combo2 于 (u1 := comboM (S M) c u, u2 := u (S M), c1 := 1, c2 := c (S M))，
     需先把 +c 项改写为 Cof_real 1 *c comboM +c Cof_real c *c u 形式。 *)
  replace (fun k : nat => comboM (S M) c u k +c Cof_real (c (S M)) *c u (S M) k)
    with (fun k : nat => Cof_real 1 *c comboM (S M) c u k +c Cof_real (c (S M)) *c u (S M) k).
  2: {
    apply functional_extensionality. intro k.
    replace (Cof_real 1 *c comboM (S M) c u k)%C with (comboM (S M) c u k)%C.
    - reflexivity.
    - apply Complex_eq; simpl; ring.
  }
  rewrite (norm_sq_combo2 (comboM (S M) c u) (u (S M)) 1 (c (S M)) W).
  replace ((1 * 1) * l2_norm_sq (comboM (S M) c u) W)%R
    with (l2_norm_sq (comboM (S M) c u) W)%R by ring.
  ring.
Qed.

(* 逐项 ≤ ⟹ 和 ≤（sum_f_R0 保序） *)
Lemma sum_f_R0_le (f g : nat -> R) (n : nat) :
  (forall k, (k <= n)%nat -> (f k <= g k)%R) ->
  (sum_f_R0 f n <= sum_f_R0 g n)%R.
Proof.
  intros H. induction n as [| n IH].
  - apply H. by apply leqnn.
  - simpl. apply Rplus_le_compat.
    + apply IH. intros k Hk. apply H. exact (leq_trans Hk (leqnSn n)).
    + apply H. by apply leqnn.
Qed.

(* 三角不等式：|Σ_{k≤n} f k| ≤ Σ_{k≤n} |f k| *)
Lemma sum_f_R0_abs (f : nat -> R) (n : nat) :
  (Rabs (sum_f_R0 f n) <= sum_f_R0 (fun k => Rabs (f k)) n)%R.
Proof.
  induction n as [| n IH].
  - simpl. apply Rle_refl.
  - simpl. apply Rle_trans with (Rabs (sum_f_R0 f n) + Rabs (f (S n)))%R.
    + apply Rabs_triang.
    + apply Rplus_le_compat; [exact IH | apply Rle_refl].
Qed.

(* 交叉项界：|⟨comboM (S M) c u, u (S M)⟩| ≤ μ·Σ_{j≤M}|c_j|（两两相干 ≤ μ） *)
Lemma cross_abs_le (M : nat) (c : nat -> R) (u : nat -> nat -> Complex) (W : nat) (mu : R) :
  (forall i j, i <= S M -> j <= S M -> i <> j ->
    (Rabs (ipW (u i) (u j) W) <= mu)%R) ->
  ((Rabs (ipW (comboM (S M) c u) (u (S M)) W))
   <= (mu * sum_f_R0 (fun j : nat => Rabs (c j)) M))%R.
Proof.
  intros Hcoh.
  rewrite ipW_combo_l.
  apply (Rle_trans _ (sum_f_R0 (fun j : nat => (Rabs (c j) * Rabs (ipW (u j) (u (S M)) W))%R) M)%R).
  - eapply Rle_trans.
    + apply sum_f_R0_abs.
    + assert (Hext : forall j : nat, (Rabs (c j * ipW (u j) (u (S M)) W) = Rabs (c j) * Rabs (ipW (u j) (u (S M)) W))%R)
        by (intro j; apply Rabs_mult).
      rewrite (sum_f_R0_ext _ (fun j : nat => (Rabs (c j) * Rabs (ipW (u j) (u (S M)) W))%R) M Hext).
      apply Rle_refl.
  - apply (Rle_trans _ (sum_f_R0 (fun j : nat => (Rabs (c j) * mu)%R) M)%R).
    + apply sum_f_R0_le. intros k Hk.
      apply Rmult_le_compat_l; [apply Rabs_pos | ].
      apply Hcoh.
      - exact (leq_trans Hk (leqnSn M)).
      - by apply leqnn.
      - move: Hk => /leP Hkp. lia.
    + assert (Hext : forall j : nat, (Rabs (c j) * mu = mu * Rabs (c j))%R) by (intro j; ring).
      rewrite (sum_f_R0_ext _ (fun j : nat => (mu * Rabs (c j))%R) M Hext).
      rewrite <- (sum_f_R0_scal mu (fun j : nat => Rabs (c j)) M).
      apply Rle_refl.
Qed.

(* 2|a||b| ≤ a²+b²（AM-GM，从 Rabs_prod_le_sq_sum 变形） *)
Lemma abs_prod_le_sq (a b : R) : ((2%R * Rabs a * Rabs b) <= (a * a + b * b))%R.
Proof.
  replace (2%R * Rabs a * Rabs b)%R with (2%R * Rabs (a * b))%R by
    (rewrite Rabs_mult; ring).
  exact (Rabs_prod_le_sq_sum a b).
Qed.

(* Σ_{j≤M} c_j² 的部分和分解：S_{SM} = S_M + c_{SM}² *)
Lemma sq_sum_step (c : nat -> R) (M : nat) :
  (sum_f_R0 (fun j : nat => c j * c j) (S M))%R
  = ((sum_f_R0 (fun j : nat => c j * c j) M) + c (S M) * c (S M))%R.
Proof. simpl. ring. Qed.

(* 逐项夹：2·|a|·|c_j| ≤ a² + c_j² 对 j ≤ M 求和：
   2·|a|·Σ_{j≤M}|c_j| ≤ (M+1)·a² + Σ_{j≤M}c_j² *)
Lemma sum_abs_cross_le (M : nat) (a : R) (c : nat -> R) :
  ((2%R * Rabs a * sum_f_R0 (fun j : nat => Rabs (c j)) M)
   <= ((INR (S M)) * (a * a) + sum_f_R0 (fun j : nat => c j * c j) M))%R.
Proof.
  rewrite <- (sum_f_R0_scal (2%R * Rabs a) (fun j : nat => Rabs (c j)) M).
  apply (Rle_trans _ (sum_f_R0 (fun j : nat => ((a * a) + c j * c j)%R) M)%R).
  - apply sum_f_R0_le. intros k Hk.
    apply (Rle_trans _ (a * a + c k * c k)%R).
    + exact (abs_prod_le_sq a (c k)).
    + apply Rle_refl.
  - setoid_rewrite (sum_f_R0_plus (fun _ : nat => (a * a)%R) (fun j : nat => (c j * c j)%R) M).
    assert (Hext : forall k : nat, (a * a = (a * a) * 1)%R) by (intro k; ring).
    setoid_rewrite (sum_f_R0_ext _ (fun _ : nat => ((a * a) * 1)%R) M Hext).
    setoid_rewrite (sum_f_R0_scal (a * a) (fun _ : nat => 1%R) M).
    setoid_rewrite (sum_f_R0_const M).
    lra.
Qed.

(* ============================================================
   —— rip_lower_M（RIP 下界，归纳）+ sparse_uniquenessM（最终定理）。
   证明链：norm_sq_comboM_rec（递归展开）+ cross_abs_le（交叉项界）
   + sum_abs_cross_le（AM-GM 聚合）+ 系数 INR 单调。
   ============================================================ *)

(* Σ_{j≤M} c_j² ≥ 0（平方和非负，独立引理避免嵌套归纳） *)
Lemma sum_sq_nonneg (c : nat -> R) (M : nat) :
  (0 <= sum_f_R0 (fun j : nat => c j * c j) M)%R.
Proof.
  induction M; simpl; [apply Rle_0_sqr | apply Rplus_le_le_0_compat; [exact IHM | apply Rle_0_sqr]].
Qed.

Lemma INR_succ_mul (mu sv : R) (M : nat) :
  (mu * sv + mu * INR (S M) * sv = mu * INR (S (S M)) * sv)%R.
Proof.
  set (N := (INR (S M))%R).
  replace (INR (S (S M)))%R with (N + 1)%R.
  - ring.
  - subst N. symmetry. exact (S_INR (S M)).
Qed.

(* 最终夹逼：纯原子 lra（INR 值作为变量，避开 Coq 对 INR (S(SM)) 与 INR (SM) 的模式匹配冲突） *)
Lemma final_squeeze (Lp Sv A2 Yv mS mN1S mN2S mN1A mN2A : R) :
  (Sv + A2 <= Lp + Yv + mN1S)%R ->
  (Yv <= mN1A + mS)%R ->
  (mS + mN1S = mN2S)%R ->
  (mN1A <= mN2A)%R ->
  (Sv + A2 <= Lp + mN2S + mN2A)%R.
Proof. intros. lra. Qed.

(* 最终夹逼：纯原子 nra（N1/N2 为 INR 值变量，避开 INR 模式匹配冲突） *)
Lemma rip_final (L A2 Sv IP Yv mu N1 N2 : R) :
  (0 <= mu)%R -> (0 <= A2)%R -> (0 <= Sv)%R ->
  (Sv + A2 <= L + A2 + 2 * IP + Yv + mu * N1 * Sv)%R ->
  (Yv <= mu * (N1 * A2 + Sv))%R ->
  (N2 = N1 + 1)%R ->
  (mu * N1 * A2 <= mu * N2 * A2)%R ->
  (Sv + A2 <= L + A2 + 2 * IP + mu * N2 * (Sv + A2))%R.
Proof. intros. nra. Qed.

(* RIP 下界（归纳）：Σ_{j≤M}c_j² ≤ l2(comboM (S M)) + μ·(M+1)·Σ_{j≤M}c_j² *)
Lemma rip_lower_M (M : nat) (c : nat -> R) (u : nat -> nat -> Complex) (W : nat) (mu : R) :
  (0 <= mu)%R ->
  (forall j, j <= M -> (l2_norm_sq (u j) W)%R = 1%R) ->
  (forall i j, i <= M -> j <= M -> i <> j ->
    (Rabs (ipW (u i) (u j) W) <= mu)%R) ->
  ((sum_f_R0 (fun j : nat => c j * c j) M)
   <= (l2_norm_sq (comboM (S M) c u) W
       + mu * INR (S M) * sum_f_R0 (fun j : nat => c j * c j) M))%R.
Proof.
  intros Hmu0.
  induction M as [| M IH].
  - (* M=0：单原子。S_0 = c_0²，l2(comboM 1) = c_0²·l2(u_0) = c_0² *)
    intros Hunit Hcoh.
    assert (Hu : (l2_norm_sq (u 0%nat) W)%R = 1%R) by (apply Hunit; by apply leqnn).
    change (sum_f_R0 (fun j : nat => c j * c j) 0)%R with (c 0%nat * c 0%nat)%R.
    rewrite (comboM_one c u).
    rewrite l2_norm_sq_scale.
    rewrite Incoherence.Cnorm_sq_Cof_real.
    rewrite Hu.
    replace ((c 0%nat * c 0%nat) * 1)%R with (c 0%nat * c 0%nat)%R by ring.
    replace (INR (S 0))%R with 1%R by (simpl; auto).
    assert (Hsq0 : (0 <= c 0%nat * c 0%nat)%R) by apply Rle_0_sqr.
    assert (Hm : (0 <= mu * (c 0%nat * c 0%nat))%R)
      by (apply Rmult_le_pos; [exact Hmu0 | exact Hsq0]).
    replace (mu * 1%R * (c 0%nat * c 0%nat))%R with (mu * (c 0%nat * c 0%nat))%R by ring.
    lra.
  - (* 归纳步 *)
    intros Hunit Hcoh.
    rewrite (sq_sum_step c M).
    rewrite (norm_sq_comboM_rec M c u W).
    assert (Hu' : (l2_norm_sq (u (S M)) W)%R = 1%R) by (apply Hunit; by apply leqnn).
    rewrite Hu'.
    replace ((c (S M) * c (S M)) * 1)%R with (c (S M) * c (S M))%R by ring.
    replace (2 * c (S M) * ipW (comboM (S M) c u) (u (S M)) W)%R
      with (2 * (c (S M) * ipW (comboM (S M) c u) (u (S M)) W))%R by ring.
    (* 记 S := Σ_{j≤M}c_j²，A := c(SM)，IP := ipW(comboM(SM),u(SM))，L := l2(comboM(SM))。
       目标：S + A² ≤ L + A² + 2A·IP + μ(M+2)(S + A²)。 *)
    (* IH（截取到 ≤ M）：S ≤ L + μ(M+1)S *)
    assert (HIH' : ((sum_f_R0 (fun j : nat => c j * c j) M)
        <= (l2_norm_sq (comboM (S M) c u) W)
           + mu * INR (S M) * sum_f_R0 (fun j : nat => c j * c j) M)%R).
    { exact (IH
        (fun j Hj => Hunit j (leq_trans Hj (leqnSn M)))
        (fun i j Hij Hji Hne => Hcoh i j (leq_trans Hij (leqnSn M)) (leq_trans Hji (leqnSn M)) Hne)). }
    (* cross_abs_le：|IP| ≤ μ·Σ_{j≤M}|c_j| *)
    assert (Hcross := cross_abs_le M c u W mu
      (fun i j Hij Hji Hne => Hcoh i j Hij Hji Hne)).
    (* 第一步：S + A² ≤ L + A² + 2A·IP + 2|A||IP| + μ(M+1)S
       即 S ≤ L + 2A·IP + 2|A||IP| + μ(M+1)S（由 HIH' + 2A·IP ≥ −2|A||IP|） *)
    assert (H1 : ((sum_f_R0 (fun j : nat => c j * c j) M)
        <= (l2_norm_sq (comboM (S M) c u) W)
           + 2 * (c (S M)) * ipW (comboM (S M) c u) (u (S M)) W
           + 2 * Rabs (c (S M)) * Rabs (ipW (comboM (S M) c u) (u (S M)) W)
           + mu * INR (S M) * sum_f_R0 (fun j : nat => c j * c j) M)%R).
    { (* 记 X := 2A·IP，Y := 2|A||IP|，M1 := μ(M+1)S。HIH' : S ≤ L + M1。
         目标 S ≤ L + X + Y + M1。由 HIH' 与 0 ≤ X + Y（Hneg 给出 −X ≤ Y ⟹ X+Y ≥ 0）。 *)
      set (X := (2 * (c (S M)) * ipW (comboM (S M) c u) (u (S M)) W)%R).
      set (Y := (2 * Rabs (c (S M)) * Rabs (ipW (comboM (S M) c u) (u (S M)) W))%R).
      set (M1 := (mu * INR (S M) * sum_f_R0 (fun j : nat => c j * c j) M)%R).
      assert (Hneg : (- X <= Y)%R).
      { unfold X, Y.
        apply (Rle_trans _ (Rabs (2 * (c (S M)) * ipW (comboM (S M) c u) (u (S M)) W))%R).
        - apply (Rle_trans _ (Rabs (- (2 * (c (S M)) * ipW (comboM (S M) c u) (u (S M)) W)))%R).
          + apply Rle_abs.
          + rewrite Rabs_opp. apply Rle_refl.
        - replace (Rabs (2 * (c (S M)) * ipW (comboM (S M) c u) (u (S M)) W))%R
            with (2 * Rabs (c (S M)) * Rabs (ipW (comboM (S M) c u) (u (S M)) W))%R.
          + apply Rle_refl.
          + rewrite Rabs_mult. rewrite Rabs_mult.
            replace (Rabs 2)%R with 2%R by (rewrite (Rabs_right 2 (Rle_ge 0 2 (Rlt_le 0 2 Rlt_0_2))); ring).
            ring. }
      assert (Hnonneg : (0 <= X + Y)%R) by lra.
      (* 目标：S ≤ L + X + Y + M1。HIH' : S ≤ L + M1。由 Hnonneg：M1 ≤ X + Y + M1。 *)
      eapply Rle_trans.
      - exact HIH'.
      - (* L + M1 ≤ L + X + Y + M1：需 M1 ≤ X + Y + M1，即 0 ≤ X + Y *)
        subst X Y M1. lra. }
    (* 第二步：2|A||IP| ≤ 2|A|·μ·Σ|c_j|（cross_abs_le 乘 2|A| ≥ 0） *)
    assert (H2 : (2 * Rabs (c (S M)) * Rabs (ipW (comboM (S M) c u) (u (S M)) W)
        <= 2 * Rabs (c (S M)) * (mu * sum_f_R0 (fun j : nat => Rabs (c j)) M))%R).
    { apply Rmult_le_compat_l.
      - apply Rmult_le_pos; [lra | apply Rabs_pos].
      - exact Hcross. }
    (* 第三步：2|A|·μ·Σ|c_j| ≤ μ·((M+1)A² + S)（sum_abs_cross_le 乘 mu ≥ 0） *)
    assert (H3 : (2 * Rabs (c (S M)) * (mu * sum_f_R0 (fun j : nat => Rabs (c j)) M)
        <= mu * ((INR (S M)) * (c (S M) * c (S M)) + sum_f_R0 (fun j : nat => c j * c j) M))%R).
    { replace (2 * Rabs (c (S M)) * (mu * sum_f_R0 (fun j : nat => Rabs (c j)) M))%R
        with (mu * (2 * Rabs (c (S M)) * sum_f_R0 (fun j : nat => Rabs (c j)) M))%R by ring.
      apply Rmult_le_compat_l; [exact Hmu0 | exact (sum_abs_cross_le M (c (S M)) c)]. }
    (* 组装：目标 S + A² ≤ L' + μ(M+2)(S + A²)，L' = l2(comboM (S(SM))) = L + A² + 2A·IP。
       链条：
       S + A² ≤ L + A² + μ(M+1)S            [HIH' 加 A²]
             = L' − 2A·IP + μ(M+1)S         [L' = L + A² + 2A·IP]
             ≤ L' + 2|A||IP| + μ(M+1)S      [−2A·IP ≤ 2|A||IP|]
             ≤ L' + μ((M+1)A² + S) + μ(M+1)S  [H2'：2|A||IP| ≤ μ((M+1)A²+S)]
             = L' + μ(M+1)A² + μ(M+2)S      [代数]
             ≤ L' + μ(M+2)A² + μ(M+2)S      [HmA：μ(M+1)A² ≤ μ(M+2)A²]
             = 目标（μ(M+2)(S+A²)）。 *)
    (* 第一步：S + A² ≤ L' + 2|A||IP| + μ(M+1)S *)
    assert (H1L : ((sum_f_R0 (fun j : nat => c j * c j) M) + c (S M) * c (S M)
        <= (l2_norm_sq (comboM (S (S M)) c u) W)
           + 2 * Rabs (c (S M)) * Rabs (ipW (comboM (S M) c u) (u (S M)) W)
           + mu * INR (S M) * sum_f_R0 (fun j : nat => c j * c j) M)%R).
    { (* 由 HIH'（S ≤ L + μ(M+1)S）加 A²：S + A² ≤ L + A² + μ(M+1)S。
         L' = L + A² + 2A·IP（norm_sq_comboM_rec 反向）。代入：
         L + A² + μ(M+1)S = L' − 2A·IP + μ(M+1)S ≤ L' + 2|A||IP| + μ(M+1)S。 *)
      eapply Rle_trans.
      - (* S + A² ≤ L + A² + μ(M+1)S *)
        apply Rplus_le_compat_r. exact HIH'.
      - (* L + A² + μ(M+1)S ≤ L' + 2|A||IP| + μ(M+1)S。
           L' = L + A² + 2A·IP ⟹ L + A² = L' − 2A·IP。需 −2A·IP ≤ 2|A||IP|。 *)
        rewrite (norm_sq_comboM_rec M c u W).
        rewrite Hu'.
        replace ((c (S M) * c (S M)) * 1)%R with (c (S M) * c (S M))%R by ring.
        (* 目标：L + A² + μ(M+1)S ≤ L + A² + 2A·IP + 2|A||IP| + μ(M+1)S。
           消去 L + A² + μ(M+1)S：需 0 ≤ 2A·IP + 2|A||IP|。 *)
        assert (Hneg : (- (2 * (c (S M)) * ipW (comboM (S M) c u) (u (S M)) W)
            <= 2 * Rabs (c (S M)) * Rabs (ipW (comboM (S M) c u) (u (S M)) W))%R).
        { apply (Rle_trans _ (Rabs (2 * (c (S M)) * ipW (comboM (S M) c u) (u (S M)) W))%R).
          - apply (Rle_trans _ (Rabs (- (2 * (c (S M)) * ipW (comboM (S M) c u) (u (S M)) W)))%R).
            + apply Rle_abs.
            + rewrite Rabs_opp. apply Rle_refl.
          - replace (Rabs (2 * (c (S M)) * ipW (comboM (S M) c u) (u (S M)) W))%R
              with (2 * Rabs (c (S M)) * Rabs (ipW (comboM (S M) c u) (u (S M)) W))%R.
            + apply Rle_refl.
            + rewrite Rabs_mult. rewrite Rabs_mult.
              replace (Rabs 2)%R with 2%R by (rewrite (Rabs_right 2 (Rle_ge 0 2 (Rlt_le 0 2 Rlt_0_2))); ring).
              ring. }
        lra. }
    (* 第二步：H2' : 2|A||IP| ≤ μ((M+1)A² + S)（H2 + H3 合成） *)
    assert (H2' : (2 * Rabs (c (S M)) * Rabs (ipW (comboM (S M) c u) (u (S M)) W)
        <= mu * ((INR (S M)) * (c (S M) * c (S M)) + sum_f_R0 (fun j : nat => c j * c j) M))%R).
    { eapply Rle_trans; [exact H2 | exact H3]. }
    (* 组装最终链：展开 H1L 的 Lp，用 rip_final（纯 nra）一步收尾。 *)
    assert (HA2 : (0 <= c (S M) * c (S M))%R) by apply Rle_0_sqr.
    assert (HS' : (0 <= sum_f_R0 (fun j : nat => c j * c j) M)%R).
    { exact (sum_sq_nonneg c M). }
    (* μ(M+1)A² ≤ μ(M+2)A² *)
    assert (HmA : (mu * INR (S M) * (c (S M) * c (S M))
        <= mu * INR (S (S M)) * (c (S M) * c (S M)))%R).
    { apply Rmult_le_compat_r.
      - exact HA2.
      - apply Rmult_le_compat_l.
        + exact Hmu0.
        + apply le_INR. lia. }
    (* 展开 H1L 的 Lp（l2(comboM(S(SM))) = L + A² + 2A·IP，norm_sq_comboM_rec + Hu'） *)
    rewrite (norm_sq_comboM_rec M c u W) in H1L.
    rewrite Hu' in H1L.
    replace ((c (S M) * c (S M)) * 1)%R with (c (S M) * c (S M))%R in H1L by ring.
    replace (2 * c (S M) * ipW (comboM (S M) c u) (u (S M)) W)%R
      with (2 * (c (S M) * ipW (comboM (S M) c u) (u (S M)) W))%R in H1L by ring.
    (* 目标：S + A2 ≤ L + A2 + 2A·IP + mu·INR(S(SM))·(S+A2)。用 rip_final。 *)
    apply (rip_final (l2_norm_sq (comboM (S M) c u) W)
                     (c (S M) * c (S M))
                     (sum_f_R0 (fun j : nat => (c j * c j)%R) M)
                     (c (S M) * ipW (comboM (S M) c u) (u (S M)) W)
                     (2 * Rabs (c (S M)) * Rabs (ipW (comboM (S M) c u) (u (S M)) W))
                     mu (INR (S M)) (INR (S (S M)))).
    - exact Hmu0.
    - exact HA2.
    - exact HS'.
    - (* Sv+A2 ≤ L + A2 + 2*(c(SM)*IP) + Yv + mu*INR(SM)*Sv = H1L（已展开） *)
      exact H1L.
    - (* Yv ≤ mu*(INR(SM)*A2 + Sv) = H2' *)
      exact H2'.
    - (* INR(S(SM)) = INR(SM) + 1 *)
      exact (S_INR (S M)).
    - exact HmA.
Qed.
(* Σ_{j≤M} c_j² = 0 ⟹ ∀j≤M, c j = 0（逐项平方非负） *)
Lemma sum_sq_zero (c : nat -> R) (M : nat) :
  (sum_f_R0 (fun j : nat => c j * c j) M = 0)%R ->
  forall j, (j <= M)%nat -> c j = 0%R.
Proof.
  intros H. induction M as [| M IH].
  - intros j Hj. assert (Hj0 : j = 0%nat) by (move: Hj => /leP Hjp; lia). subst j.
    change (sum_f_R0 (fun j : nat => c j * c j) 0)%R with (c 0%nat * c 0%nat)%R in H.
    apply (sq_sum_zero_l (c 0%nat) 0%R).
    replace (0%R * 0%R)%R with 0%R by ring.
    rewrite Rplus_0_r. exact H.
  - rewrite (sq_sum_step c M) in H.
    assert (HS : (sum_f_R0 (fun j : nat => c j * c j) M = 0)%R).
    { apply Rle_antisym.
      - assert (Hle : (sum_f_R0 (fun j : nat => c j * c j) M <= 0)%R).
        { apply (Rplus_le_reg_l (c (S M) * c (S M)) _ _).
          replace ((c (S M) * c (S M)) + sum_f_R0 (fun j : nat => c j * c j) M)%R
            with (sum_f_R0 (fun j : nat => c j * c j) M + c (S M) * c (S M))%R by ring.
          rewrite H. rewrite Rplus_0_r. apply Rle_0_sqr. }
        exact Hle.
      - exact (sum_sq_nonneg c M). }
    assert (Hsm : (c (S M) * c (S M) = 0)%R).
    { apply Rle_antisym.
      - assert (Hle : (c (S M) * c (S M) <= 0)%R).
        { apply (Rplus_le_reg_l (sum_f_R0 (fun j : nat => (c j * c j)%R) M) _ _).
          rewrite H. rewrite Rplus_0_r. exact (sum_sq_nonneg c M). }
        exact Hle.
      - apply Rle_0_sqr. }
    intros j Hj.
    destruct (Nat.eq_dec j (S M)) as [E | NE].
    + subst j. apply (sq_sum_zero_r 0%R (c (S M))).
      replace (0%R * 0%R)%R with 0%R by ring.
      rewrite Rplus_0_l. exact Hsm.
    + assert (HjM : (j <= M)%nat) by (apply/leP; move: Hj => /leP Hjp; move: NE => NEp; lia).
      exact (IH HS j HjM).
Qed.

(* CS-3b 最终定理：M-原子稀疏唯一性。
   M+1 个单位范数原子、两两相干 ≤ μ、μ(M+1) < 1，且 Σ_{j≤M}c_j·u_j ≡ 0（窗口内）
   ⟹ 所有系数 c_j = 0。 *)
Theorem sparse_uniquenessM (M : nat) (c : nat -> R) (u : nat -> nat -> Complex) (W : nat) (mu : R) :
  (0 <= mu)%R ->
  (forall j, j <= M -> (l2_norm_sq (u j) W)%R = 1%R) ->
  (forall i j, i <= M -> j <= M -> i <> j ->
    (Rabs (ipW (u i) (u j) W) <= mu)%R) ->
  (mu * INR (S M) < 1)%R ->
  (forall k, (k <= W)%nat -> (comboM (S M) c u k = C0)%C) ->
  (forall j, j <= M -> c j = 0%R).
Proof.
  intros Hmu0 Hunit Hcoh Hmu1 Hzero.
  (* 0 = l2(comboM (S M))（零组合 ⟹ 能量 0） *)
  assert (Hl2 : (l2_norm_sq (comboM (S M) c u) W)%R = 0%R).
  { unfold l2_norm_sq.
    assert (Hext1 : forall k : nat, (k <= W)%nat -> (Cnorm_sq (comboM (S M) c u k) = Cnorm_sq C0)%R)
      by (intro k; intro Hk; f_equal; exact (Hzero k Hk)).
    rewrite (Incoherence.sum_f_R0_ext_bounded _ (fun _ => Cnorm_sq C0) W Hext1).
    assert (Hext2 : forall k : nat, (k <= W)%nat -> (Cnorm_sq C0 = 0)%R)
      by (intro k; intro Hk; exact Cnorm_sq_C0).
    rewrite (Incoherence.sum_f_R0_ext_bounded _ (fun _ => 0%R) W Hext2).
    rewrite (sum_f_R0_zero W). reflexivity. }
  (* RIP 下界：Σc_j² ≤ l2 + μ(M+1)Σc_j² = μ(M+1)Σc_j²（因 l2 = 0） *)
  assert (Hrip := rip_lower_M M c u W mu Hmu0 Hunit Hcoh).
  rewrite Hl2 in Hrip.
  (* Σc_j² ≤ μ(M+1)·Σc_j² 且 μ(M+1) < 1 ⟹ Σc_j² = 0 *)
  assert (HS : (0 <= sum_f_R0 (fun j : nat => c j * c j) M)%R).
  { exact (sum_sq_nonneg c M). }
  assert (Hsq0 : (sum_f_R0 (fun j : nat => c j * c j) M = 0)%R).
  { apply Rle_antisym.
    - (* Σc_j² ≤ 0：由 Hrip 与 μ(M+1)<1 相除。 *)
      assert (H1m : (0 < 1 - mu * INR (S M))%R) by lra.
      assert (Hprod : ((1 - mu * INR (S M)) * sum_f_R0 (fun j : nat => c j * c j) M <= 0)%R).
      { replace ((1 - mu * INR (S M)) * sum_f_R0 (fun j : nat => c j * c j) M)%R
          with (sum_f_R0 (fun j : nat => c j * c j) M - mu * INR (S M) * sum_f_R0 (fun j : nat => c j * c j) M)%R by ring.
        lra. }
      apply (Rmult_le_reg_l (1 - mu * INR (S M)) _ _ H1m).
      replace ((1 - mu * INR (S M)) * 0)%R with 0%R by ring.
      exact Hprod.
    - exact HS. }
  (* 从 Σc_j² = 0 推出各 c_j = 0 *)
  exact (sum_sq_zero c M Hsq0).
Qed.

End Incoherence2.

(* ==================== 模块 43/67: probe_row_rip ==================== *)

Close Scope Z_scope.
Open Scope R_scope.
Open Scope complex_scope.
Open Scope nat_scope.
(* ============================================================

   数学内容： 行非对角和 μ_row（∀i：Σ_{j≠i}|⟨u_i,u_j⟩| ≤ μ_row）蕴含
   对 M+1 原子（k = M+1）的 RIP：
     |‖Σ_{j≤M} c_j u_j‖² − Σ_{j≤M} c_j²| ≤ μ_row·M·Σ_{j≤M} c_j²
   （δ_k = (k−1)·μ_row；交叉项 Σ_{i≠j}|c_i||c_j| ≤ M·Σc² 的 AM-GM 聚合）
   比逐对相干 μ 版更紧：μ_row ≤ M·μ_pair，且行和直接控制。

   F3 组装（经典 R 探针）：
     R0. ipW_combo_r（右线性）+ ipW_double（双重和内积展开）
     R1. norm_sq_split（单位范数：l2 = Σc² + offdiag 交叉项）
     R2. offdiag_abs_le（|交叉项| ≤ μ_row·M·Σc²：|⟨⟩|≤μ_row + AM-GM 聚合）
     R3. row_rip_bound_M（主定理）

   依赖： probe_incoherence（comboM/ipW/ipW_combo_l/norm_sq_comboM_rec 等）。
   审计：零 Admitted / 零自定义公理（同 probe_incoherence 脚印）。
   ============================================================ *)
From mathcomp Require Import ssreflect ssrbool ssrnat seq eqtype div prime.
Require Import Stdlib.Reals.Reals.
Require Import Stdlib.Arith.Arith.
Require Import Stdlib.micromega.Lia.
Require Import Stdlib.micromega.Lra.
Require Import Stdlib.ZArith.ZArith.
Require Import Stdlib.Logic.FunctionalExtensionality.
Import ComplexNumbers.
Import FourierAnalysis.
Import GridOrtho.
Import TParseval.
Import TPartial.
Import PairBound.
Import RowSum.
Import UnconditionalBasis.
Import PairDirichlet.
Import Incoherence.
Import Incoherence2.

Open Scope R_scope.
Open Scope complex_scope.
Open Scope nat_scope.

(* 双重和：Σ_{i≤M} Σ_{j≤M} f i j *)
Definition dsum (M : nat) (f : nat -> nat -> R) : R :=
  sum_f_R0 (fun i => sum_f_R0 (fun j => f i j) M) M.

(* ============ R0：内积双线性 → 双重和 ============ *)

(* 右线性提取：⟨v, Σ_{i≤M} c_i·u_i⟩ = Σ_{i≤M} c_i·⟨v, u_i⟩ *)
Lemma ipW_combo_r (M : nat) (c : nat -> R) (u : nat -> nat -> Complex)
      (v : nat -> Complex) (W : nat) :
  (ipW v (comboM (S M) c u) W)%R
  = (sum_f_R0 (fun i => c i * ipW v (u i) W) M)%R.
Proof.
  rewrite ipW_sym.
  rewrite (ipW_combo_l M c u v W).
  assert (Hext : forall i : nat, (c i * ipW (u i) v W = c i * ipW v (u i) W)%R)
    by (intro i; rewrite ipW_sym; ring).
  rewrite (sum_f_R0_ext _ (fun i => (c i * ipW v (u i) W)%R) M Hext).
  reflexivity.
Qed.

(* 行和（对角排除）：row_sum i = Σ_{j≠i, j≤M} |⟨u_i,u_j⟩| *)
Definition row_sum (M : nat) (u : nat -> nat -> Complex) (W : nat) (i : nat) : R :=
  sum_f_R0 (fun j => if Nat.eqb i j then 0%R else Rabs (ipW (u i) (u j) W)) M.

(* 前缀单调：非负 f，m ≤ n ⟹ Σ_{k≤m} f k ≤ Σ_{k≤n} f k *)
Lemma sum_f_R0_le_sub (f : nat -> R) (m n : nat) :
  (forall k, (0 <= f k)%R) -> le m n ->
  (sum_f_R0 f m <= sum_f_R0 f n)%R.
Proof.
  intros Hf Hmn.
  induction Hmn.
  - apply Rle_refl.
  - simpl. apply Rle_trans with (sum_f_R0 f m0)%R.
    + exact IHHmn.
    + apply (Rle_trans _ (sum_f_R0 f m0 + 0)%R).
      * rewrite Rplus_0_r. apply Rle_refl.
      * apply Rplus_le_compat_l. exact (Hf (S m0)).
Qed.

(* 非负 f ⟹ 和 ≥ 0 *)
Lemma row_sum_f_R0_nonneg (f : nat -> R) (M : nat) :
  (forall k, (0 <= f k)%R) -> (0 <= sum_f_R0 f M)%R.
Proof.
  intros Hf. induction M; simpl.
  - exact (Hf 0).
  - rewrite <- (Rplus_0_l 0).
    apply Rplus_le_compat; [exact IHM | exact (Hf (S M))].
Qed.

(* 单项 ≤ 全和：非负 f，j ≤ M ⟹ f j ≤ Σ_{k≤M} f k *)
Lemma sum_f_R0_ge_term (f : nat -> R) (M j : nat) :
  (forall k, (0 <= f k)%R) -> le j M ->
  (f j <= sum_f_R0 f M)%R.
Proof.
  intros Hf HjM.
  induction M as [| M IH].
  - (* M=0：j ≤ 0 ⟹ j=0，f 0 ≤ f 0 *)
    assert (Hj0 : j = 0) by lia. subst. apply Rle_refl.
  - simpl.
    destruct (Nat.eqb_spec j (S M)) as [Hj | Hjne].
    + subst.
      (* f (S M) ≤ sum_f_R0 f M + f (S M)：0 ≤ sum_f_R0 f M（f 非负） *)
      replace (sum_f_R0 f M + f (S M))%R with (f (S M) + sum_f_R0 f M)%R by ring.
      apply (Rle_trans _ (f (S M) + 0)%R).
      * rewrite Rplus_0_r. apply Rle_refl.
      * apply Rplus_le_compat_l. exact (row_sum_f_R0_nonneg f M Hf).
    + apply (Rle_trans _ (sum_f_R0 f M)).
      * apply IH. lia.
      * apply (Rle_trans _ (sum_f_R0 f M + 0)%R).
        -- rewrite Rplus_0_r. apply Rle_refl.
        -- apply Rplus_le_compat_l. exact (Hf (S M)).
Qed.

(* 单对相干 ≤ 行和：i≠j ≤ M ⟹ |⟨u_i,u_j⟩| ≤ row_sum M u W i *)
Lemma row_le_rowsum (M : nat) (u : nat -> nat -> Complex) (W : nat) (i j : nat) :
  le i M -> le j M -> i <> j ->
  (Rabs (ipW (u i) (u j) W) <= row_sum M u W i)%R.
Proof.
  intros Hi Hj Hne.
  unfold row_sum.
  (* 单项 ≤ 项 j（j≠i ⟹ g j = 单项）≤ Σ g（ge_term，非负） *)
  apply (Rle_trans _ (if Nat.eqb i j then 0%R else Rabs (ipW (u i) (u j) W))).
  - (* |⟨u_i,u_j⟩| ≤ g j *)
    destruct (Nat.eqb i j) eqn:Hijb.
    + exfalso. apply Hne. apply Nat.eqb_eq. exact Hijb.
    + simpl. apply Rle_refl.
  - (* g j ≤ Σ_{l≤M} g l：sum_f_R0_ge_term（非负） *)
    apply (sum_f_R0_ge_term (fun l => if Nat.eqb i l then 0%R else Rabs (ipW (u i) (u l) W)) M j).
    + intro l. destruct (Nat.eqb_spec i l) as [Hil | Hil'].
      * subst. right. reflexivity.
      * apply Rabs_pos.
    + exact Hj.
Qed.

(* 交叉项界（行和版，归纳步用）：
   2·|c_{SM}|·|⟨comboM (S M), u_{SM}⟩| ≤ μ_row·(Σ_{j≤M}c_j² + c_{SM}²)
   证明：|⟨comboM,u⟩| ≤ Σ|c_j||⟨u_j,u⟩|（ipW_combo_l + 三角），
   逐项 AM-GM 2|a||b| ≤ a²+b² 分配行和，|⟨⟩| ≤ μ_row（单对 ≤ 行和）。 *)
Lemma row_cross_bound (M : nat) (c : nat -> R) (u : nat -> nat -> Complex)
      (W : nat) (mu_row : R) :
  (forall i, i <= S M ->
    (row_sum (S M) u W i <= mu_row)%R) ->
  ((2%R * Rabs (c (S M)) * Rabs (ipW (comboM (S M) c u) (u (S M)) W))
   <= mu_row * (sum_f_R0 (fun j => c j * c j) M + c (S M) * c (S M)))%R.
Proof.
  intros Hrow.
  (* 1. |⟨comboM,u⟩| ≤ Σ_{j≤M}|c_j||⟨u_j,u⟩| *)
  assert (Hc1 : (Rabs (ipW (comboM (S M) c u) (u (S M)) W)
                 <= sum_f_R0 (fun j => Rabs (c j) * Rabs (ipW (u j) (u (S M)) W)) M)%R).
  { rewrite (ipW_combo_l M c u (u (S M)) W).
    apply (Rle_trans _ (sum_f_R0 (fun j => (Rabs (c j * ipW (u j) (u (S M)) W))%R) M)%R).
    - apply sum_f_R0_abs.
    - apply sum_f_R0_le. intros k Hk. rewrite Rabs_mult. apply Rle_refl. }
  (* 2. 2|c_{SM}|·Σ ≤ Σ(|c_j|²+c_{SM}²)|⟨⟩|（逐项 AM-GM） *)
  assert (Hc2 : ((2%R * Rabs (c (S M)) *
                  sum_f_R0 (fun j => Rabs (c j) * Rabs (ipW (u j) (u (S M)) W)) M)
                 <= sum_f_R0 (fun j =>
                     (Rabs (c j) * Rabs (c j) + c (S M) * c (S M))
                     * Rabs (ipW (u j) (u (S M)) W)) M)%R).
  { rewrite <- (sum_f_R0_scal (2%R * Rabs (c (S M)))
                 (fun j => (Rabs (c j) * Rabs (ipW (u j) (u (S M)) W))%R) M).
    apply sum_f_R0_le. intros k Hk.
    (* 2|c_{SM}||c_k||⟨⟩| ≤ (|c_k|²+c_{SM}²)|⟨⟩|：AM-GM 乘 |⟨⟩| ≥ 0 *)
    rewrite <- (Rmult_assoc (2%R * Rabs (c (S M))) (Rabs (c k)) _).
    replace ((2%R * Rabs (c (S M)) * Rabs (c k))%R)
      with ((2 * Rabs (c k) * Rabs (c (S M)))%R) by ring.
    apply Rmult_le_compat_r.
    + apply Rabs_pos.
    + (* 2|a||b| ≤ a²+b²，a=|c_k|, b=|c_{SM}| *)
      apply (Rle_trans _ (Rabs (c k) * Rabs (c k) + c (S M) * c (S M)))%R.
      * (* |c_k|² = c_k²（Rabs 平方） *)
        replace (Rabs (c k) * Rabs (c k))%R with (c k * c k)%R
          by (rewrite <- Rabs_mult; symmetry; apply Rabs_pos_eq; apply Rle_0_sqr).
        apply (abs_prod_le_sq (c k) (c (S M))).
      * replace (Rabs (c k) * Rabs (c k))%R with (c k * c k)%R
          by (rewrite <- Rabs_mult; symmetry; apply Rabs_pos_eq; apply Rle_0_sqr).
        apply Rle_refl. }
  (* 3. Σ(|c_j|²+c_{SM}²)|⟨⟩| ≤ μ_row·(Σc_j² + c_{SM}²) *)
  apply (Rle_trans _ (2%R * Rabs (c (S M)) *
                      sum_f_R0 (fun j => Rabs (c j) * Rabs (ipW (u j) (u (S M)) W)) M)%R).
  - (* 原目标 ≤ 中间：2|c_{SM}|·|⟨⟩| ≤ 2|c_{SM}|·Σ（Hc1 乘 2|c_{SM}| ≥ 0） *)
    apply Rmult_le_compat_l.
    + apply Rmult_le_pos; [lra | apply Rabs_pos].
    + exact Hc1.
  - (* 中间 ≤ μ_row(Σc² + c_{SM}²)：Hc2 传递 *)
    apply (Rle_trans _ (sum_f_R0 (fun j =>
        (Rabs (c j) * Rabs (c j) + c (S M) * c (S M))
        * Rabs (ipW (u j) (u (S M)) W)) M)%R).
    + exact Hc2.
    + (* Σ(|c_j|²+c²)|⟨⟩| ≤ μ_row·Σc_j² + μ_row·c² *)
      replace (sum_f_R0 (fun j => ((Rabs (c j) * Rabs (c j) + c (S M) * c (S M)) * Rabs (ipW (u j) (u (S M)) W))%R) M)%R
        with (sum_f_R0 (fun j => (Rabs (c j) * Rabs (c j) * Rabs (ipW (u j) (u (S M)) W)
                                  + c (S M) * c (S M) * Rabs (ipW (u j) (u (S M)) W))%R) M)%R
        by (apply sum_f_R0_ext; intro k; ring).
      setoid_rewrite (sum_f_R0_plus (fun j => (Rabs (c j) * Rabs (c j) * Rabs (ipW (u j) (u (S M)) W))%R)
                             (fun j => (c (S M) * c (S M) * Rabs (ipW (u j) (u (S M)) W))%R) M).
      rewrite Rmult_plus_distr_l.
      apply Rplus_le_compat.
      * (* Σ|c_j|²|⟨⟩| ≤ μ_row·Σc_j²：逐项 |⟨⟩| ≤ μ_row，|c_j|² = c_j² *)
        rewrite <- (sum_f_R0_scal mu_row (fun j => (c j * c j)%R) M).
        apply sum_f_R0_le. intros k Hk.
        replace (Rabs (c k) * Rabs (c k))%R with (c k * c k)%R
          by (rewrite <- Rabs_mult; symmetry; apply Rabs_pos_eq; apply Rle_0_sqr).
        rewrite (Rmult_comm (c k * c k) (Rabs (ipW (u k) (u (S M)) W))).
        apply Rmult_le_compat_r; [apply Rle_0_sqr | ].
        (* |⟨u_k,u_{SM}⟩| ≤ μ_row：单对 ≤ 行和_{SM} ≤ μ_row（row_le_rowsum + Hrow） *)
        rewrite (ipW_sym (u k) (u (S M)) W).
        apply (Rle_trans _ (row_sum (S M) u W (S M))).
        -- move: Hk => /leP Hk.
           apply (row_le_rowsum (S M) u W (S M) k).
           ++ apply le_n.
           ++ exact (Nat.le_trans _ _ _ Hk (Nat.le_succ_diag_r M)).
           ++ lia.
        -- apply Hrow. by apply leqnn.
      * (* c_{SM}²·Σ|⟨⟩| ≤ μ_row·c_{SM}²：行和 ≤ μ_row *)
        replace (sum_f_R0 (fun j => (c (S M) * c (S M) * Rabs (ipW (u j) (u (S M)) W))%R) M)%R
          with ((c (S M) * c (S M)) * sum_f_R0 (fun j => Rabs (ipW (u j) (u (S M)) W)) M)%R
          by (rewrite <- (sum_f_R0_scal (c (S M) * c (S M)) (fun j => Rabs (ipW (u j) (u (S M)) W)) M); reflexivity).
        rewrite (Rmult_comm (c (S M) * c (S M)) (sum_f_R0 (fun j => Rabs (ipW (u j) (u (S M)) W)) M)).
        apply Rmult_le_compat_r; [apply Rle_0_sqr | ].
        (* Σ_{j≤M}|⟨u_j,u_{SM}⟩| ≤ 行和_{SM} ≤ μ_row *)
        apply (Rle_trans _ (row_sum (S M) u W (S M))).
        ++ (* Σ_{j≤M}|⟨u_j,u_{SM}⟩| ≤ Σ_{j≤M}(if...) ：逐项（对称 + j≠SM） *)
           apply (Rle_trans _ (sum_f_R0 (fun l => if Nat.eqb (S M) l then 0%R else Rabs (ipW (u (S M)) (u l) W)) M)).
           ** apply sum_f_R0_le. intros l Hl.
              rewrite (ipW_sym (u l) (u (S M)) W).
              destruct (Nat.eqb (S M) l) eqn:Hsm.
              -- exfalso. apply (Nat.eqb_eq (S M) l) in Hsm. subst.
                 move: Hl => /leP Hl. lia.
              -- simpl. apply Rle_refl.
           ** (* Σ_{j≤M}(if...) ≤ Σ_{j≤SM}(if...) ：前缀单调（非负） *)
              apply (sum_f_R0_le_sub (fun l => if Nat.eqb (S M) l then 0%R else Rabs (ipW (u (S M)) (u l) W)) M (S M)).
              -- intro l. destruct (Nat.eqb_spec (S M) l) as [Hsm | Hsm'].
                 ++ subst. right. reflexivity.
                 ++ apply Rabs_pos.
              -- lia.
        ++ apply Hrow. by apply leqnn.
Qed.

(* ============ F3 主定理：行和 → RIP（δ = μ_row·(k−1) = μ_row·M） ============ *)

(* RIP 下界（行和版，归纳）：Σ_{j≤M}c_j² ≤ ‖comboM(SM)‖² + μ_row·M·Σ_{j≤M}c_j² *)
Lemma row_rip_lower_M (M : nat) (c : nat -> R) (u : nat -> nat -> Complex)
      (W : nat) (mu_row : R) :
  (0 <= mu_row)%R ->
  (forall i, i <= S M -> (row_sum (S M) u W i <= mu_row)%R) ->
  (forall j, j <= M -> (l2_norm_sq (u j) W)%R = 1%R) ->
  ((sum_f_R0 (fun j => c j * c j) M)
   <= (l2_norm_sq (comboM (S M) c u) W
       + mu_row * INR M * sum_f_R0 (fun j => c j * c j) M))%R.
Proof.
  intros Hmu0 Hrow Hunit.
  induction M as [| M IH].
  - (* base M=0：c₀² ≤ ‖combo 1‖² + 0 *)
    assert (Hu : (l2_norm_sq (u 0%nat) W)%R = 1%R) by (apply Hunit; by apply leqnn).
    change (sum_f_R0 (fun j : nat => c j * c j) 0)%R with (c 0%nat * c 0%nat)%R.
    rewrite (comboM_one c u).
    rewrite l2_norm_sq_scale.
    rewrite Incoherence.Cnorm_sq_Cof_real.
    rewrite Hu.
    replace ((c 0%nat * c 0%nat) * 1)%R with (c 0%nat * c 0%nat)%R by ring.
    replace (INR 0)%R with 0%R by reflexivity.
    lra.
  - (* step：P(SM) *)
    rewrite (sq_sum_step c M).
    rewrite (norm_sq_comboM_rec M c u W).
    assert (Hu' : (l2_norm_sq (u (S M)) W)%R = 1%R) by (apply Hunit; by apply leqnn).
    rewrite Hu'.
    replace ((c (S M) * c (S M)) * 1)%R with (c (S M) * c (S M))%R by ring.
    (* IH（截取到 M） *)
    assert (HIH' : (sum_f_R0 (fun j : nat => c j * c j) M
                    <= l2_norm_sq (comboM (S M) c u) W
                       + mu_row * INR M * sum_f_R0 (fun j => c j * c j) M)%R).
    { apply IH.
      - intros i Hi.
        apply (Rle_trans _ (row_sum (S (S M)) u W i)).
        + unfold row_sum.
          apply (sum_f_R0_le_sub (fun j => if Nat.eqb i j then 0%R else Rabs (ipW (u i) (u j) W)) (S M) (S (S M))).
          * intro j. destruct (Nat.eqb_spec i j) as [Hij | Hij'].
            -- subst. right. reflexivity.
            -- apply Rabs_pos.
          * lia.
        + apply Hrow.
          move: Hi => /leP Hi.
          apply/leP. lia.
      - intros j Hj. apply Hunit.
        move: Hj => /leP Hj.
        apply/leP. lia. }
    (* 截取行和上界到 S M 层：row_cross_bound 需要 (forall i, i <= S M -> row_sum (S M) u W i <= mu_row) *)
    assert (Hrow' : (forall i, i <= S M -> (row_sum (S M) u W i <= mu_row)%R)).
    { intros i Hi.
      apply (Rle_trans _ (row_sum (S (S M)) u W i)).
      + unfold row_sum.
        apply (sum_f_R0_le_sub (fun j => if Nat.eqb i j then 0%R else Rabs (ipW (u i) (u j) W)) (S M) (S (S M))).
        * intro j. destruct (Nat.eqb_spec i j) as [Hij | Hij'].
          -- subst. right. reflexivity.
          -- apply Rabs_pos.
        * lia.
      + apply Hrow.
        move: Hi => /leP Hi.
        apply/leP. lia. }
    (* row_cross_bound：2|c_{SM}|·|⟨comboM,u_{SM}⟩| ≤ μ_row(Σ_M + c_{SM}²) *)
    assert (Hcb := row_cross_bound M c u W mu_row Hrow').
    (* −2c⟨⟩ ≤ 2|c||⟨⟩|（Rle_abs + Rabs_mult） *)
    assert (Hneg2 : (- (2 * c (S M) * ipW (comboM (S M) c u) (u (S M)) W)
                    <= 2 * Rabs (c (S M)) * Rabs (ipW (comboM (S M) c u) (u (S M)) W))%R).
    { apply (Rle_trans _ (Rabs (2 * c (S M) * ipW (comboM (S M) c u) (u (S M)) W))).
      - apply (Rle_trans _ (Rabs (- (2 * c (S M) * ipW (comboM (S M) c u) (u (S M)) W)))).
        + apply Rle_abs.
        + rewrite Rabs_opp. apply Rle_refl.
      - rewrite Rabs_mult. rewrite Rabs_mult.
        replace (Rabs 2)%R with 2%R by (rewrite (Rabs_right 2 (Rle_ge 0 2 (Rlt_le 0 2 Rlt_0_2))); ring).
        apply Rle_refl. }
    (* 去掉 Rabs：−2c⟨⟩ ≤ μ_row(Σ_M + c_{SM}²)（Hneg2 + Hcb 组合，供 nra 使用） *)
    assert (Hcross : (- (2 * c (S M) * ipW (comboM (S M) c u) (u (S M)) W)
                      <= mu_row * (sum_f_R0 (fun j => c j * c j) M + c (S M) * c (S M)))%R).
    { apply (Rle_trans _ (2 * Rabs (c (S M)) * Rabs (ipW (comboM (S M) c u) (u (S M)) W))).
      - exact Hneg2.
      - exact Hcb. }
    assert (HS : (0 <= sum_f_R0 (fun j => c j * c j) M)%R) by apply sum_sq_nonneg.
    assert (HA : (0 <= c (S M) * c (S M))%R) by apply Rle_0_sqr.
    assert (HM : (0 <= INR M)%R).
    { apply (le_INR 0 M). lia. }
    rewrite (S_INR M).
    (* μm·c_{SM}² ≥ 0：nra 无法自行证明三因子乘积（Rocq 9 nra 证书限制），显式断言 *)
    assert (Hprod : (0 <= mu_row * INR M * (c (S M) * c (S M)))%R).
    { apply Rmult_le_pos.
      - apply Rmult_le_pos; assumption.
      - apply Rle_0_sqr. }
    nra.
Qed.

(* RIP 上界（行和版，归纳）：‖comboM(SM)‖² ≤ Σ_{j≤M}c_j² + μ_row·M·Σ_{j≤M}c_j² *)
Lemma row_rip_upper_M (M : nat) (c : nat -> R) (u : nat -> nat -> Complex)
      (W : nat) (mu_row : R) :
  (0 <= mu_row)%R ->
  (forall i, i <= S M -> (row_sum (S M) u W i <= mu_row)%R) ->
  (forall j, j <= M -> (l2_norm_sq (u j) W)%R = 1%R) ->
  ((l2_norm_sq (comboM (S M) c u) W
    <= sum_f_R0 (fun j => c j * c j) M
       + mu_row * INR M * sum_f_R0 (fun j => c j * c j) M)%R).
Proof.
  intros Hmu0 Hrow Hunit.
  induction M as [| M IH].
  - (* base M=0：‖combo 1‖² ≤ c₀² + 0 *)
    assert (Hu : (l2_norm_sq (u 0%nat) W)%R = 1%R) by (apply Hunit; by apply leqnn).
    change (sum_f_R0 (fun j : nat => c j * c j) 0)%R with (c 0%nat * c 0%nat)%R.
    rewrite (comboM_one c u).
    rewrite l2_norm_sq_scale.
    rewrite Incoherence.Cnorm_sq_Cof_real.
    rewrite Hu.
    replace ((c 0%nat * c 0%nat) * 1)%R with (c 0%nat * c 0%nat)%R by ring.
    replace (INR 0)%R with 0%R by reflexivity.
    lra.
  - (* step：P(SM) *)
    rewrite (norm_sq_comboM_rec M c u W).
    rewrite (sq_sum_step c M).
    assert (Hu' : (l2_norm_sq (u (S M)) W)%R = 1%R) by (apply Hunit; by apply leqnn).
    rewrite Hu'.
    replace ((c (S M) * c (S M)) * 1)%R with (c (S M) * c (S M))%R by ring.
    (* IH 截取到 M 层（行和上界前缀单调） *)
    assert (Hrow' : (forall i, i <= S M -> (row_sum (S M) u W i <= mu_row)%R)).
    { intros i Hi.
      apply (Rle_trans _ (row_sum (S (S M)) u W i)).
      + unfold row_sum.
        apply (sum_f_R0_le_sub (fun j => if Nat.eqb i j then 0%R else Rabs (ipW (u i) (u j) W)) (S M) (S (S M))).
        * intro j. destruct (Nat.eqb_spec i j) as [Hij | Hij'].
          -- subst. right. reflexivity.
          -- apply Rabs_pos.
        * lia.
      + apply Hrow.
        move: Hi => /leP Hi.
        apply/leP. lia. }
    assert (HIH' : (l2_norm_sq (comboM (S M) c u) W
                    <= sum_f_R0 (fun j : nat => c j * c j) M
                       + mu_row * INR M * sum_f_R0 (fun j => c j * c j) M)%R).
    { apply IH.
      - intros i Hi.
        apply (Rle_trans _ (row_sum (S (S M)) u W i)).
        + unfold row_sum.
          apply (sum_f_R0_le_sub (fun j => if Nat.eqb i j then 0%R else Rabs (ipW (u i) (u j) W)) (S M) (S (S M))).
          * intro j. destruct (Nat.eqb_spec i j) as [Hij | Hij'].
            -- subst. right. reflexivity.
            -- apply Rabs_pos.
          * lia.
        + apply Hrow.
          move: Hi => /leP Hi.
          apply/leP. lia.
      - intros j Hj. apply Hunit.
        move: Hj => /leP Hj.
        apply/leP. lia. }
    (* row_cross_bound：2|c_{SM}|·|⟨comboM,u_{SM}⟩| ≤ μ_row(Σ_M + c_{SM}²) *)
    assert (Hcb := row_cross_bound M c u W mu_row Hrow').
    (* 2c⟨⟩ ≤ 2|c||⟨⟩|（Rle_abs 正向） *)
    assert (Hpos : (2 * c (S M) * ipW (comboM (S M) c u) (u (S M)) W
                  <= 2 * Rabs (c (S M)) * Rabs (ipW (comboM (S M) c u) (u (S M)) W))%R).
    { apply (Rle_trans _ (Rabs (2 * c (S M) * ipW (comboM (S M) c u) (u (S M)) W))).
      - apply Rle_abs.
      - rewrite Rabs_mult. rewrite Rabs_mult.
        replace (Rabs 2)%R with 2%R by (rewrite (Rabs_right 2 (Rle_ge 0 2 (Rlt_le 0 2 Rlt_0_2))); ring).
        apply Rle_refl. }
    (* 去掉 Rabs：2c⟨⟩ ≤ μ_row(Σ_M + c_{SM}²)（Hpos + Hcb 组合，供 nra 使用） *)
    assert (Hcross_pos : (2 * c (S M) * ipW (comboM (S M) c u) (u (S M)) W
                        <= mu_row * (sum_f_R0 (fun j => c j * c j) M + c (S M) * c (S M)))%R).
    { apply (Rle_trans _ (2 * Rabs (c (S M)) * Rabs (ipW (comboM (S M) c u) (u (S M)) W))).
      - exact Hpos.
      - exact Hcb. }
    assert (HS : (0 <= sum_f_R0 (fun j => c j * c j) M)%R) by apply sum_sq_nonneg.
    assert (HA : (0 <= c (S M) * c (S M))%R) by apply Rle_0_sqr.
    assert (HM : (0 <= INR M)%R).
    { apply (le_INR 0 M). lia. }
    rewrite (S_INR M).
    (* μm·c_{SM}² ≥ 0：三因子乘积，显式断言 *)
    assert (Hprod : (0 <= mu_row * INR M * (c (S M) * c (S M)))%R).
    { apply Rmult_le_pos.
      - apply Rmult_le_pos; assumption.
      - apply Rle_0_sqr. }
    nra.
Qed.

(* ============ F3 主定理：行和 → RIP（δ = μ_row·M，M+1 原子） ============ *)
Lemma row_rip_bound_M (M : nat) (c : nat -> R) (u : nat -> nat -> Complex)
      (W : nat) (mu_row : R) :
  (0 <= mu_row)%R ->
  (forall i, i <= S M -> (row_sum (S M) u W i <= mu_row)%R) ->
  (forall j, j <= M -> (l2_norm_sq (u j) W)%R = 1%R) ->
  (Rabs (l2_norm_sq (comboM (S M) c u) W
         - sum_f_R0 (fun j => c j * c j) M)
   <= mu_row * INR M * sum_f_R0 (fun j => c j * c j) M)%R.
Proof.
  intros Hmu0 Hrow Hunit.
  apply Rabs_le.
  split.
  - (* 下界方向：−(μMΣ) ≤ L − Σ ⟸ Σ ≤ L + μMΣ *)
    assert (Hlow := row_rip_lower_M M c u W mu_row Hmu0 Hrow Hunit).
    nra.
  - (* 上界方向：L − Σ ≤ μMΣ ⟸ L ≤ Σ + μMΣ *)
    assert (Hup := row_rip_upper_M M c u W mu_row Hmu0 Hrow Hunit).
    nra.
Qed.

