(* ============ PB2：ipW 对称 + C=4 三原子相干 ≤ 11289/33920 ============ *)

(* ipW 对称：⟨u,v⟩_W = ⟨v,u⟩_W *)
Lemma ipW_sym (u v : nat -> Complex) (W : nat) :
  ipW u v W = ipW v u W.
Proof.
  unfold ipW.
  apply sum_f_R0_ext.
  intro k. apply inner_sym.
Qed.

(* C=4 前 3 原子 [3,13,53]（索引 0,1,2） *)
Definition c4v3 : nat -> nat :=
  fun j => match j with 0 => 3 | 1 => 13 | _ => 53 end.

(* 三原子两两相干 ≤ 11289/33920（W ≥ 53；11289/33920 = (53,213) 对的界，全局最大） *)
Lemma c4_coherence_3 (W : nat) : le 53 W ->
  forall i j, i <= 2 -> j <= 2 -> i <> j ->
    (Rabs (ipW (psi (c4v3 i)) (psi (c4v3 j)) W) <= 11289 / 33920)%R.
Proof.
  intros HW i j Hi Hj Hne.
  move: Hi => /leP Hi. move: Hj => /leP Hj.
  destruct i as [|[|[|i]]].
  - (* i = 0（ψ_3） *)
    destruct j as [|[|[|j]]];
      try (exfalso; lia); try (exfalso; apply Hne; reflexivity).
    + (* j=1：|⟨ψ_3,ψ_13⟩| ≤ 13/40 ≤ 11289/33920 *)
      apply (Rle_trans _ (13 / 40)).
      * apply c4_ip_3_13. lia.
      * lra.
    + (* j=2：|⟨ψ_3,ψ_53⟩| ≤ 53/400 ≤ 11289/33920 *)
      apply (Rle_trans _ (53 / 400)).
      * apply c4_ip_3_53. lia.
      * lra.
  - (* i = 1（ψ_13） *)
    destruct j as [|[|[|j]]];
      try (exfalso; lia); try (exfalso; apply Hne; reflexivity).
    + (* j=0：|⟨ψ_13,ψ_3⟩| = |⟨ψ_3,ψ_13⟩| ≤ 13/40 *)
      simpl c4v3. rewrite (ipW_sym (psi 13) (psi 3) W).
      apply (Rle_trans _ (13 / 40)).
      * apply c4_ip_3_13. lia.
      * lra.
    + (* j=2：|⟨ψ_13,ψ_53⟩| ≤ 689/2080 ≤ 11289/33920 *)
      apply (Rle_trans _ (689 / 2080)).
      * apply c4_ip_13_53. lia.
      * lra.
  - (* i = 2（ψ_53） *)
    destruct j as [|[|[|j]]];
      try (exfalso; lia); try (exfalso; apply Hne; reflexivity).
    + (* j=0：|⟨ψ_53,ψ_3⟩| = |⟨ψ_3,ψ_53⟩| ≤ 53/400 *)
      simpl c4v3. rewrite (ipW_sym (psi 53) (psi 3) W).
      apply (Rle_trans _ (53 / 400)).
      * apply c4_ip_3_53. lia.
      * lra.
    + (* j=1：|⟨ψ_53,ψ_13⟩| = |⟨ψ_13,ψ_53⟩| ≤ 689/2080 *)
      simpl c4v3. rewrite (ipW_sym (psi 53) (psi 13) W).
      apply (Rle_trans _ (689 / 2080)).
      * apply c4_ip_13_53. lia.
      * lra.
  - exfalso. lia.
Qed.

(* ============ PB3：C4_sparse_uniqueness_3（A2 主定理） ============ *)

(* 0 ≤ 11289/33920 且 11289/33920 · 3 < 1（33867 < 33920） *)
Lemma c4_mu_pos : (0 <= 11289 / 33920)%R.
Proof. lra. Qed.

Lemma c4_mu_lt_third : (11289 / 33920 * INR 3 < 1)%R.
Proof. simpl. lra. Qed.

(* A2 主定理：C=4 阶梯前 3 原子 [3,13,53] 稀疏唯一恢复
   （窗口 W ≥ 53，μ := 11289/33920 < 1/3 ⟹ μ·3 < 1，sparse_uniquenessM M=2 实例） *)
Theorem C4_sparse_uniqueness_3 (c : nat -> R) (W : nat) :
  le 53 W ->
  (forall k, (k <= W)%nat -> (comboM 3 c (fun j => psi (c4v3 j)) k = C0)%C) ->
  forall j, j <= 2 -> c j = 0%R.
Proof.
  intros HW Hzero j Hj.
  apply (sparse_uniquenessM 2 c (fun j => psi (c4v3 j)) W (11289 / 33920)).
  - exact c4_mu_pos.
  - (* 单位范数：∀j≤2，l2_norm_sq (psi (c4v3 j)) W = 1（psi_unit_norm，3/13/53 ≤ W） *)
    intros j0 Hj0.
    apply (psi_unit_norm (c4v3 j0) W).
    + destruct j0 as [|[|[|j0]]]; simpl; lia.
    + destruct j0 as [|[|[|j0]]]; simpl; lia.
  - (* 两两相干 ≤ 11289/33920（c4_coherence_3） *)
    exact (c4_coherence_3 W HW).
  - exact c4_mu_lt_third.
  - (* 零组合（用户前提） *)
    intros k Hk. exact (Hzero k Hk).
  - exact Hj.
Qed.

(* ==================== 模块 45/67: probe_welch ==================== *)

Close Scope Z_scope.
Open Scope R_scope.
Open Scope complex_scope.
Open Scope nat_scope.
(* ============================================================

   数学内容（Welch 界，经典 R 轨道）：
     M 个单位范数向量 u_0..u_{M-1} ∈ R^N（N < M），互相干上界 μ：
       ∀i≠j: |⟨u_i,u_j⟩| ≤ μ  ⟹  (M−N) ≤ N·(M−1)·μ²
     ——任何 M 个 N 维单位向量的字典，最大相干不能低于 Welch 下界；
       与频率阶梯原子族的相干紧性（witness_sandwich，Θ(C^{−3/2})）对比，
       证明该族在低相干意义下接近理论最优。

   证明路线（初等，避免特征值理论——行向量 Cauchy-Schwarz）：
         add / opp / one / sq_expand / factor / sum4_swap / split_diag / ge_diag。
     R1. Gram 重排：Σ_{i,j}⟨u_i,u_j⟩² = Σ_{k,l}(Σ_i u_ik·u_il)²。
     R2. Σ_{k,l}(Σ_i u_ik·u_il)² ≥ (Σ_k Σ_i u_ik²)²/N（对角截断 + CS 幂平均）。
     R3. Σ_k Σ_i u_ik² = M（单位范数）⟹ Gram ≥ M²/N。
     R4. Gram ≤ M + M(M−1)μ²（对角 1 + 非对角 μ² 计数）。
     R5. nra 收尾：(M−N) ≤ N(M−1)μ²。

   依赖：仅 Stdlib Reals + mathcomp（ssreflect 记法）；sum_f_R0 全套自证。
   审计：零 Admitted / 零自定义公理（同 probe_incoherence 脚印）。
   ============================================================ *)
From mathcomp Require Import ssreflect ssrbool ssrnat seq eqtype div prime.
Require Import Stdlib.Reals.Reals.
Require Import Stdlib.Arith.Arith.
Require Import Stdlib.micromega.Lia.
Require Import Stdlib.micromega.Lra.
Require Import Stdlib.ZArith.ZArith.
Require Import Stdlib.Logic.FunctionalExtensionality.

Open Scope R_scope.

(* ============ R0. 求和工具（本地自证，防合并重名） ============ *)

Lemma wl_sum_swap (A B : nat) (h : nat -> nat -> R) :
  sum_f_R0 (fun i => sum_f_R0 (h i) B) A =
  sum_f_R0 (fun j => sum_f_R0 (fun i => h i j) A) B.
Proof.
  revert B h. induction A as [| A IH]; intros B h; simpl.
  - induction B as [| B IHB]; simpl; lra.
  - rewrite IH. induction B as [| B IHB]; simpl; lra.
Qed.

Lemma wl_sum_scal_l (c : R) (f : nat -> R) (n : nat) :
  sum_f_R0 (fun i => c * f i) n = c * sum_f_R0 f n.
Proof.
  induction n as [| n IH]; simpl; [ring | rewrite IH; ring].
Qed.

Lemma wl_sum_scal_r (c : R) (f : nat -> R) (n : nat) :
  sum_f_R0 (fun i => f i * c) n = sum_f_R0 f n * c.
Proof.
  induction n as [| n IH]; simpl; [ring | rewrite IH; ring].
Qed.

Lemma wl_sum_one (n : nat) : sum_f_R0 (fun _ : nat => 1) n = INR (S n).
Proof.
  induction n as [| n IH]; simpl.
  - reflexivity.
  - rewrite IH. simpl. ring.
Qed.

(* 常数和：Σ_{i≤n} c = (S n)·c *)
Lemma wl_sum_const (c : R) (n : nat) : sum_f_R0 (fun _ : nat => c) n = INR (S n) * c.
Proof.
  induction n as [| n IH]; simpl.
  - ring.
  - rewrite IH. simpl. ring.
Qed.

Lemma wl_sum_ext (f g : nat -> R) (n : nat) :
  (forall k, le k n -> f k = g k) -> sum_f_R0 f n = sum_f_R0 g n.
Proof.
  intros H. induction n as [| n IH]; simpl.
  - apply H. lia.
  - assert (Hn : forall k : nat, le k n -> f k = g k).
    { intros k Hk. apply H. lia. }
    rewrite (IH Hn).
    assert (Hsn : f (S n) = g (S n)) by (apply H; lia).
    rewrite Hsn. reflexivity.
Qed.

Lemma wl_sum_le (f g : nat -> R) (n : nat) :
  (forall k, le k n -> f k <= g k) -> sum_f_R0 f n <= sum_f_R0 g n.
Proof.
  intros H. induction n as [| n IH]; simpl.
  - apply H. lia.
  - assert (Hn : forall k : nat, le k n -> f k <= g k).
    { intros k Hk. apply H. lia. }
    apply Rplus_le_compat; [exact (IH Hn) | apply H; lia].
Qed.

Lemma wl_sum_nonneg (f : nat -> R) (n : nat) :
  (forall k, le k n -> 0 <= f k) -> 0 <= sum_f_R0 f n.
Proof.
  intros H. induction n as [| n IH]; simpl.
  - apply H. lia.
  - assert (Hn : forall k : nat, le k n -> 0 <= f k).
    { intros k Hk. apply H. lia. }
    apply Rplus_le_le_0_compat; [exact (IH Hn) | apply H; lia].
Qed.

Lemma wl_sum_add (f g : nat -> R) (n : nat) :
  sum_f_R0 (fun k => f k + g k) n = sum_f_R0 f n + sum_f_R0 g n.
Proof.
  induction n as [| n IH]; simpl; [ring | rewrite IH; ring].
Qed.

Lemma wl_sum_opp (f : nat -> R) (n : nat) :
  sum_f_R0 (fun k => - f k) n = - sum_f_R0 f n.
Proof.
  induction n as [| n IH]; simpl; [ring | rewrite IH; ring].
Qed.

(* (Σ_{k≤n} a k)·(Σ_{k≤n} a k) = Σ_{k≤n}Σ_{l≤n} a k·a l *)
Lemma wl_sum_sq_expand (a : nat -> R) (n : nat) :
  sum_f_R0 (fun k => sum_f_R0 (fun l => a k * a l) n) n
  = (sum_f_R0 a n) * (sum_f_R0 a n).
Proof.
  transitivity (sum_f_R0 (fun k => a k * sum_f_R0 a n) n).
  - apply wl_sum_ext. intros k Hk.
    transitivity (a k * sum_f_R0 a n).
    + setoid_rewrite (wl_sum_scal_l (a k) a n). reflexivity.
    + reflexivity.
  - rewrite (wl_sum_scal_r (sum_f_R0 a n) (fun k => a k) n). reflexivity.
Qed.

(* Σ_{i≤n}Σ_{j≤n} a i·b j = (Σa)·(Σb) *)
Lemma wl_sum_factor (a b : nat -> R) (n : nat) :
  sum_f_R0 (fun i => sum_f_R0 (fun j => a i * b j) n) n
  = (sum_f_R0 a n) * (sum_f_R0 b n).
Proof.
  transitivity (sum_f_R0 (fun i => a i * sum_f_R0 b n) n).
  - apply wl_sum_ext. intros i Hi.
    transitivity (a i * sum_f_R0 b n).
    + setoid_rewrite (wl_sum_scal_l (a i) b n). reflexivity.
    + reflexivity.
  - rewrite (wl_sum_scal_r (sum_f_R0 b n) (fun i => a i) n). reflexivity.
Qed.

(* 三重和换序：Σ_i Σ_k Σ_l h = Σ_k Σ_l Σ_i h（i 上限 A；k,l 上限 B） *)
Lemma wl_sum3_swap (A B : nat) (h : nat -> nat -> nat -> R) :
  sum_f_R0 (fun i => sum_f_R0 (fun k => sum_f_R0 (fun l => h i k l) B) B) A
  = sum_f_R0 (fun k => sum_f_R0 (fun l => sum_f_R0 (fun i => h i k l) A) B) B.
Proof.
  revert B h. induction A as [| A IH]; intros B h.
  - simpl. reflexivity.
  - (* 拆出 i = S A 项 *)
    assert (Hsn : sum_f_R0 (fun i : nat => sum_f_R0 (fun k => sum_f_R0 (fun l => h i k l) B) B) (S A)
                 = sum_f_R0 (fun i : nat => sum_f_R0 (fun k => sum_f_R0 (fun l => h i k l) B) B) A
                   + sum_f_R0 (fun k => sum_f_R0 (fun l => h (S A) k l) B) B).
    { simpl. ring. }
    rewrite Hsn.
    replace (sum_f_R0 (fun i : nat => sum_f_R0 (fun k => sum_f_R0 (fun l => h i k l) B) B) A)
      with (sum_f_R0 (fun k => sum_f_R0 (fun l => sum_f_R0 (fun i : nat => h i k l) A) B) B)
      by (symmetry; exact (IH B h)).
    (* 目标：[Σ_k Σ_l Σ_{i≤A} h i k l] + [Σ_k Σ_l h (S A) k l] = Σ_k Σ_l Σ_{i≤S A} h i k l *)
    transitivity (sum_f_R0 (fun k => sum_f_R0 (fun l => sum_f_R0 (fun i : nat => h i k l) A) B
                                        + sum_f_R0 (fun l => h (S A) k l) B) B).
    - rewrite <- (wl_sum_add (fun k => sum_f_R0 (fun l => sum_f_R0 (fun i : nat => h i k l) A) B)
                             (fun k => sum_f_R0 (fun l => h (S A) k l) B) B).
      reflexivity.
    - apply wl_sum_ext. intros k Hk.
      rewrite <- (wl_sum_add (fun l => sum_f_R0 (fun i : nat => h i k l) A)
                             (fun l => h (S A) k l) B).
      reflexivity.
Qed.

(* 四重和换序：Σ_{i,j}Σ_{k,l} f = Σ_{k,l}Σ_{i,j} f（i,j 上限 A；k,l 上限 B） *)
Lemma wl_sum4_swap (A B : nat) (f : nat -> nat -> nat -> nat -> R) :
  sum_f_R0 (fun i => sum_f_R0 (fun j =>
    sum_f_R0 (fun k => sum_f_R0 (fun l => f i j k l) B) B) A) A
  = sum_f_R0 (fun k => sum_f_R0 (fun l =>
    sum_f_R0 (fun i => sum_f_R0 (fun j => f i j k l) A) A) B) B.
Proof.
  revert B f. induction A as [| A IH]; intros B f.
  - simpl. reflexivity.
  - (* 拆出 i = S A 层 *)
    assert (Hsn : sum_f_R0 (fun i : nat =>
                  sum_f_R0 (fun j => sum_f_R0 (fun k => sum_f_R0 (fun l => f i j k l) B) B) (S A)) (S A)
                 = sum_f_R0 (fun i : nat =>
                   sum_f_R0 (fun j => sum_f_R0 (fun k => sum_f_R0 (fun l => f i j k l) B) B) (S A)) A
                   + sum_f_R0 (fun j => sum_f_R0 (fun k => sum_f_R0 (fun l => f (S A) j k l) B) B) (S A)).
    { simpl. ring. }
    rewrite Hsn.
    (* 第一块再拆 j = S A 项 *)
    assert (Hsn2 : sum_f_R0 (fun i : nat =>
                   sum_f_R0 (fun j => sum_f_R0 (fun k => sum_f_R0 (fun l => f i j k l) B) B) (S A)) A
                 = sum_f_R0 (fun i : nat =>
                   sum_f_R0 (fun j => sum_f_R0 (fun k => sum_f_R0 (fun l => f i j k l) B) B) A) A
                   + sum_f_R0 (fun i => sum_f_R0 (fun k => sum_f_R0 (fun l => f i (S A) k l) B) B) A).
    { rewrite <- (wl_sum_add (fun i => sum_f_R0 (fun j => sum_f_R0 (fun k => sum_f_R0 (fun l => f i j k l) B) B) A)
                             (fun i => sum_f_R0 (fun k => sum_f_R0 (fun l => f i (S A) k l) B) B) A).
      apply wl_sum_ext. intros i Hi. simpl. ring. }
    rewrite Hsn2.
    (* 三块：①Σ_{i,j≤A}（IH）②Σ_{i≤A}·(j=S A)（sum3 换序）③Σ_{j≤S A}·(i=S A)（sum3 换序） *)
    replace (sum_f_R0 (fun i : nat => sum_f_R0 (fun j => sum_f_R0 (fun k => sum_f_R0 (fun l => f i j k l) B) B) A) A)
      with (sum_f_R0 (fun k => sum_f_R0 (fun l => sum_f_R0 (fun i => sum_f_R0 (fun j => f i j k l) A) A) B) B)
      by (symmetry; exact (IH B f)).
    rewrite (wl_sum3_swap A B (fun i k l => f i (S A) k l)).
    rewrite (wl_sum3_swap (S A) B (fun j k l => f (S A) j k l)).
    (* 合并：Σ_k Σ_l (Σ_{i,j≤A} + Σ_{i≤A} + Σ_{j≤S A}) = Σ_k Σ_l Σ_{i,j≤S A} *)
    transitivity (sum_f_R0 (fun k => sum_f_R0 (fun l => sum_f_R0 (fun i => sum_f_R0 (fun j => f i j k l) A) A) B
                                        + sum_f_R0 (fun l => sum_f_R0 (fun i => f i (S A) k l) A) B) B
                  + sum_f_R0 (fun k => sum_f_R0 (fun l => sum_f_R0 (fun j => f (S A) j k l) (S A)) B) B).
    - (* 第一块 + 第二块 合并 *)
      rewrite <- (wl_sum_add (fun k => sum_f_R0 (fun l => sum_f_R0 (fun i => sum_f_R0 (fun j => f i j k l) A) A) B)
                             (fun k => sum_f_R0 (fun l => sum_f_R0 (fun i => f i (S A) k l) A) B) B).
      reflexivity.
    - transitivity (sum_f_R0 (fun k => sum_f_R0 (fun l => sum_f_R0 (fun i => sum_f_R0 (fun j => f i j k l) A) A) B
                                        + sum_f_R0 (fun l => sum_f_R0 (fun i => f i (S A) k l) A) B
                                        + sum_f_R0 (fun l => sum_f_R0 (fun j => f (S A) j k l) (S A)) B) B).
      + (* (X+Y) + Z 合并 *)
        rewrite <- (wl_sum_add (fun k => sum_f_R0 (fun l => sum_f_R0 (fun i => sum_f_R0 (fun j => f i j k l) A) A) B
                                          + sum_f_R0 (fun l => sum_f_R0 (fun i => f i (S A) k l) A) B)
                               (fun k => sum_f_R0 (fun l => sum_f_R0 (fun j => f (S A) j k l) (S A)) B) B).
        reflexivity.
      + apply wl_sum_ext. intros k Hk.
        rewrite <- (wl_sum_add (fun l => sum_f_R0 (fun i => sum_f_R0 (fun j => f i j k l) A) A)
                               (fun l => sum_f_R0 (fun i => f i (S A) k l) A) B).
        rewrite <- (wl_sum_add (fun l => sum_f_R0 (fun i => sum_f_R0 (fun j => f i j k l) A) A
                                         + sum_f_R0 (fun i => f i (S A) k l) A)
                               (fun l => sum_f_R0 (fun j => f (S A) j k l) (S A)) B).
        apply wl_sum_ext. intros l Hl.
        rewrite <- (wl_sum_add (fun i => sum_f_R0 (fun j : nat => f i j k l) A)
                               (fun i => f i (S A) k l) A).
        simpl.
        reflexivity.
Qed.

(* 零函数和 = 0 *)
Lemma wl_sum_zero (n : nat) : sum_f_R0 (fun _ : nat => 0) n = 0.
Proof. induction n; simpl; [reflexivity | rewrite IHn; ring]. Qed.

(* ============ R2b. 计数引理（对角/非对角项数） ============ *)

(* 计数：Σ_{j≤Nat.pred M} (if j=?i then 1 else 0) = 1（i < M ⟹ i 在求和范围内） *)
Lemma wl_count_diag (M i : nat) :
  lt i M ->
  sum_f_R0 (fun j => if Nat.eqb j i then 1 else 0) (Nat.pred M) = 1.
Proof.
  intro Hi.
  induction M as [| M IHm].
  - simpl in Hi. lia.
  - destruct M as [| M'].
    + (* M = 1：Nat.pred (S 0) = 0，i < 1 ⟹ i = 0 *)
      simpl in Hi. assert (Hi0 : i = 0%nat) by lia. subst i. simpl. reflexivity.
    + (* M = S (S M')：Nat.pred = S M' *)
      simpl. destruct (Nat.eqb_spec (S M') i) as [Hi' | Hi'].
      * subst i.
        assert (Hext : forall j : nat, le j M' -> ((if Nat.eqb j (S M') then 1 else 0) = 0)%R)
          by (intros j Hj; destruct (Nat.eqb_spec j (S M')) as [Hjs | Hjs]; [exfalso; lia | simpl; reflexivity]).
        rewrite (wl_sum_ext (fun j => if Nat.eqb j (S M') then 1 else 0) (fun _ => 0) M' Hext).
        rewrite wl_sum_zero. rewrite Nat.eqb_refl. ring.
      * assert (Hilt : lt i (S M')) by lia.
        rewrite (IHm Hilt).
        -- destruct i as [| i'].
           ++ simpl. ring.
           ++ assert (Hmi : M' <> i') by (intro Hm; apply Hi'; f_equal; exact Hm).
              rewrite (proj2 (Nat.eqb_neq M' i') Hmi). simpl. ring.
Qed.

(* 计数：非对角项数 = M−1：Σ_{j≤Nat.pred M} (if j=?i then 0 else 1) = M−1（i < M） *)
Lemma wl_count_offdiag (M i : nat) :
  lt i M ->
  sum_f_R0 (fun j => if Nat.eqb j i then 0 else 1) (Nat.pred M) = INR (M - 1).
Proof.
  intro Hi.
  (* 把 if 展开为 1 − (if j=?i then 1 else 0) *)
  assert (Heq : forall j, ((if Nat.eqb j i then 0 else 1) : R) = (1 - (if Nat.eqb j i then 1 else 0))%R).
  { intros j. case (Nat.eqb j i) eqn:E.
    - apply Nat.eqb_eq in E. subst j. simpl. ring.
    - simpl. ring. }
  assert (Hext2 : forall k : nat, le k (Nat.pred M) -> ((if Nat.eqb k i then 0 else 1) = (1 - (if Nat.eqb k i then 1 else 0)))%R)
    by (intros k Hk; apply Heq).
  rewrite (wl_sum_ext (fun j => if Nat.eqb j i then 0 else 1)
                      (fun j => (1 - (if Nat.eqb j i then 1 else 0))%R) (Nat.pred M) Hext2).
  setoid_rewrite (wl_sum_add (fun _ : nat => 1%R)
                             (fun j => (- (if Nat.eqb j i then 1 else 0))%R) (Nat.pred M)).
  setoid_rewrite wl_sum_opp.
  setoid_rewrite wl_sum_one.
  rewrite (wl_count_diag M i Hi).
  replace (INR (S (Nat.pred M)))%R with (INR M)%R by (f_equal; lia).
  assert (HM1 : le 1 M) by lia.
  rewrite (minus_INR M 1 HM1); simpl; ring.
Qed.

(* Gram 平方和 ≤ M + M(M−1)μ² *)

(* 对角项 ≤ 全和（非负）：x k ≤ Σ_{j≤n} x j（k ≤ n 且各 x j ≥ 0） *)
Lemma wl_sum_ge_diag (x : nat -> R) (n k : nat) :
  le k n -> (forall j, le j n -> 0 <= x j) ->
  x k <= sum_f_R0 x n.
Proof.
  intros Hk Hx.
  replace (sum_f_R0 x n)
    with (sum_f_R0 (fun j => (if Nat.eqb j k then x k else 0) + (if Nat.eqb j k then 0 else x j)) n).
      2: { apply wl_sum_ext. intros j0 Hj0.
       destruct (Nat.eqb_spec j0 k) as [Hjk | Hjk].
       - subst. simpl. ring.
       - simpl. ring. }
  rewrite wl_sum_add.
  assert (HsumA : x k <= sum_f_R0 (fun j => if Nat.eqb j k then x k else 0) n).
  { replace (sum_f_R0 (fun j => if Nat.eqb j k then x k else 0) n)
      with (x k * sum_f_R0 (fun j => if Nat.eqb j k then 1 else 0) n).
    2: { rewrite <- (wl_sum_scal_l (x k) (fun j => if Nat.eqb j k then 1 else 0) n).
         apply wl_sum_ext. intros j Hj.
         destruct (Nat.eqb_spec j k); simpl; ring. }
    assert (Hlt : lt k (S n)) by (first [lia | rewrite ltnS; apply/leP; exact Hk]).
    rewrite (wl_count_diag (S n) k Hlt). rewrite Rmult_1_r. apply Rle_refl. }
  assert (HsumB : 0 <= sum_f_R0 (fun j => if Nat.eqb j k then 0 else x j) n).
  { apply wl_sum_nonneg. intros j Hj.
     destruct (Nat.eqb_spec j k) as [Hjk | Hjk].
    - subst. simpl. apply Rle_refl.
    - simpl. apply Hx; exact Hj. }
  lra.
Qed.

(* 幂平均（Cauchy-Schwarz）：(Σ_{k≤n} x k)² ≤ (S n)·Σ_{k≤n} x k²（x ≥ 0） *)
Lemma wl_sum_sq_ge_mean_sq (x : nat -> R) (n : nat) :
  (forall k, le k n -> 0 <= x k) ->
  (sum_f_R0 x n) * (sum_f_R0 x n)
  <= INR (S n) * sum_f_R0 (fun k => x k * x k) n.
Proof.
  intros Hx.
  (* D := Σ_{i,j≤n} (x_i − x_j)² ≥ 0 *)
  assert (HD : 0 <= sum_f_R0 (fun i => sum_f_R0 (fun j => (x i - x j) * (x i - x j)) n) n).
  { apply wl_sum_nonneg. intros i Hi.
    apply wl_sum_nonneg. intros j Hj.
    apply Rle_0_sqr. }
  (* 展开 D = 2·(S n)·Σx² − 2·(Σx)² *)
  assert (HD_eq : sum_f_R0 (fun i => sum_f_R0 (fun j => (x i - x j) * (x i - x j)) n) n
                  = 2 * INR (S n) * sum_f_R0 (fun k => x k * x k) n
                    - 2 * (sum_f_R0 x n) * (sum_f_R0 x n)).
  { (* 逐 (i,j) 展开 ring *)
    transitivity (sum_f_R0 (fun i => sum_f_R0 (fun j =>
        x i * x i - 2 * (x i * x j) + x j * x j) n) n).
    { apply wl_sum_ext. intros i Hi.
      apply wl_sum_ext. intros j Hj. ring. }
    (* 逐 i 层线性拆解 *)
    transitivity (sum_f_R0 (fun i =>
        INR (S n) * (x i * x i) - 2 * (x i * sum_f_R0 x n) + sum_f_R0 (fun j => x j * x j) n) n).
    { apply wl_sum_ext. intros i Hi.
      (* Σ_j (x_i² − 2x_ix_j + x_j²) = (S n)x_i² − 2x_iΣx + Σx² *)
      transitivity (sum_f_R0 (fun j => x i * x i) n
                    - sum_f_R0 (fun j => 2 * (x i * x j)) n
                    + sum_f_R0 (fun j => x j * x j) n).
      { rewrite (wl_sum_add (fun j => x i * x i - 2 * (x i * x j)) (fun j => x j * x j) n).
        rewrite (wl_sum_add (fun j => x i * x i) (fun j => - (2 * (x i * x j))) n).
        rewrite wl_sum_opp. ring. }
      replace (sum_f_R0 (fun j : nat => x i * x i) n)
        with (INR (S n) * (x i * x i)).
      2: { symmetry. rewrite (TaylorTheorem.sum_f_R0_const (x i * x i) n). ring. }
      replace (sum_f_R0 (fun j : nat => 2 * (x i * x j)) n)
        with (2 * (x i * sum_f_R0 x n)).
      2: { transitivity (2 * sum_f_R0 (fun j => x i * x j) n).
           - f_equal. symmetry. exact (wl_sum_scal_l (x i) x n).
           - symmetry. exact (wl_sum_scal_l 2 (fun j => x i * x j) n). }
      ring. }
    (* 外层线性拆解 *)
    transitivity (INR (S n) * sum_f_R0 (fun i => x i * x i) n
                  - 2 * (sum_f_R0 x n) * (sum_f_R0 x n)
                  + INR (S n) * sum_f_R0 (fun i => x i * x i) n).
    { (* Σ_i (A_i − B_i + C_i) = Σ_i (A_i − B_i) + Σ_i C_i *)
      transitivity (sum_f_R0 (fun i => INR (S n) * (x i * x i) - 2 * (x i * sum_f_R0 x n)) n
                    + sum_f_R0 (fun i => sum_f_R0 (fun j => x j * x j) n) n).
      - rewrite <- (wl_sum_add (fun i0 => INR (S n) * (x i0 * x i0) - 2 * (x i0 * sum_f_R0 x n))
                               (fun _ : nat => sum_f_R0 (fun j => x j * x j) n) n).
        apply wl_sum_ext. intros i Hi. reflexivity.
      - transitivity (sum_f_R0 (fun i => INR (S n) * (x i * x i) - 2 * (x i * sum_f_R0 x n)) n
                      + INR (S n) * sum_f_R0 (fun i => x i * x i) n).
        + apply Rplus_eq_compat_l.
          replace (sum_f_R0 (fun i : nat => sum_f_R0 (fun j : nat => x j * x j) n) n)
            with (INR (S n) * sum_f_R0 (fun i : nat => x i * x i) n).
          2: { transitivity (sum_f_R0 (fun _ : nat => sum_f_R0 (fun j : nat => x j * x j) n) n).
               - symmetry. apply wl_sum_const.
               - apply wl_sum_ext. intros i Hi. reflexivity. }
          reflexivity.
        + transitivity (INR (S n) * sum_f_R0 (fun i => x i * x i) n
                        - 2 * (sum_f_R0 x n) * (sum_f_R0 x n)
                        + INR (S n) * sum_f_R0 (fun i => x i * x i) n).
          * apply Rplus_eq_compat_r.
            assert (HAB : sum_f_R0 (fun i => INR (S n) * (x i * x i) - 2 * (x i * sum_f_R0 x n)) n
                          = INR (S n) * sum_f_R0 (fun i => x i * x i) n
                            - 2 * (sum_f_R0 x n) * (sum_f_R0 x n)).
            { transitivity (sum_f_R0 (fun i => INR (S n) * (x i * x i)) n
                            - sum_f_R0 (fun i => 2 * (x i * sum_f_R0 x n)) n).
              - change (sum_f_R0 (fun i => INR (S n) * (x i * x i) - 2 * (x i * sum_f_R0 x n)) n
                        = sum_f_R0 (fun i => INR (S n) * (x i * x i)) n
                          + (- sum_f_R0 (fun i => 2 * (x i * sum_f_R0 x n)) n)).
                rewrite <- (wl_sum_opp (fun i0 => 2 * (x i0 * sum_f_R0 x n)) n).
                rewrite <- (wl_sum_add (fun i0 : nat => INR (S n) * (x i0 * x i0))
                                       (fun i0 => - (2 * (x i0 * sum_f_R0 x n))) n).
                apply wl_sum_ext. intros i Hi. reflexivity.
              - transitivity (INR (S n) * sum_f_R0 (fun i => x i * x i) n
                              - sum_f_R0 (fun i => 2 * (x i * sum_f_R0 x n)) n).
                + apply Rplus_eq_compat_r.
                  replace (sum_f_R0 (fun i => INR (S n) * (x i * x i)) n)
                    with (INR (S n) * sum_f_R0 (fun i => x i * x i) n) by (symmetry; apply wl_sum_scal_l).
                  reflexivity.
                + apply Rplus_eq_compat_l.
                  replace (sum_f_R0 (fun i => 2 * (x i * sum_f_R0 x n)) n)
                    with (2 * (sum_f_R0 x n) * (sum_f_R0 x n)).
                  2: { symmetry.
                       setoid_rewrite (wl_sum_scal_l 2 (fun i => x i * sum_f_R0 x n) n).
                       rewrite (wl_sum_scal_r (sum_f_R0 x n) x n). ring. }
                  reflexivity. }
            rewrite HAB. reflexivity.
          * reflexivity.
    }
    ring.
  }
  (* 0 ≤ 2(S n)Σx² − 2(Σx)² ⟹ (Σx)² ≤ (S n)Σx² *)
  rewrite HD_eq in HD.
  nra.
Qed.

(* ============ R1. 内积与 Gram 重排 ============ *)

Definition wl_dot (u : nat -> nat -> R) (i j : nat) (n : nat) : R :=
  sum_f_R0 (fun k => u i k * u j k) n.

(* Gram 平方和（i,j 于 0..A；k,l 于 0..B）：
   Σ_{i,j≤A} (Σ_{k≤B} u_ik·u_jk)² = Σ_{k,l≤B} (Σ_{i≤A} u_ik·u_il)²  *)
Lemma wl_gram_rearrange (u : nat -> nat -> R) (A B : nat) :
  sum_f_R0 (fun i => sum_f_R0 (fun j =>
    (wl_dot u i j B) * (wl_dot u i j B)) A) A
  = sum_f_R0 (fun k => sum_f_R0 (fun l =>
    (sum_f_R0 (fun i => u i k * u i l) A)
    * (sum_f_R0 (fun i => u i k * u i l) A)) B) B.
Proof.
  (* 第一段：X = Σ_{i,j}Σ_{k,l} u_ik·u_jk·u_il·u_jl（内积平方展开） *)
  transitivity (sum_f_R0 (fun i => sum_f_R0 (fun j =>
    sum_f_R0 (fun k => sum_f_R0 (fun l => u i k * u j k * u i l * u j l) B) B) A) A).
  - apply wl_sum_ext. intros i Hi.
    apply wl_sum_ext. intros j Hj.
    unfold wl_dot.
    rewrite <- (wl_sum_sq_expand (fun k => u i k * u j k) B).
    apply wl_sum_ext. intros k Hk.
    apply wl_sum_ext. intros l Hl.
    ring.
  - (* 第二段：M = Σ_{k,l} (Σ_i u_ik·u_il)·(Σ_i u_ik·u_il)（换序 + 因式分解） *)
    transitivity (sum_f_R0 (fun k => sum_f_R0 (fun l =>
      (sum_f_R0 (fun i => u i k * u i l) A)
      * (sum_f_R0 (fun i => u i k * u i l) A)) B) B).
    + (* M = M'：sum4_swap + 内层因式分解 *)
      rewrite (wl_sum4_swap A B (fun i j k l => u i k * u j k * u i l * u j l)).
      apply wl_sum_ext. intros k Hk.
      apply wl_sum_ext. intros l Hl.
      rewrite <- (wl_sum_factor (fun i => u i k * u i l) (fun j => u j k * u j l) A).
      apply wl_sum_ext. intros i Hi.
      apply wl_sum_ext. intros j Hj.
      ring.
    + reflexivity.
Qed.

(* ============ R2. 对角截断 ============ *)

(* Σ_{k,l≤n} x_kl ≥ Σ_{k≤n} x_kk（x ≥ 0） *)
Lemma wl_dsum_diag_le (x : nat -> nat -> R) (n : nat) :
  (forall k l, le k n -> le l n -> 0 <= x k l) ->
  sum_f_R0 (fun k => x k k) n
  <= sum_f_R0 (fun k => sum_f_R0 (x k) n) n.
Proof.
  intros Hx.
  apply wl_sum_le. intros k Hk.
  apply (wl_sum_ge_diag (x k) n k).
  - exact Hk.
  - intros j Hj. apply Hx; [exact Hk | exact Hj].
Qed.

(* ============ R3. 单位范数 ============ *)

(* Σ_{i≤A} Σ_{k≤B} u_ik² = M（每个向量范数平方 1，共 S A 个） *)
Lemma wl_sum_unit_norm (u : nat -> nat -> R) (A B : nat) :
  (forall j, le j A -> sum_f_R0 (fun k => u j k * u j k) B = 1) ->
  sum_f_R0 (fun i => sum_f_R0 (fun k => u i k * u i k) B) A = INR (S A).
Proof.
  intros Hunit.
  transitivity (sum_f_R0 (fun _ : nat => 1) A).
  - apply wl_sum_ext. intros i Hi.
    apply Hunit. exact Hi.
  - apply wl_sum_one.
Qed.

(* ============ R4. Gram 上界（对角 1 + 非对角 μ²） ============ *)

(* |d| ≤ μ ⟹ d² ≤ μ²（Rabs 平方单调） *)
Lemma wl_sq_le_mu_sq (d mu : R) :
  Rabs d <= mu -> d * d <= mu * mu.
Proof.
  intros Habs.
  assert (Hmu0 : 0 <= mu) by (apply (Rle_trans _ (Rabs d)); [apply Rabs_pos | exact Habs]).
  replace (d * d)%R with ((Rabs d) * (Rabs d))%R.
  - apply (Rle_trans _ (mu * Rabs d)).
    + apply Rmult_le_compat_r; [apply Rabs_pos | exact Habs].
    + apply Rmult_le_compat_l; [exact Hmu0 | exact Habs].
  - replace (Rabs d * Rabs d)%R with (Rabs (d * d))%R by apply Rabs_mult.
    apply Rabs_pos_eq. apply Rle_0_sqr.
Qed.

Lemma wl_gram_upper (u : nat -> nat -> R) (M N : nat) (mu : R) :
  (lt N M) ->
  (forall j, lt j M -> sum_f_R0 (fun k => u j k * u j k) (Nat.pred N) = 1) ->
  (forall i j, lt i M -> lt j M -> i <> j ->
    Rabs (wl_dot u i j (Nat.pred N)) <= mu) ->
  sum_f_R0 (fun i => sum_f_R0 (fun j =>
    (wl_dot u i j (Nat.pred N)) * (wl_dot u i j (Nat.pred N))) (Nat.pred M)) (Nat.pred M)
  <= INR M + INR M * INR (M - 1) * (mu * mu).
Proof.
  intros HN Hunit Hcoh.
  (* 逐 i：Σ_j ⟨u_i,u_j⟩² ≤ 1 + (M−1)μ² *)
  assert (Hrow : forall i, lt i M ->
    sum_f_R0 (fun j => (wl_dot u i j (Nat.pred N)) * (wl_dot u i j (Nat.pred N))) (Nat.pred M)
    <= 1 + INR (M - 1) * (mu * mu)).
  { intros i Hi.
    (* 上界函数 b j = if j=?i then 1 else μ² *)
    apply (Rle_trans _ (sum_f_R0 (fun j => if Nat.eqb j i then 1 else mu * mu) (Nat.pred M))).
    - (* 逐项：⟨u_i,u_j⟩² ≤ b j *)
      apply wl_sum_le. intros j Hj.
      destruct (Nat.eqb_spec j i) as [Hji | Hji].
      + subst. simpl.
        (* ⟨u_i,u_i⟩² = 1：单位范数 *)
        unfold wl_dot.
        replace ((sum_f_R0 (fun k : nat => u i k * u i k) (Nat.pred N))
                 * (sum_f_R0 (fun k : nat => u i k * u i k) (Nat.pred N)))%R
          with 1%R.
        * reflexivity.
        * rewrite (Hunit i Hi). ring.
      + simpl.
        (* ⟨u_i,u_j⟩² ≤ μ²：由 |⟨⟩| ≤ μ（Rabs 平方单调，无需 0 ≤ ⟨⟩） *)
        assert (Habs : Rabs (wl_dot u i j (Nat.pred N)) <= mu).
        { apply Hcoh.
          - exact Hi.
          - lia.
          - intro Hij. apply Hji. symmetry. exact Hij. }
        assert (Hmu0 : 0 <= mu).
        { apply (Rle_trans _ (Rabs (wl_dot u i j (Nat.pred N)))); [apply Rabs_pos | exact Habs]. }
        assert (Hsq := wl_sq_le_mu_sq (wl_dot u i j (Nat.pred N)) mu Habs).
        exact Hsq.
    - (* Σ_j b j = 1 + (M−1)μ²（拆 i 项：1 + μ²·非对角项数） *)
      replace (sum_f_R0 (fun j => if Nat.eqb j i then 1 else mu * mu) (Nat.pred M))
        with (sum_f_R0 (fun j =>
                (if Nat.eqb j i then 0 else mu * mu) + (if Nat.eqb j i then 1 else 0)) (Nat.pred M)).
      2: { apply wl_sum_ext. intros j0 Hj0.
           destruct (Nat.eqb_spec j0 i); simpl; ring. }
      (* Σ_j [(if 0 else μ²)+(if 1 else 0)] = μ²·(M−1) + 1 *)
      replace (sum_f_R0 (fun j =>
              (if Nat.eqb j i then 0 else mu * mu) + (if Nat.eqb j i then 1 else 0)) (Nat.pred M))
        with (INR (M - 1) * (mu * mu) + 1).
      2: { assert (Hsplit : sum_f_R0 (fun j : nat => (if Nat.eqb j i then 0 else mu * mu) + (if Nat.eqb j i then 1 else 0)) (Nat.pred M)
                        = sum_f_R0 (fun j : nat => if Nat.eqb j i then 0 else mu * mu) (Nat.pred M)
                          + sum_f_R0 (fun j : nat => if Nat.eqb j i then 1 else 0) (Nat.pred M)).
           { exact (wl_sum_add (fun j => if Nat.eqb j i then 0 else mu * mu)
                               (fun j => if Nat.eqb j i then 1 else 0) (Nat.pred M)). }
           assert (H1 : sum_f_R0 (fun j : nat => if Nat.eqb j i then 0 else mu * mu) (Nat.pred M)
                           = (mu * mu) * INR (M - 1)).
           { transitivity (sum_f_R0 (fun j : nat => (mu * mu) * (if Nat.eqb j i then 0 else 1)) (Nat.pred M)).
             - apply wl_sum_ext. intros j Hj. destruct (Nat.eqb_spec j i); simpl; ring.
             - transitivity ((mu * mu) * sum_f_R0 (fun j : nat => if Nat.eqb j i then 0 else 1) (Nat.pred M)).
               + exact (wl_sum_scal_l (mu * mu) (fun j : nat => if Nat.eqb j i then 0 else 1) (Nat.pred M)).
               + f_equal. apply wl_count_offdiag. exact Hi. }
           assert (H2 : sum_f_R0 (fun j : nat => if Nat.eqb j i then 1 else 0) (Nat.pred M) = 1).
           { exact (wl_count_diag M i Hi). }
           rewrite Hsplit H1 H2. ring. }
      lra. }
  (* 汇总：Σ_i [1 + (M−1)μ²] = M + M(M−1)μ² *)
  apply (Rle_trans _ (sum_f_R0 (fun i => 1 + INR (M - 1) * (mu * mu)) (Nat.pred M))).
  - apply wl_sum_le. intros i Hi.
    apply Hrow. lia.
  - rewrite (wl_sum_add (fun _ => 1) (fun _ => INR (M - 1) * (mu * mu)) (Nat.pred M)).
    rewrite wl_sum_one.
    rewrite (wl_sum_const (INR (M - 1) * (mu * mu)) (Nat.pred M)).
    replace (INR (S (Nat.pred M)))%R with (INR M)%R by (f_equal; lia).
    lra.
Qed.

(* ============ R5. ★ 主定理：Welch 界 ============ *)

Theorem wl_welch_bound (M N : nat) (u : nat -> nat -> R) (mu : R) :
  (le 1 N) -> (lt N M) ->
  (forall j, lt j M -> sum_f_R0 (fun k => u j k * u j k) (Nat.pred N) = 1) ->
  (forall i j, lt i M -> lt j M -> i <> j ->
    Rabs (wl_dot u i j (Nat.pred N)) <= mu) ->
  (INR M - INR N <= INR N * INR (M - 1) * (mu * mu))%R.
Proof.
  intros HN1 HN Hunit Hcoh.
  (* Gram 平方和 G *)
  set (G := sum_f_R0 (fun i => sum_f_R0 (fun j =>
    (wl_dot u i j (Nat.pred N)) * (wl_dot u i j (Nat.pred N))) (Nat.pred M)) (Nat.pred M)).
  (* 上界：G ≤ M + M(M−1)μ² *)
  assert (HGhi : G <= INR M + INR M * INR (M - 1) * (mu * mu)).
  { unfold G. exact (wl_gram_upper u M N mu HN Hunit Hcoh). }
  (* 下界：INR N·G ≥ (INR M)² *)
  assert (HGlo : (INR M) * (INR M) <= INR N * G).
  { unfold G.
    rewrite (wl_gram_rearrange u (Nat.pred M) (Nat.pred N)).
    (* x_k := Σ_{i≤Nat.pred M} u_ik²（行向量范数平方） *)
    set (x := fun k => sum_f_R0 (fun i => u i k * u i k) (Nat.pred M)).
    (* a) 对角截断：Σ_k x_k² ≤ Σ_{k,l}(Σ_i u_ik u_il)²（= G 行向量 Gram） *)
    assert (Hdiag : sum_f_R0 (fun k => x k * x k) (Nat.pred N)
                    <= sum_f_R0 (fun k => sum_f_R0 (fun l =>
                        (sum_f_R0 (fun i => u i k * u i l) (Nat.pred M))
                        * (sum_f_R0 (fun i => u i k * u i l) (Nat.pred M))) (Nat.pred N)) (Nat.pred N)).
    { apply (wl_dsum_diag_le (fun k l => (sum_f_R0 (fun i => u i k * u i l) (Nat.pred M))
                                       * (sum_f_R0 (fun i => u i k * u i l) (Nat.pred M))) (Nat.pred N)).
      intros k l Hk Hl. apply Rle_0_sqr. }
    (* b) CS 幂平均：N·Σ_k x_k² ≥ (Σ_k x_k)²（N = S(Nat.pred N) ≥ 1） *)
    assert (Hcs : (sum_f_R0 x (Nat.pred N)) * (sum_f_R0 x (Nat.pred N))
                  <= INR N * sum_f_R0 (fun k => x k * x k) (Nat.pred N)).
    { replace (INR N)%R with (INR (S (Nat.pred N)))%R by (f_equal; lia).
      apply wl_sum_sq_ge_mean_sq. intros k Hk.
      unfold x. apply wl_sum_nonneg. intros i Hi. apply Rle_0_sqr. }
    (* c) Σ_k x_k = M（单位范数） *)
    assert (Hxsum : sum_f_R0 x (Nat.pred N) = INR M).
    { unfold x.
      rewrite (wl_sum_swap (Nat.pred N) (Nat.pred M) (fun k i => u i k * u i k)).
      transitivity (sum_f_R0 (fun i => sum_f_R0 (fun k => u i k * u i k) (Nat.pred N)) (Nat.pred M)).
      - apply wl_sum_ext. intros i Hi. apply wl_sum_ext. intros k Hk. ring.
      - assert (Hunit' : forall j : nat, le j (Nat.pred M) -> sum_f_R0 (fun k => u j k * u j k) (Nat.pred N) = 1)
          by (intros j Hj; apply Hunit; lia).
        rewrite (wl_sum_unit_norm u (Nat.pred M) (Nat.pred N) Hunit').
        replace (INR (S (Nat.pred M)))%R with (INR M)%R by (f_equal; lia).
        reflexivity. }
    (* 组装：M² ≤ N·Σx² ≤ N·G *)
    rewrite Hxsum in Hcs.
    apply (Rle_trans _ (INR N * sum_f_R0 (fun k => x k * x k) (Nat.pred N))).
    - exact Hcs.
    - apply Rmult_le_compat_l.
      + apply pos_INR.
      + exact Hdiag. }
  (* 收尾：M² ≤ N·G ≤ N·(M + M(M−1)μ²) ⟹ M(M−N) ≤ NM(M−1)μ² ⟹ M−N ≤ N(M−1)μ² *)
  assert (Hprod : (INR M) * (INR M - INR N)
                  <= INR N * INR M * INR (M - 1) * (mu * mu)).
  { assert (Hmid : (INR M) * (INR M)
                   <= INR N * (INR M + INR M * INR (M - 1) * (mu * mu))).
    { apply (Rle_trans _ (INR N * G)); [exact HGlo | ].
      apply Rmult_le_compat_l; [apply pos_INR | exact HGhi]. }
    nra. }
  assert (HMpos : 0 < INR M).
  { apply lt_0_INR. lia. }
  apply (Rmult_le_reg_l (INR M) (INR M - INR N)
         (INR N * INR (M - 1) * (mu * mu)) HMpos).
  replace (INR M * (INR N * INR (M - 1) * (mu * mu)))%R
    with (INR N * INR M * INR (M - 1) * (mu * mu))%R by ring.
  exact Hprod.
Qed.



























(* ==================== 模块 46/67: probe_uncertainty_cr ==================== *)

Close Scope R_scope.
Close Scope Z_scope.
(* ============================================================
   F5 不确定性原理（纯构造性 CR 版，probe_uncertainty_cr）
   纪律：纯构造性——Stdlib ConstructiveReals，零经典实数、
         零 Admitted、零自定义公理；35 定理全 Qed，
         Print Assumptions 全部 Closed under the global context。
   主定理 CRuncertainty_principle：相干字典不确定原理（唯一性正形式，
   Donoho-Stark 标准，常数 1+1/μ）。
   数学内容：若字典 {u_j}（单位范数、相干 ≤ μ）上同一信号 x 有两个稀疏表示，
   则两表示在支撑上逐点相同（|T1|+|T2|−1 的相干窗口）。
   ============================================================ *)
Require Import ConstructiveReals.
From Stdlib Require Import ConstructiveRealsMorphisms.
From Stdlib Require Import ConstructiveAbs.
From Stdlib Require Import ConstructiveSum.
From Stdlib Require Import QArith.
From Stdlib Require Import ZArith.
From Stdlib Require Import Lia.
From Stdlib Require Import List.
Import ListNotations.
From mathcomp Require Import ssreflect ssrbool ssrnat seq eqtype div prime.

Local Open Scope ConstructiveReals.

Section F5Uncertainty.

Context {R : ConstructiveReals}.
Add Ring CR_ring : (CRisRing R).

(* ============ A. 列表基础设施 ============ *)

(* 标量乘复数 *)
Definition scal (c : CRcarrier R) (z : CRComplex) : CRComplex :=
  {| cre := c * cre z; cim := c * cim z |}.

(* 列表和（尾部优先；顺序由 ring 交换律吸收） *)
Fixpoint lst_sum (T : list nat) (f : nat -> CRcarrier R) : CRcarrier R :=
  match T with
  | nil => CR_of_Q R (Qmake 0 1)
  | j :: T' => lst_sum T' f + f j
  end.

(* 平方和 / 绝对值 ℓ1 和 *)
Definition lst_sqsum (T : list nat) (e : nat -> CRcarrier R) : CRcarrier R :=
  lst_sum T (fun j => e j * e j).
Definition lst_abs_sum (T : list nat) (e : nat -> CRcarrier R) : CRcarrier R :=
  lst_sum T (fun j => CRabs R (e j)).

(* 列表线性组合 *)
Fixpoint lst_combo (T : list nat) (e : nat -> CRcarrier R) (u : nat -> CRComplex) : CRComplex :=
  match T with
  | nil => CRzero
  | j :: T' => CRadd (lst_combo T' e u) (scal (e j) (u j))
  end.

(* lst_sum 单调（逐点 ≤ ⟹ 和 ≤） *)
Lemma lst_sum_le (T : list nat) (f g : nat -> CRcarrier R) :
  (forall j, In j T -> CRle R (f j) (g j)) ->
  CRle R (lst_sum T f) (lst_sum T g).
Proof.
  induction T as [| j T' IH]; intros Hle.
  - apply CRle_refl.
  - cbn [lst_sum].
    apply (CRle_trans (R:=R) (lst_sum T' f + f j) (lst_sum T' g + f j) (lst_sum T' g + g j)).
    + apply (CRplus_le_compat_r (R:=R) (f j)).
      apply IH. intros k Hk. apply Hle. right. exact Hk.
    + apply (CRplus_le_compat_l (R:=R) (lst_sum T' g)).
      apply Hle. left. reflexivity.
Qed.

(* lst_sum 逐点相等（CReq） *)
Lemma lst_sum_morph (T : list nat) (f g : nat -> CRcarrier R) :
  (forall j, In j T -> CReq R (f j) (g j)) ->
  CReq R (lst_sum T f) (lst_sum T g).
Proof.
  induction T as [| j T' IH]; intros Heq.
  - reflexivity.
  - cbn [lst_sum].
    split.
    + apply (CRplus_le_compat (R:=R) (lst_sum T' g) (lst_sum T' f) (g j) (f j)).
      * exact (proj1 (IH (fun k Hk => Heq k (or_intror Hk)))).
      * exact (proj1 (Heq j (or_introl Logic.eq_refl))).
    + apply (CRplus_le_compat (R:=R) (lst_sum T' f) (lst_sum T' g) (f j) (g j)).
      * exact (proj2 (IH (fun k Hk => Heq k (or_intror Hk)))).
      * exact (proj2 (Heq j (or_introl Logic.eq_refl))).
Qed.

(* lst_sum 非负（逐项非负 ⟹ 和非负） *)
Lemma lst_sum_nonneg (T : list nat) (f : nat -> CRcarrier R) :
  (forall j, In j T -> CRle R (CR_of_Q R (Qmake 0 1)) (f j)) ->
  CRle R (CR_of_Q R (Qmake 0 1)) (lst_sum T f).
Proof.
  induction T as [| j T' IH]; intros Hn.
  - apply CRle_refl.
  - cbn [lst_sum].
    rewrite <- (CRplus_0_l (R:=R) (CR_of_Q R (Qmake 0 1))).
    apply (CRplus_le_compat (R:=R)
      (CR_of_Q R (Qmake 0 1)) (lst_sum T' f)
      (CR_of_Q R (Qmake 0 1)) (f j)).
    + apply IH. intros k Hk. apply Hn. right. exact Hk.
    + apply Hn. left. reflexivity.
Qed.

(* lst_sum 缩放：Σ (a·f j) == a·Σ f *)
Lemma lst_sum_scale (T : list nat) (f : nat -> CRcarrier R) (a : CRcarrier R) :
  CReq R (lst_sum T (fun j => a * f j)) (a * lst_sum T f).
Proof.
  induction T as [| j T' IH].
  - cbn [lst_sum]. ring.
  - cbn [lst_sum]. rewrite IH. ring.
Qed.

(* lst_sum 常数：Σ (fun _ => a) == a·INR(|T|) *)
(* 辅助：INR 0 == 0 *)
Lemma INR0_eq :
  CReq R (INR 0) (CR_of_Q R (Qmake 0 1)).
Proof.
  unfold INR.
  apply (CR_of_Q_morph R (Z.of_nat 0 # 1) (0 # 1)).
  unfold Qeq. cbn. reflexivity.
Qed.

Lemma lst_sum_const (T : list nat) (a : CRcarrier R) :
  CReq R (lst_sum T (fun _ : nat => a)) (a * INR (length T)).
Proof.
  induction T as [| j T' IH].
  - cbn [lst_sum length]. rewrite INR0_eq. ring.
  - cbn [lst_sum length].
    rewrite IH. rewrite (CR_INR_S (length T')). ring.
Qed.

(* 平方和 ≥ 0 *)
Lemma lst_sqsum_nonneg (T : list nat) (e : nat -> CRcarrier R) :
  CRle R (CR_of_Q R (Qmake 0 1)) (lst_sqsum T e).
Proof.
  unfold lst_sqsum.
  apply lst_sum_nonneg.
  intro j. intro Hj.
  exact (CRsqr_nonneg (e j)).
Qed.

(* AM-GM 列表求和：2|a|·Σ_{j∈T}|e_j| ≤ |T|·a² + Σ_{j∈T} e_j²
   （CRabs_amgm 逐项 2|a||e_j| ≤ a²+e_j²，求和 + 常数项 = |T|a²） *)
Lemma lst_sum_amgm (T : list nat) (a : CRcarrier R) (e : nat -> CRcarrier R) :
  CRle R ((1 + 1) * CRabs R a * lst_abs_sum T e)
         (a * a * INR (length T) + lst_sqsum T e).
Proof.
  unfold lst_abs_sum, lst_sqsum.
  assert (Hl : CReq R ((1 + 1) * CRabs R a * lst_sum T (fun j => CRabs R (e j)))
                       (lst_sum T (fun j => (1 + 1) * (CRabs R a * CRabs R (e j))))).
  { assert (Hcomm : CReq R ((1 + 1) * CRabs R a * lst_sum T (fun j => CRabs R (e j)))
                            ((1 + 1) * (CRabs R a * lst_sum T (fun j => CRabs R (e j))))). { ring. }
    rewrite Hcomm.
    rewrite <- (lst_sum_scale T (fun j => CRabs R (e j)) (CRabs R a)).
    rewrite <- (lst_sum_scale T (fun j => CRabs R a * CRabs R (e j)) (1 + 1)).
    reflexivity. }
  rewrite Hl.
  clear Hl.
  apply (CRle_trans (R:=R)
    (lst_sum T (fun j => (1 + 1) * (CRabs R a * CRabs R (e j))))
    (lst_sum T (fun j => a * a + e j * e j))
    (a * a * INR (length T) + lst_sum T (fun j => e j * e j))).
  - apply lst_sum_le. intro j. intro Hj. exact (CRabs_amgm a (e j)).
  - induction T as [| k T'' IH2].
    + cbn [lst_sum length]. rewrite INR0_eq.
      assert (Hz : CReq R (a * a * CR_of_Q R (Qmake 0 1) + CR_of_Q R (Qmake 0 1))
                           (CR_of_Q R (Qmake 0 1))). { ring. }
      apply (proj1 Hz).
    + cbn [lst_sum length].
      apply (CRle_trans (R:=R)
        (lst_sum T'' (fun j => a * a + e j * e j) + (a * a + e k * e k))
        ((a * a * INR (length T'') + lst_sum T'' (fun j => e j * e j)) + (a * a + e k * e k))
        (a * a * INR (S (length T'')) + (lst_sum T'' (fun j => e j * e j) + e k * e k))).
      * apply (CRplus_le_compat (R:=R)
          (lst_sum T'' (fun j => a * a + e j * e j))
          (a * a * INR (length T'') + lst_sum T'' (fun j => e j * e j))
          (a * a + e k * e k) (a * a + e k * e k)).
        -- exact IH2.
        -- apply CRle_refl.
      * assert (Hr : CReq R
          ((a * a * INR (length T'') + lst_sum T'' (fun j => e j * e j)) + (a * a + e k * e k))
          (a * a * INR (S (length T'')) + (lst_sum T'' (fun j => e j * e j) + e k * e k))).
        { rewrite (CR_INR_S (length T'')). ring. }
        apply (proj2 Hr).
Qed.

(* ============ B. 范数平方展开 ============ *)

(* 标量范数：‖c·z‖² == c²·‖z‖² *)
Lemma scal_norm_sq (c : CRcarrier R) (z : CRComplex) :
  CReq R (CRnorm_sq (scal c z)) (c * c * CRnorm_sq z).
Proof.
  unfold CRnorm_sq, scal. cbn [cre cim]. ring.
Qed.

(* ‖lst_combo (j::T)‖² == ‖lst_combo T‖² + e_j²·‖u_j‖² + 2e_j·⟨lst_combo T, u_j⟩ *)
Lemma lst_combo_norm_sq_cons (j : nat) (T : list nat) (e : nat -> CRcarrier R) (u : nat -> CRComplex) :
  CReq R (CRnorm_sq (lst_combo (j :: T) e u))
         (CRnorm_sq (lst_combo T e u)
          + e j * e j * CRnorm_sq (u j)
          + (1 + 1) * e j * CRip (lst_combo T e u) (u j)).
Proof.
  cbn [lst_combo].
  unfold CRnorm_sq, CRip, scal, CRadd.
  cbn [cre cim].
  ring.
Qed.

(* ============ C. 列表三角 + 相干上界 ============ *)

(* 辅助：−x ≤ |x| *)
Lemma CRopp_abs_le (x : CRcarrier R) :
  CRle R (CRopp R x) (CRabs R x).
Proof.
  apply (CRle_trans (R:=R) (CRopp R x) (CRabs R (CRopp R x)) (CRabs R x)).
  - exact (CRle_abs_self (CRopp R x)).
  - apply (proj2 (CRabs_opp (R:=R) x)).
Qed.

(* 辅助：−(a·ip) ≤ |a||ip| ⟹ 0 ≤ 2a·ip + 2|a||ip| *)
Lemma zero_le_two_ip (a ip : CRcarrier R) :
  CRle R (CRopp R (a * ip)) (CRabs R a * CRabs R ip) ->
  CRle R (CR_of_Q R (Qmake 0 1))
         ((1 + 1) * (a * ip) + (1 + 1) * (CRabs R a * CRabs R ip)).
Proof.
  intros Hle.
  apply (CRplus_le_reg_l (R:=R) (CRopp R ((1 + 1) * (a * ip)))).
  assert (Hl1 : CReq R (CRopp R ((1 + 1) * (a * ip)) + CR_of_Q R (Qmake 0 1))
                       (CRopp R ((1 + 1) * (a * ip)))). { ring. }
  rewrite Hl1.
  assert (Hl2 : CReq R (CRopp R ((1 + 1) * (a * ip))
                         + ((1 + 1) * (a * ip) + (1 + 1) * (CRabs R a * CRabs R ip)))
                       ((1 + 1) * (CRabs R a * CRabs R ip))). { ring. }
  rewrite Hl2.
  (* 目标：−((1+1)(a·ip)) ≤ (1+1)(|a||ip|)；由 Hle 乘 (1+1) ≥ 0 *)
  assert (Hring : CReq R (CRopp R ((1 + 1) * (a * ip)))
                           ((1 + 1) * (CRopp R (a * ip)))). { ring. }
  rewrite Hring.
  apply (CRmult_le_compat_l (R:=R) (1 + 1) (CRopp R (a * ip)) (CRabs R a * CRabs R ip)).
  - exact CR0_le_two.
  - exact Hle.
Qed.

(* |⟨Σ_T e_k u_k, v⟩| ≤ Σ_T |e_k|·|⟨u_k,v⟩| *)
Lemma lst_combo_ip_abs_le_sum (T : list nat) (e : nat -> CRcarrier R) (u : nat -> CRComplex) (v : CRComplex) :
  CRle R (CRabs R (CRip (lst_combo T e u) v))
         (lst_sum T (fun j => CRabs R (e j) * CRabs R (CRip (u j) v))).
Proof.
  induction T as [| j T' IH].
  - cbn [lst_combo lst_sum].
    unfold CRip. cbn [cre cim].
    assert (Hz : CReq R (cre CRzero * cre v + cim CRzero * cim v) (CR_of_Q R (Qmake 0 1))).
    { unfold CRzero. cbn. ring. }
    rewrite Hz.
    rewrite (CRabs_right (R:=R) (CR_of_Q R (Qmake 0 1)) (CRle_refl (R:=R) (CR_of_Q R (Qmake 0 1)))).
    apply CRle_refl.
  - cbn [lst_combo].
    assert (Hlin : CReq R (CRip (CRadd (lst_combo T' e u) (scal (e j) (u j))) v)
                           (CRip (lst_combo T' e u) v + CRip (scal (e j) (u j)) v)).
    { unfold CRip, CRadd, scal. cbn [cre cim]. ring. }
    apply (CRle_trans (R:=R)
      (CRabs R (CRip (CRadd (lst_combo T' e u) (scal (e j) (u j))) v))
      (CRabs R (CRip (lst_combo T' e u) v) + CRabs R (CRip (scal (e j) (u j)) v))
      (lst_sum T' (fun j0 => CRabs R (e j0) * CRabs R (CRip (u j0) v))
       + CRabs R (e j) * CRabs R (CRip (u j) v))).
    + rewrite Hlin.
      exact (CRabs_triang (R:=R) (CRip (lst_combo T' e u) v) (CRip (scal (e j) (u j)) v)).
    + apply (CRplus_le_compat (R:=R)
        (CRabs R (CRip (lst_combo T' e u) v))
        (lst_sum T' (fun j0 => CRabs R (e j0) * CRabs R (CRip (u j0) v)))
        (CRabs R (CRip (scal (e j) (u j)) v))
        (CRabs R (e j) * CRabs R (CRip (u j) v))).
      * exact IH.
      * assert (Heq : CReq R (CRip (scal (e j) (u j)) v) (e j * CRip (u j) v)).
        { unfold CRip, scal. cbn [cre cim]. ring. }
        apply (CRle_trans (R:=R)
          (CRabs R (CRip (scal (e j) (u j)) v))
          (CRabs R (e j * CRip (u j) v))
          (CRabs R (e j) * CRabs R (CRip (u j) v))).
        -- apply (proj2 (CRabs_morph_prop R (CRip (scal (e j) (u j)) v) (e j * CRip (u j) v) Heq)).
        -- apply (proj2 (CRabs_mult (R:=R) (e j) (CRip (u j) v))).
Qed.

(* 相干上界（列表版）：∀k∈T: |⟨u_k,v⟩| ≤ μ ⟹ |⟨Σ_T e_k u_k, v⟩| ≤ μ·Σ_T |e_k| *)
Lemma lst_cross_abs_le (T : list nat) (e : nat -> CRcarrier R) (u : nat -> CRComplex)
  (v : CRComplex) (mu : CRcarrier R) :
  (CRle R (CR_of_Q R (Qmake 0 1)) mu) ->
  (forall j, In j T ->
    CRle R (CRabs R (CRip (u j) v)) mu) ->
  CRle R (CRabs R (CRip (lst_combo T e u) v))
         (mu * lst_abs_sum T e).
Proof.
  intros Hmu0 Hcoh.
  apply (CRle_trans (R:=R)
    (CRabs R (CRip (lst_combo T e u) v))
    (lst_sum T (fun j => CRabs R (e j) * CRabs R (CRip (u j) v)))
    (mu * lst_abs_sum T e)).
  - exact (lst_combo_ip_abs_le_sum T e u v).
  - unfold lst_abs_sum.
    apply (CRle_trans (R:=R)
      (lst_sum T (fun j => CRabs R (e j) * CRabs R (CRip (u j) v)))
      (lst_sum T (fun j => CRabs R (e j) * mu))
      (mu * lst_sum T (fun j => CRabs R (e j)))).
    + apply lst_sum_le. intro j. intro Hj.
      apply (CRmult_le_compat_l (R:=R) (CRabs R (e j))
        (CRabs R (CRip (u j) v)) mu).
      * exact (CRabs_pos (R:=R) (e j)).
      * exact (Hcoh j Hj).
    + assert (Hc : CReq R (lst_sum T (fun j => CRabs R (e j) * mu))
                           (lst_sum T (fun j => mu * CRabs R (e j)))).
      { apply lst_sum_morph. intro j. intro Hj.
        apply (CRmult_comm (R:=R) (CRabs R (e j)) mu). }
      rewrite Hc.
      apply (proj2 (lst_sum_scale T (fun j => CRabs R (e j)) mu)).
Qed.

(* 逐点 CReq ⟹ 组合 CReq_cplx *)
Lemma lst_combo_ext (T : list nat) (e f : nat -> CRcarrier R) (u : nat -> CRComplex) :
  (forall j, In j T -> CReq R (e j) (f j)) ->
  CReq_cplx (lst_combo T e u) (lst_combo T f u).
Proof.
  induction T as [| j T' IH]; intros Heq.
  - cbn [lst_combo].
    unfold CReq_cplx. split; split; apply CRle_refl.
  - cbn [lst_combo].
    assert (Hje : CReq R (e j) (f j)) by (exact (Heq j (or_introl Logic.eq_refl))).
    assert (Hjf : CReq R (f j) (e j)).
    { split; [exact (proj2 Hje) | exact (proj1 Hje)]. }
    assert (Hre : CReq R (e j * cre (u j)) (f j * cre (u j))).
    { apply (CRmult_morph R (e j) (f j) Hje (cre (u j)) (cre (u j))).
      reflexivity. }
    assert (Hrf : CReq R (f j * cre (u j)) (e j * cre (u j))).
    { apply (CRmult_morph R (f j) (e j) Hjf (cre (u j)) (cre (u j))).
      reflexivity. }
    assert (Hie : CReq R (e j * cim (u j)) (f j * cim (u j))).
    { apply (CRmult_morph R (e j) (f j) Hje (cim (u j)) (cim (u j))).
      reflexivity. }
    assert (Hif : CReq R (f j * cim (u j)) (e j * cim (u j))).
    { apply (CRmult_morph R (f j) (e j) Hjf (cim (u j)) (cim (u j))).
      reflexivity. }
    unfold CReq_cplx. split.
    + cbn [cre].
      split.
      * apply (CRplus_le_compat (R:=R)
          (cre (lst_combo T' f u)) (cre (lst_combo T' e u))
          (f j * cre (u j)) (e j * cre (u j))).
        -- exact (proj1 (proj1 (IH (fun j0 Hj0 => Heq j0 (or_intror Hj0))))).
        -- exact (proj2 Hrf).
      * apply (CRplus_le_compat (R:=R)
          (cre (lst_combo T' e u)) (cre (lst_combo T' f u))
          (e j * cre (u j)) (f j * cre (u j))).
        -- exact (proj2 (proj1 (IH (fun j0 Hj0 => Heq j0 (or_intror Hj0))))).
        -- exact (proj2 Hre).
    + cbn [cim].
      split.
      * apply (CRplus_le_compat (R:=R)
          (cim (lst_combo T' f u)) (cim (lst_combo T' e u))
          (f j * cim (u j)) (e j * cim (u j))).
        -- exact (proj1 (proj2 (IH (fun j0 Hj0 => Heq j0 (or_intror Hj0))))).
        -- exact (proj2 Hif).
      * apply (CRplus_le_compat (R:=R)
          (cim (lst_combo T' e u)) (cim (lst_combo T' f u))
          (e j * cim (u j)) (f j * cim (u j))).
        -- exact (proj2 (proj2 (IH (fun j0 Hj0 => Heq j0 (or_intror Hj0))))).
        -- exact (proj2 Hie).
Qed.

(* ============ E. 核心：列表 RIP 下界（常数 |T|−1） ============ *)

(* Σ_T e² ≤ ‖lst_combo T e u‖² + μ·(|T|−1)·Σ_T e²
   归纳：cons 步 = 范数展开（B）+ |⟨u_j,R⟩|≤μΣ'|e|（C）+ AM-GM 逐对（D）；
   链尾 n=0（T'=[]）与 n≥1 分情形（INR(n−1)+1 == INR n 需 n≥1）。 *)
Lemma lst_rip_lower (T : list nat) (e : nat -> CRcarrier R) (u : nat -> CRComplex) (mu : CRcarrier R) :
  NoDup T ->
  (CRle R (CR_of_Q R (Qmake 0 1)) mu) ->
  (forall j, In j T -> CReq R (CRnorm_sq (u j)) (CR_of_Q R (Qmake 1 1))) ->
  (forall i j, In i T -> In j T -> i <> j ->
    CRle R (CRabs R (CRip (u i) (u j))) mu) ->
  CRle R (lst_sqsum T e)
         (CRnorm_sq (lst_combo T e u) + mu * INR (length T - 1) * lst_sqsum T e).
Proof.
  induction T as [| j T' IH]; intros Hdup Hmu0 Hunit Hcoh.
  - (* T=[]：0 ≤ 0 + mu·INR 0·0 *)
    cbn [lst_sqsum lst_sum lst_combo length].
    unfold CRnorm_sq. cbn [cre cim].
    assert (Hz : CReq R (CR_of_Q R (Qmake 0 1))
                         (CR_of_Q R (Qmake 0 1) * CR_of_Q R (Qmake 0 1) + CR_of_Q R (Qmake 0 1) * CR_of_Q R (Qmake 0 1)
                          + mu * INR (0 - 1) * CR_of_Q R (Qmake 0 1))).
    { change (@INR R (0 - 1)) with (@INR R 0). rewrite INR0_eq. ring. }
    apply (proj2 Hz).
  - destruct T' as [| j' T''].
    + (* T = [j]（T'=[]）：0+a² ≤ ‖lst_combo [j]‖² + mu·INR 0·(0+a²)，且 ‖·‖² == a² *)
      cbn [lst_sqsum lst_sum length].
      assert (Hnorm : CReq R (CRnorm_sq (lst_combo (j :: []) e u)) (e j * e j)).
      { cbn [lst_combo]. unfold CRnorm_sq, CRadd, scal. cbn [cre cim].
        assert (Hring : CReq R
          ((CR_of_Q R (Qmake 0 1) + e j * cre (u j)) * (CR_of_Q R (Qmake 0 1) + e j * cre (u j))
           + (CR_of_Q R (Qmake 0 1) + e j * cim (u j)) * (CR_of_Q R (Qmake 0 1) + e j * cim (u j)))
          (e j * e j * (cre (u j) * cre (u j) + cim (u j) * cim (u j)))). { ring. }
        rewrite Hring.
        change (cre (u j) * cre (u j) + cim (u j) * cim (u j)) with (CRnorm_sq (u j)).
        rewrite (Hunit j (or_introl Logic.eq_refl)).
        ring. }
      assert (Hl0 : CReq R (CR_of_Q R (Qmake 0 1) + e j * e j) (e j * e j)).
      { ring. }
      apply (CRle_trans (R:=R) (CR_of_Q R (Qmake 0 1) + e j * e j)
        (e j * e j)
        (CRnorm_sq (lst_combo (j :: []) e u)
         + mu * INR (0 - 1) * (CR_of_Q R (Qmake 0 1) + e j * e j))).
      * rewrite Hl0. apply CRle_refl.
      * apply (CRle_trans (R:=R) (e j * e j)
          (CRnorm_sq (lst_combo (j :: []) e u))
          (CRnorm_sq (lst_combo (j :: []) e u)
           + mu * INR (0 - 1) * (CR_of_Q R (Qmake 0 1) + e j * e j))).
        -- apply (proj1 Hnorm).
        -- apply (Rplus_le_pos (R:=R) (CRnorm_sq (lst_combo (j :: []) e u))
             (mu * INR (0 - 1) * (CR_of_Q R (Qmake 0 1) + e j * e j))).
           assert (Hz : CReq R (CR_of_Q R (Qmake 0 1))
                                (mu * INR (0 - 1) * (CR_of_Q R (Qmake 0 1) + e j * e j))).
           { change (@INR R (0 - 1)) with (@INR R 0). rewrite INR0_eq. ring. }
           apply (proj2 Hz).
    + (* T = j :: j' :: T''：|(j' :: T'')| = S(length T'') ≥ 1 *)
      assert (Hnj : ~ In j (j' :: T'')) by (inversion Hdup; assumption).
      assert (Hdup' : NoDup (j' :: T'')) by (inversion Hdup; assumption).
      cbn [length].
      set (a := e j).
      set (S' := lst_sqsum (j' :: T'') e).
      set (R' := lst_combo (j' :: T'') e u).
      set (L1' := lst_abs_sum (j' :: T'') e).
      (* IH 截取到 (j' :: T'') *)
      assert (HIH : CRle R S' (CRnorm_sq R' + mu * INR (length (j' :: T'') - 1) * S')).
      { unfold S', R'.
        apply IH.
        - exact Hdup'.
        - exact Hmu0.
        - intros j0 Hj0. apply Hunit. right. exact Hj0.
        - intros i j0 Hi Hj0 Hne. apply Hcoh.
          + right. exact Hi.
          + right. exact Hj0.
          + exact Hne. }
      (* [2]：|⟨R', u_j⟩| ≤ mu·L1' *)
      assert (Hcross : CRle R (CRabs R (CRip R' (u j))) (mu * L1')).
      { unfold R', L1'.
        apply (lst_cross_abs_le (j' :: T'') e u (u j) mu Hmu0).
        intros k Hk. apply Hcoh.
        - right. exact Hk.
        - left. reflexivity.
        - intro Hkj. subst k. exact (Hnj Hk). }
      assert (Hcross2 : CRle R ((1 + 1) * CRabs R a * CRabs R (CRip R' (u j)))
                               ((1 + 1) * CRabs R a * (mu * L1'))).
      { apply (CRmult_le_compat_l (R:=R) ((1 + 1) * CRabs R a)
          (CRabs R (CRip R' (u j))) (mu * L1')).
        - apply CRmult_le_0_compat.
          + exact CR0_le_two.
          + apply CRabs_pos.
        - exact Hcross. }
      (* [3]：‖R'‖² + a² ≤ ‖lst_combo (j::(j' :: T''))‖² + 2|a|·|⟨R',u_j⟩| *)
      assert (H3 : CRle R (CRnorm_sq R' + a * a)
                   (CRnorm_sq (lst_combo (j :: j' :: T'') e u)
                    + (1 + 1) * CRabs R a * CRabs R (CRip R' (u j)))).
      { unfold R'.
        rewrite (lst_combo_norm_sq_cons j (j' :: T'') e u).
        rewrite (Hunit j (or_introl Logic.eq_refl)).
        (* 目标：‖·‖²+a² ≤ ‖·‖²+e_j²+2e_j⟨⟩+2|a||⟨⟩|
           链：X ≤ X+Y [Rplus_le_pos] == 目标 RHS [ring] *)
        apply (CRle_trans (R:=R) (CRnorm_sq (lst_combo (j' :: T'') e u) + a * a)
          (CRnorm_sq (lst_combo (j' :: T'') e u) + a * a
           + ((1 + 1) * (a * CRip (lst_combo (j' :: T'') e u) (u j))
              + (1 + 1) * (CRabs R a * CRabs R (CRip (lst_combo (j' :: T'') e u) (u j)))))
          (CRnorm_sq (lst_combo (j' :: T'') e u) + e j * e j * CR_of_Q R (Qmake 1 1)
           + (1 + 1) * e j * CRip (lst_combo (j' :: T'') e u) (u j)
           + (1 + 1) * CRabs R a * CRabs R (CRip (lst_combo (j' :: T'') e u) (u j)))).
        - apply (Rplus_le_pos (R:=R) (CRnorm_sq (lst_combo (j' :: T'') e u) + a * a)
            ((1 + 1) * (a * CRip (lst_combo (j' :: T'') e u) (u j))
             + (1 + 1) * (CRabs R a * CRabs R (CRip (lst_combo (j' :: T'') e u) (u j))))).
          apply (zero_le_two_ip a (CRip (lst_combo (j' :: T'') e u) (u j))).
          apply (CRle_trans (R:=R)
            (CRopp R (a * CRip (lst_combo (j' :: T'') e u) (u j)))
            (CRabs R (a * CRip (lst_combo (j' :: T'') e u) (u j)))
            (CRabs R a * CRabs R (CRip (lst_combo (j' :: T'') e u) (u j)))).
          * exact (CRopp_abs_le (a * CRip (lst_combo (j' :: T'') e u) (u j))).
          * apply (proj2 (CRabs_mult (R:=R) a (CRip (lst_combo (j' :: T'') e u) (u j)))).
        - assert (Hr : CReq R (CRnorm_sq (lst_combo (j' :: T'') e u) + a * a
                                + ((1 + 1) * (a * CRip (lst_combo (j' :: T'') e u) (u j))
                                   + (1 + 1) * (CRabs R a * CRabs R (CRip (lst_combo (j' :: T'') e u) (u j)))))
                              (CRnorm_sq (lst_combo (j' :: T'') e u) + e j * e j * CR_of_Q R (Qmake 1 1)
                               + (1 + 1) * e j * CRip (lst_combo (j' :: T'') e u) (u j)
                               + (1 + 1) * CRabs R a * CRabs R (CRip (lst_combo (j' :: T'') e u) (u j)))).
          { unfold a. ring. }
          apply (proj2 Hr). }
      (* [4]：2|a|·mu·L1' ≤ mu·(|T'|a² + S')（AM-GM 乘 mu） *)
      assert (H4 : CRle R (mu * ((1 + 1) * CRabs R a * lst_abs_sum (j' :: T'') e))
                           (mu * (a * a * INR (length (j' :: T'')) + S'))).
      { apply (CRmult_le_compat_l (R:=R) mu
          ((1 + 1) * CRabs R a * lst_abs_sum (j' :: T'') e)
          (a * a * INR (length (j' :: T'')) + lst_sqsum (j' :: T'') e)).
        - exact Hmu0.
        - unfold S'. exact (lst_sum_amgm (j' :: T'') a e). }
      (* 组装：M1 ≤ M2 ≤ M3 ≤ M4 == M5
         M1 := S'+a²；M2 := (‖R'‖²+a²)+mu·INR(n)·S'；
         M3 := (‖L‖²+2|a|muL1')+mu·INR(n)·S'；M4 := (‖L‖²+mu(|T'|a²+S'))+mu·INR(n)·S'；
         M5 := ‖L‖²+mu·INR(Sn)·(S'+a²)，n := length (j'::T'')−1，L := lst_combo (j::j'::T'') e u *)
      apply (CRle_trans (R:=R) (S' + a * a)
        ((CRnorm_sq R' + a * a) + mu * INR (length (j' :: T'') - 1) * S')
        (CRnorm_sq (lst_combo (j :: j' :: T'') e u) + mu * INR (length (j' :: T'')) * (S' + a * a))).
      - (* M1 ≤ M2：HIH 加 a² + ring 对齐 *)
        apply (CRle_trans (R:=R) (S' + a * a)
          ((CRnorm_sq R' + mu * INR (length (j' :: T'') - 1) * S') + a * a)
          ((CRnorm_sq R' + a * a) + mu * INR (length (j' :: T'') - 1) * S')).
        + apply (CRplus_le_compat_r (R:=R) (a * a)).
          exact HIH.
        + assert (Hc : CReq R
            ((CRnorm_sq R' + mu * INR (length (j' :: T'') - 1) * S') + a * a)
            ((CRnorm_sq R' + a * a) + mu * INR (length (j' :: T'') - 1) * S')). { ring. }
          apply (proj2 Hc).
      - (* M2 ≤ M5 *)
        apply (CRle_trans (R:=R)
          ((CRnorm_sq R' + a * a) + mu * INR (length (j' :: T'') - 1) * S')
          ((CRnorm_sq (lst_combo (j :: j' :: T'') e u) + (1 + 1) * CRabs R a * (mu * L1'))
           + mu * INR (length (j' :: T'') - 1) * S')
          (CRnorm_sq (lst_combo (j :: j' :: T'') e u) + mu * INR (length (j' :: T'')) * (S' + a * a))).
        + (* M2 ≤ M3：H3 + Hcross2 合成 Htmp，再 CRplus_le_compat_r *)
          assert (Htmp : CRle R (CRnorm_sq R' + a * a)
               (CRnorm_sq (lst_combo (j :: j' :: T'') e u)
                + (1 + 1) * CRabs R a * (mu * L1'))).
          { apply (CRle_trans (R:=R) (CRnorm_sq R' + a * a)
              (CRnorm_sq (lst_combo (j :: j' :: T'') e u) + (1 + 1) * CRabs R a * CRabs R (CRip R' (u j)))
              (CRnorm_sq (lst_combo (j :: j' :: T'') e u) + (1 + 1) * CRabs R a * (mu * L1'))).
            - exact H3.
            - apply (CRplus_le_compat_l (R:=R) (CRnorm_sq (lst_combo (j :: j' :: T'') e u))).
              exact Hcross2. }
          apply (CRplus_le_compat_r (R:=R) (mu * INR (length (j' :: T'') - 1) * S')).
          exact Htmp.
        + (* M3 ≤ M5：H4 + ring 组装（INR(|T'|−1)+1 == INR(|T'|)，|T'| ≥ 1） *)
          apply (CRle_trans (R:=R)
            ((CRnorm_sq (lst_combo (j :: j' :: T'') e u) + (1 + 1) * CRabs R a * (mu * L1'))
             + mu * INR (length (j' :: T'') - 1) * S')
            ((CRnorm_sq (lst_combo (j :: j' :: T'') e u) + mu * (a * a * INR (length (j' :: T'')) + S'))
             + mu * INR (length (j' :: T'') - 1) * S')
            (CRnorm_sq (lst_combo (j :: j' :: T'') e u) + mu * INR (length (j' :: T'')) * (S' + a * a))).
          * (* M3 ≤ M4：Hring 换序 + H4 *)
            assert (Hring : CReq R ((1 + 1) * CRabs R a * (mu * L1'))
                                     (mu * ((1 + 1) * CRabs R a * lst_abs_sum (j' :: T'') e))).
            { unfold L1'. ring. }
            rewrite Hring.
            apply (CRplus_le_compat_r (R:=R) (mu * INR (length (j' :: T'') - 1) * S')).
            apply (CRplus_le_compat_l (R:=R) (CRnorm_sq (lst_combo (j :: j' :: T'') e u))).
            exact H4.
          * (* M4 == M5：INR 恒等（subSS/subn0 证 subn）+ ring *)
            assert (Hsub : subn (length (j' :: T'')) 1 = length T'').
            { cbn [length].
              rewrite (subSS 0 (length T'')).
              apply subn0. }
            assert (Hlen : S (subn (length (j' :: T'')) 1) = length (j' :: T'')).
            { rewrite Hsub. reflexivity. }
            assert (Hinr : CReq R (INR (length (j' :: T''))) (INR (length (j' :: T'') - 1) + 1)).
            { assert (Hmid : CReq R (INR (S (subn (length (j' :: T'')) 1))) (INR (length (j' :: T'')))).
              { rewrite Hlen. reflexivity. }
              apply (CReq_trans (R := R) (INR (length (j' :: T''))) (INR (S (subn (length (j' :: T'')) 1))) (INR (subn (length (j' :: T'')) 1) + 1)).
              - apply (CReq_sym (R := R) (INR (S (subn (length (j' :: T'')) 1))) (INR (length (j' :: T'')))).
                exact Hmid.
              - exact (CR_INR_S (subn (length (j' :: T'')) 1)). }
            assert (Hfin : CReq R
              ((CRnorm_sq (lst_combo (j :: j' :: T'') e u) + mu * (a * a * INR (length (j' :: T'')) + S'))
               + mu * INR (length (j' :: T'') - 1) * S')
              (CRnorm_sq (lst_combo (j :: j' :: T'') e u) + mu * INR (length (j' :: T'')) * (S' + a * a))).
            { rewrite Hinr. ring. }
            exact (proj2 Hfin).
Qed.

(* ============ F. 差分线性 + 分量线性 + 零项吸收 ============ *)

(* lst_combo 实部线性：re (Σ_T e_j u_j) == Σ_T e_j·re(u_j) *)
Lemma lst_combo_re_lin (T : list nat) (e : nat -> CRcarrier R) (u : nat -> CRComplex) :
  CReq R (cre (lst_combo T e u)) (lst_sum T (fun j => e j * cre (u j))).
Proof.
  induction T as [| j T' IH].
  - cbn [lst_combo lst_sum]. reflexivity.
  - cbn [lst_combo lst_sum]. unfold CRadd, scal. cbn [cre].
    split.
    + apply (CRplus_le_compat (R:=R)
        (lst_sum T' (fun j => e j * cre (u j))) (cre (lst_combo T' e u))
        (e j * cre (u j)) (e j * cre (u j))).
      * exact (proj1 IH).
      * apply CRle_refl.
    + apply (CRplus_le_compat (R:=R)
        (cre (lst_combo T' e u)) (lst_sum T' (fun j => e j * cre (u j)))
        (e j * cre (u j)) (e j * cre (u j))).
      * exact (proj2 IH).
      * apply CRle_refl.
Qed.

(* lst_combo 虚部线性 *)
Lemma lst_combo_im_lin (T : list nat) (e : nat -> CRcarrier R) (u : nat -> CRComplex) :
  CReq R (cim (lst_combo T e u)) (lst_sum T (fun j => e j * cim (u j))).
Proof.
  induction T as [| j T' IH].
  - cbn [lst_combo lst_sum]. reflexivity.
  - cbn [lst_combo lst_sum]. unfold CRadd, scal. cbn [cim].
    split.
    + apply (CRplus_le_compat (R:=R)
        (lst_sum T' (fun j => e j * cim (u j))) (cim (lst_combo T' e u))
        (e j * cim (u j)) (e j * cim (u j))).
      * exact (proj1 IH).
      * apply CRle_refl.
    + apply (CRplus_le_compat (R:=R)
        (cim (lst_combo T' e u)) (lst_sum T' (fun j => e j * cim (u j)))
        (e j * cim (u j)) (e j * cim (u j))).
      * exact (proj2 IH).
      * apply CRle_refl.
Qed.

(* lst_sum 对差的线性：Σ (f j − g j) == Σ f − Σ g *)
Lemma lst_sum_sub_morph (T : list nat) (f g : nat -> CRcarrier R) :
  CReq R (lst_sum T (fun j => f j - g j)) (lst_sum T f - lst_sum T g).
Proof.
  induction T as [| j T' IH].
  - cbn [lst_sum]. unfold CRminus. ring.
  - cbn [lst_sum].
    rewrite IH. unfold CRminus. ring.
Qed.

(* lst_sum 对 ++ 分配：Σ_{A++B} == Σ_A + Σ_B *)
Lemma lst_sum_cat (A B : list nat) (f : nat -> CRcarrier R) :
  CReq R (lst_sum (A ++ B) f) (lst_sum A f + lst_sum B f).
Proof.
  induction A as [| j A' IH].
  - cbn [lst_sum]. change ([] ++ B) with B. ring.
  - cbn [lst_sum]. change ((j :: A') ++ B) with (j :: (A' ++ B)).
    cbn [lst_sum]. rewrite IH. ring.
Qed.

(* 辅助：NoDup_cons 投影（inversion 版，避免 ssr destruct 索引问题） *)
Lemma NoDup_cons_inv (x : nat) (l : list nat) :
  NoDup (x :: l) -> ~ In x l /\ NoDup l.
Proof.
  intro H. inversion H. split; assumption.
Qed.

(* cat 版 In 引理（mathcomp cat ≠ stdlib app，in_app_iff 不匹配） *)
Lemma In_cat_l (a : nat) (l1 l2 : list nat) :
  In a l1 -> In a (l1 ++ l2).
Proof.
  induction l1 as [| j l1' IH]; intro Ha.
  - exfalso. exact Ha.
  - destruct Ha as [Haj | Ha'].
    + left. exact Haj.
    + right. exact (IH Ha').
Qed.

Lemma In_cat_r (a : nat) (l1 l2 : list nat) :
  In a l2 -> In a (l1 ++ l2).
Proof.
  induction l1 as [| j l1' IH]; intro Ha.
  - exact Ha.
  - right. exact (IH Ha).
Qed.

Lemma In_app_or_cat (a : nat) (l1 l2 : list nat) :
  In a (l1 ++ l2) -> In a l1 \/ In a l2.
Proof.
  induction l1 as [| j l1' IH]; intro Ha.
  - right. exact Ha.
  - destruct Ha as [Haj | Ha'].
    + left. left. exact Haj.
    + destruct (IH Ha') as [Hl | Hr].
      * left. right. exact Hl.
      * right. exact Hr.
Qed.

(* 辅助：NoDup (A ++ [j] ++ B) ⟹ NoDup (A ++ B)（删中间元素保持无重复） *)
Lemma NoDup_app_remove_mid (A B : list nat) (j : nat) :
  NoDup (A ++ [j] ++ B) -> NoDup (A ++ B).
Proof.
  induction A as [| a A' IH].
  - intro H.
    change ([j] ++ B) with (j :: B) in H.
    exact (proj2 (NoDup_cons_inv j B H)).
  - intro H.
    change ((a :: A') ++ [j] ++ B) with (a :: (A' ++ [j] ++ B)) in H.
    destruct (NoDup_cons_inv a (A' ++ [j] ++ B) H) as [Hnotin Hnodup].
    apply NoDup_cons.
    + intro Ha.
      apply Hnotin.
      destruct (In_app_or_cat a A' B Ha) as [Ha' | Ha''].
      * apply (In_cat_l a A' ([j] ++ B)). exact Ha'.
      * apply (In_cat_r a A' ([j] ++ B)).
        apply (In_cat_r a [j] B). exact Ha''.
    + exact (IH Hnodup).
Qed.

(* 辅助：NoDup (A ++ [j] ++ B) ⟹ ¬In j (A ++ B)（j 只在中间出现一次） *)
Lemma NoDup_mid_notin (A B : list nat) (j : nat) :
  NoDup (A ++ [j] ++ B) -> ~ In j (A ++ B).
Proof.
  induction A as [| a A' IH].
  - intro H.
    change ([j] ++ B) with (j :: B) in H.
    exact (proj1 (NoDup_cons_inv j B H)).
  - intro H.
    change ((a :: A') ++ [j] ++ B) with (a :: (A' ++ [j] ++ B)) in H.
    destruct (NoDup_cons_inv a (A' ++ [j] ++ B) H) as [Hnotin Hnodup].
    intro Hj.
    destruct (In_app_or_cat j (a :: A') B Hj) as [Hja | Hjb].
    + destruct Hja as [Hja' | Hja''].
      * subst a. apply Hnotin.
        apply (In_cat_r j A' ([j] ++ B)).
        apply (In_cat_l j [j] B).
        left. reflexivity.
      * exfalso. exact (IH Hnodup (In_cat_l j A' B Hja'')).
    + exfalso. exact (IH Hnodup (In_cat_r j A' B Hjb)).
Qed.

(* lst_sum 限制：T1 ⊆ T（NoDup）且 f 在 T\T1 为零 ⟹ Σ_T f == Σ_{T1} f *)
Lemma lst_sum_restrict (T T1 : list nat) (f : nat -> CRcarrier R) :
  NoDup T -> NoDup T1 ->
  (forall j, In j T1 -> In j T) ->
  (forall j, In j T -> ~ In j T1 -> CReq R (f j) (CR_of_Q R (Qmake 0 1))) ->
  CReq R (lst_sum T f) (lst_sum T1 f).
Proof.
  revert T1.
  induction T as [| j T' IH]; intros T1 HdupT HdupT1 Hincl Hzero.
  - (* T=[]：T1=[] *)
    destruct T1 as [| j0 T1'].
    + reflexivity.
    + exfalso. apply (Hincl j0 (or_introl Logic.eq_refl)).
  - (* T = j::T' *)
    destruct (NoDup_cons_inv j T' HdupT) as [Hnj HdupT'].
    destruct (List.In_dec Nat.eq_dec j T1) as [Hj1 | Hj1n].
    + (* j ∈ T1：In_split ⟹ T1 = l1 ++ [j] ++ l2 *)
      destruct (In_split j T1 Hj1) as [l1 [l2 HT1]].
      assert (Hnodup_mid : NoDup (l1 ++ [j] ++ l2)).
      { rewrite HT1 in HdupT1. exact HdupT1. }
      assert (Hnotin : ~ In j (l1 ++ l2)) by (exact (NoDup_mid_notin l1 l2 j Hnodup_mid)).
      (* IH 于 T' 与 l1++l2 *)
      assert (HIH' : CReq R (lst_sum T' f) (lst_sum (l1 ++ l2) f)).
      { apply IH.
        - exact HdupT'.
        - exact (NoDup_app_remove_mid l1 l2 j Hnodup_mid).
        - (* l1++l2 ⊆ T' *)
          intros k Hk.
          assert (Hk1 : In k T1).
          { rewrite HT1.
            destruct (In_app_or_cat k l1 l2 Hk) as [Hk_l1 | Hk_l2].
            - apply (In_cat_l k l1 ([j] ++ l2)). exact Hk_l1.
            - apply (In_cat_r k l1 ([j] ++ l2)).
              apply (In_cat_r k [j] l2). exact Hk_l2. }
          assert (Hkt : In k (j :: T')) by (apply Hincl; exact Hk1).
          destruct Hkt as [Hkj | Hkt'].
          + subst k. exfalso. exact (Hnotin Hk).
          + exact Hkt'.
        - (* f 在 T'\(l1++l2) 零 *)
          intros k Hk Hkn.
          apply Hzero; [right; exact Hk |].
          intro Hk1.
          rewrite HT1 in Hk1.
          destruct (In_app_or_cat k l1 ([j] ++ l2) Hk1) as [Hk_l1 | Hk_rest].
          + apply Hkn. apply (In_cat_l k l1 l2). exact Hk_l1.
          + destruct (In_app_or_cat k [j] l2 Hk_rest) as [Hk_j | Hk_l2].
            * destruct Hk_j as [Hkj | Hknil].
              -- subst k. exact (Hnj Hk).
              -- exfalso. exact Hknil.
            * apply Hkn. apply (In_cat_r k l1 l2). exact Hk_l2. }
      (* 组装：lst_sum (j::T') f == lst_sum T1 f *)
      assert (Htarget : CReq R (lst_sum (j :: T') f) (lst_sum T1 f)).
      { cbn [lst_sum].
        rewrite HT1.
        rewrite (lst_sum_cat l1 ([j] ++ l2) f).
        rewrite (lst_sum_cat [j] l2 f).
        cbn [lst_sum].
        rewrite HIH'.
        rewrite (lst_sum_cat l1 l2 f).
        ring. }
      exact Htarget.
    + (* j ∉ T1：f j == 0，删头部 *)
      cbn [lst_sum].
      assert (Hfj : CReq R (f j) (CR_of_Q R (Qmake 0 1))).
      { apply Hzero. left. reflexivity. exact Hj1n. }
      rewrite Hfj.
      assert (H0 : CReq R (lst_sum T' f + CR_of_Q R (Qmake 0 1)) (lst_sum T' f)). { ring. }
      apply (CReq_trans (R := R) (lst_sum T' f + CR_of_Q R (Qmake 0 1)) (lst_sum T' f) (lst_sum T1 f)).
      * exact H0.
      * apply IH.
        -- exact HdupT'.
        -- exact HdupT1.
        -- (* T1 ⊆ T' *)
           intros k Hk.
           assert (Hkt : In k (j :: T')) by (apply Hincl; exact Hk).
           destruct Hkt as [Hkj | Hkt'].
           ++ subst k. exfalso. exact (Hj1n Hk).
           ++ exact Hkt'.
        -- (* f 在 T'\T1 零 *)
           intros k Hk Hkn.
           apply Hzero; [right; exact Hk | exact Hkn].
Qed.

(* 辅助：非负逐项 ⟹ 每项 ≤ 和（列表版） *)
Lemma lst_sum_nonneg_term_le (T : list nat) (f : nat -> CRcarrier R) :
  (forall k, In k T -> CRle R (CR_of_Q R (Qmake 0 1)) (f k)) ->
  forall j, In j T -> CRle R (f j) (lst_sum T f).
Proof.
  induction T as [| k T' IH]; intros Hn j Hj.
  - exfalso. exact Hj.
  - cbn [lst_sum].
    destruct Hj as [Hjk | HjT'].
    + subst j.
      apply (CRle_trans (R:=R) (f k) (f k + lst_sum T' f) (lst_sum T' f + f k)).
      * apply (Rplus_le_pos (R:=R) (f k) (lst_sum T' f)).
        apply (lst_sum_nonneg T' f).
        intros j0 Hj0. apply Hn. right. exact Hj0.
      * assert (Hc : CReq R (f k + lst_sum T' f) (lst_sum T' f + f k)). { ring. }
        apply (proj2 Hc).
    + apply (CRle_trans (R:=R) (f j) (lst_sum T' f) (lst_sum T' f + f k)).
      * exact (IH (fun j0 Hj0 => Hn j0 (or_intror Hj0)) j HjT').
      * apply (Rplus_le_pos (R:=R) (lst_sum T' f) (f k)).
        apply Hn. left. reflexivity.
Qed.

(* 平方和零 ⟹ 逐项零（列表版） *)
Lemma lst_sqsum_zero_terms (T : list nat) (e : nat -> CRcarrier R)
  (Hsq : CReq R (lst_sqsum T e) (CR_of_Q R (Qmake 0 1))) :
  forall j, In j T -> CReq R (e j) (CR_of_Q R (Qmake 0 1)).
Proof.
  intros j Hj.
  assert (Hsum_le0 : CRle R (lst_sqsum T e) (CR_of_Q R (Qmake 0 1))).
  { exact (proj2 Hsq). }
  assert (Hj_le : CRle R (e j * e j) (lst_sqsum T e)).
  { unfold lst_sqsum.
    apply (lst_sum_nonneg_term_le T (fun k => e k * e k)).
    - intro k. intro Hk. exact (CRsqr_nonneg (e k)).
    - exact Hj. }
  assert (Hj_le0 : CRle R (e j * e j) (CR_of_Q R (Qmake 0 1))).
  { apply (CRle_trans (R:=R) (e j * e j) (lst_sqsum T e) (CR_of_Q R (Qmake 0 1))).
    - exact Hj_le.
    - exact Hsum_le0. }
  apply (CRsqr_eq_zero (e j)).
  split; [exact (CRsqr_nonneg (e j)) | exact Hj_le0].
Qed.

(* ============ G. undup 合并两支撑 ============ *)

(* 列表去重（保序） *)
Fixpoint list_undup (l : list nat) : list nat :=
  match l with
  | nil => nil
  | j :: t => if List.In_dec Nat.eq_dec j (list_undup t) then list_undup t else j :: list_undup t
  end.

Lemma list_undup_NoDup (l : list nat) :
  NoDup (list_undup l).
Proof.
  induction l as [| j t IH].
  - apply NoDup_nil.
  - cbn [list_undup].
    destruct (List.In_dec Nat.eq_dec j (list_undup t)) as [Hj | Hjn].
    + exact IH.
    + apply NoDup_cons. exact Hjn. exact IH.
Qed.

Lemma list_undup_In (l : list nat) (j : nat) :
  In j l -> In j (list_undup l).
Proof.
  induction l as [| k t IH]; intro Hj.
  - exfalso. exact Hj.
  - destruct Hj as [Hjk | Hjt].
    + subst k.
      change (list_undup (j :: t)) with
        (if List.In_dec Nat.eq_dec j (list_undup t) then list_undup t else j :: list_undup t).
      destruct (List.In_dec Nat.eq_dec j (list_undup t)) as [Hj' | Hjn'].
      * cbn [is_left]. exact Hj'.
      * cbn [is_left]. left. reflexivity.
    + change (list_undup (k :: t)) with
        (if List.In_dec Nat.eq_dec k (list_undup t) then list_undup t else k :: list_undup t).
      destruct (List.In_dec Nat.eq_dec k (list_undup t)) as [Hk' | Hkn'].
      * cbn [is_left]. exact (IH Hjt).
      * cbn [is_left]. right. exact (IH Hjt).
Qed.

Lemma list_undup_inv (l : list nat) (j : nat) :
  In j (list_undup l) -> In j l.
Proof.
  induction l as [| k t IH]; intro Hj.
  - exfalso. exact Hj.
  - change (list_undup (k :: t)) with
      (if List.In_dec Nat.eq_dec k (list_undup t) then list_undup t else k :: list_undup t) in Hj.
    destruct (List.In_dec Nat.eq_dec k (list_undup t)) as [Hk | Hkn].
    + cbn [is_left]. right. exact (IH Hj).
    + cbn [is_left]. destruct Hj as [Hjk | Hjt'].
      * left. exact Hjk.
      * right. exact (IH Hjt').
Qed.

Lemma list_undup_size_le (l : list nat) :
  leq (length (list_undup l)) (length l).
Proof.
  induction l as [| j t IH].
  - apply leqnn.
  - change (list_undup (j :: t)) with
      (if List.In_dec Nat.eq_dec j (list_undup t) then list_undup t else j :: list_undup t).
    destruct (List.In_dec Nat.eq_dec j (list_undup t)) as [Hj | Hjn].
    + cbn [is_left]. cbn [length].
      apply (leq_trans IH (leqnSn (length t))).
    + cbn [is_left]. cbn [length].
      rewrite (leq_add2l 1 (length (list_undup t)) (length t)).
      exact IH.
Qed.

Lemma length_cat (A B : list nat) :
  length (A ++ B) = (length A + length B)%N.
Proof.
  induction A as [| j A' IH].
  - change ([] ++ B) with B. cbn [length]. reflexivity.
  - change ((j :: A') ++ B) with (j :: (A' ++ B)).
    cbn [length].
    rewrite IH.
    reflexivity.
Qed.

(* ============ H. ★ 主定理：相干字典不确定原理（唯一性正形式） ============ *)

(* 若字典 {u_j}（单位范数、相干 ≤ μ）上同一信号 x 有两个稀疏表示
     x = Σ_{j∈T1} c_j·u_j == Σ_{j∈T2} d_j·u_j
   （c 在 T1 外为零、d 在 T2 外为零，T1/T2 无重复），且 μ·(|T1|+|T2|−1) < 1，
   则 ∀j: c_j == d_j（表示唯一——Donoho-Stark 不确定原理的构造性正形式）。 *)
Theorem CRuncertainty_principle (T1 T2 : list nat) (c d : nat -> CRcarrier R)
  (u : nat -> CRComplex) (mu : CRcarrier R)
  (Hmu0 : CRle R (CR_of_Q R (Qmake 0 1)) mu)
  (Hdup1 : NoDup T1) (Hdup2 : NoDup T2)
  (Hunit : forall j, In j T1 \/ In j T2 -> CReq R (CRnorm_sq (u j)) (CR_of_Q R (Qmake 1 1)))
  (Hcoh : forall i j, In i T1 \/ In i T2 -> In j T1 \/ In j T2 -> i <> j ->
    CRle R (CRabs R (CRip (u i) (u j))) mu)
  (Hrep : CReq_cplx (lst_combo T1 c u) (lst_combo T2 d u))
  (Hc0 : forall j, ~ In j T1 -> CReq R (c j) (CR_of_Q R (Qmake 0 1)))
  (Hd0 : forall j, ~ In j T2 -> CReq R (d j) (CR_of_Q R (Qmake 0 1)))
  (Hmu1 : CRlt R (mu * INR (length T1 + length T2 - 1)) (CR_of_Q R (Qmake 1 1))) :
  forall j, CReq R (c j) (d j).
Proof.
  (* T := undup(T1++T2)（覆盖两支撑） *)
  set (T := list_undup (T1 ++ T2)).
  assert (T_dup : NoDup T) by (unfold T; exact (list_undup_NoDup (T1 ++ T2))).
  assert (T_cov1 : forall j, In j T1 -> In j T).
  { intros j Hj. unfold T. apply (list_undup_In (T1 ++ T2) j). apply (In_cat_l j T1 T2). exact Hj. }
  assert (T_cov2 : forall j, In j T2 -> In j T).
  { intros j Hj. unfold T. apply (list_undup_In (T1 ++ T2) j). apply (In_cat_r j T1 T2). exact Hj. }
  assert (T_inv : forall j, In j T -> In j T1 \/ In j T2).
  { intros j Hj. unfold T in Hj.
    destruct (In_app_or_cat j T1 T2 (list_undup_inv (T1 ++ T2) j Hj)) as [Hj1 | Hj2].
    - left. exact Hj1.
    - right. exact Hj2. }
  assert (t_le : leq (length T) ((length T1 + length T2)%N)).
  { unfold T. apply (leq_trans (list_undup_size_le (T1 ++ T2))).
    rewrite (length_cat T1 T2). apply leqnn. }
  (* HunitT / HcohT 截取到 T *)
  assert (HunitT : forall j, In j T -> CReq R (CRnorm_sq (u j)) (CR_of_Q R (Qmake 1 1))).
  { intros j Hj. apply Hunit. exact (T_inv j Hj). }
  assert (HcohT : forall i j, In i T -> In j T -> i <> j ->
    CRle R (CRabs R (CRip (u i) (u j))) mu).
  { intros i j Hi Hj Hne. apply Hcoh.
    - exact (T_inv i Hi).
    - exact (T_inv j Hj).
    - exact Hne. }
  (* 分 t=0 / t≥1：Hmu1'（mu·INR(t−1) < 1） *)
  assert (Hmu1' : CRlt R (mu * INR (length T - 1)) (CR_of_Q R (Qmake 1 1))).
  { destruct (Nat.eq_dec (length T) 0) as [Ht0 | Htne].
    - (* t=0：mu·INR 0 == 0 < 1 *)
      rewrite Ht0. change (@INR R (0 - 1)) with (@INR R 0).
      rewrite INR0_eq.
      assert (Hz : CReq R (mu * CR_of_Q R (Qmake 0 1)) (CR_of_Q R (Qmake 0 1))). { ring. }
      rewrite Hz. exact (CRzero_lt_one R).
    - (* t ≥ 1：t−1 ≤ L−1 ⟹ INR ⟹ mu· ⟹ < 1 *)
      assert (Hsuble : leq ((length T - 1)%N) ((length T1 + length T2 - 1)%N)).
      { exact (@leq_sub (length T) ((length T1 + length T2)%N) 1 1 t_le (leqnn 1)). }
      apply (CRle_lt_trans (R:=R)
        (mu * INR (length T - 1))
        (mu * INR (length T1 + length T2 - 1))
        (CR_of_Q R (Qmake 1 1))).
      * apply (CRmult_le_compat_l (R:=R) mu
          (INR (length T - 1)) (INR (length T1 + length T2 - 1))).
        -- exact Hmu0.
        -- apply (CRle_INR ((length T - 1)%N) ((length T1 + length T2 - 1)%N)).
           apply/leP. exact Hsuble.
      * exact Hmu1. }
  (* 步骤 6：cre (lst_combo T (c−d) u) == 0 *)
  assert (Hzre : CReq R (cre (lst_combo T (fun j => c j - d j) u)) (CR_of_Q R (Qmake 0 1))).
  { rewrite (lst_combo_re_lin T (fun j => c j - d j) u).
    (* lst_sum T ((c−d)·re(u)) == lst_sum T (c·re(u)) − lst_sum T (d·re(u)) *)
    assert (Hsub : CReq R (lst_sum T (fun j => (c j - d j) * cre (u j)))
                           (lst_sum T (fun j => c j * cre (u j)) - lst_sum T (fun j => d j * cre (u j)))).
    { apply (CReq_trans (R := R)
        (lst_sum T (fun j => (c j - d j) * cre (u j)))
        (lst_sum T (fun j => c j * cre (u j) - d j * cre (u j)))
        (lst_sum T (fun j => c j * cre (u j)) - lst_sum T (fun j => d j * cre (u j)))).
      - apply lst_sum_morph. intro j. intro Hj. unfold CRminus. ring.
      - exact (lst_sum_sub_morph T (fun j => c j * cre (u j)) (fun j => d j * cre (u j))). }
    rewrite Hsub.
    (* restrict ×2：Σ_T c·re == Σ_{T1} c·re；Σ_T d·re == Σ_{T2} d·re *)
    assert (Hr1 : CReq R (lst_sum T (fun j => c j * cre (u j)))
                          (lst_sum T1 (fun j => c j * cre (u j)))).
    { apply (lst_sum_restrict T T1 (fun j => c j * cre (u j))).
      - exact T_dup.
      - exact Hdup1.
      - intros j Hj. apply T_cov1. exact Hj.
      - intros j Hj Hjn.
        rewrite (Hc0 j Hjn). ring. }
    assert (Hr2 : CReq R (lst_sum T (fun j => d j * cre (u j)))
                          (lst_sum T2 (fun j => d j * cre (u j)))).
    { apply (lst_sum_restrict T T2 (fun j => d j * cre (u j))).
      - exact T_dup.
      - exact Hdup2.
      - intros j Hj. apply T_cov2. exact Hj.
      - intros j Hj Hjn.
        rewrite (Hd0 j Hjn). ring. }
    rewrite Hr1 Hr2.
    (* Σ_{T1} c·re − Σ_{T2} d·re == 0：由 Hrep 实部 + re_lin *)
    assert (Hrep_re : CReq R (lst_sum T1 (fun j => c j * cre (u j)))
                              (lst_sum T2 (fun j => d j * cre (u j)))).
    { apply (CReq_trans (R := R)
        (lst_sum T1 (fun j => c j * cre (u j)))
        (cre (lst_combo T1 c u))
        (lst_sum T2 (fun j => d j * cre (u j)))).
      - apply (CReq_sym (R := R) (cre (lst_combo T1 c u)) (lst_sum T1 (fun j => c j * cre (u j)))).
        exact (lst_combo_re_lin T1 c u).
      - apply (CReq_trans (R := R)
          (cre (lst_combo T1 c u)) (cre (lst_combo T2 d u))
          (lst_sum T2 (fun j => d j * cre (u j)))).
        + exact (proj1 Hrep).
        + exact (lst_combo_re_lin T2 d u). }
    rewrite Hrep_re. unfold CRminus. ring. }
  (* 同 cim *)
  assert (Hzim : CReq R (cim (lst_combo T (fun j => c j - d j) u)) (CR_of_Q R (Qmake 0 1))).
  { rewrite (lst_combo_im_lin T (fun j => c j - d j) u).
    assert (Hsub : CReq R (lst_sum T (fun j => (c j - d j) * cim (u j)))
                           (lst_sum T (fun j => c j * cim (u j)) - lst_sum T (fun j => d j * cim (u j)))).
    { apply (CReq_trans (R := R)
        (lst_sum T (fun j => (c j - d j) * cim (u j)))
        (lst_sum T (fun j => c j * cim (u j) - d j * cim (u j)))
        (lst_sum T (fun j => c j * cim (u j)) - lst_sum T (fun j => d j * cim (u j)))).
      - apply lst_sum_morph. intro j. intro Hj. unfold CRminus. ring.
      - exact (lst_sum_sub_morph T (fun j => c j * cim (u j)) (fun j => d j * cim (u j))). }
    rewrite Hsub.
    assert (Hr1 : CReq R (lst_sum T (fun j => c j * cim (u j)))
                          (lst_sum T1 (fun j => c j * cim (u j)))).
    { apply (lst_sum_restrict T T1 (fun j => c j * cim (u j))).
      - exact T_dup.
      - exact Hdup1.
      - intros j Hj. apply T_cov1. exact Hj.
      - intros j Hj Hjn.
        rewrite (Hc0 j Hjn). ring. }
    assert (Hr2 : CReq R (lst_sum T (fun j => d j * cim (u j)))
                          (lst_sum T2 (fun j => d j * cim (u j)))).
    { apply (lst_sum_restrict T T2 (fun j => d j * cim (u j))).
      - exact T_dup.
      - exact Hdup2.
      - intros j Hj. apply T_cov2. exact Hj.
      - intros j Hj Hjn.
        rewrite (Hd0 j Hjn). ring. }
    rewrite Hr1 Hr2.
    assert (Hrep_im : CReq R (lst_sum T1 (fun j => c j * cim (u j)))
                              (lst_sum T2 (fun j => d j * cim (u j)))).
    { apply (CReq_trans (R := R)
        (lst_sum T1 (fun j => c j * cim (u j)))
        (cim (lst_combo T1 c u))
        (lst_sum T2 (fun j => d j * cim (u j)))).
      - apply (CReq_sym (R := R) (cim (lst_combo T1 c u)) (lst_sum T1 (fun j => c j * cim (u j)))).
        exact (lst_combo_im_lin T1 c u).
      - apply (CReq_trans (R := R)
          (cim (lst_combo T1 c u)) (cim (lst_combo T2 d u))
          (lst_sum T2 (fun j => d j * cim (u j)))).
        + exact (proj2 Hrep).
        + exact (lst_combo_im_lin T2 d u). }
    rewrite Hrep_im. unfold CRminus. ring. }
  (* 范数平方零 *)
  assert (Hnorm0 : CReq R (CRnorm_sq (lst_combo T (fun j => c j - d j) u)) (CR_of_Q R (Qmake 0 1))).
  { unfold CRnorm_sq.
    rewrite Hzre Hzim. ring. }
  (* lst_rip_lower + 范数零 ⟹ lst_sqsum ≤ mu(t−1)·lst_sqsum *)
  assert (Hrip := lst_rip_lower T (fun j => c j - d j) u mu T_dup Hmu0 HunitT HcohT).
  rewrite Hnorm0 in Hrip.
  assert (Hsq_le : CRle R (lst_sqsum T (fun j => c j - d j))
                          (mu * INR (length T - 1) * lst_sqsum T (fun j => c j - d j))).
  { apply (CRle_trans (R:=R) (lst_sqsum T (fun j => c j - d j))
      (CR_of_Q R (Qmake 0 1) + mu * INR (length T - 1) * lst_sqsum T (fun j => c j - d j))
      (mu * INR (length T - 1) * lst_sqsum T (fun j => c j - d j))).
    - exact Hrip.
    - assert (Hc : CReq R (CR_of_Q R (Qmake 0 1) + mu * INR (length T - 1) * lst_sqsum T (fun j => c j - d j))
                          (mu * INR (length T - 1) * lst_sqsum T (fun j => c j - d j))). { ring. }
      apply (proj2 Hc). }
  (* 收缩：lst_sqsum ≤ 0 ⟹ == 0 ⟹ 逐项零 *)
  assert (Hsq_le0 : CRle R (lst_sqsum T (fun j => c j - d j)) (CR_of_Q R (Qmake 0 1))).
  { apply (CRle_scaled_le_zero (lst_sqsum T (fun j => c j - d j)) (mu * INR (length T - 1))).
    - exact Hsq_le.
    - exact Hmu1'. }
  assert (Hsq0 : CReq R (lst_sqsum T (fun j => c j - d j)) (CR_of_Q R (Qmake 0 1))).
  { split.
    - exact (lst_sqsum_nonneg T (fun j => c j - d j)).
    - exact Hsq_le0. }
  (* 结论：∀j *)
  intro j.
  destruct (List.In_dec Nat.eq_dec j T) as [HjT | HjnT].
  - (* j ∈ T：e j == 0 ⟹ c j == d j *)
    assert (Hej : CReq R (c j - d j) (CR_of_Q R (Qmake 0 1))).
    { exact (lst_sqsum_zero_terms T (fun j => c j - d j) Hsq0 j HjT). }
    apply (CReq_trans (R := R) (c j) ((c j - d j) + d j) (d j)).
    + unfold CRminus. ring.
    + rewrite Hej. unfold CRminus. ring.
  - (* j ∉ T：j∉T1 且 j∉T2 ⟹ c j == 0 == d j *)
    assert (Hj1n : ~ In j T1).
    { intro Hj1. apply HjnT. apply T_cov1. exact Hj1. }
    assert (Hj2n : ~ In j T2).
    { intro Hj2. apply HjnT. apply T_cov2. exact Hj2. }
    apply (CReq_trans (R := R) (c j) (CR_of_Q R (Qmake 0 1)) (d j)).
    + exact (Hc0 j Hj1n).
    + apply (CReq_sym (R := R) (d j) (CR_of_Q R (Qmake 0 1))).
      exact (Hd0 j Hj2n).
Qed.

End F5Uncertainty.

(* ==================== 模块 47/67: probe_g8_synthesis_cr ==================== *)

Close Scope R_scope.
Close Scope Z_scope.
(* ============================================================
   纪律：纯构造性——Stdlib ConstructiveReals（Set 层 CRcarrier + Prop 层
             CReq/CRle/CRlt），零经典实数（不用 Stdlib.Reals.Reals）、
             零 Admitted、零自定义公理。

   数学内容（压缩感知三角闭环的合成定理）：
     若字典相干 μ 同时满足
       (G-7 Welch 下界，平方形态)  (INR M - INR N) ≤ INR N · INR(M-1) · μ²
       (F5 唯一性窗口)             μ · INR(|T1|+|T2|−1) < 1
     则同一信号的两个 |T|-稀疏表示必相同（唯一恢复保证）。
     —— Welch 界给出"字典设计的最优性"（相干不可能低于下界），
        F5 给出"恢复保证"（相干足够小时表示唯一），
        合成 = 相图定理：μ 落在 [Welch, 1/|T|) 才有唯一恢复。

   证明链（本探针，纯 CR，复用 F5/R4 战术）：
     R0. CR 算术辅助：0 ≤ z < 1 ⟹ z·z < 1（CRsqr_lt_one，构造性）；
         0 ≤ a ≤ b、0 ≤ c ≤ d ⟹ ac ≤ bd（CRmult_le_compat_4）。
     R1. ★ CRphase_window_nonempty（相图窗口非空）：
           Welch 下界 + F5 窗口 ⟹ (INR M − INR N)·(INR T)² < INR N·INR(M−1)
           ——"Welch < 1/|T| 时唯一性窗口非空"的定量参数条件
           （路线：0 ≤ μT ∧ μT<1 ⟹ (μT)²<1 [CRsqr_lt_one]；
             Welch 两边乘 T²；N(M−1)·(μT)² < N(M−1) [乘 0≤N(M−1)]；
             CRle_lt_trans 组装）
     R2. ★ CRg8_recovery_synthesis（主合成定理）：
           Welch 下界（抽象前提）+ F5 全部前提 ⟹ 唯一恢复
           （直接实例化 F5 CRuncertainty_principle——相图区间
             [Welch, 1/|T|) 上的恢复保证；Welch 前提经
             CRphase_window_nonempty 给出窗口非空叙事）

   依赖： ca_rip_cr（CRip/CRnorm_sq/CRcombo/CRabs）+ probe_uncertainty_cr（F5）。
   结构：Section G8Synthesis + Add Ring（与 ca_rip_cr / F5 / R4 一致）。
   审计：零 Admitted / 零自定义公理；Print Assumptions 尾部应仅
         ConstructiveReals 接口（零经典）。
   ============================================================ *)
Require Import ConstructiveReals.
From Stdlib Require Import ConstructiveRealsMorphisms.
From Stdlib Require Import ConstructiveAbs.
From Stdlib Require Import ConstructiveSum.
Require Import Stdlib.QArith.QArith.
Require Import Stdlib.ZArith.ZArith.
Require Import Stdlib.micromega.Lia.
From Stdlib Require Import List.
Import ListNotations.
From mathcomp Require Import ssreflect ssrbool ssrnat seq eqtype div prime.

Local Open Scope ConstructiveReals.
(* le/lt 用 Coq 原生函数（mathcomp 不劫持这两个标识符），lia 可处理。 *)

Section G8Synthesis.

Context {R : ConstructiveReals}.
Add Ring CR_ring : (CRisRing R).

(* ============ R0. CR 算术辅助 ============ *)

(* 0 ≤ z < 1 ⟹ z·z < 1（CR 层平方收缩，构造性） *)
Lemma CRsqr_lt_one (z : CRcarrier R) :
  CRle R (CR_of_Q R (Qmake 0 1)) z ->
  CRlt R z (CR_of_Q R (Qmake 1 1)) ->
  CRlt R (z * z) (CR_of_Q R (Qmake 1 1)).
Proof.
  intros Hz0 Hz1.
  (* z·z ≤ z·1 == z（0 ≤ z 且 z ≤ 1，乘非负） *)
  assert (Hzz : CRle R (z * z) (z * CR_of_Q R (Qmake 1 1))).
  { apply (CRmult_le_compat_l (R:=R) z z (CR_of_Q R (Qmake 1 1))).
    - exact Hz0.
    - exact (CRlt_asym (R:=R) z (CR_of_Q R (Qmake 1 1)) Hz1). }
  assert (Hzone : CReq R (z * CR_of_Q R (Qmake 1 1)) z). { ring. }
  apply (CRle_lt_trans (R:=R) (z * z) z (CR_of_Q R (Qmake 1 1))).
  - apply (CRle_trans (R:=R) (z * z) (z * CR_of_Q R (Qmake 1 1)) z).
    + exact Hzz.
    + apply (proj2 Hzone).
  - exact Hz1.
Qed.

(* 0 ≤ a ≤ b、0 ≤ c ≤ d ⟹ a·c ≤ b·d（CR 层复合单调） *)
Lemma CRmult_le_compat_4 (a b c d : CRcarrier R) :
  CRle R (CR_of_Q R (Qmake 0 1)) a -> CRle R a b ->
  CRle R (CR_of_Q R (Qmake 0 1)) c -> CRle R c d ->
  CRle R (a * c) (b * d).
Proof.
  intros Ha0 Hab Hc0 Hcd.
  apply (CRle_trans (R:=R) (a * c) (b * c) (b * d)).
  - apply (CRmult_le_compat_r (R:=R) c a b).
    + exact Hc0.
    + exact Hab.
  - apply (CRmult_le_compat_l (R:=R) b c d).
    + apply (CRle_trans (R:=R) (CR_of_Q R (Qmake 0 1)) a b).
      * exact Ha0.
      * exact Hab.
    + exact Hcd.
Qed.

(* 1 ≤ n ⟹ 0 < INR n（严格正） *)
Lemma CR0_lt_INR_pos (n : nat) :
  le 1 n -> CRlt R (CR_of_Q R (Qmake 0 1)) (INR n).
Proof.
  intros Hn1.
  apply (CRlt_le_trans (R:=R) (CR_of_Q R (Qmake 0 1)) (INR 1) (INR n)).
  - change (INR 1) with (CR_of_Q R (Qmake 1 1)).
    exact (CRzero_lt_one R).
  - apply (CRle_INR 1 n). exact Hn1.
Qed.

(* INR (Nat.pred M) 非负（M ≥ 2 由 N ≥ 1 且 N < M 推出） *)
Lemma CR_INR_pred_nonneg (M N : nat) :
  le 1 N -> lt N M ->
  CRle R (CR_of_Q R (Qmake 0 1)) (INR (Nat.pred M)).
Proof.
  intros HN1 HNM.
  assert (HM1 : le 1 (Nat.pred M)) by lia.
  apply (CRle_trans (R:=R) (CR_of_Q R (Qmake 0 1)) (INR 1) (INR (Nat.pred M))).
  - exact (CR0_le_INR 1).
  - apply (CRle_INR 1 (Nat.pred M)). exact HM1.
Qed.

(* ============ R1. ★ 相图窗口非空 ============ *)

(* 若字典相干 μ 满足 Welch 下界（平方形态）且落在 F5 唯一性窗口内，
   则窗口非空的参数条件成立：(M−N)·T² < N·(M−1)。
   （T := |T1|+|T2|−1 抽象为 nat 参数；welch 下界为 G-7 的抽象前提。） *)
Theorem CRphase_window_nonempty (M N T : nat) (mu : CRcarrier R) :
  le 1 N -> lt N M -> le 1 T ->
  CRle R (CR_of_Q R (Qmake 0 1)) mu ->
  (* G-7 Welch 下界（平方形态，抽象前提） *)
  CRle R (INR M - INR N) (INR N * INR (Nat.pred M) * mu * mu) ->
  (* F5 唯一性窗口：μ·T < 1 *)
  CRlt R (mu * INR T) (CR_of_Q R (Qmake 1 1)) ->
  (* 相图窗口非空（定量参数条件） *)
  CRlt R ((INR M - INR N) * (INR T * INR T))
         (INR N * INR (Nat.pred M)).
Proof.
  intros HN1 HNM HT1 Hmu0 Hwelch Hwin.
  (* ① (μ·T)² < 1：由 0 ≤ μ·T 与 μ·T < 1 平方收缩 *)
  assert (HmuT0 : CRle R (CR_of_Q R (Qmake 0 1)) (mu * INR T)).
  { apply (CRmult_le_0_compat (R:=R) mu (INR T)); [exact Hmu0 | exact (CR0_le_INR T)]. }
  assert (HmuT1 : CRlt R ((mu * INR T) * (mu * INR T)) (CR_of_Q R (Qmake 1 1))).
  { exact (CRsqr_lt_one (mu * INR T) HmuT0 Hwin). }
  (* ② Welch 下界两边乘 (INR T)²（非负） *)
  assert (HT20 : CRle R (CR_of_Q R (Qmake 0 1)) (INR T * INR T)).
  { apply (CRmult_le_0_compat (R:=R) (INR T) (INR T));
      exact (CR0_le_INR T). }
  assert (HwelchT : CRle R ((INR M - INR N) * (INR T * INR T))
                            ((INR N * INR (Nat.pred M) * mu * mu) * (INR T * INR T))).
  { apply (CRmult_le_compat_r (R:=R) (INR T * INR T)
      (INR M - INR N) (INR N * INR (Nat.pred M) * mu * mu)).
    - exact HT20.
    - exact Hwelch. }
  (* ③ 右侧整理：(N(M−1)·μ²)·T² == N(M−1)·(μT)² *)
  assert (Hre : CReq R
    ((INR N * INR (Nat.pred M) * mu * mu) * (INR T * INR T))
    (INR N * INR (Nat.pred M) * ((mu * INR T) * (mu * INR T)))).
  { ring. }
  assert (HwelchT' : CRle R ((INR M - INR N) * (INR T * INR T))
                            (INR N * INR (Nat.pred M) * ((mu * INR T) * (mu * INR T)))).
  { apply (CRle_trans (R:=R)
      ((INR M - INR N) * (INR T * INR T))
      ((INR N * INR (Nat.pred M) * mu * mu) * (INR T * INR T))
      (INR N * INR (Nat.pred M) * ((mu * INR T) * (mu * INR T)))).
    - exact HwelchT.
    - apply (proj2 Hre). }
  (* ④ 右侧上界：N(M−1)·(μT)² < N(M−1)·1，且 N(M−1)·1 == N(M−1) *)
  assert (HN0 : CRle R (CR_of_Q R (Qmake 0 1)) (INR N * INR (Nat.pred M))).
  { apply (CRmult_le_0_compat (R:=R) (INR N) (INR (Nat.pred M)));
      [exact (CR0_le_INR N) | exact (CR_INR_pred_nonneg M N HN1 HNM)]. }
  assert (HNpos : CRlt R (CR_of_Q R (Qmake 0 1)) (INR N * INR (Nat.pred M))).
  { apply (CRmult_lt_0_compat R (INR N) (INR (Nat.pred M))).
    - exact (CR0_lt_INR_pos N HN1).
    - assert (HM1 : le 1 (Nat.pred M)) by lia.
      exact (CR0_lt_INR_pos (Nat.pred M) HM1). }
  assert (Hright : CRlt R (INR N * INR (Nat.pred M) * ((mu * INR T) * (mu * INR T)))
                           (INR N * INR (Nat.pred M) * CR_of_Q R (Qmake 1 1))).
  { apply (CRmult_lt_compat_l (R:=R) (INR N * INR (Nat.pred M))
      ((mu * INR T) * (mu * INR T)) (CR_of_Q R (Qmake 1 1))).
    - exact HNpos.
    - exact HmuT1. }
  (* ⑤ 组装：LHS ≤ N(M−1)(μT)² < N(M−1)·1 == N(M−1) *)
  assert (Hone : CReq R
    (INR N * INR (Nat.pred M) * CR_of_Q R (Qmake 1 1))
    (INR N * INR (Nat.pred M))). { ring. }
  apply (CRle_lt_trans (R:=R)
    ((INR M - INR N) * (INR T * INR T))
    (INR N * INR (Nat.pred M) * ((mu * INR T) * (mu * INR T)))
    (INR N * INR (Nat.pred M))).
  - exact HwelchT'.
  - rewrite Hone in Hright. exact Hright.
Qed.

(* ============ R2. ★ 主合成定理：字典最优性 ⟹ 恢复保证 ============ *)

(* 若字典相干 μ 满足 Welch 下界（抽象前提，G-7 提供）且落在 F5 唯一性窗口内，
   则同一信号的两个 |T|-稀疏表示必相同。
   合成 = F5 CRuncertainty_principle 在相图区间 [Welch, 1/|T|) 上的实例化：
   Welch 前提给出"字典设计的最优性"叙事（经 R1 窗口非空），
   F5 窗口给出"恢复保证"（μ < 1/(|T1|+|T2|−1) ⟹ 表示唯一）。 *)
Theorem CRg8_recovery_synthesis (M N : nat) (T1 T2 : list nat)
  (c d : nat -> CRcarrier R) (u : nat -> CRComplex) (mu : CRcarrier R)
  (HN1 : le 1 N) (HNM : lt N M)
  (Hmu0 : CRle R (CR_of_Q R (Qmake 0 1)) mu)
  (* G-7 Welch 下界（平方形态，抽象前提） *)
  (Hwelch : CRle R (INR M - INR N) (INR N * INR (Nat.pred M) * mu * mu))
  (Hdup1 : NoDup T1) (Hdup2 : NoDup T2)
  (Hunit : forall j, In j T1 \/ In j T2 ->
    CReq R (CRnorm_sq (u j)) (CR_of_Q R (Qmake 1 1)))
  (Hcoh : forall i j, In i T1 \/ In i T2 -> In j T1 \/ In j T2 -> i <> j ->
    CRle R (CRabs R (CRip (u i) (u j))) mu)
  (Hrep : CReq_cplx (lst_combo T1 c u) (lst_combo T2 d u))
  (Hc0 : forall j, ~ In j T1 -> CReq R (c j) (CR_of_Q R (Qmake 0 1)))
  (Hd0 : forall j, ~ In j T2 -> CReq R (d j) (CR_of_Q R (Qmake 0 1)))
  (* F5 唯一性窗口：μ·(|T1|+|T2|−1) < 1 *)
  (Hwin : CRlt R (mu * INR (length T1 + length T2 - 1)) (CR_of_Q R (Qmake 1 1))) :
  forall j, CReq R (c j) (d j).
Proof.
  (* 直接实例化 F5 主定理（相图区间 [Welch, 1/|T|) 上的唯一恢复） *)
  apply (CRuncertainty_principle T1 T2 c d u mu Hmu0 Hdup1 Hdup2 Hunit Hcoh
                                 Hrep Hc0 Hd0 Hwin).
Qed.

End G8Synthesis.


(* ==================== 模块 48/67: probe_g1_norm_closed ==================== *)

Close Scope Z_scope.
Open Scope R_scope.
Open Scope complex_scope.
Open Scope nat_scope.
(* ============================================================
   用户红线：零 Admitted、零自定义公理；经典 R/C 轨道（与 probe_pairbound/
             probe_incoherence 同轨——G-1 依赖 Cexp/sin 复分析基础设施，
             CR 构造性轨道无 exp/sin，按文档定位走经典轨道）。
   数学内容（加权阶梯范数精确闭式，评估 T*-2 定理化）：
     对混窗阶梯 F = Σ_{j≤M} c_j·ψ_{n_j}（ψ_n = 窗口化复指数，单位范数）：
       ‖F‖²_W = Σ_{j≤M} c_j²·‖ψ_{n_j}‖²_W + 2·Σ_{i<j≤M} c_i·c_j·K_W(n_i,n_j)
     其中 K_W(a,b) = ⟨ψ_a,ψ_b⟩_W 为**显式 Dirichlet 核比闭式**（单对公式的
     窗口求和版）——即 Gram 交叉项的精确解析形式。
   证明路线：
     R0. 求和/复工具（sum_f_R0 split/swap、Csum re 桥、rot_atom 几何和）
     R1. ★ 单对精确内积：ipW (psi a) (psi b) W 的显式闭式
          ——psi 定义展开 → rot_atom 几何和 → re 提取（Dirichlet 实部）
     R2. ★ Gram 完全展开：‖comboM M c u‖²_W
          = Σ_{j≤M} c_j²·‖u_j‖²_W + 2·Σ_{i<j≤M} c_i·c_j·⟨u_i,u_j⟩_W
          （norm_sq_comboM_rec 归纳 + ipW_combo_l 双和组装）
     R3. ★ G1_norm_closed（主定理）：u_j := psi (n_j) 实例化 R2，
          交叉项用 R1 闭式替换 ⟹ 加权阶梯范数精确等式
   依赖： probe_incoherence（comboM/ipW/norm_sq_comboM_rec/ipW_combo_l）、
          probe_partial（rot_atom/geom_sum_identity）、
          ca_basis（psi）、probe_parseval（re_mul_conj）。
   审计：零 Admitted / 零自定义公理（同 probe_pairbound 脚印）。
   ============================================================ *)
From mathcomp Require Import ssreflect ssrbool ssrnat seq eqtype div prime.
Require Import Stdlib.Reals.Reals.
Require Import Stdlib.Arith.Arith.
Require Import Stdlib.micromega.Lia.
Require Import Stdlib.micromega.Lra.
Require Import Stdlib.ZArith.ZArith.
Require Import Stdlib.Logic.FunctionalExtensionality.
Import ComplexNumbers.
Import FourierAnalysis.
Import GridOrtho.
Import TPartial.
Import Incoherence.
Import Incoherence2.
Open Scope R_scope.
(* Open Scope complex_scope 已移除：scope 劫持 nat * 与 +（G-1 全 R 注解） *)
(* 所有 nat 运算用显式函数/括号标注 *)
Module G1NormClosed.
(* ============ R0. 求和工具（本地，防重名） ============ *)
(* 有限和递归公式（本地自证，probe_incoherence 未暴露顶层版） *)
Lemma g1_sum_S : forall (f : nat -> R) (n : nat),
  sum_f_R0 f (S n) = (sum_f_R0 f n + f (S n))%R.
Proof. intros. simpl. reflexivity. Qed.
(* 逐点相等 ⟹ 和相等（本地归纳版） *)
Lemma g1_sum_ext : forall (f g : nat -> R) (n : nat),
  (forall k, Nat.le k n -> f k = g k) ->
  sum_f_R0 f n = sum_f_R0 g n.
Proof.
  intros f g n H.
  induction n as [| n IH].
  - simpl. apply H. lia.
  - rewrite (g1_sum_S f n). rewrite (g1_sum_S g n).
    assert (Hih : forall k : nat, le k n -> f k = g k) by (intros k Hk; apply H; lia).
    rewrite (IH Hih).
    rewrite (H (S n) (Nat.le_refl (S n))). reflexivity.
Qed.
(* 常数提取：Σ (c·f k) = c·Σ f（本地） *)
Lemma g1_sum_scal : forall (c : R) (f : nat -> R) (n : nat),
  sum_f_R0 (fun k => (c * f k)%R) n = (c * sum_f_R0 f n)%R.
Proof.
  intros c f n.
  induction n as [| n IH].
  - simpl. ring.
  - rewrite (g1_sum_S (fun k => (c * f k)%R) n).
    rewrite (g1_sum_S f n). rewrite IH. ring.
Qed.
(* 常零和 = 0（本地） *)
Lemma g1_sum_zero : forall (n : nat),
  sum_f_R0 (fun _ : nat => 0%R) n = 0%R.
Proof.
  intros n. induction n as [| n IH].
  - reflexivity.
  - rewrite (g1_sum_S (fun _ => 0%R) n). rewrite IH. ring.
Qed.
(* Cof_real r *c z 的范数平方 = r²·‖z‖²（复用 Incoherence2.Cnorm_sq_scal） *)
Lemma g1_norm_Cof_mul (r : R) (z : Complex) :
  Cnorm_sq (Cof_real r *c z) = (r * r * Cnorm_sq z)%R.
Proof. exact (Cnorm_sq_scal r z). Qed.
(* 交叉双和（索引平移编码，外层 j'=S j 从 1 到 SM，i<j'，无伪项）。
   拆分：Σ_{j≤predn(SM)} = Σ_{j≤predn M} + 尾层 j'=SM（i=0..SM）。
   M≥1 前提（M=0 时 predn 1 = 0 给伪项 f 0 1，组合无原子 1） *)
Lemma g1_cross_S (M : nat) (f : nat -> nat -> R) :
  le 1 M ->
  (sum_f_R0 (fun j => sum_f_R0 (fun i => f i (S j)) j) (predn (S M)))%R
  = ((sum_f_R0 (fun j => sum_f_R0 (fun i => f i (S j)) j) (predn M))%R
     + (sum_f_R0 (fun i => f i (S M)) (predn (S M)))%R).
Proof.
  intros HM.
  destruct M as [| M'].
  - exfalso. lia.
  - rewrite (g1_sum_S (fun j => sum_f_R0 (fun i => f i (S j)) j) M').
    replace (predn (S (S M'))) with (S M') by lia.
    reflexivity.
Qed.
(* 对角尾部拆分：Σ_{j≤SM} c_j²·g_j = Σ_{j≤M} c_j²·g_j + c_{SM}²·g_{SM} *)
Lemma g1_diag_S (M : nat) (c : nat -> R) (g : nat -> R) :
  (sum_f_R0 (fun j => (c j * c j * g j)%R) (S M))%R
  = ((sum_f_R0 (fun j => (c j * c j * g j)%R) M)%R
     + (c (S M) * c (S M) * g (S M))%R)%R.
Proof. exact (g1_sum_S (fun j => (c j * c j * g j)%R) M). Qed.
(* 内层和展开：Σ_{i<SM} c_i·c_{SM}·⟨u_i,u_{SM}⟩ = Σ_{i≤M} ...（predn (S M) = M） *)
Lemma g1_cross_tail (M : nat) (c : nat -> R) (u : nat -> nat -> Complex) (W : nat) :
  (sum_f_R0 (fun i => (c i * c (S M) * ipW (u i) (u (S M)) W)%R) (predn (S M)))%R
  = (sum_f_R0 (fun i => (c i * c (S M) * ipW (u i) (u (S M)) W)%R) M)%R.
Proof.
  replace (predn (S M)) with M by lia. reflexivity.
Qed.
(* 双和交换：Σ_j c_j·Σ_i a_i·b_j·⟨u_i,u_j⟩ 换序（同索引聚合辅助，供组装） *)
Lemma g1_ipW_combo_l_cross (M : nat) (c : nat -> R) (u : nat -> nat -> Complex) (v : nat -> Complex) (W : nat) :
  (ipW (comboM (S M) c u) v W)%R
  = (sum_f_R0 (fun j => c j * ipW (u j) v W) M)%R.
Proof. exact (ipW_combo_l M c u v W). Qed.
(* ============ R1. 单对精确内积（ψ 闭式） ============ *)
(* k ≥ a 时 psi a k = C0（支撑外为零） *)
Lemma g1_psi_zero (a k : nat) :
  (a <= k)%nat -> psi a k = C0.
Proof.
  intros Hak.
  unfold psi.
  assert (Hkge : Nat.le a k) by (apply/leP; exact Hak).
  rewrite (phi_ge_n_zero a k Hkge).
  rewrite Cmul_0_r.
  reflexivity.
Qed.
(* k ≥ a 时 psi a k·conj(psi b k) = C0（支撑外乘积为零） *)
Lemma g1_psi_conj_zero (a b k : nat) :
  (a <= k)%nat -> (psi a k *c Cconj (psi b k))%C = C0.
Proof.
  intros Hak.
  rewrite (g1_psi_zero a k Hak).
  rewrite Cmul_0_l.
  reflexivity.
Qed.
(* k ≥ min(min a b)(S W) 且 k ≤ W ⟹ k ≥ min a b
   （若 k < min a b 则 m = S W ⟹ S W ≤ k 与 k ≤ W 矛盾） *)
Lemma g1_min_ge (a b W k : nat) :
  le (Nat.min (Nat.min a b) (S W)) k -> le k W ->
  le (Nat.min a b) k.
Proof.
  intros Hmk HkW.
  destruct (Nat.min_spec (Nat.min a b) (S W)) as [[Hlt Hmn] | [Hle Hmn]].
  - (* min a b < S W：min(min a b)(S W) = min a b *)
    rewrite Hmn in Hmk. exact Hmk.
  - (* S W ≤ min a b：min(min a b)(S W) = S W ⟹ S W ≤ k 与 k ≤ W 矛盾 *)
    rewrite Hmn in Hmk.
    exfalso. lia.
Qed.
(* Σ 截断：f 在 [m, W] 上为零 ⟹ Σ_{k≤W} f k = Σ_{k<predn m} f k（m ≤ S W）
   注意 Hz 只要求 m ≤ k ≤ W 范围内的 f k = 0（k > W 不在和中） *)
Lemma g1_sum_trunc (f : nat -> R) (W m : nat) :
  le m (S W) ->
  (forall k, le m k -> le k W -> f k = 0%R) ->
  (sum_f_R0 f W)%R = (sum_f_R0 f (predn m))%R.
Proof.
  intros HmW Hz.
  induction W as [| W IH].
  - (* W=0：sum_f_R0 f 0 = f 0；predn m 分 m=0/m=1（m ≤ 1） *)
    destruct m as [| m'].
    + simpl. reflexivity.
    + assert (Hm'0 : m' = 0%nat) by lia. subst. simpl. reflexivity.
  - (* W = S W'：m ≤ S(S W') *)
    destruct (Nat.leb m (S W)) as [] eqn: Hle.
    + (* m ≤ S W：sum_f_R0 f (S W) = sum_f_R0 f W + f (S W)，
         f (S W) = 0（Hz：le m (S W) 且 le (S W) (S W)）⟹ = sum_f_R0 f W = IH *)
      apply Nat.leb_le in Hle.
      rewrite (g1_sum_S f W).
      assert (Htail : f (S W) = 0%R).
      { apply Hz; lia. }
      rewrite Htail.
      assert (Hih' : forall k : nat, le m k -> le k W -> f k = 0%R) by (intros k Hk1 Hk2; apply Hz; [exact Hk1 | lia]).
      rewrite (IH Hle Hih').
      ring.
    + (* m > S W：但 m ≤ S(S W) ⟹ m = S(S W) ⟹ predn m = S W = S W' *)
      assert (Hgt : (S W < m)%coq_nat) by (apply (proj1 (Nat.leb_gt m (S W))); exact Hle).
      assert (Hm : m = S (S W)) by lia.
      rewrite (g1_sum_S f W).
      rewrite Hm. simpl. ring.
Qed.
(* Cconj 对纯虚指数：Cconj (Cexp (0+iθ)) = Cexp (0+i(−θ)) *)
(* le k (predn m) 且 1 ≤ m ⟹ k < m（nat 桥，lia + succ_pred） *)
Lemma g1_lt_pred (k m : nat) :
  le 1 m -> le k (Nat.pred m) -> lt k m.
Proof.
  intros Hm1 Hkm.
  destruct m as [| m'].
  - exfalso. lia.
  - simpl in Hkm. lia.
Qed.
Lemma g1_Cconj_Cof_real (r : R) :
  Cconj (Cof_real r) = Cof_real r.
Proof.
  unfold Cof_real, Cconj. simpl. apply Complex_eq; simpl; ring.
Qed.
(* Cconj 对纯虚指数：Cconj (Cexp (0+itheta)) = Cexp (0+i(−theta)) *)
Lemma g1_Cconj_exp (theta : R) :
  Cconj (Cexp (0 +i theta)) = Cexp (0 +i (- theta)).
Proof.
  unfold Cexp, Cconj. simpl.
  apply Complex_eq; simpl.
  - rewrite cos_neg. ring.
  - rewrite sin_neg. ring.
Qed.
(* 纯虚指数乘法：Cexp(0+itheta1)·Cexp(0+itheta2) = Cexp(0+i(theta1+theta2)) *)
Lemma g1_Cexp_mul_i (theta1 theta2 : R) :
  Cexp (0 +i theta1) *c Cexp (0 +i theta2) = Cexp (0 +i (theta1 + theta2)).
Proof.
  rewrite <- Cexp_add.
  f_equal.
  unfold Cadd.
  simpl.
  f_equal; ring.
Qed.
(* ψ_a 与 ψ_b 的单点积：psi a k *c Cconj (psi b k) = (1/√(ab))·rot_atom theta k，
   theta = 2π(b−a)/(ab)（k < min(a,b) 时） *)
Lemma g1_psi_point (a b k : nat) :
  (k < a)%nat -> (k < b)%nat ->
  (psi a k *c Cconj (psi b k))%C
  = (Cof_real ((1 / sqrt (INR a))%R * (1 / sqrt (INR b))%R)
     *c rot_atom ((2 * PI * (INR b - INR a)) / (INR a * INR b))%R k)%C.
Proof.
  intros Hka Hkb.
  (* 展开 psi 与 phi（k<a, k<b 时 phi = Cexp） *)
  unfold UnconditionalBasis.psi.
  rewrite Cconj_mul.
  rewrite (g1_Cconj_Cof_real (1 / sqrt (INR b))).
  (* UnconditionalBasis.phi a k = Cexp(0+i·2πk/a)，UnconditionalBasis.phi b k = Cexp(0+i·2πk/b) *)
  assert (Hphia : UnconditionalBasis.phi a k = Cexp (0 +i (2 * PI * INR k / INR a))).
  { unfold UnconditionalBasis.phi.
    assert (Hltb : (k <? a) = true).
    { apply (proj2 (Nat.ltb_lt k a)). move: Hka => /ltP Hka'. exact Hka'. }
    rewrite Hltb. reflexivity. }
  assert (Hphib : UnconditionalBasis.phi b k = Cexp (0 +i (2 * PI * INR k / INR b))).
  { unfold UnconditionalBasis.phi.
    assert (Hltb : (k <? b) = true).
    { apply (proj2 (Nat.ltb_lt k b)). move: Hkb => /ltP Hkb'. exact Hkb'. }
    rewrite Hltb. reflexivity. }
  rewrite Hphia.
  (* 展开 b 侧 phi：psi b k 内部 phi b k = Cexp(0+i·2πk/b)（Cconj 内 rewrite） *)
  rewrite Hphib.
  (* Cconj (Cexp (0+iθ)) = Cexp (0+i(−θ))，θ = 2πk/b（内联 g1_Cconj_exp） *)
  rewrite (g1_Cconj_exp (2 * PI * INR k / INR b)).
  (* 标量重组：(c1·Cexp(θ1))·(c2·Cexp(θ2)) = (c1·c2)·(Cexp(θ1)·Cexp(θ2)) *)
  set (c1 := Cof_real (1 / sqrt (INR a))).
  set (c2 := Cof_real (1 / sqrt (INR b))).
  assert (Hre : (c1 *c Cexp (0 +i (2 * PI * INR k / INR a)))
                *c (c2 *c Cexp (0 +i (- (2 * PI * INR k / INR b))))
                = (c1 *c c2) *c (Cexp (0 +i (2 * PI * INR k / INR a))
                                  *c Cexp (0 +i (- (2 * PI * INR k / INR b))))).
  { rewrite Cmul_assoc.
    assert (Htmp : Cexp (0 +i (2 * PI * INR k / INR a)) *c (c2 *c Cexp (0 +i (- (2 * PI * INR k / INR b))))
                   = c2 *c (Cexp (0 +i (2 * PI * INR k / INR a)) *c Cexp (0 +i (- (2 * PI * INR k / INR b))))).
    { rewrite <- Cmul_assoc.
      rewrite (Cmul_comm (Cexp (0 +i (2 * PI * INR k / INR a))) c2).
      rewrite Cmul_assoc. reflexivity. }
    rewrite Htmp. rewrite <- Cmul_assoc. reflexivity. }
  rewrite Hre.
  (* 乘法合并：Cexp(0+iθ1)·Cexp(0+i(−θ2)) = Cexp(0+i(θ1−θ2))
     —— 用 g1_Cexp_mul_i（已证） *)
  rewrite (g1_Cexp_mul_i (2 * PI * INR k / INR a) (- (2 * PI * INR k / INR b))).
  (* 角度归一：θ1+(−θ2) = INR k·2π(b−a)/(ab)，整体替换 Cexp 参数 *)
  assert (Hang : (2 * PI * INR k / INR a + - (2 * PI * INR k / INR b))
                 = (INR k * ((2 * PI * (INR b - INR a)) / (INR a * INR b)))%R).
  { field.
    split.
    - apply Rgt_not_eq. apply lt_0_INR. move: Hkb => /ltP Hkb'. lia.
    - apply Rgt_not_eq. apply lt_0_INR. move: Hka => /ltP Hka'. lia. }
  rewrite Hang.
  (* Cexp(0+i·INR k·theta) = rot_atom theta k（定义展开） *)
  replace (Cexp (0 +i (INR k * ((2 * PI * (INR b - INR a)) / (INR a * INR b)))))
    with (rot_atom ((2 * PI * (INR b - INR a)) / (INR a * INR b))%R k).
  2: { unfold rot_atom. reflexivity. }
  (* 标量合并：c1·c2 = Cof_real(1/√a)·Cof_real(1/√b) = Cof_real((1/√a)·(1/√b)) *)
  unfold c1, c2.
  replace (Cof_real (1 / sqrt (INR a)) *c Cof_real (1 / sqrt (INR b)))
    with (Cof_real ((1 / sqrt (INR a))%R * (1 / sqrt (INR b))%R)).
  2: { unfold Cof_real, Cmul. apply Complex_eq; simpl; ring. }
  reflexivity.
Qed.
(* ★ 单对精确内积（Dirichlet 实部闭式）：
   ipW (psi a) (psi b) W = (1/√(ab))·Σ_{k<m} re(rot_atom theta k)，
   m = min(a,b,W+1) —— 支撑截断 + 窗口截断（Σ 只到 k < m，即 predn m） *)
Lemma g1_ipW_psi (a b W : nat) :
  (1 <= a)%nat -> (1 <= b)%nat ->
  ipW (psi a) (psi b) W
  = ((1 / sqrt (INR a))%R * (1 / sqrt (INR b))%R)
    * sum_f_R0 (fun k => re (rot_atom ((2 * PI * (INR b - INR a)) / (INR a * INR b))%R k))
        (predn (Nat.min (Nat.min a b) (S W))).
Proof.
  intros H1 H2.
  unfold ipW.
  set (m := Nat.min (Nat.min a b) (S W)).
  assert (HmW : le m (S W)) by (unfold m; lia).
  assert (Hhz : forall k : nat, le m k -> le k W -> re (psi a k *c Cconj (psi b k)) = 0%R).
  { intros k Hk1 Hk2.
    assert (Hmin : le (Nat.min a b) k).
    { apply (g1_min_ge a b W k). exact Hk1. exact Hk2. }
    destruct (Nat.leb a b) as [] eqn: Hab.
    - apply Nat.leb_le in Hab.
      assert (Hak : le a k).
      { apply (Nat.le_trans _ (Nat.min a b) _).
        - rewrite (Nat.min_l a b Hab). reflexivity.
        - exact Hmin. }
      assert (Hakb : (a <= k)%nat) by (apply/leP; exact Hak).
      rewrite (g1_psi_conj_zero a b k Hakb). simpl. ring.
    - apply Nat.leb_gt in Hab.
      assert (Hbk : le b k).
      { apply (Nat.le_trans _ (Nat.min a b) _).
        - lia.
        - exact Hmin. }
      assert (Hbkb : (b <= k)%nat) by (apply/leP; exact Hbk).
      rewrite (g1_psi_zero b k Hbkb).
      unfold Cconj, C0, Cmul. simpl. ring. }
  rewrite (g1_sum_trunc (fun k => re (psi a k *c Cconj (psi b k))) W m HmW Hhz).
  unfold m.
  assert (Hext : forall k : nat, Nat.le k (predn (Nat.min (Nat.min a b) (S W))) ->
           re (psi a k *c Cconj (psi b k)) =
           (1 / sqrt (INR a))%R * (1 / sqrt (INR b))%R
             * re (rot_atom ((2 * PI * (INR b - INR a)) / (INR a * INR b))%R k)).
  { intros k Hk.
       assert (Hklt : lt k (Nat.min (Nat.min a b) (S W))).
       { apply (g1_lt_pred k (Nat.min (Nat.min a b) (S W))).
          - apply (Nat.min_glb (Nat.min a b) (S W) 1).
           + destruct (Nat.leb a b) as [] eqn: Hab.
             * apply Nat.leb_le in Hab.
               rewrite (Nat.min_l a b Hab). apply/leP. exact H1.
             * apply Nat.leb_gt in Hab.
               assert (Hba : le b a) by lia.
               rewrite (Nat.min_r a b Hba).
               apply/leP. exact H2.
            + lia.
         - exact Hk. }
       assert (Hka : lt k a).
        { apply (Stdlib.Arith.PeanoNat.Nat.lt_le_trans k (Nat.min (Nat.min a b) (S W)) a).
         - exact Hklt.
         - apply (Nat.le_trans _ (Nat.min a b) _).
           + apply Nat.le_min_l.
           + apply Nat.le_min_l. }
       assert (Hkb : lt k b).
         { apply (Stdlib.Arith.PeanoNat.Nat.lt_le_trans k (Nat.min (Nat.min a b) (S W)) b).
         - exact Hklt.
         - apply (Nat.le_trans _ (Nat.min a b) _).
           + apply Nat.le_min_l.
           + apply Nat.le_min_r. }
        assert (Hka' : (k < a)%nat) by (apply/ltP; exact Hka).
        assert (Hkb' : (k < b)%nat) by (apply/ltP; exact Hkb).
        rewrite (g1_psi_point a b k Hka' Hkb').
         rewrite Cof_real_mul_re.
         reflexivity. }
  rewrite (g1_sum_ext _ (fun k => ((1 / sqrt (INR a))%R * (1 / sqrt (INR b))%R
                                    * re (rot_atom ((2 * PI * (INR b - INR a)) / (INR a * INR b))%R k))%R)
                        (predn (Nat.min (Nat.min a b) (S W))) Hext).
  rewrite (g1_sum_scal ((1 / sqrt (INR a))%R * (1 / sqrt (INR b))%R)
            (fun k => re (rot_atom ((2 * PI * (INR b - INR a)) / (INR a * INR b))%R k))
            (predn (Nat.min (Nat.min a b) (S W)))).
  reflexivity.
Qed.
(* ‖comboM (S M) c u‖²_W = Σ_{j≤SM} c_j²·‖u_j‖²_W
   + 2·Σ_{j'=1}^{SM}Σ_{i<j'} c_i·c_{j'}·⟨u_i,u_{j'}⟩_W
   （comboM (S M) 含原子 0..SM；交叉和索引平移外层 j'=S j，j 到 predn M） *)
Lemma g1_gram_full (M : nat) (c : nat -> R) (u : nat -> nat -> Complex) (W : nat) :
  le 1 M ->
  (l2_norm_sq (comboM (S M) c u) W)%R
  = (sum_f_R0 (fun j => (c j * c j * l2_norm_sq (u j) W)%R) M
     + 2 * sum_f_R0 (fun j => sum_f_R0
         (fun i => (c i * c (S j) * ipW (u i) (u (S j)) W)%R) j) (predn M))%R.
Proof.
  intros HM.
  destruct M as [| M'].
  - exfalso. lia.
  - (* M = S M'：comboM (S (S M'))，归纳于 M' *)
    induction M' as [| M'' IH].
    + (* M'=0：comboM (S (S 0)) = comboM 2 = 两原子 u_0, u_1 *)
      rewrite (norm_sq_comboM_rec 0 c u W).
      rewrite (comboM_one c u).
      assert (Hc0 : (l2_norm_sq (fun k => Cof_real (c 0%nat) *c u 0%nat k) W)%R
                    = (c 0%nat * c 0%nat * l2_norm_sq (u 0%nat) W)%R).
      { unfold l2_norm_sq.
        assert (Hpt : forall k : nat, Nat.le k W -> (Cnorm_sq (Cof_real (c 0%nat) *c u 0%nat k) = c 0%nat * c 0%nat * Cnorm_sq (u 0%nat k))%R).
        { intro k. intro Hk. exact (g1_norm_Cof_mul (c 0%nat) (u 0%nat k)). }
        transitivity (sum_f_R0 (fun k => (c 0%nat * c 0%nat * Cnorm_sq (u 0%nat k))%R) W).
        { apply (g1_sum_ext (fun k => Cnorm_sq (Cof_real (c 0%nat) *c u 0%nat k))
                            (fun k => (c 0%nat * c 0%nat * Cnorm_sq (u 0%nat k))%R) W Hpt). }
        rewrite (g1_sum_scal (c 0%nat * c 0%nat) (fun k => Cnorm_sq (u 0%nat k)) W).
        reflexivity. }
      rewrite Hc0.
      (* 交叉项：2·c_1·⟨Cof_real(c_0)·u_0, u_1⟩ = 2·c_1·(c_0·⟨u_0,u_1⟩)
         （comboM 1 已归约，用 ipW_CR_l 线性提取） *)
      rewrite (ipW_CR_l (c 0%nat) (u 0%nat) (u 1%nat) W).
      (* RHS：对角 Σ_{j≤1} + 2·交叉 j'=1 层（i=0..0） *)
      replace (sum_f_R0 (fun j => (c j * c j * l2_norm_sq (u j) W)%R) 1)%R
        with ((c 0%nat * c 0%nat * l2_norm_sq (u 0%nat) W)%R
              + (c 1%nat * c 1%nat * l2_norm_sq (u 1%nat) W)%R)%R by reflexivity.
      replace (sum_f_R0 (fun j : nat => sum_f_R0
          (fun i : nat => (c i * c (S j) * ipW (u i) (u (S j)) W)%R) j) (predn 1))%R
        with (c 0%nat * c 1%nat * ipW (u 0%nat) (u 1%nat) W)%R by reflexivity.
      ring.
    + (* M' = S M''：comboM (S (S (S M'')))，norm_sq_comboM_rec (S M'') + IH *)
      rewrite (norm_sq_comboM_rec (S M'') c u W).
      rewrite (IH (le_n_S _ _ (Nat.le_0_l M''))).  (* IH 需 le 1 (S M'')，恒真 *)
      (* 交叉项：2·c_{S(S M'')}·⟨comboM (S (S M'')), u_{S(S M'')}⟩
         = 2·c_{S(S M'')}·Σ_{j≤S M''} c_j·⟨u_j, u_{S(S M'')}⟩（ipW_combo_l） *)
      rewrite (ipW_combo_l (S M'') c u (u (S (S M''))) W).
      (* RHS(S(S M'')) 拆分：对角 + 交叉双和（尾层 j'=S(S M'')） *)
      rewrite (g1_diag_S (S M'') c (fun j => l2_norm_sq (u j) W)).
      rewrite (g1_cross_S (S M'') (fun i j => (c i * c j * ipW (u i) (u j) W)%R)
                           (le_n_S 0 M'' (Nat.le_0_l M''))).
      + (* 最终：LHS 交叉项 2·c_{SM''}·Σ_{j≤SM''} c_j·⟨u_j,u_{SM''}⟩
           == RHS 尾层 2·Σ_{i≤SM''} c_i·c_{SM''}·⟨u_i,u_{SM''}⟩
           用 replace 一次性替换 LHS 交叉项为目标形式 *)
        replace (2 * c (S (S M'')) * sum_f_R0 (fun j : nat =>
            (c j * ipW (u j) (u (S (S M''))) W)%R) (S M''))%R
          with (2 * sum_f_R0 (fun i : nat =>
            (c i * c (S (S M'')) * ipW (u i) (u (S (S M''))) W)%R) (S M''))%R.
        2: { (* 目标（2: 反向）：2·Σ(c_i·c·⟨⟩) = 2·c·Σ(c_j·⟨⟩)
               ① RHS 结合律：2·c·Σ = 2·(c·Σ) *)
             replace (2 * c (S (S M'')) * sum_f_R0 (fun j : nat =>
                 (c j * ipW (u j) (u (S (S M''))) W)%R) (S M''))%R
               with (2 * (c (S (S M'')) * sum_f_R0 (fun j : nat =>
                 (c j * ipW (u j) (u (S (S M''))) W)%R) (S M'')))%R by ring.
             (* ② 消 2 *)
             apply Rmult_eq_compat_l.
             (* ③ RHS：c·Σ(c_j·⟨⟩) = Σ(c·(c_j·⟨⟩))（g1_sum_scal 反向） *)
             rewrite <- (g1_sum_scal (c (S (S M'')))
               (fun j => (c j * ipW (u j) (u (S (S M''))) W)%R) (S M'')).
             (* ④ 逐点对齐：Σ(c·(c_j·⟨⟩)) = Σ(c_j·c·⟨⟩)（g1_sum_ext） *)
             apply g1_sum_ext. intro k. intro Hk. cbv beta. ring. }
        (* 归一所有 predn：目标中 RHS 双和外层 predn (S (S M'')) = S M'' *)
        change (predn (S (S M''))) with (S M'').
        ring.
Qed.
(* ============ R3. ★ 主定理：加权阶梯范数精确闭式 ============ *)
(* 混窗阶梯 F = Σ_{j≤M} c_j·ψ_{n_j} 的范数平方精确等式：
   ‖F‖²_W = Σ_j c_j²·‖ψ_{n_j}‖²_W + 2·Σ_{i<j'} c_i·c_{j'}·⟨ψ_{n_i},ψ_{n_{j'}}⟩_W
   （交叉和索引平移编码 j'=S j，与 R2 一致） *)
Theorem G1_norm_closed (M : nat) (c : nat -> R) (n : nat -> nat) (W : nat) :
  le 1 M ->
  (l2_norm_sq (comboM (S M) c (fun j => psi (n j))) W)%R
  = (sum_f_R0 (fun j => (c j * c j * l2_norm_sq (psi (n j)) W)%R) M
     + 2 * sum_f_R0 (fun j => sum_f_R0
         (fun i => (c i * c (S j) * ipW (psi (n i)) (psi (n (S j))) W)%R) j) (predn M))%R.
Proof.
  (* R2 实例化 u := fun j => psi (n j) *)
  intros HM.
  apply (g1_gram_full M c (fun j => psi (n j)) W HM).
Qed.

End G1NormClosed.

(* ==================== 模块 49/67: probe_g2_mu_adj ==================== *)

Close Scope Z_scope.
