From mathcomp Require Import ssreflect ssrbool ssrnat seq eqtype div prime.
Require Import Stdlib.Reals.Reals.
Require Import Stdlib.Reals.Ranalysis1.
Require Import Stdlib.Reals.Ranalysis5.
Require Import Stdlib.Arith.Arith.
Require Import Stdlib.micromega.Lia.
Require Import Stdlib.micromega.Lra.
Require Import Stdlib.ZArith.ZArith.
Import ComplexNumbers.
Import FourierAnalysis.
Import GridOrtho.
Import TPartial.
Import PairBound.

Open Scope R_scope.

Module G2MuAdj.

(* ============ R0. Definition and basics ============ *)

(* mu_adj(r) := sqrt(r)*sin(pi/r)/(pi*(r-1)) *)
Definition mu_adj (r : R) : R :=
  sqrt r * sin (PI / r) / (PI * (r - 1))%R.

(* Well-defined: r > 1 gives nonzero denominator *)
Lemma mu_adj_def (r : R) :
  (1 < r)%R -> (PI * (r - 1))%R <> 0%R.
Proof.
  intros Hr.
  apply Rmult_integral_contrapositive.
  split.
  - apply Rgt_not_eq. apply PI_RGT_0.
  - apply Rgt_not_eq. lra.
Qed.

(* Nonneg: r >= 2 gives sqrt>=0, sin(pi/r)>=0, denom>0 *)
Lemma mu_adj_nonneg (r : R) :
  (2 <= r)%R -> (0 <= mu_adj r)%R.
Proof.
  intros Hr.
  unfold mu_adj.
  apply Rmult_le_pos.
  - apply Rmult_le_pos.
    + apply sqrt_pos.
    + apply sin_ge_0.
      * assert (Hpos : (0 < PI / r)%R).
        { unfold Rdiv. apply Rmult_lt_0_compat; [apply PI_RGT_0 | apply Rinv_0_lt_compat; lra]. }
        apply Rlt_le. exact Hpos.
      * assert (Hle : (PI / r <= PI)%R).
        { unfold Rdiv.
          apply (Rmult_le_reg_l r).
          - lra.
          - replace (r * (PI * / r))%R with PI%R by (field; lra).
            rewrite Rmult_comm.
            replace (PI)%R with (PI * 1)%R at 1 by ring.
            apply Rmult_le_compat_l.
            + apply Rlt_le. apply PI_RGT_0.
            + lra. }
        exact Hle.
  - apply Rlt_le. apply Rinv_0_lt_compat.
    apply Rmult_lt_0_compat; [apply PI_RGT_0 | lra].
Qed.

(* ============ R1. Monotone decreasing on r >= 2 ============ *)

(* f(r) = sqrt(r)/(r-1) decreasing: cross-multiplied form *)
Lemma g2_sqrt_cross (a b : R) :
  (2 <= a)%R -> (a < b)%R ->
  (sqrt b * (a - 1) < sqrt a * (b - 1))%R.
Proof.
  intros Ha Hab.
  assert (Hsq : b * (a - 1)^2 < a * (b - 1)^2).
  { assert (Heq : b * (a - 1)^2 - a * (b - 1)^2 = - ((b - a) * (a * b - 1))) by ring.
    apply Rminus_lt.
    rewrite Heq.
    assert (Hpos : 0 < (b - a) * (a * b - 1)) by (apply Rmult_lt_0_compat; [lra | nra]).
    lra. }
  assert (H1 : sqrt (b * (a - 1)^2) < sqrt (a * (b - 1)^2)).
  { apply sqrt_lt_1; [apply Rmult_le_pos; [lra | apply pow2_ge_0]
    | apply Rmult_le_pos; [lra | apply pow2_ge_0] | exact Hsq]. }
  assert (Hb0 : (0 <= b)%R) by lra.
  assert (Ha0 : (0 <= a)%R) by lra.
  assert (Ha1 : (0 <= a - 1)%R) by lra.
  assert (Hb1 : (0 <= b - 1)%R) by lra.
  rewrite (sqrt_mult b ((a - 1)^2) Hb0 (pow2_ge_0 (a - 1))) in H1.
  rewrite (sqrt_mult a ((b - 1)^2) Ha0 (pow2_ge_0 (b - 1))) in H1.
  rewrite (sqrt_pow2 (a - 1) Ha1) in H1.
  rewrite (sqrt_pow2 (b - 1) Hb1) in H1.
  exact H1.
Qed.

(* 0 < PI / r for r > 0 *)
Lemma g2_pi_over_r_pos (r : R) : (0 < r)%R -> (0 < PI / r)%R.
Proof.
  intros Hr.
  unfold Rdiv.
  apply Rmult_lt_0_compat; [apply PI_RGT_0 | apply Rinv_0_lt_compat; exact Hr].
Qed.

(* g(r) = sin(pi/r) increasing for r >= 2 *)
Lemma g2_sin_incr (a b : R) :
  (2 <= a)%R -> (a < b)%R ->
  (sin (PI / b) < sin (PI / a))%R.
Proof.
  intros Ha Hab.
  assert (Ha0 : 0 < a) by lra.
  assert (Hb0 : 0 < b) by lra.
  assert (HPI : 0 < PI) by apply PI_RGT_0.
  apply sin_increasing_1.
  (* -PI/2 <= PI/b *)
  - apply Rle_trans with 0%R; [lra | apply Rlt_le; apply g2_pi_over_r_pos; exact Hb0].
  (* PI/b <= PI/2 *)
  - unfold Rdiv.
    apply Rmult_le_compat_l; [apply Rlt_le; apply PI_RGT_0 |].
    apply Rinv_le_contravar; [lra | lra].
  (* -PI/2 <= PI/a *)
  - apply Rle_trans with 0%R; [lra | apply Rlt_le; apply g2_pi_over_r_pos; exact Ha0].
  (* PI/a <= PI/2 *)
  - unfold Rdiv.
    apply Rmult_le_compat_l; [apply Rlt_le; apply PI_RGT_0 |].
    apply Rinv_le_contravar; [lra | lra].
  (* PI/b < PI/a *)
  - unfold Rdiv.
    apply Rmult_lt_compat_l; [apply PI_RGT_0 |].
    apply Rinv_lt_contravar.
    + apply Rmult_lt_0_compat; lra.
    + lra.
Qed.

(* sin(pi/r) > 0 for r >= 2 *)
Lemma g2_sin_pos (r : R) :
  (2 <= r)%R -> (0 < sin (PI / r))%R.
Proof.
  intros Hr.
  assert (HPI : 0 < PI) by apply PI_RGT_0.
  assert (Hr0 : 0 < r) by lra.
  assert (H : sin 0 < sin (PI / r)).
  { apply sin_increasing_1.
    - lra.
    - lra.
    - apply Rle_trans with 0%R; [lra | apply Rlt_le; apply g2_pi_over_r_pos; exact Hr0].
    - unfold Rdiv.
      apply Rmult_le_compat_l; [apply Rlt_le; apply PI_RGT_0 |].
      apply Rinv_le_contravar; [lra | lra].
    - apply g2_pi_over_r_pos; exact Hr0.
  }
  rewrite sin_0 in H.
  exact H.
Qed.

(* 0 < sqrt r for r > 0 *)
Lemma g2_sqrt_pos (r : R) : (0 < r)%R -> (0 < sqrt r)%R.
Proof.
  intros Hr.
  assert (H : sqrt 0 < sqrt r).
  { apply sqrt_lt_1; [lra | apply Rlt_le; exact Hr | lra]. }
  rewrite sqrt_0 in H.
  exact H.
Qed.

(* Cross form: mu_adj numerator comparison *)
Lemma g2_mu_cross (r1 r2 : R) :
  (2 <= r1)%R -> (r1 < r2)%R ->
  (sqrt r2 * sin (PI / r2) * (r1 - 1) < sqrt r1 * sin (PI / r1) * (r2 - 1))%R.
Proof.
  intros Hr1 Hr12.
  assert (Hsin : sin (PI / r2) < sin (PI / r1)) by (apply g2_sin_incr; assumption).
  assert (Hsqrt : sqrt r2 * (r1 - 1) < sqrt r1 * (r2 - 1)) by (apply g2_sqrt_cross; assumption).
  assert (Hsinpos : 0 < sin (PI / r1)) by (apply g2_sin_pos; lra).
  assert (Hprodpos : 0 < sqrt r2 * (r1 - 1)) by (apply Rmult_lt_0_compat; [apply g2_sqrt_pos; lra | lra]).
  apply (Rlt_trans _ (sqrt r2 * sin (PI / r1) * (r1 - 1)) _).
  - replace (sqrt r2 * sin (PI / r2) * (r1 - 1)) with ((sqrt r2 * (r1 - 1)) * sin (PI / r2)) by ring.
    replace (sqrt r2 * sin (PI / r1) * (r1 - 1)) with ((sqrt r2 * (r1 - 1)) * sin (PI / r1)) by ring.
    apply Rmult_lt_compat_l; [exact Hprodpos | exact Hsin].
  - replace (sqrt r2 * sin (PI / r1) * (r1 - 1)) with (sin (PI / r1) * (sqrt r2 * (r1 - 1))) by ring.
    replace (sqrt r1 * sin (PI / r1) * (r2 - 1)) with (sin (PI / r1) * (sqrt r1 * (r2 - 1))) by ring.
    apply Rmult_lt_compat_l; [exact Hsinpos | exact Hsqrt].
Qed.

(* Divide-out helpers for the final cross-multiplication *)
Lemma g2_mu_div_l (r1 r2 : R) :
  (2 <= r1)%R -> (r1 < r2)%R ->
  (sqrt r2 * sin (PI / r2) * (r1 - 1) * / (PI * (r2 - 1) * (r1 - 1))
   = sqrt r2 * sin (PI / r2) * / (PI * (r2 - 1)))%R.
Proof.
  intros Hr1 Hr12.
  field.
  split; [lra | split; [apply Rgt_not_eq, PI_RGT_0 | lra]].
Qed.

Lemma g2_mu_div_r (r1 r2 : R) :
  (2 <= r1)%R -> (r1 < r2)%R ->
  (sqrt r1 * sin (PI / r1) * (r2 - 1) * / (PI * (r2 - 1) * (r1 - 1))
   = sqrt r1 * sin (PI / r1) * / (PI * (r1 - 1)))%R.
Proof.
  intros Hr1 Hr12.
  field.
  split; [lra | split; [apply Rgt_not_eq, PI_RGT_0 | lra]].
Qed.

Theorem mu_adj_decreasing (r1 r2 : R) :
  (2 <= r1)%R -> (r1 < r2)%R ->
  (mu_adj r2 < mu_adj r1)%R.
Proof.
  intros Hr1 Hr12.
  unfold mu_adj.
  assert (Hcross : sqrt r2 * sin (PI / r2) * (r1 - 1) < sqrt r1 * sin (PI / r1) * (r2 - 1))
    by (apply g2_mu_cross; assumption).
  (* multiply both sides of Hcross by the positive /(PI*(r2-1)*(r1-1)) *)
  apply (Rmult_lt_compat_r (/ (PI * (r2 - 1) * (r1 - 1)))) in Hcross.
  - rewrite (g2_mu_div_l r1 r2 Hr1 Hr12) in Hcross.
    rewrite (g2_mu_div_r r1 r2 Hr1 Hr12) in Hcross.
    exact Hcross.
  - apply Rinv_0_lt_compat.
    assert (HPI : 0 < PI) by apply PI_RGT_0.
    assert (Hr21 : 0 < r2 - 1) by lra.
    assert (Hr11 : 0 < r1 - 1) by lra.
    apply Rmult_lt_0_compat; [apply Rmult_lt_0_compat; [exact HPI | exact Hr21] | exact Hr11].
Qed.

(* ============ R2. Phase transition exists ============ *)
(* 相变存在性证明路线：
   - pi upper bound pi < 17/5 via sin_bound 0th order (sin_approx t 2 = t - t^3/6 + t^5/120)
   - pi lower bound pi > 3 via PI2_3_2
   - mu_adj(6/5) > 4/5  (sqrt(6/5)*5/(2pi) > 4/5  <=>  750 > 64 pi^2, pi < 17/5)
   - mu_adj(3/2) < 4/5  (3/(sqrt 2 * pi) < 4/5  <=>  225 < 32 pi^2, pi > 3)
   - IVT_interv on g(r) = -(mu_adj r - 4/5), g(6/5) < 0 < g(3/2) *)

(* pi < 17/5: sin_bound 0th order *)
Lemma g2_sin_approx2 (t : R) :
  sin_approx t 2 = t - t ^ 3 / 6 + t ^ 5 / 120.
Proof.
  unfold sin_approx, sin_term.
  cbn.
  replace (2 * 0 + 1)%nat with 1%nat by reflexivity.
  replace (2 * 1 + 1)%nat with 3%nat by reflexivity.
  replace (2 * 2 + 1)%nat with 5%nat by reflexivity.
  field.
  all: try (apply Rgt_not_eq; lra).
Qed.

Lemma g2_sin_approx2_pi_ge_1 : (1 <= sin_approx (PI / 2) 2)%R.
Proof.
  assert (Hpos : (0 <= PI / 2)%R) by (apply Rlt_le; apply PI2_RGT_0).
  assert (Hle : (PI / 2 <= PI)%R) by (apply Rlt_le; apply PI2_Rlt_PI).
  pose proof (sin_bound (PI / 2) 0 Hpos Hle) as H.
  destruct H as [Hlo Hhi].
  rewrite sin_PI2 in Hhi.
  replace (2 * (0 + 1))%nat with 2%nat in Hhi by reflexivity.
  exact Hhi.
Qed.

Lemma pow2_2 (t : R) : t ^ 4 = (t ^ 2) ^ 2.
Proof.
  change (t ^ (2 * 2) = (t ^ 2) ^ 2).
  rewrite <- pow_mult.
  reflexivity.
Qed.

(* f'(t) = 1 - t^2/2 + t^4/24 < 0 on [17/10, 2] *)
Lemma g2_fp_neg (t : R) : (17 / 10 <= t)%R -> (t <= 2)%R ->
  (1 - t ^ 2 / 2 + t ^ 4 / 24 < 0)%R.
Proof.
  intros Hlo Hhi.
  rewrite pow2_2.
  set (u := t ^ 2).
  assert (Hlo_u : (289 / 100 <= u)%R).
  { subst u. nra. }
  assert (Hhi_u : (u <= 4)%R).
  { subst u. nra. }
  replace (1 - t ^ 2 / 2 + (t ^ 2) ^ 2 / 24) with (1 - u / 2 + u ^ 2 / 24) by (subst u; ring).
  nra.
Qed.

(* f(x) = x - x^3/6 + x^5/120, derivative in INR form *)
Lemma g2_dpl_f (x : R) :
  derivable_pt_lim (fun t => t - t ^ 3 / 6 + t ^ 5 / 120)
                   x (1 - INR 3 * x ^ Nat.pred 3 / 6 + INR 5 * x ^ Nat.pred 5 / 120).
Proof.
  assert (Hpow3 : derivable_pt_lim (fun t => t ^ 3) x (INR 3 * x ^ (Nat.pred 3))).
  { apply (derivable_pt_lim_pow x 3). }
  assert (Hpow5 : derivable_pt_lim (fun t => t ^ 5) x (INR 5 * x ^ (Nat.pred 5))).
  { apply (derivable_pt_lim_pow x 5). }
  assert (Hdiv3 : derivable_pt_lim (fun t => t ^ 3 / 6) x (INR 3 * x ^ Nat.pred 3 / 6)).
  { apply derivable_pt_lim_div_scal. exact Hpow3. }
  assert (Hdiv5 : derivable_pt_lim (fun t => t ^ 5 / 120) x (INR 5 * x ^ Nat.pred 5 / 120)).
  { apply derivable_pt_lim_div_scal. exact Hpow5. }
  assert (H1 : derivable_pt_lim (fun t => t - t ^ 3 / 6) x (1 - INR 3 * x ^ Nat.pred 3 / 6)).
  { change (derivable_pt_lim (fun t => t + (- (t ^ 3 / 6))) x (1 + (- (INR 3 * x ^ Nat.pred 3 / 6)))).
    apply derivable_pt_lim_plus.
    - change (derivable_pt_lim id x 1). apply derivable_pt_lim_id.
    - apply derivable_pt_lim_opp. exact Hdiv3. }
  change (derivable_pt_lim (fun t => (t - t ^ 3 / 6) + t ^ 5 / 120) x ((1 - INR 3 * x ^ Nat.pred 3 / 6) + INR 5 * x ^ Nat.pred 5 / 120)).
  apply derivable_pt_lim_plus; [exact H1 | exact Hdiv5].
Qed.

(* bridge to the displayed derivative *)
Lemma g2_dpl_f_nice (x : R) :
  derivable_pt_lim (fun t => t - t ^ 3 / 6 + t ^ 5 / 120) x (1 - x ^ 2 / 2 + x ^ 4 / 24).
Proof.
  assert (H : derivable_pt_lim (fun t => t - t ^ 3 / 6 + t ^ 5 / 120)
                   x (1 - INR 3 * x ^ Nat.pred 3 / 6 + INR 5 * x ^ Nat.pred 5 / 120)) by apply g2_dpl_f.
  assert (Hv : (1 - INR 3 * x ^ Nat.pred 3 / 6 + INR 5 * x ^ Nat.pred 5 / 120
                = 1 - x ^ 2 / 2 + x ^ 4 / 24)%R).
  { unfold Nat.pred.
    assert (H3 : (INR 3 = 3)%R). { rewrite INR_IZR_INZ. reflexivity. }
    assert (H5 : (INR 5 = 5)%R). { rewrite INR_IZR_INZ. reflexivity. }
    rewrite H3. rewrite H5.
    field. }
  rewrite Hv in H.
  exact H.
Qed.

(* f strictly decreasing on [17/10, t] for t <= 2 via MVT *)
Lemma g2_f_decr (t : R) :
  (17 / 10 < t)%R -> (t <= 2)%R ->
  (t - t ^ 3 / 6 + t ^ 5 / 120 < 17/10 - (17/10)^3/6 + (17/10)^5/120)%R.
Proof.
  intros Hlt Hhi.
  destruct (MVT_cor3 (fun x => x - x ^ 3 / 6 + x ^ 5 / 120)
                     (fun x => 1 - x ^ 2 / 2 + x ^ 4 / 24)
                     (17 / 10) t) as [c [Hc1 [Hc2 Hc3]]].
  - exact Hlt.
  - intros x Hx1 Hx2. apply g2_dpl_f_nice.
  - assert (Hneg : (1 - c ^ 2 / 2 + c ^ 4 / 24 < 0)%R).
    { apply g2_fp_neg; [exact Hc1 | eapply Rle_trans; [exact Hc2 | exact Hhi]]. }
    rewrite Hc3.
    nra.
Qed.

Lemma g2_f_17_10_lt_1 : (17/10 - (17/10)^3/6 + (17/10)^5/120 < 1)%R.
Proof.
  nra.
Qed.

Lemma g2_pi_lt_17_5 : (PI < 17 / 5)%R.
Proof.
  apply Rnot_ge_lt.
  intro Hge.
  assert (Ht : (17 / 10 <= PI / 2)%R) by lra.
  assert (Hlt1 : (sin_approx (17 / 10) 2 < 1)%R).
  { rewrite g2_sin_approx2. exact g2_f_17_10_lt_1. }
  assert (Hc : (sin_approx (PI / 2) 2 < 1)%R).
  { destruct (Req_dec (PI / 2) (17 / 10)) as [Heq | Hne].
    - rewrite Heq. exact Hlt1.
    - assert (Hlt : (17 / 10 < PI / 2)%R) by lra.
      assert (Hdec : (sin_approx (PI / 2) 2 < sin_approx (17 / 10) 2)%R).
      { rewrite g2_sin_approx2. rewrite g2_sin_approx2.
        apply g2_f_decr; [exact Hlt | ].
        assert (Hpi2 : (PI / 2 <= 2)%R).
        { apply Rmult_le_reg_l with 2%R; [lra |].
          replace (2 * (PI / 2))%R with PI%R by (field; apply Rgt_not_eq, PI_RGT_0).
          replace (2 * 2)%R with 4%R by ring.
          exact PI_4. }
        exact Hpi2. }
      eapply Rlt_trans; [exact Hdec | exact Hlt1]. }
  assert (H1le : (1 <= sin_approx (PI / 2) 2)%R) by exact g2_sin_approx2_pi_ge_1.
  lra.
Qed.

(* pi > 3 *)
Lemma g2_pi_gt_3 : (3 < PI)%R.
Proof.
  assert (H : (2 * (3 / 2) < 2 * (PI / 2))%R).
  { apply Rmult_lt_compat_l; [lra | exact PI2_3_2]. }
  replace (2 * (3 / 2))%R with 3%R in H by field.
  replace (2 * (PI / 2))%R with PI%R in H by (field; apply Rgt_not_eq, PI_RGT_0).
  exact H.
Qed.

(* sqrt(3/2)*sqrt 3 = 3/sqrt 2 *)
Lemma g2_sqrt_32_3 : (sqrt (3 / 2) * sqrt 3 = 3 / sqrt 2)%R.
Proof.
  assert (Hm : (sqrt (3 / 2) * sqrt 3 = sqrt ((3 / 2) * 3))%R).
  { symmetry. apply sqrt_mult; lra. }
  rewrite Hm.
  replace ((3 / 2) * 3)%R with (9 / 2)%R by field.
  apply Rsqr_inj.
  - apply sqrt_pos.
  - apply Rlt_le; apply Rdiv_lt_0_compat; [lra | apply g2_sqrt_pos; lra].
  - assert (Ht1 : (Rsqr (sqrt (9 / 2)) = 9 / 2)%R).
    { unfold Rsqr. apply Rsqr_sqrt. lra. }
    assert (Ht2 : (Rsqr (3 / sqrt 2) = 9 / 2)%R).
    { unfold Rsqr, Rdiv.
      assert (Hnz : sqrt 2 <> 0) by (apply Rgt_not_eq; apply g2_sqrt_pos; lra).
      replace (3 * / sqrt 2 * (3 * / sqrt 2))%R with (9 * / (sqrt 2 * sqrt 2))%R by (field; exact Hnz).
      replace (sqrt 2 * sqrt 2)%R with 2%R by (rewrite (sqrt_sqrt 2 (Rlt_le 0 2 Rlt_0_2)); ring).
      field. }
    rewrite Ht1. rewrite Ht2. reflexivity.
Qed.

(* mu_adj(6/5) > 4/5 : 25*sqrt(6/5) > 8PI  <=>  750 > 64 PI^2, pi < 17/5 *)
Lemma g2_mu_65_gt : (sqrt (6 / 5) * 5 / (2 * PI) > 4 / 5)%R.
Proof.
  assert (Hpi : (PI < 17 / 5)%R) by exact g2_pi_lt_17_5.
  assert (Hpi2 : (Rsqr PI < 289 / 25)%R).
  { unfold Rsqr.
    assert (Hp1 : (PI * PI < PI * (17 / 5))%R).
    { apply Rmult_lt_compat_l; [apply PI_RGT_0 | exact Hpi]. }
    assert (Hp2 : (PI * (17 / 5) < 289 / 25)%R).
    { assert (Hq : (PI * (17 / 5) < (17 / 5) * (17 / 5))%R).
      { apply Rmult_lt_compat_r; [lra | exact Hpi]. }
      replace ((17 / 5) * (17 / 5))%R with (289 / 25)%R in Hq by field.
      exact Hq. }
    apply Rlt_trans with (PI * (17 / 5))%R; [exact Hp1 | exact Hp2]. }
  assert (Hgt : (8 * PI / 25 < sqrt (6 / 5))%R).
  { apply Rnot_le_lt.
    intro Hle.
    assert (Hsq : (Rsqr (sqrt (6 / 5)) <= Rsqr (8 * PI / 25))%R).
    { apply Rsqr_incr_1; [exact Hle | apply sqrt_pos | ].
      assert (Hpi0 : (0 < PI)%R) by apply PI_RGT_0.
      assert (Hpos : (0 < 8 * PI / 25)%R).
      { unfold Rdiv. apply Rmult_lt_0_compat; [lra | apply Rinv_0_lt_compat; lra]. }
      apply Rlt_le. exact Hpos. }
    assert (Hs : (Rsqr (sqrt (6 / 5)) = 6 / 5)%R).
    { apply Rsqr_sqrt. lra. }
    rewrite Hs in Hsq.
    assert (Heq : (Rsqr (8 * PI / 25) = 64 * Rsqr PI / 625)%R).
    { unfold Rsqr. field. }
    rewrite Heq in Hsq.
    assert (H750 : (750 <= 64 * Rsqr PI)%R).
    { apply (Rmult_le_compat_r 625) in Hsq; [| lra].
      replace (6 / 5 * 625)%R with 750%R in Hsq by field.
      replace (64 * Rsqr PI / 625 * 625)%R with (64 * Rsqr PI)%R in Hsq by (field; lra).
      exact Hsq. }
    assert (H750lt : (750 > 64 * Rsqr PI)%R).
    { assert (H64 : (64 * Rsqr PI < 64 * (289 / 25))%R).
      { apply Rmult_lt_compat_l; [lra | exact Hpi2]. }
      replace (64 * (289 / 25))%R with (18496 / 25)%R in H64 by field.
      apply Rlt_trans with (18496 / 25)%R; [exact H64 | nra]. }
    lra. }
  assert (H25 : (8 * PI < 25 * sqrt (6 / 5))%R).
  { apply (Rmult_lt_compat_r 25) in Hgt.
    - replace (8 * PI / 25 * 25)%R with (8 * PI)%R in Hgt by (field; lra).
      replace (sqrt (6 / 5) * 25)%R with (25 * sqrt (6 / 5))%R in Hgt by ring.
      exact Hgt.
    - lra. }
  assert (Hcross : (4 / 5 < sqrt (6 / 5) * 5 / (2 * PI))%R).
  { replace (4 / 5)%R with ((8 * PI) / (5 * (2 * PI)))%R
      by (field; apply Rgt_not_eq, PI_RGT_0).
    replace (sqrt (6 / 5) * 5 / (2 * PI))%R with ((25 * sqrt (6 / 5)) / (5 * (2 * PI)))%R.
    - assert (Hden : (0 < 5 * (2 * PI))%R).
      { assert (Hpi0 : (0 < PI)%R) by apply PI_RGT_0. lra. }
      apply Rmult_lt_reg_r with (5 * (2 * PI))%R; [exact Hden |].
      replace ((8 * PI) / (5 * (2 * PI)) * (5 * (2 * PI)))%R with (8 * PI)%R
        by (field; apply Rgt_not_eq, PI_RGT_0).
      replace ((25 * sqrt (6 / 5)) / (5 * (2 * PI)) * (5 * (2 * PI)))%R with (25 * sqrt (6 / 5))%R
        by (field; apply Rgt_not_eq, PI_RGT_0).
      exact H25.
    - field. apply Rgt_not_eq, PI_RGT_0. }
  exact Hcross.
Qed.

(* mu_adj(3/2) < 4/5 : 3/(sqrt 2 * pi) < 4/5  <=>  225 < 32 pi^2, pi > 3 *)
Lemma g2_mu_32_lt : (sqrt (3 / 2) * sin (2 * (PI / 3)) / (PI * (3 / 2 - 1)) < 4 / 5)%R.
Proof.
  rewrite sin_2PI3.
  assert (Heq : (sqrt (3 / 2) * (sqrt 3 / 2) / (PI * (3 / 2 - 1)) = 3 / (sqrt 2 * PI))%R).
  { replace (sqrt (3 / 2) * (sqrt 3 / 2))%R with (sqrt (3 / 2) * sqrt 3 * / 2)%R by (field; lra).
    rewrite g2_sqrt_32_3.
    replace (3 / 2 - 1)%R with (/ 2)%R by field.
    field.
    split; [apply Rgt_not_eq, PI_RGT_0 | apply Rgt_not_eq; apply g2_sqrt_pos; lra]. }
  rewrite Heq.
  assert (Hpi : (3 < PI)%R) by exact g2_pi_gt_3.
  assert (Hpi2 : (3 * 3 < Rsqr PI)%R).
  { unfold Rsqr.
    assert (Hp1 : (3 * 3 < 3 * PI)%R).
    { apply Rmult_lt_compat_l; [lra | exact Hpi]. }
    assert (Hp2 : (3 * PI < PI * PI)%R).
    { apply Rmult_lt_compat_r; [apply PI_RGT_0 | exact Hpi]. }
    apply Rlt_trans with (3 * PI)%R; [exact Hp1 | exact Hp2]. }
  assert (Hsq : (225 < 32 * Rsqr PI)%R).
  { apply Rlt_trans with (32 * (3 * 3))%R.
    - nra.
    - apply Rmult_lt_compat_l; [lra | exact Hpi2]. }
  assert (Hc : (15 < 4 * sqrt 2 * PI)%R).
  { apply Rnot_le_lt.
    intro Hle.
    assert (Hsqle : (Rsqr (4 * sqrt 2 * PI) <= Rsqr 15)%R).
    { apply Rsqr_incr_1; [exact Hle | | ].
      - apply Rmult_le_pos; [apply Rmult_le_pos; [lra | apply sqrt_pos] | apply Rlt_le, PI_RGT_0].
      - lra. }
    replace (Rsqr 15)%R with 225%R in Hsqle by (unfold Rsqr; ring).
    replace (Rsqr (4 * sqrt 2 * PI))%R with (32 * Rsqr PI)%R in Hsqle.
    + lra.
    + rewrite Rsqr_mult. rewrite Rsqr_mult.
      replace (Rsqr (sqrt 2))%R with 2%R by (unfold Rsqr; rewrite (sqrt_sqrt 2 (Rlt_le 0 2 Rlt_0_2)); ring).
      unfold Rsqr. ring. }
  apply Rmult_lt_reg_r with (sqrt 2 * PI)%R; [apply Rmult_lt_0_compat; [apply g2_sqrt_pos; lra | apply PI_RGT_0] |].
  apply Rmult_lt_reg_r with 5%R; [lra |].
  replace ((3 / (sqrt 2 * PI)) * (sqrt 2 * PI) * 5)%R with 15%R
    by (field; split; [apply Rgt_not_eq, PI_RGT_0 | apply Rgt_not_eq; apply g2_sqrt_pos; lra]).
  replace ((4 / 5) * (sqrt 2 * PI) * 5)%R with (4 * sqrt 2 * PI)%R by (field; lra).
  exact Hc.
Qed.

(* sin(PI/(6/5)) = 1/2 *)
Lemma g2_sin_65 : (sin (PI / (6 / 5)) = 1 / 2)%R.
Proof.
  replace (PI / (6 / 5))%R with (5 * (PI / 6))%R by (field; lra).
  replace (5 * (PI / 6))%R with (PI - PI / 6)%R by (field; apply Rgt_not_eq, PI_RGT_0).
  rewrite sin_PI_x.
  rewrite sin_PI6.
  reflexivity.
Qed.

(* sin(PI/(3/2)) = sin(2*(PI/3)) *)
Lemma g2_sin_32 : (sin (PI / (3 / 2)) = sin (2 * (PI / 3)))%R.
Proof.
  replace (PI / (3 / 2))%R with (2 * (PI / 3))%R by (field; lra).
  reflexivity.
Qed.

(* mu_adj(6/5) > 4/5 in mu_adj form *)
Lemma g2_mu_65_gt_mu : (mu_adj (6 / 5) > 4 / 5)%R.
Proof.
  unfold mu_adj.
  rewrite g2_sin_65.
  replace (6 / 5 - 1)%R with (1 / 5)%R by field.
  replace (sqrt (6 / 5) * (1 / 2) / (PI * (1 / 5)))%R with (sqrt (6 / 5) * 5 / (2 * PI))%R.
  - exact g2_mu_65_gt.
  - field. apply Rgt_not_eq, PI_RGT_0.
Qed.

(* mu_adj(3/2) < 4/5 in mu_adj form *)
Lemma g2_mu_32_lt_mu : (mu_adj (3 / 2) < 4 / 5)%R.
Proof.
  unfold mu_adj.
  rewrite g2_sin_32.
  exact g2_mu_32_lt.
Qed.


(* ============ R3. Adjacent-band asymptotic ============ *)

(* Generic: continuity_pt f l + Un_cv An l => Un_cv (f o An) (f l) *)
Lemma g2_Un_cv_cont (f : R -> R) (An : nat -> R) (l : R) :
  continuity_pt f l -> Un_cv An l ->
  Un_cv (fun n => f (An n)) (f l).
Proof.
  intros Hcont Hcv eps Hep.
  unfold Un_cv in Hcv.
  unfold continuity_pt in Hcont.
  unfold continue_in, limit1_in, limit_in in Hcont.
  destruct (Hcont eps Hep) as [alp [Halp Hball]].
  destruct (Hcv alp Halp) as [N HN].
  exists N.
  intros n Hn.
  destruct (Req_dec (An n) l) as [Heq | Hne].
  - rewrite Heq.
    replace (Rdist (f l) (f l)) with 0.
    + exact Hep.
    + symmetry. apply (proj2 (Rdist_refl (f l) (f l))). reflexivity.
  - apply Hball.
    + split.
      * unfold D_x, no_cond. split; [exact I | exact (not_eq_sym Hne)].
      * apply HN. exact Hn.
Qed.

Lemma g2_cont_id (x : R) : continuity_pt id x.
Proof.
  apply derivable_continuous_pt.
  apply derivable_pt_id.
Qed.

Lemma g2_cont_const (a x : R) : continuity_pt (fct_cte a) x.
Proof.
  apply continuity_pt_const.
  unfold constant, fct_cte. intros x1 x2. reflexivity.
Qed.

Lemma g2_cont_pi_over (x : R) : x <> 0 -> continuity_pt (fun t => PI / t) x.
Proof.
  intros Hx.
  change (continuity_pt (mult_real_fct PI (/ id)) x).
  apply continuity_pt_scal.
  apply continuity_pt_inv.
  - apply g2_cont_id.
  - exact Hx.
Qed.

Lemma g2_cont_sin_pi_over (x : R) : x <> 0 -> continuity_pt (fun t => sin (PI / t)) x.
Proof.
  intros Hx.
  change (continuity_pt (comp sin (fun t => PI / t)) x).
  apply continuity_pt_comp.
  - apply g2_cont_pi_over. exact Hx.
  - apply continuity_sin.
Qed.

Lemma g2_cont_mu_adj (r : R) : (1 < r)%R -> continuity_pt mu_adj r.
Proof.
  intros Hr.
  unfold mu_adj.
  change (continuity_pt ((fun t => sqrt t * sin (PI / t)) / (fun t => PI * (t - 1))) r).
  apply continuity_pt_div.
  - apply continuity_pt_mult.
    + apply continuity_pt_sqrt. lra.
    + apply g2_cont_sin_pi_over. lra.
  - change (continuity_pt (mult_real_fct PI (fun t => t - 1)) r).
    apply continuity_pt_scal.
    apply continuity_pt_minus.
    + apply g2_cont_id.
    + apply g2_cont_const.
  - apply Rmult_integral_contrapositive.
    split; [apply Rgt_not_eq, PI_RGT_0 | lra].
Qed.

Theorem mu_adj_phase_transition :
  exists r : R, (1 < r)%R /\ (r < 2)%R /\ (mu_adj r = 4/5)%R.
Proof.
  set (f := fun r => mu_adj r - 4 / 5).
  assert (Hf65 : (f (6 / 5) > 0)%R).
  { unfold f. apply Rgt_minus. exact g2_mu_65_gt_mu. }
  assert (Hf32 : (f (3 / 2) < 0)%R).
  { unfold f. apply Rlt_minus. exact g2_mu_32_lt_mu. }
  set (g := fun r => - (mu_adj r - 4 / 5)).
  assert (Hg65 : (g (6 / 5) < 0)%R).
  { unfold g. unfold f in Hf65. lra. }
  assert (Hg32 : (0 < g (3 / 2))%R).
  { unfold g. unfold f in Hf32. lra. }
  destruct (IVT_interv g (6 / 5) (3 / 2)) as [r Hr_spec].
  - intros a Ha.
    apply continuity_pt_opp.
    apply continuity_pt_plus.
    + apply g2_cont_mu_adj.
      destruct Ha as [Hal Hah].
      lra.
    + apply continuity_pt_const.
      unfold constant. intros x y. reflexivity.
  - lra.
  - exact Hg65.
  - exact Hg32.
  - destruct Hr_spec as [Hrange Hg0].
    exists r. split.
    + destruct Hrange as [Hrl Hrh]. lra.
    + split.
      * destruct Hrange as [Hrl Hrh]. lra.
      * unfold g in Hg0.
        unfold f in *.
        lra.
Qed.

Print Assumptions mu_adj_phase_transition.
Theorem mu_adj_asymptotic (r : R) (n : nat -> nat) :
  (2 <= r)%R ->
  (forall k, (1 < n k)%nat) ->
  (forall k, (n k < n (S k))%nat) ->
  (Un_cv (fun k => INR (n (S k)) / INR (n k)) r) ->
  (Un_cv (fun k => mu_adj (INR (n (S k)) / INR (n k))) (mu_adj r)).
Proof.
  intros Hr Hn1 Hnlt Hlim.
  apply (g2_Un_cv_cont mu_adj (fun k => INR (n (S k)) / INR (n k)) r).
  - apply g2_cont_mu_adj. lra.
  - exact Hlim.
Qed.

End G2MuAdj.


(* ==================== 模块 50/67: probe_pi_cr_m1a ==================== *)

Close Scope R_scope.
Close Scope Z_scope.
(* ============================================================
   M1a：交替级数余项通用引理（纯 CR 基础，π 构造的核心）
   零经典、零 Admitted、零自定义公理
   核心：Leibniz 夹逼 S_N ∈ [S_1, S_0] ⟹ |Σ(-1)^k a_k| ≤ a_0
   ============================================================ *)
From Stdlib Require Import ConstructiveReals.
From Stdlib Require Import ConstructiveRealsMorphisms.
From Stdlib Require Import ConstructiveAbs.
From Stdlib Require Import ConstructiveSum.
From Stdlib Require Import ConstructiveLimits.
From Stdlib Require Import QArith.
From Stdlib Require Import ZArith.
From Stdlib Require Import Lia.
From Stdlib Require Import PeanoNat.
From Stdlib Require Import Ring.

(* 双环境 nat 记号保护（合并版环境 mathcomp 劫持 nat_scope 为 addn/muln/subn/divn，
   lia/Nat 引理不认；独立环境注册 Stdlib 同义记号，仅 notation-overridden warning 无害）。
   放在 Require 之后、任何正文之前；全局注册使依赖本文件的 m1b/m2/m3 同样受保护。 *)
Notation "a + b" := (Nat.add a b) (at level 50, left associativity) : nat_scope.
Notation "a - b" := (Nat.sub a b) (at level 50, left associativity) : nat_scope.
Notation "a * b" := (Nat.mul a b) (at level 40, left associativity) : nat_scope.
Notation "a / b" := (Nat.div a b) (at level 40, left associativity) : nat_scope.
Notation "a <= b" := (Nat.le a b) (at level 70, no associativity) : nat_scope.
Notation "a < b" := (Nat.lt a b) (at level 70, no associativity) : nat_scope.
Notation "a >= b" := (Nat.le b a) (at level 70, no associativity) : nat_scope.
Notation "a > b" := (Nat.lt b a) (at level 70, no associativity) : nat_scope.
Notation "a ^ b" := (Nat.pow a b) (at level 30, right associativity) : nat_scope.

Local Open Scope ConstructiveReals.

Section M1a.

Context {R : ConstructiveReals}.
Add Ring CR_ring : (CRisRing R).

(* 符号：(-1)^k = if odd k then -1 else 1 *)
Definition alt_sign (k : nat) : CRcarrier R :=
  if Nat.odd k then CR_of_Q R (-1 # 1) else CR_of_Q R (1 # 1).

(* 交替部分和 *)
Definition alt_partial (a : nat -> CRcarrier R) (N : nat) : CRcarrier R :=
  CRsum (fun k => alt_sign k * a k) N.

Lemma odd_2N_1 (N : nat) : Nat.odd (2 * N + 1) = true.
Proof.
  induction N as [|N IH].
  - cbn. reflexivity.
  - replace (2 * S N + 1)%nat with (S (S (2 * N + 1)))%nat by lia.
    rewrite Nat.odd_succ_succ.
    exact IH.
Qed.

Lemma even_2N (N : nat) : Nat.odd (2 * N) = false.
Proof.
  apply Nat.odd_even.
Qed.

Lemma odd_2N_plus2 (N : nat) : Nat.odd (2 * N + 2) = false.
Proof.
  replace (2 * N + 2)%nat with (S (S (2 * N)))%nat by lia.
  rewrite Nat.odd_succ_succ. apply even_2N.
Qed.

Lemma alt_sign_even_plus2 (N : nat) :
  CReq R (alt_sign (2 * N + 2)) (CR_of_Q R (1 # 1)).
Proof.
  unfold alt_sign. rewrite (odd_2N_plus2 N). cbn. apply CReq_refl.
Qed.

Lemma odd_2N_plus3 (N : nat) : Nat.odd (2 * N + 3) = true.
Proof.
  replace (2 * N + 3)%nat with (S (S (2 * N + 1)))%nat by lia.
  rewrite Nat.odd_succ_succ.
  replace (2 * N + 1)%nat with (S (2 * N))%nat by lia.
  rewrite Nat.odd_succ. apply Nat.even_spec. exists N. lia.
Qed.

Lemma alt_sign_odd_plus3 (N : nat) :
  CReq R (alt_sign (2 * N + 3)) (CR_of_Q R (-1 # 1)).
Proof.
  unfold alt_sign. rewrite (odd_2N_plus3 N). cbn. apply CReq_refl.
Qed.

Lemma alt_sign_odd (N : nat) :
  CReq R (alt_sign (2 * N + 1)) (CR_of_Q R (-1 # 1)).
Proof.
  unfold alt_sign. rewrite (odd_2N_1 N). cbn. apply CReq_refl.
Qed.

Lemma alt_sign_even (N : nat) :
  CReq R (alt_sign (2 * N)) (CR_of_Q R (1 # 1)).
Proof.
  unfold alt_sign. rewrite (even_2N N). cbn. apply CReq_refl.
Qed.

Lemma alt_partial_S (a : nat -> CRcarrier R) (N : nat) :
  CReq R (alt_partial a (S N))
    (alt_partial a N + alt_sign (S N) * a (S N)).
Proof.
  unfold alt_partial. cbn [CRsum]. apply CReq_refl.
Qed.

(* 工具：0 ≤ a1 - a2 ⟸ a2 ≤ a1 *)
Lemma zero_le_minus (a1 a2 : CRcarrier R) :
  CRle R a2 a1 -> CRle R 0 (a1 - a2).
Proof.
  intros H.
  apply (CRle_minus a2 a1). exact H.
Qed.

(* 工具：0 ≤ a ⟹ (-1)·a ≤ 0 *)
Lemma neg_le_0_of_nonneg (a : CRcarrier R) :
  CRle R (CR_of_Q R (0 # 1)) a ->
  CRle R (CR_of_Q R (-1 # 1) * a) (CR_of_Q R (0 # 1)).
Proof.
  intros Ha.
  apply (CRmult_le0 (CR_of_Q R (-1 # 1)) a).
  - apply (CRlt_asym (CR_of_Q R (-1 # 1)) (CR_of_Q R (0 # 1))).
    apply CR_of_Q_lt. unfold Qlt. simpl. lia.
  - exact Ha.
Qed.

(* 奇 ≤ 偶：S_{2m+1} ≤ S_{2m} *)
Lemma alt_odd_le_even (a : nat -> CRcarrier R) (m : nat) :
  (forall k, 0 <= a k) ->
  CRle R (alt_partial a (2 * m + 1)) (alt_partial a (2 * m)).
Proof.
  intros Ha.
  replace (2 * m + 1)%nat with (S (2 * m))%nat by lia.
  rewrite (alt_partial_S a (2 * m)).
  replace (S (2 * m))%nat with (2 * m + 1)%nat by lia.
  rewrite (alt_sign_odd m).
  (* 目标: alt_partial + (-1)·a ≤ alt_partial，即 (-1)·a ≤ 0
     （setoid_rewrite at 兼容标准/ssreflect 双环境；rewrite ... at 在 ssreflect 下语法非法） *)
  setoid_rewrite <- (CRplus_0_r (alt_partial a (2 * m))) at 2.
  apply (CRplus_le_compat_l (alt_partial a (2 * m))).
  apply (neg_le_0_of_nonneg (a (2 * m + 1)%nat)). apply Ha.
Qed.

(* 工具：a2 - a1 ≤ 0 ⟸ a2 ≤ a1 *)
Lemma minus_le_0 (a1 a2 : CRcarrier R) :
  CRle R a2 a1 -> CRle R (a2 - a1) 0.
Proof.
  intros H.
  apply (CRplus_le_reg_r a1).
  setoid_rewrite (CRplus_assoc a2 (- a1) a1).
  rewrite (CRplus_opp_l a1).
  ring_simplify.
  exact H.
Qed.

(* 工具：x ≤ 0 ⟹ S + x ≤ S *)
Lemma plus_le_0 (S x : CRcarrier R) :
  CRle R x (CR_of_Q R (0 # 1)) -> CRle R (S + x) S.
Proof.
  intros H.
  apply (proj2 (CRle_morph R (S + x) (S + x) (CReq_refl _)
                S (S + CR_of_Q R (0 # 1)) (CReq_sym (S + CR_of_Q R (0 # 1)) S ltac:(ring)))).
  apply (CRplus_le_compat_l S). exact H.
Qed.

(* 工具：0 ≤ t ⟹ x ≤ x + t *)
Lemma x_le_x_plus (x t : CRcarrier R) :
  CRle R (CR_of_Q R (0 # 1)) t -> CRle R x (x + t).
Proof.
  intros H.
  apply (CRle_morph R (x + CR_of_Q R (0 # 1)) x ltac:(ring)
                    (x + t) (x + t) (CReq_refl _)).
  apply (CRplus_le_compat_l x). exact H.
Qed.

(* 工具：((S+x)+y)+z == S+(x+(y+z)) *)
Lemma assoc3 (S x y z : CRcarrier R) :
  CReq R (((S + x) + y) + z) (S + (x + (y + z))).
Proof.
  setoid_rewrite (CRplus_assoc (S + x) y z).
  setoid_rewrite (CRplus_assoc S x (y + z)).
  apply CReq_refl.
Qed.

(* 展开 S_{2m+2} = S_{2m} + s_{2m+1}a_{2m+1} + s_{2m+2}a_{2m+2} *)
Lemma alt_partial_2m_plus2 (a : nat -> CRcarrier R) (m : nat) :
  CReq R (alt_partial a (2 * m + 2)%nat)
    (alt_partial a (2 * m)%nat + alt_sign (2 * m + 1)%nat * a (2 * m + 1)%nat + alt_sign (2 * m + 2)%nat * a (2 * m + 2)%nat).
Proof.
  replace (2 * m + 2)%nat with (S (2 * m + 1))%nat by lia.
  rewrite (alt_partial_S a (2 * m + 1)).
  replace (2 * m + 1)%nat with (S (2 * m))%nat by lia.
  rewrite (alt_partial_S a (2 * m)).
  apply CReq_refl.
Qed.

(* 偶部分和递减：S_{2m+2} ≤ S_{2m} *)
Lemma alt_even_decr (a : nat -> CRcarrier R) (m : nat) :
  (forall k, a (S k) <= a k) ->
  CRle R (alt_partial a (2 * (S m))) (alt_partial a (2 * m)).
Proof.
  intros Hdecr.
  replace (2 * (S m))%nat with (2 * m + 2)%nat by lia.
  rewrite (alt_partial_2m_plus2 a m).
  (* 符号：s_{2m+1} = -1, s_{2m+2} = 1 *)
  replace (alt_sign (2 * m + 1)%nat) with (CR_of_Q R (-1 # 1)) by
    (unfold alt_sign; rewrite (odd_2N_1 m); reflexivity).
  replace (alt_sign (2 * m + 2)%nat) with (CR_of_Q R (1 # 1)) by
    (unfold alt_sign; rewrite (odd_2N_plus2 m); reflexivity).
  (* 目标: (S + (-1)a1) + 1a2 ≤ S ⟺ (-1)a1 + 1a2 ≤ 0 ⟺ a2 - a1 ≤ 0 *)
  apply (proj2 (CRle_morph R
           ((alt_partial a (2 * m)%nat + CR_of_Q R (-1 # 1) * a (2 * m + 1)%nat) + CR_of_Q R (1 # 1) * a (2 * m + 2)%nat)
           (alt_partial a (2 * m)%nat + (CR_of_Q R (-1 # 1) * a (2 * m + 1)%nat + CR_of_Q R (1 # 1) * a (2 * m + 2)%nat))
           (CRplus_assoc (alt_partial a (2 * m)%nat) (CR_of_Q R (-1 # 1) * a (2 * m + 1)%nat) (CR_of_Q R (1 # 1) * a (2 * m + 2)%nat))
           (alt_partial a (2 * m)%nat) (alt_partial a (2 * m)%nat) (CReq_refl _))).
  apply (plus_le_0 (alt_partial a (2 * m)%nat)
                   (CR_of_Q R (-1 # 1) * a (2 * m + 1)%nat + CR_of_Q R (1 # 1) * a (2 * m + 2)%nat)).
  (* 目标: (-1)a1 + 1a2 ≤ 0；改写成 a2 - a1 ≤ 0 *)
  apply (proj2 (CRle_morph R
           (CR_of_Q R (-1 # 1) * a (2 * m + 1)%nat + CR_of_Q R (1 # 1) * a (2 * m + 2)%nat)
           (a (2 * m + 2)%nat - a (2 * m + 1)%nat)
           ltac:(rewrite (CR_of_Q_opp (1 # 1)); unfold CRminus; ring)
           (CR_of_Q R (0 # 1)) (CR_of_Q R (0 # 1)) (CReq_refl _))).
  apply (minus_le_0 (a (2 * m + 1)%nat) (a (2 * m + 2)%nat)).
  replace (2 * m + 2)%nat with (S (2 * m + 1))%nat by lia.
  apply Hdecr.
Qed.

(* 奇部分和递增：S_{2m+1} ≤ S_{2m+3} *)
Lemma alt_odd_incr (a : nat -> CRcarrier R) (m : nat) :
  (forall k, a (S k) <= a k) ->
  CRle R (alt_partial a (2 * m + 1)) (alt_partial a (2 * (S m) + 1)).
Proof.
  intros Hdecr.
  (* RHS: 2m+3 = S(2m+2)，先展开一层 *)
  replace (2 * (S m) + 1)%nat with (S (2 * m + 2))%nat by lia.
  rewrite (alt_partial_S a (2 * m + 2)).
  replace (S (2 * m + 2))%nat with (2 * m + 3)%nat by lia.
  rewrite (alt_partial_2m_plus2 a m).
  (* LHS: 2m+1 = S(2m) *)
  replace (2 * m + 1)%nat with (S (2 * m))%nat by lia.
  rewrite (alt_partial_S a (2 * m)).
  replace (S (2 * m))%nat with (2 * m + 1)%nat by lia.
  (* 符号：s1 = -1, s2 = 1, s3 = -1 *)
  rewrite (alt_sign_odd m).
  rewrite (alt_sign_even_plus2 m).
  rewrite (alt_sign_odd_plus3 m).
  (* 目标：S + s1a1 ≤ (S + s1a1) + 1a2 + (-1)a3 *)
  (* 右侧结合：RHS == S+s1a1 + (1a2 + (-1)a3) *)
  apply (proj1 (CRle_morph R
           (alt_partial a (2 * m)%nat + CR_of_Q R (-1 # 1) * a (2 * m + 1)%nat)
           (alt_partial a (2 * m)%nat + CR_of_Q R (-1 # 1) * a (2 * m + 1)%nat) (CReq_refl _)
           (alt_partial a (2 * m)%nat + CR_of_Q R (-1 # 1) * a (2 * m + 1)%nat + (CR_of_Q R (1 # 1) * a (2 * m + 2)%nat + CR_of_Q R (-1 # 1) * a (2 * m + 3)%nat))
           (alt_partial a (2 * m)%nat + CR_of_Q R (-1 # 1) * a (2 * m + 1)%nat + CR_of_Q R (1 # 1) * a (2 * m + 2)%nat + CR_of_Q R (-1 # 1) * a (2 * m + 3)%nat)
           (CReq_sym _ _ (CRplus_assoc (alt_partial a (2 * m)%nat + CR_of_Q R (-1 # 1) * a (2 * m + 1)%nat) (CR_of_Q R (1 # 1) * a (2 * m + 2)%nat) (CR_of_Q R (-1 # 1) * a (2 * m + 3)%nat))))).
  apply (x_le_x_plus (alt_partial a (2 * m)%nat + CR_of_Q R (-1 # 1) * a (2 * m + 1)%nat)
                     (CR_of_Q R (1 # 1) * a (2 * m + 2)%nat + CR_of_Q R (-1 # 1) * a (2 * m + 3)%nat)).
  (* 目标：0 ≤ 1a2 + (-1)a3 = a2 - a3 *)
  apply (CRle_morph R (CR_of_Q R (0 # 1)) (CR_of_Q R (0 # 1)) (CReq_refl _)
                    (CR_of_Q R (1 # 1) * a (2 * m + 2)%nat + CR_of_Q R (-1 # 1) * a (2 * m + 3)%nat)
                    (a (2 * m + 2)%nat - a (2 * m + 3)%nat)
                    ltac:(rewrite (CR_of_Q_opp (1 # 1)); unfold CRminus; ring)).
  apply (zero_le_minus (a (2 * m + 2)%nat) (a (2 * m + 3)%nat)).
  replace (2 * m + 3)%nat with (S (2 * m + 2))%nat by lia.
  apply Hdecr.
Qed.
(* S_{2m} ≤ S_0（偶递减链） *)
Lemma alt_even_le_0 (a : nat -> CRcarrier R) (m : nat) :
  (forall k, a (S k) <= a k) ->
  CRle R (alt_partial a (2 * m)) (alt_partial a 0).
Proof.
  intros Hdecr.
  induction m as [|m IH].
  - apply CRle_refl.
  - apply (CRle_trans _ (alt_partial a (2 * m)) _).
    + apply alt_even_decr. exact Hdecr.
    + exact IH.
Qed.

(* S_1 ≤ S_{2m+1}（奇递增链） *)
Lemma alt_odd_ge_1 (a : nat -> CRcarrier R) (m : nat) :
  (forall k, a (S k) <= a k) ->
  CRle R (alt_partial a 1) (alt_partial a (2 * m + 1)).
Proof.
  intros Hdecr.
  induction m as [|m IH].
  - apply CRle_refl.
  - apply (CRle_trans _ (alt_partial a (2 * m + 1)) _).
    + exact IH.
    + apply alt_odd_incr. exact Hdecr.
Qed.

(* 上界：S_M ≤ S_0（对任意 M） *)
Lemma alt_partial_le_0 (a : nat -> CRcarrier R) (M : nat) :
  (forall k, 0 <= a k) ->
  (forall k, a (S k) <= a k) ->
  CRle R (alt_partial a M) (alt_partial a 0).
Proof.
  intros Ha Hdecr.
  destruct (Nat.eqb (M mod 2)%nat 0%nat) eqn:Hm.
  - (* M 偶：M = 2m *)
    assert (Hm0 : (M mod 2)%nat = 0%nat) by (apply (Nat.eqb_eq (M mod 2)%nat 0%nat); exact Hm).
    assert (Hm' : exists m : nat, M = (2 * m)%nat).
    { assert (Hq : M = (2 * (M / 2) + (M mod 2))%nat) by (apply (Nat.div_mod M 2); lia).
      exists (M / 2)%nat. setoid_rewrite Hq at 1. rewrite Hm0. apply Nat.add_0_r. }
    destruct Hm' as [m Hm']. subst M.
    apply alt_even_le_0. exact Hdecr.
  - (* M 奇：M = 2m+1 *)
    assert (Hm1 : (M mod 2)%nat = 1%nat).    { assert (Hne : (M mod 2)%nat <> 0%nat) by (apply (proj1 (Nat.eqb_neq (M mod 2)%nat 0%nat)); exact Hm).
      pose proof (Nat.mod_upper_bound M 2) as Hlt.
      assert (Hnz : 2%nat <> 0%nat) by lia.
      specialize (Hlt Hnz).
      destruct (M mod 2)%nat as [|[|n]]; simpl in *.
      - exfalso. apply Hne. reflexivity.
      - reflexivity.
      - exfalso. lia. }
    assert (Hm' : exists m : nat, M = (2 * m + 1)%nat).
    { assert (Hq : M = (2 * (M / 2) + (M mod 2))%nat) by (apply (Nat.div_mod M 2); lia).
      exists (M / 2)%nat. setoid_rewrite Hq at 1. rewrite Hm1. simpl. lia. }
    destruct Hm' as [m Hm']. subst M.
    (* S_{2m+1} ≤ S_{2m} ≤ S_0 *)
    apply (CRle_trans _ (alt_partial a (2 * m)) _).
    + apply alt_odd_le_even. exact Ha.
    + apply alt_even_le_0. exact Hdecr.
Qed.

(* 下界：S_1 ≤ S_M（对任意 M） *)
Lemma alt_partial_ge_1 (a : nat -> CRcarrier R) (M : nat) :
  (forall k, 0 <= a k) ->
  (forall k, a (S k) <= a k) ->
  CRle R (alt_partial a 1) (alt_partial a M).
Proof.
  intros Ha Hdecr.
  destruct (Nat.eqb (M mod 2)%nat 0%nat) eqn:Hm.
  - (* M 偶 = 2m：S_1 ≤ S_{2m+1} ≤ S_{2m} *)
    assert (Hm0 : (M mod 2)%nat = 0%nat) by (apply (Nat.eqb_eq (M mod 2)%nat 0%nat); exact Hm).
    assert (Hm' : exists m : nat, M = (2 * m)%nat).
    { assert (Hq : M = (2 * (M / 2) + (M mod 2))%nat) by (apply (Nat.div_mod M 2); lia).
      exists (M / 2)%nat. setoid_rewrite Hq at 1. rewrite Hm0. apply Nat.add_0_r. }
    destruct Hm' as [m Hm']. subst M.
    apply (CRle_trans _ (alt_partial a (2 * m + 1)) _).
    + apply alt_odd_ge_1. exact Hdecr.
    + apply alt_odd_le_even. exact Ha.
  - (* M 奇 = 2m+1 *)
    assert (Hm1 : (M mod 2)%nat = 1%nat).
    { assert (Hne : (M mod 2)%nat <> 0%nat) by (apply (proj1 (Nat.eqb_neq (M mod 2)%nat 0%nat)); exact Hm).
      pose proof (Nat.mod_upper_bound M 2) as Hlt.
      assert (Hnz : 2%nat <> 0%nat) by lia.
      specialize (Hlt Hnz).
      destruct (M mod 2)%nat as [|[|n]]; simpl in *.
      - exfalso. apply Hne. reflexivity.
      - reflexivity.
      - exfalso. lia. }
    assert (Hm' : exists m : nat, M = (2 * m + 1)%nat).
    { assert (Hq : M = (2 * (M / 2) + (M mod 2))%nat) by (apply (Nat.div_mod M 2); lia).
      exists (M / 2)%nat. setoid_rewrite Hq at 1. rewrite Hm1. simpl. lia. }
    destruct Hm' as [m Hm']. subst M.
    apply alt_odd_ge_1. exact Hdecr.
Qed.

(* S_1 ≥ 0（a 递减 ⟹ a_1 ≤ a_0 ⟹ a_0 - a_1 ≥ 0） *)
Lemma alt_s1_ge_0 (a : nat -> CRcarrier R) :
  (forall k, a (S k) <= a k) ->
  CRle R (CR_of_Q R (0 # 1)) (alt_partial a 1).
Proof.
  intros Hdecr.
  (* S_1 = a_0 - a_1 *)
  unfold alt_partial. cbn [CRsum].
  unfold alt_sign. cbn.
  (* 目标: 0 ≤ 1*a0 + (-1)*a1，改写成 0 ≤ a0 - a1 *)
  apply (CRle_morph R (CR_of_Q R (0 # 1)) (CR_of_Q R (0 # 1)) (CReq_refl _)
                    (CR_of_Q R (1 # 1) * a 0%nat + CR_of_Q R (-1 # 1) * a 1%nat)
                    (a 0%nat - a 1%nat)
                    ltac:(rewrite (CR_of_Q_opp (1 # 1)); unfold CRminus; ring)).
  apply (zero_le_minus (a 0%nat) (a 1%nat)). apply Hdecr.
Qed.

(* 核心：|S_M| ≤ a_0 *)
Lemma alt_series_remainder (a : nat -> CRcarrier R) (M : nat) :
  (forall k, 0 <= a k) ->
  (forall k, a (S k) <= a k) ->
  CRle R (CRabs R (alt_partial a M)) (a 0%nat).
Proof.
  intros Ha Hdecr.
  (* |S_M| ≤ a_0 ⟺ S_M ≤ a_0 ∧ -S_M ≤ a_0 *)
  apply (proj1 (CRabs_def R (alt_partial a M) (a 0%nat))).
  split.
  - (* S_M ≤ a_0 = S_0 *)
    apply (CRle_trans _ (alt_partial a 0) _).
    + apply alt_partial_le_0. exact Ha. exact Hdecr.
    + (* S_0 = a_0 *)
      unfold alt_partial. cbn [CRsum].
      unfold alt_sign. cbn. ring_simplify.
      apply CRle_refl.
  - (* -S_M ≤ a_0：S_M ≥ 0 ⟹ -S_M ≤ 0 ≤ a_0 *)
    apply (CRle_trans _ (CR_of_Q R (0 # 1)) _).
    + (* -S_M ≤ 0：由 0 ≤ S_M *)
      apply (CRle_morph R
               (CR_of_Q R (-1 # 1) * alt_partial a M)
               (- alt_partial a M)
               ltac:(rewrite (CR_of_Q_opp (1 # 1)); ring)
               (CR_of_Q R (0 # 1)) (CR_of_Q R (0 # 1)) (CReq_refl _)).
      apply (neg_le_0_of_nonneg (alt_partial a M)).
      (* 0 ≤ S_M：S_1 ≤ S_M 且 0 ≤ S_1 *)
      apply (CRle_trans _ (alt_partial a 1) _).
      * apply alt_s1_ge_0. exact Hdecr.
      * apply alt_partial_ge_1. exact Ha. exact Hdecr.
    + (* 0 ≤ a_0 *)
      apply Ha.
Qed.

End M1a.

(* ==================== 模块 51/67: probe_pi_cr_m1b ==================== *)

Close Scope R_scope.
Close Scope Z_scope.
(* ============================================================
   M1b CRpi（构造性 π）：交替级数取极限 + 有理界
   零经典、零 Admitted、零自定义公理
   复用 M1a：alt_partial/alt_sign/alt_a/alt_series_remainder
   核心：tail_partial 平移余项 → |S_j - S_i| ≤ a_{min+1} → Cauchy → CR_complete → π
   ============================================================ *)
From Stdlib Require Import ConstructiveReals.
From Stdlib Require Import ConstructiveRealsMorphisms.
From Stdlib Require Import ConstructiveAbs.
From Stdlib Require Import ConstructiveSum.
From Stdlib Require Import ConstructiveLimits.
From Stdlib Require Import QArith.
From Stdlib Require Import ZArith.
From Stdlib Require Import Lia.
From Stdlib Require Import PeanoNat.
From Stdlib Require Import Ring.

Local Open Scope ConstructiveReals.

Section M1b.

Context {R : ConstructiveReals}.
Add Ring CR_ring : (CRisRing R).

(* 交替级数项：1/(2k+1) *)
Definition alt_a (k : nat) : CRcarrier R :=
  CR_of_Q R (Qmake 1 (Pos.of_nat (2 * k + 1))).

Lemma alt_a_nonneg (k : nat) : 0 <= alt_a k.
Proof.
  unfold alt_a. apply (CRlt_asym (CR_of_Q R (0 # 1)) (alt_a k)).
  apply CR_of_Q_lt. unfold Qlt. simpl. lia.
Qed.

Lemma alt_a_S_lt (k : nat) : alt_a (S k) < alt_a k.
Proof.
  unfold alt_a.
  apply CR_of_Q_lt.
  change (Qmake 1 (Pos.of_nat (2 * S k + 1)) < Qmake 1 (Pos.of_nat (2 * k + 1)))%Q.
  unfold Qlt. simpl.
  change (Pos.of_nat (2 * k + 1) < Pos.of_nat (2 * S k + 1))%positive.
  apply Pos2Nat.inj_lt. lia.
Qed.

(* alt_sign 加法分裂：s(a+b) = s(a)·s(b) *)
Lemma alt_sign_add (a b : nat) :
  CReq R (alt_sign (a + b)) (alt_sign a * alt_sign b).
Proof.
  unfold alt_sign.
  rewrite (Nat.odd_add).
  destruct (Nat.odd a) eqn:Ha; destruct (Nat.odd b) eqn:Hb; cbn;
  try (rewrite (CR_of_Q_opp (1#1))); try (setoid_rewrite (CR_of_Q_opp (1#1)) at 2);
  ring.
Qed.

(* |1| ≤ 1 与 |-1| ≤ 1 *)
Lemma abs_one_le : CRle R (CRabs R (CR_of_Q R (1 # 1))) (CR_of_Q R (1 # 1)).
Proof.
  apply (proj1 (CRabs_def R (CR_of_Q R (1 # 1)) (CR_of_Q R (1 # 1)))).
  split.
  - apply CRle_refl.
  - apply (CRle_morph R (- (CR_of_Q R (1 # 1))) (CR_of_Q R (-1 # 1))
            ltac:(rewrite (CR_of_Q_opp (1#1)); ring)
            (CR_of_Q R (1 # 1)) (CR_of_Q R (1 # 1)) (CReq_refl _)).
    apply (CRlt_asym (CR_of_Q R (-1 # 1)) (CR_of_Q R (1 # 1))).
    apply CR_of_Q_lt. unfold Qlt. simpl. lia.
Qed.

Lemma abs_minus_one_le : CRle R (CRabs R (CR_of_Q R (-1 # 1))) (CR_of_Q R (1 # 1)).
Proof.
  apply (proj1 (CRabs_def R (CR_of_Q R (-1 # 1)) (CR_of_Q R (1 # 1)))).
  split.
  - apply (CRlt_asym (CR_of_Q R (-1 # 1)) (CR_of_Q R (1 # 1))).
    apply CR_of_Q_lt. unfold Qlt. simpl. lia.
  - apply (CRle_morph R (- (CR_of_Q R (-1 # 1))) (CR_of_Q R (1 # 1))
            ltac:(rewrite (CR_of_Q_opp (1#1)); ring)
            (CR_of_Q R (1 # 1)) (CR_of_Q R (1 # 1)) (CReq_refl _)).
    apply CRle_refl.
Qed.

(* CRsum 单步差：CRsum f (S i) - CRsum f i = f (S i) *)
Lemma CRsum_diff_dS0 (f : nat -> CRcarrier R) (i : nat) :
  CReq R (CRsum f (S i) - CRsum f i) (f (S i)).
Proof.
  cbn [CRsum].
  set (A := CRsum f i). set (b := f (S i)).
  transitivity (A + (b + (- A))).
  - setoid_rewrite (CRplus_assoc A b (CRopp R A)). apply CReq_refl.
  - transitivity (A + ((- A) + b)).
    + rewrite (CRplus_comm b (CRopp R A)). apply CReq_refl.
    + transitivity ((A + (- A)) + b).
      * apply CReq_sym. setoid_rewrite (CRplus_assoc A (CRopp R A) b). apply CReq_refl.
      * rewrite (CRplus_opp_r A). rewrite (CRplus_0_l b). apply CReq_refl.
Qed.

(* 平移部分和：从 N+1 起 M 项的交替和 Σ_{k=0}^{M} (-1)^{N+1+k} a_{N+1+k} *)
Definition tail_partial (N M : nat) : CRcarrier R :=
  CRsum (fun k => alt_sign (N + 1 + k) * alt_a (N + 1 + k)) M.

(* 公因子提取：Σ (c·g k) == c·Σ g k *)
Lemma CRsum_scale (g : nat -> CRcarrier R) (c : CRcarrier R) (M : nat) :
  CReq R (CRsum (fun k => c * g k) M) (c * CRsum g M).
Proof.
  induction M.
  - reflexivity.
  - cbn [CRsum]. rewrite IHM. ring.
Qed.

(* 平移部分和的符号分裂：tail = s_{N+1} · Σ s_k·a_{N+1+k} *)
Lemma tail_sign_split (N M : nat) :
  CReq R (tail_partial N M)
         (alt_sign (N + 1) * CRsum (fun k => alt_sign k * alt_a (N + 1 + k)) M).
Proof.
  unfold tail_partial.
  (* ① Σ s_{N+1+k}·a == Σ (s_{N+1}·s_k)·a：逐点用 alt_sign_add *)
  transitivity (CRsum (fun k => (alt_sign (N + 1) * alt_sign k) * alt_a (N + 1 + k)) M).
  - apply (CRsum_eq _ _ _ (fun k Hk =>
      CRmult_morph R (alt_sign (N + 1 + k)) (alt_sign (N + 1) * alt_sign k) (alt_sign_add (N + 1) k)
                    (alt_a (N + 1 + k)) (alt_a (N + 1 + k)) (CReq_refl _))).
  - (* ② Σ (s_{N+1}·s_k)·a == s_{N+1}·Σ s_k·a：结合 + 公因子 *)
    transitivity (CRsum (fun k => alt_sign (N + 1) * (alt_sign k * alt_a (N + 1 + k))) M).
    + apply (CRsum_eq _ _ _ (fun k Hk =>
        CRmult_assoc (alt_sign (N + 1)) (alt_sign k) (alt_a (N + 1 + k)))).
    + apply (CRsum_scale (fun k => alt_sign k * alt_a (N + 1 + k)) (alt_sign (N + 1)) M).
Qed.

(* N+1+0 == N+1 的 CR 层辅助 *)
Lemma alt_a_0_plus (N : nat) : CReq R (alt_a (N + 1 + 0)) (alt_a (N + 1)).
Proof.
  assert (Hnat : (N + 1 + 0)%nat = (N + 1)%nat) by lia.
  unfold alt_a. rewrite Hnat. apply CReq_refl.
Qed.

(* 核心：|tail_partial N M| ≤ a_{N+1} *)
Lemma tail_partial_bound (N M : nat) :
  CRle R (CRabs R (tail_partial N M)) (alt_a (N + 1)).
Proof.
  (* |tail| = |s_{N+1}|·|Σ s_k a_{N+1+k}| = 1·|alt_partial 平移| ≤ a_{N+1} *)
  rewrite (tail_sign_split N M).
  (* |c·x| = |c|·|x| *)
  rewrite (CRabs_mult (alt_sign (N + 1)) _).
  (* |s_{N+1}| ≤ 1：s 是 ±1 *)
  (* 目标: |s|·|Σ| ≤ a_{N+1}；|s| ≤ 1 且 |Σ| ≤ a_{N+1} *)
  (* 用 CRmult_le_compat：|s| ≤ 1，0 ≤ |Σ|，|Σ| ≤ a_{N+1} *)
  apply (CRle_trans _ (CR_of_Q R (1 # 1) * CRabs R (CRsum (fun k => alt_sign k * alt_a (N + 1 + k)) M)) _).
  - (* |s|·|Σ| ≤ 1·|Σ| *)
    apply (CRmult_le_compat_r (CRabs R (CRsum (fun k => alt_sign k * alt_a (N + 1 + k)) M))).
    + (* 0 ≤ |Σ|：CRabs_pos *)
      apply (CRabs_pos (CRsum (fun k => alt_sign k * alt_a (N + 1 + k)) M)).
    + (* |s_{N+1}| ≤ 1 *)
      destruct (Nat.odd (N + 1)) eqn:Hodd.
      * unfold alt_sign. rewrite Hodd. apply abs_minus_one_le.
      * unfold alt_sign. rewrite Hodd. apply abs_one_le.
  - (* 1·|Σ| ≤ a_{N+1}；|Σ| ≤ a_{N+1} 由 alt_series_remainder 于平移序列 *)
    rewrite (CRmult_1_l (CRabs R (CRsum (fun k => alt_sign k * alt_a (N + 1 + k)) M))).
    (* Σ s_k·a_{N+1+k} = alt_partial (fun k => alt_a (N+1+k)) M *)
    apply (CRle_trans _ (alt_a (N + 1)) _).
    + (* |alt_partial 平移| ≤ a_{N+1} *)
      change (CRle R (CRabs R (alt_partial (fun k => alt_a (N + 1 + k)) M)) (alt_a (N + 1))).
      (* alt_series_remainder 结论 ≤ b 0 = alt_a (N+1+0)；用 alt_a_0_plus 桥接 *)
      apply (CRle_trans _ (alt_a (N + 1 + 0)) _).
      * apply (alt_series_remainder (fun k => alt_a (N + 1 + k)) M).
        -- intros k. apply alt_a_nonneg.
        -- intros k. apply (CRlt_asym (alt_a (N + 1 + S k)) (alt_a (N + 1 + k))).
           replace (N + 1 + S k)%nat with (S (N + 1 + k))%nat by lia.
           apply alt_a_S_lt.
      * apply (proj2 (alt_a_0_plus N)).
    + apply CRle_refl.
Qed.

(* CRsum 单步差：CRsum f (S i) - CRsum f i = f (S i)（已在上面定义） *)

(* 差的可加性：a - c = (a - b) + (b - c) *)
Lemma CRminus_trans (a b c : CRcarrier R) :
  CReq R (a - c) ((a - b) + (b - c)).
Proof. unfold CRminus. ring. Qed.

(* 核心恒等式：S_{N+1+M} - S_N == tail_partial N M *)
Lemma S_tail_eq (N M : nat) :
  CReq R (alt_partial alt_a (N + 1 + M) - alt_partial alt_a N)
         (tail_partial N M).
Proof.
  induction M as [|M IHM].
  - (* 基例 M=0：S_{N+1} - S_N == s_{N+1}a_{N+1} *)
    unfold tail_partial. unfold alt_partial.
    replace (N + 1 + 0)%nat with (S N) by lia.
    cbn [CRsum].
    replace (N + 1 + 0)%nat with (S N) by lia.
    set (A := CRsum (fun k : nat => alt_sign k * alt_a k) N).
    set (b := alt_sign (S N) * alt_a (S N)).
    unfold CRminus.
    transitivity (A + (b + (- A))).
    + setoid_rewrite (CRplus_assoc A b (- A)). apply CReq_refl.
    + transitivity (A + ((- A) + b)).
      * rewrite (CRplus_comm b (- A)). apply CReq_refl.
      * transitivity ((A + (- A)) + b).
        -- apply CReq_sym. setoid_rewrite (CRplus_assoc A (- A) b). apply CReq_refl.
        -- rewrite (CRplus_opp_r A). rewrite (CRplus_0_l b). apply CReq_refl.
  - (* 归纳步：S_{N+1+(M+1)} - S_N == tail N (M+1) *)
    (* 拆：S_{S(N+1+M)} - S_N = (S_{S(N+1+M)} - S_{N+1+M}) + (S_{N+1+M} - S_N)
       = s_{N+1+M+1} a_{N+1+M+1} + tail N M（CRsum_diff_dS0 + IHM） *)
    replace (N + 1 + S M)%nat with (S (N + 1 + M))%nat by lia.
    rewrite (CRminus_trans (alt_partial alt_a (S (N + 1 + M))) (alt_partial alt_a (N + 1 + M)) (alt_partial alt_a N)).
    (* 先对第二项用 IHM（保持 alt_partial 形式未展开时替换） *)
    setoid_rewrite IHM.
    (* 再展开 alt_partial 使第一项可套 CRsum_diff_dS0 *)
    unfold alt_partial.
    setoid_rewrite (CRsum_diff_dS0 (fun k => alt_sign k * alt_a k) (N + 1 + M)).
    (* RHS: tail N (S M) = tail N M + s_{N+1+S M} a_{N+1+S M}（tail_partial 定义展开） *)
    unfold tail_partial.
    cbn [CRsum].
    (* 索引统一：S(N+1+M) == N+1+S M *)
    replace (N + 1 + S M)%nat with (S (N + 1 + M))%nat by lia.
    (* 交换左侧顺序 *)
    rewrite (CRplus_comm (alt_sign (S (N + 1 + M)) * alt_a (S (N + 1 + M))) _).
    apply CReq_refl.
Qed.

(* ============ π/4 极限与有理界 ============ *)

(* 下降：k ≤ m ⟹ alt_a m ≤ alt_a k *)
Lemma alt_a_decr (k m : nat) : (k <= m)%nat -> CRle R (alt_a m) (alt_a k).
Proof.
  intros H. induction m as [|m IHm].
  - destruct (Nat.eq_dec k 0); subst; [apply CRle_refl | lia].
  - destruct (Nat.lt_ge_cases k (S m)) as [Hlt|Hge].
    + apply (CRle_trans _ (alt_a m) _).
      * apply (CRlt_asym (alt_a (S m)) (alt_a m)). apply alt_a_S_lt.
      * apply IHm. lia.
    + assert (k = S m) by lia. subst. apply CRle_refl.
Qed.

(* |0| ≤ y *)
Lemma abs_0_le (y : CRcarrier R) : CRle R (CR_of_Q R (0 # 1)) y ->
  CRle R (CRabs R (CR_of_Q R (0 # 1))) y.
Proof.
  intros H. rewrite (CRabs_right (CR_of_Q R (0 # 1)) (CRle_refl _)). exact H.
Qed.

(* 核心 gap：i < j ⟹ |S_j - S_i| ≤ alt_a (i+1) *)
Lemma pi4_gap (i j : nat) : (i < j)%nat ->
  CRle R (CRabs R (alt_partial alt_a j - alt_partial alt_a i)) (alt_a (i + 1)%nat).
Proof.
  intros Hij.
  set (M := (j - i - 1)%nat).
  assert (Hnat : (i + 1 + M)%nat = j) by (subst M; lia).
  assert (Heq : CReq R (alt_partial alt_a j - alt_partial alt_a i) (tail_partial i M)).
  { rewrite <- Hnat. apply S_tail_eq. }
  rewrite (CRabs_morph_prop R (alt_partial alt_a j - alt_partial alt_a i) (tail_partial i M) Heq).
  apply (tail_partial_bound i M).
Qed.

(* Cauchy 性：|S_i - S_j| ≤ 1/p（i,j ≥ p） *)
Lemma pi4_cauchy : CR_cauchy R (alt_partial alt_a).
Proof.
  intros p.
  exists (Pos.to_nat p).
  intros i j Hi Hj.
  destruct (Nat.le_ge_cases i j) as [Hij|Hji].
  - destruct (Nat.lt_ge_cases i j) as [Hijlt|Hige].
    + rewrite (CRabs_minus_sym (alt_partial alt_a i) (alt_partial alt_a j)).
      apply (CRle_trans _ (alt_a (i + 1)%nat) _).
      * apply pi4_gap. exact Hijlt.
      * apply (CRle_trans _ (alt_a (Pos.to_nat p + 1)%nat) _).
        -- apply alt_a_decr. lia.
        -- unfold alt_a. apply CR_of_Q_le.
           unfold Qle. simpl. lia.
    + replace j with i by lia.
      apply (CRle_trans _ (CR_of_Q R (0 # 1)) _).
      * apply (proj2 (CRle_morph R
                 (CRabs R (alt_partial alt_a i - alt_partial alt_a i))
                 (CRabs R (CR_of_Q R (0 # 1)))
                 ltac:(apply (CRabs_morph_prop R (alt_partial alt_a i - alt_partial alt_a i) (CR_of_Q R (0 # 1)));
                       unfold CRminus;
                       rewrite (CRplus_opp_r (alt_partial alt_a i));
                       apply CReq_refl)
                 (CR_of_Q R (0 # 1)) (CR_of_Q R (0 # 1)) (CReq_refl _))).
        apply abs_0_le. apply CRle_refl.
      * apply CR_of_Q_le. unfold Qle. simpl. lia.
  - destruct (Nat.lt_ge_cases j i) as [Hjilt|Hjge].
    + apply (CRle_trans _ (alt_a (j + 1)%nat) _).
      * apply pi4_gap. exact Hjilt.
      * apply (CRle_trans _ (alt_a (Pos.to_nat p + 1)%nat) _).
        -- apply alt_a_decr. lia.
        -- unfold alt_a. apply CR_of_Q_le. unfold Qle. simpl. lia.
    + replace i with j by lia.
      apply (CRle_trans _ (CR_of_Q R (0 # 1)) _).
      * apply (proj2 (CRle_morph R
                 (CRabs R (alt_partial alt_a j - alt_partial alt_a j))
                 (CRabs R (CR_of_Q R (0 # 1)))
                 ltac:(apply (CRabs_morph_prop R (alt_partial alt_a j - alt_partial alt_a j) (CR_of_Q R (0 # 1)));
                       unfold CRminus;
                       rewrite (CRplus_opp_r (alt_partial alt_a j));
                       apply CReq_refl)
                 (CR_of_Q R (0 # 1)) (CR_of_Q R (0 # 1)) (CReq_refl _))).
        apply abs_0_le. apply CRle_refl.
      * apply CR_of_Q_le. unfold Qle. simpl. lia.
Qed.

(* π/4 定义 *)
Definition CRpi4 : CRcarrier R :=
  projT1 (CR_complete R (alt_partial alt_a) pi4_cauchy).

Lemma pi4_cv : CR_cv R (alt_partial alt_a) CRpi4.
Proof. exact (projT2 (CR_complete R (alt_partial alt_a) pi4_cauchy)). Qed.

(* 奇/偶子列收敛 *)
Lemma odd_subseq_cv : CR_cv R (fun n => alt_partial alt_a (2 * n + 1)%nat) CRpi4.
Proof.
  intros p. destruct (pi4_cv p) as [N HN]. exists N. intros m Hm.
  apply HN. lia.
Qed.

Lemma even_subseq_cv : CR_cv R (fun n => alt_partial alt_a (2 * n)%nat) CRpi4.
Proof.
  intros p. destruct (pi4_cv p) as [N HN]. exists N. intros m Hm.
  apply HN. lia.
Qed.

(* 奇部分和递增（多步） / 偶部分和递减（多步） *)
Lemma odd_incr_multi (m n : nat) : (m <= n)%nat ->
  CRle R (alt_partial alt_a (2 * m + 1)%nat) (alt_partial alt_a (2 * n + 1)%nat).
Proof.
  intros H. induction n as [|n IHn].
  - destruct (Nat.eq_dec m 0); subst; [apply CRle_refl | lia].
  - destruct (Nat.lt_ge_cases m (S n)) as [Hlt|Hge].
    + apply (CRle_trans _ (alt_partial alt_a (2 * n + 1)%nat) _).
      * apply IHn. lia.
      * apply alt_odd_incr. intros k. apply (CRlt_asym (alt_a (S k)) (alt_a k)). apply alt_a_S_lt.
    + assert (m = S n) by lia. subst. apply CRle_refl.
Qed.

Lemma even_decr_multi (m n : nat) : (m <= n)%nat ->
  CRle R (alt_partial alt_a (2 * n)%nat) (alt_partial alt_a (2 * m)%nat).
Proof.
  intros H. induction n as [|n IHn].
  - destruct (Nat.eq_dec m 0); subst; [apply CRle_refl | lia].
  - destruct (Nat.lt_ge_cases m (S n)) as [Hlt|Hge].
    + apply (CRle_trans _ (alt_partial alt_a (2 * n)%nat) _).
      * apply alt_even_decr. intros k. apply (CRlt_asym (alt_a (S k)) (alt_a k)). apply alt_a_S_lt.
      * apply IHn. lia.
    + assert (m = S n) by lia. subst. apply CRle_refl.
Qed.

(* 奇部分和 ≤ 极限 ≤ 偶部分和 *)
Lemma pi4_odd_le (M : nat) :
  CRle R (alt_partial alt_a (2 * M + 1)%nat) CRpi4.
Proof.
  apply (CR_cv_bound_down (fun n => alt_partial alt_a (2 * n + 1)%nat)
          (alt_partial alt_a (2 * M + 1)%nat) CRpi4 M).
  - intros n Hn. apply odd_incr_multi. exact Hn.
  - apply odd_subseq_cv.
Qed.

Lemma pi4_even_ge (M : nat) :
  CRle R CRpi4 (alt_partial alt_a (2 * M)%nat).
Proof.
  apply (CR_cv_bound_up (fun n => alt_partial alt_a (2 * n)%nat)
          (alt_partial alt_a (2 * M)%nat) CRpi4 M).
  - intros n Hn. apply even_decr_multi. exact Hn.
  - apply even_subseq_cv.
Qed.

(* ============ Q 级精确计算：S_801 = 157/200 附近 ============ *)

(* Q 求和：无 Qred 的朴素有限和（分母为乘积；vm_compute 原生大整数，2001 项仅 ~8s） *)
Fixpoint qsum (q : nat -> Q) (n : nat) : Q :=
  match n with 0%nat => q 0%nat | S m => qsum q m + q (S m) end.

(* 交替级数的 Q 系数：±1/(2k+1) *)
Definition altq (k : nat) : Q :=
  if Nat.odd k then Qmake (-1) (Pos.of_nat (2 * k + 1))
  else Qmake 1 (Pos.of_nat (2 * k + 1)).

Lemma CR_of_Q_mult_sym (q r : Q) :
  CReq R (CR_of_Q R q * CR_of_Q R r) (CR_of_Q R (q * r)).
Proof. apply CReq_sym. apply CR_of_Q_mult. Qed.

(* 逐点：s_k·a_k == CR_of_Q (altq k) *)
Lemma altq_pointwise (k : nat) :
  CReq R (alt_sign k * alt_a k) (CR_of_Q R (altq k)).
Proof.
  unfold alt_sign, alt_a, altq.
  destruct (Nat.odd k) eqn:Hodd.
  - transitivity (CR_of_Q R ((-1 # 1) * (1 # Pos.of_nat (2 * k + 1)))).
    + apply CR_of_Q_mult_sym.
    + apply (CR_of_Q_morph R ((-1 # 1) * (1 # Pos.of_nat (2 * k + 1)))
                            (Qmake (-1) (Pos.of_nat (2 * k + 1)))).
      vm_compute. reflexivity.
  - transitivity (CR_of_Q R ((1 # 1) * (1 # Pos.of_nat (2 * k + 1)))).
    + apply CR_of_Q_mult_sym.
    + apply (CR_of_Q_morph R ((1 # 1) * (1 # Pos.of_nat (2 * k + 1)))
                            (Qmake 1 (Pos.of_nat (2 * k + 1)))).
      vm_compute. reflexivity.
Qed.

(* CRsum 与 Q 求和桥接（raw 版：无 Qred，定义相等） *)
Lemma CRsum_of_Q (q : nat -> Q) (n : nat) :
  CReq R (CRsum (fun k => CR_of_Q R (q k)) n) (CR_of_Q R (qsum q n)).
Proof.
  induction n.
  - cbn [CRsum qsum]. apply CReq_refl.
  - cbn [CRsum qsum].
    rewrite IHn.
    transitivity (CR_of_Q R (qsum q n + q (S n))).
    + apply CReq_sym. apply CR_of_Q_plus.
    + apply CReq_refl.
Qed.

(* 部分和 == Q 求和 *)
Lemma alt_partial_of_Q (n : nat) :
  CReq R (alt_partial alt_a n) (CR_of_Q R (qsum altq n)).
Proof.
  unfold alt_partial.
  transitivity (CRsum (fun k => CR_of_Q R (altq k)) n).
  - apply CRsum_eq. intros k Hk. apply altq_pointwise.
  - apply CRsum_of_Q.
Qed.

(* ============ Q 级精确计算：S_801（每个 vm_compute 约 35s） ============ *)

(* 下界 S_801 ≥ 157/200 *)
Lemma pi4_lower_rat :
  CRle R (CR_of_Q R (157 # 200)) (alt_partial alt_a 801).
Proof.
  rewrite (alt_partial_of_Q 801).
  apply CR_of_Q_le.
  apply Qle_bool_imp_le.
  vm_compute. reflexivity.
Qed.

(* alt_a 802 的 Q 表示 *)
Lemma alt_a_802_q : CReq R (alt_a 802) (CR_of_Q R (1 # Pos.of_nat 1605)).
Proof.
  unfold alt_a.
  apply (CR_of_Q_morph R (Qmake 1 (Pos.of_nat (2 * 802 + 1))) (1 # Pos.of_nat 1605)).
  vm_compute. reflexivity.
Qed.

(* 上界 S_801 + a_802 ≤ 63/80 *)
Lemma pi4_upper_rat :
  CRle R (alt_partial alt_a 801 + alt_a 802) (CR_of_Q R (63 # 80)).
Proof.
  (* 先消去巨大部分和，再处理小项：避免在含 CRsum 的目标里 rewrite *)
  rewrite (alt_partial_of_Q 801).
  rewrite alt_a_802_q.
  rewrite <- (CR_of_Q_plus R (qsum altq 801) (1 # Pos.of_nat 1605)).
  apply CR_of_Q_le.
  apply Qle_bool_imp_le.
  vm_compute. reflexivity.
Qed.

(* 下界：157/200 ≤ π/4 *)
Lemma pi4_lower : CRle R (CR_of_Q R (157 # 200)) CRpi4.
Proof.
  apply (CRle_trans _ (alt_partial alt_a 801) _).
  - apply pi4_lower_rat.
  - replace 801%nat with (2 * 400 + 1)%nat by lia.
    apply pi4_odd_le.
Qed.

(* 交替级数余项：|CRpi4 - S_N| ≤ alt_a (N+1) *)
Lemma pi4_remainder (N : nat) :
  CRle R (CRabs R (CRpi4 - alt_partial alt_a N)) (alt_a (N + 1)).
Proof.
  (* 平移尾序列 t_M := tail_partial N M == S_{N+1+M} - S_N → CRpi4 - S_N *)
  (* |t_M| ≤ alt_a (N+1)（tail_partial_bound）→ 取极限 *)
  (* 先建立 t_M 的收敛性 *)
  assert (Hcv : CR_cv R (fun M => tail_partial N M) (CRpi4 - alt_partial alt_a N)).
  { (* tail_partial N M == S_{N+1+M} - S_N，且 S_{N+1+M} → CRpi4 *)
    apply (CR_cv_eq (fun M => tail_partial N M)
                    (fun M => alt_partial alt_a (N + 1 + M) - alt_partial alt_a N)
                    (CRpi4 - alt_partial alt_a N)).
    - intros M. apply S_tail_eq.
    - apply (CR_cv_minus (fun M => alt_partial alt_a (N + 1 + M))
                         (fun _ => alt_partial alt_a N)
                         CRpi4 (alt_partial alt_a N)).
      + (* 平移序列收敛：S_{N+1+M} → CRpi4 *)
        intros p. destruct (pi4_cv p) as [N0 HN0]. exists N0. intros m Hm.
        apply HN0. lia.
      + apply CR_cv_const. }
  (* |t_M| ≤ a：上界 a 与下界 -a，取极限 *)
  apply (proj1 (CRabs_def R (CRpi4 - alt_partial alt_a N) (alt_a (N + 1)))).
  split.
  - (* CRpi4 - S_N ≤ a：CR_cv_bound_up *)
    apply (CR_cv_bound_up (fun M => tail_partial N M) (alt_a (N + 1))
                          (CRpi4 - alt_partial alt_a N) 0).
    + intros M H. apply (proj1 (CRabs_def2 (tail_partial N M) (alt_a (N + 1))
                                        (tail_partial_bound N M))).
    + exact Hcv.
  - (* -(CRpi4 - S_N) ≤ a：CR_cv_bound_down 得 -a ≤ l，再反号 *)
    apply (proj2 (CRle_morph R (- (CRpi4 - alt_partial alt_a N))
            (- (CRpi4 - alt_partial alt_a N)) (CReq_refl _)
            (alt_a (N + 1)) (- (- (alt_a (N + 1))))
            ltac:(apply CReq_sym; ring))).
    apply (CRopp_ge_le_contravar (CRpi4 - alt_partial alt_a N) (- (alt_a (N + 1)))).
    apply (CR_cv_bound_down (fun M => tail_partial N M) (- (alt_a (N + 1)))
                            (CRpi4 - alt_partial alt_a N) 0).
    + intros M H.
      apply (proj2 (CRabs_def2 (tail_partial N M) (alt_a (N + 1))
                                (tail_partial_bound N M))).
    + exact Hcv.
Qed.

(* 上界：π/4 ≤ S_801 + a_802 ≤ 63/80 *)
Lemma pi4_upper : CRle R CRpi4 (CR_of_Q R (63 # 80)).
Proof.
  apply (CRle_trans _ (alt_partial alt_a 801 + alt_a 802) _).
  - (* CRpi4 ≤ S_801 + a_802：由余项 CRpi4 - S_801 ≤ a_802 *)
    apply (proj2 (CRle_morph R CRpi4
            (alt_partial alt_a 801 + (CRpi4 - alt_partial alt_a 801))
            ltac:(unfold CRminus; ring)
            (alt_partial alt_a 801 + alt_a 802)
            (alt_partial alt_a 801 + alt_a 802) (CReq_refl _))).
    apply (CRplus_le_compat_l (alt_partial alt_a 801)).
    apply (proj1 (CRabs_def2 (CRpi4 - alt_partial alt_a 801) (alt_a 802)
                             (pi4_remainder 801))).
  - apply pi4_upper_rat.
Qed.

(* π := 4·(π/4) *)
Definition CRpi : CRcarrier R := CR_of_Q R (4 # 1) * CRpi4.

(* 4·(157/200) == 157/50，4·(63/80) == 63/20 *)
Lemma CRpi_scale_lower : CReq R (CR_of_Q R (4 # 1) * CR_of_Q R (157 # 200))
                                (CR_of_Q R (157 # 50)).
Proof.
  rewrite <- (CR_of_Q_mult R (4 # 1) (157 # 200)).
  apply CR_of_Q_morph. vm_compute. reflexivity.
Qed.

Lemma CRpi_scale_upper : CReq R (CR_of_Q R (4 # 1) * CR_of_Q R (63 # 80))
                                (CR_of_Q R (63 # 20)).
Proof.
  rewrite <- (CR_of_Q_mult R (4 # 1) (63 # 80)).
  apply CR_of_Q_morph. vm_compute. reflexivity.
Qed.

(* 3.14 ≤ π ≤ 3.15 *)
Lemma CRpi_lower : CRle R (CR_of_Q R (157 # 50)) CRpi.
Proof.
  unfold CRpi.
  apply (CRle_trans _ (CR_of_Q R (4 # 1) * CR_of_Q R (157 # 200)) _).
  - setoid_rewrite CRpi_scale_lower. apply CRle_refl.
  - apply (CRmult_le_compat_l (CR_of_Q R (4 # 1)) (CR_of_Q R (157 # 200)) CRpi4).
    + apply CR_of_Q_le. apply Qle_bool_imp_le. vm_compute. reflexivity.
    + apply pi4_lower.
Qed.

Lemma CRpi_upper : CRle R CRpi (CR_of_Q R (63 # 20)).
Proof.
  unfold CRpi.
  apply (CRle_trans _ (CR_of_Q R (4 # 1) * CR_of_Q R (63 # 80)) _).
  - apply (CRmult_le_compat_l (CR_of_Q R (4 # 1)) CRpi4 (CR_of_Q R (63 # 80))).
    + apply CR_of_Q_le. apply Qle_bool_imp_le. vm_compute. reflexivity.
    + apply pi4_upper.
  - setoid_rewrite CRpi_scale_upper. apply CRle_refl.
Qed.

(* ============ π 界增强：3.141 ≤ π ≤ 3.142（G-5 M2 闭合所需） ============ *)

(* a_3002 = 1/6005 的 Q 表示 *)
Lemma alt_a_3002_q : CReq R (alt_a 3002) (CR_of_Q R (1 # Pos.of_nat 6005)).
Proof.
  unfold alt_a.
  apply (CR_of_Q_morph R (Qmake 1 (Pos.of_nat (2 * 3002 + 1))) (1 # Pos.of_nat 6005)).
  vm_compute. reflexivity.
Qed.

(* S_2001 ≥ 3141/4000：直接 vm_compute（~70s） *)
Lemma pi4_lower_rat_2001 :
  CRle R (CR_of_Q R (3141 # 4000)) (alt_partial alt_a 2001).
Proof.
  rewrite (alt_partial_of_Q 2001).
  apply CR_of_Q_le.
  apply Qle_bool_imp_le.
  vm_compute. reflexivity.
Qed.

(* S_3001 + a_3002 ≤ 3142/4000：直接 vm_compute（~70s） *)
Lemma pi4_upper_rat_3001 :
  CRle R (alt_partial alt_a 3001 + alt_a 3002) (CR_of_Q R (3142 # 4000)).
Proof.
  rewrite (alt_partial_of_Q 3001).
  rewrite alt_a_3002_q.
  rewrite <- (CR_of_Q_plus R (qsum altq 3001) (1 # Pos.of_nat 6005)).
  apply CR_of_Q_le.
  apply Qle_bool_imp_le.
  vm_compute. reflexivity.
Qed.

(* 3.141 ≤ π/4 且 π/4 ≤ 3.142 *)
Lemma pi4_lower_3141 : CRle R (CR_of_Q R (3141 # 4000)) CRpi4.
Proof.
  apply (CRle_trans _ (alt_partial alt_a 2001) _).
  - apply pi4_lower_rat_2001.
  - replace 2001%nat with (2 * 1000 + 1)%nat by lia.
    apply pi4_odd_le.
Qed.

Lemma pi4_upper_3142 : CRle R CRpi4 (CR_of_Q R (3142 # 4000)).
Proof.
  apply (CRle_trans _ (alt_partial alt_a 3001 + alt_a 3002) _).
  - (* CRpi4 ≤ S_3001 + a_3002：由余项 CRpi4 - S_3001 ≤ a_3002 *)
    apply (proj2 (CRle_morph R CRpi4
            (alt_partial alt_a 3001 + (CRpi4 - alt_partial alt_a 3001))
            ltac:(unfold CRminus; ring)
            (alt_partial alt_a 3001 + alt_a 3002)
            (alt_partial alt_a 3001 + alt_a 3002) (CReq_refl _))).
    apply (CRplus_le_compat_l (alt_partial alt_a 3001)).
    apply (proj1 (CRabs_def2 (CRpi4 - alt_partial alt_a 3001) (alt_a 3002)
                             (pi4_remainder 3001))).
  - apply pi4_upper_rat_3001.
Qed.

(* 4·(3141/4000) == 3141/1000，4·(3142/4000) == 3142/1000 *)
Lemma CRpi_scale_lower_3141 : CReq R (CR_of_Q R (4 # 1) * CR_of_Q R (3141 # 4000))
                                     (CR_of_Q R (3141 # 1000)).
Proof.
  rewrite <- (CR_of_Q_mult R (4 # 1) (3141 # 4000)).
  apply CR_of_Q_morph. vm_compute. reflexivity.
Qed.

Lemma CRpi_scale_upper_3142 : CReq R (CR_of_Q R (4 # 1) * CR_of_Q R (3142 # 4000))
                                     (CR_of_Q R (3142 # 1000)).
Proof.
  rewrite <- (CR_of_Q_mult R (4 # 1) (3142 # 4000)).
  apply CR_of_Q_morph. vm_compute. reflexivity.
Qed.

(* 3.141 ≤ π ≤ 3.142 *)
Lemma CRpi_lower_3141 : CRle R (CR_of_Q R (3141 # 1000)) CRpi.
Proof.
  unfold CRpi.
  apply (CRle_trans _ (CR_of_Q R (4 # 1) * CR_of_Q R (3141 # 4000)) _).
  - setoid_rewrite CRpi_scale_lower_3141. apply CRle_refl.
  - apply (CRmult_le_compat_l (CR_of_Q R (4 # 1)) (CR_of_Q R (3141 # 4000)) CRpi4).
    + apply CR_of_Q_le. apply Qle_bool_imp_le. vm_compute. reflexivity.
    + apply pi4_lower_3141.
Qed.

Lemma CRpi_upper_3142 : CRle R CRpi (CR_of_Q R (3142 # 1000)).
Proof.
  unfold CRpi.
  apply (CRle_trans _ (CR_of_Q R (4 # 1) * CR_of_Q R (3142 # 4000)) _).
  - apply (CRmult_le_compat_l (CR_of_Q R (4 # 1)) CRpi4 (CR_of_Q R (3142 # 4000))).
    + apply CR_of_Q_le. apply Qle_bool_imp_le. vm_compute. reflexivity.
    + apply pi4_upper_3142.
  - setoid_rewrite CRpi_scale_upper_3142. apply CRle_refl.
Qed.

End M1b.

(* ==================== 模块 52/67: probe_sin_cr_m2 ==================== *)

Close Scope R_scope.
Close Scope Z_scope.
(* ============================================================
   G-5 可判定性溢价 M2：构造性 sin（交替幂级数）
   纯构造性：Stdlib ConstructiveReals，零经典、零 Admitted、零公理
   sin x = Σ_{k=0}^∞ (-1)^k x^{2k+1}/(2k+1)!
   复用 M1a alt_series_remainder 骨架（alt_sign/alt_partial）
   ============================================================ *)
From Stdlib Require Import ConstructiveReals.
From Stdlib Require Import ConstructiveRealsMorphisms.
From Stdlib Require Import ConstructiveAbs.
From Stdlib Require Import ConstructiveSum.
From Stdlib Require Import ConstructiveLimits.
From Stdlib Require Import QArith.
From Stdlib Require Import ZArith.
From Stdlib Require Import Lia.
From Stdlib Require Import Ring.

Local Open Scope ConstructiveReals.

Section M2.

Context {R : ConstructiveReals}.
Add Ring CR_ring : (CRisRing R).

(* ============ nat 层：阶乘 ============ *)

Fixpoint nfact (n : nat) : nat :=
  match n with 0%nat => 1%nat | S m => (S m * nfact m)%nat end.

Lemma nfact_S (n : nat) : nfact (S n) = (S n * nfact n)%nat.
Proof. reflexivity. Qed.

Lemma nfact_pos (n : nat) : (0 < nfact n)%nat.
Proof.
  induction n.
  - cbn [nfact]. lia.
  - cbn [nfact]. lia.
Qed.

(* 关键拆分：nfact (2k+3) = (2k+2)*(2k+3)*nfact (2k+1) *)
Lemma nfact_2k3 (k : nat) :
  nfact (2 * k + 3) = ((2 * k + 2) * (2 * k + 3) * nfact (2 * k + 1))%nat.
Proof.
  replace (2 * k + 3)%nat with (S (S (2 * k + 1)))%nat by lia.
  rewrite nfact_S.
  rewrite nfact_S.
  nia.
Qed.

(* ============ CR 层：幂 ============ *)

Fixpoint x_pow (x : CRcarrier R) (n : nat) : CRcarrier R :=
  match n with 0%nat => CR_of_Q R 1 | S m => x_pow x m * x end.

(* 幂加法：x_pow x (m+n) == x_pow x m * x_pow x n *)
Lemma x_pow_add (x : CRcarrier R) (m n : nat) :
  CReq R (x_pow x (m + n)) (x_pow x m * x_pow x n).
Proof.
  induction m.
  - cbn [x_pow].
    transitivity (CR_of_Q R 1 * x_pow x n).
    + apply CReq_sym. apply CRmult_1_l.
    + apply CReq_refl.
  - cbn [x_pow].
    replace (S m + n)%nat with (S (m + n))%nat by lia.
    cbn [x_pow].
    rewrite IHm.
    (* (x_pow x m * x_pow x n) * x == (x_pow x m * x) * x_pow x n *)
    ring.
Qed.

(* ============ sin 级数项 ============ *)

(* 绝对值项：x^{2k+1}/(2k+1)! *)
Definition sin_a (x : CRcarrier R) (k : nat) : CRcarrier R :=
  CR_of_Q R (Qmake 1 (Pos.of_nat (nfact (2 * k + 1)))) * x_pow x (2 * k + 1).

(* 正数层：Pos.of_nat (nfact (2k+1)) * Pos.of_nat ((2k+2)(2k+3)) = Pos.of_nat (nfact (2k+3)) *)
Lemma pos_coef_S (k : nat) :
  (Pos.of_nat (nfact (2 * k + 1)) * Pos.of_nat ((2 * k + 2) * (2 * k + 3)))%positive
  = Pos.of_nat (nfact (2 * k + 3)).
Proof.
  assert (Hn : nfact (2 * k + 1) <> 0%nat) by (apply Nat.neq_0_lt_0; apply nfact_pos).
  assert (Hp : ((2 * k + 2) * (2 * k + 3))%nat <> 0%nat) by lia.
  rewrite <- (Nat2Pos.inj_mul (nfact (2 * k + 1)) ((2 * k + 2) * (2 * k + 3))%nat Hn Hp).
  f_equal.
  symmetry.
  rewrite nfact_2k3.
  nia.
Qed.

(* 系数拆分：1/(2k+3)! == (1/(2k+1)!) * (1/((2k+2)(2k+3))) *)
Lemma sin_coef_S (k : nat) :
  CReq R (CR_of_Q R (1 # Pos.of_nat (nfact (2 * k + 3))))
         (CR_of_Q R (1 # Pos.of_nat (nfact (2 * k + 1)))
          * CR_of_Q R (1 # Pos.of_nat ((2 * k + 2) * (2 * k + 3)))).
Proof.
  transitivity (CR_of_Q R ((1 # Pos.of_nat (nfact (2 * k + 1)))
                           * (1 # Pos.of_nat ((2 * k + 2) * (2 * k + 3))))).
  - apply (CR_of_Q_morph R (1 # Pos.of_nat (nfact (2 * k + 3)))
                          ((1 # Pos.of_nat (nfact (2 * k + 1)))
                           * (1 # Pos.of_nat ((2 * k + 2) * (2 * k + 3))))).
    (* Q 层：Qeq (1 # Pos.of_nat (nfact (2k+3))) ((1#A)*(1#B)) *)
    unfold Qeq, Qmult. cbn [Qnum Qden].
    apply (f_equal Z.pos).
    apply pos_coef_S.
  - apply CR_of_Q_mult.
Qed.

(* 递推：sin_a x (S k) == sin_a x k * x_pow x 2 * CR_of_Q (1#((2k+2)(2k+3))) *)
Lemma sin_a_S (x : CRcarrier R) (k : nat) :
  CReq R (sin_a x (S k))
         (sin_a x k * x_pow x 2
          * CR_of_Q R (1 # Pos.of_nat ((2 * k + 2) * (2 * k + 3)))).
Proof.
  unfold sin_a.
  (* 幂指数：2*(S k)+1 = (2k+1)+2 *)
  replace (2 * (S k) + 1)%nat with ((2 * k + 1) + 2)%nat by lia.
  rewrite (x_pow_add x (2 * k + 1) 2).
  (* 系数：nfact (2*(S k)+1) = nfact ((2k+1)+2) = nfact (2k+3) *)
  replace ((2 * k + 1) + 2)%nat with (2 * k + 3)%nat by lia.
  transitivity (CR_of_Q R (1 # Pos.of_nat (nfact (2 * k + 1)))
                * CR_of_Q R (1 # Pos.of_nat ((2 * k + 2) * (2 * k + 3)))
                * (x_pow x (2 * k + 1) * x_pow x 2)).
  - (* 左边：系数拆分 *)
    apply (CRmult_morph_Proper
             (CR_of_Q R (1 # Pos.of_nat (nfact (2 * k + 3))))
             (CR_of_Q R (1 # Pos.of_nat (nfact (2 * k + 1)))
              * CR_of_Q R (1 # Pos.of_nat ((2 * k + 2) * (2 * k + 3))))
             (sin_coef_S k)
             (x_pow x (2 * k + 1) * x_pow x 2)
             (x_pow x (2 * k + 1) * x_pow x 2)
             (CReq_refl _)).
    ring.
Qed.

(* 部分和：Σ_{k=0}^{N} (-1)^k sin_a x k *)
Definition sin_partial (x : CRcarrier R) (N : nat) : CRcarrier R :=
  alt_partial (sin_a x) N.

(* ============ 非负性与单调性（0 ≤ x ≤ 1 时） ============ *)

(* 幂非负：0 ≤ x ⟹ 0 ≤ x_pow x n *)
Lemma x_pow_nonneg (x : CRcarrier R) (Hx : 0 <= x) (n : nat) :
  0 <= x_pow x n.
Proof.
  induction n.
  - cbn [x_pow]. apply CR_of_Q_le. unfold Qle. simpl. lia.
  - cbn [x_pow]. apply CRmult_le_0_compat. exact IHn. exact Hx.
Qed.

(* 幂 ≤ 1：0 ≤ x ≤ 1 ⟹ x_pow x n ≤ 1 *)
Lemma x_pow_le_1 (x : CRcarrier R) (Hx0 : 0 <= x) (Hx1 : x <= 1) (n : nat) :
  x_pow x n <= 1.
Proof.
  induction n.
  - cbn [x_pow]. apply CRle_refl.
  - cbn [x_pow].
    apply (CRle_trans _ (x_pow x n * 1) _).
    + apply (CRmult_le_compat_l (x_pow x n) x 1).
      * apply x_pow_nonneg. exact Hx0.
      * exact Hx1.
    + (* x_pow x n * 1 == x_pow x n ≤ 1 *)
      apply (CRle_morph R (x_pow x n * 1) (x_pow x n) ltac:(ring)
                          1 1 (CReq_refl _)).
      exact IHn.
Qed.

(* 级数项非负：0 ≤ x ⟹ 0 ≤ sin_a x k *)
Lemma sin_a_nonneg (x : CRcarrier R) (Hx : 0 <= x) (k : nat) :
  0 <= sin_a x k.
Proof.
  unfold sin_a.
  apply CRmult_le_0_compat.
  - apply CR_of_Q_le. unfold Qle. simpl.
    (* 0*D ≤ 1*nfact... 实际：0 ≤ 1/(2k+1)! *)
    lia.
  - apply x_pow_nonneg. exact Hx.
Qed.

(* 系数 ≤ 1：1/((2k+2)(2k+3)) ≤ 1 *)
Lemma coef_le_1 (k : nat) :
  CR_of_Q R (1 # Pos.of_nat ((2 * k + 2) * (2 * k + 3))) <= 1.
Proof.
  apply CR_of_Q_le. unfold Qle. simpl. lia.
Qed.

(* 项递减：0 ≤ x ≤ 1 ⟹ sin_a x (S k) ≤ sin_a x k *)
Lemma sin_a_S_le (x : CRcarrier R) (Hx0 : 0 <= x) (Hx1 : x <= 1) (k : nat) :
  sin_a x (S k) <= sin_a x k.
Proof.
  rewrite sin_a_S.
  (* 目标：sin_a x k * x_pow x 2 * c ≤ sin_a x k *)
  apply (CRle_trans _ (sin_a x k * 1) _).
  - (* 第一段：sin_a x k * x_pow x 2 * c ≤ sin_a x k * 1 *)
    (* 结合左边：sin_a x k * x_pow x 2 * c == sin_a x k * (x_pow x 2 * c) *)
    apply (CRle_morph R
             (sin_a x k * x_pow x 2 * CR_of_Q R (1 # Pos.of_nat ((2 * k + 2) * (2 * k + 3))))
             (sin_a x k * (x_pow x 2 * CR_of_Q R (1 # Pos.of_nat ((2 * k + 2) * (2 * k + 3)))))
             ltac:(ring)
             (sin_a x k * 1) (sin_a x k * 1) (CReq_refl _)).
    apply (CRmult_le_compat_l (sin_a x k)
                              (x_pow x 2 * CR_of_Q R (1 # Pos.of_nat ((2 * k + 2) * (2 * k + 3))))
                              1).
    + apply sin_a_nonneg. exact Hx0.
    + (* x_pow x 2 * c ≤ 1 *)
      apply (CRle_trans _ (x_pow x 2 * 1) _).
      * apply (CRmult_le_compat_l (x_pow x 2)
                                  (CR_of_Q R (1 # Pos.of_nat ((2 * k + 2) * (2 * k + 3))))
                                  1).
        - apply x_pow_nonneg. exact Hx0.
        - apply coef_le_1.
      * (* x_pow x 2 * 1 == x_pow x 2 ≤ 1 *)
        apply (CRle_morph R (x_pow x 2 * 1) (x_pow x 2) ltac:(ring)
                            1 1 (CReq_refl _)).
        apply x_pow_le_1. exact Hx0. exact Hx1.
  - (* sin_a x k * 1 == sin_a x k *)
    apply (CRle_morph R (sin_a x k * 1) (sin_a x k) ltac:(ring)
                        (sin_a x k) (sin_a x k) (CReq_refl _)).
    apply CRle_refl.
Qed.

(* 多步递减：m ≤ n ⟹ sin_a x n ≤ sin_a x m *)
Lemma sin_a_decr (x : CRcarrier R) (Hx0 : 0 <= x) (Hx1 : x <= 1) (k m : nat) :
  (k <= m)%nat -> sin_a x m <= sin_a x k.
Proof.
  intros Hkm.
  induction m.
  - (* m=0：k≤0 ⟹ k=0 *)
    assert (k = 0%nat) by lia. subst. apply CRle_refl.
  - (* m = S m' *)
    destruct (Nat.eq_dec k (S m)) as [Hk | Hk].
    + subst. apply CRle_refl.
    + apply (CRle_trans _ (sin_a x m) _).
      * apply sin_a_S_le. exact Hx0. exact Hx1.
      * apply IHm. lia.
Qed.

(* ============ sin 交替级数收敛（0 ≤ x ≤ 1） ============ *)

(* sin 尾平移部分和 *)
Definition sin_tail_partial (x : CRcarrier R) (N M : nat) : CRcarrier R :=
  CRsum (fun k => alt_sign (N + 1 + k) * sin_a x (N + 1 + k)) M.

(* 平移部分和的符号分裂（同 M1b tail_sign_split，换 sin_a） *)
Lemma sin_tail_sign_split (x : CRcarrier R) (N M : nat) :
  CReq R (sin_tail_partial x N M)
         (alt_sign (N + 1) * CRsum (fun k => alt_sign k * sin_a x (N + 1 + k)) M).
Proof.
  unfold sin_tail_partial.
  transitivity (CRsum (fun k => (alt_sign (N + 1) * alt_sign k) * sin_a x (N + 1 + k)) M).
  - apply (CRsum_eq _ _ _ (fun k Hk =>
      CRmult_morph R (alt_sign (N + 1 + k)) (alt_sign (N + 1) * alt_sign k) (alt_sign_add (N + 1) k)
                    (sin_a x (N + 1 + k)) (sin_a x (N + 1 + k)) (CReq_refl _))).
  - transitivity (CRsum (fun k => alt_sign (N + 1) * (alt_sign k * sin_a x (N + 1 + k))) M).
    + apply (CRsum_eq _ _ _ (fun k Hk =>
        CRmult_assoc (alt_sign (N + 1)) (alt_sign k) (sin_a x (N + 1 + k)))).
    + apply (CRsum_scale (fun k => alt_sign k * sin_a x (N + 1 + k)) (alt_sign (N + 1)) M).
Qed.

(* sin 尾平移部分和界：|sin_tail N M| ≤ sin_a x (N+1) *)
Lemma sin_tail_partial_bound (x : CRcarrier R) (Hx0 : 0 <= x) (Hx1 : x <= 1) (N M : nat) :
  CRle R (CRabs R (sin_tail_partial x N M)) (sin_a x (N + 1)).
Proof.
  rewrite (sin_tail_sign_split x N M).
  rewrite (CRabs_mult (alt_sign (N + 1)) _).
  apply (CRle_trans _ (CR_of_Q R (1 # 1) * CRabs R (CRsum (fun k => alt_sign k * sin_a x (N + 1 + k)) M)) _).
  - apply (CRmult_le_compat_r (CRabs R (CRsum (fun k => alt_sign k * sin_a x (N + 1 + k)) M))).
    + apply (CRabs_pos (CRsum (fun k => alt_sign k * sin_a x (N + 1 + k)) M)).
    + destruct (Nat.odd (N + 1)) eqn:Hodd.
      * unfold alt_sign. rewrite Hodd. apply abs_minus_one_le.
      * unfold alt_sign. rewrite Hodd. apply abs_one_le.
  - rewrite (CRmult_1_l (CRabs R (CRsum (fun k => alt_sign k * sin_a x (N + 1 + k)) M))).
    apply (CRle_trans _ (sin_a x (N + 1)) _).
    + change (CRle R (CRabs R (alt_partial (fun k => sin_a x (N + 1 + k)) M)) (sin_a x (N + 1))).
      apply (CRle_trans _ (sin_a x (N + 1 + 0)) _).
      * apply (alt_series_remainder (fun k => sin_a x (N + 1 + k)) M).
        -- intros k. apply sin_a_nonneg. exact Hx0.
        -- intros k. apply (sin_a_decr x Hx0 Hx1 (N + 1 + k) (N + 1 + S k)).
           lia.
      * replace (N + 1 + 0)%nat with (N + 1)%nat by lia.
        apply CRle_refl.
    + apply CRle_refl.
Qed.

(* 核心恒等式：S_{N+1+M} - S_N == sin_tail N M *)
Lemma sin_S_tail_eq (x : CRcarrier R) (N M : nat) :
  CReq R (alt_partial (sin_a x) (N + 1 + M) - alt_partial (sin_a x) N)
         (sin_tail_partial x N M).
Proof.
  induction M as [|M IHM].
  - unfold sin_tail_partial. unfold alt_partial.
    replace (N + 1 + 0)%nat with (S N) by lia.
    cbn [CRsum].
    replace (N + 1 + 0)%nat with (S N) by lia.
    set (A := CRsum (fun k : nat => alt_sign k * sin_a x k) N).
    set (b := alt_sign (S N) * sin_a x (S N)).
    unfold CRminus.
    transitivity (A + (b + (- A))).
    + setoid_rewrite (CRplus_assoc A b (- A)). apply CReq_refl.
    + transitivity (A + ((- A) + b)).
      * rewrite (CRplus_comm b (- A)). apply CReq_refl.
      * transitivity ((A + (- A)) + b).
        -- apply CReq_sym. setoid_rewrite (CRplus_assoc A (- A) b). apply CReq_refl.
        -- rewrite (CRplus_opp_r A). rewrite (CRplus_0_l b). apply CReq_refl.
  - replace (N + 1 + S M)%nat with (S (N + 1 + M))%nat by lia.
    rewrite (CRminus_trans (alt_partial (sin_a x) (S (N + 1 + M)))
                           (alt_partial (sin_a x) (N + 1 + M))
                           (alt_partial (sin_a x) N)).
    setoid_rewrite IHM.
    unfold alt_partial.
    setoid_rewrite (CRsum_diff_dS0 (fun k => alt_sign k * sin_a x k) (N + 1 + M)).
    unfold sin_tail_partial.
    cbn [CRsum].
    replace (N + 1 + S M)%nat with (S (N + 1 + M))%nat by lia.
    rewrite (CRplus_comm (alt_sign (S (N + 1 + M)) * sin_a x (S (N + 1 + M))) _).
    apply CReq_refl.
Qed.

(* 核心 gap：i < j ⟹ |S_j - S_i| ≤ sin_a x (i+1) *)
Lemma sin_gap (x : CRcarrier R) (Hx0 : 0 <= x) (Hx1 : x <= 1) (i j : nat) :
  (i < j)%nat ->
  CRle R (CRabs R (alt_partial (sin_a x) j - alt_partial (sin_a x) i)) (sin_a x (i + 1)%nat).
Proof.
  intros Hij.
  set (M := (j - i - 1)%nat).
  assert (Hnat : (i + 1 + M)%nat = j) by (subst M; lia).
  assert (Heq : CReq R (alt_partial (sin_a x) j - alt_partial (sin_a x) i) (sin_tail_partial x i M)).
  { rewrite <- Hnat. apply sin_S_tail_eq. }
  rewrite (CRabs_morph_prop R (alt_partial (sin_a x) j - alt_partial (sin_a x) i)
                              (sin_tail_partial x i M) Heq).
  apply (sin_tail_partial_bound x Hx0 Hx1 i M).
Qed.

(* n ≤ nfact n（归纳） *)
Lemma nfact_ge_n (n : nat) : (n <= nfact n)%nat.
Proof.
  induction n.
  - cbn [nfact]. lia.
  - rewrite nfact_S.
    (* S n ≤ S n * nfact n：nfact n ≥ 1 ⟹ nfact n = S k *)
    assert (Hp : (1 <= nfact n)%nat) by (exact (nfact_pos n)).
    destruct (nfact n) as [|nf] eqn:Hnf.
    + lia.
    + nia.
Qed.

(* sin_a 上界：sin_a x n ≤ 1/nfact(2n+1)（0 ≤ x ≤ 1） *)
Lemma sin_a_coef_bound (x : CRcarrier R) (Hx0 : 0 <= x) (Hx1 : x <= 1) (n : nat) :
  sin_a x n <= CR_of_Q R (1 # Pos.of_nat (nfact (2 * n + 1))).
Proof.
  unfold sin_a.
  (* sin_a = c · pow ≤ c · 1 = c（pow ≤ 1，c ≥ 0） *)
  apply (CRle_trans _ (CR_of_Q R (1 # Pos.of_nat (nfact (2 * n + 1))) * 1) _).
  - apply (CRmult_le_compat_l (CR_of_Q R (1 # Pos.of_nat (nfact (2 * n + 1))))
                              (x_pow x (2 * n + 1)) 1).
    + apply CR_of_Q_le. unfold Qle. simpl. lia.
    + apply x_pow_le_1. exact Hx0. exact Hx1.
  - apply (CRle_morph R
             (CR_of_Q R (1 # Pos.of_nat (nfact (2 * n + 1))) * 1)
             (CR_of_Q R (1 # Pos.of_nat (nfact (2 * n + 1))))
             ltac:(ring)
             (CR_of_Q R (1 # Pos.of_nat (nfact (2 * n + 1))))
             (CR_of_Q R (1 # Pos.of_nat (nfact (2 * n + 1))))
             (CReq_refl _)).
    apply CRle_refl.
Qed.

(* 1/nfact(2n+1) ≤ 1/(2n+1)（nfact ≥ 2n+1） *)
Lemma sin_a_coef_le_recip (n : nat) :
  CR_of_Q R (1 # Pos.of_nat (nfact (2 * n + 1))) <=
  CR_of_Q R (1 # Pos.of_nat (2 * n + 1)).
Proof.
  apply CR_of_Q_le. unfold Qle. cbn [Qnum Qden]. simpl.
  (* 目标：Z.pos (Pos.of_nat (2n+1)) ≤ Z.pos (Pos.of_nat (nfact(2n+1))) *)
  rewrite <- !positive_nat_Z.
  (* 目标：Z.of_nat (Pos.to_nat (Pos.of_nat (2n+1))) ≤ Z.of_nat (Pos.to_nat (Pos.of_nat (nfact(2n+1)))) *)
  apply Nat2Z.inj_le.
  (* nat 层：Pos.to_nat (Pos.of_nat m) == m（m ≠ 0）；目标里 2n+1 被 simpl 成 n+(n+0)+1 *)
  replace (n + (n + 0) + 1)%nat with (2 * n + 1)%nat by lia.
  rewrite (Nat2Pos.id (2 * n + 1) ltac:(lia)).
  rewrite (Nat2Pos.id (nfact (2 * n + 1)) ltac:(apply Nat.neq_0_lt_0; apply nfact_pos)).
  apply nfact_ge_n.
Qed.

(* 1/(2(p+1)+1) ≤ 1/p（p ≥ 1） *)
Lemma sin_a_recip_le_1p (p : positive) :
  CR_of_Q R (1 # Pos.of_nat (2 * Pos.to_nat p + 3)) <=
  CR_of_Q R (1 # Pos.of_nat (Pos.to_nat p)).
Proof.
  apply CR_of_Q_le. unfold Qle. cbn [Qnum Qden]. simpl.
  rewrite <- !positive_nat_Z.
  apply Nat2Z.inj_le.
  (* nat 层：Pos.to_nat (Pos.of_nat (Pos.to_nat p)) == Pos.to_nat p *)
  rewrite (Nat2Pos.id (Pos.to_nat p) ltac:(apply Nat.neq_0_lt_0; apply Pos2Nat.is_pos)).
  replace (Pos.to_nat p + (Pos.to_nat p + 0) + 3)%nat with (2 * Pos.to_nat p + 3)%nat by lia.
  rewrite (Nat2Pos.id (2 * Pos.to_nat p + 3) ltac:(lia)).
  lia.
Qed.

(* sin_a x (p+1) ≤ 1/p（0 ≤ x ≤ 1），RHS 归一为 1#p *)
Lemma sin_a_bound_1p (x : CRcarrier R) (Hx0 : 0 <= x) (Hx1 : x <= 1) (p : positive) :
  sin_a x (Pos.to_nat p + 1) <= CR_of_Q R (1 # p).
Proof.
  apply (CRle_trans _ (CR_of_Q R (1 # Pos.of_nat (Pos.to_nat p))) _).
  - apply (CRle_trans _ (CR_of_Q R (1 # Pos.of_nat (nfact (2 * (Pos.to_nat p + 1) + 1)))) _).
    + apply sin_a_coef_bound. exact Hx0. exact Hx1.
    + apply (CRle_trans _ (CR_of_Q R (1 # Pos.of_nat (2 * (Pos.to_nat p + 1) + 1))) _).
      * apply sin_a_coef_le_recip.
      * (* 1/(2(p+1)+1) == 1/(2p+3) ≤ 1/p *)
        replace (2 * (Pos.to_nat p + 1) + 1)%nat with (2 * Pos.to_nat p + 3)%nat by lia.
        apply sin_a_recip_le_1p.
  - (* 1#Pos.of_nat (Pos.to_nat p) ≤ 1#p *)
    apply (proj2 (CR_of_Q_morph R (1 # Pos.of_nat (Pos.to_nat p)) (1 # p)
                  ltac:(unfold Qeq; simpl; rewrite Pos2Nat.id; lia))).
Qed.

(* Cauchy 性：|S_i - S_j| ≤ 1/p（i,j ≥ p） *)
Lemma sin_cauchy (x : CRcarrier R) (Hx0 : 0 <= x) (Hx1 : x <= 1) :
  CR_cauchy R (alt_partial (sin_a x)).
Proof.
  intros p.
  exists (Pos.to_nat p).
  intros i j Hi Hj.
  destruct (Nat.le_ge_cases i j) as [Hij|Hji].
  - destruct (Nat.lt_ge_cases i j) as [Hijlt|Hige].
    + rewrite (CRabs_minus_sym (alt_partial (sin_a x) i) (alt_partial (sin_a x) j)).
      apply (CRle_trans _ (sin_a x (i + 1)%nat) _).
      * apply (sin_gap x Hx0 Hx1). exact Hijlt.
      * apply (CRle_trans _ (sin_a x (Pos.to_nat p + 1)%nat) _).
        -- apply sin_a_decr. exact Hx0. exact Hx1. lia.
        -- apply (sin_a_bound_1p x Hx0 Hx1 p).
    + replace j with i by lia.
      apply (CRle_trans _ (CR_of_Q R (0 # 1)) _).
      * apply (proj2 (CRle_morph R
                 (CRabs R (alt_partial (sin_a x) i - alt_partial (sin_a x) i))
                 (CRabs R (CR_of_Q R (0 # 1)))
                 ltac:(apply (CRabs_morph_prop R (alt_partial (sin_a x) i - alt_partial (sin_a x) i) (CR_of_Q R (0 # 1)));
                       unfold CRminus;
                       rewrite (CRplus_opp_r (alt_partial (sin_a x) i));
                       apply CReq_refl)
                 (CR_of_Q R (0 # 1)) (CR_of_Q R (0 # 1)) (CReq_refl _))).
        apply abs_0_le. apply CRle_refl.
      * apply CR_of_Q_le. unfold Qle. simpl. lia.
  - destruct (Nat.lt_ge_cases j i) as [Hjilt|Hjge].
    + apply (CRle_trans _ (sin_a x (j + 1)%nat) _).
      * apply (sin_gap x Hx0 Hx1). exact Hjilt.
      * apply (CRle_trans _ (sin_a x (Pos.to_nat p + 1)%nat) _).
        -- apply sin_a_decr. exact Hx0. exact Hx1. lia.
        -- apply (sin_a_bound_1p x Hx0 Hx1 p).
    + replace i with j by lia.
      apply (CRle_trans _ (CR_of_Q R (0 # 1)) _).
      * apply (proj2 (CRle_morph R
                 (CRabs R (alt_partial (sin_a x) j - alt_partial (sin_a x) j))
                 (CRabs R (CR_of_Q R (0 # 1)))
                 ltac:(apply (CRabs_morph_prop R (alt_partial (sin_a x) j - alt_partial (sin_a x) j) (CR_of_Q R (0 # 1)));
                       unfold CRminus;
                       rewrite (CRplus_opp_r (alt_partial (sin_a x) j));
                       apply CReq_refl)
                 (CR_of_Q R (0 # 1)) (CR_of_Q R (0 # 1)) (CReq_refl _))).
        apply abs_0_le. apply CRle_refl.
      * apply CR_of_Q_le. unfold Qle. simpl. lia.
Qed.

(* sin 定义（0 ≤ x ≤ 1 时收敛） *)
Definition CRsin_bounded (x : CRcarrier R) (Hx0 : 0 <= x) (Hx1 : x <= 1) : CRcarrier R :=
  projT1 (CR_complete R (alt_partial (sin_a x)) (sin_cauchy x Hx0 Hx1)).

Lemma sin_cv (x : CRcarrier R) (Hx0 : 0 <= x) (Hx1 : x <= 1) :
  CR_cv R (alt_partial (sin_a x)) (CRsin_bounded x Hx0 Hx1).
Proof. exact (projT2 (CR_complete R (alt_partial (sin_a x)) (sin_cauchy x Hx0 Hx1))). Qed.

(* 余项：|sin x - S_N| ≤ sin_a x (N+1)（0 ≤ x ≤ 1） *)
Lemma sin_remainder (x : CRcarrier R) (Hx0 : 0 <= x) (Hx1 : x <= 1) (N : nat) :
  CRle R (CRabs R (CRsin_bounded x Hx0 Hx1 - alt_partial (sin_a x) N)) (sin_a x (N + 1)).
Proof.
  assert (Hcv : CR_cv R (fun M => sin_tail_partial x N M)
                          (CRsin_bounded x Hx0 Hx1 - alt_partial (sin_a x) N)).
  { apply (CR_cv_eq (fun M => sin_tail_partial x N M)
                    (fun M => alt_partial (sin_a x) (N + 1 + M) - alt_partial (sin_a x) N)
                    (CRsin_bounded x Hx0 Hx1 - alt_partial (sin_a x) N)).
    - intros M. apply sin_S_tail_eq.
    - apply (CR_cv_minus (fun M => alt_partial (sin_a x) (N + 1 + M))
                         (fun _ => alt_partial (sin_a x) N)
                         (CRsin_bounded x Hx0 Hx1) (alt_partial (sin_a x) N)).
      + intros p. destruct (sin_cv x Hx0 Hx1 p) as [N0 HN0]. exists N0. intros m Hm.
        apply HN0. lia.
      + apply CR_cv_const. }
  apply (proj1 (CRabs_def R (CRsin_bounded x Hx0 Hx1 - alt_partial (sin_a x) N) (sin_a x (N + 1)))).
  split.
  - apply (CR_cv_bound_up (fun M => sin_tail_partial x N M) (sin_a x (N + 1))
                          (CRsin_bounded x Hx0 Hx1 - alt_partial (sin_a x) N) 0).
    + intros M H. apply (proj1 (CRabs_def2 (sin_tail_partial x N M) (sin_a x (N + 1))
                                           (sin_tail_partial_bound x Hx0 Hx1 N M))).
    + exact Hcv.
  - apply (proj2 (CRle_morph R (- (CRsin_bounded x Hx0 Hx1 - alt_partial (sin_a x) N))
            (- (CRsin_bounded x Hx0 Hx1 - alt_partial (sin_a x) N)) (CReq_refl _)
            (sin_a x (N + 1)) (- (- (sin_a x (N + 1))))
            ltac:(apply CReq_sym; ring))).
    apply (CRopp_ge_le_contravar (CRsin_bounded x Hx0 Hx1 - alt_partial (sin_a x) N) (- (sin_a x (N + 1)))).
    apply (CR_cv_bound_down (fun M => sin_tail_partial x N M) (- (sin_a x (N + 1)))
                            (CRsin_bounded x Hx0 Hx1 - alt_partial (sin_a x) N) 0).
    + intros M H.
      apply (proj2 (CRabs_def2 (sin_tail_partial x N M) (sin_a x (N + 1))
                                (sin_tail_partial_bound x Hx0 Hx1 N M))).
    + exact Hcv.
Qed.

(* ============ Taylor 数值界 ============ *)

(* sin_a 递减条件（给 alt_even_decr/alt_odd_incr） *)
Lemma sin_a_decr_step (x : CRcarrier R) (Hx0 : 0 <= x) (Hx1 : x <= 1) (k : nat) :
  sin_a x (S k) <= sin_a x k.
Proof. apply sin_a_S_le. exact Hx0. exact Hx1. Qed.

(* 奇部分和递增（多步） *)
Lemma sin_odd_incr_multi (x : CRcarrier R) (Hx0 : 0 <= x) (Hx1 : x <= 1) (m n : nat) :
  (m <= n)%nat ->
  CRle R (alt_partial (sin_a x) (2 * m + 1)%nat) (alt_partial (sin_a x) (2 * n + 1)%nat).
Proof.
  intros H. induction n as [|n IHn].
  - destruct (Nat.eq_dec m 0); subst; [apply CRle_refl | lia].
  - destruct (Nat.lt_ge_cases m (S n)) as [Hlt|Hge].
    + apply (CRle_trans _ (alt_partial (sin_a x) (2 * n + 1)%nat) _).
      * apply IHn. lia.
      * apply (alt_odd_incr (sin_a x) n). intros k. apply sin_a_decr_step. exact Hx0. exact Hx1.
    + assert (m = S n) by lia. subst. apply CRle_refl.
Qed.

(* 偶部分和递减（多步） *)
Lemma sin_even_decr_multi (x : CRcarrier R) (Hx0 : 0 <= x) (Hx1 : x <= 1) (m n : nat) :
  (m <= n)%nat ->
  CRle R (alt_partial (sin_a x) (2 * n)%nat) (alt_partial (sin_a x) (2 * m)%nat).
Proof.
  intros H. induction n as [|n IHn].
  - destruct (Nat.eq_dec m 0); subst; [apply CRle_refl | lia].
  - destruct (Nat.lt_ge_cases m (S n)) as [Hlt|Hge].
    + apply (CRle_trans _ (alt_partial (sin_a x) (2 * n)%nat) _).
      * apply (alt_even_decr (sin_a x) n). intros k. apply sin_a_decr_step. exact Hx0. exact Hx1.
      * apply IHn. lia.
    + assert (m = S n) by lia. subst. apply CRle_refl.
Qed.

(* 奇子列收敛 → sin x *)
Lemma sin_odd_subseq_cv (x : CRcarrier R) (Hx0 : 0 <= x) (Hx1 : x <= 1) :
  CR_cv R (fun n => alt_partial (sin_a x) (2 * n + 1)%nat) (CRsin_bounded x Hx0 Hx1).
Proof.
  intros p. destruct (sin_cv x Hx0 Hx1 p) as [N HN]. exists N. intros m Hm.
  apply HN. lia.
Qed.

(* 偶子列收敛 → sin x *)
Lemma sin_even_subseq_cv (x : CRcarrier R) (Hx0 : 0 <= x) (Hx1 : x <= 1) :
  CR_cv R (fun n => alt_partial (sin_a x) (2 * n)%nat) (CRsin_bounded x Hx0 Hx1).
Proof.
  intros p. destruct (sin_cv x Hx0 Hx1 p) as [N HN]. exists N. intros m Hm.
  apply HN. lia.
Qed.

(* 下界：S_{2M+1} ≤ sin x *)
Lemma sin_odd_le (x : CRcarrier R) (Hx0 : 0 <= x) (Hx1 : x <= 1) (M : nat) :
  CRle R (alt_partial (sin_a x) (2 * M + 1)%nat) (CRsin_bounded x Hx0 Hx1).
Proof.
  apply (CR_cv_bound_down (fun n => alt_partial (sin_a x) (2 * n + 1)%nat)
          (alt_partial (sin_a x) (2 * M + 1)%nat) (CRsin_bounded x Hx0 Hx1) M).
  - intros n Hn.
    apply (sin_odd_incr_multi x Hx0 Hx1 M n). exact Hn.
  - apply sin_odd_subseq_cv.
Qed.

(* 上界：sin x ≤ S_{2M} *)
Lemma sin_even_ge (x : CRcarrier R) (Hx0 : 0 <= x) (Hx1 : x <= 1) (M : nat) :
  CRle R (CRsin_bounded x Hx0 Hx1) (alt_partial (sin_a x) (2 * M)%nat).
Proof.
  apply (CR_cv_bound_up (fun n => alt_partial (sin_a x) (2 * n)%nat)
          (alt_partial (sin_a x) (2 * M)%nat) (CRsin_bounded x Hx0 Hx1) M).
  - intros n Hn. apply (sin_even_decr_multi x Hx0 Hx1 M n). exact Hn.
  - apply sin_even_subseq_cv.
Qed.

(* ============ 多项式展开：S_3 / S_5 ============ *)

(* 幂重写：x_pow x 1 == x *)
Lemma x_pow_1 (x : CRcarrier R) : CReq R (x_pow x 1) x.
Proof.
  cbn [x_pow]. ring.
Qed.

(* x_pow x 3 == x * (x * x) *)
Lemma x_pow_3 (x : CRcarrier R) : CReq R (x_pow x 3) (x * x * x).
Proof.
  cbn [x_pow]. ring.
Qed.

(* sin_a x 0 == x *)
Lemma sin_a_0 (x : CRcarrier R) : CReq R (sin_a x 0) x.
Proof.
  unfold sin_a.
  replace (2 * 0 + 1)%nat with 1%nat by lia.
  (* 1#nfact 1 == 1#1 *)
  replace (Pos.of_nat (nfact 1)) with 1%positive by (vm_compute; reflexivity).
  (* CR_of_Q (1#1) * x_pow x 1 == 1 * x == x（CR_of_Q (1#1) 定义上 = 1） *)
  transitivity (1 * x).
  - apply (CRmult_morph_Proper
             (CR_of_Q R (1 # 1)) 1 (CReq_refl _)
             (x_pow x 1) x (x_pow_1 x)).
  - ring.
Qed.

(* sin_a x 1 == x³/6 *)
Lemma sin_a_1 (x : CRcarrier R) :
  CReq R (sin_a x 1) (CR_of_Q R (1 # 6) * (x * x * x)).
Proof.
  unfold sin_a.
  replace (2 * 1 + 1)%nat with 3%nat by lia.
  (* nfact 3 == 6 *)
  replace (Pos.of_nat (nfact 3)) with 6%positive by (vm_compute; reflexivity).
  (* CR_of_Q (1#Pos.of_nat 6) == CR_of_Q (1#6) *)
  transitivity (CR_of_Q R (1 # Pos.of_nat 6) * (x * x * x)).
  - apply (CRmult_morph_Proper
             (CR_of_Q R (1 # Pos.of_nat 6)) (CR_of_Q R (1 # Pos.of_nat 6)) (CReq_refl _)
             (x_pow x 3) (x * x * x) (x_pow_3 x)).
  - apply (CRmult_morph_Proper
             (CR_of_Q R (1 # Pos.of_nat 6)) (CR_of_Q R (1 # 6))
             ltac:(apply (CR_of_Q_morph R (1 # Pos.of_nat 6) (1 # 6)); vm_compute; reflexivity)
             (x * x * x) (x * x * x) (CReq_refl _)).
Qed.

(* 符号归一：CR_of_Q (1#1) == 1、CR_of_Q (-1#1) == -1 *)
Lemma sign_one : CReq R (CR_of_Q R (1 # 1)) (1 : CRcarrier R).
Proof. reflexivity. Qed.

Lemma sign_minus_one : CReq R (CR_of_Q R (-1 # 1)) (- (1 : CRcarrier R)).
Proof.
  transitivity (- CR_of_Q R (1 # 1)).
  - apply CR_of_Q_opp.
  - apply CReq_refl.
Qed.

(* S_1 == x - x³/6（Taylor 3 阶：k=0 正，k=1 负） *)
Lemma sin_S3_poly (x : CRcarrier R) :
  CReq R (alt_partial (sin_a x) 1) (x - CR_of_Q R (1 # 6) * (x * x * x)).
Proof.
  unfold alt_partial.
  cbn [CRsum].
  rewrite (sin_a_0 x).
  replace (alt_sign 0) with (CR_of_Q R (1 # 1)) by (unfold alt_sign; cbn; reflexivity).
  rewrite (sin_a_1 x).
  replace (alt_sign 1) with (CR_of_Q R (-1 # 1)) by (unfold alt_sign; cbn; reflexivity).
  (* 归一符号：CR_of_Q (1#1)·x == 1·x、CR_of_Q (-1#1)·(1/6·x³) == (-1)·(1/6·x³) *)
  transitivity (1 * x + (- (1 : CRcarrier R)) * (CR_of_Q R (1 # 6) * (x * x * x))).
  - apply (CRplus_morph_Proper
             (CR_of_Q R (1 # 1) * x) (1 * x)
             ltac:(apply (CRmult_morph_Proper (CR_of_Q R (1 # 1)) 1 sign_one x x (CReq_refl _)))
             (CR_of_Q R (-1 # 1) * (CR_of_Q R (1 # 6) * (x * x * x)))
             ((- (1 : CRcarrier R)) * (CR_of_Q R (1 # 6) * (x * x * x)))
             ltac:(apply (CRmult_morph_Proper (CR_of_Q R (-1 # 1)) (- (1 : CRcarrier R)) sign_minus_one
                          (CR_of_Q R (1 # 6) * (x * x * x)) (CR_of_Q R (1 # 6) * (x * x * x)) (CReq_refl _)))).
  - unfold CRminus. ring.
Qed.

(* sin_a x 2 == x⁵/120 *)
Lemma sin_a_2 (x : CRcarrier R) :
  CReq R (sin_a x 2) (CR_of_Q R (1 # 120) * (x * x * x * x * x)).
Proof.
  unfold sin_a.
  replace (2 * 2 + 1)%nat with 5%nat by lia.
  (* nfact 5 == 120 *)
  replace (Pos.of_nat (nfact 5)) with 120%positive by (vm_compute; reflexivity).
  (* x_pow x 5 == x⁵ *)
  transitivity (CR_of_Q R (1 # Pos.of_nat 120) * (x * x * x * x * x)).
  - apply (CRmult_morph_Proper
             (CR_of_Q R (1 # Pos.of_nat 120)) (CR_of_Q R (1 # Pos.of_nat 120)) (CReq_refl _)
             (x_pow x 5) (x * x * x * x * x)
             ltac:(cbn [x_pow]; ring)).
  - apply (CRmult_morph_Proper
             (CR_of_Q R (1 # Pos.of_nat 120)) (CR_of_Q R (1 # 120))
             ltac:(apply (CR_of_Q_morph R (1 # Pos.of_nat 120) (1 # 120)); vm_compute; reflexivity)
             (x * x * x * x * x) (x * x * x * x * x) (CReq_refl _)).
Qed.

(* S_2 == x - x³/6 + x⁵/120（Taylor 5 阶：k=0 正，k=1 负，k=2 正） *)
Lemma sin_S5_poly (x : CRcarrier R) :
  CReq R (alt_partial (sin_a x) 2)
         (x - CR_of_Q R (1 # 6) * (x * x * x) + CR_of_Q R (1 # 120) * (x * x * x * x * x)).
Proof.
  unfold alt_partial.
  cbn [CRsum].
  rewrite (sin_a_0 x).
  replace (alt_sign 0) with (CR_of_Q R (1 # 1)) by (unfold alt_sign; cbn; reflexivity).
  rewrite (sin_a_1 x).
  replace (alt_sign 1) with (CR_of_Q R (-1 # 1)) by (unfold alt_sign; cbn; reflexivity).
  rewrite (sin_a_2 x).
  replace (alt_sign 2) with (CR_of_Q R (1 # 1)) by (unfold alt_sign; cbn; reflexivity).
  (* 归一符号后 ring（unfold CRminus） *)
  transitivity (1 * x + (- (1 : CRcarrier R)) * (CR_of_Q R (1 # 6) * (x * x * x))
                + 1 * (CR_of_Q R (1 # 120) * (x * x * x * x * x))).
  - apply (CRplus_morph_Proper
             (CR_of_Q R (1 # 1) * x + CR_of_Q R (-1 # 1) * (CR_of_Q R (1 # 6) * (x * x * x)))
             (1 * x + (- (1 : CRcarrier R)) * (CR_of_Q R (1 # 6) * (x * x * x)))
             ltac:(apply (CRplus_morph_Proper
                            (CR_of_Q R (1 # 1) * x) (1 * x)
                            ltac:(apply (CRmult_morph_Proper (CR_of_Q R (1 # 1)) 1 sign_one x x (CReq_refl _)))
                            (CR_of_Q R (-1 # 1) * (CR_of_Q R (1 # 6) * (x * x * x)))
                            ((- (1 : CRcarrier R)) * (CR_of_Q R (1 # 6) * (x * x * x)))
                            ltac:(apply (CRmult_morph_Proper (CR_of_Q R (-1 # 1)) (- (1 : CRcarrier R)) sign_minus_one
                                         (CR_of_Q R (1 # 6) * (x * x * x)) (CR_of_Q R (1 # 6) * (x * x * x)) (CReq_refl _)))))
             (CR_of_Q R (1 # 1) * (CR_of_Q R (1 # 120) * (x * x * x * x * x)))
             (1 * (CR_of_Q R (1 # 120) * (x * x * x * x * x)))
             ltac:(apply (CRmult_morph_Proper (CR_of_Q R (1 # 1)) 1 sign_one
                          (CR_of_Q R (1 # 120) * (x * x * x * x * x)) (CR_of_Q R (1 # 120) * (x * x * x * x * x)) (CReq_refl _)))).
  - unfold CRminus. ring.
Qed.

(* Taylor 下界：x - x³/6 ≤ sin x（0 ≤ x ≤ 1） *)
Lemma sin_taylor_lower (x : CRcarrier R) (Hx0 : 0 <= x) (Hx1 : x <= 1) :
  CRle R (x - CR_of_Q R (1 # 6) * (x * x * x)) (CRsin_bounded x Hx0 Hx1).
Proof.
  apply (CRle_trans _ (alt_partial (sin_a x) 1) _).
  - apply (proj1 (sin_S3_poly x)).
  - apply (sin_odd_le x Hx0 Hx1 0).
Qed.

(* Taylor 上界：sin x ≤ x - x³/6 + x⁵/120（0 ≤ x ≤ 1） *)
Lemma sin_taylor_upper (x : CRcarrier R) (Hx0 : 0 <= x) (Hx1 : x <= 1) :
  CRle R (CRsin_bounded x Hx0 Hx1)
         (x - CR_of_Q R (1 # 6) * (x * x * x) + CR_of_Q R (1 # 120) * (x * x * x * x * x)).
Proof.
  apply (CRle_trans _ (alt_partial (sin_a x) 2) _).
  - apply (sin_even_ge x Hx0 Hx1 1).
  - apply (proj2 (sin_S5_poly x)).
Qed.

End M2.

(* ============================================================
   M2 扩展（M2E）：定义域 [0, 2] 的 CRsin（M4 G-5 主探针需求）
   项递减：x² ≤ 4 < 6（c_0 = 1/6）；Cauchy：x_pow ≤ 2^n 且
   N·2^{2N+3} ≤ (2N+3)!（nat 归纳）；sin_odd_le/sin_even_ge 任意阶 Taylor 界
   ============================================================ *)

Section M2E.

Context {R : ConstructiveReals}.
Add Ring CR_ring : (CRisRing R).

(* 幂单调：0 ≤ x ≤ y ⟹ x_pow x n ≤ x_pow y n *)
Lemma m2e_x_pow_mono (x y : CRcarrier R) (Hx0 : 0 <= x) (Hxy : x <= y) (n : nat) :
  x_pow x n <= x_pow y n.
Proof.
  induction n.
  - cbn [x_pow]. apply CRle_refl.
  - cbn [x_pow].
    apply (CRle_trans _ (x_pow x n * y) _).
    + apply (CRmult_le_compat_l (x_pow x n) x y).
      * apply x_pow_nonneg. exact Hx0.
      * exact Hxy.
    + apply (CRmult_le_compat_r y (x_pow x n) (x_pow y n)).
      * apply (CRle_trans _ x _). exact Hx0. exact Hxy.
      * exact IHn.
Qed.

(* x_pow (CR_of_Q 2) n == CR_of_Q (2^n 的 Q 表示) *)
Lemma m2e_x_pow_2 (n : nat) :
  CReq R (x_pow (CR_of_Q R (2 # 1)) n) (CR_of_Q R (Z.of_nat (2 ^ n) # 1)).
Proof.
  induction n.
  - cbn [x_pow].
    apply (CR_of_Q_morph R (1 # 1) (Z.of_nat (2 ^ 0) # 1)).
    unfold Qeq. simpl. lia.
  - cbn [x_pow].
    rewrite IHn.
    transitivity (CR_of_Q R ((Z.of_nat (2 ^ n) # 1) * (2 # 1))).
    + apply CReq_sym. apply CR_of_Q_mult.
    + apply (CR_of_Q_morph R ((Z.of_nat (2 ^ n) # 1) * (2 # 1)) (Z.of_nat (2 ^ S n) # 1)).
      unfold Qeq. simpl.
      rewrite Nat2Z.inj_add.
      rewrite Nat2Z.inj_add.
      simpl.
      lia.
Qed.

(* 幂 ≤ 2^n：0 ≤ x ≤ 2 ⟹ x_pow x n ≤ CR_of_Q (2^n) *)
Lemma m2e_x_pow_le_2 (x : CRcarrier R) (Hx0 : 0 <= x) (Hx2 : x <= CR_of_Q R (2 # 1)) (n : nat) :
  x_pow x n <= CR_of_Q R (Z.of_nat (2 ^ n) # 1).
Proof.
  apply (CRle_trans _ (x_pow (CR_of_Q R (2 # 1)) n) _).
  - apply (m2e_x_pow_mono x (CR_of_Q R (2 # 1)) Hx0 Hx2).
  - apply (proj2 (CRle_morph R
       (x_pow (CR_of_Q R (2 # 1)) n) (CR_of_Q R (Z.of_nat (2 ^ n) # 1))
       (m2e_x_pow_2 n)
       (CR_of_Q R (Z.of_nat (2 ^ n) # 1)) (CR_of_Q R (Z.of_nat (2 ^ n) # 1))
       (CReq_refl _))).
    apply CRle_refl.
Qed.

(* x ≤ 2 ⟹ x_pow x 2 ≤ 4（特例，用 CR_of_Q） *)
Lemma m2e_x_pow2_le_4 (x : CRcarrier R) (Hx0 : 0 <= x) (Hx2 : x <= CR_of_Q R (2 # 1)) :
  x_pow x 2 <= CR_of_Q R (4 # 1).
Proof.
  replace (CR_of_Q R (4 # 1)) with (CR_of_Q R (Z.of_nat (2 ^ 2) # 1)) by (vm_compute; reflexivity).
  apply m2e_x_pow_le_2. exact Hx0. exact Hx2.
Qed.

(* 系数界：1/((2k+2)(2k+3)) ≤ 1/6 *)
Lemma m2e_coef_le_6 (k : nat) :
  CR_of_Q R (1 # Pos.of_nat ((2 * k + 2) * (2 * k + 3))) <= CR_of_Q R (1 # 6).
Proof.
  apply CR_of_Q_le. unfold Qle. simpl. lia.
Qed.

(* 4·(1/6) ≤ 1（Q 层） *)
Lemma m2e_4_6_le_1 : CRle R (CR_of_Q R (4 # 1) * CR_of_Q R (1 # 6)) (CR_of_Q R (1 # 1)).
Proof.
  apply (proj2 (CRle_morph R
     (CR_of_Q R (4 # 1) * CR_of_Q R (1 # 6))
     (CR_of_Q R ((4 # 1) * (1 # 6)))
     (CReq_sym _ _ (CR_of_Q_mult R (4 # 1) (1 # 6)))
     (CR_of_Q R (1 # 1)) (CR_of_Q R (1 # 1)) (CReq_refl _))).
  apply CR_of_Q_le.
  unfold Qle. simpl. lia.
Qed.

(* 项递减：0 ≤ x ≤ 2 ⟹ sin_a x (S k) ≤ sin_a x k *)
Lemma m2e_sin_a_S_le (x : CRcarrier R) (Hx0 : 0 <= x) (Hx2 : x <= CR_of_Q R (2 # 1)) (k : nat) :
  sin_a x (S k) <= sin_a x k.
Proof.
  rewrite sin_a_S.
  apply (CRle_trans _ (sin_a x k * 1) _).
  - apply (CRle_morph R
       (sin_a x k * x_pow x 2 * CR_of_Q R (1 # Pos.of_nat ((2 * k + 2) * (2 * k + 3))))
       (sin_a x k * (x_pow x 2 * CR_of_Q R (1 # Pos.of_nat ((2 * k + 2) * (2 * k + 3)))))
       ltac:(ring)
       (sin_a x k * 1) (sin_a x k * 1) (CReq_refl _)).
    apply (CRmult_le_compat_l (sin_a x k)
                              (x_pow x 2 * CR_of_Q R (1 # Pos.of_nat ((2 * k + 2) * (2 * k + 3))))
                              1).
    + apply sin_a_nonneg. exact Hx0.
    + (* x_pow x 2 * c_k ≤ 1：≤ 4·(1/6) ≤ 1 *)
      apply (CRle_trans _ (CR_of_Q R (4 # 1) * CR_of_Q R (1 # 6)) _).
      * (* x_pow x 2 * c_k ≤ 4·(1/6)：x_pow x 2 ≤ 4、c_k ≤ 1/6、非负组合 *)
        apply (CRle_trans _ (CR_of_Q R (4 # 1) * CR_of_Q R (1 # Pos.of_nat ((2 * k + 2) * (2 * k + 3)))) _).
        -- (* x_pow x 2 · c_k ≤ 4·c_k（右乘单调） *)
           apply (CRmult_le_compat_r (CR_of_Q R (1 # Pos.of_nat ((2 * k + 2) * (2 * k + 3))))
                                     (x_pow x 2) (CR_of_Q R (4 # 1))).
           ++ apply CR_of_Q_le. unfold Qle. simpl. lia.
           ++ exact (m2e_x_pow2_le_4 x Hx0 Hx2).
        -- (* 4·c_k ≤ 4·(1/6)（左乘单调） *)
           apply (CRmult_le_compat_l (CR_of_Q R (4 # 1))
                                     (CR_of_Q R (1 # Pos.of_nat ((2 * k + 2) * (2 * k + 3))))
                                     (CR_of_Q R (1 # 6))).
           ++ apply CR_of_Q_le. unfold Qle. simpl. lia.
           ++ exact (m2e_coef_le_6 k).
      * exact m2e_4_6_le_1.
  - apply (CRle_morph R (sin_a x k * 1) (sin_a x k) ltac:(ring)
                        (sin_a x k) (sin_a x k) (CReq_refl _)).
    apply CRle_refl.
Qed.

(* 多步递减：m ≤ n ⟹ sin_a x n ≤ sin_a x m（0 ≤ x ≤ 2） *)
Lemma m2e_sin_a_decr (x : CRcarrier R) (Hx0 : 0 <= x) (Hx2 : x <= CR_of_Q R (2 # 1)) (k m : nat) :
  (k <= m)%nat -> sin_a x m <= sin_a x k.
Proof.
  intros Hkm.
  induction m.
  - assert (k = 0%nat) by lia. subst. apply CRle_refl.
  - destruct (Nat.eq_dec k (S m)) as [Hk | Hk].
    + subst. apply CRle_refl.
    + apply (CRle_trans _ (sin_a x m) _).
      * apply (m2e_sin_a_S_le x Hx0 Hx2).
      * apply IHm. lia.
Qed.

(* 尾平移部分和界：|sin_tail N M| ≤ sin_a x (N+1)（0 ≤ x ≤ 2） *)
Lemma m2e_sin_tail_partial_bound (x : CRcarrier R) (Hx0 : 0 <= x) (Hx2 : x <= CR_of_Q R (2 # 1)) (N M : nat) :
  CRle R (CRabs R (sin_tail_partial x N M)) (sin_a x (N + 1)).
Proof.
  rewrite (sin_tail_sign_split x N M).
  rewrite (CRabs_mult (alt_sign (N + 1)) _).
  apply (CRle_trans _ (CR_of_Q R (1 # 1) * CRabs R (CRsum (fun k => alt_sign k * sin_a x (N + 1 + k)) M)) _).
  - apply (CRmult_le_compat_r (CRabs R (CRsum (fun k => alt_sign k * sin_a x (N + 1 + k)) M))).
    + apply (CRabs_pos (CRsum (fun k => alt_sign k * sin_a x (N + 1 + k)) M)).
    + destruct (Nat.odd (N + 1)) eqn:Hodd.
      * unfold alt_sign. rewrite Hodd. apply abs_minus_one_le.
      * unfold alt_sign. rewrite Hodd. apply abs_one_le.
  - rewrite (CRmult_1_l (CRabs R (CRsum (fun k => alt_sign k * sin_a x (N + 1 + k)) M))).
    apply (CRle_trans _ (sin_a x (N + 1)) _).
    + change (CRle R (CRabs R (alt_partial (fun k => sin_a x (N + 1 + k)) M)) (sin_a x (N + 1))).
      apply (CRle_trans _ (sin_a x (N + 1 + 0)) _).
      * apply (alt_series_remainder (fun k => sin_a x (N + 1 + k)) M).
        -- intros k. apply sin_a_nonneg. exact Hx0.
        -- intros k. apply (m2e_sin_a_decr x Hx0 Hx2 (N + 1 + k) (N + 1 + S k)).
           lia.
      * replace (N + 1 + 0)%nat with (N + 1)%nat by lia.
        apply CRle_refl.
    + apply CRle_refl.
Qed.

(* gap：i < j ⟹ |S_j - S_i| ≤ sin_a x (i+1)（0 ≤ x ≤ 2） *)
Lemma m2e_sin_gap (x : CRcarrier R) (Hx0 : 0 <= x) (Hx2 : x <= CR_of_Q R (2 # 1)) (i j : nat) :
  (i < j)%nat ->
  CRle R (CRabs R (alt_partial (sin_a x) j - alt_partial (sin_a x) i)) (sin_a x (i + 1)%nat).
Proof.
  intros Hij.
  set (M := (j - i - 1)%nat).
  assert (Hnat : (i + 1 + M)%nat = j) by (subst M; lia).
  assert (Heq : CReq R (alt_partial (sin_a x) j - alt_partial (sin_a x) i) (sin_tail_partial x i M)).
  { rewrite <- Hnat. apply sin_S_tail_eq. }
  rewrite (CRabs_morph_prop R (alt_partial (sin_a x) j - alt_partial (sin_a x) i)
                              (sin_tail_partial x i M) Heq).
  apply (m2e_sin_tail_partial_bound x Hx0 Hx2 i M).
Qed.

(* nat 层：N·2^{2N+3} ≤ (2N+3)!（N ≥ 1）——Cauchy 界核心 *)
Lemma m2e_N_2pow_le_fact (N : nat) (HN : (1 <= N)%nat) :
  (N * 2 ^ (2 * N + 3) <= nfact (2 * N + 3))%nat.
Proof.
  induction N as [|n IHn].
  - lia.  (* N=0：HN 矛盾 *)
  - (* 目标：S n · 2^{2·S n+3} <= nfact(2·S n+3) *)
    destruct n as [|n'].
    + (* n=0：N=1 base：1·2⁵ = 32 ≤ 5! = 120 *)
      cbn [nfact].
      replace (2 * 1 + 3)%nat with 5%nat by lia.
      cbn [nfact]. simpl. lia.
    + (* n = S n' ≥ 1 *)
      assert (Hih : (S n' * 2 ^ (2 * S n' + 3) <= nfact (2 * S n' + 3))%nat).
      { apply IHn. lia. }
      (* 由 Hih：2^{2·S n'+3} ≤ nfact(2·S n'+3)（S n' ≥ 1） *)
      assert (Hpow : (2 ^ (2 * S n' + 3) <= nfact (2 * S n' + 3))%nat).
      { apply (Nat.le_trans _ (S n' * 2 ^ (2 * S n' + 3)) _).
        - nia.
        - exact Hih. }
      (* 指数：2^{2·S(S n')+3} = 2^{2·S n'+3+2} = 2^{2·S n'+3}·2² *)
      replace (2 * S (S n') + 3)%nat with (2 * S n' + 3 + 2)%nat by lia.
      rewrite Nat.pow_add_r.
      (* 阶乘：nfact(2·S n'+3+2) = (2·S n'+5)(2·S n'+4)·nfact(2·S n'+3) *)
      replace (2 * S n' + 3 + 2)%nat with (S (S (2 * S n' + 3)))%nat by lia.
      rewrite nfact_S. rewrite nfact_S.
      replace (2 ^ 2)%nat with 4%nat by reflexivity.
      (* 重组 LHS：S(S n')·4·2^{2·S n'+3} *)
      replace (S (S n') * (2 ^ (2 * S n' + 3) * 4))%nat
         with (S (S n') * 4 * 2 ^ (2 * S n' + 3))%nat by nia.
      (* 用 Hpow：2^{...} ≤ nfact ⟹ LHS ≤ S(S n')·4·nfact *)
      assert (Hle1 : (S (S n') * 4 * 2 ^ (2 * S n' + 3) <= S (S n') * 4 * nfact (2 * S n' + 3))%nat).
      { apply (Nat.mul_le_mono_l (2 ^ (2 * S n' + 3)) (nfact (2 * S n' + 3)) (S (S n') * 4)).
        exact Hpow. }
      apply (Nat.le_trans _ (S (S n') * 4 * nfact (2 * S n' + 3)) _).
      - exact Hle1.
      - (* S(S n')·4·nfact ≤ (2·S n'+5)(2·S n'+4)·nfact：S(S n')·4 ≤ (2·S n'+5)(2·S n'+4) *)
        nia.
Qed.

(* Q 层：1/nfact(2N+3) · 2^{2N+3} ≤ 1/N（N ≥ 1）——由 m2e_N_2pow_le_fact *)
(* Qnum 投影展开的恒等 Z match 归约辅助 *)
Lemma m2e_Zid (z : Z) :
  match z with 0%Z => 0%Z | Z.pos y => Z.pos y | Z.neg y => Z.neg y end = z.
Proof. destruct z; reflexivity. Qed.

Lemma m2e_Q_one_over (N : nat) (HN : (1 <= N)%nat) :
  Qle ((1 # Pos.of_nat (nfact (2 * N + 3))) * (Z.of_nat (2 ^ (2 * N + 3)) # 1))
      (1 # Pos.of_nat N).
Proof.
  unfold Qle. cbn [Qnum Qden]. simpl.
  (* 归约 Qnum 投影产生的恒等 Z match，化到 nat 层 *)
  rewrite (m2e_Zid (Z.of_nat ((2 ^ (N + (N + 0) + 3))%nat))).
  rewrite Pos.mul_1_r.
  rewrite <- !positive_nat_Z.
  rewrite (Nat2Pos.id N ltac:(apply Nat.neq_0_lt_0; lia)).
  rewrite (Nat2Pos.id (nfact (N + (N + 0) + 3)) ltac:(apply Nat.neq_0_lt_0; apply nfact_pos)).
  replace (N + (N + 0) + 3)%nat with (2 * N + 3)%nat by lia.
  rewrite <- (Nat2Z.inj_mul (2 ^ (2 * N + 3)) N).
  apply Nat2Z.inj_le.
  replace (2 ^ (2 * N + 3) * N)%nat with (N * 2 ^ (2 * N + 3))%nat by lia.
  exact (m2e_N_2pow_le_fact N HN).
Qed.

(* sin_a 上界：sin_a x (N+1) ≤ 1/N（0 ≤ x ≤ 2，N ≥ 1）——Cauchy 界 *)
Lemma m2e_sin_a_bound_1N (x : CRcarrier R) (Hx0 : 0 <= x) (Hx2 : x <= CR_of_Q R (2 # 1)) (N : nat) (HN : (1 <= N)%nat) :
  sin_a x (N + 1) <= CR_of_Q R (1 # Pos.of_nat N).
Proof.
  unfold sin_a.
  (* sin_a x (N+1) = c · x_pow x (2N+3) ≤ c · 2^{2N+3} ≤ 1/N *)
  replace (2 * (N + 1) + 1)%nat with (2 * N + 3)%nat by lia.
  apply (CRle_trans _ (CR_of_Q R (1 # Pos.of_nat (nfact (2 * N + 3)))
                       * CR_of_Q R (Z.of_nat (2 ^ (2 * N + 3)) # 1)) _).
  - apply (CRmult_le_compat_l (CR_of_Q R (1 # Pos.of_nat (nfact (2 * N + 3))))).
    + apply CR_of_Q_le. unfold Qle. simpl. lia.
    + apply (m2e_x_pow_le_2 x Hx0 Hx2 (2 * N + 3)).
  - (* c·2^{2N+3} ≤ 1/N：桥乘积 == CR_of_Q((1#A)·(B#1)) + m2e_Q_one_over *)
    setoid_rewrite <- (CR_of_Q_mult R (1 # Pos.of_nat (nfact (2 * N + 3))) (Z.of_nat (2 ^ (2 * N + 3)) # 1)).
    apply CR_of_Q_le.
    exact (m2e_Q_one_over N HN).
Qed.

(* 版本 p：sin_a x (Pos.to_nat p + 1) ≤ 1/p（桥 Pos.of_nat(Pos.to_nat p) == p） *)
Lemma m2e_sin_a_bound_1p (x : CRcarrier R) (Hx0 : 0 <= x) (Hx2 : x <= CR_of_Q R (2 # 1)) (p : positive) :
  sin_a x (Pos.to_nat p + 1) <= CR_of_Q R (1 # p).
Proof.
  apply (proj2 (CRle_morph R
     (sin_a x (Pos.to_nat p + 1)) (sin_a x (Pos.to_nat p + 1)) (CReq_refl _)
     (CR_of_Q R (1 # p)) (CR_of_Q R (1 # Pos.of_nat (Pos.to_nat p)))
     ltac:(apply (CR_of_Q_morph R (1 # p) (1 # Pos.of_nat (Pos.to_nat p)));
           unfold Qeq; simpl; rewrite Pos2Nat.id; lia))).
  apply (m2e_sin_a_bound_1N x Hx0 Hx2 (Pos.to_nat p)).
  apply Pos2Nat.is_pos.
Qed.

(* Cauchy 性：|S_i - S_j| ≤ 1/p（0 ≤ x ≤ 2） *)
Lemma m2e_sin_cauchy (x : CRcarrier R) (Hx0 : 0 <= x) (Hx2 : x <= CR_of_Q R (2 # 1)) :
  CR_cauchy R (alt_partial (sin_a x)).
Proof.
  intros p.
  exists (Pos.to_nat p).
  intros i j Hi Hj.
  destruct (Nat.le_ge_cases i j) as [Hij|Hji].
  - destruct (Nat.lt_ge_cases i j) as [Hijlt|Hige].
    + rewrite (CRabs_minus_sym (alt_partial (sin_a x) i) (alt_partial (sin_a x) j)).
      apply (CRle_trans _ (sin_a x (i + 1)%nat) _).
      * apply (m2e_sin_gap x Hx0 Hx2). exact Hijlt.
      * apply (CRle_trans _ (sin_a x (Pos.to_nat p + 1)%nat) _).
        -- apply (m2e_sin_a_decr x Hx0 Hx2). lia.
        -- apply (m2e_sin_a_bound_1p x Hx0 Hx2 p).
    + replace j with i by lia.
      apply (CRle_trans _ (CR_of_Q R (0 # 1)) _).
      * apply (proj2 (CRle_morph R
                 (CRabs R (alt_partial (sin_a x) i - alt_partial (sin_a x) i))
                 (CRabs R (CR_of_Q R (0 # 1)))
                 ltac:(apply (CRabs_morph_prop R (alt_partial (sin_a x) i - alt_partial (sin_a x) i) (CR_of_Q R (0 # 1)));
                       unfold CRminus;
                       rewrite (CRplus_opp_r (alt_partial (sin_a x) i));
                       apply CReq_refl)
                 (CR_of_Q R (0 # 1)) (CR_of_Q R (0 # 1)) (CReq_refl _))).
        apply abs_0_le. apply CRle_refl.
      * apply CR_of_Q_le. unfold Qle. simpl. lia.
  - destruct (Nat.lt_ge_cases j i) as [Hjilt|Hjge].
    + apply (CRle_trans _ (sin_a x (j + 1)%nat) _).
      * apply (m2e_sin_gap x Hx0 Hx2). exact Hjilt.
      * apply (CRle_trans _ (sin_a x (Pos.to_nat p + 1)%nat) _).
        -- apply (m2e_sin_a_decr x Hx0 Hx2). lia.
        -- apply (m2e_sin_a_bound_1p x Hx0 Hx2 p).
    + replace i with j by lia.
      apply (CRle_trans _ (CR_of_Q R (0 # 1)) _).
      * apply (proj2 (CRle_morph R
                 (CRabs R (alt_partial (sin_a x) j - alt_partial (sin_a x) j))
                 (CRabs R (CR_of_Q R (0 # 1)))
                 ltac:(apply (CRabs_morph_prop R (alt_partial (sin_a x) j - alt_partial (sin_a x) j) (CR_of_Q R (0 # 1)));
                       unfold CRminus;
                       rewrite (CRplus_opp_r (alt_partial (sin_a x) j));
                       apply CReq_refl)
                 (CR_of_Q R (0 # 1)) (CR_of_Q R (0 # 1)) (CReq_refl _))).
        apply abs_0_le. apply CRle_refl.
      * apply CR_of_Q_le. unfold Qle. simpl. lia.
Qed.

(* sin 定义（0 ≤ x ≤ 2 时收敛） *)
Definition m2e_CRsin (x : CRcarrier R) (Hx0 : 0 <= x) (Hx2 : x <= CR_of_Q R (2 # 1)) : CRcarrier R :=
  projT1 (CR_complete R (alt_partial (sin_a x)) (m2e_sin_cauchy x Hx0 Hx2)).

Lemma m2e_sin_cv (x : CRcarrier R) (Hx0 : 0 <= x) (Hx2 : x <= CR_of_Q R (2 # 1)) :
  CR_cv R (alt_partial (sin_a x)) (m2e_CRsin x Hx0 Hx2).
Proof. exact (projT2 (CR_complete R (alt_partial (sin_a x)) (m2e_sin_cauchy x Hx0 Hx2))). Qed.

(* 余项：|sin x - S_N| ≤ sin_a x (N+1)（0 ≤ x ≤ 2） *)
Lemma m2e_sin_remainder (x : CRcarrier R) (Hx0 : 0 <= x) (Hx2 : x <= CR_of_Q R (2 # 1)) (N : nat) :
  CRle R (CRabs R (m2e_CRsin x Hx0 Hx2 - alt_partial (sin_a x) N)) (sin_a x (N + 1)).
Proof.
  assert (Hcv : CR_cv R (fun M => sin_tail_partial x N M)
                          (m2e_CRsin x Hx0 Hx2 - alt_partial (sin_a x) N)).
  { apply (CR_cv_eq (fun M => sin_tail_partial x N M)
                    (fun M => alt_partial (sin_a x) (N + 1 + M) - alt_partial (sin_a x) N)
                    (m2e_CRsin x Hx0 Hx2 - alt_partial (sin_a x) N)).
    - intros M. apply sin_S_tail_eq.
    - apply (CR_cv_minus (fun M => alt_partial (sin_a x) (N + 1 + M))
                         (fun _ => alt_partial (sin_a x) N)
                         (m2e_CRsin x Hx0 Hx2) (alt_partial (sin_a x) N)).
      + intros p. destruct (m2e_sin_cv x Hx0 Hx2 p) as [N0 HN0]. exists N0. intros m Hm.
        apply HN0. lia.
      + apply CR_cv_const. }
  apply (proj1 (CRabs_def R (m2e_CRsin x Hx0 Hx2 - alt_partial (sin_a x) N) (sin_a x (N + 1)))).
  split.
  - apply (CR_cv_bound_up (fun M => sin_tail_partial x N M) (sin_a x (N + 1))
                          (m2e_CRsin x Hx0 Hx2 - alt_partial (sin_a x) N) 0).
    + intros M H. apply (proj1 (CRabs_def2 (sin_tail_partial x N M) (sin_a x (N + 1))
                                           (m2e_sin_tail_partial_bound x Hx0 Hx2 N M))).
    + exact Hcv.
  - apply (proj2 (CRle_morph R (- (m2e_CRsin x Hx0 Hx2 - alt_partial (sin_a x) N))
            (- (m2e_CRsin x Hx0 Hx2 - alt_partial (sin_a x) N)) (CReq_refl _)
            (sin_a x (N + 1)) (- (- (sin_a x (N + 1))))
            ltac:(apply CReq_sym; ring))).
    apply (CRopp_ge_le_contravar (m2e_CRsin x Hx0 Hx2 - alt_partial (sin_a x) N) (- (sin_a x (N + 1)))).
    apply (CR_cv_bound_down (fun M => sin_tail_partial x N M) (- (sin_a x (N + 1)))
                            (m2e_CRsin x Hx0 Hx2 - alt_partial (sin_a x) N) 0).
    + intros M H.
      apply (proj2 (CRabs_def2 (sin_tail_partial x N M) (sin_a x (N + 1))
                                (m2e_sin_tail_partial_bound x Hx0 Hx2 N M))).
    + exact Hcv.
Qed.

(* 奇部分和递增（多步，0 ≤ x ≤ 2） *)
Lemma m2e_sin_odd_incr_multi (x : CRcarrier R) (Hx0 : 0 <= x) (Hx2 : x <= CR_of_Q R (2 # 1)) (m n : nat) :
  (m <= n)%nat ->
  CRle R (alt_partial (sin_a x) (2 * m + 1)%nat) (alt_partial (sin_a x) (2 * n + 1)%nat).
Proof.
  intros H. induction n as [|n IHn].
  - destruct (Nat.eq_dec m 0); subst; [apply CRle_refl | lia].
  - destruct (Nat.lt_ge_cases m (S n)) as [Hlt|Hge].
    + apply (CRle_trans _ (alt_partial (sin_a x) (2 * n + 1)%nat) _).
      * apply IHn. lia.
      * apply (alt_odd_incr (sin_a x) n). intros k. apply (m2e_sin_a_S_le x Hx0 Hx2).
    + assert (m = S n) by lia. subst. apply CRle_refl.
Qed.

(* 偶部分和递减（多步，0 ≤ x ≤ 2） *)
Lemma m2e_sin_even_decr_multi (x : CRcarrier R) (Hx0 : 0 <= x) (Hx2 : x <= CR_of_Q R (2 # 1)) (m n : nat) :
  (m <= n)%nat ->
  CRle R (alt_partial (sin_a x) (2 * n)%nat) (alt_partial (sin_a x) (2 * m)%nat).
Proof.
  intros H. induction n as [|n IHn].
  - destruct (Nat.eq_dec m 0); subst; [apply CRle_refl | lia].
  - destruct (Nat.lt_ge_cases m (S n)) as [Hlt|Hge].
    + apply (CRle_trans _ (alt_partial (sin_a x) (2 * n)%nat) _).
      * apply (alt_even_decr (sin_a x) n). intros k. apply (m2e_sin_a_S_le x Hx0 Hx2).
      * apply IHn. lia.
    + assert (m = S n) by lia. subst. apply CRle_refl.
Qed.

(* 奇子列收敛 → sin x（0 ≤ x ≤ 2） *)
Lemma m2e_sin_odd_subseq_cv (x : CRcarrier R) (Hx0 : 0 <= x) (Hx2 : x <= CR_of_Q R (2 # 1)) :
  CR_cv R (fun n => alt_partial (sin_a x) (2 * n + 1)%nat) (m2e_CRsin x Hx0 Hx2).
Proof.
  intros p. destruct (m2e_sin_cv x Hx0 Hx2 p) as [N HN]. exists N. intros m Hm.
  apply HN. lia.
Qed.

(* 偶子列收敛 → sin x（0 ≤ x ≤ 2） *)
Lemma m2e_sin_even_subseq_cv (x : CRcarrier R) (Hx0 : 0 <= x) (Hx2 : x <= CR_of_Q R (2 # 1)) :
  CR_cv R (fun n => alt_partial (sin_a x) (2 * n)%nat) (m2e_CRsin x Hx0 Hx2).
Proof.
  intros p. destruct (m2e_sin_cv x Hx0 Hx2 p) as [N HN]. exists N. intros m Hm.
  apply HN. lia.
Qed.

(* 下界：S_{2M+1} ≤ sin x（0 ≤ x ≤ 2，任意阶 Taylor 下界） *)
Lemma m2e_sin_odd_le (x : CRcarrier R) (Hx0 : 0 <= x) (Hx2 : x <= CR_of_Q R (2 # 1)) (M : nat) :
  CRle R (alt_partial (sin_a x) (2 * M + 1)%nat) (m2e_CRsin x Hx0 Hx2).
Proof.
  apply (CR_cv_bound_down (fun n => alt_partial (sin_a x) (2 * n + 1)%nat)
          (alt_partial (sin_a x) (2 * M + 1)%nat) (m2e_CRsin x Hx0 Hx2) M).
  - intros n Hn.
    apply (m2e_sin_odd_incr_multi x Hx0 Hx2 M n). exact Hn.
  - apply m2e_sin_odd_subseq_cv.
Qed.

(* 上界：sin x ≤ S_{2M}（0 ≤ x ≤ 2，任意阶 Taylor 上界） *)
Lemma m2e_sin_even_ge (x : CRcarrier R) (Hx0 : 0 <= x) (Hx2 : x <= CR_of_Q R (2 # 1)) (M : nat) :
  CRle R (m2e_CRsin x Hx0 Hx2) (alt_partial (sin_a x) (2 * M)%nat).
Proof.
  apply (CR_cv_bound_up (fun n => alt_partial (sin_a x) (2 * n)%nat)
          (alt_partial (sin_a x) (2 * M)%nat) (m2e_CRsin x Hx0 Hx2) M).
  - intros n Hn. apply (m2e_sin_even_decr_multi x Hx0 Hx2 M n). exact Hn.
  - apply m2e_sin_even_subseq_cv.
Qed.

(* ============ S7 / S9 多项式展开（M4 数值界用） ============ *)

(* sin_a x 3 == x⁷/5040 *)
Lemma m2e_sin_a_3 (x : CRcarrier R) :
  CReq R (sin_a x 3) (CR_of_Q R (1 # 5040) * (x * x * x * x * x * x * x)).
Proof.
  unfold sin_a.
  replace (2 * 3 + 1)%nat with 7%nat by lia.
  replace (Pos.of_nat (nfact 7)) with 5040%positive by (vm_compute; reflexivity).
  transitivity (CR_of_Q R (1 # Pos.of_nat 5040) * (x_pow x 7)).
  - apply (CRmult_morph_Proper
             (CR_of_Q R (1 # Pos.of_nat (nfact 7))) (CR_of_Q R (1 # Pos.of_nat 5040))
             ltac:(apply (CR_of_Q_morph R (1 # Pos.of_nat (nfact 7)) (1 # Pos.of_nat 5040)); vm_compute; reflexivity)
             (x_pow x 7) (x_pow x 7) (CReq_refl _)).
  - apply (CRmult_morph_Proper
             (CR_of_Q R (1 # Pos.of_nat 5040)) (CR_of_Q R (1 # 5040))
             ltac:(apply (CR_of_Q_morph R (1 # Pos.of_nat 5040) (1 # 5040)); vm_compute; reflexivity)
             (x_pow x 7) (x * x * x * x * x * x * x)
             ltac:(cbn [x_pow]; ring)).
Qed.

(* sin_a x 4 == x⁹/362880 *)
Lemma m2e_sin_a_4 (x : CRcarrier R) :
  CReq R (sin_a x 4) (CR_of_Q R (1 # 362880) * (x * x * x * x * x * x * x * x * x)).
Proof.
  unfold sin_a.
  replace (2 * 4 + 1)%nat with 9%nat by lia.
  replace (Pos.of_nat (nfact 9)) with 362880%positive by (vm_compute; reflexivity).
  transitivity (CR_of_Q R (1 # Pos.of_nat 362880) * (x_pow x 9)).
  - apply (CRmult_morph_Proper
             (CR_of_Q R (1 # Pos.of_nat (nfact 9))) (CR_of_Q R (1 # Pos.of_nat 362880))
             ltac:(apply (CR_of_Q_morph R (1 # Pos.of_nat (nfact 9)) (1 # Pos.of_nat 362880)); vm_compute; reflexivity)
             (x_pow x 9) (x_pow x 9) (CReq_refl _)).
  - apply (CRmult_morph_Proper
             (CR_of_Q R (1 # Pos.of_nat 362880)) (CR_of_Q R (1 # 362880))
             ltac:(apply (CR_of_Q_morph R (1 # Pos.of_nat 362880) (1 # 362880)); vm_compute; reflexivity)
             (x_pow x 9) (x * x * x * x * x * x * x * x * x)
             ltac:(cbn [x_pow]; ring)).
Qed.

(* alt_sign 3 = -1、alt_sign 4 = 1 *)
Lemma m2e_alt_sign_3 : CReq R (alt_sign 3) (CR_of_Q R (-1 # 1)).
Proof. unfold alt_sign. cbn. reflexivity. Qed.

Lemma m2e_alt_sign_4 : CReq R (alt_sign 4) (CR_of_Q R (1 # 1)).
Proof. unfold alt_sign. cbn. reflexivity. Qed.

(* S7 == x - x³/6 + x⁵/120 - x⁷/5040（alt_partial 3 的多项式展开） *)
Lemma m2e_S7_poly (x : CRcarrier R) :
  CReq R (alt_partial (sin_a x) 3)
         (x - CR_of_Q R (1 # 6) * (x * x * x) + CR_of_Q R (1 # 120) * (x * x * x * x * x)
          - CR_of_Q R (1 # 5040) * (x * x * x * x * x * x * x)).
Proof.
  unfold alt_partial.
  cbn [CRsum].
  rewrite (sin_a_0 x).
  replace (alt_sign 0) with (CR_of_Q R (1 # 1)) by (unfold alt_sign; cbn; reflexivity).
  rewrite (sin_a_1 x).
  replace (alt_sign 1) with (CR_of_Q R (-1 # 1)) by (unfold alt_sign; cbn; reflexivity).
  rewrite (sin_a_2 x).
  replace (alt_sign 2) with (CR_of_Q R (1 # 1)) by (unfold alt_sign; cbn; reflexivity).
  rewrite (m2e_sin_a_3 x).
  rewrite m2e_alt_sign_3.
  (* 归一符号后 ring（unfold CRminus） *)
  transitivity (1 * x + (- (1 : CRcarrier R)) * (CR_of_Q R (1 # 6) * (x * x * x))
                + 1 * (CR_of_Q R (1 # 120) * (x * x * x * x * x))
                + (- (1 : CRcarrier R)) * (CR_of_Q R (1 # 5040) * (x * x * x * x * x * x * x))).
  - apply (CRplus_morph_Proper
             (CR_of_Q R (1 # 1) * x + CR_of_Q R (-1 # 1) * (CR_of_Q R (1 # 6) * (x * x * x))
              + CR_of_Q R (1 # 1) * (CR_of_Q R (1 # 120) * (x * x * x * x * x)))
             (1 * x + (- (1 : CRcarrier R)) * (CR_of_Q R (1 # 6) * (x * x * x))
              + 1 * (CR_of_Q R (1 # 120) * (x * x * x * x * x)))
             ltac:(apply (CRplus_morph_Proper
                            (CR_of_Q R (1 # 1) * x + CR_of_Q R (-1 # 1) * (CR_of_Q R (1 # 6) * (x * x * x)))
                            (1 * x + (- (1 : CRcarrier R)) * (CR_of_Q R (1 # 6) * (x * x * x)))
                            ltac:(apply (CRplus_morph_Proper
                                           (CR_of_Q R (1 # 1) * x) (1 * x)
                                           ltac:(apply (CRmult_morph_Proper (CR_of_Q R (1 # 1)) 1 sign_one x x (CReq_refl _)))
                                           (CR_of_Q R (-1 # 1) * (CR_of_Q R (1 # 6) * (x * x * x)))
                                           ((- (1 : CRcarrier R)) * (CR_of_Q R (1 # 6) * (x * x * x)))
                                           ltac:(apply (CRmult_morph_Proper (CR_of_Q R (-1 # 1)) (- (1 : CRcarrier R)) sign_minus_one
                                                        (CR_of_Q R (1 # 6) * (x * x * x)) (CR_of_Q R (1 # 6) * (x * x * x)) (CReq_refl _)))))
                            (CR_of_Q R (1 # 1) * (CR_of_Q R (1 # 120) * (x * x * x * x * x)))
                            (1 * (CR_of_Q R (1 # 120) * (x * x * x * x * x)))
                            ltac:(apply (CRmult_morph_Proper (CR_of_Q R (1 # 1)) 1 sign_one
                                         (CR_of_Q R (1 # 120) * (x * x * x * x * x)) (CR_of_Q R (1 # 120) * (x * x * x * x * x)) (CReq_refl _)))))
             (CR_of_Q R (-1 # 1) * (CR_of_Q R (1 # 5040) * (x * x * x * x * x * x * x)))
             ((- (1 : CRcarrier R)) * (CR_of_Q R (1 # 5040) * (x * x * x * x * x * x * x)))
             ltac:(apply (CRmult_morph_Proper (CR_of_Q R (-1 # 1)) (- (1 : CRcarrier R)) sign_minus_one
                          (CR_of_Q R (1 # 5040) * (x * x * x * x * x * x * x)) (CR_of_Q R (1 # 5040) * (x * x * x * x * x * x * x)) (CReq_refl _)))).
  - unfold CRminus. ring.
Qed.

(* S9 == S7 + x⁹/362880（alt_partial 4 的多项式展开） *)
Lemma m2e_S9_poly (x : CRcarrier R) :
  CReq R (alt_partial (sin_a x) 4)
         (x - CR_of_Q R (1 # 6) * (x * x * x) + CR_of_Q R (1 # 120) * (x * x * x * x * x)
          - CR_of_Q R (1 # 5040) * (x * x * x * x * x * x * x)
          + CR_of_Q R (1 # 362880) * (x * x * x * x * x * x * x * x * x)).
Proof.
  unfold alt_partial.
  cbn [CRsum].
  rewrite (sin_a_0 x).
  replace (alt_sign 0) with (CR_of_Q R (1 # 1)) by (unfold alt_sign; cbn; reflexivity).
  rewrite (sin_a_1 x).
  replace (alt_sign 1) with (CR_of_Q R (-1 # 1)) by (unfold alt_sign; cbn; reflexivity).
  rewrite (sin_a_2 x).
  replace (alt_sign 2) with (CR_of_Q R (1 # 1)) by (unfold alt_sign; cbn; reflexivity).
  rewrite (m2e_sin_a_3 x).
  rewrite m2e_alt_sign_3.
  rewrite (m2e_sin_a_4 x).
  rewrite m2e_alt_sign_4.
  transitivity (1 * x + (- (1 : CRcarrier R)) * (CR_of_Q R (1 # 6) * (x * x * x))
                + 1 * (CR_of_Q R (1 # 120) * (x * x * x * x * x))
                + (- (1 : CRcarrier R)) * (CR_of_Q R (1 # 5040) * (x * x * x * x * x * x * x))
                + 1 * (CR_of_Q R (1 # 362880) * (x * x * x * x * x * x * x * x * x))).
  - apply (CRplus_morph_Proper
             (CR_of_Q R (1 # 1) * x + CR_of_Q R (-1 # 1) * (CR_of_Q R (1 # 6) * (x * x * x))
              + CR_of_Q R (1 # 1) * (CR_of_Q R (1 # 120) * (x * x * x * x * x))
              + CR_of_Q R (-1 # 1) * (CR_of_Q R (1 # 5040) * (x * x * x * x * x * x * x)))
             (1 * x + (- (1 : CRcarrier R)) * (CR_of_Q R (1 # 6) * (x * x * x))
              + 1 * (CR_of_Q R (1 # 120) * (x * x * x * x * x))
              + (- (1 : CRcarrier R)) * (CR_of_Q R (1 # 5040) * (x * x * x * x * x * x * x)))
             ltac:(apply (CRplus_morph_Proper
                            (CR_of_Q R (1 # 1) * x + CR_of_Q R (-1 # 1) * (CR_of_Q R (1 # 6) * (x * x * x))
                             + CR_of_Q R (1 # 1) * (CR_of_Q R (1 # 120) * (x * x * x * x * x)))
                            (1 * x + (- (1 : CRcarrier R)) * (CR_of_Q R (1 # 6) * (x * x * x))
                             + 1 * (CR_of_Q R (1 # 120) * (x * x * x * x * x)))
                            ltac:(apply (CRplus_morph_Proper
                                           (CR_of_Q R (1 # 1) * x + CR_of_Q R (-1 # 1) * (CR_of_Q R (1 # 6) * (x * x * x)))
                                           (1 * x + (- (1 : CRcarrier R)) * (CR_of_Q R (1 # 6) * (x * x * x)))
                                           ltac:(apply (CRplus_morph_Proper
                                                          (CR_of_Q R (1 # 1) * x) (1 * x)
                                                          ltac:(apply (CRmult_morph_Proper (CR_of_Q R (1 # 1)) 1 sign_one x x (CReq_refl _)))
                                                          (CR_of_Q R (-1 # 1) * (CR_of_Q R (1 # 6) * (x * x * x)))
                                                          ((- (1 : CRcarrier R)) * (CR_of_Q R (1 # 6) * (x * x * x)))
                                                          ltac:(apply (CRmult_morph_Proper (CR_of_Q R (-1 # 1)) (- (1 : CRcarrier R)) sign_minus_one
                                                                       (CR_of_Q R (1 # 6) * (x * x * x)) (CR_of_Q R (1 # 6) * (x * x * x)) (CReq_refl _)))))
                                           (CR_of_Q R (1 # 1) * (CR_of_Q R (1 # 120) * (x * x * x * x * x)))
                                           (1 * (CR_of_Q R (1 # 120) * (x * x * x * x * x)))
                                           ltac:(apply (CRmult_morph_Proper (CR_of_Q R (1 # 1)) 1 sign_one
                                                        (CR_of_Q R (1 # 120) * (x * x * x * x * x)) (CR_of_Q R (1 # 120) * (x * x * x * x * x)) (CReq_refl _)))))
                            (CR_of_Q R (-1 # 1) * (CR_of_Q R (1 # 5040) * (x * x * x * x * x * x * x)))
                            ((- (1 : CRcarrier R)) * (CR_of_Q R (1 # 5040) * (x * x * x * x * x * x * x)))
                            ltac:(apply (CRmult_morph_Proper (CR_of_Q R (-1 # 1)) (- (1 : CRcarrier R)) sign_minus_one
                                         (CR_of_Q R (1 # 5040) * (x * x * x * x * x * x * x)) (CR_of_Q R (1 # 5040) * (x * x * x * x * x * x * x)) (CReq_refl _)))))
             (CR_of_Q R (1 # 1) * (CR_of_Q R (1 # 362880) * (x * x * x * x * x * x * x * x * x)))
             (1 * (CR_of_Q R (1 # 362880) * (x * x * x * x * x * x * x * x * x)))
             ltac:(apply (CRmult_morph_Proper (CR_of_Q R (1 # 1)) 1 sign_one
                          (CR_of_Q R (1 # 362880) * (x * x * x * x * x * x * x * x * x))
                          (CR_of_Q R (1 # 362880) * (x * x * x * x * x * x * x * x * x)) (CReq_refl _)))).
  - unfold CRminus. ring.
Qed.

End M2E.

(* ==================== 模块 53/67: probe_sqrt_cr_m3 ==================== *)

Close Scope R_scope.
Close Scope Z_scope.
(* ============================================================
   G-5 可判定性溢价 M3：构造性 sqrt（Q 层二分 + CR 极限）
   纯构造性：Stdlib ConstructiveReals，零经典、零 Admitted、零公理
   目标：CRsqrt 定义 + √21 ≥ 458/100、√105 ≥ 10246/1000
   思路：Q 层二分（Qlt_le_dec 可判定）→ 有理序列 lo_n/hi_n 夹逼 √q
   → CR_complete 取极限 → 证明极限² = q（夹逼）
   ============================================================ *)
From Stdlib Require Import ConstructiveReals.
From Stdlib Require Import ConstructiveRealsMorphisms.
From Stdlib Require Import ConstructiveAbs.
From Stdlib Require Import ConstructiveSum.
From Stdlib Require Import ConstructiveLimits.
From Stdlib Require Import QArith.
From Stdlib Require Import Qfield.
From Stdlib Require Import ZArith.
From Stdlib Require Import Lia.
From Stdlib Require Import Ring.

Section M3Q.

(* ============ Q 层二分（纯 Q，无 CR scope 干扰） ============ *)

(* 中点：(a+b)/2 *)
Definition qmid (a b : Q) : Q := (a + b) * (1 # 2).

(* 二分不动点：lo_0 = 0, hi_0 = q+1；每步若 mid² ≤ q 则 lo=mid, hi 不变；否则反之 *)
Fixpoint qbisec (q : Q) (n : nat) : Q * Q :=
  match n with
  | 0%nat => (0, q + 1)
  | S m =>
    let '(lo, hi) := qbisec q m in
    let mid := qmid lo hi in
    if Qle_bool (mid * mid) q then (mid, hi) else (lo, mid)
  end.

Definition qlo (q : Q) (n : nat) : Q := fst (qbisec q n).
Definition qhi (q : Q) (n : nat) : Q := snd (qbisec q n).

Local Open Scope Q_scope.

(* q ≤ q+1 *)
Lemma Qle_self_plus1 (q : Q) : (q <= q + 1).
Proof.
  apply (proj2 (Qle_comp q (q + 0) (Qeq_sym (q + 0) q (Qplus_0_r q)) (q + 1) (q + 1) (Qeq_refl (q + 1)))).
  apply (Qplus_le_compat q q 0 1). apply Qle_refl.
  unfold Qle. simpl. lia.
Qed.

(* 1 ≤ q+1（0 ≤ q） *)
Lemma Qle_1_plus1 (q : Q) (Hq : (0 <= q)) : (1 <= q + 1).
Proof.
  apply (proj2 (Qle_comp 1 (0 + 1) (Qeq_sym (0 + 1) 1 (Qplus_0_l 1)) (q + 1) (q + 1) (Qeq_refl (q + 1)))).
  apply (Qplus_le_compat 0 q 1 1). exact Hq. apply Qle_refl.
Qed.

(* 0 ≤ q+1（0 ≤ q） *)
Lemma Qle_0_plus1 (q : Q) (Hq : (0 <= q)) : (0 <= q + 1).
Proof.
  apply (Qle_trans _ q _). exact Hq. apply Qle_self_plus1.
Qed.

(* q ≤ (q+1)²（0 ≤ q） *)
Lemma q_le_sq_plus1 (q : Q) (Hq : (0 <= q)) : (q <= (q + 1) * (q + 1)).
Proof.
  apply (Qle_trans _ (q + 1) _).
  - apply Qle_self_plus1.
  - apply (proj2 (Qle_comp (q + 1) (1 * (q + 1)) (Qeq_sym (1 * (q + 1)) (q + 1) (Qmult_1_l (q + 1)))
                           ((q + 1) * (q + 1)) ((q + 1) * (q + 1)) (Qeq_refl _))).
    apply (Qmult_le_compat_r 1 (q + 1) (q + 1)).
    + apply Qle_1_plus1. exact Hq.
    + apply Qle_0_plus1. exact Hq.
Qed.

(* 2x == x+x *)
Lemma two_mult_r (x : Q) : (x * 2 == x + x).
Proof. field. Qed.

(* x·(1/2) == x/2 *)
Lemma half_div (x : Q) : (x * (1 # 2) == x / 2).
Proof. field. Qed.

(* qmid ≤ hi：lo ≤ hi ⟹ (lo+hi)/2 ≤ hi *)
Lemma qmid_le_hi (lo hi : Q) : (lo <= hi) -> (qmid lo hi <= hi).
Proof.
  intros H. unfold qmid.
  apply (proj2 (Qle_comp ((lo + hi) * (1 # 2)) ((lo + hi) / 2) (half_div (lo + hi))
                           hi hi (Qeq_refl hi))).
  apply (Qle_shift_div_r (lo + hi) 2 hi).
  - vm_compute. reflexivity.
  - apply (proj2 (Qle_comp (lo + hi) (lo + hi) (Qeq_refl _) (hi * 2) (hi + hi) (two_mult_r hi))).
    apply (Qplus_le_compat lo hi hi hi). exact H. apply Qle_refl.
Qed.

(* lo ≤ qmid：lo ≤ hi ⟹ lo ≤ (lo+hi)/2 *)
Lemma qmid_ge_lo (lo hi : Q) : (lo <= hi) -> (lo <= qmid lo hi).
Proof.
  intros H. unfold qmid.
  apply (proj2 (Qle_comp lo lo (Qeq_refl _)
                           ((lo + hi) * (1 # 2)) ((lo + hi) / 2) (half_div (lo + hi)))).
  apply (Qle_shift_div_l lo (lo + hi) 2).
  - vm_compute. reflexivity.
  - apply (proj2 (Qle_comp (lo * 2) (lo + lo) (two_mult_r lo)
                           (lo + hi) (lo + hi) (Qeq_refl _))).
    apply (Qplus_le_compat lo lo lo hi). apply Qle_refl. exact H.
Qed.

(* ¬(mid² ≤ q) ⟹ q < mid²（Qle_bool 假 ⟹ q ≤ mid² 的严格形式） *)
Lemma qle_bool_false_lt (a b : Q) :
  Qle_bool a b = false -> (b < a).
Proof.
  intros H.
  apply Qnot_le_lt.
  intros Hle.
  apply (proj2 (Qle_bool_iff a b)) in Hle.
  rewrite Hle in H. discriminate.
Qed.

(* qlo/qhi 递推：lo_{n+1}、hi_{n+1} 由 lo_n、hi_n 与 mid 决定 *)
Lemma qlo_S (q : Q) (n : nat) :
  qlo q (S n) =
    let lo := qlo q n in
    let hi := qhi q n in
    let mid := qmid lo hi in
    if Qle_bool (mid * mid) q then mid else lo.
Proof.
  unfold qlo, qhi.
  change (fst (let '(lo, hi) := qbisec q n in
               if Qle_bool (qmid lo hi * qmid lo hi) q then (qmid lo hi, hi) else (lo, qmid lo hi))
          =
          let lo := fst (qbisec q n) in
          let hi := snd (qbisec q n) in
          let mid := qmid lo hi in
          if Qle_bool (mid * mid) q then mid else lo).
  destruct (qbisec q n) as [l h] eqn:Hp.
  simpl.
  destruct (Qle_bool (qmid l h * qmid l h) q) eqn:Hb.
  - reflexivity.
  - reflexivity.
Qed.

Lemma qhi_S (q : Q) (n : nat) :
  qhi q (S n) =
    let lo := qlo q n in
    let hi := qhi q n in
    let mid := qmid lo hi in
    if Qle_bool (mid * mid) q then hi else mid.
Proof.
  unfold qhi, qlo.
  change (snd (let '(lo, hi) := qbisec q n in
               if Qle_bool (qmid lo hi * qmid lo hi) q then (qmid lo hi, hi) else (lo, qmid lo hi))
          =
          let lo := fst (qbisec q n) in
          let hi := snd (qbisec q n) in
          let mid := qmid lo hi in
          if Qle_bool (mid * mid) q then hi else mid).
  destruct (qbisec q n) as [l h] eqn:Hp.
  simpl.
  destruct (Qle_bool (qmid l h * qmid l h) q) eqn:Hb.
  - reflexivity.
  - reflexivity.
Qed.

(* 核心不变量：lo_n² ≤ q ≤ hi_n² ∧ lo_n ≤ hi_n *)
Lemma qbisec_inv (q : Q) (Hq : (0 <= q)) (n : nat) :
  ((qlo q n) * (qlo q n) <= q) /\
  (q <= (qhi q n) * (qhi q n)) /\
  ((qlo q n) <= (qhi q n)).
Proof.
  induction n.
  - (* n=0：lo=0, hi=q+1 *)
    assert (Hlo : qlo q 0 = 0) by (unfold qlo, qbisec; reflexivity).
    assert (Hhi : qhi q 0 = (q + 1)) by (unfold qhi, qbisec; reflexivity).
    rewrite Hlo. rewrite Hhi.
    split; [| split].
    + (* 0*0 ≤ q：0*0 == 0（field）且 0 ≤ q *)
      apply (proj2 (Qle_comp 0 (0 * 0) (Qeq_sym (0 * 0) 0 (Qmult_0_l 0)) q q (Qeq_refl q))).
      exact Hq.
    + (* q ≤ (q+1)*(q+1) *)
      apply q_le_sq_plus1. exact Hq.
    + apply Qle_0_plus1. exact Hq.
  - (* n = S m：由 IHn 递推 *)
    destruct IHn as [Hlo2 [Hqle Hle]].
    (* 对 qmid (qlo q n) (qhi q n)² ≤ q 分情况 *)
    destruct (Qle_bool (qmid (qlo q n) (qhi q n) * qmid (qlo q n) (qhi q n)) q) eqn:Hmid.
    + (* mid² ≤ q：lo'=mid, hi'=hi *)
      rewrite qlo_S. rewrite qhi_S.
      simpl.
      rewrite Hmid.
      split; [| split].
      * (* mid² ≤ q *)
        apply Qle_bool_imp_le. exact Hmid.
      * exact Hqle.
      * (* mid ≤ hi：qmid (qlo q n) (qhi q n) ≤ qhi q n *)
        apply qmid_le_hi. exact Hle.
    + (* ¬(mid² ≤ q)：lo'=lo, hi'=mid *)
      rewrite qlo_S. rewrite qhi_S.
      simpl.
      rewrite Hmid.
      split; [| split].
      * exact Hlo2.
      * (* q ≤ mid² *)
        apply Qlt_le_weak. apply (qle_bool_false_lt
                                    (qmid (qlo q n) (qhi q n) * qmid (qlo q n) (qhi q n)) q). exact Hmid.
      * (* lo ≤ mid *)
        apply qmid_ge_lo. exact Hle.
Qed.

(* ============ 区间宽度：hi_n - lo_n = (q+1)/2^n ============ *)

(* 2^n 的 Q 表示 *)
Fixpoint qpow2 (n : nat) : Q :=
  match n with 0%nat => 1 | S m => qpow2 m * 2 end.

(* 宽度递推：hi_{n+1} - lo_{n+1} = (hi_n - lo_n) / 2 *)
Lemma qwidth_S (q : Q) (n : nat) :
  qhi q (S n) - qlo q (S n) == (qhi q n - qlo q n) / 2.
Proof.
  rewrite qlo_S. rewrite qhi_S.
  (* 展开 let（经验卡：unfold/simpl 展开 let 后再匹配） *)
  simpl.
  (* 不用 set，直接对完整条件 destruct（destruct 后 if 自动化简） *)
  destruct (Qle_bool (qmid (qlo q n) (qhi q n) * qmid (qlo q n) (qhi q n)) q) eqn:Hb.
  - (* true：lo' = qmid (qlo q n) (qhi q n)，hi' = qhi q n *)
    unfold qmid. field.
  - (* false：lo' = qlo q n，hi' = qmid (qlo q n) (qhi q n) *)
    unfold qmid. field.
Qed.

(* qpow2 正性：0 < 2^n *)
Lemma qpow2_pos (n : nat) : 0 < qpow2 n.
Proof.
  induction n.
  - unfold qpow2. vm_compute. reflexivity.
  - unfold qpow2. apply (Qmult_lt_0_compat _ _ IHn).
    vm_compute. reflexivity.
Qed.

(* qpow2 非零（Qeq 版本，field 除法前提） *)
Lemma qpow2_neq0_eq (n : nat) : ~ (qpow2 n == 0).
Proof.
  intros H. apply (Qlt_not_eq _ _ (qpow2_pos n)).
  apply Qeq_sym. exact H.
Qed.

(* 宽度闭式：hi_n - lo_n == (q+1) / 2^n *)
Lemma qwidth_closed (q : Q) (n : nat) :
  qhi q n - qlo q n == (q + 1) / qpow2 n.
Proof.
  induction n.
  - (* n=0：hi_0 - lo_0 = q+1；qpow2 0 = 1 *)
    assert (Hlo : qlo q 0 = 0) by (unfold qlo, qbisec; reflexivity).
    assert (Hhi : qhi q 0 = (q + 1)) by (unfold qhi, qbisec; reflexivity).
    rewrite Hlo. rewrite Hhi. unfold qpow2. field.
  - (* n = S m *)
    setoid_rewrite qwidth_S.
    rewrite IHn.
    unfold qpow2.
    (* (q+1)/qpow2 m / 2 == (q+1)/(qpow2 m * 2)：field 需 qpow2 m ≠ 0（Qeq） *)
    field.
    apply qpow2_neq0_eq.
Qed.

(* qlo 单调递增：qlo q n ≤ qlo q (S n)（0 ≤ q） *)
Lemma qlo_mono (q : Q) (Hq : (0 <= q)) (n : nat) : qlo q n <= qlo q (S n).
Proof.
  rewrite qlo_S.
  simpl.
  destruct (Qle_bool (qmid (qlo q n) (qhi q n) * qmid (qlo q n) (qhi q n)) q) eqn:Hb.
  - (* lo' = mid ≥ lo *)
    apply qmid_ge_lo.
    destruct (qbisec_inv q Hq n) as [_ [_ Hle]]. exact Hle.
  - (* lo' = lo *)
    apply Qle_refl.
Qed.

(* qhi 单调递减：qhi q (S n) ≤ qhi q n（0 ≤ q） *)
Lemma qhi_mono (q : Q) (Hq : (0 <= q)) (n : nat) : qhi q (S n) <= qhi q n.
Proof.
  rewrite qhi_S.
  simpl.
  destruct (Qle_bool (qmid (qlo q n) (qhi q n) * qmid (qlo q n) (qhi q n)) q) eqn:Hb.
  - (* hi' = hi *)
    apply Qle_refl.
  - (* hi' = mid ≤ hi *)
    apply qmid_le_hi.
    destruct (qbisec_inv q Hq n) as [_ [_ Hle]]. exact Hle.
Qed.

(* 多步单调：m ≤ n ⟹ qlo q m ≤ qlo q n *)
Lemma qlo_mono_multi (q : Q) (Hq : (0 <= q)) (m n : nat) :
  (m <= n)%nat -> qlo q m <= qlo q n.
Proof.
  intros Hmn.
  induction n.
  - (* n=0：m≤0 ⟹ m=0 *)
    assert (m = 0%nat) by lia. subst. apply Qle_refl.
  - destruct (Nat.eq_dec m (S n)) as [Hm | Hm].
    + subst. apply Qle_refl.
    + apply (Qle_trans _ (qlo q n) _).
      * apply IHn. lia.
      * apply qlo_mono. exact Hq.
Qed.

(* 多步单调（递减）：m ≤ n ⟹ qhi q n ≤ qhi q m *)
Lemma qhi_mono_multi (q : Q) (Hq : (0 <= q)) (m n : nat) :
  (m <= n)%nat -> qhi q n <= qhi q m.
Proof.
  intros Hmn.
  induction n.
  - (* n=0：m≤0 ⟹ m=0 *)
    assert (m = 0%nat) by lia. subst. apply Qle_refl.
  - destruct (Nat.eq_dec m (S n)) as [Hm | Hm].
    + subst. apply Qle_refl.
    + apply (Qle_trans _ (qhi q n) _).
      * apply qhi_mono. exact Hq.
      * apply IHn. lia.
Qed.

(* gap：m,n ≥ k ⟹ qlo q m − qlo q n ≤ (q+1)/2^k（qlo 递增 + 区间包含） *)
Lemma qlo_gap (q : Q) (Hq : (0 <= q)) (m n k : nat) :
  (k <= m)%nat -> (k <= n)%nat ->
  qlo q m - qlo q n <= (q + 1) / qpow2 k.
Proof.
  intros Hkm Hkn.
  (* qlo m − qlo n ≤ hi k − lo k：移项 qlo m + lo k ≤ qlo n + hi k *)
  (* 由 qlo m ≤ qhi k（m≥k：qlo m ≤ qhi m ≤ qhi k）和 qlo k ≤ qlo n（n≥k） *)
  apply (Qle_trans _ ((qhi q k) - (qlo q k)) _).
  - (* qlo m − qlo n ≤ qhi k − qlo k *)
    (* Qle_minus_iff : p ≤ q ↔ 0 ≤ q + (−p)；proj2 : 0≤q−p → p≤q *)
    apply (proj2 (Qle_minus_iff (qlo q m - qlo q n) ((qhi q k) - (qlo q k)))).
    (* 0 ≤ (qhi k − qlo k) + (−(qlo m − qlo n)) == 0 ≤ (qhi k + qlo n) − (qlo m + qlo k)（field） *)
    apply (proj2 (Qle_comp 0 0 (Qeq_refl 0)
                           (((qhi q k) - (qlo q k)) + (- ((qlo q m) - (qlo q n))))
                           (((qhi q k) + (qlo q n)) - ((qlo q m) + (qlo q k)))
                           ltac:(field))).
    (* 目标：0 ≤ (qhi k + qlo n) − (qlo m + qlo k) ⟺ qlo m + qlo k ≤ qhi k + qlo n *)
    (* 桥接减法为加法：0 ≤ C − A == 0 ≤ C + (−A)（field） *)
    apply (proj2 (Qle_comp 0 0 (Qeq_refl 0)
                           (((qhi q k) + (qlo q n)) - ((qlo q m) + (qlo q k)))
                           (((qhi q k) + (qlo q n)) + (- ((qlo q m) + (qlo q k))))
                           ltac:(field))).
    (* 目标：0 ≤ (qhi k + qlo n) + (−(qlo m + qlo k))：Qle_minus_iff proj1（A≤C → 0≤C−A） *)
    apply (proj1 (Qle_minus_iff (qlo q m + qlo q k) ((qhi q k) + (qlo q n)))).
    (* 子目标：qlo m + qlo k ≤ qhi k + qlo n *)
    assert (Hsum : (qlo q m + qlo q k <= qhi q k + qlo q n)%Q).
    { apply (Qplus_le_compat (qlo q m) (qhi q k) (qlo q k) (qlo q n)).
      + (* qlo q m ≤ qhi q k *)
        apply (Qle_trans _ (qhi q m) _).
        * destruct (qbisec_inv q Hq m) as [_ [_ Hle]]. exact Hle.
        * apply qhi_mono_multi. exact Hq. exact Hkm.
      + (* qlo q k ≤ qlo q n *)
        apply qlo_mono_multi. exact Hq. exact Hkn. }
    exact Hsum.
  - (* (qhi q k − qlo q k) ≤ (q+1)/2^k：宽度闭式 + Qeq 转 Qle *)
    apply (proj2 (Qle_comp ((qhi q k) - (qlo q k)) ((q + 1) / qpow2 k)
                           (qwidth_closed q k) _ _ (Qeq_refl _))).
    apply Qle_refl.
Qed.

(* 宽度版 gap：m,n ≥ k ⟹ qlo q m − qlo q n ≤ qhi q k − qlo q k *)
Lemma qlo_gap_width (q : Q) (Hq : (0 <= q)) (m n k : nat) :
  (k <= m)%nat -> (k <= n)%nat ->
  qlo q m - qlo q n <= qhi q k - qlo q k.
Proof.
  intros Hkm Hkn.
  apply (Qle_trans _ ((qhi q k) - (qlo q k)) _).
  - (* qlo m − qlo n ≤ qhi k − qlo k：同 qlo_gap 的第一段 *)
    apply (proj2 (Qle_minus_iff (qlo q m - qlo q n) ((qhi q k) - (qlo q k)))).
    apply (proj2 (Qle_comp 0 0 (Qeq_refl 0)
                           (((qhi q k) - (qlo q k)) + (- ((qlo q m) - (qlo q n))))
                           (((qhi q k) + (qlo q n)) - ((qlo q m) + (qlo q k)))
                           ltac:(field))).
    apply (proj2 (Qle_comp 0 0 (Qeq_refl 0)
                           (((qhi q k) + (qlo q n)) - ((qlo q m) + (qlo q k)))
                           (((qhi q k) + (qlo q n)) + (- ((qlo q m) + (qlo q k))))
                           ltac:(field))).
    apply (proj1 (Qle_minus_iff (qlo q m + qlo q k) ((qhi q k) + (qlo q n)))).
    assert (Hsum : (qlo q m + qlo q k <= qhi q k + qlo q n)%Q).
    { apply (Qplus_le_compat (qlo q m) (qhi q k) (qlo q k) (qlo q n)).
      + apply (Qle_trans _ (qhi q m) _).
        * destruct (qbisec_inv q Hq m) as [_ [_ Hle]]. exact Hle.
        * apply qhi_mono_multi. exact Hq. exact Hkm.
      + apply qlo_mono_multi. exact Hq. exact Hkn. }
    exact Hsum.
  - apply Qle_refl.
Qed.

(* ============ archimedean：取 N 使 2^N 超过给定值 ============ *)

(* nat 层：2^M ≥ 1 *)
Lemma nat_pow2_ge_1 (M : nat) : (1 <= 2 ^ M)%nat.
Proof.
  induction M; [reflexivity | rewrite Nat.pow_succ_r'; lia].
Qed.

(* nat 层：M ≤ 2^M（构造性归纳） *)
Lemma nat_le_pow2 (M : nat) : (M <= 2 ^ M)%nat.
Proof.
  induction M.
  - lia.
  - assert (H1 : (1 <= 2 ^ M)%nat) by (apply nat_pow2_ge_1).
    rewrite Nat.pow_succ_r'.
    apply (Nat.le_trans _ (2 ^ M + 1) _).
    + lia.
    + apply (Nat.le_trans _ (2 ^ M + 2 ^ M) _).
      * apply Nat.add_le_mono_l. exact H1.
      * rewrite Nat.mul_comm. lia.
Qed.

(* qpow2 n == (2^n 的 Q 表示) *)
Lemma qpow2_pow (n : nat) : qpow2 n == (Z.of_nat (2 ^ n) # 1).
Proof.
  induction n.
  - unfold qpow2. simpl. unfold Qeq. simpl. lia.
  - unfold qpow2. setoid_rewrite IHn.
    rewrite Nat.pow_succ_r'.
    unfold Qeq. simpl. lia.
Qed.

(* M ≤ 2^(to_nat M)（Q 层，M : positive） *)
Lemma qpow2_ge_pos (M : positive) : (Z.pos M # 1 <= qpow2 (Pos.to_nat M))%Q.
Proof.
  setoid_rewrite (qpow2_pow (Pos.to_nat M)).
  apply (proj2 (Qle_comp (Z.pos M # 1) (Z.of_nat (Pos.to_nat M) # 1)
                         ltac:(unfold Qeq; simpl; lia)
                         (Z.of_nat (2 ^ Pos.to_nat M) # 1) (Z.of_nat (2 ^ Pos.to_nat M) # 1)
                         (Qeq_refl _))).
  unfold Qle. simpl. rewrite !Z.mul_1_r.
  apply Nat2Z.inj_le. apply nat_le_pow2.
Qed.

(* (1#p) == 1/(Z.pos p # 1)（Q 层） *)
Lemma qone_over_pos (p : positive) : ((1 # p) == / (Z.pos p # 1))%Q.
Proof.
  unfold Qinv, Qeq. simpl. lia.
Qed.

(* 宽度 archimedean：给定正 p，存在 N 使 (q+1)/2^N ≤ 1/p（Set 层 sig，供 CR_cauchy 构造性使用） *)
Lemma qwidth_archimedean (q : Q) (p : positive) :
  {N : nat | ((q + 1) / qpow2 N <= (1 # p))%Q}.
Proof.
  destruct (Qarchimedean ((q + 1) * (Z.pos p # 1))) as [M HM].
  exists (Pos.to_nat M).
  assert (Hqp : ((q + 1) * (Z.pos p # 1) <= qpow2 (Pos.to_nat M))%Q).
  { apply (Qle_trans _ (Z.pos M # 1) _).
    - apply Qlt_le_weak. exact HM.
    - apply qpow2_ge_pos. }
  (* (q+1)/2^N ≤ 1/p：Qle_shift_div_r a b c : 0<b → a≤c·b → a/b≤c
     a=q+1, b=2^N, c=1/p；需 (q+1) ≤ (1/p)·2^N *)
  apply (Qle_shift_div_r (q + 1) (qpow2 (Pos.to_nat M)) (1 # p)).
  - apply qpow2_pos.
  - (* (q+1) ≤ (1/p)·2^N：桥接 (1/p)·2^N == 2^N/p，再由 Qle_shift_div_l *)
    apply (proj2 (Qle_comp ((q + 1)) ((q + 1)) (Qeq_refl _)
                           ((1 # p) * qpow2 (Pos.to_nat M))
                           (qpow2 (Pos.to_nat M) / (Z.pos p # 1))
                           ltac:(rewrite (qone_over_pos p); unfold Qdiv; rewrite Qmult_comm; reflexivity))).
    apply (Qle_shift_div_l (q + 1) (qpow2 (Pos.to_nat M)) (Z.pos p # 1)).
    + vm_compute. reflexivity.
    + exact Hqp.
Qed.

(* ============ 极限²=q 的 Q 层辅助 ============ *)

(* qlo 非负：0 ≤ qlo q n（q ≥ 0） *)
Lemma qlo_ge_0 (q : Q) (Hq : (0 <= q)) (n : nat) : (0 <= qlo q n)%Q.
Proof.
  assert (H0 : qlo q 0 = 0) by (unfold qlo, qbisec; reflexivity).
  apply (Qle_trans _ (qlo q 0) _).
  - rewrite H0. apply Qle_refl.
  - apply qlo_mono_multi. exact Hq. apply Nat.le_0_l.
Qed.

(* qhi 有界：qhi q n ≤ qhi q 0 = q+1 *)
Lemma qhi_le_qhi0 (q : Q) (Hq : (0 <= q)) (n : nat) : (qhi q n <= qhi q 0)%Q.
Proof.
  apply qhi_mono_multi. exact Hq. apply Nat.le_0_l.
Qed.

(* hi + lo 有界：qlo q n + qhi q n ≤ 2·(q+1) *)
Lemma qsum_bound (q : Q) (Hq : (0 <= q)) (n : nat) :
  (qlo q n + qhi q n <= 2 * (q + 1))%Q.
Proof.
  assert (Hh0 : qhi q 0 = q + 1) by (unfold qhi, qbisec; reflexivity).
  apply (Qle_trans _ (qhi q 0 + qhi q 0) _).
  - apply (Qplus_le_compat (qlo q n) (qhi q 0) (qhi q n) (qhi q 0)).
    + apply (Qle_trans _ (qhi q n) _).
      * destruct (qbisec_inv q Hq n) as [_ [_ Hle]]. exact Hle.
      * apply qhi_le_qhi0. exact Hq.
    + apply qhi_le_qhi0. exact Hq.
  - rewrite Hh0.
    apply (proj1 (Qle_comp (2 * (q + 1)) (q + 1 + (q + 1)) ltac:(ring)
                           (2 * (q + 1)) (2 * (q + 1)) (Qeq_refl _))).
    apply Qle_refl.
Qed.

(* 宽度非负：0 ≤ qhi q n − qlo q n *)
Lemma qwidth_nonneg (q : Q) (Hq : (0 <= q)) (n : nat) : (0 <= qhi q n - qlo q n)%Q.
Proof.
  apply (proj1 (Qle_minus_iff (qlo q n) (qhi q n))).
  destruct (qbisec_inv q Hq n) as [_ [_ Hle]].
  exact Hle.
Qed.

(* 宽度单步单调：width_{n+1} ≤ width_n（width_n ≥ 0） *)
Lemma qwidth_mono (q : Q) (Hq : (0 <= q)) (n : nat) :
  (qhi q (S n) - qlo q (S n) <= qhi q n - qlo q n)%Q.
Proof.
  setoid_rewrite qwidth_S.
  (* (width_n)/2 ≤ width_n：width_n ≤ width_n·2（0 ≤ width_n），Qle_shift_div_r *)
  apply (Qle_shift_div_r (qhi q n - qlo q n) 2 (qhi q n - qlo q n)).
  - vm_compute. reflexivity.
  - (* x ≤ x·2 == x·(1+1)：桥接 *)
    apply (proj2 (Qle_comp (qhi q n - qlo q n) ((qhi q n - qlo q n) + 0)
                           (Qeq_sym _ _ (Qplus_0_r (qhi q n - qlo q n)))
                           ((qhi q n - qlo q n) * 2) ((qhi q n - qlo q n) + (qhi q n - qlo q n))
                           ltac:(ring))).
    apply (Qplus_le_compat (qhi q n - qlo q n) (qhi q n - qlo q n)
                           (0) (qhi q n - qlo q n)).
    + apply Qle_refl.
    + apply qwidth_nonneg. exact Hq.
Qed.

(* 宽度多步单调：k ≤ n ⟹ width_n ≤ width_k *)
Lemma qwidth_mono_multi (q : Q) (Hq : (0 <= q)) (k n : nat) :
  (k <= n)%nat -> (qhi q n - qlo q n <= qhi q k - qlo q k)%Q.
Proof.
  intros Hkn.
  induction n.
  - assert (k = 0%nat) by lia. subst. apply Qle_refl.
  - destruct (Nat.eq_dec k (S n)) as [Hk | Hk].
    + subst. apply Qle_refl.
    + apply (Qle_trans _ (qhi q n - qlo q n) _).
      * apply qwidth_mono. exact Hq.
      * apply IHn. lia.
Qed.

(* 宽度非负（闭式形式）：0 ≤ (q+1)/2^n（qwidth_nonneg + qwidth_closed 桥接） *)
Lemma qwidth_nonneg_closed (q : Q) (Hq : (0 <= q)) (n : nat) :
  (0 <= (q + 1) / qpow2 n)%Q.
Proof.
  apply (proj2 (Qle_comp 0 0 (Qeq_refl 0) ((q + 1) / qpow2 n) (qhi q n - qlo q n)
                (Qeq_sym _ _ (qwidth_closed q n)))).
  apply (qwidth_nonneg q Hq n).
Qed.

(* hi+lo 有界（交换序）：qhi q n + qlo q n ≤ 2·(q+1) *)
Lemma qsum_bound' (q : Q) (Hq : (0 <= q)) (n : nat) :
  (qhi q n + qlo q n <= 2 * (q + 1))%Q.
Proof.
  apply (proj2 (Qle_comp (qhi q n + qlo q n) (qlo q n + qhi q n) (Qplus_comm (qhi q n) (qlo q n))
                        (2 * (q + 1)) (2 * (q + 1)) (Qeq_refl _))).
  apply (qsum_bound q Hq n).
Qed.
(* 平方差上界：q − lo² ≤ (hi−lo)·(hi+lo)（由 lo² ≤ q ≤ hi² + 代数恒等式） *)
Lemma q_lo_sq_sub (q : Q) (Hq : (0 <= q)) (n : nat) :
  (q - qlo q n * qlo q n <= (qhi q n - qlo q n) * (qhi q n + qlo q n))%Q.
Proof.
  apply (Qle_trans _ (qhi q n * qhi q n - qlo q n * qlo q n) _).
  - (* q − lo² ≤ hi² − lo²：q ≤ hi² 两侧加 −lo² *)
    apply (proj2 (Qle_comp (q - qlo q n * qlo q n)
                           (q + (- (qlo q n * qlo q n)))
                           ltac:(unfold Qminus; reflexivity)
                           (qhi q n * qhi q n - qlo q n * qlo q n)
                           (qhi q n * qhi q n + (- (qlo q n * qlo q n)))
                           ltac:(unfold Qminus; reflexivity))).
    apply (Qplus_le_compat q (qhi q n * qhi q n) (- (qlo q n * qlo q n)) (- (qlo q n * qlo q n))).
    - destruct (qbisec_inv q Hq n) as [_ [Hqle _]]. exact Hqle.
    - apply Qle_refl.
  - (* hi² − lo² == (hi−lo)(hi+lo)（field） *)
    apply (proj2 (Qle_comp (qhi q n * qhi q n - qlo q n * qlo q n)
                           ((qhi q n - qlo q n) * (qhi q n + qlo q n))
                           ltac:(field)
                           ((qhi q n - qlo q n) * (qhi q n + qlo q n))
                           ((qhi q n - qlo q n) * (qhi q n + qlo q n))
                           (Qeq_refl _))).
    apply Qle_refl.
Qed.

End M3Q.

(* ============ CR 层：平方与 sqrt ============ *)

Local Open Scope ConstructiveReals.

Section M3.

Context {R : ConstructiveReals}.
Add Ring CR_ring : (CRisRing R).

(* CR_of_Q 的平方保持：CR_of_Q (q*r) == CR_of_Q q * CR_of_Q r *)
Lemma CR_of_Q_sq (q : Q) :
  CReq R (CR_of_Q R (q * q)) (CR_of_Q R q * CR_of_Q R q).
Proof.
  apply CR_of_Q_mult.
Qed.

(* CR_of_Q 的减法保持：CR_of_Q (q - r) == CR_of_Q q - CR_of_Q r *)
Lemma m3_CR_of_Q_minus (q r : Q) :
  CReq R (CR_of_Q R (q - r)) (CR_of_Q R q - CR_of_Q R r).
Proof.
  (* q - r == q + (-r)；CR_of_Q_plus + CR_of_Q_opp *)
  transitivity (CR_of_Q R (q + (- r))).
  - apply (CR_of_Q_morph R (q - r) (q + (- r))).
    unfold Qminus. reflexivity.
  - transitivity (CR_of_Q R q + CR_of_Q R (- r)).
    + apply CR_of_Q_plus.
    + apply (CRplus_morph_Proper
               (CR_of_Q R q) (CR_of_Q R q) (CReq_refl _)
               (CR_of_Q R (- r)) (- CR_of_Q R r)
               (CR_of_Q_opp r)).
Qed.

(* CR_of_Q 的序保持：q ≤ r ⟹ CR_of_Q q ≤ CR_of_Q r *)
Lemma CR_of_Q_le' (q r : Q) : (q <= r)%Q -> CRle R (CR_of_Q R q) (CR_of_Q R r).
Proof. apply CR_of_Q_le. Qed.

(* CR_of_Q 的严格序保持：q < r ⟹ CR_of_Q q < CR_of_Q r *)
Lemma CR_of_Q_lt' (q r : Q) : (q < r)%Q -> CRlt R (CR_of_Q R q) (CR_of_Q R r).
Proof. apply CR_of_Q_lt. Qed.

(* ============ CRsqrt：二分序列的 CR 极限 ============ *)

(* qlo 序列的 CR 版本 *)
Definition CRsqrseq (q : Q) (n : nat) : CRcarrier R :=
  CR_of_Q R (qlo q n).

(* qhi 序列的 CR 版本 *)
Definition CRsqrseq_hi (q : Q) (n : nat) : CRcarrier R :=
  CR_of_Q R (qhi q n).

(* 上界：m,n ≥ k ⟹ u_m − u_n ≤ CR_of_Q (qhi q k − qlo q k) *)
Lemma CRsqrseq_ub (q : Q) (Hq : (0 <= q)%Q) (m n k : nat) :
  (k <= m)%nat -> (k <= n)%nat ->
  CRle R (CRsqrseq q m - CRsqrseq q n) (CR_of_Q R ((qhi q k) - (qlo q k))).
Proof.
  intros Hkm Hkn.
  (* u_m − u_n == CR_of_Q (qlo m − qlo n)（m3_CR_of_Q_minus）*)
  apply (proj2 (CRle_morph R
           (CRsqrseq q m - CRsqrseq q n)
           (CR_of_Q R ((qlo q m) - (qlo q n)))
           ltac:(unfold CRsqrseq; apply CReq_sym; apply (m3_CR_of_Q_minus (qlo q m) (qlo q n)))
           (CR_of_Q R ((qhi q k) - (qlo q k)))
           (CR_of_Q R ((qhi q k) - (qlo q k)))
           (CReq_refl _))).
  (* CR_of_Q (qlo m − qlo n) ≤ CR_of_Q (qhi k − qlo k)：由 qlo_gap_width（Q 层） *)
  apply CR_of_Q_le'.
  apply (qlo_gap_width q Hq m n k). exact Hkm. exact Hkn.
Qed.

(* 对称下界：m,n ≥ k ⟹ −(u_m − u_n) ≤ CR_of_Q (qhi q k − qlo q k) *)
Lemma CRsqrseq_lb (q : Q) (Hq : (0 <= q)%Q) (m n k : nat) :
  (k <= m)%nat -> (k <= n)%nat ->
  CRle R (- (CRsqrseq q m - CRsqrseq q n)) (CR_of_Q R ((qhi q k) - (qlo q k))).
Proof.
  intros Hkm Hkn.
  (* −(u_m − u_n) == u_n − u_m（ring）*)
  apply (proj2 (CRle_morph R
           (- (CRsqrseq q m - CRsqrseq q n))
           (CRsqrseq q n - CRsqrseq q m)
           ltac:(unfold CRminus; ring)
           (CR_of_Q R ((qhi q k) - (qlo q k)))
           (CR_of_Q R ((qhi q k) - (qlo q k)))
           (CReq_refl _))).
  apply CRsqrseq_ub. exact Hq. exact Hkn. exact Hkm.
Qed.

(* qlo 序列 Cauchy（用 CRabs_def 拆两方向）：m,n ≥ k ⟹ |u_m − u_n| ≤ CR_of_Q ((q+1)/2^k) *)
Lemma CRsqrseq_gap (q : Q) (Hq : (0 <= q)%Q) (m n k : nat) :
  (k <= m)%nat -> (k <= n)%nat ->
  CRle R (CRabs R (CRsqrseq q m - CRsqrseq q n)) (CR_of_Q R ((q + 1) / qpow2 k)).
Proof.
  intros Hkm Hkn.
  (* CRabs_def : (x≤y ∧ −x≤y) ↔ |x|≤y；proj2 拆 *)
  apply (proj1 (CRabs_def R (CRsqrseq q m - CRsqrseq q n)
                           (CR_of_Q R ((q + 1) / qpow2 k)))).
  split.
  - (* u_m − u_n ≤ (q+1)/2^k *)
    apply (CRle_trans _ (CR_of_Q R (((qhi q k) - (qlo q k))%Q)) _).
    + apply CRsqrseq_ub. exact Hq. exact Hkm. exact Hkn.
    + (* CR_of_Q (qhi k − qlo k) ≤ CR_of_Q ((q+1)/2^k) *)
      apply CR_of_Q_le'.
      apply (proj2 (Qle_comp (((qhi q k) - (qlo q k))%Q) (((q + 1) / qpow2 k)%Q)
                             (qwidth_closed q k) _ _ (Qeq_refl _))).
      apply Qle_refl.
  - (* −(u_m − u_n) ≤ (q+1)/2^k *)
    apply (CRle_trans _ (CR_of_Q R (((qhi q k) - (qlo q k))%Q)) _).
    + apply CRsqrseq_lb. exact Hq. exact Hkm. exact Hkn.
    + apply CR_of_Q_le'.
      apply (proj2 (Qle_comp (((qhi q k) - (qlo q k))%Q) (((q + 1) / qpow2 k)%Q)
                             (qwidth_closed q k) _ _ (Qeq_refl _))).
      apply Qle_refl.
Qed.

(* ============ CRsqrt：CR_complete 取极限 ============ *)

(* qlo 序列 Cauchy：∀p, ∃N, ∀m,n≥N, |u_m−u_n| ≤ 1/p *)
Lemma CRsqrseq_cauchy (q : Q) (Hq : (0 <= q)%Q) :
  CR_cauchy R (CRsqrseq q).
Proof.
  intros p.
  (* 选 K 使 (q+1)/2^K ≤ 1/p（qwidth_archimedean） *)
  destruct (qwidth_archimedean q p) as [K HK].
  exists K.
  intros m n Hm Hn.
  (* |u_m − u_n| ≤ CR_of_Q ((q+1)/2^K) ≤ CR_of_Q (1/p) == 1/p *)
  apply (CRle_trans _ (CR_of_Q R (((q + 1) / qpow2 K)%Q)) _).
  - (* |u_m − u_n| ≤ CR_of_Q ((q+1)/2^K)：CRsqrseq_gap *)
    apply (CRsqrseq_gap q Hq m n K). exact Hm. exact Hn.
  - (* CR_of_Q ((q+1)/2^K) ≤ CR_of_Q (1/p)：由 Q 层 HK *)
    apply CR_of_Q_le'.
    exact HK.
Qed.

(* CRsqrt 定义：qlo 序列的 CR 极限 *)
Definition CRsqrt (q : Q) (Hq : (0 <= q)%Q) : CRcarrier R :=
  projT1 (CR_complete R (CRsqrseq q) (CRsqrseq_cauchy q Hq)).

Lemma CRsqrt_cv (q : Q) (Hq : (0 <= q)%Q) :
  CR_cv R (CRsqrseq q) (CRsqrt q Hq).
Proof.
  unfold CRsqrt.
  exact (projT2 (CR_complete R (CRsqrseq q) (CRsqrseq_cauchy q Hq))).
Qed.

(* ============ 构造性极限乘法（CR_cv_mult，Stdlib 缺失，自建） ============ *)

(* 0 < 1 (CR) *)
Lemma CR_0_lt_1 : CR_of_Q R 0 < CR_of_Q R (1 # 1).
Proof.
  apply CR_of_Q_lt. vm_compute. reflexivity.
Qed.

(* 收敛序列最终有界：xn → a ⟹ ∃N M, ∀n≥N, |xn| ≤ M 且 0 ≤ M *)
Lemma m3_CR_cv_abs_bounded (xn : nat -> CRcarrier R) (a : CRcarrier R) :
  CR_cv R xn a ->
  {N : nat & {M : CRcarrier R | (forall n, (N <= n)%nat -> CRabs R (xn n) <= M)
        /\ CR_of_Q R 0 <= M}}.
Proof.
  intros Hcv.
  destruct (Hcv 1%positive) as [N HN].
  exists N. exists (CR_of_Q R (1 # 1) + CRabs R a).
  split.
  - intros n Hn.
    apply (CRle_trans _ (CRabs R (xn n - a) + CRabs R a) _).
    + (* |xn| ≤ |xn−a| + |a|：|xn| == |(xn−a)+a| ≤ |xn−a|+|a| *)
      apply (proj2 (CRle_morph R
               (CRabs R (xn n)) (CRabs R ((xn n - a) + a))
               ltac:(apply (CRabs_morph_prop R (xn n) ((xn n - a) + a)); unfold CRminus; ring)
               (CRabs R (xn n - a) + CRabs R a) (CRabs R (xn n - a) + CRabs R a) (CReq_refl _))).
      apply (CRabs_triang (xn n - a) a).
    + (* |xn−a| + |a| ≤ 1 + |a| *)
      apply (CRplus_le_compat (CRabs R (xn n - a)) (CR_of_Q R (1 # 1))
                              (CRabs R a) (CRabs R a)).
      * exact (HN n Hn).
      * apply CRle_refl.
  - (* 0 ≤ 1 + |a| *)
    apply (CRle_trans _ (CR_of_Q R (1 # 1)) _).
    + apply CRlt_asym. apply CR_0_lt_1.
    + apply (proj2 (CRle_morph R
               (CR_of_Q R (1 # 1)) (CR_of_Q R (1 # 1) + CR_of_Q R 0) ltac:(ring)
               (CR_of_Q R (1 # 1) + CRabs R a) (CR_of_Q R (1 # 1) + CRabs R a) (CReq_refl _))).
      apply (CRplus_le_compat (CR_of_Q R (1 # 1)) (CR_of_Q R (1 # 1))
                              (CR_of_Q R 0) (CRabs R a)).
      * apply CRle_refl.
      * apply (CRabs_pos a).
Qed.

(* |xn·yn| ≤ M·|yn|：|xn·yn| == |xn|·|yn| ≤ M·|yn| *)
Lemma step1 (xn yn : nat -> CRcarrier R) (M : CRcarrier R) (k : nat) :
  CRabs R (xn k) <= M ->
  CRabs R (xn k * yn k) <= M * CRabs R (yn k).
Proof.
  intros Hx.
  apply (proj2 (CRle_morph R
           (CRabs R (xn k * yn k)) (CRabs R (xn k) * CRabs R (yn k))
           (CRabs_mult (xn k) (yn k))
           (M * CRabs R (yn k)) (M * CRabs R (yn k)) (CReq_refl _))).
  apply (CRmult_le_compat_r (CRabs R (yn k)) (CRabs R (xn k)) M).
  - apply (CRabs_pos (yn k)).
  - exact Hx.
Qed.

(* M·|yn| ≤ n·(1/(n·p))：M ≤ n 且 |yn| ≤ 1/(n·p) *)
Lemma step2 (yn : nat -> CRcarrier R) (M : CRcarrier R) (n : positive) (p : positive) (k : nat) :
  M <= CR_of_Q R (Z.pos n # 1) ->
  CRabs R (yn k) <= CR_of_Q R (1 # Pos.mul n p) ->
  CR_of_Q R 0 <= CRabs R (yn k) ->
  CR_of_Q R 0 <= CR_of_Q R (Z.pos n # 1) ->
  M * CRabs R (yn k) <=
    CR_of_Q R (Z.pos n # 1) * CR_of_Q R (1 # Pos.mul n p).
Proof.
  intros HMn Hy1p Hyn0 Hn0.
  apply (CRle_trans _ (CR_of_Q R (Z.pos n # 1) * CRabs R (yn k)) _).
  - apply (CRmult_le_compat_r (CRabs R (yn k)) M (CR_of_Q R (Z.pos n # 1))).
    + exact Hyn0.
    + exact HMn.
  - apply (CRmult_le_compat_l (CR_of_Q R (Z.pos n # 1)) (CRabs R (yn k))
                              (CR_of_Q R (1 # Pos.mul n p))).
    + exact Hn0.
    + exact Hy1p.
Qed.

(* n·(1/(n·p)) == 1/p（Q 层恒等式，CR_of_Q 提升） *)
Lemma n_mul_inv_np (n : positive) (p : positive) :
  CReq R (CR_of_Q R (Z.pos n # 1) * CR_of_Q R (1 # Pos.mul n p))
         (CR_of_Q R (1 # p)).
Proof.
  transitivity (CR_of_Q R ((Z.pos n # 1) * (1 # Pos.mul n p))).
  - apply CReq_sym. apply CR_of_Q_mult.
  - apply (CR_of_Q_morph R ((Z.pos n # 1) * (1 # Pos.mul n p)) (1 # p)).
    unfold Qeq. simpl. lia.
Qed.

(* 0 ≤ n（CR_of_Q 提升） *)
Lemma CR_pos_le_0 (n : positive) : CR_of_Q R 0 <= CR_of_Q R (Z.pos n # 1).
Proof.
  apply CR_of_Q_le. unfold Qle. simpl. lia.
Qed.

(* |y−0| == |y| *)
Lemma abs_minus_0 (yn : CRcarrier R) : CReq R (CRabs R (yn - 0)) (CRabs R yn).
Proof.
  apply (CRabs_morph_prop R (yn - 0) yn). unfold CRminus. ring.
Qed.

(* 有界序列 × 趋于 0 的序列 → 趋于 0 *)
Lemma bounded_times_cv0 (xn yn : nat -> CRcarrier R) (M : CRcarrier R) :
  {N : nat | forall n, (N <= n)%nat -> CRabs R (xn n) <= M} ->
  CR_cv R yn 0 ->
  CR_cv R (fun n => xn n * yn n) 0.
Proof.
  intros [N Hbound] Hy0.
  destruct (CR_archimedean R M) as [n Hn].
  intros p.
  destruct (Hy0 (Pos.mul n p)) as [N1 HN1].
  exists (Nat.max N N1).
  intros k Hk.
  assert (Hk1 : (N <= k)%nat).
  { apply (Nat.le_trans _ (Nat.max N N1) _).
    apply Nat.le_max_l.
    exact Hk. }
  assert (Hk2 : (N1 <= k)%nat).
  { apply (Nat.le_trans _ (Nat.max N N1) _).
    apply Nat.le_max_r.
    exact Hk. }
  apply (CRle_trans _ (M * CRabs R (yn k)) _).
  - apply (proj2 (CRle_morph R
           (CRabs R (xn k * yn k - 0)) (CRabs R (xn k * yn k))
           (abs_minus_0 (xn k * yn k))
           (M * CRabs R (yn k)) (M * CRabs R (yn k)) (CReq_refl _))).
    apply step1. exact (Hbound k Hk1).
  - apply (CRle_trans _ (CR_of_Q R (Z.pos n # 1) * CR_of_Q R (1 # Pos.mul n p)) _).
    + apply (step2 yn M n p k).
      * apply CRlt_asym. exact Hn.
      * apply (proj1 (CRle_morph R
                 (CRabs R (yn k - 0)) (CRabs R (yn k))
                 (abs_minus_0 (yn k))
                 (CR_of_Q R (1 # Pos.mul n p)) (CR_of_Q R (1 # Pos.mul n p)) (CReq_refl _))).
        apply HN1. exact Hk2.
      * apply (CRabs_pos (yn k)).
      * apply CR_pos_le_0.
    + apply (proj2 (n_mul_inv_np n p)).
Qed.

(* |u| → 0 ⟹ u → 0（CR_cv_abs_cont 的逆用：|u_n|→0 则 u_n→0） *)
Lemma abs_cv0 (u : nat -> CRcarrier R) :
  CR_cv R (fun n => CRabs R (u n)) 0 -> CR_cv R u 0.
Proof.
  intros Hu.
  intros p.
  destruct (Hu p) as [N HN].
  exists N.
  intros n Hn.
  apply (proj1 (CRle_morph R
           (CRabs R (u n)) (CRabs R (u n - 0))
           (CReq_sym _ _ (abs_minus_0 (u n)))
           (CR_of_Q R (1 # p)) (CR_of_Q R (1 # p)) (CReq_refl _))).
  apply (proj2 (CRle_morph R
           (CRabs R (u n)) (CRabs R (CRabs R (u n) - 0))
           ltac:(apply CReq_trans with (CRabs R (CRabs R (u n)));
                 [apply CReq_sym; apply (CRabs_right (CRabs R (u n))); apply (CRabs_pos (u n)) |
                  apply CReq_sym; apply (abs_minus_0 (CRabs R (u n)))])
           (CR_of_Q R (1 # p)) (CR_of_Q R (1 # p)) (CReq_refl _))).
  exact (HN n Hn).
Qed.

Lemma squeeze_cv0 (z w : nat -> CRcarrier R) :
  (forall n, CR_of_Q R 0 <= z n) ->
  (forall n, z n <= w n) ->
  CR_cv R w 0 -> CR_cv R z 0.
Proof.
  intros Hz0 Hzw Hw.
  assert (Hw0 : forall n, CR_of_Q R 0 <= w n).
  { intros n. apply (CRle_trans _ (z n) _). apply Hz0. apply Hzw. }
  intros p.
  destruct (Hw p) as [N HN].
  exists N.
  intros n Hn.
  apply (proj1 (CRle_morph R
           (z n) (CRabs R (z n - 0))
           ltac:(apply CReq_trans with (CRabs R (z n));
                 [apply CReq_sym; apply (CRabs_right (z n)); apply (Hz0 n) |
                  apply CReq_sym; apply (abs_minus_0 (z n))])
           (CR_of_Q R (1 # p)) (CR_of_Q R (1 # p)) (CReq_refl _))).
  apply (CRle_trans _ (w n) _).
  - exact (Hzw n).
  - apply (proj2 (CRle_morph R
             (w n) (CRabs R (w n - 0))
             ltac:(apply CReq_trans with (CRabs R (w n));
                   [apply CReq_sym; apply (CRabs_right (w n)); apply (Hw0 n) |
                    apply CReq_sym; apply (abs_minus_0 (w n))])
             (CR_of_Q R (1 # p)) (CR_of_Q R (1 # p)) (CReq_refl _))).
    exact (HN n Hn).
Qed.

(* ============ 构造性极限乘法 m3_CR_cv_mult（Stdlib 缺失，自建完成） ============ *)
(* xn → a, yn → b ⟹ xn·yn → a·b
   分解：xn·yn − a·b = xn·(yn−b) + (xn−a)·b
   |xn·(yn−b)| → 0：xn 最终有界（m3_CR_cv_abs_bounded）× (yn−b)→0（bounded_times_cv0）
   |(xn−a)·b| → 0：b 常值有界 × (xn−a)→0（bounded_times_cv0）
   三角不等式 + squeeze_cv0 + abs_cv0 收尾 *)
Lemma m3_CR_cv_mult (xn yn : nat -> CRcarrier R) (a b : CRcarrier R) :
  CR_cv R xn a -> CR_cv R yn b ->
  CR_cv R (fun n => xn n * yn n) (a * b).
Proof.
  intros Hx Hy.
  assert (Hdiff : CR_cv R (fun n => xn n * yn n - a * b) 0).
  { apply abs_cv0.
    apply (squeeze_cv0
      (fun n => CRabs R (xn n * yn n - a * b))
      (fun n => CRabs R (xn n * (yn n - b)) + CRabs R ((xn n - a) * b))).
    - intros n. apply (CRabs_pos (xn n * yn n - a * b)).
    - intros n.
      apply (proj2 (CRle_morph R
               (CRabs R (xn n * yn n - a * b))
               (CRabs R (xn n * (yn n - b) + (xn n - a) * b))
               ltac:(apply (CRabs_morph_prop R
                      (xn n * yn n - a * b)
                      (xn n * (yn n - b) + (xn n - a) * b));
                     unfold CRminus; ring)
               (CRabs R (xn n * (yn n - b)) + CRabs R ((xn n - a) * b))
               (CRabs R (xn n * (yn n - b)) + CRabs R ((xn n - a) * b))
               (CReq_refl _))).
      apply (CRabs_triang (xn n * (yn n - b)) ((xn n - a) * b)).
    - apply (CR_cv_proper
        (fun n => CRabs R (xn n * (yn n - b)) + CRabs R ((xn n - a) * b))
        (CR_of_Q R 0 + CR_of_Q R 0) (CR_of_Q R 0)).
      + apply (CR_cv_plus
          (fun n => CRabs R (xn n * (yn n - b)))
          (fun n => CRabs R ((xn n - a) * b)) 0 0).
        * apply (CR_cv_proper _ (CRabs R 0) _).
          -- apply CR_cv_abs_cont.
             destruct (m3_CR_cv_abs_bounded xn a Hx) as [N [M [Hbd Hm0]]].
             apply (bounded_times_cv0 xn (fun n => yn n - b) M).
             ++ exists N. exact Hbd.
             ++ apply (CR_cv_proper _ (b - b) _).
                ** apply CR_cv_minus. exact Hy. apply CR_cv_const.
                ** unfold CRminus. ring.
          -- apply CRabs_right. apply CRle_refl.
        * apply (CR_cv_proper _ (CRabs R 0) _).
          -- apply CR_cv_abs_cont.
             apply (CR_cv_eq (fun n => (xn n - a) * b) (fun n => b * (xn n - a)) 0).
             ++ intros n. unfold CRminus. ring.
             ++ apply (bounded_times_cv0 (fun _ => b) (fun n => xn n - a) (CRabs R b)).
                ** exists 0%nat. intros n Hn. apply CRle_refl.
                ** apply (CR_cv_proper _ (a - a) _).
                   *** apply CR_cv_minus. exact Hx. apply CR_cv_const.
                   *** unfold CRminus. ring.
          -- apply CRabs_right. apply CRle_refl.
      + ring.
  }
  apply (CR_cv_eq (fun n => xn n * yn n)
                  (fun n => (xn n * yn n - a * b) + a * b)
                  (a * b)).
  - intros n. unfold CRminus. ring.
  - apply (CR_cv_proper _ (CR_of_Q R 0 + a * b) _).
    + apply CR_cv_plus.
      * exact Hdiff.
      * apply CR_cv_const.
    + ring.
Qed.

(* ============ 极限² = q（CR 层收官） ============ *)

(* 宽度序列 → 0：CR_cv (fun n => CR_of_Q ((q+1)/2^n)) 0
   （qwidth_archimedean 给 K 使 width K ≤ 1/p；width 单调降 ⟹ n≥K 时 width n ≤ 1/p） *)
Lemma CR_of_Q_width_cv0 (q : Q) (Hq : (0 <= q)%Q) :
  CR_cv R (fun n => CR_of_Q R ((q + 1) / qpow2 n)) 0.
Proof.
  intros p.
  destruct (qwidth_archimedean q p) as [K HK].
  exists K.
  intros n Hn.
  apply (proj1 (CRle_morph R
           (CR_of_Q R ((q + 1) / qpow2 n)) (CRabs R (CR_of_Q R ((q + 1) / qpow2 n) - 0))
           ltac:(apply CReq_trans with (CRabs R (CR_of_Q R ((q + 1) / qpow2 n)));
                 [apply CReq_sym; apply (CRabs_right (CR_of_Q R ((q + 1) / qpow2 n)));
                  apply (CR_of_Q_le' 0%Q ((q + 1) / qpow2 n)%Q);
                  apply (proj2 (Qle_comp 0%Q 0%Q (Qeq_refl 0%Q) ((q + 1) / qpow2 n)%Q (qhi q n - qlo q n)%Q
                                (Qeq_sym _ _ (qwidth_closed q n))));
                  exact (qwidth_nonneg q Hq n) |
                  apply CReq_sym; apply (abs_minus_0 (CR_of_Q R ((q + 1) / qpow2 n)))])
           (CR_of_Q R (1 # p)) (CR_of_Q R (1 # p)) (CReq_refl _))).
  apply (CRle_trans _ (CR_of_Q R ((q + 1) / qpow2 K)) _).
  - apply (proj2 (CRle_morph R
             (CR_of_Q R ((q + 1) / qpow2 n)) (CR_of_Q R (qhi q n - qlo q n))
             ltac:(apply (CR_of_Q_morph R ((q + 1) / qpow2 n) (qhi q n - qlo q n)); apply (Qeq_sym _ _ (qwidth_closed q n)))
             (CR_of_Q R ((q + 1) / qpow2 K)) (CR_of_Q R (qhi q K - qlo q K))
             ltac:(apply (CR_of_Q_morph R ((q + 1) / qpow2 K) (qhi q K - qlo q K)); apply (Qeq_sym _ _ (qwidth_closed q K))))).
    apply CR_of_Q_le'.
    apply (qwidth_mono_multi q Hq K n). exact Hn.
  - apply CR_of_Q_le'. exact HK.
Qed.

(* gap_prod == width·CR_of_Q(hi+lo) 的 CR 拆分（qwidth_closed + CR_of_Q_mult） *)
Lemma CRsqrseq_gap_prod_eq (q : Q) (n : nat) :
  CReq R (CR_of_Q R ((qhi q n - qlo q n) * (qhi q n + qlo q n)))
         (CR_of_Q R ((q + 1) / qpow2 n) * CR_of_Q R (qhi q n + qlo q n)).
Proof.
  transitivity (CR_of_Q R (((q + 1) / qpow2 n) * (qhi q n + qlo q n))%Q).
  - apply (CR_of_Q_morph R ((qhi q n - qlo q n) * (qhi q n + qlo q n))%Q
                           (((q + 1) / qpow2 n) * (qhi q n + qlo q n))%Q).
    rewrite (qwidth_closed q n). reflexivity.
  - apply CR_of_Q_mult.
Qed.

(* gap_prod → 0：squeeze gap_prod ≤ width·CR_of_Q(2(q+1)) → 0 *)
Lemma CRsqrseq_gap_prod_cv (q : Q) (Hq : (0 <= q)%Q) :
  CR_cv R (fun n => CR_of_Q R ((qhi q n - qlo q n) * (qhi q n + qlo q n))) 0.
Proof.
  apply (squeeze_cv0
    (fun n => CR_of_Q R ((qhi q n - qlo q n) * (qhi q n + qlo q n)))
    (fun n => CR_of_Q R ((q + 1) / qpow2 n) * CR_of_Q R (2 * (q + 1)))).
  - intros n.
    apply (CR_of_Q_le' 0%Q ((qhi q n - qlo q n) * (qhi q n + qlo q n))%Q).
    apply Qmult_le_0_compat.
    + apply qwidth_nonneg. exact Hq.
    + apply (proj2 (Qle_comp 0%Q (0 + 0)%Q (Qeq_sym _ _ (Qplus_0_l 0%Q))
                            (qhi q n + qlo q n)%Q (qlo q n + qhi q n)%Q (Qplus_comm (qhi q n) (qlo q n)))).
      apply (Qplus_le_compat 0%Q (qlo q n) 0%Q (qhi q n)).
      * apply qlo_ge_0. exact Hq.
      * apply (Qle_trans _ (qlo q n) _).
        -- apply qlo_ge_0. exact Hq.
        -- destruct (qbisec_inv q Hq n) as [_ [_ Hle]]. exact Hle.
  - intros n.
    apply (CRle_trans _ (CR_of_Q R ((q + 1) / qpow2 n) * CR_of_Q R (qhi q n + qlo q n)) _).
    + apply (proj2 (CRle_morph R
             (CR_of_Q R ((qhi q n - qlo q n) * (qhi q n + qlo q n)))
             (CR_of_Q R ((q + 1) / qpow2 n) * CR_of_Q R (qhi q n + qlo q n))
             (CRsqrseq_gap_prod_eq q n)
             (CR_of_Q R ((q + 1) / qpow2 n) * CR_of_Q R (qhi q n + qlo q n))
             (CR_of_Q R ((q + 1) / qpow2 n) * CR_of_Q R (qhi q n + qlo q n)) (CReq_refl _))).
      apply CRle_refl.
    + apply (CRmult_le_compat_l (CR_of_Q R ((q + 1) / qpow2 n))
                                (CR_of_Q R (qhi q n + qlo q n)) (CR_of_Q R (2 * (q + 1)))).
      * apply CR_of_Q_le'. apply qwidth_nonneg_closed. exact Hq.
      * apply CR_of_Q_le'. apply qsum_bound'. exact Hq.
  - apply (CR_cv_proper _ (CR_of_Q R 0 * CR_of_Q R (2 * (q + 1))) _).
    + apply CR_cv_scale. apply CR_of_Q_width_cv0. exact Hq.
    + ring.
Qed.

(* |lo_n² − q| == CR_of_Q(q − lo_n²)（lo² ≤ q，CRabs_left） *)
Lemma CRsqr_sq_minus (q : Q) (Hq : (0 <= q)%Q) (n : nat) :
  CReq R (CR_of_Q R (q - qlo q n * qlo q n))
         (CRabs R (CRsqrseq q n * CRsqrseq q n - CR_of_Q R q)).
Proof.
  unfold CRsqrseq.
  apply CReq_sym.
  apply (CReq_trans _ (CRabs R (CR_of_Q R (qlo q n * qlo q n) - CR_of_Q R q)) _).
  - apply (CRabs_morph_prop R
             (CR_of_Q R (qlo q n) * CR_of_Q R (qlo q n) - CR_of_Q R q)
             (CR_of_Q R (qlo q n * qlo q n) - CR_of_Q R q)).
    apply (CRplus_morph_Proper
             (CR_of_Q R (qlo q n) * CR_of_Q R (qlo q n)) (CR_of_Q R (qlo q n * qlo q n))
             (CReq_sym _ _ (CR_of_Q_mult R (qlo q n) (qlo q n)))
             (- CR_of_Q R q) (- CR_of_Q R q) (CReq_refl _)).
  - apply (CReq_trans _ (CRabs R (CR_of_Q R (qlo q n * qlo q n - q))) _).
    + apply (CRabs_morph_prop R
               (CR_of_Q R (qlo q n * qlo q n) - CR_of_Q R q)
               (CR_of_Q R (qlo q n * qlo q n - q))).
      apply CReq_sym. apply (m3_CR_of_Q_minus (qlo q n * qlo q n) q).
    + apply (CReq_trans _ (- CR_of_Q R (qlo q n * qlo q n - q)) _).
      * apply CRabs_left.
        apply (CR_of_Q_le' (qlo q n * qlo q n - q)%Q 0%Q).
        apply (proj2 (Qle_minus_iff (qlo q n * qlo q n - q)%Q 0%Q)).
        apply (proj2 (Qle_comp 0%Q 0%Q (Qeq_refl 0%Q)
                      (0 - (qlo q n * qlo q n - q))%Q (q - qlo q n * qlo q n)%Q ltac:(field))).
        apply (proj1 (Qle_minus_iff (qlo q n * qlo q n)%Q q)).
        destruct (qbisec_inv q Hq n) as [Hlo2 _]. exact Hlo2.
      * apply (CReq_trans _ (CR_of_Q R (- (qlo q n * qlo q n - q))) _).
        -- apply CReq_sym. apply (CR_of_Q_opp (qlo q n * qlo q n - q)).
        -- apply (CR_of_Q_morph R (- (qlo q n * qlo q n - q)) (q - qlo q n * qlo q n)).
           field.
Qed.

(* lo_n² → q：|lo²−q| ≤ gap_prod（squeeze）+ gap_prod → 0 *)
Lemma CRsqrseq_sq_cv (q : Q) (Hq : (0 <= q)%Q) :
  CR_cv R (fun n => CRsqrseq q n * CRsqrseq q n) (CR_of_Q R q).
Proof.
  apply (CR_cv_eq (fun n => CRsqrseq q n * CRsqrseq q n)
                  (fun n => (CRsqrseq q n * CRsqrseq q n - CR_of_Q R q) + CR_of_Q R q)
                  (CR_of_Q R q)).
  - intros n. unfold CRminus. ring.
  - apply (CR_cv_proper _ (CR_of_Q R 0 + CR_of_Q R q) _).
    + apply CR_cv_plus.
      * apply abs_cv0.
        apply (squeeze_cv0
          (fun n => CRabs R (CRsqrseq q n * CRsqrseq q n - CR_of_Q R q))
          (fun n => CR_of_Q R ((qhi q n - qlo q n) * (qhi q n + qlo q n)))).
        -- intros n. apply (CRabs_pos (CRsqrseq q n * CRsqrseq q n - CR_of_Q R q)).
        -- intros n.
           apply (proj2 (CRle_morph R
                    (CRabs R (CRsqrseq q n * CRsqrseq q n - CR_of_Q R q))
                    (CR_of_Q R (q - qlo q n * qlo q n))
                    (CReq_sym _ _ (CRsqr_sq_minus q Hq n))
                    (CR_of_Q R ((qhi q n - qlo q n) * (qhi q n + qlo q n)))
                    (CR_of_Q R ((qhi q n - qlo q n) * (qhi q n + qlo q n))) (CReq_refl _))).
           apply CR_of_Q_le'.
           apply (q_lo_sq_sub q Hq n).
        -- apply CRsqrseq_gap_prod_cv. exact Hq.
      * apply CR_cv_const.
    + ring.
Qed.

(* 主定理：CRsqrt² == q（CR_cv_mult + 唯一性） *)
Lemma CRsqrt_sq (q : Q) (Hq : (0 <= q)%Q) :
  CReq R (CRsqrt q Hq * CRsqrt q Hq) (CR_of_Q R q).
Proof.
  apply (CR_cv_unique (fun n => CRsqrseq q n * CRsqrseq q n)
          (CRsqrt q Hq * CRsqrt q Hq) (CR_of_Q R q)).
  - apply (m3_CR_cv_mult (CRsqrseq q) (CRsqrseq q) (CRsqrt q Hq) (CRsqrt q Hq)).
    + apply (CRsqrt_cv q Hq).
    + apply (CRsqrt_cv q Hq).
  - apply (CRsqrseq_sq_cv q Hq).
Qed.

(* ============ M3 数值界：CRsqrt 21 ≥ 4582/1000、CRsqrt 105 ≥ 10246/1000 ============
   代数路线（P4 非平凡化）：Q 层平方界 (4582/1000)² ≤ 21 + 非负平方单调
   ——替代 qbisec 有限步 vm_compute 核验；qbisec 核验 qlo21_20_ge/qlo105_20_ge
   保留作交叉验证记录。 *)

(* 极限 ≥ 单调递增序列每项：CRsqrt q ≥ CR_of_Q (qlo q n) *)
Lemma CRsqrt_ge_qlo (q : Q) (Hq : (0 <= q)%Q) (n : nat) :
  CRle R (CR_of_Q R (qlo q n)) (CRsqrt q Hq).
Proof.
  apply (CR_cv_bound_down (CRsqrseq q) (CR_of_Q R (qlo q n)) (CRsqrt q Hq) n).
  - intros m Hm.
    apply CR_of_Q_le'.
    apply (qlo_mono_multi q Hq n m). exact Hm.
  - apply (CRsqrt_cv q Hq).
Qed.

(* 21 ≥ 0、105 ≥ 0（Q 层） *)
Lemma Q21_nonneg : (0 <= 21 # 1)%Q.
Proof. vm_compute. discriminate. Qed.

Lemma Q105_nonneg : (0 <= 105 # 1)%Q.
Proof. vm_compute. discriminate. Qed.

(* qbisec 有限步下逼近核验（交叉验证记录；主证明走下方代数平方界） *)
Lemma qlo21_20_ge : (4582 # 1000 <= qlo (21 # 1) 20)%Q.
Proof. vm_compute. discriminate. Qed.

Lemma qlo105_20_ge : (10246 # 1000 <= qlo (105 # 1) 20)%Q.
Proof. vm_compute. discriminate. Qed.

(* ===== 代数化：Q 层平方界 + 非负平方单调（P4，替代 vm_compute） ===== *)

(* Q 层平方界与界值非负：(4582/1000)² ≤ 21、0 ≤ 4582/1000（unfold Qle; simpl; lia） *)
Lemma q21_sq_bound : ((4582 # 1000) * (4582 # 1000) <= (21 # 1))%Q.
Proof. unfold Qle. simpl. lia. Qed.

Lemma Q4582_nonneg : (0 <= 4582 # 1000)%Q.
Proof. unfold Qle. simpl. lia. Qed.

Lemma q105_sq_bound : ((10246 # 1000) * (10246 # 1000) <= (105 # 1))%Q.
Proof. unfold Qle. simpl. lia. Qed.

Lemma Q10246_nonneg : (0 <= 10246 # 1000)%Q.
Proof. unfold Qle. simpl. lia. Qed.

(* 非负平方单调：0≤x → 0≤y → x²≤y² → x≤y
   （CRle := ¬(y<x)，反证 + 乘法保序：CRmult_lt_compat_l / CRmult_le_compat_r / CRle_lt_trans） *)
Lemma CRle_square_nonneg (x y : CRcarrier R) :
  CRle R (CR_of_Q R 0%Q) x -> CRle R (CR_of_Q R 0%Q) y ->
  CRle R (x * x) (y * y) -> CRle R x y.
Proof.
  intros Hx Hy Hsq Hyx.
  assert (Hx0 : CRlt R (CR_of_Q R 0%Q) x).
  { apply (CRle_lt_trans (CR_of_Q R 0%Q) y x). exact Hy. exact Hyx. }
  assert (Hyxle : CRle R y x) by exact (CRlt_asym y x Hyx).
  assert (Hyysq : CRle R (y * y) (x * y)).
  { apply (CRmult_le_compat_r y y x). exact Hy. exact Hyxle. }
  assert (Hxy : CRlt R (x * y) (x * x)).
  { apply (CRmult_lt_compat_l x y x). exact Hx0. exact Hyx. }
  assert (Hyy : CRlt R (y * y) (x * x)).
  { apply (CRle_lt_trans (y * y) (x * y) (x * x)). exact Hyysq. exact Hxy. }
  exact (Hsq Hyy).
Qed.

(* CRsqrt 21 ≥ 4582/1000（代数：平方界 + 非负平方单调 + CRsqrt_sq） *)
Lemma sqrt21_lower :
  CRle R (CR_of_Q R (4582 # 1000)) (CRsqrt (21 # 1) Q21_nonneg).
Proof.
  apply (CRle_square_nonneg (CR_of_Q R (4582 # 1000)) (CRsqrt (21 # 1) Q21_nonneg)).
  - apply CR_of_Q_le'. exact Q4582_nonneg.
  - (* 0 ≤ CRsqrt 21：qlo 21 0 = 0，极限 ≥ 单调序列每项 *)
    assert (Hqlo0 : qlo (21 # 1) 0%nat = 0%Q) by (unfold qlo, qbisec; reflexivity).
    assert (Hsq0 : CRle R (CR_of_Q R (qlo (21 # 1) 0%nat)) (CRsqrt (21 # 1) Q21_nonneg)).
    { apply (CRsqrt_ge_qlo (21 # 1) Q21_nonneg 0%nat). }
    rewrite Hqlo0 in Hsq0. exact Hsq0.
  - (* (4582/1000)² ≤ (CRsqrt 21)²：CR_of_Q_mult 桥 + CRsqrt_sq *)
    apply (proj1 (CRle_morph R (CR_of_Q R ((4582 # 1000) * (4582 # 1000)))
                 (CR_of_Q R (4582 # 1000) * CR_of_Q R (4582 # 1000))
                 (CR_of_Q_mult R (4582 # 1000) (4582 # 1000))
                 (CR_of_Q R (21 # 1))
                 (CRsqrt (21 # 1) Q21_nonneg * CRsqrt (21 # 1) Q21_nonneg)
                 (CReq_sym (CRsqrt (21 # 1) Q21_nonneg * CRsqrt (21 # 1) Q21_nonneg)
                   (CR_of_Q R (21 # 1)) (CRsqrt_sq (21 # 1) Q21_nonneg)))).
    apply CR_of_Q_le'. exact q21_sq_bound.
Qed.

(* CRsqrt 105 ≥ 10246/1000（同上） *)
Lemma sqrt105_lower :
  CRle R (CR_of_Q R (10246 # 1000)) (CRsqrt (105 # 1) Q105_nonneg).
Proof.
  apply (CRle_square_nonneg (CR_of_Q R (10246 # 1000)) (CRsqrt (105 # 1) Q105_nonneg)).
  - apply CR_of_Q_le'. exact Q10246_nonneg.
  - assert (Hqlo0 : qlo (105 # 1) 0%nat = 0%Q) by (unfold qlo, qbisec; reflexivity).
    assert (Hsq0 : CRle R (CR_of_Q R (qlo (105 # 1) 0%nat)) (CRsqrt (105 # 1) Q105_nonneg)).
    { apply (CRsqrt_ge_qlo (105 # 1) Q105_nonneg 0%nat). }
    rewrite Hqlo0 in Hsq0. exact Hsq0.
  - apply (proj1 (CRle_morph R (CR_of_Q R ((10246 # 1000) * (10246 # 1000)))
                 (CR_of_Q R (10246 # 1000) * CR_of_Q R (10246 # 1000))
                 (CR_of_Q_mult R (10246 # 1000) (10246 # 1000))
                 (CR_of_Q R (105 # 1))
                 (CRsqrt (105 # 1) Q105_nonneg * CRsqrt (105 # 1) Q105_nonneg)
                 (CReq_sym (CRsqrt (105 # 1) Q105_nonneg * CRsqrt (105 # 1) Q105_nonneg)
                   (CR_of_Q R (105 # 1)) (CRsqrt_sq (105 # 1) Q105_nonneg)))).
    apply CR_of_Q_le'. exact q105_sq_bound.
Qed.

End M3.







(* ==================== 模块 54/67: probe_s7_s9_mono ==================== *)

Close Scope R_scope.
Close Scope Z_scope.
(* ============================================================
   G-5 P0 正式模块：S7 递增 [0,3/2] / S9 递减 [1.6,2] 多项式单调性（M4 数值界依赖）
   纯构造性：Stdlib ConstructiveReals，零经典、零 Admitted、零公理
   数学核心：9B = 5A² + (y-x)²(4y²+7yx+4x²) ⟹ B ≥ 5A²/9
   注意：B9/A2 不用 Definition（ring 不展开带参定义），全部完全展开
   ============================================================ *)
From Stdlib Require Import ConstructiveReals.
From Stdlib Require Import ConstructiveRealsMorphisms.
From Stdlib Require Import QArith.
From Stdlib Require Import Lia.
From Stdlib Require Import Ring.

Local Open Scope ConstructiveReals.

Section P0mono.

Context {R : ConstructiveReals}.
Add Ring CR_ring : (CRisRing R).

(* ============ 系数合并器（已验证） ============ *)

Lemma CRscale_sub (a b : Q) (z : CRcarrier R) :
  CReq R (CR_of_Q R a * z - CR_of_Q R b * z) (CR_of_Q R (a - b) * z).
Proof.
  assert (H : CReq R (CR_of_Q R a) (CR_of_Q R (a - b) + CR_of_Q R b)).
  { apply (CReq_trans _ (CR_of_Q R ((a - b) + b)) _).
    - apply (CR_of_Q_morph R a ((a - b) + b)). ring.
    - apply (CR_of_Q_plus R (a - b) b). }
  unfold CRminus.
  apply (CReq_trans _ ((CR_of_Q R (a - b) + CR_of_Q R b) * z + (- (CR_of_Q R b * z))) _).
  - apply (CRplus_morph_Proper
             (CR_of_Q R a * z) ((CR_of_Q R (a - b) + CR_of_Q R b) * z)
             ltac:(apply (CRmult_morph_Proper (CR_of_Q R a) (CR_of_Q R (a - b) + CR_of_Q R b) H z z (CReq_refl _)))
             (- (CR_of_Q R b * z)) (- (CR_of_Q R b * z)) (CReq_refl _)).
  - ring.
Qed.

Lemma CRscale_add (a b : Q) (z : CRcarrier R) :
  CReq R (CR_of_Q R (a + b) * z) (CR_of_Q R a * z + CR_of_Q R b * z).
Proof.
  apply (CReq_trans _ ((CR_of_Q R a + CR_of_Q R b) * z) _).
  - apply (CRmult_morph_Proper (CR_of_Q R (a + b)) (CR_of_Q R a + CR_of_Q R b)
           ltac:(apply (CR_of_Q_plus R a b)) z z (CReq_refl _)).
  - ring.
Qed.

Lemma five_opp (T : CRcarrier R) :
  CReq R (CR_of_Q R (5 # 1) * (- T)) (- (CR_of_Q R (5 # 1) * T)).
Proof. unfold CRminus. ring. Qed.

Lemma CRscale_4m5 (z : CRcarrier R) :
  CReq R (CR_of_Q R (4 # 1) * z - CR_of_Q R (5 # 1) * z) (- z).
Proof.
  apply (CReq_trans _ (CR_of_Q R ((4 # 1) - (5 # 1)) * z) _).
  - apply (CRscale_sub (4 # 1) (5 # 1) z).
  - apply (CReq_trans _ (CR_of_Q R (-1 # 1) * z) _).
    + apply (CRmult_morph_Proper (CR_of_Q R ((4 # 1) - (5 # 1))) (CR_of_Q R (-1 # 1))
             ltac:(apply (CR_of_Q_morph R ((4 # 1) - (5 # 1)) (-1 # 1)); vm_compute; reflexivity)
             z z (CReq_refl _)).
    + rewrite (CR_of_Q_opp (1 # 1)). ring.
Qed.

Lemma CRscale_4m5m5 (z : CRcarrier R) :
  CReq R (CR_of_Q R (4 # 1) * z - CR_of_Q R (5 # 1) * z - CR_of_Q R (5 # 1) * z)
         (- (CR_of_Q R (6 # 1) * z)).
Proof.
  unfold CRminus.
  setoid_rewrite (CRscale_sub (4 # 1) (5 # 1) z).
  setoid_rewrite (CRscale_sub ((4 # 1) - (5 # 1)) (5 # 1) z).
  apply (CReq_trans _ (CR_of_Q R (-6 # 1) * z) _).
  - apply (CRmult_morph_Proper (CR_of_Q R ((4 # 1) - (5 # 1) - (5 # 1))) (CR_of_Q R (-6 # 1))
           ltac:(apply (CR_of_Q_morph R ((4 # 1) - (5 # 1) - (5 # 1)) (-6 # 1)); vm_compute; reflexivity)
           z z (CReq_refl _)).
  - rewrite (CR_of_Q_opp (6 # 1)). ring.
Qed.

(* ============ 多项式记号（纯展开，ring 可处理） ============ *)

(* B9 := y⁴+y³x+y²x²+yx³+x⁴（完全展开） *)
(* A2 := (y²+yx+x²)²（完全展开） *)

(* 9B == 5B + 4B *)
Lemma nineB_split (x y : CRcarrier R) :
  CReq R (CR_of_Q R (9 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x))
    (CR_of_Q R (5 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
     + CR_of_Q R (4 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)).
Proof.
  apply (CReq_trans _ (CR_of_Q R ((5 # 1) + (4 # 1))%Q * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)) _).
  - apply (CRmult_morph_Proper (CR_of_Q R (9 # 1)) (CR_of_Q R ((5 # 1) + (4 # 1))%Q)
           ltac:(apply (CR_of_Q_morph R (9 # 1) ((5 # 1) + (4 # 1))%Q); vm_compute; reflexivity)
           (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
           (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x) (CReq_refl _)).
  - apply (CRscale_add (5 # 1) (4 # 1) (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)).
Qed.

(* B - A² == -(y³x + y²x² + y²x² + yx³) *)
Lemma B_minus_Asq (x y : CRcarrier R) :
  CReq R ((y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
          - (y*y + y*x + x*x) * (y*y + y*x + x*x))
    (- ((y*y*y*x + y*y*x*x + y*y*x*x + y*x*x*x))).
Proof. unfold CRminus. ring. Qed.

(* 5B - 5A² == -5(y³x + y²x² + y²x² + yx³) *)
Lemma fiveB_minus_fiveAsq (x y : CRcarrier R) :
  CReq R (CR_of_Q R (5 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
          - CR_of_Q R (5 # 1) * ((y*y + y*x + x*x) * (y*y + y*x + x*x)))
    (- (CR_of_Q R (5 # 1) * (y*y*y*x + y*y*x*x + y*y*x*x + y*x*x*x))).
Proof.
  apply (CReq_trans _ (CR_of_Q R (5 # 1) * ((y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
                                            - (y*y + y*x + x*x) * (y*y + y*x + x*x))) _).
  - unfold CRminus. ring.
  - apply (CReq_trans _ (CR_of_Q R (5 # 1) * (- (y*y*y*x + y*y*x*x + y*y*x*x + y*x*x*x))) _).
    + apply (CRmult_morph_Proper (CR_of_Q R (5 # 1)) (CR_of_Q R (5 # 1)) (CReq_refl _)
               ((y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x) - (y*y + y*x + x*x) * (y*y + y*x + x*x))
               (- (y*y*y*x + y*y*x*x + y*y*x*x + y*x*x*x))
               (B_minus_Asq x y)).
    + apply (five_opp (y*y*y*x + y*y*x*x + y*y*x*x + y*x*x*x)).
Qed.

(* 4B - 5(y³x+y²x²+y²x²+yx³) == 4y⁴ - y³x - 6y²x² - yx³ + 4x⁴ *)
Lemma fourB_minus_fiveT (x y : CRcarrier R) :
  CReq R
    (CR_of_Q R (4 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
     - CR_of_Q R (5 # 1) * (y*y*y*x + y*y*x*x + y*y*x*x + y*x*x*x))
    (CR_of_Q R (4 # 1) * (y*y*y*y) - (y*y*y*x) - CR_of_Q R (6 # 1) * (y*y*x*x) - (y*x*x*x) + CR_of_Q R (4 # 1) * (x*x*x*x)).
Proof.
  apply (CReq_trans _
           (CR_of_Q R (4 # 1) * (y*y*y*y)
            + (CR_of_Q R (4 # 1) * (y*y*y*x) - CR_of_Q R (5 # 1) * (y*y*y*x))
            + (CR_of_Q R (4 # 1) * (y*y*x*x) - CR_of_Q R (5 # 1) * (y*y*x*x) - CR_of_Q R (5 # 1) * (y*y*x*x))
            + (CR_of_Q R (4 # 1) * (y*x*x*x) - CR_of_Q R (5 # 1) * (y*x*x*x))
            + CR_of_Q R (4 # 1) * (x*x*x*x)) _).
  - unfold CRminus. ring.
  - setoid_rewrite (CRscale_4m5 (y*y*y*x)).
    setoid_rewrite (CRscale_4m5m5 (y*y*x*x)).
    setoid_rewrite (CRscale_4m5 (y*x*x*x)).
    unfold CRminus. ring.
Qed.

(* 9B - 5A² == 4y⁴ - y³x - 6y²x² - yx³ + 4x⁴ *)
Lemma nineB_minus_fiveAsq (x y : CRcarrier R) :
  CReq R (CR_of_Q R (9 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
          - CR_of_Q R (5 # 1) * ((y*y + y*x + x*x) * (y*y + y*x + x*x)))
    (CR_of_Q R (4 # 1) * (y*y*y*y) - (y*y*y*x) - CR_of_Q R (6 # 1) * (y*y*x*x) - (y*x*x*x) + CR_of_Q R (4 # 1) * (x*x*x*x)).
Proof.
  assert (H9 : CReq R (CR_of_Q R (9 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
                       - CR_of_Q R (5 # 1) * ((y*y + y*x + x*x) * (y*y + y*x + x*x)))
                    (CR_of_Q R (5 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
                     - CR_of_Q R (5 # 1) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))
                     + CR_of_Q R (4 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x))).
  { rewrite (nineB_split x y). unfold CRminus. ring. }
  apply (CReq_trans _ (CR_of_Q R (5 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
                        - CR_of_Q R (5 # 1) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))
                        + CR_of_Q R (4 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)) _ H9).
  apply (CReq_trans _ (- (CR_of_Q R (5 # 1) * (y*y*y*x + y*y*x*x + y*y*x*x + y*x*x*x))
                        + CR_of_Q R (4 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)) _).
  - apply (CRplus_morph_Proper
             (CR_of_Q R (5 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
              - CR_of_Q R (5 # 1) * ((y*y + y*x + x*x) * (y*y + y*x + x*x)))
             (- (CR_of_Q R (5 # 1) * (y*y*y*x + y*y*x*x + y*y*x*x + y*x*x*x)))
             (fiveB_minus_fiveAsq x y)
             (CR_of_Q R (4 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x))
             (CR_of_Q R (4 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x))
             (CReq_refl _)).
  - apply (CReq_trans _ (CR_of_Q R (4 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
                          - CR_of_Q R (5 # 1) * (y*y*y*x + y*y*x*x + y*y*x*x + y*x*x*x)) _).
    + unfold CRminus. ring.
    + exact (fourB_minus_fiveT x y).
Qed.

(* ============ Phase B：B ≥ 5A²/9（0 ≤ x, y） ============ *)

(* 0 < -a 从 a < 0（ca_rip_cr.v 模式） *)
Lemma s7_CR0_lt_opp (a : CRcarrier R) :
  CRlt R a 0 -> CRlt R 0 (- a).
Proof.
  intros Ha.
  apply (CRplus_lt_reg_r (R:=R) a).
  rewrite CRplus_0_l. rewrite CRplus_opp_l.
  exact Ha.
Qed.

(* 平方非负：0 ≤ v·v（反证 + 分离性，ca_rip_cr.v L104-129 模式） *)
Lemma s7_CRsqr_nonneg (v : CRcarrier R) : CRle R 0 (v * v).
Proof.
  unfold CRle. intro H.
  assert (Hpos : CRlt R 0 (v * (- v))).
  { rewrite <- (CRopp_mult_distr_r (R:=R) v v).
    apply (CRplus_lt_reg_r (R:=R) (v * v)).
    rewrite CRplus_0_l. rewrite CRplus_opp_l.
    exact H. }
  destruct (CRmult_pos_appart_zero (R:=R) v (- v) Hpos) as [Hvgt|Hvlt].
  - assert (Hsq : CRlt R 0 (v * v)).
    { apply (CRmult_lt_0_compat R v v Hvgt Hvgt). }
    exact (fst (fst (CRltLinear R)) 0 (v * v) Hsq H).
  - assert (Hnv : CRlt R 0 (- v)).
    { exact (s7_CR0_lt_opp v Hvlt). }
    assert (Hsq : CRlt R 0 ((- v) * (- v))).
    { apply (CRmult_lt_0_compat R (- v) (- v) Hnv Hnv). }
    assert (Hsq' : CRlt R 0 (v * v)).
    { rewrite <- (CRopp_mult_distr_r (R:=R) (- v) v) in Hsq.
      rewrite (CRopp_mult_distr_l (R:=R) (- v) v) in Hsq.
      rewrite (CRopp_involutive (R:=R) v) in Hsq.
      exact Hsq. }
    exact (fst (fst (CRltLinear R)) 0 (v * v) Hsq' H).
Qed.

(* 非负积：0 ≤ u·v（0 ≤ u ∧ 0 ≤ v） *)
Lemma q_nonprod (u v : CRcarrier R) (Hu : 0 <= u) (Hv : 0 <= v) :
  CRle R 0 (u * v).
Proof. apply (CRmult_le_0_compat u v); assumption. Qed.

(* 三项非负和 *)
Lemma sum3_nonneg (a b c : CRcarrier R) (Ha : 0 <= a) (Hb : 0 <= b) (Hc : 0 <= c) :
  CRle R 0 (a + b + c).
Proof.
  assert (Hab : CRle R 0 (a + b)).
  { apply (CRle_morph R 0 (0 + 0) ltac:(ring) (a + b) (a + b) (CReq_refl _)).
    apply (CRplus_le_compat 0 a 0 b Ha Hb). }
  apply (CRle_morph R 0 (0 + 0) ltac:(ring) (a + b + c) ((a + b) + c) ltac:(ring)).
  apply (CRplus_le_compat 0 (a + b) 0 c Hab Hc).
Qed.

(* 系数合并：7z - 4z - 4z == -z *)
Lemma CRscale_7m4m4 (z : CRcarrier R) :
  CReq R (CR_of_Q R (7 # 1) * z - CR_of_Q R (4 # 1) * z - CR_of_Q R (4 # 1) * z) (- z).
Proof.
  unfold CRminus.
  setoid_rewrite (CRscale_sub (7 # 1) (4 # 1) z).
  setoid_rewrite (CRscale_sub (3 # 1) (4 # 1) z).
  rewrite (CR_of_Q_opp (1 # 1)). ring.
Qed.

(* 系数合并：4z - 7z - 7z + 4z == -6z *)
Lemma CRscale_4m7m7p4 (z : CRcarrier R) :
  CReq R (CR_of_Q R (4 # 1) * z - CR_of_Q R (7 # 1) * z - CR_of_Q R (7 # 1) * z + CR_of_Q R (4 # 1) * z)
         (- (CR_of_Q R (6 # 1) * z)).
Proof.
  unfold CRminus.
  setoid_rewrite (CRscale_sub (4 # 1) (7 # 1) z).
  setoid_rewrite (CRscale_sub (-3 # 1) (7 # 1) z).
  setoid_rewrite <- (CRscale_add (-10 # 1) (4 # 1) z).
  rewrite (CR_of_Q_opp (6 # 1)). ring.
Qed.

(* (y-x)²(4y²+7yx+4x²) 展开为 9 项中间形 M9（纯 ring，系数不合并） *)
Lemma m9_expand (x y : CRcarrier R) :
  CReq R
    ((y - x) * (y - x) * (CR_of_Q R (4 # 1) * (y * y) + CR_of_Q R (7 # 1) * (y * x) + CR_of_Q R (4 # 1) * (x * x)))
    (CR_of_Q R (4 # 1) * (y*y*y*y)
     + (CR_of_Q R (7 # 1) * (y*y*y*x) - CR_of_Q R (4 # 1) * (y*y*y*x) - CR_of_Q R (4 # 1) * (y*y*y*x))
     + (CR_of_Q R (4 # 1) * (y*y*x*x) - CR_of_Q R (7 # 1) * (y*y*x*x) - CR_of_Q R (7 # 1) * (y*y*x*x) + CR_of_Q R (4 # 1) * (y*y*x*x))
     + (CR_of_Q R (7 # 1) * (y*x*x*x) - CR_of_Q R (4 # 1) * (y*x*x*x) - CR_of_Q R (4 # 1) * (y*x*x*x))
     + CR_of_Q R (4 # 1) * (x*x*x*x)).
Proof. unfold CRminus. ring. Qed.

(* 9B - 5A² == (y-x)²(4y²+7yx+4x²) *)
Lemma nineB_eq_sqdiff (x y : CRcarrier R) :
  CReq R (CR_of_Q R (9 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
          - CR_of_Q R (5 # 1) * ((y*y + y*x + x*x) * (y*y + y*x + x*x)))
         ((y - x) * (y - x) * (CR_of_Q R (4 # 1) * (y * y) + CR_of_Q R (7 # 1) * (y * x) + CR_of_Q R (4 # 1) * (x * x))).
Proof.
  apply (CReq_trans _ (CR_of_Q R (4 # 1) * (y*y*y*y) - (y*y*y*x) - CR_of_Q R (6 # 1) * (y*y*x*x) - (y*x*x*x) + CR_of_Q R (4 # 1) * (x*x*x*x)) _).
  - apply nineB_minus_fiveAsq.
  - apply (CReq_trans _ (CR_of_Q R (4 # 1) * (y*y*y*y)
                         + (CR_of_Q R (7 # 1) * (y*y*y*x) - CR_of_Q R (4 # 1) * (y*y*y*x) - CR_of_Q R (4 # 1) * (y*y*y*x))
                         + (CR_of_Q R (4 # 1) * (y*y*x*x) - CR_of_Q R (7 # 1) * (y*y*x*x) - CR_of_Q R (7 # 1) * (y*y*x*x) + CR_of_Q R (4 # 1) * (y*y*x*x))
                         + (CR_of_Q R (7 # 1) * (y*x*x*x) - CR_of_Q R (4 # 1) * (y*x*x*x) - CR_of_Q R (4 # 1) * (y*x*x*x))
                         + CR_of_Q R (4 # 1) * (x*x*x*x)) _).
    + unfold CRminus.
      setoid_rewrite (CRscale_7m4m4 (y*y*y*x)).
      setoid_rewrite (CRscale_4m7m7p4 (y*y*x*x)).
      setoid_rewrite (CRscale_7m4m4 (y*x*x*x)).
      ring.
    + apply (CReq_sym _ _ (m9_expand x y)).
Qed.

(* (y-x)² ≥ 0 *)
Lemma sqdiff_nonneg (x y : CRcarrier R) : CRle R 0 ((y - x) * (y - x)).
Proof. apply s7_CRsqr_nonneg. Qed.

(* 4·(v·v) ≥ 0 *)
Lemma four_sq_nonneg (v : CRcarrier R) : CRle R 0 (CR_of_Q R (4 # 1) * (v * v)).
Proof.
  apply (CRle_morph R 0 (0 * (v * v)) ltac:(ring)
                     (CR_of_Q R (4 # 1) * (v * v)) (CR_of_Q R (4 # 1) * (v * v)) (CReq_refl _)).
  apply (CRmult_le_compat_r (v * v) 0 (CR_of_Q R (4 # 1))).
  - apply s7_CRsqr_nonneg.
  - apply (CR_of_Q_le 0 (4 # 1)). unfold Qle. simpl. lia.
Qed.

(* 7·(y·x) ≥ 0（0 ≤ y ∧ 0 ≤ x） *)
Lemma seven_yx_nonneg (y x : CRcarrier R) (Hy : 0 <= y) (Hx : 0 <= x) :
  CRle R 0 (CR_of_Q R (7 # 1) * (y * x)).
Proof.
  apply (CRle_morph R 0 (0 * (y * x)) ltac:(ring)
                     (CR_of_Q R (7 # 1) * (y * x)) (CR_of_Q R (7 # 1) * (y * x)) (CReq_refl _)).
  apply (CRmult_le_compat_r (y * x) 0 (CR_of_Q R (7 # 1))).
  - apply q_nonprod; assumption.
  - apply (CR_of_Q_le 0 (7 # 1)). unfold Qle. simpl. lia.
Qed.

(* 4y² + 7yx + 4x² ≥ 0 *)
Lemma q4_nonneg (x y : CRcarrier R) (Hx : 0 <= x) (Hy : 0 <= y) :
  CRle R 0 (CR_of_Q R (4 # 1) * (y * y) + CR_of_Q R (7 # 1) * (y * x) + CR_of_Q R (4 # 1) * (x * x)).
Proof.
  apply sum3_nonneg.
  - apply four_sq_nonneg.
  - apply seven_yx_nonneg; assumption.
  - apply four_sq_nonneg.
Qed.

(* 0 ≤ T ⟹ a ≤ a + T（Stdlib 无 CRle_plus_r，自建） *)
Lemma le_plus_l (a T : CRcarrier R) (HT : 0 <= T) : a <= a + T.
Proof.
  apply (proj1 (CRle_morph R (a + 0) a ltac:(ring) (a + T) (a + T) (CReq_refl _))).
  apply (CRplus_le_compat_l a 0 T). exact HT.
Qed.

(* B ≥ 5A²/9：9B - 5A² = (y-x)²(4y²+7yx+4x²) ≥ 0 *)
Lemma nineB_ge_fiveAsq (x y : CRcarrier R) (Hx : 0 <= x) (Hy : 0 <= y) :
  CRle R (CR_of_Q R (5 # 1) * ((y*y + y*x + x*x) * (y*y + y*x + x*x)))
         (CR_of_Q R (9 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)).
Proof.
  apply (CRle_morph R (CR_of_Q R (5 # 1) * ((y*y + y*x + x*x) * (y*y + y*x + x*x)))
                     (CR_of_Q R (5 # 1) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))) (CReq_refl _)
                     (CR_of_Q R (9 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x))
                     (CR_of_Q R (5 # 1) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))
                      + (CR_of_Q R (9 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
                         - CR_of_Q R (5 # 1) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))))
                     ltac:(unfold CRminus; ring)).
  apply (le_plus_l (CR_of_Q R (5 # 1) * ((y*y + y*x + x*x) * (y*y + y*x + x*x)))
                   (CR_of_Q R (9 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
                    - CR_of_Q R (5 # 1) * ((y*y + y*x + x*x) * (y*y + y*x + x*x)))).
  apply (CRle_morph R 0 0 (CReq_refl _)
                     (CR_of_Q R (9 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
                      - CR_of_Q R (5 # 1) * ((y*y + y*x + x*x) * (y*y + y*x + x*x)))
                     ((y - x) * (y - x) * (CR_of_Q R (4 # 1) * (y * y) + CR_of_Q R (7 # 1) * (y * x) + CR_of_Q R (4 # 1) * (x * x)))
                     (nineB_eq_sqdiff x y)).
  apply (q_nonprod ((y - x) * (y - x))
                   (CR_of_Q R (4 # 1) * (y * y) + CR_of_Q R (7 # 1) * (y * x) + CR_of_Q R (4 # 1) * (x * x))).
  - apply sqdiff_nonneg.
  - apply q4_nonneg; assumption.
Qed.

(* ============ Phase C：幂单调与 A/C 界 ============ *)

(* Q 层 nat 幂（避免 Z 幂） *)
Fixpoint qn (q : Q) (n : nat) : Q :=
  match n with 0%nat => 1%Q | S m => qn q m * q end.

(* x_pow (CR_of_Q q) n == CR_of_Q (qn q n) *)
Lemma x_pow_Q (q : Q) (n : nat) :
  CReq R (x_pow (CR_of_Q R q) n) (CR_of_Q R (qn q n)).
Proof.
  induction n.
  - cbn [x_pow qn]. apply CReq_refl.
  - cbn [x_pow qn].
    apply (CReq_trans _ (CR_of_Q R (qn q n) * CR_of_Q R q) _).
    + apply (CRmult_morph_Proper (x_pow (CR_of_Q R q) n) (CR_of_Q R (qn q n)) IHn
                                 (CR_of_Q R q) (CR_of_Q R q) (CReq_refl _)).
    + apply CReq_sym. apply CR_of_Q_mult.
Qed.

(* (3/2)^6 == 729/64 *)
Lemma qpow6 : CReq R (x_pow (CR_of_Q R (3 # 2)) 6) (CR_of_Q R (729 # 64)).
Proof.
  transitivity (CR_of_Q R (qn (3 # 2) 6)).
  - apply (x_pow_Q (3 # 2) 6).
  - apply (CR_of_Q_morph R (qn (3 # 2) 6) (729 # 64)). vm_compute. reflexivity.
Qed.

(* 幂单调：0 ≤ a ≤ b ⟹ x_pow a n ≤ x_pow b n *)
Lemma pow_le (a b : CRcarrier R) (Hab : a <= b) (Ha : 0 <= a) (n : nat) :
  x_pow a n <= x_pow b n.
Proof.
  induction n.
  - cbn [x_pow]. apply CRle_refl.
  - cbn [x_pow].
    apply (CRle_trans _ (x_pow b n * a) _).
    + apply (CRmult_le_compat_r a (x_pow a n) (x_pow b n)).
      * exact Ha.
      * exact IHn.
    + apply (CRmult_le_compat_l (x_pow b n) a b).
      * apply x_pow_nonneg. apply (CRle_trans _ a _). exact Ha. exact Hab.
      * exact Hab.
Qed.

(* 单项界：0 ≤ u,v ≤ c ⟹ x_pow u k · x_pow v (n-k) ≤ c^n（k ≤ n） *)
Lemma mon_le_const (c : Q) (u v : CRcarrier R) (k n : nat) (Hk : (k <= n)%nat)
    (Hu0 : 0 <= u) (Hv0 : 0 <= v)
    (Hcu : u <= CR_of_Q R c) (Hcv : v <= CR_of_Q R c)
    (Hc0 : 0 <= CR_of_Q R c) :
  x_pow u k * x_pow v (n - k) <= CR_of_Q R (qn c n).
Proof.
  apply (CRle_trans _ (x_pow (CR_of_Q R c) k * x_pow v (n - k)) _).
  - apply (CRmult_le_compat_r (x_pow v (n - k)) (x_pow u k) (x_pow (CR_of_Q R c) k)).
    + apply x_pow_nonneg. exact Hv0.
    + apply pow_le. exact Hcu. exact Hu0.
  - apply (CRle_trans _ (x_pow (CR_of_Q R c) k * x_pow (CR_of_Q R c) (n - k)) _).
    + apply (CRmult_le_compat_l (x_pow (CR_of_Q R c) k) (x_pow v (n - k)) (x_pow (CR_of_Q R c) (n - k))).
      * apply x_pow_nonneg. exact Hc0.
      * apply pow_le. exact Hcv. exact Hv0.
    + apply (CRle_morph R (x_pow (CR_of_Q R c) k * x_pow (CR_of_Q R c) (n - k))
                         (x_pow (CR_of_Q R c) (k + (n - k)))
                         ltac:(apply CReq_sym; apply (x_pow_add (CR_of_Q R c) k (n - k)))
                         (CR_of_Q R (qn c n)) (CR_of_Q R (qn c n)) (CReq_refl _)).
      replace (k + (n - k))%nat with n%nat by lia.
      apply (CRle_morph R (x_pow (CR_of_Q R c) n) (CR_of_Q R (qn c n)) (x_pow_Q c n)
                         (CR_of_Q R (qn c n)) (CR_of_Q R (qn c n)) (CReq_refl _)).
      apply CRle_refl.
Qed.

(* v² ≤ 9/4（0 ≤ v ≤ 3/2） *)
Lemma sq_le_94 (v : CRcarrier R) (Hv0 : 0 <= v) (Hv32 : v <= CR_of_Q R (3 # 2)) :
  v * v <= CR_of_Q R (9 # 4).
Proof.
  apply (CRle_trans _ (CR_of_Q R (3 # 2) * v) _).
  - apply (CRmult_le_compat_r v v (CR_of_Q R (3 # 2))).
    + exact Hv0.
    + exact Hv32.
  - apply (CRle_trans _ (CR_of_Q R (3 # 2) * CR_of_Q R (3 # 2)) _).
    + apply (CRmult_le_compat_l (CR_of_Q R (3 # 2)) v (CR_of_Q R (3 # 2))).
      * apply (CR_of_Q_le 0 (3 # 2)). unfold Qle. simpl. lia.
      * exact Hv32.
    + apply (CRle_morph R (CR_of_Q R (3 # 2) * CR_of_Q R (3 # 2)) (CR_of_Q R (9 # 4))
                         ltac:(apply CReq_sym; apply (CR_of_Q_mult R (3 # 2) (3 # 2)))
                         (CR_of_Q R (9 # 4)) (CR_of_Q R (9 # 4)) (CReq_refl _)).
      apply CRle_refl.
Qed.

(* y·x ≤ 9/4（0 ≤ x, y ≤ 3/2） *)
Lemma yx_le_94 (y x : CRcarrier R) (Hx0 : 0 <= x) (Hy32 : y <= CR_of_Q R (3 # 2))
    (Hx32 : x <= CR_of_Q R (3 # 2)) :
  y * x <= CR_of_Q R (9 # 4).
Proof.
  apply (CRle_trans _ (CR_of_Q R (3 # 2) * x) _).
  - apply (CRmult_le_compat_r x y (CR_of_Q R (3 # 2))).
    + exact Hx0.
    + exact Hy32.
  - apply (CRle_trans _ (CR_of_Q R (3 # 2) * CR_of_Q R (3 # 2)) _).
    + apply (CRmult_le_compat_l (CR_of_Q R (3 # 2)) x (CR_of_Q R (3 # 2))).
      * apply (CR_of_Q_le 0 (3 # 2)). unfold Qle. simpl. lia.
      * exact Hx32.
    + apply (CRle_morph R (CR_of_Q R (3 # 2) * CR_of_Q R (3 # 2)) (CR_of_Q R (9 # 4))
                         ltac:(apply CReq_sym; apply (CR_of_Q_mult R (3 # 2) (3 # 2)))
                         (CR_of_Q R (9 # 4)) (CR_of_Q R (9 # 4)) (CReq_refl _)).
      apply CRle_refl.
Qed.

(* CR_of_Q q1 + CR_of_Q q2 + CR_of_Q q3 == CR_of_Q (q1+q2+q3) *)
Lemma sum3_of_Q (q1 q2 q3 : Q) :
  CReq R (CR_of_Q R q1 + CR_of_Q R q2 + CR_of_Q R q3)
         (CR_of_Q R (q1 + q2 + q3)).
Proof.
  apply (CReq_trans _ (CR_of_Q R (q1 + q2) + CR_of_Q R q3) _).
  - apply (CRplus_morph_Proper (CR_of_Q R q1 + CR_of_Q R q2) (CR_of_Q R (q1 + q2))
           ltac:(apply CReq_sym; apply (CR_of_Q_plus R q1 q2))
           (CR_of_Q R q3) (CR_of_Q R q3) (CReq_refl _)).
  - apply CReq_sym. apply (CR_of_Q_plus R (q1 + q2) q3).
Qed.

(* A = y²+yx+x² ≤ 27/4（0 ≤ x,y ≤ 3/2） *)
Lemma A_le (x y : CRcarrier R) (Hx0 : 0 <= x) (Hy0 : 0 <= y)
    (Hx32 : x <= CR_of_Q R (3 # 2)) (Hy32 : y <= CR_of_Q R (3 # 2)) :
  y*y + y*x + x*x <= CR_of_Q R (27 # 4).
Proof.
  apply (CRle_trans _ (CR_of_Q R (9 # 4) + CR_of_Q R (9 # 4) + CR_of_Q R (9 # 4)) _).
  - apply (CRplus_le_compat (y*y + y*x) (CR_of_Q R (9 # 4) + CR_of_Q R (9 # 4))
                            (x*x) (CR_of_Q R (9 # 4))).
    + apply (CRplus_le_compat (y*y) (CR_of_Q R (9 # 4)) (y*x) (CR_of_Q R (9 # 4))).
      * apply sq_le_94; assumption.
      * apply yx_le_94; assumption.
    + apply sq_le_94; assumption.
  - apply (CRle_morph R (CR_of_Q R (9 # 4) + CR_of_Q R (9 # 4) + CR_of_Q R (9 # 4))
                       (CR_of_Q R (27 # 4))
                       ltac:(apply (CReq_trans _ (CR_of_Q R ((9 # 4) + (9 # 4) + (9 # 4))%Q) _);
                             [ apply (sum3_of_Q (9 # 4) (9 # 4) (9 # 4))
                             | apply (CR_of_Q_morph R ((9 # 4) + (9 # 4) + (9 # 4))%Q (27 # 4)); vm_compute; reflexivity ])
                       (CR_of_Q R (27 # 4)) (CR_of_Q R (27 # 4)) (CReq_refl _)).
    apply CRle_refl.
Qed.

(* C = y⁶+y⁵x+y⁴x²+y³x³+y²x⁴+yx⁵+x⁶ ≤ 5103/64（0 ≤ x,y ≤ 3/2） *)
Lemma C_le (x y : CRcarrier R) (Hx0 : 0 <= x) (Hy0 : 0 <= y)
    (Hx32 : x <= CR_of_Q R (3 # 2)) (Hy32 : y <= CR_of_Q R (3 # 2)) :
  y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x
  <= CR_of_Q R (5103 # 64).
Proof.
  assert (H0 : y*y*y*y*y*y <= CR_of_Q R (729 # 64)).
  { apply (CRle_morph R (y*y*y*y*y*y) (x_pow y 6 * x_pow x 0) ltac:(cbn [x_pow]; ring)
                       (CR_of_Q R (729 # 64)) (CR_of_Q R (729 # 64)) (CReq_refl _)).
    apply (mon_le_const (3 # 2) y x 6 6 ltac:(lia) Hy0 Hx0 Hy32 Hx32
                         ltac:(apply (CR_of_Q_le 0 (3 # 2)); unfold Qle; simpl; lia)). }
  assert (H1 : y*y*y*y*y*x <= CR_of_Q R (729 # 64)).
  { apply (CRle_morph R (y*y*y*y*y*x) (x_pow y 5 * x_pow x 1) ltac:(cbn [x_pow]; ring)
                       (CR_of_Q R (729 # 64)) (CR_of_Q R (729 # 64)) (CReq_refl _)).
    apply (mon_le_const (3 # 2) y x 5 6 ltac:(lia) Hy0 Hx0 Hy32 Hx32
                         ltac:(apply (CR_of_Q_le 0 (3 # 2)); unfold Qle; simpl; lia)). }
  assert (H2 : y*y*y*y*x*x <= CR_of_Q R (729 # 64)).
  { apply (CRle_morph R (y*y*y*y*x*x) (x_pow y 4 * x_pow x 2) ltac:(cbn [x_pow]; ring)
                       (CR_of_Q R (729 # 64)) (CR_of_Q R (729 # 64)) (CReq_refl _)).
    apply (mon_le_const (3 # 2) y x 4 6 ltac:(lia) Hy0 Hx0 Hy32 Hx32
                         ltac:(apply (CR_of_Q_le 0 (3 # 2)); unfold Qle; simpl; lia)). }
  assert (H3 : y*y*y*x*x*x <= CR_of_Q R (729 # 64)).
  { apply (CRle_morph R (y*y*y*x*x*x) (x_pow y 3 * x_pow x 3) ltac:(cbn [x_pow]; ring)
                       (CR_of_Q R (729 # 64)) (CR_of_Q R (729 # 64)) (CReq_refl _)).
    apply (mon_le_const (3 # 2) y x 3 6 ltac:(lia) Hy0 Hx0 Hy32 Hx32
                         ltac:(apply (CR_of_Q_le 0 (3 # 2)); unfold Qle; simpl; lia)). }
  assert (H4 : y*y*x*x*x*x <= CR_of_Q R (729 # 64)).
  { apply (CRle_morph R (y*y*x*x*x*x) (x_pow y 2 * x_pow x 4) ltac:(cbn [x_pow]; ring)
                       (CR_of_Q R (729 # 64)) (CR_of_Q R (729 # 64)) (CReq_refl _)).
    apply (mon_le_const (3 # 2) y x 2 6 ltac:(lia) Hy0 Hx0 Hy32 Hx32
                         ltac:(apply (CR_of_Q_le 0 (3 # 2)); unfold Qle; simpl; lia)). }
  assert (H5 : y*x*x*x*x*x <= CR_of_Q R (729 # 64)).
  { apply (CRle_morph R (y*x*x*x*x*x) (x_pow y 1 * x_pow x 5) ltac:(cbn [x_pow]; ring)
                       (CR_of_Q R (729 # 64)) (CR_of_Q R (729 # 64)) (CReq_refl _)).
    apply (mon_le_const (3 # 2) y x 1 6 ltac:(lia) Hy0 Hx0 Hy32 Hx32
                         ltac:(apply (CR_of_Q_le 0 (3 # 2)); unfold Qle; simpl; lia)). }
  assert (H6 : x*x*x*x*x*x <= CR_of_Q R (729 # 64)).
  { apply (CRle_morph R (x*x*x*x*x*x) (x_pow y 0 * x_pow x 6) ltac:(cbn [x_pow]; ring)
                       (CR_of_Q R (729 # 64)) (CR_of_Q R (729 # 64)) (CReq_refl _)).
    apply (mon_le_const (3 # 2) y x 0 6 ltac:(lia) Hy0 Hx0 Hy32 Hx32
                         ltac:(apply (CR_of_Q_le 0 (3 # 2)); unfold Qle; simpl; lia)). }
  apply (CRle_trans _ (CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64)
                     + CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64)) _).
  - apply (CRplus_le_compat (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x)
                            (CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64)
                             + CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64))
                            (x*x*x*x*x*x) (CR_of_Q R (729 # 64))).
    + apply (CRplus_le_compat (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x)
                              (CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64)
                               + CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64))
                              (y*x*x*x*x*x) (CR_of_Q R (729 # 64))).
      * apply (CRplus_le_compat (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x)
                                (CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64)
                                 + CR_of_Q R (729 # 64))
                                (y*y*x*x*x*x) (CR_of_Q R (729 # 64))).
        + apply (CRplus_le_compat (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x)
                                  (CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64))
                                  (y*y*y*x*x*x) (CR_of_Q R (729 # 64))).
          * apply (CRplus_le_compat (y*y*y*y*y*y + y*y*y*y*y*x)
                                    (CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64))
                                    (y*y*y*y*x*x) (CR_of_Q R (729 # 64))).
            + apply (CRplus_le_compat (y*y*y*y*y*y) (CR_of_Q R (729 # 64))
                                      (y*y*y*y*y*x) (CR_of_Q R (729 # 64))).
              * exact H0.
              * exact H1.
            + exact H2.
          * exact H3.
        + exact H4.
      * exact H5.
    + exact H6.
  - apply (CRle_morph R (CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64)
                       + CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64) + CR_of_Q R (729 # 64))
                       (CR_of_Q R (5103 # 64))
                       ltac:(unfold CRminus;
                             setoid_rewrite <- (CRmult_1_l (CR_of_Q R (729 # 64)));
                             setoid_rewrite <- (CRscale_add (1 # 1) (1 # 1) (CR_of_Q R (729 # 64)));
                             setoid_rewrite <- (CRscale_add (2 # 1) (1 # 1) (CR_of_Q R (729 # 64)));
                             setoid_rewrite <- (CRscale_add (3 # 1) (1 # 1) (CR_of_Q R (729 # 64)));
                             setoid_rewrite <- (CRscale_add (4 # 1) (1 # 1) (CR_of_Q R (729 # 64)));
                             setoid_rewrite <- (CRscale_add (5 # 1) (1 # 1) (CR_of_Q R (729 # 64)));
                             setoid_rewrite <- (CRscale_add (6 # 1) (1 # 1) (CR_of_Q R (729 # 64)));
                             apply (CReq_trans _ (CR_of_Q R ((7 # 1) * (729 # 64))%Q) _);
                             [ apply CReq_sym; apply (CR_of_Q_mult R (7 # 1) (729 # 64))
                             | apply (CR_of_Q_morph R ((7 # 1) * (729 # 64))%Q (5103 # 64)); vm_compute; reflexivity ])
                       (CR_of_Q R (5103 # 64)) (CR_of_Q R (5103 # 64)) (CReq_refl _)).
    apply CRle_refl.
Qed.

(* ============ Phase D：S7 递增 [0,3/2] ============ *)

(* 负号单调：S ≤ T ⟹ -T ≤ -S *)
Lemma opp_le_compat (S T : CRcarrier R) (HST : S <= T) : - T <= - S.
Proof.
  apply (CRplus_le_reg_r (R:=R) T).
  apply (proj2 (CRle_morph R (- T + T) 0 ltac:(ring) (- S + T) (T - S) ltac:(unfold CRminus; ring))).
  apply (proj2 (CRle_morph R 0 (S + (- S)) ltac:(ring) (T - S) (T - S) (CReq_refl _))).
  apply (CRplus_le_compat_r (- S) S T). exact HST.
Qed.

(* A+B ≤ 27/2（0 ≤ A ≤ B ≤ 27/4） *)
Lemma AB_le_272 (A B : CRcarrier R) (HA0 : 0 <= A) (HAB : A <= B) (HB274 : B <= CR_of_Q R (27 # 4)) :
  A + B <= CR_of_Q R (27 # 2).
Proof.
  apply (CRle_trans _ (B + B) _).
  - apply (CRplus_le_compat A B B B). exact HAB. apply CRle_refl.
  - apply (CRle_trans _ (CR_of_Q R (27 # 4) + CR_of_Q R (27 # 4)) _).
    + apply (CRplus_le_compat B (CR_of_Q R (27 # 4)) B (CR_of_Q R (27 # 4))). exact HB274. exact HB274.
    + apply (CRle_morph R (CR_of_Q R (27 # 4) + CR_of_Q R (27 # 4)) (CR_of_Q R (27 # 2))
                         ltac:(apply (CReq_trans _ (CR_of_Q R ((27 # 4) + (27 # 4))%Q) _);
                               [ apply CReq_sym; apply (CR_of_Q_plus R (27 # 4) (27 # 4))
                               | apply (CR_of_Q_morph R ((27 # 4) + (27 # 4))%Q (27 # 2)); vm_compute; reflexivity ])
                         (CR_of_Q R (27 # 2)) (CR_of_Q R (27 # 2)) (CReq_refl _)).
      apply CRle_refl.
Qed.

(* 1/6 - (5/1080)(A+B) ≥ 0（0 ≤ A ≤ B ≤ 27/4） *)
Lemma q6_factor_nonneg (A B : CRcarrier R) (HA0 : 0 <= A) (HAB : A <= B) (HB274 : B <= CR_of_Q R (27 # 4)) :
  0 <= CR_of_Q R (1 # 6) - CR_of_Q R (5 # 1080) * (A + B).
Proof.
  (* S = (5/1080)(A+B) ≤ 1/6 *)
  assert (HS16 : CR_of_Q R (5 # 1080) * (A + B) <= CR_of_Q R (1 # 6)).
  { apply (CRle_trans _ (CR_of_Q R (5 # 1080) * CR_of_Q R (27 # 2)) _).
    - apply (CRmult_le_compat_l (CR_of_Q R (5 # 1080)) (A + B) (CR_of_Q R (27 # 2))).
      + apply (CR_of_Q_le 0 (5 # 1080)). unfold Qle. simpl. lia.
      + apply AB_le_272; assumption.
    - apply (CRle_trans _ (CR_of_Q R (1 # 16)) _).
      + apply (CRle_morph R (CR_of_Q R (5 # 1080) * CR_of_Q R (27 # 2)) (CR_of_Q R (1 # 16))
                           ltac:(apply (CReq_trans _ (CR_of_Q R ((5 # 1080) * (27 # 2))%Q) _);
                                 [ apply CReq_sym; apply (CR_of_Q_mult R (5 # 1080) (27 # 2))
                                 | apply (CR_of_Q_morph R ((5 # 1080) * (27 # 2))%Q (1 # 16)); vm_compute; reflexivity ])
                           (CR_of_Q R (1 # 16)) (CR_of_Q R (1 # 16)) (CReq_refl _)).
        apply CRle_refl.
      + apply (CR_of_Q_le (1 # 16) (1 # 6)). unfold Qle. simpl. lia.
  }
  apply (CRle_morph R 0 ((CR_of_Q R (5 # 1080) * (A + B)) + (- (CR_of_Q R (5 # 1080) * (A + B)))) ltac:(ring)
                           (CR_of_Q R (1 # 6) - (CR_of_Q R (5 # 1080) * (A + B)))
                           (CR_of_Q R (1 # 6) - (CR_of_Q R (5 # 1080) * (A + B))) (CReq_refl _)).
  apply (CRplus_le_compat_r (- (CR_of_Q R (5 # 1080) * (A + B))) (CR_of_Q R (5 # 1080) * (A + B)) (CR_of_Q R (1 # 6))). exact HS16.
Qed.

(* h 递减：0 ≤ A ≤ B ≤ 27/4 ⟹ h(B) ≤ h(A)，h(t) = 1 - t/6 + 5t²/1080 *)
Lemma h_decr (A B : CRcarrier R) (HA0 : 0 <= A) (HAB : A <= B) (HB274 : B <= CR_of_Q R (27 # 4)) :
  (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * B + CR_of_Q R (5 # 1080) * (B * B))
  <=
  (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * A + CR_of_Q R (5 # 1080) * (A * A)).
Proof.
  (* 0 ≤ hA - hB == (B-A)·(1/6 - 5(A+B)/1080) *)
  apply (CRle_morph R (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * B + CR_of_Q R (5 # 1080) * (B * B))
                     (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * B + CR_of_Q R (5 # 1080) * (B * B)) (CReq_refl _)
                     (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * A + CR_of_Q R (5 # 1080) * (A * A))
                     (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * B + CR_of_Q R (5 # 1080) * (B * B)
                      + ((CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * A + CR_of_Q R (5 # 1080) * (A * A))
                         - (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * B + CR_of_Q R (5 # 1080) * (B * B))))
                     ltac:(unfold CRminus; ring)).
  apply (le_plus_l (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * B + CR_of_Q R (5 # 1080) * (B * B))
                   ((CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * A + CR_of_Q R (5 # 1080) * (A * A))
                    - (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * B + CR_of_Q R (5 # 1080) * (B * B)))).
  apply (CRle_morph R 0 0 (CReq_refl _)
                     ((CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * A + CR_of_Q R (5 # 1080) * (A * A))
                      - (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * B + CR_of_Q R (5 # 1080) * (B * B)))
                     ((B - A) * (CR_of_Q R (1 # 6) - CR_of_Q R (5 # 1080) * (A + B)))
                     ltac:(unfold CRminus; ring)).
  apply q_nonprod.
  - apply (CRle_morph R 0 (A + (- A)) ltac:(ring) (B - A) (B - A) (CReq_refl _)).
    apply (CRplus_le_compat_r (- A) A B). exact HAB.
  - apply q6_factor_nonneg; assumption.
Qed.

(* h(27/4) == 11/128 *)
Lemma h274_val :
  CReq R (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (CR_of_Q R (27 # 4))
          + CR_of_Q R (5 # 1080) * (CR_of_Q R (27 # 4) * CR_of_Q R (27 # 4)))
         (CR_of_Q R (11 # 128)).
Proof.
  apply (CReq_trans _ (CR_of_Q R (1 # 1) - CR_of_Q R (27 # 24) + CR_of_Q R (3645 # 17280)) _).
  - assert (H1 : CReq R (CR_of_Q R (1 # 6) * (CR_of_Q R (27 # 4))) (CR_of_Q R (27 # 24))).
    { apply CReq_sym. apply (CR_of_Q_mult R (1 # 6) (27 # 4)). }
    assert (H2 : CReq R (CR_of_Q R (5 # 1080) * (CR_of_Q R (27 # 4) * CR_of_Q R (27 # 4)))
                 (CR_of_Q R (3645 # 17280))).
    { apply (CReq_trans _ (CR_of_Q R (5 # 1080) * CR_of_Q R (729 # 16)) _).
      - apply (CRmult_morph_Proper (CR_of_Q R (5 # 1080)) (CR_of_Q R (5 # 1080)) (CReq_refl _)
                                   (CR_of_Q R (27 # 4) * CR_of_Q R (27 # 4)) (CR_of_Q R (729 # 16))
                                   ltac:(apply CReq_sym; apply (CR_of_Q_mult R (27 # 4) (27 # 4)))).
      - apply CReq_sym. apply (CR_of_Q_mult R (5 # 1080) (729 # 16)). }
    unfold CRminus.
    apply (CReq_trans _ (CR_of_Q R (1 # 1) + (- (CR_of_Q R (27 # 24))) + CR_of_Q R (3645 # 17280)) _).
    + apply (CRplus_morph_Proper (CR_of_Q R (1 # 1) + (- (CR_of_Q R (1 # 6) * (CR_of_Q R (27 # 4)))))
                                 (CR_of_Q R (1 # 1) + (- (CR_of_Q R (27 # 24))))
                                 ltac:(apply (CRplus_morph_Proper (CR_of_Q R (1 # 1)) (CR_of_Q R (1 # 1)) (CReq_refl _)
                                                               (- (CR_of_Q R (1 # 6) * (CR_of_Q R (27 # 4)))) (- (CR_of_Q R (27 # 24)))
                                                               ltac:(apply (CRopp_morph_Proper (CR_of_Q R (1 # 6) * (CR_of_Q R (27 # 4))) (CR_of_Q R (27 # 24)) H1))))
                                 (CR_of_Q R (5 # 1080) * (CR_of_Q R (27 # 4) * CR_of_Q R (27 # 4)))
                                 (CR_of_Q R (3645 # 17280)) H2).
    + apply CReq_refl.
  - unfold CRminus.
    apply (CReq_trans _ (CR_of_Q R (1 # 1) + CR_of_Q R (-(27 # 24)) + CR_of_Q R (3645 # 17280)) _).
    + apply (CRplus_morph_Proper (CR_of_Q R (1 # 1) + (- (CR_of_Q R (27 # 24))))
                                 (CR_of_Q R (1 # 1) + CR_of_Q R (-(27 # 24)))
                                 ltac:(apply (CRplus_morph_Proper (CR_of_Q R (1 # 1)) (CR_of_Q R (1 # 1)) (CReq_refl _)
                                                       (- (CR_of_Q R (27 # 24))) (CR_of_Q R (-(27 # 24)))
                                                       ltac:(apply CReq_sym; apply (CR_of_Q_opp (27 # 24)))))
                                 (CR_of_Q R (3645 # 17280)) (CR_of_Q R (3645 # 17280)) (CReq_refl _)).
    + apply (CReq_trans _ (CR_of_Q R ((1 # 1) + (-(27 # 24)) + (3645 # 17280))%Q) _).
      * apply (sum3_of_Q (1 # 1) (-(27 # 24)) (3645 # 17280)).
      * apply (CR_of_Q_morph R ((1 # 1) + (-(27 # 24)) + (3645 # 17280))%Q (11 # 128)). vm_compute. reflexivity.
Qed.

(* 11/128 - 5103/322560 == 22617/322560 *)
Lemma q_lower_val :
  CReq R (CR_of_Q R (11 # 128) - CR_of_Q R (5103 # 322560)) (CR_of_Q R (22617 # 322560)).
Proof.
  unfold CRminus.
  apply (CReq_trans _ (CR_of_Q R (11 # 128) + CR_of_Q R (-(5103 # 322560))) _).
  - apply (CRplus_morph_Proper (CR_of_Q R (11 # 128)) (CR_of_Q R (11 # 128)) (CReq_refl _)
                               (- (CR_of_Q R (5103 # 322560))) (CR_of_Q R (-(5103 # 322560)))
                               ltac:(apply CReq_sym; apply (CR_of_Q_opp (5103 # 322560)))).
  - apply (CReq_trans _ (CR_of_Q R ((11 # 128) + (-(5103 # 322560)))%Q) _).
    + apply CReq_sym. apply (CR_of_Q_plus R (11 # 128) (-(5103 # 322560))).
    + apply (CR_of_Q_morph R ((11 # 128) + (-(5103 # 322560)))%Q (22617 # 322560)). vm_compute. reflexivity.
Qed.

(* (5/1080)A² ≤ (1/120)B（0 ≤ x,y，9B ≥ 5A²） *)
Lemma fiveA2_B_scale (x y : CRcarrier R) (Hx0 : 0 <= x) (Hy0 : 0 <= y) :
  CR_of_Q R (5 # 1080) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))
  <= CR_of_Q R (1 # 120) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x).
Proof.
  assert (H5 : CReq R (CR_of_Q R (1 # 1080) * (CR_of_Q R (5 # 1) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))))
                     (CR_of_Q R (5 # 1080) * ((y*y + y*x + x*x) * (y*y + y*x + x*x)))).
  { apply (CReq_trans _ ((CR_of_Q R (1 # 1080) * CR_of_Q R (5 # 1)) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))) _).
    - apply CReq_sym. apply (CRmult_assoc (CR_of_Q R (1 # 1080)) (CR_of_Q R (5 # 1)) ((y*y + y*x + x*x) * (y*y + y*x + x*x))).
    - apply (CRmult_morph_Proper (CR_of_Q R (1 # 1080) * CR_of_Q R (5 # 1)) (CR_of_Q R (5 # 1080))
             ltac:(apply CReq_sym; apply (CR_of_Q_mult R (1 # 1080) (5 # 1)))
             ((y*y + y*x + x*x) * (y*y + y*x + x*x)) ((y*y + y*x + x*x) * (y*y + y*x + x*x)) (CReq_refl _)). }
  assert (H9 : CReq R (CR_of_Q R (1 # 1080) * (CR_of_Q R (9 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)))
                     (CR_of_Q R (1 # 120) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x))).
  { apply (CReq_trans _ ((CR_of_Q R (1 # 1080) * CR_of_Q R (9 # 1)) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)) _).
    - apply CReq_sym. apply (CRmult_assoc (CR_of_Q R (1 # 1080)) (CR_of_Q R (9 # 1)) (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)).
    - apply (CReq_trans _ (CR_of_Q R (9 # 1080) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)) _).
      + apply (CRmult_morph_Proper (CR_of_Q R (1 # 1080) * CR_of_Q R (9 # 1)) (CR_of_Q R (9 # 1080))
               ltac:(apply CReq_sym; apply (CR_of_Q_mult R (1 # 1080) (9 # 1)))
               (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x) (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x) (CReq_refl _)).
      + apply (CRmult_morph_Proper (CR_of_Q R (9 # 1080)) (CR_of_Q R (1 # 120))
               ltac:(apply (CR_of_Q_morph R (9 # 1080) (1 # 120)); vm_compute; reflexivity)
               (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x) (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x) (CReq_refl _)). }
  apply (proj1 (CRle_morph R (CR_of_Q R (1 # 1080) * (CR_of_Q R (5 # 1) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))))
                           (CR_of_Q R (5 # 1080) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))) H5
                           (CR_of_Q R (1 # 1080) * (CR_of_Q R (9 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)))
                           (CR_of_Q R (1 # 120) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)) H9)).
  apply (CRmult_le_compat_l (CR_of_Q R (1 # 1080)) (CR_of_Q R (5 # 1) * ((y*y + y*x + x*x) * (y*y + y*x + x*x)))
                            (CR_of_Q R (9 # 1) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x))).
  - apply (CR_of_Q_le 0 (1 # 1080)). unfold Qle. simpl. lia.
  - apply nineB_ge_fiveAsq; assumption.
Qed.

(* S7 多项式：t - t³/6 + t⁵/120 - t⁷/5040 *)
Definition S7 (t : CRcarrier R) : CRcarrier R :=
  t - CR_of_Q R (1 # 6) * (t*t*t) + CR_of_Q R (1 # 120) * (t*t*t*t*t) - CR_of_Q R (1 # 5040) * (t*t*t*t*t*t*t).

(* S7 差商：S7(y) - S7(x) == (y-x)·Q7，Q7 = 1 - A/6 + B/120 - C/5040 *)
Lemma S7_diff (x y : CRcarrier R) :
  CReq R (S7 y - S7 x)
         ((y - x) * (CR_of_Q R (1 # 1)
                     - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                     + CR_of_Q R (1 # 120) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
                     - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x))).
Proof. unfold S7. unfold CRminus. ring. Qed.

(* Q7 ≥ 22617/322560（0 ≤ x,y ≤ 3/2） *)
Lemma Q7_lower (x y : CRcarrier R) (Hx0 : 0 <= x) (Hy0 : 0 <= y)
    (Hx32 : x <= CR_of_Q R (3 # 2)) (Hy32 : y <= CR_of_Q R (3 # 2)) :
  CR_of_Q R (22617 # 322560)
  <= (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
      + CR_of_Q R (1 # 120) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
      - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x)).
Proof.
  (* 22617/322560 ≤ 11/128 - 5103/322560 *)
  apply (CRle_trans _ (CR_of_Q R (11 # 128) - CR_of_Q R (5103 # 322560)) _).
  - apply (CRle_morph R (CR_of_Q R (22617 # 322560)) (CR_of_Q R (22617 # 322560)) (CReq_refl _)
                       (CR_of_Q R (11 # 128) - CR_of_Q R (5103 # 322560)) (CR_of_Q R (22617 # 322560)) (q_lower_val)).
    apply CRle_refl.
  - (* 11/128 - 5103/322560 ≤ h(A) - C/5040 *)
    assert (HA274 : CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (CR_of_Q R (27 # 4))
                    + CR_of_Q R (5 # 1080) * (CR_of_Q R (27 # 4) * CR_of_Q R (27 # 4))
                    <= CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                    + CR_of_Q R (5 # 1080) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))).
    { apply (h_decr (y*y + y*x + x*x) (CR_of_Q R (27 # 4))).
      - apply sum3_nonneg.
        + apply s7_CRsqr_nonneg.
        + apply q_nonprod; assumption.
        + apply s7_CRsqr_nonneg.
      - apply A_le; assumption.
      - apply CRle_refl. }
    assert (HC5040 : CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x)
                     <= CR_of_Q R (5103 # 322560)).
    { apply (CRle_trans _ (CR_of_Q R (1 # 5040) * CR_of_Q R (5103 # 64)) _).
      - apply (CRmult_le_compat_l (CR_of_Q R (1 # 5040)) (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x)
                                 (CR_of_Q R (5103 # 64))).
        + apply (CR_of_Q_le 0 (1 # 5040)). unfold Qle. simpl. lia.
        + apply C_le; assumption.
      - apply (CRle_morph R (CR_of_Q R (1 # 5040) * CR_of_Q R (5103 # 64)) (CR_of_Q R (5103 # 322560))
                           ltac:(apply CReq_sym; apply (CR_of_Q_mult R (1 # 5040) (5103 # 64)))
                           (CR_of_Q R (5103 # 322560)) (CR_of_Q R (5103 # 322560)) (CReq_refl _)).
        apply CRle_refl. }
    apply (CRle_trans _ (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                         + CR_of_Q R (5 # 1080) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))
                         - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x)) _).
    + (* 11/128 - 5103/322560 ≤ h(A) - C/5040 *)
      apply (CRplus_le_compat (CR_of_Q R (11 # 128))
                              (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                               + CR_of_Q R (5 # 1080) * ((y*y + y*x + x*x) * (y*y + y*x + x*x)))
                              (- (CR_of_Q R (5103 # 322560)))
                              (- (CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x)))).
      * (* 11/128 ≤ h(A) *)
        apply (CRle_trans _ (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (CR_of_Q R (27 # 4))
                            + CR_of_Q R (5 # 1080) * (CR_of_Q R (27 # 4) * CR_of_Q R (27 # 4))) _).
        - apply (CRle_morph R (CR_of_Q R (11 # 128)) (CR_of_Q R (11 # 128)) (CReq_refl _)
                             (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (CR_of_Q R (27 # 4))
                              + CR_of_Q R (5 # 1080) * (CR_of_Q R (27 # 4) * CR_of_Q R (27 # 4)))
                             (CR_of_Q R (11 # 128)) (h274_val)).
          apply CRle_refl.
        - exact HA274.
      * (* -(5103/322560) ≤ -(C/5040) *)
        apply opp_le_compat. exact HC5040.
    + (* h(A) - C/5040 ≤ Q7 *)
      apply (CRle_morph R (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                           + CR_of_Q R (5 # 1080) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))
                           - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x))
                         (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                          + (CR_of_Q R (5 # 1080) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))
                             - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x)))
                         ltac:(unfold CRminus; ring)
                         (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                          + CR_of_Q R (1 # 120) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
                          - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x))
                         (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                          + (CR_of_Q R (1 # 120) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
                             - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x)))
                         ltac:(unfold CRminus; ring)).
      apply (CRplus_le_compat_l (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x))
                                (CR_of_Q R (5 # 1080) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))
                                 - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x))
                                (CR_of_Q R (1 # 120) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
                                 - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x))).
      apply (CRplus_le_compat_r (- (CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x)))
                                (CR_of_Q R (5 # 1080) * ((y*y + y*x + x*x) * (y*y + y*x + x*x)))
                                (CR_of_Q R (1 # 120) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x))).
      apply fiveA2_B_scale; assumption.
Qed.

(* S7 递增：0 ≤ x ≤ y ≤ 3/2 ⟹ S7(x) ≤ S7(y) *)
Lemma S7_incr (x y : CRcarrier R) (Hxy : x <= y) (Hx0 : 0 <= x) (Hy32 : y <= CR_of_Q R (3 # 2)) :
  S7 x <= S7 y.
Proof.
  assert (Hy0 : 0 <= y) by (apply (CRle_trans _ x _); assumption).
  assert (Hx32 : x <= CR_of_Q R (3 # 2)) by (apply (CRle_trans _ y _); assumption).
  (* 0 ≤ S7y - S7x == (y-x)·Q7 ≥ 0 *)
  apply (CRle_morph R (S7 x) (S7 x) (CReq_refl _)
                     (S7 y) (S7 x + (S7 y - S7 x)) ltac:(unfold CRminus; ring)).
  apply (le_plus_l (S7 x) (S7 y - S7 x)).
  apply (CRle_morph R 0 0 (CReq_refl _) (S7 y - S7 x)
                     ((y - x) * (CR_of_Q R (1 # 1)
                                 - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                                 + CR_of_Q R (1 # 120) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
                                 - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x)))
                     (S7_diff x y)).
  apply q_nonprod.
  - apply (CRle_morph R 0 (x + (- x)) ltac:(ring) (y - x) (y - x) (CReq_refl _)).
    apply (CRplus_le_compat_r (- x) x y). exact Hxy.
  - apply (CRle_trans _ (CR_of_Q R (22617 # 322560)) _).
    + apply (CR_of_Q_le 0 (22617 # 322560)). unfold Qle. simpl. lia.
    + apply Q7_lower; assumption.
Qed.

(* ============ Phase E：S9 递减 [8/5,2] ============ *)

(* T ≤ 0 ⟹ 0 ≤ -T *)
Lemma le0_nonneg (T : CRcarrier R) (HT : T <= 0) : 0 <= - T.
Proof.
  apply (CRle_morph R 0 (T + (- T)) ltac:(ring) (- T) (CR_of_Q R 0 + (- T)) ltac:(ring)).
  apply (CRplus_le_compat_r (- T) T 0). exact HT.
Qed.

(* 0 ≤ T ⟹ -T ≤ 0 *)
Lemma nonneg_opp_le0 (T : CRcarrier R) (HT : 0 <= T) : - T <= 0.
Proof.
  apply (CRle_morph R (- T) (0 + (- T)) ltac:(ring) 0 (T + (- T)) ltac:(ring)).
  apply (CRplus_le_compat_r (- T) 0 T). exact HT.
Qed.

(* 非负 × 非正 ≤ 0 *)
Lemma neg_prod (a b : CRcarrier R) (Ha : 0 <= a) (Hb : b <= 0) : a * b <= 0.
Proof.
  apply (CRle_morph R (a * b) (- (a * (- b))) ltac:(ring) 0 0 (CReq_refl _)).
  apply nonneg_opp_le0.
  apply q_nonprod.
  - exact Ha.
  - apply (proj1 (CRle_morph R (b + (- b)) 0 ltac:(ring) (0 + (- b)) (- b) ltac:(ring))).
    apply (CRplus_le_compat_r (- b) b 0). exact Hb.
Qed.

(* a ≤ b ⟹ 0 ≤ b-a *)
Lemma diff_nonneg (a b : CRcarrier R) (Hab : a <= b) : 0 <= b - a.
Proof.
  apply (CRle_morph R 0 (a + (- a)) ltac:(ring) (b - a) (b - a) (CReq_refl _)).
  apply (CRplus_le_compat_r (- a) a b). exact Hab.
Qed.

(* yx·(y+x)² ≥ 16384/625（x,y ≥ 8/5） *)
Lemma yx_ysq_ge (x y : CRcarrier R) (Hx0 : 0 <= x) (Hy0 : 0 <= y)
    (Hx85 : CR_of_Q R (8 # 5) <= x) (Hy85 : CR_of_Q R (8 # 5) <= y) :
  CR_of_Q R (16384 # 625) <= (y * x) * ((y + x) * (y + x)).
Proof.
  assert (Hyx : CR_of_Q R (64 # 25) <= y * x).
  { apply (CRle_trans _ (CR_of_Q R (8 # 5) * x) _).
    - apply (CRle_morph R (CR_of_Q R (64 # 25)) (CR_of_Q R (8 # 5) * CR_of_Q R (8 # 5))
                         ltac:(apply (CR_of_Q_mult R (8 # 5) (8 # 5)))
                         (CR_of_Q R (8 # 5) * x) (CR_of_Q R (8 # 5) * x) (CReq_refl _)).
      apply (CRmult_le_compat_l (CR_of_Q R (8 # 5)) (CR_of_Q R (8 # 5)) 
x
).
      + apply (CR_of_Q_le 0 (8 # 5)). unfold Qle. simpl. lia.
      + exact Hx85.
    - apply (CRmult_le_compat_r x (CR_of_Q R (8 # 5)) y).
      + exact Hx0.
      + exact Hy85. }
  assert (Hyx2 : CR_of_Q R (256 # 25) <= (y + x) * (y + x)).
  { assert (Hyxp : CR_of_Q R (16 # 5) <= y + x).
    { apply (CRle_trans _ (CR_of_Q R (8 # 5) + CR_of_Q R (8 # 5)) _).
      - apply (CRle_morph R (CR_of_Q R (16 # 5)) (CR_of_Q R (8 # 5) + CR_of_Q R (8 # 5))
                           ltac:(apply (CReq_trans _ (CR_of_Q R ((8 # 5) + (8 # 5))%Q) _);
                             [ apply (CR_of_Q_morph R (16 # 5) ((8 # 5) + (8 # 5))%Q); vm_compute; reflexivity
                             | apply (CR_of_Q_plus R (8 # 5) (8 # 5)) ])
                           (CR_of_Q R (8 # 5) + CR_of_Q R (8 # 5)) (CR_of_Q R (8 # 5) + CR_of_Q R (8 # 5)) (CReq_refl _)).
        apply CRle_refl.
      - apply (CRplus_le_compat (CR_of_Q R (8 # 5)) y (CR_of_Q R (8 # 5)) x).
        + exact Hy85.
        + exact Hx85. }
    apply (CRle_trans _ (CR_of_Q R (16 # 5) * (y + x)) _).
    - apply (CRle_morph R (CR_of_Q R (256 # 25)) (CR_of_Q R (16 # 5) * CR_of_Q R (16 # 5))
                         ltac:(apply (CR_of_Q_mult R (16 # 5) (16 # 5)))
                         (CR_of_Q R (16 # 5) * (y + x)) (CR_of_Q R (16 # 5) * (y + x)) (CReq_refl _)).
      apply (CRmult_le_compat_l (CR_of_Q R (16 # 5)) (CR_of_Q R (16 # 5)) (y + x)).
      + apply (CR_of_Q_le 0 (16 # 5)). unfold Qle. simpl. lia.
      + exact Hyxp.
    - apply (CRmult_le_compat_r (y + x) (CR_of_Q R (16 # 5)) (y + x)).
      + apply (CRle_trans _ (CR_of_Q R (16 # 5)) _). apply (CR_of_Q_le 0 (16 # 5)). unfold Qle. simpl. lia. exact Hyxp.
      + exact Hyxp. }
  apply (CRle_trans _ (CR_of_Q R (64 # 25) * CR_of_Q R (256 # 25)) _).
  - (* 16384/625 == (64/25)(256/25) *)
    apply (CRle_morph R (CR_of_Q R (16384 # 625)) (CR_of_Q R (16384 # 625)) (CReq_refl _)
                       (CR_of_Q R (64 # 25) * CR_of_Q R (256 # 25)) (CR_of_Q R (16384 # 625))
                       ltac:(apply CReq_sym; apply (CR_of_Q_mult R (64 # 25) (256 # 25)))).
    apply CRle_refl.
  - (* (64/25)(256/25) ≤ yx·((y+x)²) *)
    apply (CRle_trans _ ((y * x) * CR_of_Q R (256 # 25)) _).
    + apply (CRmult_le_compat_r (CR_of_Q R (256 # 25)) (CR_of_Q R (64 # 25)) (y * x)).
      * apply (CR_of_Q_le 0 (256 # 25)). unfold Qle. simpl. lia.
      * exact Hyx.
    + apply (CRmult_le_compat_l (y * x) (CR_of_Q R (256 # 25)) ((y + x) * (y + x))).
      * apply q_nonprod; assumption.
      * exact Hyx2.
Qed.

(* F(A) = 1 - A/6 + A²/120 ≤ 15864/75000（A ∈ [192/25, 12]） *)
Lemma F_le (A : CRcarrier R) (HA0 : 0 <= A) (HA192 : CR_of_Q R (192 # 25) <= A)
    (HA12 : A <= CR_of_Q R (12 # 1)) :
  (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * A + CR_of_Q R (1 # 120) * (A * A))
  <= CR_of_Q R (15864 # 75000).
Proof.
  (* F(A) - F(192/25) = (A - 192/25)·((A+192/25)/120 - 1/6) ≤ 0 *)
  (* 因子2 = S - 1/6 ≤ 0，S = (1/120)(A+192/25) ≤ 41/250 < 1/6 *)
  assert (Hf2 : CR_of_Q R (1 # 120) * (A + CR_of_Q R (192 # 25)) - CR_of_Q R (1 # 6) <= 0).
  { apply (CRle_morph R (CR_of_Q R (1 # 120) * (A + CR_of_Q R (192 # 25)) - CR_of_Q R (1 # 6))
                       (- (CR_of_Q R (1 # 6) - CR_of_Q R (1 # 120) * (A + CR_of_Q R (192 # 25)))) ltac:(unfold CRminus; ring)
                       0 0 (CReq_refl _)).
    apply nonneg_opp_le0.
    apply diff_nonneg.
    apply (CRle_trans _ (CR_of_Q R (1 # 120) * (CR_of_Q R (12 # 1) + CR_of_Q R (192 # 25))) _).
    - apply (CRmult_le_compat_l (CR_of_Q R (1 # 120)) (A + CR_of_Q R (192 # 25)) (CR_of_Q R (12 # 1) + CR_of_Q R (192 # 25))).
      + apply (CR_of_Q_le 0 (1 # 120)). unfold Qle. simpl. lia.
      + apply (CRplus_le_compat A (CR_of_Q R (12 # 1)) (CR_of_Q R (192 # 25)) (CR_of_Q R (192 # 25))).
        * exact HA12. apply CRle_refl.
    - apply (CRle_trans _ (CR_of_Q R (41 # 250)) _).
      + assert (Hq : CReq R (CR_of_Q R (1 # 120) * (CR_of_Q R (12 # 1) + CR_of_Q R (192 # 25)))
                            (CR_of_Q R (41 # 250))).
        { apply (CReq_trans _ (CR_of_Q R (1 # 120) * CR_of_Q R ((12 # 1) + (192 # 25))%Q) _).
          - apply (CRmult_morph_Proper (CR_of_Q R (1 # 120)) (CR_of_Q R (1 # 120)) (CReq_refl _)
                                       (CR_of_Q R (12 # 1) + CR_of_Q R (192 # 25)) (CR_of_Q R ((12 # 1) + (192 # 25))%Q)
                                       ltac:(apply CReq_sym; apply (CR_of_Q_plus R (12 # 1) (192 # 25)))).
          - apply (CReq_trans _ (CR_of_Q R ((1 # 120) * ((12 # 1) + (192 # 25)))%Q) _);
            [ apply CReq_sym; apply (CR_of_Q_mult R (1 # 120) ((12 # 1) + (192 # 25))%Q)
            | apply (CR_of_Q_morph R ((1 # 120) * ((12 # 1) + (192 # 25)))%Q (41 # 250)); vm_compute; reflexivity ]. }
        apply (CRle_morph R (CR_of_Q R (1 # 120) * (CR_of_Q R (12 # 1) + CR_of_Q R (192 # 25))) (CR_of_Q R (41 # 250))
                           ltac:(exact Hq)
                           (CR_of_Q R (41 # 250)) (CR_of_Q R (41 # 250)) (CReq_refl _)).
        apply CRle_refl.
      + apply (CR_of_Q_le (41 # 250) (1 # 6)). unfold Qle. simpl. lia.
  }
  (* F(A) - F(192/25) == (A - 192/25)·((A+192/25)/120 - 1/6) *)
  apply (CRle_trans _ (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (CR_of_Q R (192 # 25))
                       + CR_of_Q R (1 # 120) * (CR_of_Q R (192 # 25) * CR_of_Q R (192 # 25))) _).
  - apply (CRle_morph R (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * A + CR_of_Q R (1 # 120) * (A * A))
                             (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * A + CR_of_Q R (1 # 120) * (A * A)) (CReq_refl _)
                             (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (CR_of_Q R (192 # 25))
                              + CR_of_Q R (1 # 120) * (CR_of_Q R (192 # 25) * CR_of_Q R (192 # 25)))
                             (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * A + CR_of_Q R (1 # 120) * (A * A)
                              + ((CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (CR_of_Q R (192 # 25))
                                  + CR_of_Q R (1 # 120) * (CR_of_Q R (192 # 25) * CR_of_Q R (192 # 25)))
                                 - (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * A + CR_of_Q R (1 # 120) * (A * A))))
                             ltac:(unfold CRminus; ring)).
    apply (le_plus_l (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * A + CR_of_Q R (1 # 120) * (A * A))
                     ((CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (CR_of_Q R (192 # 25))
                       + CR_of_Q R (1 # 120) * (CR_of_Q R (192 # 25) * CR_of_Q R (192 # 25)))
                      - (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * A + CR_of_Q R (1 # 120) * (A * A)))).
    apply (CRle_morph R 0 0 (CReq_refl _)
                             ((CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (CR_of_Q R (192 # 25))
                               + CR_of_Q R (1 # 120) * (CR_of_Q R (192 # 25) * CR_of_Q R (192 # 25)))
                              - (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * A + CR_of_Q R (1 # 120) * (A * A)))
                             ((A - CR_of_Q R (192 # 25)) * (CR_of_Q R (1 # 6) - CR_of_Q R (1 # 120) * (A + CR_of_Q R (192 # 25))))
                             ltac:(unfold CRminus; ring)).
    apply q_nonprod.
    + apply diff_nonneg. exact HA192.
    + apply (CRle_morph R 0 0 (CReq_refl _)
                         (- (CR_of_Q R (1 # 120) * (A + CR_of_Q R (192 # 25)) - CR_of_Q R (1 # 6)))
                         (CR_of_Q R (1 # 6) - CR_of_Q R (1 # 120) * (A + CR_of_Q R (192 # 25)))
                         ltac:(unfold CRminus; ring)).
      apply le0_nonneg. exact Hf2.
  - (* F(192/25) == 15864/75000 *)
    assert (Hq : CReq R (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (CR_of_Q R (192 # 25))
                         + CR_of_Q R (1 # 120) * (CR_of_Q R (192 # 25) * CR_of_Q R (192 # 25)))
                        (CR_of_Q R (15864 # 75000))).
    { unfold CRminus.
      setoid_rewrite <- (CR_of_Q_mult R (1 # 6) (192 # 25)).
      setoid_rewrite <- (CR_of_Q_mult R (192 # 25) (192 # 25)).
      setoid_rewrite <- (CR_of_Q_mult R (1 # 120) (36864 # 625)).
      setoid_rewrite <- (CR_of_Q_opp (192 # 150)).
      apply (CReq_trans _ (CR_of_Q R ((1 # 1) + (-(192 # 150)) + (36864 # 75000))%Q) _).
      - apply (sum3_of_Q (1 # 1) (-(192 # 150)) (36864 # 75000)).
      - apply (CR_of_Q_morph R ((1 # 1) + (-(192 # 150)) + (36864 # 75000))%Q (15864 # 75000)). vm_compute. reflexivity. }
    apply (CRle_morph R (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (CR_of_Q R (192 # 25))
                         + CR_of_Q R (1 # 120) * (CR_of_Q R (192 # 25) * CR_of_Q R (192 # 25)))
                       (CR_of_Q R (15864 # 75000))
                       ltac:(exact Hq)
                       (CR_of_Q R (15864 # 75000)) (CR_of_Q R (15864 # 75000)) (CReq_refl _)).
    apply CRle_refl.
Qed.

(* A ≥ 192/25（x,y ≥ 8/5） *)
Lemma A_ge_192 (x y : CRcarrier R) (Hx0 : 0 <= x) (Hy0 : 0 <= y)
    (Hx85 : CR_of_Q R (8 # 5) <= x) (Hy85 : CR_of_Q R (8 # 5) <= y) :
  CR_of_Q R (192 # 25) <= y*y + y*x + x*x.
Proof.
  assert (Hy2 : CR_of_Q R (64 # 25) <= y * y).
  { apply (CRle_trans _ (CR_of_Q R (8 # 5) * y) _).
    - apply (CRle_morph R (CR_of_Q R (64 # 25)) (CR_of_Q R (8 # 5) * CR_of_Q R (8 # 5))
                         ltac:(apply (CR_of_Q_mult R (8 # 5) (8 # 5)))
                         (CR_of_Q R (8 # 5) * y) (CR_of_Q R (8 # 5) * y) (CReq_refl _)).
      apply (CRmult_le_compat_l (CR_of_Q R (8 # 5)) (CR_of_Q R (8 # 5)) 
y
).
      + apply (CR_of_Q_le 0 (8 # 5)). unfold Qle. simpl. lia.
      + exact Hy85.
    - apply (CRmult_le_compat_r y (CR_of_Q R (8 # 5)) y).
      + exact Hy0.
      + exact Hy85. }
  assert (Hyx : CR_of_Q R (64 # 25) <= y * x).
  { apply (CRle_trans _ (CR_of_Q R (8 # 5) * x) _).
    - apply (CRle_morph R (CR_of_Q R (64 # 25)) (CR_of_Q R (8 # 5) * CR_of_Q R (8 # 5))
                         ltac:(apply (CR_of_Q_mult R (8 # 5) (8 # 5)))
                         (CR_of_Q R (8 # 5) * x) (CR_of_Q R (8 # 5) * x) (CReq_refl _)).
      apply (CRmult_le_compat_l (CR_of_Q R (8 # 5)) (CR_of_Q R (8 # 5)) 
x
).
      + apply (CR_of_Q_le 0 (8 # 5)). unfold Qle. simpl. lia.
      + exact Hx85.
    - apply (CRmult_le_compat_r x (CR_of_Q R (8 # 5)) y).
      + exact Hx0.
      + exact Hy85. }
  assert (Hx2 : CR_of_Q R (64 # 25) <= x * x).
  { apply (CRle_trans _ (CR_of_Q R (8 # 5) * x) _).
    - apply (CRle_morph R (CR_of_Q R (64 # 25)) (CR_of_Q R (8 # 5) * CR_of_Q R (8 # 5))
                         ltac:(apply (CR_of_Q_mult R (8 # 5) (8 # 5)))
                         (CR_of_Q R (8 # 5) * x) (CR_of_Q R (8 # 5) * x) (CReq_refl _)).
      apply (CRmult_le_compat_l (CR_of_Q R (8 # 5)) (CR_of_Q R (8 # 5)) 
x
).
      + apply (CR_of_Q_le 0 (8 # 5)). unfold Qle. simpl. lia.
      + exact Hx85.
    - apply (CRmult_le_compat_r x (CR_of_Q R (8 # 5)) x).
      + exact Hx0.
      + exact Hx85. }
  apply (CRle_trans _ (CR_of_Q R (64 # 25) + CR_of_Q R (64 # 25) + CR_of_Q R (64 # 25)) _).
  - (* 192/25 == 3·(64/25) *)
    apply (CRle_morph R (CR_of_Q R (192 # 25)) (CR_of_Q R (192 # 25)) (CReq_refl _)
                       (CR_of_Q R (64 # 25) + CR_of_Q R (64 # 25) + CR_of_Q R (64 # 25)) (CR_of_Q R (192 # 25))
                       ltac:(apply (CReq_trans _ (CR_of_Q R ((64 # 25) + (64 # 25) + (64 # 25))%Q) _);
                             [ apply (sum3_of_Q (64 # 25) (64 # 25) (64 # 25))
                             | apply (CR_of_Q_morph R ((64 # 25) + (64 # 25) + (64 # 25))%Q (192 # 25)); vm_compute; reflexivity ])).
    apply CRle_refl.
  - (* 3M ≤ y²+yx+x² *)
    apply (CRplus_le_compat (CR_of_Q R (64 # 25) + CR_of_Q R (64 # 25)) (y*y + y*x)
                            (CR_of_Q R (64 # 25)) (x*x)).
    + apply (CRplus_le_compat (CR_of_Q R (64 # 25)) (y*y) (CR_of_Q R (64 # 25)) (y*x)).
      * exact Hy2.
      * exact Hyx.
    + exact Hx2.
Qed.

(* A ≤ 12（x,y ≤ 2） *)
Lemma A_le_12 (x y : CRcarrier R) (Hx0 : 0 <= x) (Hy0 : 0 <= y)
    (Hx2 : x <= CR_of_Q R (2 # 1)) (Hy2 : y <= CR_of_Q R (2 # 1)) :
  y*y + y*x + x*x <= CR_of_Q R (12 # 1).
Proof.
  assert (Hy2q : y * y <= CR_of_Q R (4 # 1)).
  { apply (CRle_trans _ (CR_of_Q R (2 # 1) * y) _).
    - apply (CRmult_le_compat_r y y (CR_of_Q R (2 # 1))).
      + exact Hy0.
      + exact Hy2.
    - apply (CRle_trans _ (CR_of_Q R (2 # 1) * CR_of_Q R (2 # 1)) _).
      + apply (CRmult_le_compat_l (CR_of_Q R (2 # 1)) y (CR_of_Q R (2 # 1))).
        * apply (CR_of_Q_le 0 (2 # 1)). unfold Qle. simpl. lia.
        * exact Hy2.
      + apply (CRle_morph R (CR_of_Q R (2 # 1) * CR_of_Q R (2 # 1)) (CR_of_Q R (4 # 1))
                           ltac:(apply CReq_sym; apply (CR_of_Q_mult R (2 # 1) (2 # 1)))
                           (CR_of_Q R (4 # 1)) (CR_of_Q R (4 # 1)) (CReq_refl _)).
        apply CRle_refl. }
  assert (Hyx : y * x <= CR_of_Q R (4 # 1)).
  { apply (CRle_trans _ (CR_of_Q R (2 # 1) * x) _).
    - apply (CRmult_le_compat_r x y (CR_of_Q R (2 # 1))).
      + exact Hx0.
      + exact Hy2.
    - apply (CRle_trans _ (CR_of_Q R (2 # 1) * CR_of_Q R (2 # 1)) _).
      + apply (CRmult_le_compat_l (CR_of_Q R (2 # 1)) x (CR_of_Q R (2 # 1))).
        * apply (CR_of_Q_le 0 (2 # 1)). unfold Qle. simpl. lia.
        * exact Hx2.
      + apply (CRle_morph R (CR_of_Q R (2 # 1) * CR_of_Q R (2 # 1)) (CR_of_Q R (4 # 1))
                           ltac:(apply CReq_sym; apply (CR_of_Q_mult R (2 # 1) (2 # 1)))
                           (CR_of_Q R (4 # 1)) (CR_of_Q R (4 # 1)) (CReq_refl _)).
        apply CRle_refl. }
  assert (Hx2q : x * x <= CR_of_Q R (4 # 1)).
  { apply (CRle_trans _ (CR_of_Q R (2 # 1) * x) _).
    - apply (CRmult_le_compat_r x x (CR_of_Q R (2 # 1))).
      + exact Hx0.
      + exact Hx2.
    - apply (CRle_trans _ (CR_of_Q R (2 # 1) * CR_of_Q R (2 # 1)) _).
      + apply (CRmult_le_compat_l (CR_of_Q R (2 # 1)) x (CR_of_Q R (2 # 1))).
        * apply (CR_of_Q_le 0 (2 # 1)). unfold Qle. simpl. lia.
        * exact Hx2.
      + apply (CRle_morph R (CR_of_Q R (2 # 1) * CR_of_Q R (2 # 1)) (CR_of_Q R (4 # 1))
                           ltac:(apply CReq_sym; apply (CR_of_Q_mult R (2 # 1) (2 # 1)))
                           (CR_of_Q R (4 # 1)) (CR_of_Q R (4 # 1)) (CReq_refl _)).
        apply CRle_refl. }
  apply (CRle_trans _ (CR_of_Q R (4 # 1) + CR_of_Q R (4 # 1) + CR_of_Q R (4 # 1)) _).
  - apply (CRplus_le_compat (y*y + y*x) (CR_of_Q R (4 # 1) + CR_of_Q R (4 # 1)) (x*x) (CR_of_Q R (4 # 1))).
    + apply (CRplus_le_compat (y*y) (CR_of_Q R (4 # 1)) (y*x) (CR_of_Q R (4 # 1))). exact Hy2q. exact Hyx.
    + exact Hx2q.
  - apply (CRle_morph R (CR_of_Q R (4 # 1) + CR_of_Q R (4 # 1) + CR_of_Q R (4 # 1)) (CR_of_Q R (12 # 1))
                       ltac:(apply (CReq_trans _ (CR_of_Q R ((4 # 1) + (4 # 1) + (4 # 1))%Q) _);
                             [ apply (sum3_of_Q (4 # 1) (4 # 1) (4 # 1))
                             | apply (CR_of_Q_morph R ((4 # 1) + (4 # 1) + (4 # 1))%Q (12 # 1)); vm_compute; reflexivity ])
                       (CR_of_Q R (12 # 1)) (CR_of_Q R (12 # 1)) (CReq_refl _)).
    apply CRle_refl.
Qed.

(* C ≥ 0（7 项非负和） *)
Lemma C_nonneg (x y : CRcarrier R) (Hx0 : 0 <= x) (Hy0 : 0 <= y) :
  0 <= y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x.
Proof.
  assert (Hy6 : 0 <= y*y*y*y*y*y).
  { apply (CRle_morph R 0 0 (CReq_refl _) (x_pow y 6 * x_pow x 0) (y*y*y*y*y*y) ltac:(cbn [x_pow]; ring)).
    apply (q_nonprod (x_pow y 6) (x_pow x 0)).
    - apply x_pow_nonneg. exact Hy0.
    - apply x_pow_nonneg. exact Hx0. }
  assert (Hy5x : 0 <= y*y*y*y*y*x).
  { apply (CRle_morph R 0 0 (CReq_refl _) (x_pow y 5 * x_pow x 1) (y*y*y*y*y*x) ltac:(cbn [x_pow]; ring)).
    apply (q_nonprod (x_pow y 5) (x_pow x 1)).
    - apply x_pow_nonneg. exact Hy0.
    - apply x_pow_nonneg. exact Hx0. }
  assert (Hy4x2 : 0 <= y*y*y*y*x*x).
  { apply (CRle_morph R 0 0 (CReq_refl _) (x_pow y 4 * x_pow x 2) (y*y*y*y*x*x) ltac:(cbn [x_pow]; ring)).
    apply (q_nonprod (x_pow y 4) (x_pow x 2)).
    - apply x_pow_nonneg. exact Hy0.
    - apply x_pow_nonneg. exact Hx0. }
  assert (Hy3x3 : 0 <= y*y*y*x*x*x).
  { apply (CRle_morph R 0 0 (CReq_refl _) (x_pow y 3 * x_pow x 3) (y*y*y*x*x*x) ltac:(cbn [x_pow]; ring)).
    apply (q_nonprod (x_pow y 3) (x_pow x 3)).
    - apply x_pow_nonneg. exact Hy0.
    - apply x_pow_nonneg. exact Hx0. }
  assert (Hy2x4 : 0 <= y*y*x*x*x*x).
  { apply (CRle_morph R 0 0 (CReq_refl _) (x_pow y 2 * x_pow x 4) (y*y*x*x*x*x) ltac:(cbn [x_pow]; ring)).
    apply (q_nonprod (x_pow y 2) (x_pow x 4)).
    - apply x_pow_nonneg. exact Hy0.
    - apply x_pow_nonneg. exact Hx0. }
  assert (Hyx5 : 0 <= y*x*x*x*x*x).
  { apply (CRle_morph R 0 0 (CReq_refl _) (x_pow y 1 * x_pow x 5) (y*x*x*x*x*x) ltac:(cbn [x_pow]; ring)).
    apply (q_nonprod (x_pow y 1) (x_pow x 5)).
    - apply x_pow_nonneg. exact Hy0.
    - apply x_pow_nonneg. exact Hx0. }
  assert (Hx6 : 0 <= x*x*x*x*x*x).
  { apply (CRle_morph R 0 0 (CReq_refl _) (x_pow y 0 * x_pow x 6) (x*x*x*x*x*x) ltac:(cbn [x_pow]; ring)).
    apply (q_nonprod (x_pow y 0) (x_pow x 6)).
    - apply x_pow_nonneg. exact Hy0.
    - apply x_pow_nonneg. exact Hx0. }
  apply (CRle_trans _ (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x) _).
  - apply (CRle_trans _ (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x) _).
    + apply (CRle_trans _ (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x) _).
      * apply (CRle_trans _ (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x) _).
        + apply (CRle_trans _ (y*y*y*y*y*y + y*y*y*y*y*x) _).
          * apply (CRle_trans _ (y*y*y*y*y*y) _).
            - exact Hy6.
            - apply (le_plus_l (y*y*y*y*y*y) (y*y*y*y*y*x)). exact Hy5x.
          * apply (le_plus_l (y*y*y*y*y*y + y*y*y*y*y*x) (y*y*y*y*x*x)). exact Hy4x2.
        + apply (le_plus_l (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x) (y*y*y*x*x*x)). exact Hy3x3.
      * apply (le_plus_l (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x) (y*y*x*x*x*x)). exact Hy2x4.
    + apply (le_plus_l (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x) (y*x*x*x*x*x)). exact Hyx5.
  - apply (le_plus_l (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x) (x*x*x*x*x*x)). exact Hx6.
Qed.

(* B == A² - yx·(y+x)²（B = y⁴+...+x⁴，A = y²+yx+x²） *)
Lemma B_eq_sqdiff (x y : CRcarrier R) :
  CReq R (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
         ((y*y + y*x + x*x) * (y*y + y*x + x*x) - (y * x) * ((y + x) * (y + x))).
Proof. unfold CRminus. ring. Qed.

(* Q7 ≤ -520/75000（8/5 ≤ x,y ≤ 2） *)
Lemma Q7_upper (x y : CRcarrier R) (Hx0 : 0 <= x) (Hy0 : 0 <= y)
    (Hx85 : CR_of_Q R (8 # 5) <= x) (Hy85 : CR_of_Q R (8 # 5) <= y)
    (Hx2 : x <= CR_of_Q R (2 # 1)) (Hy2 : y <= CR_of_Q R (2 # 1)) :
  (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
   + CR_of_Q R (1 # 120) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
   - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x))
  <= CR_of_Q R (-(520 # 75000)).
Proof.
  (* Q7 == F(A) - yx(y+x)²/120 - C/5040（B == A² - yx(y+x)² 恒等式） *)
  (* Q7 ≤ F(A) - S（S = yx(y+x)²/120，C ≥ 0 丢弃）≤ 15864/75000 - 16384/75000 = -520/75000 *)
  assert (HA192 : CR_of_Q R (192 # 25) <= y*y + y*x + x*x).
  { apply A_ge_192; assumption. }
  assert (HA12 : y*y + y*x + x*x <= CR_of_Q R (12 # 1)).
  { apply A_le_12; assumption. }
  apply (CRle_trans _ (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                       + CR_of_Q R (1 # 120) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))
                       - CR_of_Q R (1 # 120) * ((y * x) * ((y + x) * (y + x)))) _).
  - (* Q7 ≤ F(A) - S：B == A² - yx(y+x)² 代入，再丢 -C/5040 *)
    apply (CRle_trans _ (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                         + CR_of_Q R (1 # 120) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))
                         - CR_of_Q R (1 # 120) * ((y * x) * ((y + x) * (y + x)))
                         - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x)) _).
  - (* F(A) - S ≤ 15864/75000 - 16384/75000 = -520/75000 *)
    + assert (Hq : CReq R (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                           + CR_of_Q R (1 # 120) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
                           - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x))
                          (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                           + CR_of_Q R (1 # 120) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))
                           - CR_of_Q R (1 # 120) * ((y * x) * ((y + x) * (y + x)))
                           - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x))).
      { setoid_rewrite (B_eq_sqdiff x y).
        unfold CRminus.
        ring. }
      apply (CRle_morph R (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                           + CR_of_Q R (1 # 120) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
                           - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x))
                         (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                          + CR_of_Q R (1 # 120) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))
                          - CR_of_Q R (1 # 120) * ((y * x) * ((y + x) * (y + x)))
                          - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x))
                         ltac:(exact Hq)
                         (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                          + CR_of_Q R (1 # 120) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))
                          - CR_of_Q R (1 # 120) * ((y * x) * ((y + x) * (y + x)))
                          - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x))
                         (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                          + CR_of_Q R (1 # 120) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))
                          - CR_of_Q R (1 # 120) * ((y * x) * ((y + x) * (y + x)))
                          - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x))
                         (CReq_refl _)).
      apply CRle_refl.
    + apply (proj1 (CRle_morph R ((CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                                   + CR_of_Q R (1 # 120) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))
                                   - CR_of_Q R (1 # 120) * ((y * x) * ((y + x) * (y + x))))
                                  + (- (CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x))))
                           (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                            + CR_of_Q R (1 # 120) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))
                            - CR_of_Q R (1 # 120) * ((y * x) * ((y + x) * (y + x)))
                            - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x))
                           ltac:(unfold CRminus; ring)
                           ((CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                             + CR_of_Q R (1 # 120) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))
                             - CR_of_Q R (1 # 120) * ((y * x) * ((y + x) * (y + x)))) + 0)
                           (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                            + CR_of_Q R (1 # 120) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))
                            - CR_of_Q R (1 # 120) * ((y * x) * ((y + x) * (y + x))))
                           ltac:(ring))).
      apply (CRplus_le_compat_l (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                                 + CR_of_Q R (1 # 120) * ((y*y + y*x + x*x) * (y*y + y*x + x*x))
                                 - CR_of_Q R (1 # 120) * ((y * x) * ((y + x) * (y + x))))
                                (- (CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x)))
                                (CR_of_Q R 0)).
      apply nonneg_opp_le0.
      apply (q_nonprod (CR_of_Q R (1 # 5040))
                       (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x)).
      * apply (CR_of_Q_le 0 (1 # 5040)). unfold Qle. simpl. lia.
      * apply C_nonneg; assumption.
    apply (CRle_trans _ (CR_of_Q R (15864 # 75000) - CR_of_Q R (1 # 120) * ((y * x) * ((y + x) * (y + x)))) _).
    + apply (CRplus_le_compat_r (- (CR_of_Q R (1 # 120) * ((y * x) * ((y + x) * (y + x)))))
                                (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                                 + CR_of_Q R (1 # 120) * ((y*y + y*x + x*x) * (y*y + y*x + x*x)))
                                (CR_of_Q R (15864 # 75000))).
      apply F_le.
      * apply sum3_nonneg.
        + apply s7_CRsqr_nonneg.
        + apply q_nonprod; assumption.
        + apply s7_CRsqr_nonneg.
      * exact HA192.
      * exact HA12.
    + apply (CRle_trans _ (CR_of_Q R (15864 # 75000) - CR_of_Q R (16384 # 75000)) _).
      * apply (CRplus_le_compat_l (CR_of_Q R (15864 # 75000))
                                  (- (CR_of_Q R (1 # 120) * ((y * x) * ((y + x) * (y + x)))))
                                  (- (CR_of_Q R (16384 # 75000)))).
        apply opp_le_compat.
        apply (CRle_trans _ (CR_of_Q R (1 # 120) * CR_of_Q R (16384 # 625)) _).
        - apply (CRle_morph R (CR_of_Q R (16384 # 75000)) (CR_of_Q R (16384 # 75000)) (CReq_refl _)
                             (CR_of_Q R (1 # 120) * CR_of_Q R (16384 # 625)) (CR_of_Q R (16384 # 75000))
                             ltac:(apply CReq_sym; apply (CR_of_Q_mult R (1 # 120) (16384 # 625)))).
          apply CRle_refl.
        - apply (CRmult_le_compat_l (CR_of_Q R (1 # 120)) (CR_of_Q R (16384 # 625)) ((y * x) * ((y + x) * (y + x)))).
          + apply (CR_of_Q_le 0 (1 # 120)). unfold Qle. simpl. lia.
          + apply yx_ysq_ge; assumption.
      * assert (Hdiff : CReq R (CR_of_Q R (15864 # 75000) - CR_of_Q R (16384 # 75000))
                                (CR_of_Q R (-(520 # 75000)))).
        { unfold CRminus.
          apply (CReq_trans _ (CR_of_Q R (15864 # 75000) + CR_of_Q R (-(16384 # 75000))) _).
          - apply (CRplus_morph_Proper (CR_of_Q R (15864 # 75000)) (CR_of_Q R (15864 # 75000)) (CReq_refl _)
                                       (- (CR_of_Q R (16384 # 75000))) (CR_of_Q R (-(16384 # 75000)))
                                       ltac:(apply CReq_sym; apply (CR_of_Q_opp (16384 # 75000)))).
          - apply (CReq_trans _ (CR_of_Q R ((15864 # 75000) + (-(16384 # 75000)))%Q) _).
            + apply CReq_sym. apply (CR_of_Q_plus R (15864 # 75000) (-(16384 # 75000))).
            + apply (CR_of_Q_morph R ((15864 # 75000) + (-(16384 # 75000)))%Q (-(520 # 75000))). vm_compute. reflexivity.
        }
        apply (CRle_morph R (CR_of_Q R (15864 # 75000) - CR_of_Q R (16384 # 75000))
                           (CR_of_Q R (-(520 # 75000)))
                           ltac:(exact Hdiff)
                           (CR_of_Q R (-(520 # 75000))) (CR_of_Q R (-(520 # 75000))) (CReq_refl _)).
        apply CRle_refl.
Qed.

(* D = y⁸+...+x⁸ ≤ 2304（x,y ≤ 2） *)
(* sum9 求和辅助：9 项每项 ≤ M ⟹ 和 ≤ 9M（展开形式） *)
Lemma sum9_le_M (a0 a1 a2 a3 a4 a5 a6 a7 a8 M : CRcarrier R)
    (H0 : a0 <= M) (H1 : a1 <= M) (H2 : a2 <= M) (H3 : a3 <= M) (H4 : a4 <= M)
    (H5 : a5 <= M) (H6 : a6 <= M) (H7 : a7 <= M) (H8 : a8 <= M) :
  a0+a1+a2+a3+a4+a5+a6+a7+a8 <= M+M+M+M+M+M+M+M+M.
Proof.
  apply (CRplus_le_compat (a0+a1+a2+a3+a4+a5+a6+a7) (M+M+M+M+M+M+M+M) (a8) (M)).
  - apply (CRplus_le_compat (a0+a1+a2+a3+a4+a5+a6) (M+M+M+M+M+M+M) (a7) (M)).
    + apply (CRplus_le_compat (a0+a1+a2+a3+a4+a5) (M+M+M+M+M+M) (a6) (M)).
      * apply (CRplus_le_compat (a0+a1+a2+a3+a4) (M+M+M+M+M) (a5) (M)).
        - apply (CRplus_le_compat (a0+a1+a2+a3) (M+M+M+M) (a4) (M)).
          + apply (CRplus_le_compat (a0+a1+a2) (M+M+M) (a3) (M)).
            * apply (CRplus_le_compat (a0+a1) (M+M) (a2) (M)).
              - apply (CRplus_le_compat (a0) (M) (a1) (M)). exact H0. exact H1.
              - exact H2.
            * exact H3.
          + exact H4.
        - exact H5.
      * exact H6.
    + exact H7.
  - exact H8.
Qed.

Lemma D_le2304 (x y : CRcarrier R) (Hx0 : 0 <= x) (Hy0 : 0 <= y)
    (Hx2 : x <= CR_of_Q R (2 # 1)) (Hy2 : y <= CR_of_Q R (2 # 1)) :
  y*y*y*y*y*y*y*y + y*y*y*y*y*y*y*x + y*y*y*y*y*y*x*x + y*y*y*y*y*x*x*x + y*y*y*y*x*x*x*x + y*y*y*x*x*x*x*x + y*y*x*x*x*x*x*x + y*x*x*x*x*x*x*x + x*x*x*x*x*x*x*x
  <= CR_of_Q R (2304 # 1).
Proof.
  assert (H0 : y*y*y*y*y*y*y*y <= CR_of_Q R (256 # 1)).
  { apply (CRle_morph R (y*y*y*y*y*y*y*y) (x_pow y 8 * x_pow x 0) ltac:(cbn [x_pow]; ring)
                       (CR_of_Q R (256 # 1)) (CR_of_Q R (256 # 1)) (CReq_refl _)).
    apply (mon_le_const (2 # 1) y x 8 8 ltac:(lia) Hy0 Hx0 Hy2 Hx2
                         ltac:(apply (CR_of_Q_le 0 (2 # 1)); unfold Qle; simpl; lia)). }
  assert (H1 : y*y*y*y*y*y*y*x <= CR_of_Q R (256 # 1)).
  { apply (CRle_morph R (y*y*y*y*y*y*y*x) (x_pow y 7 * x_pow x 1) ltac:(cbn [x_pow]; ring)
                       (CR_of_Q R (256 # 1)) (CR_of_Q R (256 # 1)) (CReq_refl _)).
    apply (mon_le_const (2 # 1) y x 7 8 ltac:(lia) Hy0 Hx0 Hy2 Hx2
                         ltac:(apply (CR_of_Q_le 0 (2 # 1)); unfold Qle; simpl; lia)). }
  assert (H2 : y*y*y*y*y*y*x*x <= CR_of_Q R (256 # 1)).
  { apply (CRle_morph R (y*y*y*y*y*y*x*x) (x_pow y 6 * x_pow x 2) ltac:(cbn [x_pow]; ring)
                       (CR_of_Q R (256 # 1)) (CR_of_Q R (256 # 1)) (CReq_refl _)).
    apply (mon_le_const (2 # 1) y x 6 8 ltac:(lia) Hy0 Hx0 Hy2 Hx2
                         ltac:(apply (CR_of_Q_le 0 (2 # 1)); unfold Qle; simpl; lia)). }
  assert (H3 : y*y*y*y*y*x*x*x <= CR_of_Q R (256 # 1)).
  { apply (CRle_morph R (y*y*y*y*y*x*x*x) (x_pow y 5 * x_pow x 3) ltac:(cbn [x_pow]; ring)
                       (CR_of_Q R (256 # 1)) (CR_of_Q R (256 # 1)) (CReq_refl _)).
    apply (mon_le_const (2 # 1) y x 5 8 ltac:(lia) Hy0 Hx0 Hy2 Hx2
                         ltac:(apply (CR_of_Q_le 0 (2 # 1)); unfold Qle; simpl; lia)). }
  assert (H4 : y*y*y*y*x*x*x*x <= CR_of_Q R (256 # 1)).
  { apply (CRle_morph R (y*y*y*y*x*x*x*x) (x_pow y 4 * x_pow x 4) ltac:(cbn [x_pow]; ring)
                       (CR_of_Q R (256 # 1)) (CR_of_Q R (256 # 1)) (CReq_refl _)).
    apply (mon_le_const (2 # 1) y x 4 8 ltac:(lia) Hy0 Hx0 Hy2 Hx2
                         ltac:(apply (CR_of_Q_le 0 (2 # 1)); unfold Qle; simpl; lia)). }
  assert (H5 : y*y*y*x*x*x*x*x <= CR_of_Q R (256 # 1)).
  { apply (CRle_morph R (y*y*y*x*x*x*x*x) (x_pow y 3 * x_pow x 5) ltac:(cbn [x_pow]; ring)
                       (CR_of_Q R (256 # 1)) (CR_of_Q R (256 # 1)) (CReq_refl _)).
    apply (mon_le_const (2 # 1) y x 3 8 ltac:(lia) Hy0 Hx0 Hy2 Hx2
                         ltac:(apply (CR_of_Q_le 0 (2 # 1)); unfold Qle; simpl; lia)). }
  assert (H6 : y*y*x*x*x*x*x*x <= CR_of_Q R (256 # 1)).
  { apply (CRle_morph R (y*y*x*x*x*x*x*x) (x_pow y 2 * x_pow x 6) ltac:(cbn [x_pow]; ring)
                       (CR_of_Q R (256 # 1)) (CR_of_Q R (256 # 1)) (CReq_refl _)).
    apply (mon_le_const (2 # 1) y x 2 8 ltac:(lia) Hy0 Hx0 Hy2 Hx2
                         ltac:(apply (CR_of_Q_le 0 (2 # 1)); unfold Qle; simpl; lia)). }
  assert (H7 : y*x*x*x*x*x*x*x <= CR_of_Q R (256 # 1)).
  { apply (CRle_morph R (y*x*x*x*x*x*x*x) (x_pow y 1 * x_pow x 7) ltac:(cbn [x_pow]; ring)
                       (CR_of_Q R (256 # 1)) (CR_of_Q R (256 # 1)) (CReq_refl _)).
    apply (mon_le_const (2 # 1) y x 1 8 ltac:(lia) Hy0 Hx0 Hy2 Hx2
                         ltac:(apply (CR_of_Q_le 0 (2 # 1)); unfold Qle; simpl; lia)). }
  assert (H8 : x*x*x*x*x*x*x*x <= CR_of_Q R (256 # 1)).
  { apply (CRle_morph R (x*x*x*x*x*x*x*x) (x_pow y 0 * x_pow x 8) ltac:(cbn [x_pow]; ring)
                       (CR_of_Q R (256 # 1)) (CR_of_Q R (256 # 1)) (CReq_refl _)).
    apply (mon_le_const (2 # 1) y x 0 8 ltac:(lia) Hy0 Hx0 Hy2 Hx2
                         ltac:(apply (CR_of_Q_le 0 (2 # 1)); unfold Qle; simpl; lia)). }
  apply (CRle_trans _ (CR_of_Q R (256 # 1) + CR_of_Q R (256 # 1) + CR_of_Q R (256 # 1)
                     + CR_of_Q R (256 # 1) + CR_of_Q R (256 # 1) + CR_of_Q R (256 # 1) + CR_of_Q R (256 # 1)
                     + CR_of_Q R (256 # 1) + CR_of_Q R (256 # 1)) _).
  - apply (sum9_le_M (y*y*y*y*y*y*y*y) (y*y*y*y*y*y*y*x) (y*y*y*y*y*y*x*x) (y*y*y*y*y*x*x*x) (y*y*y*y*x*x*x*x)
                     (y*y*y*x*x*x*x*x) (y*y*x*x*x*x*x*x) (y*x*x*x*x*x*x*x) (x*x*x*x*x*x*x*x) (CR_of_Q R (256 # 1)));
    assumption.
  - apply (CRle_morph R (CR_of_Q R (256 # 1) + CR_of_Q R (256 # 1) + CR_of_Q R (256 # 1)
                       + CR_of_Q R (256 # 1) + CR_of_Q R (256 # 1) + CR_of_Q R (256 # 1) + CR_of_Q R (256 # 1)
                       + CR_of_Q R (256 # 1) + CR_of_Q R (256 # 1))
                       (CR_of_Q R (2304 # 1))
                       ltac:(unfold CRminus;
                             setoid_rewrite <- (CRmult_1_l (CR_of_Q R (256 # 1)));
                             setoid_rewrite <- (CRscale_add (1 # 1) (1 # 1) (CR_of_Q R (256 # 1)));
                             setoid_rewrite <- (CRscale_add (2 # 1) (1 # 1) (CR_of_Q R (256 # 1)));
                             setoid_rewrite <- (CRscale_add (3 # 1) (1 # 1) (CR_of_Q R (256 # 1)));
                             setoid_rewrite <- (CRscale_add (4 # 1) (1 # 1) (CR_of_Q R (256 # 1)));
                             setoid_rewrite <- (CRscale_add (5 # 1) (1 # 1) (CR_of_Q R (256 # 1)));
                             setoid_rewrite <- (CRscale_add (6 # 1) (1 # 1) (CR_of_Q R (256 # 1)));
                             setoid_rewrite <- (CRscale_add (7 # 1) (1 # 1) (CR_of_Q R (256 # 1)));
                             setoid_rewrite <- (CRscale_add (8 # 1) (1 # 1) (CR_of_Q R (256 # 1)));
                             apply (CReq_trans _ (CR_of_Q R ((9 # 1) * (256 # 1))%Q) _);
                             [ apply CReq_sym; apply (CR_of_Q_mult R (9 # 1) (256 # 1))
                             | apply (CR_of_Q_morph R ((9 # 1) * (256 # 1))%Q (2304 # 1)); vm_compute; reflexivity ])
                       (CR_of_Q R (2304 # 1)) (CR_of_Q R (2304 # 1)) (CReq_refl _)).
    apply CRle_refl.
Qed.

(* Q9 = Q7 + D/362880 ≤ 0（8/5 ≤ x,y ≤ 2） *)
Lemma Q9_upper (x y : CRcarrier R) (Hx0 : 0 <= x) (Hy0 : 0 <= y)
    (Hx85 : CR_of_Q R (8 # 5) <= x) (Hy85 : CR_of_Q R (8 # 5) <= y)
    (Hx2 : x <= CR_of_Q R (2 # 1)) (Hy2 : y <= CR_of_Q R (2 # 1)) :
  (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
   + CR_of_Q R (1 # 120) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
   - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x)
   + CR_of_Q R (1 # 362880) * (y*y*y*y*y*y*y*y + y*y*y*y*y*y*y*x + y*y*y*y*y*y*x*x + y*y*y*y*y*x*x*x + y*y*y*y*x*x*x*x + y*y*y*x*x*x*x*x + y*y*x*x*x*x*x*x + y*x*x*x*x*x*x*x + x*x*x*x*x*x*x*x))
  <= CR_of_Q R 0.
Proof.
  apply (CRle_trans _ (CR_of_Q R (-(520 # 75000)) + CR_of_Q R (2304 # 362880)) _).
  - apply (CRle_trans _ (CR_of_Q R (-(520 # 75000)) + CR_of_Q R (1 # 362880) * (y*y*y*y*y*y*y*y + y*y*y*y*y*y*y*x + y*y*y*y*y*y*x*x + y*y*y*y*y*x*x*x + y*y*y*y*x*x*x*x + y*y*y*x*x*x*x*x + y*y*x*x*x*x*x*x + y*x*x*x*x*x*x*x + x*x*x*x*x*x*x*x)) _).
    - (* Q9 ≤ -520/75000 + c362880·D（Q7 ≤ -520/75000） *)
      apply (proj1 (CRle_morph R ((CR_of_Q R (1 # 362880) * (y*y*y*y*y*y*y*y + y*y*y*y*y*y*y*x + y*y*y*y*y*y*x*x + y*y*y*y*y*x*x*x + y*y*y*y*x*x*x*x + y*y*y*x*x*x*x*x + y*y*x*x*x*x*x*x + y*x*x*x*x*x*x*x + x*x*x*x*x*x*x*x)) + (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x) + CR_of_Q R (1 # 120) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x) - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x)))
                               (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x) + CR_of_Q R (1 # 120) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x) - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x) + CR_of_Q R (1 # 362880) * (y*y*y*y*y*y*y*y + y*y*y*y*y*y*y*x + y*y*y*y*y*y*x*x + y*y*y*y*y*x*x*x + y*y*y*y*x*x*x*x + y*y*y*x*x*x*x*x + y*y*x*x*x*x*x*x + y*x*x*x*x*x*x*x + x*x*x*x*x*x*x*x))
                               ltac:(unfold CRminus; ring)
                               ((CR_of_Q R (1 # 362880) * (y*y*y*y*y*y*y*y + y*y*y*y*y*y*y*x + y*y*y*y*y*y*x*x + y*y*y*y*y*x*x*x + y*y*y*y*x*x*x*x + y*y*y*x*x*x*x*x + y*y*x*x*x*x*x*x + y*x*x*x*x*x*x*x + x*x*x*x*x*x*x*x)) + (CR_of_Q R (-(520 # 75000))))
                               ((CR_of_Q R (-(520 # 75000))) + (CR_of_Q R (1 # 362880) * (y*y*y*y*y*y*y*y + y*y*y*y*y*y*y*x + y*y*y*y*y*y*x*x + y*y*y*y*y*x*x*x + y*y*y*y*x*x*x*x + y*y*y*x*x*x*x*x + y*y*x*x*x*x*x*x + y*x*x*x*x*x*x*x + x*x*x*x*x*x*x*x)))
                               ltac:(ring))).
      apply (CRplus_le_compat_l (CR_of_Q R (1 # 362880) * (y*y*y*y*y*y*y*y + y*y*y*y*y*y*y*x + y*y*y*y*y*y*x*x + y*y*y*y*y*x*x*x + y*y*y*y*x*x*x*x + y*y*y*x*x*x*x*x + y*y*x*x*x*x*x*x + y*x*x*x*x*x*x*x + x*x*x*x*x*x*x*x))
                                (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x) + CR_of_Q R (1 # 120) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x) - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x))
                                (CR_of_Q R (-(520 # 75000)))).
      apply Q7_upper; assumption.
    + (* c362880·D ≤ 2304/362880（D ≤ 2304） *)
      apply (CRplus_le_compat_l (CR_of_Q R (-(520 # 75000)))
                                (CR_of_Q R (1 # 362880) * (y*y*y*y*y*y*y*y + y*y*y*y*y*y*y*x + y*y*y*y*y*y*x*x + y*y*y*y*y*x*x*x + y*y*y*y*x*x*x*x + y*y*y*x*x*x*x*x + y*y*x*x*x*x*x*x + y*x*x*x*x*x*x*x + x*x*x*x*x*x*x*x))
                                (CR_of_Q R (2304 # 362880))).
      apply (CRle_trans _ (CR_of_Q R (1 # 362880) * CR_of_Q R (2304 # 1)) _).
      * apply (CRmult_le_compat_l (CR_of_Q R (1 # 362880)) (y*y*y*y*y*y*y*y + y*y*y*y*y*y*y*x + y*y*y*y*y*y*x*x + y*y*y*y*y*x*x*x + y*y*y*y*x*x*x*x + y*y*y*x*x*x*x*x + y*y*x*x*x*x*x*x + y*x*x*x*x*x*x*x + x*x*x*x*x*x*x*x)
                                  (CR_of_Q R (2304 # 1))).
        - apply (CR_of_Q_le 0 (1 # 362880)). unfold Qle. simpl. lia.
        - apply D_le2304; assumption.
      * apply (CRle_morph R (CR_of_Q R (1 # 362880) * CR_of_Q R (2304 # 1)) (CR_of_Q R (2304 # 362880))
                           ltac:(apply CReq_sym; apply (CR_of_Q_mult R (1 # 362880) (2304 # 1)))
                           (CR_of_Q R (2304 # 362880)) (CR_of_Q R (2304 # 362880)) (CReq_refl _)).
        apply CRle_refl.
  - apply (CRle_trans _ (CR_of_Q R (-(520 # 75000)) + CR_of_Q R (2304 # 362880)) _).
    + apply CRle_refl.
    + apply (CRle_morph R (CR_of_Q R (-(520 # 75000)) + CR_of_Q R (2304 # 362880))
                         (CR_of_Q R ((-(520 # 75000)) + (2304 # 362880))%Q)
                         ltac:(apply CReq_sym; apply (CR_of_Q_plus R (-(520 # 75000)) (2304 # 362880)))
                         (CR_of_Q R 0) (CR_of_Q R 0) (CReq_refl _)).
      apply (CR_of_Q_le ((-(520 # 75000)) + (2304 # 362880))%Q 0). unfold Qle. simpl. lia.
Qed.

(* S9 = S7 + t⁹/362880 *)
Definition S9 (t : CRcarrier R) : CRcarrier R :=
  S7 t + CR_of_Q R (1 # 362880) * (t*t*t*t*t*t*t*t*t).

(* S9 差商：S9(y) - S9(x) == (y-x)·Q9 *)
Lemma S9_diff (x y : CRcarrier R) :
  CReq R (S9 y - S9 x)
         ((y - x) * (CR_of_Q R (1 # 1)
                     - CR_of_Q R (1 # 6) * (y*y + y*x + x*x)
                     + CR_of_Q R (1 # 120) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x)
                     - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x)
                     + CR_of_Q R (1 # 362880) * (y*y*y*y*y*y*y*y + y*y*y*y*y*y*y*x + y*y*y*y*y*y*x*x + y*y*y*y*y*x*x*x + y*y*y*y*x*x*x*x + y*y*y*x*x*x*x*x + y*y*x*x*x*x*x*x + y*x*x*x*x*x*x*x + x*x*x*x*x*x*x*x))).
Proof. unfold S9, S7. unfold CRminus. ring. Qed.

(* S9 递减：8/5 ≤ x ≤ y ≤ 2 ⟹ S9(y) ≤ S9(x) *)
Lemma S9_decr (x y : CRcarrier R) (Hxy : x <= y) (Hx85 : CR_of_Q R (8 # 5) <= x)
    (Hy2 : y <= CR_of_Q R (2 # 1)) :
  S9 y <= S9 x.
Proof.
  assert (Hx0 : 0 <= x) by (apply (CRle_trans _ (CR_of_Q R (8 # 5)) _); [apply (CR_of_Q_le 0 (8 # 5)); unfold Qle; simpl; lia | exact Hx85]).
  assert (Hy0 : 0 <= y) by (apply (CRle_trans _ x _); assumption).
  assert (Hy85 : CR_of_Q R (8 # 5) <= y) by (apply (CRle_trans _ x _); assumption).
  assert (Hx2 : x <= CR_of_Q R (2 # 1)) by (apply (CRle_trans _ y _); assumption).
  apply (CRle_morph R (S9 y) (S9 y) (CReq_refl _)
                     (S9 x) (S9 y + (S9 x - S9 y)) ltac:(unfold CRminus; ring)).
  apply (le_plus_l (S9 y) (S9 x - S9 y)).
  assert (Hdiff : CReq R (S9 x - S9 y) (- (S9 y - S9 x))).
  { unfold CRminus. ring. }
  apply (CRle_morph R 0 0 (CReq_refl _)
                     (S9 x - S9 y) (- (S9 y - S9 x)) ltac:(exact Hdiff)).
  apply (CRle_morph R 0 0 (CReq_refl _)
                     (- (S9 y - S9 x))
                     (- ((y - x) * (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x) + CR_of_Q R (1 # 120) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x) - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x) + CR_of_Q R (1 # 362880) * (y*y*y*y*y*y*y*y + y*y*y*y*y*y*y*x + y*y*y*y*y*y*x*x + y*y*y*y*y*x*x*x + y*y*y*y*x*x*x*x + y*y*y*x*x*x*x*x + y*y*x*x*x*x*x*x + y*x*x*x*x*x*x*x + x*x*x*x*x*x*x*x))))
                     ltac:(apply (CRopp_morph_Proper (S9 y - S9 x)
                                                     ((y - x) * (CR_of_Q R (1 # 1) - CR_of_Q R (1 # 6) * (y*y + y*x + x*x) + CR_of_Q R (1 # 120) * (y*y*y*y + y*y*y*x + y*y*x*x + y*x*x*x + x*x*x*x) - CR_of_Q R (1 # 5040) * (y*y*y*y*y*y + y*y*y*y*y*x + y*y*y*y*x*x + y*y*y*x*x*x + y*y*x*x*x*x + y*x*x*x*x*x + x*x*x*x*x*x) + CR_of_Q R (1 # 362880) * (y*y*y*y*y*y*y*y + y*y*y*y*y*y*y*x + y*y*y*y*y*y*x*x + y*y*y*y*y*x*x*x + y*y*y*y*x*x*x*x + y*y*y*x*x*x*x*x + y*y*x*x*x*x*x*x + y*x*x*x*x*x*x*x + x*x*x*x*x*x*x*x)))
                                                     (S9_diff x y)))).
  apply le0_nonneg.
  apply neg_prod.
  - apply diff_nonneg. exact Hxy.
  - apply Q9_upper; assumption.
Qed.

End P0mono.

(* ==================== 模块 55/67: probe_decidability_premium_cr ==================== *)

Close Scope R_scope.
Close Scope Z_scope.
(* ============================================================
   G-5 可判定性溢价 M4：构造性主探针（probe_decidability_premium_cr.v）
   [3,7,15] 阶梯：精确 Gram 相干行和 ≤ 63/80（frame-certifiable）
   但有理反射判据 21/16 > 4/5（判拒），可判定性溢价 = 21/16 ÷ 63/80 = 5/3
   纯构造性：Stdlib ConstructiveReals，零经典、零 Admitted、零公理
   依赖：M1（CRpi，π∈[3.141,3.142]）+ M2（CRsin + M2E 扩展 [0,2] Taylor 界）
         + M3（CRsqrt 数值界 √21≥4582/1000、√105≥10246/1000）
   数值链（路线 X2，2026-08-26 精确核算）：
     sin(4π/7)  ≤ S9(4π_lo/7) = 0.9750185 ≤ 0.97520（S9 递减 [1.6,2]）
     sin(4π/21) ≥ S7(4π_lo/21) = 0.5632268 ≥ 0.56322（S7 递增 [0,3/2]）
     sin(8π/15) ≤ S9(8π_lo/15) = 0.9945621 ≤ 0.99460（S9 递减 [1.6,2]）
     sin(8π/105)≥ S7(8π_lo/105) = 0.2370365 ≥ 0.23703（S7 递增 [0,3/2]）
     √21 ≥ 4582/1000、√105 ≥ 10246/1000（M3 qbisec 二分）
     行 1 = |<3,7>| + |<7,15>| ≤ 0.377808 + 0.409514 = 0.787322 ≤ 63/80 ✓
   ============================================================ *)
From Stdlib Require Import ConstructiveReals.
From Stdlib Require Import ConstructiveRealsMorphisms.
From Stdlib Require Import ConstructiveAbs.
From Stdlib Require Import ConstructiveSum.
From Stdlib Require Import ConstructiveLimits.
From Stdlib Require Import QArith.
From Stdlib Require Import ZArith.
From Stdlib Require Import Lia.
From Stdlib Require Import Ring.

Local Open Scope ConstructiveReals.

Section M4.

Context {R : ConstructiveReals}.
Add Ring CR_ring : (CRisRing R).

(* ============ Q 层：反射界与溢价 ============ *)

(* 反射界：pair(3,7)=21/32、pair(7,15)=21/32 ⟹ 反射界 21/16 > 4/5
   代数版（非计算反射）：unfold Qlt/Qcompare → Z 层 4·16 < 21·5 → 64 < 105 *)
Lemma m4_reflect_bound_gt : (4 # 5 < 21 # 16)%Q.
Proof. unfold Qlt, Qcompare. simpl. lia. Qed.

(* 溢价：21/16 ÷ 63/80 == 5/3
   代数版（非计算反射）：unfold Qeq/Qcompare/Qdiv → Z 层交叉相乘 5040 = 5040 *)
Lemma m4_premium_ratio : ((21 # 16) / (63 # 80) == 5 # 3)%Q.
Proof. unfold Qeq, Qcompare. simpl. lia. Qed.

(* 21/16 ÷ 63/80 = 5/3 ⟺ 交叉相乘 21·80·3 = 5·16·63（=5040；mathcomp muln 下直接归约） *)
Lemma m4_premium_numer : (21 * 80 * 3 = 5 * 16 * 63)%nat.
Proof. reflexivity. Qed.

(* ============ Q 层：S7/S9 多项式值 ============ *)

Definition S9q (q : Q) : Q :=
  q - (1 # 6) * (q*q*q) + (1 # 120) * (q*q*q*q*q) - (1 # 5040) * (q*q*q*q*q*q*q) + (1 # 362880) * (q*q*q*q*q*q*q*q*q).

Definition S7q (q : Q) : Q :=
  q - (1 # 6) * (q*q*q) + (1 # 120) * (q*q*q*q*q) - (1 # 5040) * (q*q*q*q*q*q*q).

(* 4π_lo/7 = 4·(3141/1000)/7 = 3141/1750：S9(4π_lo/7) ≤ 9752/10000 *)
Lemma m4_S9_lo7_le : (S9q (3141 # 1750) <= (9752 # 10000))%Q.
Proof. apply Qle_bool_imp_le. vm_compute. reflexivity. Qed.

(* 4π_lo/21 = 3141/5250：S7(4π_lo/21) ≥ 56322/100000 *)
Lemma m4_S7_lo21_ge : ((56322 # 100000) <= S7q (3141 # 5250))%Q.
Proof. apply Qle_bool_imp_le. vm_compute. reflexivity. Qed.

(* 8π_lo/15 = 8·(3141/1000)/15 = 3141/1875：S9(8π_lo/15) ≤ 99460/100000 *)
Lemma m4_S9_lo15_le : (S9q (3141 # 1875) <= (99460 # 100000))%Q.
Proof. apply Qle_bool_imp_le. vm_compute. reflexivity. Qed.

(* 8π_lo/105 = 3141/13125：S7(8π_lo/105) ≥ 23703/100000 *)
Lemma m4_S7_lo105_ge : ((23703 # 100000) <= S7q (3141 # 13125))%Q.
Proof. apply Qle_bool_imp_le. vm_compute. reflexivity. Qed.

(* ============ CR_of_Q 同态：S7/S9 在 CR_of_Q 处 == CR_of_Q (Q 层值) ============ *)
(* x_pow 展开辅助（m2 只有 x_pow_1/3） *)
Lemma x_pow_5 (x : CRcarrier R) : CReq R (x_pow x 5) (x*x*x*x*x).
Proof. cbn [x_pow]. ring. Qed.
Lemma x_pow_7 (x : CRcarrier R) : CReq R (x_pow x 7) (x*x*x*x*x*x*x).
Proof. cbn [x_pow]. ring. Qed.
Lemma x_pow_9 (x : CRcarrier R) : CReq R (x_pow x 9) (x*x*x*x*x*x*x*x*x).
Proof. cbn [x_pow]. ring. Qed.

(* 5 个 CR_of_Q 相加合并 *)
Lemma sum5_of_Q (q1 q2 q3 q4 q5 : Q) :
  CReq R (CR_of_Q R q1 + CR_of_Q R q2 + CR_of_Q R q3 + CR_of_Q R q4 + CR_of_Q R q5)
         (CR_of_Q R (q1 + q2 + q3 + q4 + q5)).
Proof.
  apply (CReq_trans _ (CR_of_Q R (q1 + q2 + q3 + q4) + CR_of_Q R q5) _).
  - apply (CRplus_morph_Proper (CR_of_Q R q1 + CR_of_Q R q2 + CR_of_Q R q3 + CR_of_Q R q4)
                               (CR_of_Q R (q1 + q2 + q3 + q4))
                               ltac:(apply (CReq_trans _ (CR_of_Q R (q1 + q2 + q3) + CR_of_Q R q4) _);
                                     [ apply (CRplus_morph_Proper (CR_of_Q R q1 + CR_of_Q R q2 + CR_of_Q R q3)
                                                                  (CR_of_Q R (q1 + q2 + q3))
                                                                  ltac:(apply (CReq_trans _ (CR_of_Q R (q1 + q2) + CR_of_Q R q3) _);
                                                                        [ apply (CRplus_morph_Proper (CR_of_Q R q1 + CR_of_Q R q2) (CR_of_Q R (q1 + q2))
                                                                                 ltac:(apply CReq_sym; apply (CR_of_Q_plus R q1 q2))
                                                                                 (CR_of_Q R q3) (CR_of_Q R q3) (CReq_refl _))
                                                                        | apply CReq_sym; apply (CR_of_Q_plus R (q1 + q2) q3) ])
                                                                  (CR_of_Q R q4) (CR_of_Q R q4) (CReq_refl _))
                                     | apply CReq_sym; apply (CR_of_Q_plus R (q1 + q2 + q3) q4) ])
                               (CR_of_Q R q5) (CR_of_Q R q5) (CReq_refl _)).
  - apply CReq_sym. apply (CR_of_Q_plus R (q1 + q2 + q3 + q4) q5).
Qed.

(* 4 个 CR_of_Q 相加合并 *)
Lemma sum4_of_Q (q1 q2 q3 q4 : Q) :
  CReq R (CR_of_Q R q1 + CR_of_Q R q2 + CR_of_Q R q3 + CR_of_Q R q4)
         (CR_of_Q R (q1 + q2 + q3 + q4)).
Proof.
  apply (CReq_trans _ (CR_of_Q R (q1 + q2 + q3) + CR_of_Q R q4) _).
  - apply (CRplus_morph_Proper (CR_of_Q R q1 + CR_of_Q R q2 + CR_of_Q R q3)
                               (CR_of_Q R (q1 + q2 + q3))
                               ltac:(apply (CReq_trans _ (CR_of_Q R (q1 + q2) + CR_of_Q R q3) _);
                                     [ apply (CRplus_morph_Proper (CR_of_Q R q1 + CR_of_Q R q2) (CR_of_Q R (q1 + q2))
                                              ltac:(apply CReq_sym; apply (CR_of_Q_plus R q1 q2))
                                              (CR_of_Q R q3) (CR_of_Q R q3) (CReq_refl _))
                                     | apply CReq_sym; apply (CR_of_Q_plus R (q1 + q2) q3) ])
                               (CR_of_Q R q4) (CR_of_Q R q4) (CReq_refl _)).
  - apply CReq_sym. apply (CR_of_Q_plus R (q1 + q2 + q3) q4).
Qed.

(* S9 (CR_of_Q q) == CR_of_Q (S9q q) *)(* S9 (CR_of_Q q) == CR_of_Q (S9q q) *)
Lemma S9_of_Q (q : Q) :
  CReq R (S9 (CR_of_Q R q)) (CR_of_Q R (S9q q)).
Proof.
  apply (CReq_trans _ (CR_of_Q R q + CR_of_Q R (-((1 # 6) * (qn q 3))) + CR_of_Q R ((1 # 120) * (qn q 5))
                       + CR_of_Q R (-((1 # 5040) * (qn q 7))) + CR_of_Q R ((1 # 362880) * (qn q 9))) _).
  - unfold S9, S7. unfold CRminus.
    apply (CReq_trans _ (CR_of_Q R q + (- (CR_of_Q R (1 # 6) * (x_pow (CR_of_Q R q) 3)))
                       + CR_of_Q R (1 # 120) * (x_pow (CR_of_Q R q) 5)
                       + (- (CR_of_Q R (1 # 5040) * (x_pow (CR_of_Q R q) 7)))
                       + CR_of_Q R (1 # 362880) * (x_pow (CR_of_Q R q) 9)) _).
    + cbn [x_pow]. ring.
    + setoid_rewrite (x_pow_Q q 3).
      setoid_rewrite (x_pow_Q q 5).
      setoid_rewrite (x_pow_Q q 7).
      setoid_rewrite (x_pow_Q q 9).
      setoid_rewrite <- (CR_of_Q_mult R (1 # 6) (qn q 3)).
      setoid_rewrite <- (CR_of_Q_mult R (1 # 120) (qn q 5)).
      setoid_rewrite <- (CR_of_Q_mult R (1 # 5040) (qn q 7)).
      setoid_rewrite <- (CR_of_Q_mult R (1 # 362880) (qn q 9)).
      setoid_rewrite <- (CR_of_Q_opp ((1 # 6) * (qn q 3))).
      setoid_rewrite <- (CR_of_Q_opp ((1 # 5040) * (qn q 7))).
      ring.
  - apply (CReq_trans _ (CR_of_Q R (q + (-((1 # 6) * (qn q 3))) + ((1 # 120) * (qn q 5)) + (-((1 # 5040) * (qn q 7))) + ((1 # 362880) * (qn q 9)))) _).
    + apply (sum5_of_Q q (-((1 # 6) * (qn q 3))) ((1 # 120) * (qn q 5)) (-((1 # 5040) * (qn q 7))) ((1 # 362880) * (qn q 9))).
    + apply (CR_of_Q_morph R (q + (-((1 # 6) * (qn q 3))) + ((1 # 120) * (qn q 5)) + (-((1 # 5040) * (qn q 7))) + ((1 # 362880) * (qn q 9))) (S9q q)).
      unfold S9q, qn. ring.
Qed.
(* S7 (CR_of_Q q) == CR_of_Q (S7q q) *)
Lemma S7_of_Q (q : Q) :
  CReq R (S7 (CR_of_Q R q)) (CR_of_Q R (S7q q)).
Proof.
  apply (CReq_trans _ (CR_of_Q R q + CR_of_Q R (-((1 # 6) * (qn q 3))) + CR_of_Q R ((1 # 120) * (qn q 5))
                       + CR_of_Q R (-((1 # 5040) * (qn q 7)))) _).
  - unfold S7. unfold CRminus.
    apply (CReq_trans _ (CR_of_Q R q + (- (CR_of_Q R (1 # 6) * (x_pow (CR_of_Q R q) 3)))
                       + CR_of_Q R (1 # 120) * (x_pow (CR_of_Q R q) 5)
                       + (- (CR_of_Q R (1 # 5040) * (x_pow (CR_of_Q R q) 7)))) _).
    + cbn [x_pow]. ring.
    + setoid_rewrite (x_pow_Q q 3).
      setoid_rewrite (x_pow_Q q 5).
      setoid_rewrite (x_pow_Q q 7).
      setoid_rewrite <- (CR_of_Q_mult R (1 # 6) (qn q 3)).
      setoid_rewrite <- (CR_of_Q_mult R (1 # 120) (qn q 5)).
      setoid_rewrite <- (CR_of_Q_mult R (1 # 5040) (qn q 7)).
      setoid_rewrite <- (CR_of_Q_opp ((1 # 6) * (qn q 3))).
      setoid_rewrite <- (CR_of_Q_opp ((1 # 5040) * (qn q 7))).
      ring.
  - apply (CReq_trans _ (CR_of_Q R (q + (-((1 # 6) * (qn q 3))) + ((1 # 120) * (qn q 5)) + (-((1 # 5040) * (qn q 7))))) _).
    + apply (sum4_of_Q q (-((1 # 6) * (qn q 3))) ((1 # 120) * (qn q 5)) (-((1 # 5040) * (qn q 7)))).
    + apply (CR_of_Q_morph R (q + (-((1 # 6) * (qn q 3))) + ((1 # 120) * (qn q 5)) + (-((1 # 5040) * (qn q 7)))) (S7q q)).
      unfold S7q, qn. ring.
Qed.

(* S7/S9 的 Proper 实例（setoid_rewrite 深入用） *)
Instance S7_proper : Proper (CReq R ==> CReq R) S7.
Proof.
  intros x y Hxy.
  unfold S7. unfold CRminus.
  setoid_rewrite Hxy.
  apply CReq_refl.
Qed.
Instance S9_proper : Proper (CReq R ==> CReq R) S9.
Proof.
  intros x y Hxy.
  unfold S9, S7. unfold CRminus.
  setoid_rewrite Hxy.
  apply CReq_refl.
Qed.
(* ============ 辅助：π 界与区间成员 ============ *)

(* c·π ≥ 0（0 ≤ c 且 π ≥ 3.141 > 0） *)
Lemma m4_c_pi_nonneg (c : Q) (Hc : Qle 0 c) :
  CRle R 0 (CR_of_Q R c * CRpi).
Proof.
  apply (CRmult_le_0_compat (CR_of_Q R c) CRpi).
  - apply (CR_of_Q_le 0 c). exact Hc.
  - apply (CRle_trans _ (CR_of_Q R (3141 # 1000)) _).
    + apply (CR_of_Q_le 0 (3141 # 1000)). unfold Qle. simpl. lia.
    + exact CRpi_lower_3141.
Qed.

(* c·π ≤ 2（0 ≤ c 且 c·3.142 ≤ 2 且 π ≤ 3.142） *)
Lemma m4_c_pi_le2 (c : Q) (Hc0 : Qle 0 c) (Hc : Qle (c * (3142 # 1000)) (2 # 1)) :
  CRle R (CR_of_Q R c * CRpi) (CR_of_Q R (2 # 1)).
Proof.
  apply (CRle_trans _ (CR_of_Q R c * CR_of_Q R (3142 # 1000)) _).
  - apply (CRmult_le_compat_l (CR_of_Q R c) CRpi (CR_of_Q R (3142 # 1000))).
    + apply (CR_of_Q_le 0 c). exact Hc0.
    + exact CRpi_upper_3142.
  - apply (CRle_trans _ (CR_of_Q R (c * (3142 # 1000))) _).
    + apply (CRle_morph R (CR_of_Q R c * CR_of_Q R (3142 # 1000)) (CR_of_Q R (c * (3142 # 1000)))
                         ltac:(apply CReq_sym; apply (CR_of_Q_mult R c (3142 # 1000)))
                         (CR_of_Q R (c * (3142 # 1000))) (CR_of_Q R (c * (3142 # 1000))) (CReq_refl _)).
      apply CRle_refl.
    + apply (CR_of_Q_le (c * (3142 # 1000)) (2 # 1)). exact Hc.
Qed.

(* c·π ≤ 3/2（对 c = 4/21、8/105 等小点，S7_incr 用） *)
Lemma m4_c_pi_le32 (c : Q) (Hc0 : Qle 0 c) (Hc : Qle (c * (3142 # 1000)) (3 # 2)) :
  CRle R (CR_of_Q R c * CRpi) (CR_of_Q R (3 # 2)).
Proof.
  apply (CRle_trans _ (CR_of_Q R c * CR_of_Q R (3142 # 1000)) _).
  - apply (CRmult_le_compat_l (CR_of_Q R c) CRpi (CR_of_Q R (3142 # 1000))).
    + apply (CR_of_Q_le 0 c). exact Hc0.
    + exact CRpi_upper_3142.
  - apply (CRle_trans _ (CR_of_Q R (c * (3142 # 1000))) _).
    + apply (CRle_morph R (CR_of_Q R c * CR_of_Q R (3142 # 1000)) (CR_of_Q R (c * (3142 # 1000)))
                         ltac:(apply CReq_sym; apply (CR_of_Q_mult R c (3142 # 1000)))
                         (CR_of_Q R (c * (3142 # 1000))) (CR_of_Q R (c * (3142 # 1000))) (CReq_refl _)).
      apply CRle_refl.
    + apply (CR_of_Q_le (c * (3142 # 1000)) (3 # 2)). exact Hc.
Qed.

(* 8/5 ≤ c·(3141/1000)（Q 层 Hc） *)
Lemma m4_lo_ge85 (c : Q) (Hc : Qle (8 # 5) (c * (3141 # 1000))) :
  CRle R (CR_of_Q R (8 # 5)) (CR_of_Q R c * CR_of_Q R (3141 # 1000)).
Proof.
  apply (CRle_morph R (CR_of_Q R (8 # 5)) (CR_of_Q R (8 # 5)) (CReq_refl _)
                     (CR_of_Q R c * CR_of_Q R (3141 # 1000)) (CR_of_Q R (c * (3141 # 1000)))
                     ltac:(apply CReq_sym; apply (CR_of_Q_mult R c (3141 # 1000)))).
  apply (CR_of_Q_le (8 # 5) (c * (3141 # 1000))). exact Hc.
Qed.

(* lo ≤ c·π（π ≥ 3141/1000） *)
Lemma m4_lo_le_cpi (c : Q) (Hc0 : Qle 0 c) :
  CRle R (CR_of_Q R c * CR_of_Q R (3141 # 1000)) (CR_of_Q R c * CRpi).
Proof.
  apply (CRmult_le_compat_l (CR_of_Q R c) (CR_of_Q R (3141 # 1000)) CRpi).
  - apply (CR_of_Q_le 0 c). exact Hc0.
  - exact CRpi_lower_3141.
Qed.

(* c·(3141/1000) == lo（Q 层等价） *)
Lemma m4_c3141_of_Q (c lo : Q) (Hlo : Qeq (c * (3141 # 1000)) lo) :
  CReq R (CR_of_Q R c * CR_of_Q R (3141 # 1000)) (CR_of_Q R lo).
Proof.
  apply (CReq_trans _ (CR_of_Q R (c * (3141 # 1000))) _).
  - apply CReq_sym. apply (CR_of_Q_mult R c (3141 # 1000)).
  - apply (CR_of_Q_morph R (c * (3141 # 1000)) lo). exact Hlo.
Qed.

(* ============ 4 个 sin 界 ============ *)

(* sin(4π/7) ≤ S9(4π/7) ≤ S9(4π_lo/7) ≤ 9752/10000 *)
Lemma m4_sin_4pi7_le :
  CRle R (m2e_CRsin (CR_of_Q R (4 # 7) * CRpi)
                    (m4_c_pi_nonneg (4 # 7) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity))
                    (m4_c_pi_le2 (4 # 7) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)
                                 ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)))
         (CR_of_Q R (9752 # 10000)).
Proof.
  apply (CRle_trans _ (S9 (CR_of_Q R (4 # 7) * CRpi)) _).
  - apply (CRle_trans _ (alt_partial (sin_a (CR_of_Q R (4 # 7) * CRpi)) 4) _).
    + apply (m2e_sin_even_ge (CR_of_Q R (4 # 7) * CRpi)
                             (m4_c_pi_nonneg (4 # 7) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity))
                             (m4_c_pi_le2 (4 # 7) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)
                                          ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)) 2).
    + apply (CRle_morph R (alt_partial (sin_a (CR_of_Q R (4 # 7) * CRpi)) 4)
                         (S9 (CR_of_Q R (4 # 7) * CRpi)) (m2e_S9_poly (CR_of_Q R (4 # 7) * CRpi))
                         (S9 (CR_of_Q R (4 # 7) * CRpi)) (S9 (CR_of_Q R (4 # 7) * CRpi)) (CReq_refl _)).
      apply CRle_refl.
  - apply (CRle_trans _ (S9 (CR_of_Q R (4 # 7) * CR_of_Q R (3141 # 1000))) _).
    + apply (S9_decr (CR_of_Q R (4 # 7) * CR_of_Q R (3141 # 1000)) (CR_of_Q R (4 # 7) * CRpi)).
      * apply (m4_lo_le_cpi (4 # 7) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)).
      * apply (m4_lo_ge85 (4 # 7) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)).
      * apply (m4_c_pi_le2 (4 # 7) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)).
    + apply (CRle_morph R (S9 (CR_of_Q R (4 # 7) * CR_of_Q R (3141 # 1000)))
                         (S9 (CR_of_Q R (3141 # 1750)))
                         ltac:(apply (S9_proper (CR_of_Q R (4 # 7) * CR_of_Q R (3141 # 1000)) (CR_of_Q R (3141 # 1750)) (m4_c3141_of_Q (4 # 7) (3141 # 1750) ltac:(apply Qeq_bool_iff; vm_compute; reflexivity))))
                         (CR_of_Q R (9752 # 10000)) (CR_of_Q R (9752 # 10000)) (CReq_refl _)).
      apply (CRle_morph R (S9 (CR_of_Q R (3141 # 1750)))
                         (CR_of_Q R (S9q (3141 # 1750))) (S9_of_Q (3141 # 1750))
                         (CR_of_Q R (9752 # 10000)) (CR_of_Q R (9752 # 10000)) (CReq_refl _)).
      apply (CR_of_Q_le (S9q (3141 # 1750)) (9752 # 10000)).
      exact m4_S9_lo7_le.
Qed.

(* lo = c·(3141/1000) ≥ 0 *)
Lemma m4_lo_nonneg (c : Q) (Hc : Qle 0 c) :
  CRle R 0 (CR_of_Q R c * CR_of_Q R (3141 # 1000)).
Proof.
  apply (CRmult_le_0_compat (CR_of_Q R c) (CR_of_Q R (3141 # 1000))).
  - apply (CR_of_Q_le 0 c). exact Hc.
  - apply (CR_of_Q_le 0 (3141 # 1000)). unfold Qle. simpl. lia.
Qed.

(* sin(4π/21) ≥ S7(4π_lo/21) ≥ 56322/100000 *)
Lemma m4_sin_4pi21_ge :
  CRle R (CR_of_Q R (56322 # 100000))
         (m2e_CRsin (CR_of_Q R (4 # 21) * CRpi)
                    (m4_c_pi_nonneg (4 # 21) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity))
                    (m4_c_pi_le2 (4 # 21) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)
                                 ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity))).
Proof.
  apply (CRle_trans _ (S7 (CR_of_Q R (4 # 21) * CR_of_Q R (3141 # 1000))) _).
  - apply (CRle_morph R (CR_of_Q R (56322 # 100000)) (CR_of_Q R (56322 # 100000)) (CReq_refl _)
                       (S7 (CR_of_Q R (4 # 21) * CR_of_Q R (3141 # 1000)))
                       (CR_of_Q R (S7q (3141 # 5250)))
                       ltac:(apply (CReq_trans _ (S7 (CR_of_Q R (3141 # 5250))) _);
                             [ apply (S7_proper (CR_of_Q R (4 # 21) * CR_of_Q R (3141 # 1000)) (CR_of_Q R (3141 # 5250))
