    apply (CR_of_Q_le (56322 # 100000) (S7q (3141 # 5250))). exact m4_S7_lo21_ge.
  - apply (CRle_trans _ (S7 (CR_of_Q R (4 # 21) * CRpi)) _).
    + apply (S7_incr (CR_of_Q R (4 # 21) * CR_of_Q R (3141 # 1000)) (CR_of_Q R (4 # 21) * CRpi)).
      * apply (m4_lo_le_cpi (4 # 21) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)).
      * apply (m4_lo_nonneg (4 # 21) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)).
      * apply (m4_c_pi_le32 (4 # 21) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)
                            ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)).
    + apply (CRle_trans _ (alt_partial (sin_a (CR_of_Q R (4 # 21) * CRpi)) 3) _).
      * apply (CRle_morph R (S7 (CR_of_Q R (4 # 21) * CRpi))
