(* sin(8π/15) ≤ S9(8π_lo/15) ≤ 99460/100000 *)
Lemma m4_sin_8pi15_le :
  CRle R (m2e_CRsin (CR_of_Q R (8 # 15) * CRpi)
                    (m4_c_pi_nonneg (8 # 15) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity))
                    (m4_c_pi_le2 (8 # 15) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)
                                 ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)))
         (CR_of_Q R (99460 # 100000)).
Proof.
  apply (CRle_trans _ (S9 (CR_of_Q R (8 # 15) * CRpi)) _).
  - apply (CRle_trans _ (alt_partial (sin_a (CR_of_Q R (8 # 15) * CRpi)) 4) _).
    + apply (m2e_sin_even_ge (CR_of_Q R (8 # 15) * CRpi)
                             (m4_c_pi_nonneg (8 # 15) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity))
                             (m4_c_pi_le2 (8 # 15) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)
                                          ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)) 2).
    + apply (CRle_morph R (alt_partial (sin_a (CR_of_Q R (8 # 15) * CRpi)) 4)
                         (S9 (CR_of_Q R (8 # 15) * CRpi)) (m2e_S9_poly (CR_of_Q R (8 # 15) * CRpi))
                         (S9 (CR_of_Q R (8 # 15) * CRpi)) (S9 (CR_of_Q R (8 # 15) * CRpi)) (CReq_refl _)).
      apply CRle_refl.
  - apply (CRle_trans _ (S9 (CR_of_Q R (8 # 15) * CR_of_Q R (3141 # 1000))) _).
    + apply (S9_decr (CR_of_Q R (8 # 15) * CR_of_Q R (3141 # 1000)) (CR_of_Q R (8 # 15) * CRpi)).
      * apply (m4_lo_le_cpi (8 # 15) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)).
      * apply (m4_lo_ge85 (8 # 15) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)).
      * apply (m4_c_pi_le2 (8 # 15) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)
                            ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)).
    + apply (CRle_morph R (S9 (CR_of_Q R (8 # 15) * CR_of_Q R (3141 # 1000)))
                         (S9 (CR_of_Q R (3141 # 1875)))
                         ltac:(apply (S9_proper (CR_of_Q R (8 # 15) * CR_of_Q R (3141 # 1000)) (CR_of_Q R (3141 # 1875))
                                               (m4_c3141_of_Q (8 # 15) (3141 # 1875) ltac:(apply Qeq_bool_iff; vm_compute; reflexivity))))
                         (CR_of_Q R (99460 # 100000)) (CR_of_Q R (99460 # 100000)) (CReq_refl _)).
      apply (CRle_morph R (S9 (CR_of_Q R (3141 # 1875)))
                         (CR_of_Q R (S9q (3141 # 1875))) (S9_of_Q (3141 # 1875))
                         (CR_of_Q R (99460 # 100000)) (CR_of_Q R (99460 # 100000)) (CReq_refl _)).
      apply (CR_of_Q_le (S9q (3141 # 1875)) (99460 # 100000)).
      exact m4_S9_lo15_le.
Qed.

