(* ============ 行和 ≤ 63/80 ============ *)

(* Q 层核算：0.9752/(0.56322·4.582) + 0.99460/(0.23703·10.246) ≤ 63/80
   非平凡代数版（无计算反射）：unfold Qle（Rocq 9 直接是 Z 交叉相乘）→ simpl 通分 → nia
   归约终点：3948094614048000000000000000 <= 3948492983567891976000000000（N·80 ≤ 63·D）*)
Lemma m4_row_q_le : Qle (((9752 # 10000) / ((56322 # 100000) * (4582 # 1000)))
                         + ((99460 # 100000) / ((23703 # 100000) * (10246 # 1000))))
                        (63 # 80).
Proof. unfold Qle. simpl. nia. Qed.

(* 0 < x → CRapart x 0 *)
Lemma m4_pos_apart (x : CRcarrier R) (Hx : 0 < x) : CRapart R x 0.
Proof.
  unfold CRapart. right. exact Hx.
Qed.

(* 0 < x → 0 ≤ x（CRle 是 ¬(x<0)，反证 + CRltLinear 反对称）*)
Lemma m4_CRlt_le_incl (x y : CRcarrier R) (H : x < y) : x <= y.
Proof.
  unfold CRle. intro Habs.
  exact (fst (fst (CRltLinear R)) x y H Habs).
Qed.

(* CRinv 单调（反变）：0 < y ≤ x ⟹ CRinv x ≤ CRinv y
   证明：1 ≤ (1/y)·x（用 1 == (1/y)·y ≤ (1/y)·x）
         再两边乘 1/x ≥ 0：(1/x)·1 ≤ (1/x)·(1/y·x) == 1/y *)
Lemma m4_CRinv_le_contravar (x y : CRcarrier R) (Hx0 : 0 < x) (Hy0 : 0 < y) (Hyx : y <= x) :
  CRinv R x (m4_pos_apart x Hx0) <= CRinv R y (m4_pos_apart y Hy0).
Proof.
  assert (Hiny : 0 <= CRinv R y (m4_pos_apart y Hy0)).
  { apply (m4_CRlt_le_incl 0 (CRinv R y (m4_pos_apart y Hy0))).
    apply (CRinv_0_lt_compat R y (m4_pos_apart y Hy0) Hy0). }
  assert (Hinx : 0 <= CRinv R x (m4_pos_apart x Hx0)).
  { apply (m4_CRlt_le_incl 0 (CRinv R x (m4_pos_apart x Hx0))).
    apply (CRinv_0_lt_compat R x (m4_pos_apart x Hx0) Hx0). }
  (* 1 ≤ (1/y)·x *)
  assert (H1 : CR_of_Q R 1 <= CRinv R y (m4_pos_apart y Hy0) * x).
  { apply (CRle_trans _ (CRinv R y (m4_pos_apart y Hy0) * y) _).
    - apply (CRle_morph R (CR_of_Q R 1) (CR_of_Q R 1) (CReq_refl _)
                         (CRinv R y (m4_pos_apart y Hy0) * y) (CR_of_Q R 1)
                         ltac:(apply (CRinv_l R y (m4_pos_apart y Hy0)))).
      apply CRle_refl.
    - apply (CRmult_le_compat_l (CRinv R y (m4_pos_apart y Hy0)) y x). exact Hiny. exact Hyx. }
  (* 1 ≤ 1/y·x → (1/x)·1 ≤ (1/x)·(1/y·x) → 1/x ≤ 1/y *)
  apply (CRle_morph R (CRinv R x (m4_pos_apart x Hx0))
                     (CRinv R x (m4_pos_apart x Hx0) * 1) ltac:(ring)
                     (CRinv R y (m4_pos_apart y Hy0))
                     (CRinv R x (m4_pos_apart x Hx0) * (CRinv R y (m4_pos_apart y Hy0) * x))
                     ltac:(apply CReq_sym;
                           apply (CReq_trans _ ((CRinv R x (m4_pos_apart x Hx0) * x) * CRinv R y (m4_pos_apart y Hy0)) _);
                           [ ring
                           | apply (CReq_trans _ (CR_of_Q R 1 * CRinv R y (m4_pos_apart y Hy0)) _);
                             [ apply (CRmult_morph_Proper (CRinv R x (m4_pos_apart x Hx0) * x) (CR_of_Q R 1)
                                      (CRinv_l R x (m4_pos_apart x Hx0))
                                      (CRinv R y (m4_pos_apart y Hy0)) (CRinv R y (m4_pos_apart y Hy0)) (CReq_refl _))
                             | ring ] ])).
  apply (CRmult_le_compat_l (CRinv R x (m4_pos_apart x Hx0))
                            1 (CRinv R y (m4_pos_apart y Hy0) * x)).
  - exact Hinx.
  - exact H1.
Qed.

(* ============ 行和 ≤ 63/80：CRinv 反变 + Q 层核算 ============ *)

(* Q 层正性（代数判定，非计算反射）：
   - 分数正性 0 < (n # d)：Rocq 9.0 的 Qlt 直接定义为 Z 层比较
     (Qnum x * QDen y < Qnum y * QDen x)%Z，unfold Qlt 后化简到 (0 < n)%Z，
     由 lia 证明整数算术（lia 是证明引擎，非计算反射）；
   - 乘积正性：QArith 库引理 Qmult_lt_0_compat 组合两条分数正性；
   - 全程不用 vm_compute / Qle_bool_imp_le / Qeq_bool_iff。 *)
Lemma m4_Qlt_0_make : forall (n : Z) (d : positive), (0 < n)%Z -> (0 < (n # d))%Q.
Proof.
  intros n d Hn.
  unfold Qlt. cbn.
  rewrite Z.mul_1_r.
  exact Hn.
Qed.

Lemma m4_b37_pos : (0 < (56322 # 100000) * (4582 # 1000))%Q.
Proof.
  apply Qmult_lt_0_compat.
  - apply m4_Qlt_0_make. lia.
  - apply m4_Qlt_0_make. lia.
Qed.
Lemma m4_b715_pos : (0 < (23703 # 100000) * (10246 # 1000))%Q.
Proof.
  apply Qmult_lt_0_compat.
  - apply m4_Qlt_0_make. lia.
  - apply m4_Qlt_0_make. lia.
Qed.
