Proof. apply m4_Qlt_0_make. lia. Qed.
Lemma m4_q56322_pos : (0 < (56322 # 100000))%Q.
Proof. apply m4_Qlt_0_make. lia. Qed.
Lemma m4_q4582_pos : (0 < (4582 # 1000))%Q.
Proof. apply m4_Qlt_0_make. lia. Qed.
Lemma m4_q23703_pos : (0 < (23703 # 100000))%Q.
Proof. apply m4_Qlt_0_make. lia. Qed.
Lemma m4_q10246_pos : (0 < (10246 # 1000))%Q.
Proof. apply m4_Qlt_0_make. lia. Qed.

(* 0 ≤ CR_of_Q 正数（CRlt_le_incl + CR_of_Q_pos）*)
Lemma m4_q9752_nonneg : CRle R 0 (CR_of_Q R (9752 # 10000)).
Proof. apply (m4_CRlt_le_incl 0 (CR_of_Q R (9752 # 10000))). apply (CR_of_Q_pos (9752 # 10000) m4_q9752_pos). Qed.
