Proof. apply (m4_CRlt_le_incl 0 (CR_of_Q R (10246 # 1000))). apply (CR_of_Q_pos (10246 # 1000) m4_q10246_pos). Qed.

(* sin 项缩写（与 m4_sin_4pi7_le 等陈述逐字一致）*)
Definition m4_s47 : CRcarrier R :=
  m2e_CRsin (CR_of_Q R (4 # 7) * CRpi)
            (m4_c_pi_nonneg (4 # 7) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity))
            (m4_c_pi_le2 (4 # 7) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)
                         ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)).
