            (m4_c_pi_nonneg (8 # 105) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity))
            (m4_c_pi_le2 (8 # 105) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)
                         ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)).
Definition m4_d37 : CRcarrier R := m4_s21 * CRsqrt (21 # 1) Q21_nonneg.
Definition m4_d715 : CRcarrier R := m4_s8105 * CRsqrt (105 # 1) Q105_nonneg.

(* 分子/分母正性：sin ≥ 正 Q 下界、sqrt ≥ 正下界、分母 = 乘积 *)
Lemma m4_sin21_pos : 0 < m4_s21.
Proof.
  unfold m4_s21.
  apply (CRlt_le_trans 0 (CR_of_Q R (56322 # 100000))
         (m2e_CRsin (CR_of_Q R (4 # 21) * CRpi)
                    (m4_c_pi_nonneg (4 # 21) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity))
                    (m4_c_pi_le2 (4 # 21) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)
                                 ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)))).
  - apply (CR_of_Q_pos (56322 # 100000) m4_q56322_pos).
  - exact m4_sin_4pi21_ge.
Qed.
Lemma m4_sin105_pos : 0 < m4_s8105.
Proof.
  unfold m4_s8105.
  apply (CRlt_le_trans 0 (CR_of_Q R (23703 # 100000))
         (m2e_CRsin (CR_of_Q R (8 # 105) * CRpi)
                    (m4_c_pi_nonneg (8 # 105) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity))
                    (m4_c_pi_le2 (8 # 105) ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)
                                 ltac:(apply Qle_bool_imp_le; vm_compute; reflexivity)))).
  - apply (CR_of_Q_pos (23703 # 100000) m4_q23703_pos).
  - exact m4_sin_8pi105_ge.
Qed.
