Proof.
  apply (CRlt_le_trans 0 (CR_of_Q R (4582 # 1000)) (CRsqrt (21 # 1) Q21_nonneg)).
  - apply (CR_of_Q_pos (4582 # 1000) m4_q4582_pos).
  - exact sqrt21_lower.
Qed.
Lemma m4_sqrt105_pos : CR_of_Q R 0 < CRsqrt (105 # 1) Q105_nonneg.
