  - apply (CR_of_Q_pos (10246 # 1000) m4_q10246_pos).
  - exact sqrt105_lower.
Qed.
Lemma m4_sin21_nonneg : CRle R 0 m4_s21.
Proof. apply (m4_CRlt_le_incl 0 m4_s21). exact m4_sin21_pos. Qed.
Lemma m4_sin105_nonneg : CRle R 0 m4_s8105.
Proof. apply (m4_CRlt_le_incl 0 m4_s8105). exact m4_sin105_pos. Qed.
Lemma m4_sqrt21_nonneg : CRle R 0 (CRsqrt (21 # 1) Q21_nonneg).
Proof. apply (m4_CRlt_le_incl 0 (CRsqrt (21 # 1) Q21_nonneg)). exact m4_sqrt21_pos. Qed.
Lemma m4_sqrt105_nonneg : CRle R 0 (CRsqrt (105 # 1) Q105_nonneg).
