Lemma m4_d715_pos : 0 < m4_d715.
Proof. unfold m4_d715. apply (CRmult_lt_0_compat R m4_s8105 (CRsqrt (105 # 1) Q105_nonneg)). exact m4_sin105_pos. exact m4_sqrt105_pos. Qed.

(* 分母下界：CR_of_Q ((56322/100000)·(4582/1000)) ≤ m4_d37 *)
Lemma m4_d37_ge : CRle R (CR_of_Q R ((56322 # 100000) * (4582 # 1000))) m4_d37.
Proof.
  unfold m4_d37.
  apply (CRle_trans _ (CR_of_Q R (56322 # 100000) * CR_of_Q R (4582 # 1000)) _).
  - apply (CRle_morph R (CR_of_Q R ((56322 # 100000) * (4582 # 1000)))
                       (CR_of_Q R ((56322 # 100000) * (4582 # 1000))) (CReq_refl _)
                       (CR_of_Q R (56322 # 100000) * CR_of_Q R (4582 # 1000))
                       (CR_of_Q R ((56322 # 100000) * (4582 # 1000)))
                       ltac:(apply CReq_sym; apply (CR_of_Q_mult R (56322 # 100000) (4582 # 1000)))).
    apply CRle_refl.
  - apply (CRle_trans _ (m4_s21 * CR_of_Q R (4582 # 1000)) _).
    + apply (CRmult_le_compat_r (CR_of_Q R (4582 # 1000)) (CR_of_Q R (56322 # 100000)) m4_s21).
      * exact m4_q4582_nonneg.
      * unfold m4_s21. exact m4_sin_4pi21_ge.
    + apply (CRmult_le_compat_l m4_s21 (CR_of_Q R (4582 # 1000)) (CRsqrt (21 # 1) Q21_nonneg)).
      * exact m4_sin21_nonneg.
      * exact sqrt21_lower.
Qed.
(* 分母下界：CR_of_Q ((23703/100000)·(10246/1000)) ≤ m4_d715 *)
Lemma m4_d715_ge : CRle R (CR_of_Q R ((23703 # 100000) * (10246 # 1000))) m4_d715.
Proof.
  unfold m4_d715.
  apply (CRle_trans _ (CR_of_Q R (23703 # 100000) * CR_of_Q R (10246 # 1000)) _).
  - apply (CRle_morph R (CR_of_Q R ((23703 # 100000) * (10246 # 1000)))
                       (CR_of_Q R ((23703 # 100000) * (10246 # 1000))) (CReq_refl _)
                       (CR_of_Q R (23703 # 100000) * CR_of_Q R (10246 # 1000))
                       (CR_of_Q R ((23703 # 100000) * (10246 # 1000)))
                       ltac:(apply CReq_sym; apply (CR_of_Q_mult R (23703 # 100000) (10246 # 1000)))).
    apply CRle_refl.
  - apply (CRle_trans _ (m4_s8105 * CR_of_Q R (10246 # 1000)) _).
    + apply (CRmult_le_compat_r (CR_of_Q R (10246 # 1000)) (CR_of_Q R (23703 # 100000)) m4_s8105).
      * exact m4_q10246_nonneg.
      * unfold m4_s8105. exact m4_sin_8pi105_ge.
    + apply (CRmult_le_compat_l m4_s8105 (CR_of_Q R (10246 # 1000)) (CRsqrt (105 # 1) Q105_nonneg)).
      * exact m4_sin105_nonneg.
      * exact sqrt105_lower.
Qed.

(* CR_of_Q b37 > 0（CRinv 反变的前提）*)
Lemma m4_b37_crpos : 0 < CR_of_Q R ((56322 # 100000) * (4582 # 1000)).
Proof. apply (CR_of_Q_pos ((56322 # 100000) * (4582 # 1000)) m4_b37_pos). Qed.
