Proof. apply (CR_of_Q_pos ((23703 # 100000) * (10246 # 1000)) m4_b715_pos). Qed.

(* CRinv 反变：CRinv m4_d37 ≤ CRinv (CR_of_Q b37) *)
Lemma m4_inv_d37_le :
  CRle R (CRinv R m4_d37 (m4_pos_apart m4_d37 m4_d37_pos))
         (CRinv R (CR_of_Q R ((56322 # 100000) * (4582 # 1000)))
                  (m4_pos_apart (CR_of_Q R ((56322 # 100000) * (4582 # 1000))) m4_b37_crpos)).
Proof.
  apply (m4_CRinv_le_contravar m4_d37 (CR_of_Q R ((56322 # 100000) * (4582 # 1000)))
                               m4_d37_pos m4_b37_crpos).
