Qed.

(* Q 层核算定义 + Qdiv 展开判定 *)
Definition m4_q37 : Q := (9752 # 10000) / ((56322 # 100000) * (4582 # 1000)).
Definition m4_q715 : Q := (99460 # 100000) / ((23703 # 100000) * (10246 # 1000)).
Lemma m4_q37_div_eq : (m4_q37 == (9752 # 10000) * Qinv ((56322 # 100000) * (4582 # 1000)))%Q.
Proof. unfold m4_q37, Qdiv. reflexivity. Qed.
Lemma m4_q715_div_eq : (m4_q715 == (99460 # 100000) * Qinv ((23703 # 100000) * (10246 # 1000)))%Q.
Proof. unfold m4_q715, Qdiv. reflexivity. Qed.

(* (9752/10000)·CRinv(CR_of_Q b37)(inr apart) == CR_of_Q q37 *)
Lemma m4_t1_eq_inr :
  CReq R (CR_of_Q R (9752 # 10000) * CRinv R (CR_of_Q R ((56322 # 100000) * (4582 # 1000)))
                              (inr (CR_of_Q_pos ((56322 # 100000) * (4582 # 1000)) m4_b37_pos)))
         (CR_of_Q R m4_q37).
Proof.
  apply (CReq_trans _ (CR_of_Q R (9752 # 10000) * CR_of_Q R (Qinv ((56322 # 100000) * (4582 # 1000)))) _).
  - apply (CRmult_morph_Proper (CR_of_Q R (9752 # 10000)) (CR_of_Q R (9752 # 10000)) (CReq_refl _)
           (CRinv R (CR_of_Q R ((56322 # 100000) * (4582 # 1000)))
                   (inr (CR_of_Q_pos ((56322 # 100000) * (4582 # 1000)) m4_b37_pos)))
           (CR_of_Q R (Qinv ((56322 # 100000) * (4582 # 1000))))
           ltac:(apply CReq_sym; apply (CR_of_Q_inv ((56322 # 100000) * (4582 # 1000)) m4_b37_pos))).
  - apply (CReq_trans _ (CR_of_Q R (((9752 # 10000) * Qinv ((56322 # 100000) * (4582 # 1000)))%Q)) _).
    + apply CReq_sym. apply (CR_of_Q_mult R (9752 # 10000) (Qinv ((56322 # 100000) * (4582 # 1000)))).
    + apply CReq_sym. apply (CR_of_Q_morph R m4_q37 (((9752 # 10000) * Qinv ((56322 # 100000) * (4582 # 1000)))%Q)).
      apply Qeq_sym. exact m4_q37_div_eq.
Qed.
(* 统一 apart 为 m4_pos_apart 版本（CRinv_morph 换 apart 证明）*)
Lemma m4_t1_eq :
  CReq R (CR_of_Q R (9752 # 10000) * CRinv R (CR_of_Q R ((56322 # 100000) * (4582 # 1000)))
                              (m4_pos_apart (CR_of_Q R ((56322 # 100000) * (4582 # 1000))) m4_b37_crpos))
