                              (inr (CR_of_Q_pos ((56322 # 100000) * (4582 # 1000)) m4_b37_pos))) _).
  - apply (CRmult_morph_Proper (CR_of_Q R (9752 # 10000)) (CR_of_Q R (9752 # 10000)) (CReq_refl _)
           (CRinv R (CR_of_Q R ((56322 # 100000) * (4582 # 1000)))
                   (m4_pos_apart (CR_of_Q R ((56322 # 100000) * (4582 # 1000))) m4_b37_crpos))
           (CRinv R (CR_of_Q R ((56322 # 100000) * (4582 # 1000)))
                   (inr (CR_of_Q_pos ((56322 # 100000) * (4582 # 1000)) m4_b37_pos)))
           ltac:(apply (CRinv_morph (CR_of_Q R ((56322 # 100000) * (4582 # 1000)))
                                    (CR_of_Q R ((56322 # 100000) * (4582 # 1000)))
                                    (m4_pos_apart (CR_of_Q R ((56322 # 100000) * (4582 # 1000))) m4_b37_crpos)
                                    (inr (CR_of_Q_pos ((56322 # 100000) * (4582 # 1000)) m4_b37_pos))
                                    (CReq_refl _)))).
